def _is_path_probability_follow_strategy(strategy: Any, *, allow_blank: bool = False) -> bool:
    strategy_norm = str(strategy or "").strip().lower()
    if not strategy_norm:
        return bool(allow_blank)
    return strategy_norm in PATH_PROBABILITY_FOLLOW_LEGACY_STRATEGIES


def _path_probability_follow_env_key(env_key: str) -> str:
    key = str(env_key or "")
    if key.startswith("PM_LCB_GLOBAL_"):
        return "PM_PATH_PROBABILITY_FOLLOW_" + key[len("PM_LCB_GLOBAL_") :]
    return key


def _env_value_with_path_follow_alias(env_key: str) -> Optional[str]:
    key = str(env_key or "")
    primary = _path_probability_follow_env_key(key)
    if primary != key:
        raw = os.environ.get(primary)
        if raw is not None:
            return raw
    return os.environ.get(key)


def _path_follow_env_aliases(env_key: str) -> Tuple[str, ...]:
    key = str(env_key or "")
    primary = _path_probability_follow_env_key(key)
    return (primary, key) if primary != key else (key,)

