def _runtime_private_key_literal(value: str) -> bool:
    return bool(re.fullmatch(r"0x[0-9A-Fa-f]{64}", str(value or "").strip()))


def _read_runtime_env_file_vars(path: Path, keys: Iterable[str]) -> Dict[str, str]:
    wanted = {str(key or "").strip() for key in (keys or []) if str(key or "").strip()}
    if not wanted or not path.exists():
        return {}
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return {}
    out: Dict[str, str] = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("export "):
            stripped = stripped[7:].lstrip()
        if "=" not in stripped:
            if "PRIVATE_KEY" in wanted and "PRIVATE_KEY" not in out and _runtime_private_key_literal(stripped):
                out["PRIVATE_KEY"] = stripped
            continue
        key, value = stripped.split("=", 1)
        key = key.strip()
        if key not in wanted:
            continue
        value = value.strip()
        if value and value[0] not in {"'", '"'} and " #" in value:
            value = value.split(" #", 1)[0].rstrip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
            value = value[1:-1]
        out[key] = value
    return out


def _shared_poly_env_path() -> Path:
    raw = str(os.environ.get("PM_SHARED_POLY_ENV_PATH") or "").strip()
    if raw:
        return Path(raw).expanduser()
    home = Path(os.environ.get("HOME") or str(Path.home())).expanduser()
    return home / "poly" / ".env"


def _runtime_launchctl_getenv(name: str) -> str:
    key = str(name or "").strip()
    if not key:
        return ""
    launchctl_bin = "/bin/launchctl" if Path("/bin/launchctl").exists() else "launchctl"
    try:
        res = subprocess.run(
            [launchctl_bin, "getenv", key],
            capture_output=True,
            text=True,
            timeout=0.3,
            check=False,
        )
    except Exception:
        return ""
    if res.returncode != 0:
        return ""
    return str(res.stdout or "").strip()


def _hydrate_auto_trade_runtime_env(force: bool = False) -> None:
    global _RUNTIME_ENV_HYDRATED
    with _RUNTIME_ENV_LOCK:
        if _RUNTIME_ENV_HYDRATED and not force:
            return
        control_values = _read_runtime_env_file_vars(_RUNTIME_ENV_PATH, _RUNTIME_ENV_CONTROL_KEYS)
        for key, value in control_values.items():
            os.environ[key] = str(value)

        repo_shared_values = _read_runtime_env_file_vars(_RUNTIME_ENV_PATH, _RUNTIME_ENV_SHARED_KEYS)
        for key, value in repo_shared_values.items():
            if str(value or "").strip() == "":
                continue
            if not os.environ.get(key):
                os.environ[key] = str(value)

        shared_env_path = _shared_poly_env_path()
        shared_values = _read_runtime_env_file_vars(shared_env_path, _RUNTIME_ENV_SHARED_KEYS)
        for key, value in shared_values.items():
            if str(value or "").strip() == "":
                continue
            if key in _RUNTIME_ENV_CREDENTIAL_KEYS or not os.environ.get(key):
                os.environ[key] = str(value)

        allow_launchctl_credentials = str(
            os.environ.get("PM_ALLOW_LAUNCHCTL_POLY_CREDENTIALS") or ""
        ).strip().lower() in {"1", "true", "yes", "on"}
        for key in (*_RUNTIME_ENV_CONTROL_KEYS, *_RUNTIME_ENV_SHARED_KEYS):
            if key in _RUNTIME_ENV_CREDENTIAL_KEYS and not allow_launchctl_credentials:
                continue
            if os.environ.get(key):
                continue
            value = _runtime_launchctl_getenv(key)
            if value:
                os.environ[key] = value

        if not os.environ.get("PRIVATE_KEY") and os.environ.get("POLY_PRIVATE_KEY"):
            os.environ["PRIVATE_KEY"] = str(os.environ.get("POLY_PRIVATE_KEY") or "")
        if not os.environ.get("PM_FUNDER_ADDRESS") and os.environ.get("POLY_FUNDER_ADDRESS"):
            os.environ["PM_FUNDER_ADDRESS"] = str(os.environ.get("POLY_FUNDER_ADDRESS") or "")
        _RUNTIME_ENV_HYDRATED = True


def _ensure_nofile_limit() -> None:
    """Best-effort increase process NOFILE soft limit to avoid Errno 24 under long runs."""
    try:
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    except Exception:
        return
    target_raw = str(os.environ.get("PM_NOFILE_SOFT", "8192") or "").strip()
    try:
        target = int(float(target_raw))
    except Exception:
        target = 8192
    if target <= 0:
        return
    upper = hard if isinstance(hard, int) and hard > 0 else soft
    if not isinstance(upper, int) or upper <= 0:
        return
    desired = max(int(soft or 0), min(target, upper))
    if desired <= int(soft or 0):
        return
    try:
        resource.setrlimit(resource.RLIMIT_NOFILE, (desired, hard))
        print(f"[fd_limit] RLIMIT_NOFILE soft {soft} -> {desired} (hard={hard})")
    except Exception:
        if resolution_source and "wunderground.com" in resolution_source and market_var in {
            "temperature_2m_max",
            "temperature_2m_min",
        }:
            return None


_ensure_nofile_limit()

