# -------------------------
# Helpers: Polymarket
# -------------------------

def slug_from_event_url(event_url: str) -> str:
    m = re.search(r"/event/([^/?#]+)", event_url)
    if not m:
        raise ValueError("Cannot parse slug from event_url")
    return m.group(1)


def _parse_host_list(value: Optional[str]) -> List[str]:
    if not value:
        return []
    parts = re.split(r"[,\s]+", value)
    return [p.strip().lower() for p in parts if p.strip()]


def _host_matches(host: str, pattern: str) -> bool:
    if not host or not pattern:
        return False
    pattern = pattern.strip().lower()
    if pattern.startswith("."):
        pattern = pattern[1:]
    return host == pattern or host.endswith(f".{pattern}")


def _force_direct_enabled() -> bool:
    value = os.environ.get("PM_SCAN_FORCE_DIRECT", "")
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _proxy_dual_mode_enabled() -> bool:
    value = os.environ.get("PM_SCAN_PROXY_DUAL_MODE", "")
    if not value:
        value = os.environ.get("PM_PROXY_DUAL_MODE", "")
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _open_meteo_force_proxy() -> bool:
    value = os.environ.get("PM_SCAN_OPEN_METEO_FORCE_PROXY", "")
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _clob_direct_override_active() -> bool:
    with _CLOB_DIRECT_OVERRIDE_LOCK:
        until = float(_CLOB_DIRECT_OVERRIDE_UNTIL or 0.0)
    return until > 0 and time.time() < until


def _mark_clob_direct_override(reason: str, ttl_sec: float) -> None:
    if ttl_sec is None or not math.isfinite(ttl_sec) or ttl_sec <= 0:
        return
    now = time.time()
    until = now + float(ttl_sec)
    with _CLOB_DIRECT_OVERRIDE_LOCK:
        global _CLOB_DIRECT_OVERRIDE_UNTIL, _CLOB_DIRECT_OVERRIDE_REASON
        _CLOB_DIRECT_OVERRIDE_UNTIL = until
        _CLOB_DIRECT_OVERRIDE_REASON = str(reason or "")


def _env_has_proxy() -> bool:
    for key in ("HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "http_proxy", "https_proxy", "all_proxy"):
        if os.environ.get(key):
            return True
    return False


_PROXY_ENV_KEYS = ("HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "http_proxy", "https_proxy", "all_proxy")


def _parse_proxy_host_port(proxy_url: str) -> Tuple[str, Optional[int]]:
    if not proxy_url:
        return "", None
    if "://" not in proxy_url:
        proxy_url = f"http://{proxy_url}"
    try:
        parsed = urlparse(proxy_url)
    except Exception:
        return "", None
    return parsed.hostname or "", parsed.port


def _parse_port_list(value: Optional[str]) -> List[int]:
    if not value:
        return []
    ports: List[int] = []
    for part in re.split(r"[,\s]+", value):
        if not part:
            continue
        try:
            port = int(part)
        except (TypeError, ValueError):
            continue
        if port <= 0 or port > 65535:
            continue
        if port not in ports:
            ports.append(port)
    return ports


def _collect_proxy_port_candidates(scutil_output: str = "") -> List[int]:
    ports: List[int] = []
    ports.extend(_parse_port_list(os.environ.get("PM_PROXY_PORTS")))
    proxy_url = os.environ.get("HTTPS_PROXY") or os.environ.get("HTTP_PROXY") or os.environ.get("ALL_PROXY")
    if proxy_url:
        _host, port = _parse_proxy_host_port(proxy_url)
        if port and port not in ports:
            ports.append(port)
    if not ports and scutil_output:
        for key in ("HTTPPort", "HTTPSPort", "SOCKSPort"):
            raw = _parse_scutil_value(scutil_output, key)
            try:
                port = int(raw)
            except (TypeError, ValueError):
                continue
            if port > 0 and port <= 65535 and port not in ports:
                ports.append(port)
    return ports


def _local_proxy_fallback_ports(scutil_output: str = "") -> List[int]:
    ports = _collect_proxy_port_candidates(scutil_output)
    if ports:
        return ports
    ports = _parse_port_list(os.environ.get("PM_PROXY_LOCAL_FALLBACK_PORTS"))
    if ports:
        return ports
    return [1082]


def _detect_local_http_proxy_url(scutil_output: str = "") -> str:
    for host in ("127.0.0.1", "localhost"):
        for port in _local_proxy_fallback_ports(scutil_output):
            if _proxy_reachable(host, port):
                return f"http://{host}:{int(port)}"
    return ""


def _proxy_reachable(host: str, port: Optional[int], timeout: float = 0.5) -> bool:
    if not host or not port:
        return False
    try:
        with socket.create_connection((host, int(port)), timeout=timeout):
            return True
    except Exception:
        return False


def _current_proxy_unreachable() -> bool:
    proxy_url = os.environ.get("HTTPS_PROXY") or os.environ.get("HTTP_PROXY") or os.environ.get("ALL_PROXY")
    if not proxy_url:
        return False
    host, port = _parse_proxy_host_port(proxy_url)
    if host in {"127.0.0.1", "localhost"} and port:
        return not _proxy_reachable(host, port)
    return False


def _build_node_env() -> Dict[str, str]:
    _hydrate_auto_trade_runtime_env()
    env = dict(os.environ)
    force_direct = env.get("PM_CLOB_FORCE_DIRECT", "").strip().lower() in {"1", "true", "yes", "on"}
    if force_direct:
        for key in _PROXY_ENV_KEYS:
            env.pop(key, None)
        env.pop("GLOBAL_AGENT_HTTP_PROXY", None)
        return env
    proxy_url = env.get("HTTPS_PROXY") or env.get("HTTP_PROXY") or env.get("ALL_PROXY")
    if proxy_url:
        host, port = _parse_proxy_host_port(proxy_url)
        if host in {"127.0.0.1", "localhost"} and port:
            if not _proxy_reachable(host, port):
                output = ""
                if shutil.which("scutil"):
                    try:
                        output = subprocess.check_output(["scutil", "--proxy"], text=True)
                    except Exception:
                        output = ""
                candidates = _collect_proxy_port_candidates(output)
                replacement = None
                for candidate in candidates:
                    if candidate == port:
                        continue
                    if _proxy_reachable(host, candidate):
                        replacement = candidate
                        break
                if replacement:
                    proxy_value = f"http://{host}:{replacement}"
                    env["HTTP_PROXY"] = proxy_value
                    env["HTTPS_PROXY"] = proxy_value
                    env["GLOBAL_AGENT_HTTP_PROXY"] = proxy_value
                else:
                    for key in _PROXY_ENV_KEYS:
                        env.pop(key, None)
                    env.pop("GLOBAL_AGENT_HTTP_PROXY", None)
                    env["PM_CLOB_PROXY_SKIPPED"] = "1"
    proxy_url = env.get("HTTPS_PROXY") or env.get("HTTP_PROXY") or env.get("ALL_PROXY")
    if not proxy_url:
        fallback_proxy = _detect_local_http_proxy_url()
        if fallback_proxy:
            env["HTTP_PROXY"] = fallback_proxy
            env["HTTPS_PROXY"] = fallback_proxy
            env["http_proxy"] = fallback_proxy
            env["https_proxy"] = fallback_proxy
            env["GLOBAL_AGENT_HTTP_PROXY"] = fallback_proxy
    return env


def _coerce_int(value: Optional[str], default: int) -> int:
    try:
        return int(value) if value is not None else default
    except (TypeError, ValueError):
        return default


def _apply_clob_trade_env_defaults(env: Dict[str, str]) -> None:
    if "PM_CLOB_DIRECT_FIRST" not in env:
        env["PM_CLOB_DIRECT_FIRST"] = "1"
    if "PM_CLOB_DIRECT_RETRIES" not in env:
        env["PM_CLOB_DIRECT_RETRIES"] = "2"
    if "PM_CLOB_RETRY_MAX" not in env:
        env["PM_CLOB_RETRY_MAX"] = "2"
    if "PM_CLOB_TRADES_MAX_PAGES" not in env:
        # Align with node default (scripts/polymarket_order.mjs) and SOP: fetch enough pages per sync
        # so fills-based position reconciliation can converge quickly.
        env["PM_CLOB_TRADES_MAX_PAGES"] = "10"
    max_pages = _coerce_int(env.get("PM_CLOB_TRADES_MAX_PAGES"), 10)
    if max_pages <= 0:
        max_pages = 1
    if "PM_CLOB_TIMEOUT_MS" not in env:
        budget_ms = max(1000, int((AUTO_TRADE_TIMEOUT - 2) * 1000))
        timeout_ms = int(budget_ms / max_pages) if max_pages else budget_ms
        timeout_ms = max(5000, min(60000, timeout_ms))
        env["PM_CLOB_TIMEOUT_MS"] = str(timeout_ms)
    if "PM_CLOB_TRADES_BUDGET_MS" not in env:
        total_budget_ms = max(8000, int((AUTO_TRADE_TIMEOUT - 5) * 1000 * 0.35))
        env["PM_CLOB_TRADES_BUDGET_MS"] = str(min(30000, total_budget_ms))


def _apply_clob_fast_direct_env_defaults(
    env: Dict[str, str],
    *,
    timeout_sec: Optional[float] = None,
    hard_timeout_ms_key: Optional[str] = None,
    min_timeout_ms: int = 3000,
    max_timeout_ms: int = 8000,
    hard_timeout_min_ms: int = 4000,
    hard_timeout_padding_ms: int = 1000,
) -> None:
    force_proxy = env.get("PM_CLOB_FORCE_PROXY", "").strip().lower() in {"1", "true", "yes", "on"}
    force_direct = (
        env.get("PM_CLOB_FORCE_DIRECT", "").strip().lower() in {"1", "true", "yes", "on"}
        and not force_proxy
    )
    allow_proxy_fallback = env.get("PM_CLOB_FAST_ALLOW_PROXY_FALLBACK", "").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    if force_proxy:
        env["PM_CLOB_FORCE_PROXY"] = "1"
        env["PM_CLOB_FORCE_DIRECT"] = "0"
        env["PM_CLOB_DIRECT_FIRST"] = "0"
        env["PM_SCAN_FORCE_DIRECT"] = "0"
    elif not force_direct and not allow_proxy_fallback:
        env["PM_CLOB_FORCE_DIRECT"] = "1"
        force_direct = True
    if force_direct:
        for key in _PROXY_ENV_KEYS:
            env.pop(key, None)
        env.pop("GLOBAL_AGENT_HTTP_PROXY", None)
    if "PM_CLOB_DIRECT_FIRST" not in env:
        env["PM_CLOB_DIRECT_FIRST"] = "1"
    if "PM_CLOB_DIRECT_RETRIES" not in env:
        env["PM_CLOB_DIRECT_RETRIES"] = "1"
    if "PM_CLOB_RETRY_MAX" not in env:
        env["PM_CLOB_RETRY_MAX"] = "1"
    if "PM_CLOB_RETRY_BASE_MS" not in env:
        env["PM_CLOB_RETRY_BASE_MS"] = "0"
    if "PM_CLOB_RETRY_MAX_MS" not in env:
        env["PM_CLOB_RETRY_MAX_MS"] = "0"
    timeout_budget_ms = 6000
    if timeout_sec is not None and math.isfinite(timeout_sec) and timeout_sec > 0:
        timeout_budget_ms = int(
            max(
                int(min_timeout_ms),
                min(int(max_timeout_ms), float(timeout_sec) * 1000.0 - int(hard_timeout_padding_ms)),
            )
        )
    existing_timeout_ms = _coerce_int(env.get("PM_CLOB_TIMEOUT_MS"), 0)
    if existing_timeout_ms <= 0 or existing_timeout_ms > timeout_budget_ms:
        env["PM_CLOB_TIMEOUT_MS"] = str(timeout_budget_ms)
    hard_timeout_ms = _coerce_int(env.get("PM_CLOB_TIMEOUT_MS"), 6000) + int(
        hard_timeout_padding_ms
    )
    hard_timeout_ms = max(int(hard_timeout_min_ms), hard_timeout_ms)
    if hard_timeout_ms_key:
        existing_hard_timeout_ms = _coerce_int(env.get(hard_timeout_ms_key), 0)
        if existing_hard_timeout_ms <= 0 or existing_hard_timeout_ms > hard_timeout_ms:
            env[hard_timeout_ms_key] = str(hard_timeout_ms)
    existing_command_hard_timeout_ms = _coerce_int(env.get("PM_CLOB_COMMAND_HARD_TIMEOUT_MS"), 0)
    if (
        existing_command_hard_timeout_ms <= 0
        or existing_command_hard_timeout_ms > hard_timeout_ms
    ):
        env["PM_CLOB_COMMAND_HARD_TIMEOUT_MS"] = str(hard_timeout_ms)


def _cap_node_outer_timeout_to_hard_timeout(
    timeout_sec: float,
    env: Dict[str, str],
    *hard_timeout_keys: str,
    padding_sec: float = 0.75,
    min_timeout_sec: float = 2.0,
) -> float:
    hard_timeouts_ms = [
        _coerce_int(env.get(key), 0)
        for key in hard_timeout_keys
        if str(key or "").strip()
    ]
    hard_timeouts_ms = [value for value in hard_timeouts_ms if value > 0]
    if not hard_timeouts_ms:
        return timeout_sec
    hard_timeout_sec = min(hard_timeouts_ms) / 1000.0 + max(0.0, float(padding_sec))
    return max(float(min_timeout_sec), min(float(timeout_sec), hard_timeout_sec))


def _direct_target_order_timeout_sec() -> float:
    proxy_fallback_enabled = _env_bool("PM_AUTO_TRADE_DIRECT_PROXY_FALLBACK_ENABLED", False)
    timeout = _env_float("PM_AUTO_TRADE_DIRECT_ORDER_TIMEOUT_SEC")
    if timeout is None:
        timeout = _env_float("PM_HARD_SOURCE_DIRECT_ORDER_TIMEOUT_SEC")
    if timeout is None:
        timeout = _env_float("PM_POSTERIOR_TARGET_DIRECT_ORDER_TIMEOUT_SEC")
    if timeout is None or not math.isfinite(timeout) or timeout <= 0:
        timeout = 15.0 if proxy_fallback_enabled else 6.0
    min_timeout = _env_float("PM_AUTO_TRADE_DIRECT_ORDER_TIMEOUT_MIN_SEC")
    if min_timeout is None or not math.isfinite(min_timeout) or min_timeout <= 0:
        min_timeout = 2.0
    max_timeout = 15.0 if proxy_fallback_enabled else 8.0
    return max(float(min_timeout), min(float(timeout), max_timeout))


def _direct_target_exit_order_timeout_sec() -> float:
    timeout = _env_float("PM_AUTO_TRADE_DIRECT_EXIT_ORDER_TIMEOUT_SEC")
    if timeout is None:
        timeout = _env_float("PM_POSTERIOR_TARGET_DIRECT_EXIT_ORDER_TIMEOUT_SEC")
    if timeout is None:
        timeout = _env_float("PM_HARD_SOURCE_DIRECT_EXIT_ORDER_TIMEOUT_SEC")
    if timeout is None:
        timeout = _env_float("PM_AUTO_TRADE_EXIT_NODE_TIMEOUT_SEC")
    if timeout is None or not math.isfinite(timeout) or timeout <= 0:
        timeout = 15.0
    return max(5.0, min(float(timeout), 30.0))


def _cancel_order_timeout_sec() -> float:
    timeout = _env_float("PM_AUTO_TRADE_CANCEL_ORDER_TIMEOUT_SEC")
    if timeout is None:
        timeout = _env_float("PM_CLOB_CANCEL_ORDER_TIMEOUT_SEC")
    if timeout is None or not math.isfinite(timeout) or timeout <= 0:
        timeout = 20.0
    return max(5.0, min(float(timeout), 45.0))


def _get_order_timeout_sec() -> float:
    timeout = _env_float("PM_AUTO_TRADE_GET_ORDER_TIMEOUT_SEC")
    if timeout is None:
        timeout = _env_float("PM_CLOB_GET_ORDER_TIMEOUT_SEC")
    if timeout is None or not math.isfinite(timeout) or timeout <= 0:
        timeout = 12.0
    return max(3.0, min(float(timeout), 45.0))


def _direct_target_order_env_overrides(
    *,
    timeout_sec: Optional[float] = None,
    exit_order: bool = False,
) -> Dict[str, str]:
    if timeout_sec is None:
        timeout_sec = (
            _direct_target_exit_order_timeout_sec()
            if exit_order
            else _direct_target_order_timeout_sec()
        )
    global_force_proxy = _env_bool("PM_CLOB_FORCE_PROXY", False)
    allow_proxy_fallback = (
        global_force_proxy
        or _env_bool("PM_AUTO_TRADE_DIRECT_PROXY_FALLBACK_ENABLED", False)
    )
    force_proxy_on_fallback = global_force_proxy or (
        allow_proxy_fallback
        and _env_bool(
            "PM_AUTO_TRADE_DIRECT_FORCE_PROXY_ON_FALLBACK",
            True,
        )
    )
    if exit_order:
        clob_timeout_cap_ms = 90000
        clob_timeout_padding_ms = 5000
        clob_timeout_min_ms = 1200
    else:
        configured_cap_ms = _env_int("PM_AUTO_TRADE_DIRECT_ENTRY_CLOB_TIMEOUT_CAP_MS")
        if configured_cap_ms is None or configured_cap_ms <= 0:
            configured_cap_ms = _env_int("PM_CLOB_DIRECT_ENTRY_PLACE_ORDER_TIMEOUT_CAP_MS")
        if configured_cap_ms is None or configured_cap_ms <= 0:
            configured_cap_ms = 9000
        clob_timeout_cap_ms = max(2500, min(int(configured_cap_ms), 30000))
        configured_padding_ms = _env_int("PM_AUTO_TRADE_DIRECT_ENTRY_CLOB_TIMEOUT_PADDING_MS")
        if configured_padding_ms is None or configured_padding_ms <= 0:
            configured_padding_ms = 3500
        clob_timeout_padding_ms = max(500, min(int(configured_padding_ms), 10000))
        clob_timeout_min_ms = 800
    clob_timeout_ms = int(
        max(
            clob_timeout_min_ms,
            min(
                int(clob_timeout_cap_ms),
                float(timeout_sec) * 1000.0 - float(clob_timeout_padding_ms),
            ),
        )
    )
    entry_hard_padding_ms = 1000 if force_proxy_on_fallback else 12000
    hard_timeout_cap_ms = (
        clob_timeout_ms + (10000 if exit_order else entry_hard_padding_ms)
        if allow_proxy_fallback
        else clob_timeout_ms + (10000 if exit_order else 1000)
    )
    hard_timeout_ms = int(
        max(
            clob_timeout_ms + 250,
            min(float(timeout_sec) * 1000.0 - 100.0, hard_timeout_cap_ms),
        )
    )
    if hard_timeout_ms <= clob_timeout_ms:
        hard_timeout_ms = clob_timeout_ms + 250
    operation_timeout_ms = None
    if not exit_order:
        configured_operation_ms = _env_int("PM_AUTO_TRADE_DIRECT_ENTRY_OPERATION_TIMEOUT_MS")
        if configured_operation_ms is None or configured_operation_ms <= 0:
            configured_operation_ms = _env_int("PM_CLOB_DIRECT_ENTRY_PLACE_ORDER_OPERATION_TIMEOUT_MS")
        if configured_operation_ms is None or configured_operation_ms <= 0:
            configured_operation_ms = clob_timeout_ms + 500
        operation_timeout_ms = max(
            clob_timeout_ms + 250,
            min(int(configured_operation_ms), max(clob_timeout_ms + 250, hard_timeout_ms - 250)),
        )
    overrides = {
        "PM_AUTO_TRADE_DIRECT_JOB_CONTEXT": "1",
        "PM_AUTO_TRADE_DIRECT_ORDER_TIMEOUT_SEC": f"{timeout_sec:.3f}",
        "PM_AUTO_TRADE_DIRECT_EXIT_ORDER_CONTEXT": "1" if exit_order else "0",
        "PM_SCAN_FORCE_DIRECT": "0" if force_proxy_on_fallback else "1",
        "PM_CLOB_DIRECT_FIRST": "0" if force_proxy_on_fallback else "1",
        "PM_CLOB_DIRECT_RETRIES": "1",
        "PM_CLOB_RETRY_MAX": "2" if allow_proxy_fallback else "1",
        "PM_CLOB_PLACE_ORDER_MAX_ATTEMPTS": "2" if allow_proxy_fallback else "1",
        "PM_CLOB_PLACE_ORDER_TIMEOUT_CAP_MS": str(clob_timeout_cap_ms),
        "PM_CLOB_PLACE_ORDER_SDK_RETRY_ON_ERROR": "0",
        "PM_CLOB_RETRY_BASE_MS": "0",
        "PM_CLOB_RETRY_MAX_MS": "0",
        "PM_CLOB_TIMEOUT_MS": str(clob_timeout_ms),
        "PM_CLOB_COMMAND_HARD_TIMEOUT_MS": str(hard_timeout_ms),
        "PM_CLOB_PLACE_ORDER_HARD_TIMEOUT_MS": str(hard_timeout_ms),
        "PM_CLOB_DEFAULT_TICK_SIZE": str(os.environ.get("PM_CLOB_DEFAULT_TICK_SIZE") or "0.01"),
        "PM_CLOB_DEFAULT_NEG_RISK": str(os.environ.get("PM_CLOB_DEFAULT_NEG_RISK") or "1"),
    }
    if _env_bool("PM_AUTO_TRADE_DIRECT_SKIP_NODE_PARENT_WATCHDOG", True):
        overrides["PM_POLYMARKET_ORDER_WATCHDOG_CHILD"] = "1"
    if operation_timeout_ms is not None:
        overrides["PM_CLOB_PLACE_ORDER_OPERATION_TIMEOUT_MS"] = str(operation_timeout_ms)
    if allow_proxy_fallback:
        overrides["PM_CLOB_FAST_ALLOW_PROXY_FALLBACK"] = "1"
        overrides["PM_CLOB_FORCE_PROXY"] = "1" if force_proxy_on_fallback else "0"
        overrides["PM_CLOB_FORCE_DIRECT"] = "0"
    else:
        overrides["PM_CLOB_FORCE_PROXY"] = "0"
        overrides["PM_CLOB_FORCE_DIRECT"] = "1"
    return overrides


def _event_day_is_past(
    event_date_raw: Optional[str],
    fallback_event_date: Optional[str] = None,
    *,
    now_dt: Optional[datetime] = None,
) -> bool:
    now_local = now_dt or datetime.now().astimezone()
    for candidate in (event_date_raw, fallback_event_date):
        value = str(candidate or "").strip()
        if not value:
            continue
        try:
            event_day = datetime.strptime(value[:10], "%Y-%m-%d").date()
        except Exception:
            continue
        return event_day < now_local.date()
    return False


def _should_preserve_exit_retry_block(
    *,
    prev_last_action: Optional[str],
    prev_exit_live_like: bool,
) -> bool:
    if prev_exit_live_like:
        return True
    action_norm = str(prev_last_action or "").strip().lower()
    return action_norm in {"exit", "open_order_sync", "open_order_reprice"}


def _is_marketable_no_match_error(payload_or_text: Any) -> bool:
    if isinstance(payload_or_text, dict):
        text = " ".join(
            str(payload_or_text.get(key) or "")
            for key in ("error_detail", "error", "status", "statusText", "stderr", "stdout")
        )
    else:
        text = str(payload_or_text or "")
    lowered = text.strip().lower()
    if not lowered:
        return False
    if "no orders found to match" in lowered:
        return True
    return (
        "no match" in lowered
        and "fak" in lowered
        and ("kill" in lowered or "partially filled" in lowered)
    )


def _parse_scutil_value(text: str, key: str) -> str:
    m = re.search(rf"^\s*{re.escape(key)}\s*:\s*(.+)$", text, flags=re.M)
    return m.group(1).strip() if m else ""


def ensure_system_proxy_settings(force: bool = False) -> None:
    global _SYSTEM_PROXY_LAST_CHECK
    if _force_direct_enabled():
        return
    now = time.time()
    refresh_sec = float(os.environ.get("PM_PROXY_REFRESH_SEC", "60") or 60)
    # When the current proxy is unreachable (common in unstable local proxy setups), repeatedly
    # calling scutil and probing ports on every HTTP request can dominate runtime (especially during
    # market refresh which fans out across many orderbooks). Cache the "unreachable" state briefly.
    refresh_unreachable_sec = float(os.environ.get("PM_PROXY_REFRESH_UNREACHABLE_SEC", "10") or 10)
    proxy_unreachable = _current_proxy_unreachable()
    if (
        not force
        and _SYSTEM_PROXY_LAST_CHECK > 0
        and (
            (not proxy_unreachable and (now - _SYSTEM_PROXY_LAST_CHECK) < refresh_sec)
            or (proxy_unreachable and (now - _SYSTEM_PROXY_LAST_CHECK) < refresh_unreachable_sec)
        )
    ):
        return
    _SYSTEM_PROXY_LAST_CHECK = now
    proxy_url = os.environ.get("HTTPS_PROXY") or os.environ.get("HTTP_PROXY") or os.environ.get("ALL_PROXY")
    if proxy_url:
        host, port = _parse_proxy_host_port(proxy_url)
        if host in {"127.0.0.1", "localhost"} and port and not _proxy_reachable(host, port):
            output = ""
            if shutil.which("scutil"):
                try:
                    output = subprocess.check_output(["scutil", "--proxy"], text=True)
                except Exception:
                    output = ""
            candidates = _collect_proxy_port_candidates(output)
            for candidate in candidates:
                if candidate == port:
                    continue
                if _proxy_reachable(host, candidate):
                    os.environ["HTTP_PROXY"] = f"http://{host}:{candidate}"
                    os.environ["HTTPS_PROXY"] = f"http://{host}:{candidate}"
                    return
        return
    output = ""
    if shutil.which("scutil"):
        try:
            output = subprocess.check_output(["scutil", "--proxy"], text=True)
        except Exception:
            output = ""
    http_enable = _parse_scutil_value(output, "HTTPEnable") == "1"
    https_enable = _parse_scutil_value(output, "HTTPSEnable") == "1"
    socks_enable = _parse_scutil_value(output, "SOCKSEnable") == "1"
    http_host = _parse_scutil_value(output, "HTTPProxy")
    http_port = _parse_scutil_value(output, "HTTPPort")
    https_host = _parse_scutil_value(output, "HTTPSProxy")
    https_port = _parse_scutil_value(output, "HTTPSPort")
    socks_host = _parse_scutil_value(output, "SOCKSProxy")
    socks_port = _parse_scutil_value(output, "SOCKSPort")
    if http_enable and http_host and http_port:
        os.environ["HTTP_PROXY"] = f"http://{http_host}:{http_port}"
    if https_enable and https_host and https_port:
        os.environ["HTTPS_PROXY"] = f"http://{https_host}:{https_port}"
    if socks_enable and socks_host and socks_port:
        os.environ["ALL_PROXY"] = f"socks5://{socks_host}:{socks_port}"
    proxy_url = os.environ.get("HTTPS_PROXY") or os.environ.get("HTTP_PROXY") or os.environ.get("ALL_PROXY")
    if not proxy_url:
        fallback_proxy = _detect_local_http_proxy_url(output)
        if fallback_proxy:
            os.environ["HTTP_PROXY"] = fallback_proxy
            os.environ["HTTPS_PROXY"] = fallback_proxy
            os.environ["http_proxy"] = fallback_proxy
            os.environ["https_proxy"] = fallback_proxy


def _should_force_proxy(url: str) -> bool:
    if _force_direct_enabled():
        return False
    host = urlparse(url).hostname or ""
    if not host:
        return False
    host = host.lower()
    for suffix in DEFAULT_FORCE_PROXY_SUFFIXES:
        if host == suffix or host.endswith(f".{suffix}"):
            return True
    for pattern in _parse_host_list(os.environ.get("PM_SCAN_FORCE_PROXY_HOSTS")):
        if _host_matches(host, pattern):
            return True
    return False


def _should_bypass_proxy(url: str, requested: bool) -> bool:
    if requested:
        return True
    host = urlparse(url).hostname or ""
    if not host:
        return requested
    host = host.lower()
    if host in DEFAULT_BYPASS_PROXY_HOSTS:
        return True
    for suffix in DEFAULT_BYPASS_PROXY_SUFFIXES:
        if host == suffix or host.endswith(f".{suffix}"):
            return True
    meteostat_host = os.environ.get("METEOSTAT_API_HOST")
    if meteostat_host and _host_matches(host, meteostat_host):
        return True
    for pattern in _parse_host_list(os.environ.get("PM_SCAN_BYPASS_PROXY_HOSTS")):
        if _host_matches(host, pattern):
            return True
    return False


def _should_allow_insecure_ssl() -> bool:
    if INSECURE_SSL:
        return True
    value = os.environ.get("PM_SCAN_ALLOW_INSECURE_SSL", "")
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _sleep_backoff(backoff: float, attempt: int, max_backoff: float) -> None:
    delay = min(max_backoff, backoff * (2 ** attempt))
    jitter = delay * random.uniform(0.0, 0.2)
    time.sleep(delay + jitter)


def _refresh_auto_trade_config() -> None:
    global AUTO_TRADE_MIN_EDGE_SCORE, _AUTO_TRADE_CONFIG_MTIME
    global AUTO_TRADE_DRY_RUN
    global MINUTE_EDGE_ENTRY_ASK_MIN, MINUTE_EDGE_ENTRY_ASK_MAX
