    global MINUTE_EDGE_ENTRY_ASK_LE_Q_MIN_BUFFER
    global MINUTE_EDGE_ENTRY_EDGE_MIN
    global MINUTE_EDGE_ENTRY_YES_TOP_EDGE_MIN
    global MINUTE_EDGE_ENTRY_YES_TOP_REQUIRE_ASK_MIN, MINUTE_EDGE_ENTRY_YES_TOP_ASK_MIN
