def to_float(value: Optional[float]) -> Optional[float]:
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _finite_float(value: Any) -> Optional[float]:
    if isinstance(value, bool):
        return None
    val = to_float(value)
    if val is None or not math.isfinite(val):
        return None
    return float(val)


def _soft_forecast_posterior_status(
    *,
    peak_c: Any,
    posterior_signal: Any,
    status: Any = "",
    channel_status: Any = "",
    source: Any = "",
    captured_label: str = "已抓取但未进入主后验",
) -> Dict[str, Any]:
    peak_val = _finite_float(peak_c)
    signal_val = _finite_float(posterior_signal)
    if signal_val is None:
        signal_val = 0.0
    raw_status = str(status or "").strip()
    raw_channel_status = str(channel_status or "").strip()
    source_text = str(source or "").strip()
    captured = peak_val is not None or bool(raw_status) or bool(raw_channel_status) or bool(source_text)
    included = bool(captured and signal_val > 1e-12)
    if included:
        posterior_status = "included_in_main_posterior"
        label = "已进入主后验"
        reason = ""
    elif captured:
        posterior_status = "captured_not_in_main_posterior"
        label = captured_label
        if raw_channel_status:
            reason = raw_channel_status
        elif raw_status == "zero_scaled":
            reason = "created_at_safe_walk_forward_weight_zero"
        elif raw_status in {"disabled", "not_enabled"}:
            reason = "channel_disabled_or_not_approved"
        elif raw_status:
            reason = raw_status
        else:
            reason = "created_at_safe_walk_forward_not_approved"
    else:
        posterior_status = "not_captured"
        label = "未抓取"
        reason = "source_missing"
    return {
        "captured": captured,
        "posterior_included": included,
        "posterior_status": posterior_status,
        "posterior_label": label,
        "not_in_posterior_reason": "" if included else reason,
        "posterior_evidence": float(signal_val),
    }


def _first_finite_float(source: Mapping[str, Any], *keys: str) -> Tuple[Optional[float], str]:
    if not isinstance(source, Mapping):
        return None, ""
    for key in keys:
        val = _finite_float(source.get(key))
        if val is not None:
            return val, key
    return None, ""


def _min_finite_float(source: Mapping[str, Any], *keys: str) -> Tuple[Optional[float], str]:
    if not isinstance(source, Mapping):
        return None, ""
    best_val: Optional[float] = None
    best_key = ""
    for key in keys:
        val = _finite_float(source.get(key))
        if val is None:
            continue
        if best_val is None or float(val) < float(best_val):
            best_val = float(val)
            best_key = key
    return best_val, best_key


def _entry_usable_edge_env_float(key: str, default: float) -> float:
    raw = str(os.environ.get(key, "") or "").strip()
    if not raw:
        return float(default)
    val = _finite_float(raw)
    if val is None:
        return float(default)
    return float(val)


def _entry_usable_edge_bool(value: Any) -> Optional[bool]:
    if isinstance(value, bool):
        return value
    if value is None:
        return None
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "on", "ok", "pass"}:
        return True
    if text in {"0", "false", "no", "off", "fail", "blocked"}:
        return False
    return None


def _entry_usable_edge_counter_items(value: Any) -> List[str]:
    if value is None or isinstance(value, bool):
        return []
    if isinstance(value, (list, tuple, set)):
        raw_items: Iterable[Any] = value
    else:
        text = str(value or "").strip()
        if not text:
            return []
        parsed: Any = None
        if text[:1] == "[":
            try:
                parsed = json.loads(text)
            except Exception:
                parsed = None
        raw_items = parsed if isinstance(parsed, list) else re.split(r"[,;|]", text)
    out: List[str] = []
    for item in raw_items:
        text = str(item or "").strip()
        if text and text not in out:
            out.append(text)
    return out


