def _normalize_entry_block_reason_codes(
    reason_codes: Optional[Sequence[str]],
    entry_only_realizable: Optional[bool] = None,
) -> Tuple[List[str], List[str]]:
    hard_codes: List[str] = []
    soft_codes: List[str] = []
    seen_hard: Set[str] = set()
    seen_soft: Set[str] = set()
    soft_mode = bool(entry_only_realizable) if entry_only_realizable is not None else False
    for raw_code in reason_codes or []:
        code = str(raw_code or "").strip()
        if not code:
            continue
        canonical = ENTRY_HARD_REASON_ALIASES.get(code, code)
        if soft_mode and canonical in ENTRY_SOFT_REASON_CODES_WHEN_REALIZABLE_ONLY:
            if canonical not in seen_soft:
                soft_codes.append(canonical)
                seen_soft.add(canonical)
            continue
        if canonical in ENTRY_HARD_REASON_CODES:
            if canonical not in seen_hard:
                hard_codes.append(canonical)
                seen_hard.add(canonical)
        elif code not in seen_soft:
            soft_codes.append(code)
            seen_soft.add(code)
    return hard_codes, soft_codes


