def _exit_reason_family_for_code(raw_code: Any) -> str:
    return exit_reason_family_for_code(raw_code)


def _normalize_exit_reason_family_codes(
    reason_codes: Optional[Sequence[Any]],
) -> List[str]:
    families: List[str] = []
    seen: Set[str] = set()
    for raw_code in reason_codes or []:
        code = str(raw_code or "").strip()
        if not code or code in EXIT_DECISION_REASON_CODES:
            continue
        family = _exit_reason_family_for_code(raw_code)
        if not family or family in seen:
            continue
        families.append(family)
        seen.add(family)
    return families


def _declared_exit_reason_families(details: Optional[Mapping[str, Any]]) -> List[str]:
    if not isinstance(details, Mapping):
        return []
    declared: List[str] = []
    for key in (
        "exit_reason_family",
        "exit_reason_primary_family",
        "exit_policy_primary_family",
        "exit_reason_family_codes",
        "exit_policy_family_codes",
    ):
        for value in _parse_reason_list(details.get(key)):
            family = str(value or "").strip().lower()
            if family and family not in declared:
                declared.append(family)
    return declared


def _target_realization_invalidation_code_for_side(side: Any) -> str:
    return (
        "target_realization_no_invalidated"
        if str(side or "").strip().upper() == "NO"
        else "target_realization_yes_target_invalidated"
    )


def _is_executable_exit_reason_code(raw_code: Any) -> bool:
    return is_executable_exit_reason_code(raw_code)


def _exit_reason_text(raw_code: Any, side: Any = "") -> str:
    code = str(raw_code or "").strip()
    side_text = str(side or "").strip().upper()
    if code in TARGET_REALIZATION_EXIT_REASON_CODES:
        return f"Bayes目标失效/结算：{side_text or '持仓'} {code}"
    if code in MARKET_ALPHA_TAKE_PROFIT_REASON_CODES:
        return code
    return ""


def _filter_executable_exit_payload(
    reasons: Optional[Sequence[Any]],
    codes: Optional[Sequence[Any]],
    *,
    side: Any = "",
) -> Tuple[List[str], List[str], List[str]]:
    raw_codes = [str(code or "").strip() for code in (codes or []) if str(code or "").strip()]
    filtered_codes: List[str] = []
    removed_codes: List[str] = []
    for code in raw_codes:
        if _is_executable_exit_reason_code(code):
            if code not in filtered_codes:
                filtered_codes.append(code)
        else:
            removed_codes.append(code)

    if not filtered_codes:
        return [], [], removed_codes

    raw_reasons = [str(reason or "").strip() for reason in (reasons or []) if str(reason or "").strip()]
    filtered_reasons: List[str] = []
    for reason in raw_reasons:
        if (
            "Bayes" in reason
            or "目标桶" in reason
            or "目标仓位" in reason
            or "硬归零" in reason
            or "SSOT" in reason
        ):
            if reason not in filtered_reasons:
                filtered_reasons.append(reason)
    for code in filtered_codes:
        reason_text = _exit_reason_text(code, side=side)
        if reason_text and reason_text not in filtered_reasons:
            filtered_reasons.append(reason_text)
    return filtered_reasons, filtered_codes, removed_codes


def _exit_order_policy_allow_reason(
    reason_codes: Optional[Sequence[Any]],
    *,
    details: Optional[Mapping[str, Any]] = None,
) -> str:
    codes = _parse_reason_list(reason_codes)
    if not codes and isinstance(details, Mapping):
        codes = _parse_reason_list(details.get("exit_reason_codes"))
    executable_families = {
        _exit_reason_family_for_code(code)
        for code in codes
        if _is_executable_exit_reason_code(code)
    }
    executable_families.discard("")
    if len(executable_families) != 1:
        return ""
    expected_family = next(iter(executable_families))
    if _declared_exit_reason_families(details) != [expected_family]:
        return ""
    if any(not _is_executable_exit_reason_code(code) for code in codes):
        return ""
    if expected_family == MARKET_ALPHA_TAKE_PROFIT_FAMILY:
        return ""
    if expected_family == TARGET_REALIZATION_FAMILY:
        return expected_family
    return ""


def _exit_order_policy_block_reason(
    reason_codes: Optional[Sequence[Any]],
    *,
    details: Optional[Mapping[str, Any]] = None,
) -> str:
    if _exit_order_policy_allow_reason(reason_codes, details=details):
        return ""
    return EXIT_ORDER_POLICY_LEGACY_BLOCK_REASON


def _exit_order_policy_guard_details(
    reason_codes: Optional[Sequence[Any]],
    *,
    reasons: Optional[Sequence[Any]] = None,
    details: Optional[Mapping[str, Any]] = None,
    block_reason: str = "",
    side: Any = "",
) -> Dict[str, Any]:
    raw_codes = _parse_reason_list(reason_codes)
    if not raw_codes and isinstance(details, Mapping):
        raw_codes = _parse_reason_list(details.get("exit_reason_codes"))
    raw_reasons = _parse_reason_list(reasons)
    if not raw_reasons and isinstance(details, Mapping):
        raw_reasons = _parse_reason_list(details.get("exit_reasons"))
    filtered_reasons, filtered_codes, removed_codes = _filter_executable_exit_payload(
        raw_reasons,
        raw_codes,
        side=side,
    )
    allow_reason = _exit_order_policy_allow_reason(filtered_codes, details=details)
    return {
        "exit_order_policy_guard_version": EXIT_ORDER_POLICY_GUARD_VERSION,
        "exit_order_policy_allowed": bool(allow_reason),
        "exit_order_policy_allow_reason": allow_reason,
        "exit_order_policy_block_reason": str(block_reason or ""),
        "exit_order_policy_boundary": "exact_exit_reason_family_and_code_allowlist",
        "market_alpha_take_profit_runtime_enabled": bool(
            MARKET_ALPHA_TAKE_PROFIT_RUNTIME_ENABLED
        ),
        "exit_order_policy_input_reason_codes": list(raw_codes),
        "exit_order_policy_input_reasons": list(raw_reasons),
        "exit_order_policy_allowed_reason_codes": list(filtered_codes),
        "exit_order_policy_declared_families": _declared_exit_reason_families(details),
        "exit_order_policy_allowed_reasons": list(filtered_reasons),
        "exit_order_policy_removed_legacy_codes": list(removed_codes),
    }


def _dump_exit_reason_family_codes(reason_codes: Any) -> Optional[str]:
    family_codes = _normalize_exit_reason_family_codes(_parse_reason_list(reason_codes))
    return _dump_reason_list(family_codes)


def _exit_operational_reason_codes_from_decision(
    decision_reason_codes: Optional[Sequence[Any]],
) -> List[str]:
    out: List[str] = []
    for raw_code in decision_reason_codes or []:
        text = str(raw_code or "").strip()
        if not text or text not in EXIT_DECISION_REASON_CODES or text in out:
            continue
        out.append(text)
    return out


def _exit_trigger_reason_codes_from_decision(
    details: Optional[Mapping[str, Any]],
    decision_reason_codes: Optional[Sequence[Any]] = None,
) -> List[str]:
    out: List[str] = []
    if isinstance(details, Mapping):
        for code in _parse_reason_list(details.get("exit_reason_codes")):
            text = str(code or "").strip()
            if not text or text in out or text in EXIT_DECISION_REASON_CODES:
                continue
            if not _is_executable_exit_reason_code(text):
                continue
            out.append(text)
    if not out:
        for code in decision_reason_codes or []:
            text = str(code or "").strip()
            if not text or text in out:
                continue
            if text in EXIT_DECISION_REASON_CODES:
                continue
            if not _is_executable_exit_reason_code(text):
                continue
            out.append(text)
    return out


def _infer_exit_trigger_reason_codes_from_policy(
    details: Optional[Mapping[str, Any]],
    trigger_reason_codes: Optional[Sequence[Any]] = None,
) -> List[str]:
    out: List[str] = []
    seen: Set[str] = set()
    for raw_code in trigger_reason_codes or []:
        code = str(raw_code or "").strip()
        if not code or code in seen:
            continue
        out.append(code)
        seen.add(code)
    return out


def _build_exit_policy_audit(
    details: Optional[Mapping[str, Any]],
    *,
    trigger_reason_codes: Optional[Sequence[Any]] = None,
    family_codes: Optional[Sequence[Any]] = None,
    operational_reason_codes: Optional[Sequence[Any]] = None,
) -> Dict[str, Any]:
    details_map = details if isinstance(details, Mapping) else {}
    trigger_codes = _parse_reason_list(trigger_reason_codes)
    if not trigger_codes:
        trigger_codes = _parse_reason_list(
            details_map.get("exit_original_reason_codes")
            or details_map.get("exit_reason_codes")
        )
    families = _parse_reason_list(family_codes)
    if not families:
        families = _parse_reason_list(details_map.get("exit_reason_family_codes"))
    families = [
        str(family or "").strip()
        for family in families
        if str(family or "").strip() in EXIT_REASON_FAMILY_CODES
    ]
    if not families and trigger_codes:
        families = _normalize_exit_reason_family_codes(trigger_codes)
    op_codes = _parse_reason_list(operational_reason_codes)
    if not op_codes:
        op_codes = _parse_reason_list(details_map.get("exit_operational_reason_codes"))

    edge_min = _finite_float(details_map.get("exit_hold_edge_realizable_min"))
    if edge_min is None:
        edge_min = float(MINUTE_EDGE_HEADROOM_EXIT)
    edge_value = _finite_float(details_map.get("hold_edge_realizable"))
    edge_trigger_value = _finite_float(details_map.get("hold_edge_realizable_trigger"))
    prev_edge_trigger_value = _finite_float(details_map.get("prev_hold_edge_realizable"))

    edge_current_below_min = bool(edge_value is not None and edge_value < edge_min)
    edge_trigger_below_min = bool(
        edge_trigger_value is not None and edge_trigger_value < edge_min
    )
    prev_edge_trigger_below_min = bool(
        prev_edge_trigger_value is not None and prev_edge_trigger_value < edge_min
    )
    target_realization_triggered = bool(TARGET_REALIZATION_FAMILY in families)
    edge_triggered = False
    risk_triggered = False
    repricing_triggered = False
    strategy_triggered = bool(target_realization_triggered)
    blocking_op_codes = [
        code for code in op_codes if code not in EXIT_OPERATIONAL_NON_BLOCKING_CODES
    ]

    audit: Dict[str, Any] = {
        "exit_policy_version": EXIT_POLICY_VERSION,
        "exit_policy_rule": EXIT_POLICY_RULE,
        "exit_policy_primary_source": EXIT_POLICY_PRIMARY_SOURCE,
        "exit_policy_primary_edge_source": "",
        "exit_policy_legacy_edge_min": float(edge_min),
        "exit_policy_legacy_edge_below_min": bool(
            edge_current_below_min or edge_trigger_below_min
        ),
        "exit_policy_legacy_edge_current_below_min": bool(edge_current_below_min),
        "exit_policy_legacy_edge_trigger_below_min": bool(edge_trigger_below_min),
        "exit_policy_legacy_prev_edge_trigger_below_min": bool(prev_edge_trigger_below_min),
        "exit_policy_edge_min": None,
        "exit_policy_edge_below_min": False,
        "exit_policy_edge_current_below_min": False,
        "exit_policy_edge_trigger_below_min": False,
        "exit_policy_prev_edge_trigger_below_min": False,
        "exit_policy_edge_triggered": bool(edge_triggered),
        "exit_policy_target_realization_triggered": bool(target_realization_triggered),
        "exit_policy_risk_triggered": bool(risk_triggered),
        "exit_policy_repricing_triggered": bool(repricing_triggered),
        "exit_policy_strategy_triggered": bool(strategy_triggered),
        "exit_policy_operational_blocked": bool(blocking_op_codes),
        "exit_policy_order_submitted": bool(
            any(code == "order_submitted" for code in op_codes)
        ),
        "exit_policy_marketable_submitted": bool(
            any(code == "exit_marketable_retry_submitted" for code in op_codes)
        ),
        "exit_policy_no_trigger": bool("exit_no_trigger" in op_codes),
    }
    if edge_value is not None:
        audit["exit_policy_legacy_edge_value"] = float(edge_value)
    else:
        audit["exit_policy_legacy_edge_na_reason"] = "hold_edge_realizable_missing"
    if edge_trigger_value is not None:
        audit["exit_policy_legacy_edge_trigger_value"] = float(edge_trigger_value)
    if prev_edge_trigger_value is not None:
        audit["exit_policy_legacy_prev_edge_trigger_value"] = float(prev_edge_trigger_value)
    edge_realizable_only = _entry_usable_edge_bool(details_map.get("exit_edge_realizable_only"))
    if edge_realizable_only is not None:
        audit["exit_policy_edge_realizable_only"] = bool(edge_realizable_only)
    if trigger_codes:
        audit["exit_policy_trigger_reason_codes"] = list(trigger_codes)
    if families:
        audit["exit_policy_family_codes"] = list(families)
        audit["exit_policy_primary_family"] = str(families[0])
    if op_codes:
        audit["exit_policy_operational_reason_codes"] = list(op_codes)
    if blocking_op_codes:
        audit["exit_policy_operational_block_codes"] = list(blocking_op_codes)
    return audit


def _finalize_exit_decision_details(
    details: Optional[Mapping[str, Any]],
    decision_reason_codes: Optional[Sequence[Any]] = None,
) -> Dict[str, Any]:
    merged_details = dict(details or {}) if isinstance(details, Mapping) else {}
    raw_exit_codes = _exit_trigger_reason_codes_from_decision(
        merged_details,
        decision_reason_codes=decision_reason_codes,
    )
    raw_exit_codes = _infer_exit_trigger_reason_codes_from_policy(
        merged_details,
        trigger_reason_codes=raw_exit_codes,
    )
    family_codes = _normalize_exit_reason_family_codes(raw_exit_codes)
    operational_codes = _exit_operational_reason_codes_from_decision(
        decision_reason_codes
    )
    if raw_exit_codes:
        merged_details["exit_original_reason_codes"] = list(raw_exit_codes)
    if family_codes:
        merged_details["exit_reason_family_codes"] = list(family_codes)
        merged_details["exit_reason_primary_family"] = str(family_codes[0])
    if operational_codes:
        merged_details["exit_operational_reason_codes"] = list(operational_codes)
    merged_details["exit_policy_primary_source"] = EXIT_POLICY_PRIMARY_SOURCE
    merged_details["exit_edge_primary_source"] = ""
    merged_details.update(
        _build_exit_policy_audit(
            merged_details,
            trigger_reason_codes=raw_exit_codes,
            family_codes=family_codes,
            operational_reason_codes=operational_codes,
        )
    )
    return merged_details


_EXPLICIT_SSOT_ENTRY_BLOCK_CONTEXT_FIELDS: Tuple[str, ...] = (
    "entry_usable_edge_na_reason",
    "weather_strategy_entry_block_reason",
    "posterior_settlement_entry_block_reason",
    "auto_trade_ssot_diagnostic",
    "target_realization_batch_reason",
    "target_bucket",
    "target_posterior",
    "remote_bucket_realization_prob",
    "token_id",
    "ssot_entry_reasons",
)


def _nonempty_decision_detail_value(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, str) and not value.strip():
        return False
    return True


def _is_explicit_ssot_entry_block_context(source: Optional[Mapping[str, Any]]) -> bool:
    if not isinstance(source, Mapping):
        return False
    if source.get("entry_ok") is False or source.get("expected_entry_ok") is False:
        return bool(source.get("auto_trade_ssot_diagnostic") or source.get("target_realization_batch_reason"))
    return False


def _explicit_ssot_entry_block_context(source: Optional[Mapping[str, Any]]) -> Dict[str, Any]:
    if not _is_explicit_ssot_entry_block_context(source):
        return {}
    assert isinstance(source, Mapping)
    out: Dict[str, Any] = {
        "expected_entry_ok": False,
        "auto_trade_ssot_diagnostic": True,
    }
    block_reason = str(
        source.get("weather_strategy_entry_block_reason")
        or source.get("entry_usable_edge_na_reason")
        or source.get("posterior_settlement_entry_block_reason")
        or ""
    ).strip()
    if block_reason:
        out["entry_usable_edge_na_reason"] = block_reason
        out["weather_strategy_entry_block_reason"] = block_reason
    for field in _EXPLICIT_SSOT_ENTRY_BLOCK_CONTEXT_FIELDS:
        if field not in source:
            continue
        value = source.get(field)
        if not _nonempty_decision_detail_value(value):
            continue
        if field in {"entry_usable_edge_na_reason", "weather_strategy_entry_block_reason"} and block_reason:
            continue
        out[field] = value
    return out


def _apply_explicit_ssot_entry_block_context(
    target: Dict[str, Any],
    source: Optional[Mapping[str, Any]],
) -> Dict[str, Any]:
    if not isinstance(target, dict):
        return target
    context = _explicit_ssot_entry_block_context(source)
    if not context:
        return target
    for field, value in context.items():
        if _nonempty_decision_detail_value(value) or field in {"expected_entry_ok", "auto_trade_ssot_diagnostic"}:
            target[field] = value
    return target


