def _load_market_tick_latest_by_key(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> Dict[Tuple[str, str], datetime]:
    latest_by_key: Dict[Tuple[str, str], datetime] = {}
    if not slug or not event_date:
        return latest_by_key
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT outcome, side, MAX(created_at) AS last_at
            FROM event_market_ticks
            WHERE slug = ? AND event_date = ?
            GROUP BY outcome, side
            """,
            (slug, event_date),
        )
        for tick_row in cur.fetchall():
            outcome = str(tick_row[0] or "").strip()
            side = str(tick_row[1] or "").strip().upper()
            last_at_text = str(tick_row[2] or "").strip()
            if not outcome or side not in {"YES", "NO"} or not last_at_text:
                continue
            ts = _parse_iso_dt(last_at_text)
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
            latest_by_key[(outcome, side)] = ts
    except sqlite3.OperationalError:
        pass
    return latest_by_key


def _load_market_tick_latest_signature_by_key(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    *,
    source: str,
    source_detail: str,
) -> Dict[
    Tuple[str, str],
    Tuple[Optional[float], Optional[float], Optional[float], Optional[float], Optional[float], datetime],
]:
    latest_by_key: Dict[
        Tuple[str, str],
        Tuple[Optional[float], Optional[float], Optional[float], Optional[float], Optional[float], datetime],
    ] = {}
    if not slug or not event_date:
        return latest_by_key
    if not source:
        source = ""
    if not source_detail:
        source_detail = ""
    cur = conn.cursor()
    limit_raw = _env_int("PM_AUTO_TRADE_MARKET_TICK_SIGNATURE_LOOKBACK_ROWS")
    if limit_raw is None or limit_raw <= 0:
        limit_raw = 120
    lookback_limit = max(20, min(int(limit_raw), 500))
    busy_timeout_raw = _env_int("PM_AUTO_TRADE_MARKET_TICK_SIGNATURE_BUSY_TIMEOUT_MS")
    if busy_timeout_raw is None or busy_timeout_raw < 0:
        busy_timeout_raw = 100
    busy_timeout_ms = max(0, min(int(busy_timeout_raw), 1000))
    deadline_sec = _env_float("PM_AUTO_TRADE_MARKET_TICK_SIGNATURE_DEADLINE_SEC")
    if deadline_sec is None or not math.isfinite(deadline_sec) or deadline_sec <= 0:
        deadline_sec = 0.25
    deadline_at = time.monotonic() + max(0.05, min(float(deadline_sec), 2.0))
    source_sql = """
        SELECT outcome, side, best_bid, best_ask, spread, bid_depth_topN, ask_depth_topN, created_at
        FROM event_market_ticks
        WHERE slug = ? AND event_date = ? AND source = ? AND source_detail = ?
        ORDER BY created_at DESC, id DESC
        LIMIT ?
    """
    # Source/version fields were introduced recently. Rows written earlier may be
    # missing source tags; when no source-qualified row exists, fallback to a
    # bounded newest slice across all sources. This function is only a coalescing
    # optimization, so it must never block auto-trade on a full tick-history scan.
    fallback_sql = """
        SELECT outcome, side, best_bid, best_ask, spread, bid_depth_topN, ask_depth_topN, created_at
        FROM event_market_ticks
        WHERE slug = ? AND event_date = ?
        ORDER BY created_at DESC, id DESC
        LIMIT ?
    """

    def _progress_handler() -> int:
        return 1 if time.monotonic() > deadline_at else 0

    def _collect(rows: Iterable[Any]) -> None:
        for tick_row in rows:
            outcome = str(tick_row[0] or "").strip()
            side = str(tick_row[1] or "").strip().upper()
            if not outcome or side not in {"YES", "NO"}:
                continue
            key = (outcome, side)
            if key in latest_by_key:
                continue
            created_at = _parse_iso_dt(tick_row[7] if len(tick_row) > 7 else None)
            if created_at is None:
                continue
            if created_at.tzinfo is None:
                created_at = created_at.replace(tzinfo=timezone.utc)
            latest_by_key[key] = (
                to_float(tick_row[2]),
                to_float(tick_row[3]),
                to_float(tick_row[4]),
                to_float(tick_row[5]),
                to_float(tick_row[6]),
                created_at,
            )

    try:
        try:
            conn.execute(f"PRAGMA busy_timeout={int(busy_timeout_ms)}")
        except sqlite3.Error:
            pass
        try:
            conn.set_progress_handler(_progress_handler, 1000)
        except Exception:
            pass
        rows = cur.execute(source_sql, (slug, event_date, source, source_detail, lookback_limit)).fetchall()
        if not rows:
            rows = cur.execute(fallback_sql, (slug, event_date, lookback_limit)).fetchall()
        _collect(rows)
    except sqlite3.OperationalError:
        pass
    finally:
        try:
            conn.set_progress_handler(None, 0)
        except Exception:
            pass
        try:
            conn.execute(f"PRAGMA busy_timeout={int(DB_BUSY_TIMEOUT_MS)}")
        except sqlite3.Error:
            pass
    return latest_by_key


_EVENT_MARKET_TICK_CLEANUP_STATE = DATA_DIR / "event_market_ticks.cleanup_at"


def _should_run_market_tick_cleanup(now_ts: float) -> bool:
    raw_interval = os.environ.get("PM_DB_TICK_CLEANUP_INTERVAL_SEC", "900")
    try:
        interval_sec = float(str(raw_interval).strip())
    except Exception:
        interval_sec = 900.0
    if not math.isfinite(interval_sec) or interval_sec <= 0:
        return False
    if not DATA_DIR.exists():
        return False
    try:
        last_cleanup_ts = _EVENT_MARKET_TICK_CLEANUP_STATE.stat().st_mtime
    except FileNotFoundError:
        return True
    except OSError:
        return True
    return (now_ts - last_cleanup_ts) >= interval_sec


def _mark_market_tick_cleanup_run(now_ts: float) -> None:
    if not DATA_DIR.exists():
        return
    try:
        _EVENT_MARKET_TICK_CLEANUP_STATE.write_text(
            f"{float(now_ts)}",
            encoding="utf-8",
        )
    except Exception:
        pass


def _cleanup_expired_market_ticks(conn: sqlite3.Connection, now_iso: Optional[str] = None) -> int:
    try:
        keep_days = _env_int("PM_DB_KEEP_TICKS_DAYS")
    except Exception:
        keep_days = None
    if keep_days is None or keep_days <= 0:
        return 0
    if now_iso is None or not now_iso:
        now_iso = utc_now_iso()
    try:
        cutoff_dt = datetime.fromisoformat(str(now_iso).replace("Z", "+00:00")) - timedelta(
            days=int(keep_days)
        )
    except Exception:
        now_dt = datetime.now(timezone.utc)
        cutoff_dt = now_dt - timedelta(days=int(keep_days))
    cutoff_iso = cutoff_dt.isoformat()
    batch_size = _env_int("PM_DB_GOVERNANCE_BATCH_SIZE")
    if batch_size is None or batch_size <= 0:
        batch_size = 50000
    cur = conn.cursor()
    try:
        cur.execute(
            """
            DELETE FROM event_market_ticks
            WHERE id IN (
                SELECT id FROM event_market_ticks
                WHERE created_at < ?
                ORDER BY created_at ASC
                LIMIT ?
            )
            """,
            (cutoff_iso, int(batch_size)),
        )
        return int(cur.rowcount or 0)
    except sqlite3.Error:
        return 0


def _tick_signature_changed(
    prev: Tuple[Optional[float], Optional[float], Optional[float], Optional[float], Optional[float]],
    curr: Tuple[Optional[float], Optional[float], Optional[float], Optional[float], Optional[float]],
    *,
    tolerance: float,
) -> bool:
    p_bid, p_ask, p_spread, p_bid_depth, p_ask_depth = prev
    c_bid, c_ask, c_spread, c_bid_depth, c_ask_depth = curr
    for p_v, c_v in (
        (p_bid, c_bid),
        (p_ask, c_ask),
        (p_spread, c_spread),
        (p_bid_depth, c_bid_depth),
        (p_ask_depth, c_ask_depth),
    ):
        if p_v is None and c_v is None:
            continue
        if p_v is None or c_v is None:
            return True
        if abs(float(p_v) - float(c_v)) > float(tolerance):
            return True
    return False


def _augment_rows_with_positions(
    rows: List[Dict[str, Any]],
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> List[Dict[str, Any]]:
    if not rows:
        rows = []
    if not slug or not event_date:
        return rows
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT outcome, side
            FROM edge_trades
            WHERE slug = ? AND event_date = ?
              AND (
                (position_size IS NOT NULL AND position_size > 0)
                OR state IN ('entry', 'entry_pending')
                OR (
                    state = 'exit'
                    AND COALESCE(last_order_id, '') != ''
                    AND COALESCE(last_status, '') NOT IN ('no_position', 'exit_size_too_small')
                )
              )
            """,
            (slug, event_date),
        )
        open_rows = cur.fetchall()
    except sqlite3.OperationalError:
        return rows
    if not open_rows:
        return rows
    outcome_map: Dict[str, Dict[str, Any]] = {}
    for row in rows:
        outcome = str(row.get("outcome") or "")
        if outcome and outcome not in outcome_map:
            outcome_map[outcome] = row
    for open_row in open_rows:
        outcome = str(open_row[0] or "")
        side = str(open_row[1] or "").upper()
        if not outcome or side not in {"YES", "NO"}:
            continue
        row = outcome_map.get(outcome)
        if row is None:
            row = {"outcome": outcome, "synthetic_exit_only": True}
            rows.append(row)
            outcome_map[outcome] = row
            print(f"[auto-trade] add exit row {slug} {outcome} side={side} reason=missing_bucket")
        token_key = "yes_token" if side == "YES" else "no_token"
        if not row.get(token_key):
            token_id = _lookup_token_from_fills(conn, slug, event_date, outcome, side)
            if token_id:
                row[token_key] = token_id
        bid_key = "best_bid" if side == "YES" else "best_bid_no"
        ask_key = "best_ask" if side == "YES" else "best_ask_no"
        prev_bid_key = "prev_best_bid" if side == "YES" else "prev_best_bid_no"
        prev_ask_key = "prev_best_ask" if side == "YES" else "prev_best_ask_no"
        if row.get(bid_key) is None and row.get(ask_key) is None:
            (
                best_bid,
                best_ask,
                bid_depth,
                ask_depth,
                prev_bid,
                prev_ask,
                _prev_bid_depth,
                _prev_ask_depth,
            ) = _latest_tick_for_outcome(conn, slug, event_date, outcome, side)
            if best_bid is not None:
                row[bid_key] = best_bid
            if best_ask is not None:
                row[ask_key] = best_ask
            depth_bid_key = "bid_depth_topN" if side == "YES" else "bid_depth_topN_no"
            depth_ask_key = "ask_depth_topN" if side == "YES" else "ask_depth_topN_no"
            if row.get(depth_bid_key) is None and bid_depth is not None:
                row[depth_bid_key] = bid_depth
            if row.get(depth_ask_key) is None and ask_depth is not None:
                row[depth_ask_key] = ask_depth
            if prev_bid is not None:
                row[prev_bid_key] = prev_bid
            if prev_ask is not None:
                row[prev_ask_key] = prev_ask
            if side == "YES":
                if row.get("spread") is None and best_bid is not None and best_ask is not None:
                    row["spread"] = max(best_ask - best_bid, 0.0)
            else:
                if row.get("spread_no") is None and best_bid is not None and best_ask is not None:
                    row["spread_no"] = max(best_ask - best_bid, 0.0)
        if row.get(prev_bid_key) is None and row.get(bid_key) is not None:
            row[prev_bid_key] = row.get(bid_key)
        if row.get(prev_ask_key) is None and row.get(ask_key) is not None:
            row[prev_ask_key] = row.get(ask_key)
    return rows


def _fill_rows_with_latest_ticks(
    rows: List[Dict[str, Any]],
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    *,
    override_existing: bool = True,
) -> None:
    if not rows or not slug or not event_date:
        return

    def _apply_side(
        row: Dict[str, Any],
        *,
        side: str,
        best_bid: Optional[float],
        best_ask: Optional[float],
        bid_depth: Optional[float],
        ask_depth: Optional[float],
    ) -> None:
        side_u = side.upper()
        if side_u == "NO":
            bid_key = "best_bid_no"
            ask_key = "best_ask_no"
            spread_key = "spread_no"
            bid_depth_key = "bid_depth_topN_no"
            ask_depth_key = "ask_depth_topN_no"
            ask_reason_key = "ask_missing_reason_no"
            override_key = "market_tick_override_no"
            source_key = "market_tick_override_source_no"
            overrode_key = "market_tick_quote_overrode_existing_no"
        else:
            bid_key = "best_bid"
            ask_key = "best_ask"
            spread_key = "spread"
            bid_depth_key = "bid_depth_topN"
            ask_depth_key = "ask_depth_topN"
            ask_reason_key = "ask_missing_reason_yes"
            override_key = "market_tick_override_yes"
            source_key = "market_tick_override_source_yes"
            overrode_key = "market_tick_quote_overrode_existing_yes"

        gamma_fallback = (
            str(row.get(ask_reason_key) or "").strip().lower()
            == "gamma_price_fallback"
        )
        can_override = bool(override_existing or gamma_fallback)
        touched = False
        overrode_existing = False

        def _set_quote(key: str, value: Optional[float]) -> None:
            nonlocal touched, overrode_existing
            if value is None:
                return
            previous = row.get(key)
            if previous is not None and not can_override:
                return
            prev_float = to_float(previous) if previous is not None else None
            if (
                prev_float is not None
                and math.isfinite(prev_float)
                and abs(float(prev_float) - float(value)) > TIME_EDGE_Q_EPS
            ):
                overrode_existing = True
            row[key] = value
            touched = True

        _set_quote(bid_key, best_bid)
        _set_quote(ask_key, best_ask)
        _set_quote(bid_depth_key, bid_depth)
        _set_quote(ask_depth_key, ask_depth)
        if best_bid is not None and best_ask is not None:
            _set_quote(spread_key, max(best_ask - best_bid, 0.0))

        if not touched:
            return
        if best_ask is not None:
            row[ask_reason_key] = None
        row[override_key] = True
        row[source_key] = "event_market_ticks"
        if overrode_existing:
            row[overrode_key] = True

    for row in rows:
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        (
            best_bid,
            best_ask,
            bid_depth,
            ask_depth,
            _prev_bid,
            _prev_ask,
            _prev_bid_depth,
            _prev_ask_depth,
        ) = _latest_tick_for_outcome(conn, slug, event_date, outcome, "YES")
        _apply_side(
            row,
            side="YES",
            best_bid=best_bid,
            best_ask=best_ask,
            bid_depth=bid_depth,
            ask_depth=ask_depth,
        )

        (
            best_bid_no,
            best_ask_no,
            bid_depth_no,
            ask_depth_no,
            _prev_bid_no,
            _prev_ask_no,
            _prev_bid_depth_no,
            _prev_ask_depth_no,
        ) = _latest_tick_for_outcome(conn, slug, event_date, outcome, "NO")
        _apply_side(
            row,
            side="NO",
            best_bid=best_bid_no,
            best_ask=best_ask_no,
            bid_depth=bid_depth_no,
            ask_depth=ask_depth_no,
        )


def _edge_level(headroom: Optional[float]) -> Tuple[str, float]:
    if headroom is None:
        return "", 0.0
    h_pct = headroom * 100.0
    for low, high, label, ratio in EDGE_LEVELS:
        if h_pct >= low and h_pct < high:
            return label, ratio
    return "", 0.0


def _ask_discount(ask: Optional[float]) -> float:
    if ask is None:
        return 1.0
    try:
        pct = float(ask) * 100.0
    except (TypeError, ValueError):
        return 1.0
    if pct > 90.0:
        return 0.5
    if pct > 80.0:
        return 0.7
    return 1.0


def _is_tail_locked_quote(ask: Optional[float], q_prob: Optional[float]) -> bool:
    if not MINUTE_EDGE_ENTRY_TAIL_LOCK_ENABLED:
        return False
    if ask is None or not math.isfinite(ask):
        return False
    if ask <= MINUTE_EDGE_ENTRY_TAIL_LOCK_ASK_HARD + TIME_EDGE_Q_EPS:
        return True
    if q_prob is None or not math.isfinite(q_prob):
        return False
    return (
        ask <= MINUTE_EDGE_ENTRY_TAIL_LOCK_ASK_SOFT + TIME_EDGE_Q_EPS
        and q_prob >= MINUTE_EDGE_ENTRY_TAIL_LOCK_Q_MIN - TIME_EDGE_Q_EPS
    )


def _format_pct(value: Optional[float], decimals: int = 1) -> str:
    if value is None:
        return "—"
    try:
        return f"{value * 100:.{decimals}f}%"
    except (TypeError, ValueError):
        return "—"


def _format_ratio(value: Optional[float], decimals: int = 2) -> str:
    if value is None:
        return "—"
    try:
        return f"{value:.{decimals}f}"
    except (TypeError, ValueError):
        return "—"


def _entry_depth_mult(
    edge_score: Optional[float],
    min_mult: float,
    max_mult: float,
    slope: float,
) -> float:
    if max_mult <= 0:
        return 0.0
    if edge_score is None or not math.isfinite(edge_score):
        return max_mult
    if min_mult > max_mult:
        min_mult = max_mult
    mult = max_mult - slope * edge_score
    return max(min_mult, min(max_mult, mult))


def _format_usdc(value: Optional[float]) -> str:
    if value is None:
        return "—"
    try:
        return f"${value:.2f}"
    except (TypeError, ValueError):
        return "—"


def _env_float(key: str, default: Optional[float] = None) -> Optional[float]:
    val = to_float(_env_value_with_path_follow_alias(key))
    if val is None or not math.isfinite(val):
        return float(default) if default is not None else None
    return float(val)


DEFAULT_KELLY_FRACTION = 0.10
DEFAULT_MAX_ORDER_NOTIONAL_USDC = 10.0


def _env_int(key: str) -> Optional[int]:
    raw = _env_value_with_path_follow_alias(key)
    if raw is None:
        return None
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


def _sqlite_locked_error(exc: Exception) -> bool:
    text = str(exc or "").lower()
    return "locked" in text or "busy" in text


def _sqlite_execute_with_retry(
    cur: sqlite3.Cursor,
    sql: str,
    params: Tuple[Any, ...] = (),
    *,
    attempts: int = 8,
    sleep_base_sec: float = 0.25,
    sleep_cap_sec: float = 2.0,
) -> None:
    max_attempts = max(1, int(attempts))
    base_sleep = max(0.0, float(sleep_base_sec))
    cap_sleep = max(0.0, float(sleep_cap_sec))
    for attempt in range(max_attempts):
        try:
            cur.execute(sql, params)
            return
        except sqlite3.OperationalError as exc:
            if (not _sqlite_locked_error(exc)) or attempt >= (max_attempts - 1):
                raise
            if base_sleep <= 0:
                continue
            sleep_for = base_sleep * float(attempt + 1)
            if cap_sleep > 0:
                sleep_for = min(sleep_for, cap_sleep)
            time.sleep(sleep_for)


def _sqlite_executemany_with_retry(
    cur: sqlite3.Cursor,
    sql: str,
    seq_of_params: Iterable[Tuple[Any, ...]],
    *,
    attempts: int = 8,
    sleep_base_sec: float = 0.25,
    sleep_cap_sec: float = 2.0,
) -> None:
    max_attempts = max(1, int(attempts))
    base_sleep = max(0.0, float(sleep_base_sec))
    cap_sleep = max(0.0, float(sleep_cap_sec))
    for attempt in range(max_attempts):
        try:
            cur.executemany(sql, seq_of_params)
            return
        except sqlite3.OperationalError as exc:
            if (not _sqlite_locked_error(exc)) or attempt >= (max_attempts - 1):
                raise
            if base_sleep <= 0:
                continue
            sleep_for = base_sleep * float(attempt + 1)
            if cap_sleep > 0:
                sleep_for = min(sleep_for, cap_sleep)
            time.sleep(sleep_for)


def _facts_lock_wait_sec(default: float = 45.0) -> float:
    val = _env_float("PM_FACTS_LOCK_WAIT_SEC", default)
    if val is None or not math.isfinite(val) or val < 0:
        return float(default)
    return float(val)


def _facts_lock_poll_sec(default: float = 1.0) -> float:
    val = _env_float("PM_FACTS_LOCK_POLL_SEC", default)
    if val is None or not math.isfinite(val) or val <= 0:
        return float(default)
    return max(0.2, min(float(val), 10.0))


def _facts_lock_stale_sec(default: float = 21600.0) -> float:
    val = _env_float("PM_FACTS_LOCK_STALE_SEC", default)
    if val is None or not math.isfinite(val) or val <= 0:
        return float(default)
    return float(val)


def _lock_dir_active(lock_dir: Path, *, stale_sec: Optional[float] = None) -> bool:
    try:
        if not lock_dir.exists():
            return False
    except OSError:
        return False
    pid_path = lock_dir / "pid"
    pid_text = ""
    try:
        pid_text = pid_path.read_text(encoding="utf-8").strip()
    except OSError:
        pid_text = ""
    if pid_text.isdigit():
        try:
            os.kill(int(pid_text), 0)
            return True
        except OSError:
            pass
    else:
        stale_limit = float(stale_sec) if stale_sec is not None and math.isfinite(float(stale_sec)) else _facts_lock_stale_sec()
        try:
            mtime = lock_dir.stat().st_mtime
        except OSError:
            mtime = None
        if mtime is not None and (time.time() - float(mtime)) < max(30.0, stale_limit):
            # Recent lock dir with no pid may still be in-progress initialization.
            return True
    # stale lock dir: best effort cleanup, do not fail caller on cleanup errors.
    try:
        stale_name = f"{lock_dir.name}.stale.{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')}"
        stale_path = lock_dir.with_name(stale_name)
        lock_dir.rename(stale_path)
        shutil.rmtree(stale_path, ignore_errors=True)
    except OSError:
        try:
            shutil.rmtree(lock_dir, ignore_errors=True)
        except OSError:
            return True
    return False


def _facts_lock_active() -> bool:
    return _lock_dir_active(FACTS_MATERIALIZE_LOCK_DIR, stale_sec=_facts_lock_stale_sec())


def _db_writer_lock_active() -> bool:
    return _lock_dir_active(DB_WRITER_LOCK_DIR, stale_sec=_facts_lock_stale_sec())


def _db_writer_lock_wait_sec(default: float = 10.0) -> float:
    val = _env_float("PM_DB_WRITER_LOCK_WAIT_SEC", default)
    if val is None or not math.isfinite(val) or val < 0:
        return float(default)
    return float(val)


def _wait_for_db_writer_lock(tag: str, wait_sec: Optional[float] = None) -> bool:
    max_wait = _db_writer_lock_wait_sec() if wait_sec is None else float(wait_sec)
    if not math.isfinite(max_wait) or max_wait <= 0:
        return True
    poll = _facts_lock_poll_sec()
    waited = 0.0
    while _db_writer_lock_active():
        if waited >= max_wait:
            print(f"[{tag}] db_writer lock active, skip (waited={int(waited)}s)")
            return False
        sleep_for = min(poll, max_wait - waited)
        if sleep_for <= 0:
            break
        time.sleep(sleep_for)
        waited += sleep_for
    if waited > 0:
        print(f"[{tag}] db_writer lock cleared after {int(waited)}s")
    return True


def _wait_for_auto_trade_runtime_lock(tag: str, wait_sec: Optional[float] = None) -> bool:
    max_wait = 0.0 if wait_sec is None else float(wait_sec)
    if not math.isfinite(max_wait) or max_wait < 0:
        max_wait = 0.0
    poll = _facts_lock_poll_sec()
    waited = 0.0
    while _auto_trade_runtime_lock_is_active(cleanup_stale=True):
        if waited >= max_wait:
            print(f"[{tag}] auto_trade runtime active, skip (waited={int(waited)}s)")
            return False
        sleep_for = min(poll, max_wait - waited)
        if sleep_for <= 0:
            break
        time.sleep(sleep_for)
        waited += sleep_for
    if waited > 0:
        print(f"[{tag}] auto_trade runtime cleared after {int(waited)}s")
    return True


def _wait_for_facts_lock(tag: str, wait_sec: Optional[float] = None) -> bool:
    max_wait = _facts_lock_wait_sec() if wait_sec is None else float(wait_sec)
    if not math.isfinite(max_wait) or max_wait <= 0:
        return True
    poll = _facts_lock_poll_sec()
    waited = 0.0
    while _facts_lock_active():
        if waited >= max_wait:
            print(f"[{tag}] facts lock active, skip (waited={int(waited)}s)")
            return False
        sleep_for = min(poll, max_wait - waited)
        if sleep_for <= 0:
            break
        time.sleep(sleep_for)
        waited += sleep_for
    if waited > 0:
        print(f"[{tag}] facts lock cleared after {int(waited)}s")
    return True


def _resolve_order_size(
    price: Optional[float],
    position_ratio: Optional[float],
    notional_override: Optional[float] = None,
) -> Optional[float]:
    if price is None or price <= 0:
        return None
    ratio = float(position_ratio) if position_ratio is not None else 0.0
    bankroll = _env_float("PM_BANKROLL_USDC")
    notional = None
    if bankroll is not None and ratio > 0:
        notional = bankroll * ratio
    elif notional_override is not None and math.isfinite(notional_override) and notional_override > 0:
        notional = notional_override
    else:
        notional = _env_float("PM_ORDER_USDC")
        if notional is None or not math.isfinite(notional) or notional <= 0:
            configured_size = _env_float("PM_ORDER_SIZE")
            if configured_size is None or not math.isfinite(configured_size) or configured_size <= 0:
                # Keep live entry sizing deterministic even when LaunchAgent env
                # lacks PM_ORDER_USDC. The configured min notional defaults to 1u.
                notional = _entry_budget_min_notional_usdc()
    if notional is not None:
        notional = _apply_entry_budget_notional(notional, floor_to_min=True)
        size = notional / float(price)
    else:
        size = _env_float("PM_ORDER_SIZE")
    if size is None:
        return None
    max_notional = _entry_order_notional_cap_usdc()
    if max_notional is not None and max_notional > 0:
        size_cap = max_notional / float(price)
        if size_cap > 0:
            size = min(size, size_cap)
    max_size = _env_float("PM_MAX_ORDER_SIZE")
    if max_size is not None and max_size > 0 and size > max_size:
        size = max_size
    min_size = _env_float("PM_MIN_ORDER_SIZE")
    if min_size is None or not math.isfinite(min_size) or min_size < 0:
        min_size = 0.0
    if _env_bool("PM_ENFORCE_EXCHANGE_MIN_ORDER_SIZE", True):
        # Polymarket CLOB rejects orders below 5 shares. Keep a runtime floor so
        # config drift (e.g. PM_MIN_ORDER_SIZE=1) does not cause repeated rejects.
        exchange_min_size = _env_float("PM_EXCHANGE_MIN_ORDER_SIZE")
        if (
            exchange_min_size is None
            or not math.isfinite(exchange_min_size)
            or exchange_min_size <= 0
        ):
            exchange_min_size = 5.0
        min_size = max(float(min_size), float(exchange_min_size))
    if min_size > 0 and size < min_size:
        size = min_size
    return round(size, 4)


def _clamp_prob01(value: Optional[float]) -> Optional[float]:
    if value is None or not math.isfinite(value):
        return None
    return max(0.0, min(1.0, float(value)))


def _entry_budget_ratio() -> float:
    ratio = _env_float("PM_AUTO_TRADE_ENTRY_BUDGET_RATIO")
    if ratio is None or not math.isfinite(ratio) or ratio <= 0:
        return 1.0
    if ratio > 1.0 + TIME_EDGE_Q_EPS and ratio <= 100.0:
        ratio = float(ratio) / 100.0
    return max(0.0, float(ratio))


def _entry_budget_min_notional_usdc() -> float:
    min_notional = _env_float("PM_AUTO_TRADE_ENTRY_BUDGET_MIN_USDC")
    if min_notional is None or not math.isfinite(min_notional) or min_notional < 0:
        min_notional = _env_float("PM_KELLY_MIN_NOTIONAL_USDC")
    if min_notional is None or not math.isfinite(min_notional) or min_notional < 0:
        min_notional = 1.0
    return max(0.0, float(min_notional))


def _apply_entry_budget_notional(
    notional: Optional[float],
    *,
    floor_to_min: bool,
) -> Optional[float]:
    if notional is None or not math.isfinite(notional) or notional <= 0:
        return None
    adjusted = float(notional) * float(_entry_budget_ratio())
    if floor_to_min:
        adjusted = max(float(adjusted), float(_entry_budget_min_notional_usdc()))
    return max(0.0, float(adjusted))


def _apply_entry_budget_cap_notional(notional_cap: Optional[float]) -> Optional[float]:
    if notional_cap is None or not math.isfinite(notional_cap) or notional_cap <= 0:
        return None
    adjusted = float(notional_cap) * float(_entry_budget_ratio())
    return max(0.0, float(adjusted))


def _entry_order_notional_cap_usdc() -> Optional[float]:
    cap = _env_float("PM_MAX_ORDER_USDC", DEFAULT_MAX_ORDER_NOTIONAL_USDC)
    if cap is None or not math.isfinite(cap) or cap <= 0:
        cap = DEFAULT_MAX_ORDER_NOTIONAL_USDC
    return _apply_entry_budget_cap_notional(float(cap))


def _same_outcome_active_entry_block_from_state(
    *,
    outcome_label: str,
    side_label: str,
    prev_states: Mapping[Tuple[str, str], Mapping[str, Any]],
    rows: Sequence[Mapping[str, Any]],
    open_orders_by_token: Mapping[str, Sequence[Mapping[str, Any]]],
    entry_submit_guard_runtime: Set[Tuple[str, str]],
    entry_submit_guard_meta: Mapping[Tuple[str, str], Mapping[str, Any]],
    ignored_state_keys: Optional[Set[Tuple[str, str]]] = None,
    enabled: bool = True,
    allow_same_side_position: bool = False,
) -> Optional[Dict[str, Any]]:
    if not enabled:
        return None
    outcome_key = str(outcome_label or "").strip()
    side_key = str(side_label or "").strip().upper()
    if not outcome_key or side_key not in {"YES", "NO"}:
        return None
    active_sources: List[Dict[str, Any]] = []
    for guard_outcome, guard_side in sorted(entry_submit_guard_runtime):
        if str(guard_outcome or "").strip() != outcome_key:
            continue
        active_sources.append(
            {
                "source": "run_submit_guard",
                "outcome": outcome_key,
                "side": str(guard_side or "").strip().upper(),
                "guard": dict(entry_submit_guard_meta.get((guard_outcome, guard_side)) or {}),
            }
        )
    for (state_outcome, state_side), state_entry in prev_states.items():
        if str(state_outcome or "").strip() != outcome_key:
            continue
        state_side_key = str(state_side or "").strip().upper()
        if ignored_state_keys and (outcome_key, state_side_key) in ignored_state_keys:
            continue
        state_now = str(state_entry.get("state") or "").strip().lower()
        position_now = to_float(state_entry.get("position_size")) or 0.0
        last_order_id = str(state_entry.get("last_order_id") or "")
        if (
            allow_same_side_position
            and state_side_key == side_key
            and position_now > TIME_EDGE_Q_EPS
            and not (state_now == "entry_pending" and last_order_id)
        ):
            continue
        if state_now in {"entry", "entry_pending"} or position_now > TIME_EDGE_Q_EPS:
            active_sources.append(
                {
                    "source": "local_position_ledger",
                    "outcome": outcome_key,
                    "side": state_side_key,
                    "state": state_now,
                    "position_size": float(position_now),
                    "last_order_id": last_order_id,
                    "last_action": str(state_entry.get("last_action") or ""),
                    "last_action_at": str(state_entry.get("last_action_at") or ""),
                }
            )
    seen_open_orders: Set[Tuple[str, str, str]] = set()
    for row_ref in rows:
        if str(row_ref.get("outcome") or "").strip() != outcome_key:
            continue
        for open_side in ("YES", "NO"):
            token_ref = row_ref.get("yes_token") if open_side == "YES" else row_ref.get("no_token")
            token_key = str(token_ref or "").strip()
            if not token_key:
                continue
            buy_orders = [
                order
                for order in (open_orders_by_token.get(token_key) or [])
                if str(order.get("side") or "").upper() == "BUY"
            ]
            for order in buy_orders:
                order_id = str(order.get("order_id") or order.get("id") or "")
                dedupe_key = (outcome_key, open_side, order_id or token_key)
                if dedupe_key in seen_open_orders:
                    continue
                seen_open_orders.add(dedupe_key)
                active_sources.append(
                    {
                        "source": "open_orders",
                        "outcome": outcome_key,
                        "side": open_side,
                        "token_id": token_key,
                        "order_id": order_id,
                        "created_at": str(order.get("created_at") or ""),
                        "price": to_float(order.get("price")),
                        "size": to_float(order.get("size")),
                    }
                )
    if not active_sources:
        return None
    return {
        "outcome": outcome_key,
        "side": side_key,
        "one_order_per_outcome_enabled": True,
        "active_count": len(active_sources),
        "active_sources": active_sources[:6],
    }


def _candidate_label(candidate: Mapping[str, Any]) -> str:
    for key in ("outcome", "bucket_label", "q_temperature_bucket_label"):
        text = str(candidate.get(key) or "").strip()
        if text:
            return text.lower()
    return ""


def _candidate_prob_from_keys(
    candidate: Mapping[str, Any],
    keys: Sequence[str],
) -> Tuple[Optional[float], str]:
    for key in keys:
        val = _clamp_prob01(to_float(candidate.get(key)))
        if val is not None:
            return val, key
    return None, ""


def _candidate_entry_prob(candidate: Dict[str, Any], price: float) -> Optional[float]:
    side = str(candidate.get("side") or "").strip().upper()
    posterior_family = _is_posterior_settlement_candidate(candidate)
    if posterior_family:
        bucket_prob, bucket_source = _candidate_prob_from_keys(
            candidate,
            (
                "posterior_settlement_candidate_bucket_prob",
                "candidate_bucket_realization_prob",
                "q_temperature_bucket_posterior",
            ),
        )
        if bucket_prob is not None:
            if side == "NO":
                candidate["kelly_q_source"] = f"1-{bucket_source}"
                return max(0.0, min(1.0, 1.0 - float(bucket_prob)))
            candidate["q_entry"] = float(bucket_prob)
            candidate["q_min_bound"] = float(bucket_prob)
            candidate["kelly_q_source"] = bucket_source
            return float(bucket_prob)

        target_label = str(
            candidate.get("target_bucket")
            or candidate.get("posterior_settlement_target_bucket")
            or ""
        ).strip().lower()
        if side != "NO" and target_label and target_label == _candidate_label(candidate):
            target_prob, target_source = _candidate_prob_from_keys(
                candidate,
                ("target_posterior", "posterior_settlement_target_posterior"),
            )
            if target_prob is not None:
                candidate["q_entry"] = float(target_prob)
                candidate["q_min_bound"] = float(target_prob)
                candidate["kelly_q_source"] = target_source
                return float(target_prob)

    if posterior_family:
        fallback_keys: Tuple[str, ...] = (
            "edge_tradeability_bayes_q",
            "q_bayes_posterior",
            "q_entry",
            "q_prob",
            "q_min_bound",
            "q_calibrated",
            "q_round",
            "q_raw",
        )
    else:
        fallback_keys = (
            "edge_tradeability_bayes_q",
            "q_entry",
            "q_prob",
            "q_min_bound",
            "q_bayes_posterior",
            "q_calibrated",
            "q_round",
            "q_raw",
        )
    if side != "NO":
        insert_at = fallback_keys.index("q_calibrated")
        fallback_keys = (
            *fallback_keys[:insert_at],
            "q_temperature_bucket_posterior",
            *fallback_keys[insert_at:],
        )
    for key in fallback_keys:
        val = to_float(candidate.get(key))
        val = _clamp_prob01(val)
        if val is not None:
            candidate["kelly_q_source"] = key
            return val
    ask_val = to_float(candidate.get("ask"))
    edge_min = to_float(candidate.get("edge_min"))
    if edge_min is not None and math.isfinite(edge_min):
        if ask_val is not None and math.isfinite(ask_val):
            val = _clamp_prob01(float(ask_val) + float(edge_min))
            if val is not None:
                candidate["kelly_q_source"] = "ask_plus_edge_min"
                return val
        val = _clamp_prob01(float(price) + float(edge_min))
        if val is not None:
            candidate["kelly_q_source"] = "price_plus_edge_min"
            return val
    return None


def _kelly_ignore_price_edge(candidate: Mapping[str, Any]) -> bool:
    return bool(
        _env_bool(
            "PM_KELLY_IGNORE_PRICE_EDGE",
            _is_posterior_settlement_candidate(candidate),
        )
    )


def _kelly_ratio_env(key: str, default: float) -> float:
    val = _env_float(key)
    if val is None or not math.isfinite(val):
        val = default
    val = float(val)
    if val > 1.0 + TIME_EDGE_Q_EPS and val <= 100.0:
        val /= 100.0
    if val < 0.0:
        val = 0.0
    return float(val)


def _env_float_first(keys: Sequence[str], default: Optional[float] = None) -> Optional[float]:
    for key in keys:
        val = _env_float(str(key))
        if val is not None and math.isfinite(val):
            return float(val)
    return float(default) if default is not None else None


def _kelly_ratio_env_any(keys: Sequence[str], default: float) -> float:
    val = _env_float_first(keys, default)
    if val is None or not math.isfinite(val):
        val = default
    val = float(val)
    if val > 1.0 + TIME_EDGE_Q_EPS and val <= 100.0:
        val /= 100.0
    if val < 0.0:
        val = 0.0
    return float(val)


_TARGET_REALIZATION_FACT_PLAN_CACHE: Dict[
    Tuple[str, str, str],
    Tuple[float, Dict[Tuple[str, str], Dict[str, Any]], Dict[str, Any]],
] = {}


def _target_realization_side_notional_cap_usdc(
    side: str,
    leg: Optional[Mapping[str, Any]] = None,
    plan: Optional[Mapping[str, Any]] = None,
) -> Optional[float]:
    leg_ref = leg if isinstance(leg, Mapping) else {}
    plan_ref = plan if isinstance(plan, Mapping) else {}
    if str(plan_ref.get("version") or "").strip() != "strong_posterior_three_leg_strategy_v2":
        return None
    cap = to_float(leg_ref.get("target_notional_cap_usdc"))
    if cap is None:
        cap = to_float(leg_ref.get("max_notional_usdc"))
    if cap is None or not math.isfinite(float(cap)) or float(cap) <= 0:
        return None
    return float(cap)


_STRONG_POSTERIOR_LEG_SIDES = {
    "top_yes_wave": "YES",
    "second_yes": "YES",
    "strongly_excluded_no": "NO",
}


def _sanitize_strong_posterior_strategy_legs(plan: Dict[str, Any]) -> Dict[str, Any]:
    """Fail closed unless the committed plan is exactly the current three-leg contract."""
    if not isinstance(plan, dict):
        return {}
    if str(plan.get("version") or "").strip() != "strong_posterior_three_leg_strategy_v2":
        plan["legs"] = []
        plan["strategy_plan_block_reason"] = "retired_target_realization_plan_version"
        return plan
    raw_legs = plan.get("legs")
    if not isinstance(raw_legs, list):
        plan["legs"] = []
        plan["strategy_plan_block_reason"] = "strong_posterior_three_leg_missing"
        return plan
    cleaned: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for raw_leg in raw_legs:
        if not isinstance(raw_leg, Mapping):
            continue
        leg = dict(raw_leg)
        role = str(leg.get("role") or leg.get("strategy_leg") or "").strip()
        side = str(leg.get("side") or "").strip().upper()
        bucket = str(leg.get("bucket") or leg.get("outcome") or "").strip()
        action = str(leg.get("action") or "").strip().lower()
        empty_hold_no = role == "strongly_excluded_no" and side == "NO" and action == "hold" and not bucket
        if (not bucket and not empty_hold_no) or role in seen or _STRONG_POSTERIOR_LEG_SIDES.get(role) != side:
            continue
        if action not in {"add", "hold"}:
            continue
        leg["role"] = role
        leg["strategy_leg"] = role
        seen.add(role)
        cleaned.append(leg)
    plan["legs"] = cleaned
    if set(_STRONG_POSTERIOR_LEG_SIDES) != seen:
        plan["strategy_plan_block_reason"] = "strong_posterior_three_leg_contract_incomplete"
    return plan


def _target_realization_plan_legs(
    plan: Mapping[str, Any],
) -> Dict[Tuple[str, str], Dict[str, Any]]:
    sanitized = _sanitize_strong_posterior_strategy_legs(dict(plan))
    if sanitized.get("strategy_plan_block_reason"):
        return {}
    out: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for leg in sanitized.get("legs") or []:
        if isinstance(leg, Mapping) and str(leg.get("bucket") or "").strip():
            out[(str(leg.get("bucket") or "").strip(), str(leg.get("side") or "").strip().upper())] = dict(leg)
    return out


def _target_realization_plan_blocks_yes_follow(plan: Mapping[str, Any]) -> bool:
    if not isinstance(plan, Mapping):
        return False
    if plan.get("temperature_path_trade_follow_block_yes") is True:
        return True
    allowed = plan.get("temperature_path_trade_follow_allowed")
    return allowed is False


def _target_realization_path_distribution_bucket_fields(
    path_distribution: Mapping[str, Any],
) -> Dict[str, Dict[str, Any]]:
    if not isinstance(path_distribution, Mapping):
        return {}
    out: Dict[str, Dict[str, Any]] = {}

    def add(label: Any, *, posterior: Any = None, path_probability: Any = None, source: Any = None) -> None:
        label_text = str(label or "").strip()
        if not label_text:
            return
        entry = out.setdefault(label_text, {})
        posterior_val = _clamp_prob01(to_float(posterior))
        if posterior_val is not None:
            entry["posterior"] = float(posterior_val)
            entry["posterior_source"] = "temperature_path_distribution"
        path_val = _clamp_prob01(to_float(path_probability))
        entry["path_probability_present"] = True
        entry["path_probability_source"] = str(
            source
            or entry.get("path_probability_source")
            or "temperature_path_distribution"
        )
        if path_val is not None:
            entry["path_probability"] = float(path_val)

    bucket_distribution = path_distribution.get("bucket_distribution")
    if isinstance(bucket_distribution, list):
        for bucket in bucket_distribution:
            if not isinstance(bucket, Mapping):
                continue
            add(
                bucket.get("bucket"),
                posterior=bucket.get("posterior"),
                path_probability=bucket.get("path_probability"),
                source=bucket.get("path_probability_source"),
            )
    target = path_distribution.get("target")
    if isinstance(target, Mapping):
        add(
            target.get("bucket"),
            posterior=target.get("posterior"),
            path_probability=target.get("path_probability"),
            source=target.get("path_probability_source"),
        )
    second = path_distribution.get("second_target")
    if isinstance(second, Mapping):
        add(
            second.get("bucket"),
            posterior=second.get("posterior"),
            path_probability=second.get("path_probability"),
            source=second.get("path_probability_source"),
        )
    add(
        path_distribution.get("target_bucket"),
        posterior=path_distribution.get("target_bucket_posterior"),
        path_probability=path_distribution.get("target_bucket_path_probability"),
        source=path_distribution.get("target_bucket_path_probability_source"),
    )
    add(
        path_distribution.get("second_target_bucket"),
        posterior=path_distribution.get("second_target_bucket_posterior"),
        path_probability=path_distribution.get("second_target_bucket_path_probability"),
        source=path_distribution.get("second_target_bucket_path_probability_source"),
    )
    return out


def _align_target_realization_plan_with_path_distribution(
    plan: Dict[str, Any],
    payload: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    if not isinstance(plan, dict) or not isinstance(payload, Mapping):
        return plan
    path_distribution = payload.get("temperature_path_distribution")
    if not isinstance(path_distribution, Mapping):
        summary = payload.get("chengdu_intraday_summary")
        if isinstance(summary, Mapping):
            path_distribution = summary.get("temperature_path_distribution")
    if not isinstance(path_distribution, Mapping):
        return plan
    by_bucket = _target_realization_path_distribution_bucket_fields(path_distribution)
    if not by_bucket:
        return plan

    posterior_field_markers: List[str] = []
    for container in (
        payload,
        payload.get("target_bucket_selection"),
        payload.get("posterior_target_bucket_selection"),
        plan,
    ):
        if not isinstance(container, Mapping):
            continue
        for key in (
            "target_probability_field",
            "target_bucket_probability_field",
            "target_bucket_probability_source",
            "target_bucket_selection_source",
            "selection_priority",
        ):
            value = container.get(key)
            if value not in (None, ""):
                posterior_field_markers.append(str(value))
    preserve_distribution_posterior = any(
        "event_fact_latest.distribution" in marker
        or "q_temperature_bucket_posterior" in marker
        for marker in posterior_field_markers
    )

    target_bucket = str(plan.get("target_bucket") or path_distribution.get("target_bucket") or "").strip()
    second_bucket = str(plan.get("second_target_bucket") or path_distribution.get("second_target_bucket") or "").strip()
    target_fields = by_bucket.get(target_bucket) or {}
    second_fields = by_bucket.get(second_bucket) or {}
    if not preserve_distribution_posterior and target_fields.get("posterior") is not None:
        plan["target_posterior"] = float(target_fields["posterior"])
        plan["target_posterior_source"] = "temperature_path_distribution"
    if not preserve_distribution_posterior and second_fields.get("posterior") is not None:
        plan["second_target_posterior"] = float(second_fields["posterior"])
        plan["second_target_posterior_source"] = "temperature_path_distribution"

    legs = plan.get("legs")
    if isinstance(legs, list):
        aligned_legs: List[Any] = []
        for raw_leg in legs:
            if not isinstance(raw_leg, Mapping):
                aligned_legs.append(raw_leg)
                continue
            leg = dict(raw_leg)
            bucket = str(leg.get("bucket") or leg.get("outcome") or "").strip()
            side = str(leg.get("side") or "").strip().upper()
            fields = by_bucket.get(bucket) or {}
            posterior_val = _clamp_prob01(to_float(fields.get("posterior")))
            path_val = _clamp_prob01(to_float(fields.get("path_probability")))
            if posterior_val is not None and not preserve_distribution_posterior:
                leg["posterior"] = float(posterior_val)
                leg["posterior_source"] = "temperature_path_distribution"
                if side == "NO":
                    leg["prob_for_size"] = max(0.0, min(1.0, 1.0 - float(posterior_val)))
                else:
                    leg["prob_for_size"] = float(posterior_val)
            if path_val is not None:
                leg["target_realization_path_probability"] = float(path_val)
                leg["target_realization_path_probability_source"] = str(
                    fields.get("path_probability_source") or "temperature_path_distribution"
                )
                leg["target_realization_reliability"] = (
                    max(0.0, min(1.0, 1.0 - float(path_val)))
                    if side == "NO"
                    else float(path_val)
                )
                leg["target_realization_reliability_source"] = (
                    "temperature_path_distribution_not_reach_probability"
                    if side == "NO"
                    else "temperature_path_distribution_reach_probability"
                )
            elif (
                side == "YES"
                and str(leg.get("role") or "") in {"target_yes", "second_target_yes"}
                and fields.get("path_probability_present") is True
            ):
                leg["target_realization_path_probability"] = None
                leg["target_realization_path_probability_source"] = str(
                    fields.get("path_probability_source") or "temperature_path_distribution"
                )
                leg["target_realization_reliability"] = 0.0
                leg["target_realization_reliability_source"] = (
                    "temperature_path_distribution_path_probability_missing"
                )
            aligned_legs.append(leg)
        plan["legs"] = aligned_legs

    risk = plan.get("ui_risk_explanation")
    if not isinstance(risk, Mapping):
        risk = plan.get("risk_explanation")
    if isinstance(risk, Mapping):
        risk_out = dict(risk)
    else:
        risk_out = {
            "available": True,
            "version": "target_realization_ui_risk_explanation_v1",
            "source": "target_realization_capital_plan",
        }
    if target_bucket:
        risk_out["target_bucket"] = target_bucket
    if second_bucket:
        risk_out["second_target_bucket"] = second_bucket
    if not preserve_distribution_posterior and target_fields.get("posterior") is not None:
        risk_out["target_posterior"] = float(target_fields["posterior"])
    if not preserve_distribution_posterior and second_fields.get("posterior") is not None:
        risk_out["second_target_posterior"] = float(second_fields["posterior"])
    if target_fields.get("path_probability") is not None:
        risk_out["target_realization_probability"] = float(target_fields["path_probability"])
    elif target_fields.get("path_probability_present") is True:
        risk_out["target_realization_probability"] = None
    if second_fields.get("path_probability") is not None:
        risk_out["second_target_realization_probability"] = float(second_fields["path_probability"])
    elif second_fields.get("path_probability_present") is True:
        risk_out["second_target_realization_probability"] = None
    for key in ("freshness", "reliability", "error_band", "hard_source_state", "trade_follow", "risk_codes"):
        val = path_distribution.get(key)
        if val not in (None, ""):
            risk_out[key] = val
    risk_text = str(path_distribution.get("risk_explanation") or "").strip()
    if risk_text:
        risk_out["text"] = risk_text
    plan["ui_risk_explanation"] = risk_out
    plan["risk_explanation"] = risk_out
    if isinstance(path_distribution.get("trade_follow"), Mapping):
        trade_follow = path_distribution.get("trade_follow") or {}
        plan["temperature_path_trade_follow_allowed"] = trade_follow.get("allowed")
        plan["temperature_path_trade_follow_reason"] = str(trade_follow.get("reason") or "")
        plan["temperature_path_trade_follow_block_yes"] = trade_follow.get("allowed") is False
    plan["target_realization_path_distribution_aligned"] = True
    return plan


def _apply_temperature_path_trade_follow_gate_to_plan(
    plan: Dict[str, Any],
    payload: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    if not isinstance(plan, dict):
        return {}
    blocked = _target_realization_plan_blocks_yes_follow(plan)
    reason = str(plan.get("temperature_path_trade_follow_reason") or "").strip()
    if not blocked and isinstance(payload, Mapping):
        blocked, reason = _temperature_path_trade_follow_gate(payload)
    if not blocked:
        return plan
    plan["temperature_path_trade_follow_allowed"] = False
    plan["temperature_path_trade_follow_block_yes"] = True
    plan["temperature_path_trade_follow_reason"] = reason
    legs = plan.get("legs")
    if isinstance(legs, list):
        cleaned_legs: List[Any] = []
        for raw_leg in legs:
            if not isinstance(raw_leg, dict):
                cleaned_legs.append(raw_leg)
                continue
            leg = dict(raw_leg)
            side = str(leg.get("side") or "").strip().upper()
            role = str(leg.get("role") or "").strip()
            if side == "YES" and role in {"target_yes", "second_target_yes"}:
                leg["action"] = "hold"
                leg["action_label"] = "路径门控禁止跟随"
                leg["block_reason"] = TEMPERATURE_PATH_TRADE_FOLLOW_BLOCK_REASON
                current_notional = to_float(leg.get("current_notional"))
                if current_notional is not None and math.isfinite(current_notional):
                    leg["target_notional"] = float(current_notional)
                else:
                    leg["target_notional"] = 0.0
                price_val = to_float(leg.get("price"))
                if price_val is not None and math.isfinite(price_val) and price_val > TIME_EDGE_Q_EPS:
                    leg["target_size"] = float(leg.get("target_notional") or 0.0) / float(price_val)
                leg["delta_notional"] = 0.0
                leg["delta_size"] = 0.0
                leg["target_realization_trade_follow_allowed"] = False
                leg["target_realization_trade_follow_reason"] = reason
                leg["temperature_path_trade_follow_allowed"] = False
                leg["temperature_path_trade_follow_reason"] = reason
                leg["temperature_path_trade_follow_block_yes"] = True
                leg["temperature_path_trade_follow_gate_source"] = "temperature_path_distribution.trade_follow"
            cleaned_legs.append(leg)
        plan["legs"] = cleaned_legs
    if not str(plan.get("summary") or "").startswith("路径概率门控禁止 YES 跟随"):
        plan["summary"] = (
            f"路径概率门控禁止 YES 跟随：{reason or TEMPERATURE_PATH_TRADE_FOLLOW_BLOCK_REASON}；"
            "目标桶/资金第二腿只展示观察，不新增 YES。"
        )
    return plan


def _target_realization_plan_source_texts(
    plan: Mapping[str, Any],
    payload: Optional[Mapping[str, Any]] = None,
) -> List[str]:
    texts: List[str] = []

    def add(value: Any) -> None:
        text = str(value or "").strip()
        if text:
            texts.append(text)

    containers: List[Mapping[str, Any]] = []
    if isinstance(plan, Mapping):
        containers.append(plan)
        for key in ("posterior_target_bucket_selection", "target_bucket_selection"):
            nested = plan.get(key)
            if isinstance(nested, Mapping):
                containers.append(nested)
    if isinstance(payload, Mapping):
        for key in ("posterior_target_bucket_selection", "target_bucket_selection"):
            nested = payload.get(key)
            if isinstance(nested, Mapping):
                containers.append(nested)
        ssot_fact = payload.get("posterior_ssot_fact")
        if isinstance(ssot_fact, Mapping):
            containers.append(ssot_fact)

    for container in containers:
        for key in (
            "target_bucket_selection_source",
            "target_bucket_source",
            "target_probability_field",
            "target_bucket_probability_field",
            "ssot_source",
            "source",
            "schema",
        ):
            add(container.get(key))
    return texts


def _target_realization_plan_uses_posterior_ssot(
    plan: Mapping[str, Any],
    payload: Optional[Mapping[str, Any]] = None,
) -> bool:
    if not isinstance(plan, Mapping):
        return False
    source_text = " ".join(_target_realization_plan_source_texts(plan, payload)).lower()
    if "posterior_ssot_fact" in source_text:
        return True
    if isinstance(payload, Mapping):
        ssot_fact = payload.get("posterior_ssot_fact")
        if isinstance(ssot_fact, Mapping):
            ssot_state = str(ssot_fact.get("state") or "").strip().lower()
            if ssot_state and ssot_state not in {"available", "ready", "ok"}:
                return False
            plan_bucket = str(plan.get("target_bucket") or "").strip()
            ssot_bucket = str(
                ssot_fact.get("target_bucket")
                or ssot_fact.get("top_bucket")
                or ssot_fact.get("selected_bucket")
                or ""
            ).strip()
            if plan_bucket and ssot_bucket and plan_bucket == ssot_bucket:
                return True
    return False


def _target_realization_plan_uses_hard_source_target(plan: Mapping[str, Any]) -> bool:
    if not isinstance(plan, Mapping):
        return False
    for text in _target_realization_plan_source_texts(plan):
        lower = text.lower()
        if lower.startswith("hard_source_") or "hard_source_direct" in lower:
            return True
    return False


def _target_realization_plan_is_executable_ssot(
    plan: Mapping[str, Any],
    payload: Optional[Mapping[str, Any]] = None,
) -> bool:
    return bool(
        isinstance(plan, Mapping)
        and str(plan.get("version") or "").strip() == "strong_posterior_three_leg_strategy_v2"
        and _target_realization_plan_uses_posterior_ssot(plan, payload)
        and not _sanitize_strong_posterior_strategy_legs(dict(plan)).get("strategy_plan_block_reason")
    )


def _target_realization_plan_decision_ssot(
    plan: Mapping[str, Any],
    payload: Optional[Mapping[str, Any]] = None,
) -> str:
    if _target_realization_plan_is_executable_ssot(plan, payload):
        return "posterior_ssot_fact"
    return ""


def _target_realization_plan_from_snapshot_payload(
    payload: Mapping[str, Any],
    *,
    slug_key: str,
    event_key: str,
) -> Optional[Dict[str, Any]]:
    facts = payload.get("facts") if isinstance(payload, Mapping) else None
    items = facts.get("items") if isinstance(facts, Mapping) else None
    if not isinstance(items, list):
        return None
    for item in items:
        if not isinstance(item, Mapping):
            continue
        if str(item.get("slug") or "").strip() != slug_key:
            continue
        if str(item.get("event_date") or "").strip().split("T", 1)[0] != event_key:
            continue
        plan = item.get("target_realization_capital_plan")
        if isinstance(plan, Mapping) and plan.get("ok") is not False:
            if not _target_realization_plan_is_executable_ssot(plan, item):
                return None
            aligned = _align_target_realization_plan_with_path_distribution(dict(plan), item)
            gated = _apply_temperature_path_trade_follow_gate_to_plan(aligned, item)
            sanitized = _sanitize_strong_posterior_strategy_legs(gated)
            return _merge_target_realization_plan_ssot_context(sanitized, item)
        return None
    return None


def _merge_target_realization_plan_ssot_context(
    plan: Dict[str, Any],
    payload: Mapping[str, Any],
) -> Dict[str, Any]:
    if not isinstance(plan, dict) or not isinstance(payload, Mapping):
        return plan
    posterior_ssot_fact = payload.get("posterior_ssot_fact")
    if isinstance(posterior_ssot_fact, Mapping):
        plan.setdefault("posterior_ssot_fact", dict(posterior_ssot_fact))
        ssot_bucket = str(
            posterior_ssot_fact.get("target_bucket")
            or posterior_ssot_fact.get("top_bucket")
            or posterior_ssot_fact.get("selected_bucket")
            or ""
        ).strip()
        if ssot_bucket and ssot_bucket == str(plan.get("target_bucket") or "").strip():
            plan.setdefault("target_bucket_selection_source", "posterior_ssot_fact.top_bucket")
            plan.setdefault("target_probability_field", "posterior_ssot_fact.target_probability")
    path_distribution = payload.get("temperature_path_distribution")
    if not isinstance(path_distribution, Mapping):
        summary = payload.get("chengdu_intraday_summary")
        if isinstance(summary, Mapping):
            path_distribution = summary.get("temperature_path_distribution")
    if isinstance(path_distribution, Mapping):
        plan.setdefault("temperature_path_distribution", dict(path_distribution))
    switch_context = payload.get("target_switch_context")
    if not isinstance(switch_context, Mapping):
        selection = payload.get("target_bucket_selection")
        if isinstance(selection, Mapping):
            switch_context = selection.get("target_switch_context")
    if isinstance(switch_context, Mapping):
        switch_context_dict = dict(switch_context)
        plan.setdefault("target_switch_context", switch_context_dict)
        impact = switch_context_dict.get("trajectory_momentum_impact")
        if isinstance(impact, Mapping):
            plan.setdefault("trajectory_momentum_impact", dict(impact))
    impact = payload.get("trajectory_momentum_impact")
    if isinstance(impact, Mapping):
        plan.setdefault("trajectory_momentum_impact", dict(impact))
    selection = payload.get("target_bucket_selection")
    if isinstance(selection, Mapping):
        plan.setdefault("target_bucket_selection", dict(selection))
    posterior_selection = payload.get("posterior_target_bucket_selection")
    if isinstance(posterior_selection, Mapping):
        plan.setdefault("posterior_target_bucket_selection", dict(posterior_selection))
    return plan


def _load_target_realization_local_fact_plan(
    slug_key: str,
    event_key: str,
) -> Optional[Dict[str, Any]]:
    if not DB_PATH.exists():
        return None
    try:
        conn = sqlite3.connect(f"file:{DB_PATH}?mode=ro", uri=True, timeout=0.5)
        conn.row_factory = sqlite3.Row
        try:
            conn.execute("PRAGMA query_only=ON")
            conn.execute("PRAGMA busy_timeout=500")
            row = conn.execute(
                """
                SELECT h.fact_json, h.fact_as_of, h.composer_version, h.created_at
                FROM event_fact_latest l
                JOIN event_fact_history h ON h.id = l.fact_id
                WHERE l.slug = ? AND l.event_date = ?
                LIMIT 1
                """,
                (slug_key, event_key),
            ).fetchone()
        finally:
            conn.close()
    except Exception:
        return None
    if row is None:
        return None
    try:
        payload = json.loads(row["fact_json"] or "{}")
    except Exception:
        return None
    if not isinstance(payload, Mapping):
        return None
    plan = payload.get("target_realization_capital_plan")
    if not isinstance(plan, Mapping) or plan.get("ok") is False:
        return None
    if not _target_realization_plan_is_executable_ssot(plan, payload):
        return None
    out = dict(plan)
    out = _sanitize_strong_posterior_strategy_legs(out)
    out = _merge_target_realization_plan_ssot_context(out, payload)
    out.setdefault("source", "event_fact_latest")
    out["ssot_load_source"] = "event_fact_latest_local"
    out["ssot_fact_as_of"] = str(row["fact_as_of"] or "")
    out["ssot_fact_composer_version"] = str(row["composer_version"] or "")
    out["ssot_fact_created_at"] = str(row["created_at"] or "")
    return out


def _load_target_realization_fact_plan(
    slug: str,
    event_date: str,
) -> Tuple[Dict[Tuple[str, str], Dict[str, Any]], Dict[str, Any]]:
    slug_key = str(slug or "").strip()
    event_key = str(event_date or "").strip().split("T", 1)[0]
    if not slug_key or not event_key:
        return {}, {}
    now_mono = time.monotonic()
    try:
        db_selector = str(Path(DB_PATH).resolve())
    except Exception:
        db_selector = str(DB_PATH)
    cache_key = (slug_key, event_key, f"event_fact_latest:{db_selector}")
    cached = _TARGET_REALIZATION_FACT_PLAN_CACHE.get(cache_key)
    cache_ttl = _env_float("PM_TARGET_REALIZATION_SSOT_CACHE_SEC")
    if cache_ttl is None or not math.isfinite(cache_ttl) or cache_ttl < 0:
        cache_ttl = 2.0
    if cached and now_mono - float(cached[0]) <= float(cache_ttl):
        return dict(cached[1]), dict(cached[2])
    plan = _load_target_realization_local_fact_plan(slug_key, event_key)
    if not isinstance(plan, Mapping):
        return {}, {}
    out = _target_realization_plan_legs(plan)
    _TARGET_REALIZATION_FACT_PLAN_CACHE[cache_key] = (now_mono, dict(out), dict(plan))
    return out, dict(plan)


def _merge_target_realization_probability_fields_from_ssot_leg(
    out: Dict[str, Any],
    ssot_leg: Mapping[str, Any],
) -> Dict[str, Any]:
    path_probability_val = _clamp_prob01(
        to_float(ssot_leg.get("target_realization_path_probability"))
    )
    rel_val = _clamp_prob01(to_float(ssot_leg.get("target_realization_reliability")))
    if path_probability_val is not None:
        out["target_realization_path_probability"] = float(path_probability_val)
        out["target_realization_path_p_reach_yes"] = float(path_probability_val)
        out["target_realization_path_probability_source"] = str(
            ssot_leg.get("target_realization_path_probability_source")
            or "ui_snapshot_target_realization_capital_plan"
        )
    if rel_val is not None:
        out["target_realization_reliability"] = float(rel_val)
        out["kelly_realization_strength"] = float(rel_val)
        out["target_realization_reliability_source"] = str(
            ssot_leg.get("target_realization_reliability_source")
            or "ui_snapshot_target_realization_capital_plan"
        )
    return out


def _copy_target_realization_plan_context_to_details(
    details: Dict[str, Any],
    ssot_plan: Mapping[str, Any],
) -> Dict[str, Any]:
    if not isinstance(details, dict) or not isinstance(ssot_plan, Mapping):
        return details
    if ssot_plan.get("ok") is False:
        return details
    plan_dict = dict(ssot_plan)
    decision_ssot = _target_realization_plan_decision_ssot(ssot_plan)
    details["target_realization_capital_plan"] = plan_dict
    details["target_realization_capital_plan_version"] = str(
        ssot_plan.get("version") or "target_realization_capital_plan_v2"
    )
    details["target_realization_capital_plan_source"] = str(
        ssot_plan.get("ssot_load_source")
        or ssot_plan.get("source")
        or "ui_snapshot_ssot"
    )
    if decision_ssot:
        details["decision_ssot"] = decision_ssot
        details["posterior_ssot_fact_used"] = decision_ssot == "posterior_ssot_fact"
        if decision_ssot == "posterior_ssot_fact":
            details["target_probability_field"] = "posterior_ssot_fact.target_probability"
    target_bucket = str(ssot_plan.get("target_bucket") or "").strip()
    second_bucket = str(ssot_plan.get("second_target_bucket") or "").strip()
    target_posterior = _clamp_prob01(to_float(ssot_plan.get("target_posterior")))
    second_posterior = _clamp_prob01(to_float(ssot_plan.get("second_target_posterior")))
    if target_bucket:
        details["capital_plan_target_bucket"] = target_bucket
        details["target_bucket"] = target_bucket
        details["ssot_target_bucket"] = target_bucket
        details.setdefault("new_target_bucket", target_bucket)
    if second_bucket:
        details["capital_plan_second_target_bucket"] = second_bucket
        details["second_target_bucket"] = second_bucket
    if target_posterior is not None:
        details["capital_plan_target_posterior"] = float(target_posterior)
        details["target_posterior"] = float(target_posterior)
        details["posterior_settlement_target_posterior"] = float(target_posterior)
    if second_posterior is not None:
        details["capital_plan_second_target_posterior"] = float(second_posterior)
        details["second_target_posterior"] = float(second_posterior)
        details["posterior_settlement_second_target_posterior"] = float(second_posterior)
    for key in (
        "target_switch_context",
        "trajectory_momentum_impact",
        "temperature_path_distribution",
        "target_bucket_selection",
        "posterior_target_bucket_selection",
        "buy_new_leg",
        "buy_new_legs",
        "sell_old_leg",
        "sell_old_legs",
        "buy_old_reverse_leg",
        "buy_old_reverse_legs",
        "sell_old_buy_new_legs",
        "active_position_legs",
    ):
        value = ssot_plan.get(key)
        if isinstance(value, Mapping):
            details[key] = dict(value)
        elif isinstance(value, list):
            details[key] = [dict(item) if isinstance(item, Mapping) else item for item in value]
        elif value is not None:
            details[key] = value
    switch_context = details.get("target_switch_context")
    if isinstance(switch_context, Mapping):
        impact = switch_context.get("trajectory_momentum_impact")
        if isinstance(impact, Mapping):
            details["trajectory_momentum_impact"] = dict(impact)
    if _is_posterior_target_direct_candidate(details):
        details = _apply_posterior_target_direct_snapshot_protection(details)
    return details


def _kelly_near_market_day(candidate: Mapping[str, Any]) -> Tuple[str, Optional[int]]:
    raw_days = to_float(candidate.get("days_to_event"))
    if raw_days is None or not math.isfinite(raw_days):
        event_text = str(
            candidate.get("event_date")
            or candidate.get("event_date_key")
            or candidate.get("market_event_date")
            or ""
        ).strip()[:10]
        run_text = str(
            candidate.get("run_date")
            or candidate.get("run_date_key")
            or candidate.get("as_of_date")
            or ""
        ).strip()[:10]
        if event_text and run_text:
            try:
                event_day = datetime.strptime(event_text, "%Y-%m-%d").date()
                run_day = datetime.strptime(run_text, "%Y-%m-%d").date()
                raw_days = float((event_day - run_day).days)
            except Exception:
                raw_days = None
        if raw_days is None or not math.isfinite(raw_days):
            return "unknown", None
    day_idx = int(round(float(raw_days)))
    if day_idx <= 0:
        return "today", 0
    if day_idx == 1:
        return "tomorrow", 1
    if day_idx == 2:
        return "day_after", 2
    return "outside_near_three", int(day_idx)


def _kelly_market_day_ratio(day: str) -> float:
    weights = {
        "today": _kelly_ratio_env_any(("PM_TARGET_REALIZATION_TODAY_RATIO", "PM_KELLY_MARKET_TODAY_RATIO"), 0.60),
        "tomorrow": _kelly_ratio_env_any(("PM_TARGET_REALIZATION_TOMORROW_RATIO", "PM_KELLY_MARKET_TOMORROW_RATIO"), 0.30),
        "day_after": _kelly_ratio_env_any(("PM_TARGET_REALIZATION_DAY_AFTER_RATIO", "PM_KELLY_MARKET_DAY_AFTER_RATIO"), 0.10),
    }
    total = sum(float(v) for v in weights.values() if math.isfinite(float(v)))
    if total <= TIME_EDGE_Q_EPS:
        return 0.0
    return max(0.0, float(weights.get(day, 0.0))) / float(total)


def _kelly_side_ratio(candidate: Mapping[str, Any]) -> float:
    yes_ratio = _kelly_ratio_env_any(("PM_TARGET_REALIZATION_YES_RATIO", "PM_KELLY_YES_RATIO"), 0.20)
    no_ratio = _kelly_ratio_env_any(("PM_TARGET_REALIZATION_NO_RATIO", "PM_KELLY_NO_RATIO"), 0.80)
    total = float(yes_ratio) + float(no_ratio)
    if total <= TIME_EDGE_Q_EPS:
        return 0.0
    side = str(candidate.get("side") or "").strip().upper()
    raw = float(no_ratio) if side == "NO" else float(yes_ratio)
    return max(0.0, raw) / float(total)


def _kelly_realization_strength(candidate: Mapping[str, Any]) -> float:
    for key in (
        "target_realization_path_p_reach_yes",
        "target_realization_path_p_reach",
        "target_realization_signal_confidence_yes",
        "target_realization_signal_confidence",
        "target_bucket_realization_reliability",
        "target_realization_reliability",
        "new_target_realization_reliability",
        "posterior_settlement_size_scale",
    ):
        val = _clamp_prob01(to_float(candidate.get(key)))
        if val is not None:
            return float(val)
    return 1.0


def _kelly_near_three_target_notional(
    candidate: Dict[str, Any],
    *,
    bankroll: Optional[float],
    kelly_effective: float,
) -> Optional[float]:
    if bankroll is None or not math.isfinite(bankroll) or bankroll <= TIME_EDGE_Q_EPS:
        candidate["kelly_portfolio_mode"] = "base_scaled_no_bankroll"
        return None
    day, day_idx = _kelly_near_market_day(candidate)
    reserve_ratio = _kelly_ratio_env_any(("PM_TARGET_REALIZATION_RESERVE_RATIO", "PM_KELLY_RESERVE_RATIO"), 0.20)
    reserve_abs = _env_float_first(("PM_TARGET_REALIZATION_RESERVE_USDC", "PM_KELLY_RESERVE_USDC"))
    reserve_by_ratio = float(bankroll) * float(reserve_ratio)
    reserve_usdc = reserve_by_ratio
    if reserve_abs is not None and math.isfinite(reserve_abs) and reserve_abs > 0:
        reserve_usdc = max(float(reserve_usdc), float(reserve_abs))
    reserve_usdc = max(0.0, min(float(bankroll), float(reserve_usdc)))
    available_usdc = max(0.0, float(bankroll) - float(reserve_usdc))
    market_ratio = _kelly_market_day_ratio(day)
    side_ratio = _kelly_side_ratio(candidate)
    market_budget = float(available_usdc) * float(market_ratio)
    side_budget = float(market_budget) * float(side_ratio)
    target_notional = float(side_budget) * float(kelly_effective)
    candidate["kelly_portfolio_mode"] = "near_three_market_allocation"
    candidate["target_realization_capital_plan_version"] = "target_realization_capital_plan_v2"
    candidate["target_realization_capital_plan_source"] = "auto_trade_execution_sizing"
    candidate["target_realization_plan_notional"] = float(target_notional)
    candidate["target_realization_plan_notional_source"] = "near_three_market_allocation"
    candidate["kelly_bankroll_usdc"] = float(bankroll)
    candidate["kelly_reserve_ratio"] = float(reserve_ratio)
    candidate["kelly_reserve_usdc"] = float(reserve_usdc)
    candidate["kelly_available_usdc"] = float(available_usdc)
    candidate["kelly_market_day"] = str(day)
    if day_idx is not None:
        candidate["kelly_market_day_index"] = float(day_idx)
    candidate["kelly_market_day_ratio"] = float(market_ratio)
    candidate["kelly_market_budget_usdc"] = float(market_budget)
    candidate["kelly_side_ratio"] = float(side_ratio)
    candidate["kelly_side_budget_usdc"] = float(side_budget)
    candidate["kelly_target_notional_before_caps"] = float(target_notional)
    if day not in {"today", "tomorrow", "day_after"}:
        candidate["kelly_reason"] = f"near_three_market_out_of_scope:{day}"
        return 0.0
    return float(target_notional)


def _apply_kelly_size_in_place(
    candidate: Dict[str, Any],
    *,
    allow_apply: bool,
) -> None:
    if not isinstance(candidate, dict):
        return
    candidate["kelly_enabled"] = bool(_env_bool("PM_KELLY_ENABLED", True))
    candidate["kelly_applied"] = False
    candidate["kelly_blocked"] = False
    candidate["kelly_reason"] = ""

    enabled = bool(candidate.get("kelly_enabled"))
    if not enabled:
        candidate["kelly_reason"] = "kelly_disabled"
        return
    if not allow_apply:
        candidate["kelly_reason"] = "topup_skip"
        return
    price = to_float(candidate.get("price") or candidate.get("order_price"))
    if price is None or not math.isfinite(price) or price <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "price_invalid"
        return
    price = max(TIME_EDGE_Q_EPS, min(float(price), 1.0 - TIME_EDGE_Q_EPS))
    candidate["kelly_price"] = float(price)

    size_before = to_float(candidate.get("size"))
    base_notional = None
    if (
        size_before is not None
        and math.isfinite(size_before)
        and size_before > TIME_EDGE_Q_EPS
    ):
        base_notional = float(size_before) * float(price)
    if base_notional is None:
        fallback_notional = _env_float("PM_ORDER_USDC")
        if (
            fallback_notional is not None
            and math.isfinite(fallback_notional)
            and fallback_notional > TIME_EDGE_Q_EPS
        ):
            base_notional = _apply_entry_budget_notional(
                float(fallback_notional),
                floor_to_min=True,
            )
    if base_notional is None or base_notional <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "base_notional_missing"
        return
    candidate["kelly_base_notional"] = float(base_notional)
    if size_before is not None and math.isfinite(size_before):
        candidate["kelly_size_before"] = float(size_before)

    q_prob = _candidate_entry_prob(candidate, float(price))
    if q_prob is None:
        candidate["kelly_reason"] = "q_missing"
        return
    q_prob = max(TIME_EDGE_Q_EPS, min(float(q_prob), 1.0 - TIME_EDGE_Q_EPS))
    candidate["kelly_q_prob"] = float(q_prob)

    # Classic binary Kelly is price-sensitive. The posterior-settlement strategy
    # intentionally ignores "buy-too-expensive" edge semantics; price only
    # converts notional into shares and hard risk caps.
    classic_kelly_raw = (float(q_prob) - float(price)) / max(
        1.0 - float(price),
        TIME_EDGE_Q_EPS,
    )
    ignore_price_edge = _kelly_ignore_price_edge(candidate)
    candidate["kelly_classic_fraction_raw"] = float(classic_kelly_raw)
    candidate["kelly_price_edge_ignored"] = bool(ignore_price_edge)
    if ignore_price_edge:
        kelly_raw = float(q_prob)
        candidate["kelly_fraction_basis"] = "target_realization_probability"
    else:
        kelly_raw = float(classic_kelly_raw)
        candidate["kelly_fraction_basis"] = "classic_binary_price_edge"
    candidate["kelly_fraction_raw"] = float(kelly_raw)
    if not math.isfinite(kelly_raw) or kelly_raw <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "kelly_nonpositive"
        if _env_bool("PM_KELLY_BLOCK_NONPOSITIVE", False):
            candidate["kelly_blocked"] = True
        return

    posterior_target_mode = bool(ignore_price_edge and _is_posterior_settlement_candidate(candidate))
    candidate["target_realization_sizing_active"] = bool(posterior_target_mode)
    if posterior_target_mode:
        kelly_fraction = _env_float_first(("PM_TARGET_REALIZATION_FRACTION", "PM_KELLY_FRACTION"))
    else:
        kelly_fraction = _env_float("PM_KELLY_FRACTION")
    if kelly_fraction is None or not math.isfinite(kelly_fraction) or kelly_fraction <= 0:
        kelly_fraction = DEFAULT_KELLY_FRACTION
    kelly_fraction = max(0.0, min(1.0, float(kelly_fraction)))
    candidate["kelly_fraction_cfg"] = float(kelly_fraction)

    prob_components: List[float] = []
    for key in ("edge_realizable_p_realize", "edge_path_p_reach_lcb", "edge_realizable_p_converge"):
        v = _clamp_prob01(to_float(candidate.get(key)))
        if v is not None:
            prob_components.append(float(v))
    quality_anchor = min(prob_components) if prob_components else 1.0
    quality_mult = 0.5 + 0.5 * float(quality_anchor)
    quality_mult = max(0.0, min(1.0, quality_mult))
    candidate["kelly_quality_anchor"] = float(quality_anchor)
    candidate["kelly_quality_mult"] = float(quality_mult)
    if posterior_target_mode and _env_bool("PM_TARGET_REALIZATION_IGNORE_EDGE_QUALITY", True):
        quality_anchor = 1.0
        quality_mult = 1.0
        candidate["kelly_quality_anchor"] = 1.0
        candidate["kelly_quality_mult"] = 1.0
        candidate["kelly_quality_source"] = "target_realization_ignores_edge_quality"

    realization_mult = 1.0
    if posterior_target_mode:
        realization_mult = _kelly_realization_strength(candidate)
        candidate["kelly_realization_strength"] = float(realization_mult)
        candidate["kelly_realization_strength_included"] = True
    else:
        candidate["kelly_realization_strength"] = float(realization_mult)
        candidate["kelly_realization_strength_included"] = False

    kelly_effective = (
        float(kelly_raw)
        * float(kelly_fraction)
        * float(quality_mult)
        * float(realization_mult)
    )
    candidate["kelly_fraction_effective"] = float(kelly_effective)
    if kelly_effective <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "kelly_effective_nonpositive"
        if _env_bool("PM_KELLY_BLOCK_NONPOSITIVE", False):
            candidate["kelly_blocked"] = True
        return

    bankroll = _env_float_first(
        (
            "PM_TARGET_REALIZATION_BANKROLL_USDC",
            "PM_BANKROLL_USDC",
            "PM_AUTO_TRADE_BANKROLL_USDC",
        )
    )
    near_market_day, _near_market_day_idx = _kelly_near_market_day(candidate)
    if (
        posterior_target_mode
        and near_market_day in {"today", "tomorrow", "day_after"}
        and (
        bankroll is None or not math.isfinite(bankroll) or bankroll <= TIME_EDGE_Q_EPS
        )
    ):
        bankroll = 900.0
        candidate["target_realization_bankroll_defaulted"] = True
        candidate["target_realization_bankroll_default_source"] = "ui_snapshot_default_900"
    target_notional = None
    sizing_source = "base_scaled"
    if posterior_target_mode:
        ssot_target_notional = to_float(
            candidate.get("target_realization_plan_notional")
            or candidate.get("kelly_target_notional")
        )
        ssot_source = str(
            candidate.get("target_realization_plan_notional_source")
            or candidate.get("kelly_sizing_source")
            or ""
        ).strip()
        if (
            ssot_target_notional is not None
            and math.isfinite(ssot_target_notional)
            and ssot_target_notional > TIME_EDGE_Q_EPS
            and ssot_source in {"ui_snapshot_ssot", "ui_snapshot_ssot_capital_plan"}
        ):
            target_notional = float(ssot_target_notional)
            sizing_source = "ui_snapshot_ssot_capital_plan"
            candidate["kelly_target_notional_before_caps"] = float(ssot_target_notional)
    if posterior_target_mode:
        if target_notional is None:
            target_notional = _kelly_near_three_target_notional(
                candidate,
                bankroll=(
                    float(bankroll)
                    if bankroll is not None and math.isfinite(bankroll)
                    else None
                ),
                kelly_effective=float(kelly_effective),
            )
            if target_notional is not None:
                sizing_source = "near_three_market_allocation"
                if float(target_notional) <= TIME_EDGE_Q_EPS:
                    if not str(candidate.get("kelly_reason") or "").strip():
                        candidate["kelly_reason"] = "near_three_allocation_zero"
                    if _env_bool("PM_KELLY_BLOCK_NONPOSITIVE", False):
                        candidate["kelly_blocked"] = True
                    return
    if bankroll is not None and math.isfinite(bankroll) and bankroll > TIME_EDGE_Q_EPS:
        if target_notional is None:
            target_notional = _apply_entry_budget_notional(
                float(bankroll) * float(kelly_effective),
                floor_to_min=True,
            )
            sizing_source = "bankroll_fraction"
    if target_notional is None:
        ref_fraction = _env_float("PM_KELLY_REF_FRACTION")
        if ref_fraction is None or not math.isfinite(ref_fraction) or ref_fraction <= 0:
            ref_fraction = 0.05
        ref_fraction = max(float(ref_fraction), TIME_EDGE_Q_EPS)
        candidate["kelly_ref_fraction"] = float(ref_fraction)
        scale = float(kelly_effective) / float(ref_fraction)
        min_scale = _env_float("PM_KELLY_MIN_SCALE")
        max_scale = _env_float("PM_KELLY_MAX_SCALE")
        if min_scale is None or not math.isfinite(min_scale) or min_scale < 0:
            min_scale = 0.5
        if max_scale is None or not math.isfinite(max_scale) or max_scale <= 0:
            max_scale = 2.0
        if max_scale < min_scale:
            max_scale = min_scale
        scale = max(float(min_scale), min(float(max_scale), float(scale)))
        candidate["kelly_scale"] = float(scale)
        target_notional = float(base_notional) * float(scale)

    min_notional = _env_float("PM_KELLY_MIN_NOTIONAL_USDC")
    if min_notional is not None and (not math.isfinite(min_notional) or min_notional < 0):
        min_notional = None
    max_notional = _env_float("PM_KELLY_MAX_NOTIONAL_USDC", DEFAULT_MAX_ORDER_NOTIONAL_USDC)
    if max_notional is not None and (not math.isfinite(max_notional) or max_notional <= 0):
        max_notional = DEFAULT_MAX_ORDER_NOTIONAL_USDC
    hard_cap_notional = _entry_order_notional_cap_usdc()
    max_notional = _apply_entry_budget_cap_notional(max_notional)
    if hard_cap_notional is not None:
        max_notional = min(max_notional, hard_cap_notional) if max_notional is not None else hard_cap_notional
    if min_notional is not None:
        target_notional = max(float(target_notional), float(min_notional))
    if max_notional is not None:
        target_notional = min(float(target_notional), float(max_notional))
    if target_notional <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "target_notional_nonpositive"
        if _env_bool("PM_KELLY_BLOCK_NONPOSITIVE", False):
            candidate["kelly_blocked"] = True
        return
    candidate["kelly_target_notional"] = float(target_notional)
    candidate["kelly_sizing_source"] = str(sizing_source)
    if sizing_source == "ui_snapshot_ssot_capital_plan":
        candidate["order_size_source"] = "ui_snapshot_ssot_capital_plan"

    size_new = float(target_notional) / float(price)
    min_size = _env_float("PM_MIN_ORDER_SIZE")
    if min_size is not None and math.isfinite(min_size) and min_size > 0:
        size_new = max(float(size_new), float(min_size))
    max_size = _env_float("PM_MAX_ORDER_SIZE")
    if max_size is not None and math.isfinite(max_size) and max_size > 0:
        size_new = min(float(size_new), float(max_size))
    if not math.isfinite(size_new) or size_new <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "size_after_kelly_invalid"
        if _env_bool("PM_KELLY_BLOCK_NONPOSITIVE", False):
            candidate["kelly_blocked"] = True
        return

    candidate["size"] = round(float(size_new), 4)
    candidate["kelly_applied"] = True
    candidate["kelly_reason"] = "applied"


def _normalize_nonnegative_ratio(value: Optional[float], default: float = 1.0) -> float:
    ratio = to_float(value)
    if ratio is None or not math.isfinite(ratio):
        ratio = default
    ratio = float(ratio)
    if ratio < 0:
        ratio = 0.0
    return ratio


def _bayes_bimodal_size_scale(candidate: Mapping[str, Any]) -> float:
    """Retired legacy bimo-size gate; retain field rendering as diagnostics."""

    del candidate
    return 1.0


def _parse_order_usdc_tiers(raw: Optional[str]) -> List[Dict[str, float]]:
    if not raw:
        return []
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        return []
    if not isinstance(payload, list):
        return []
    tiers: List[Dict[str, float]] = []
    for item in payload:
        if not isinstance(item, dict):
            continue
        order_usdc = to_float(item.get("order_usdc"))
        if order_usdc is None or not math.isfinite(order_usdc) or order_usdc <= 0:
            continue
        min_edge_score = to_float(item.get("min_edge_score"))
        min_edge_conf = to_float(item.get("min_edge_confidence"))
        tiers.append(
            {
                "order_usdc": float(order_usdc),
                "min_edge_score": min_edge_score,
                "min_edge_confidence": min_edge_conf,
            }
        )
    tiers.sort(key=lambda t: float(t.get("order_usdc") or 0.0))
    return tiers


def _resolve_order_usdc_tier(
    edge_score: Optional[float],
    edge_confidence: Optional[float],
    tiers: List[Dict[str, float]],
) -> Optional[float]:
    if not tiers:
        return None
    if edge_score is None or not math.isfinite(edge_score):
        return None
    best: Optional[float] = None
    for tier in tiers:
        min_score = to_float(tier.get("min_edge_score"))
        min_conf = to_float(tier.get("min_edge_confidence"))
        if min_score is not None and math.isfinite(min_score):
            if edge_score + TIME_EDGE_Q_EPS < min_score:
                continue
        if min_conf is not None and math.isfinite(min_conf):
            if edge_confidence is None or not math.isfinite(edge_confidence):
                if min_conf > 0:
                    continue
            elif edge_confidence + TIME_EDGE_Q_EPS < min_conf:
                continue
        order_usdc = to_float(tier.get("order_usdc"))
        if order_usdc is None or not math.isfinite(order_usdc) or order_usdc <= 0:
            continue
        if best is None or order_usdc > best + TIME_EDGE_Q_EPS:
            best = float(order_usdc)
    return best


def _model_cache_key(lat: float, lon: float) -> str:
    return f"{lat:.4f},{lon:.4f}"


def _archive_write_scope() -> str:
    return str(
        os.environ.get("PM_ARCHIVE_WRITE_SCOPE")
        or os.environ.get("PM_SCAN_WRITE_SCOPE")
        or ""
    ).strip().lower()


def _archive_write_scope_is_chengdu_zuuu() -> bool:
    scope = _archive_write_scope()
    if not scope:
        return False
    return scope in {
        "chengdu",
        "chengdu_zuuu",
        "chengdu/zuuu",
        "zuuu",
    }


def _coords_are_chengdu(lat: Optional[float], lon: Optional[float]) -> bool:
    lat_val = to_float(lat)
    lon_val = to_float(lon)
    if lat_val is None or lon_val is None:
        return False
    # ZUUU/Chengdu airport and city-center observations can differ slightly.
    return 30.0 <= float(lat_val) <= 31.0 and 103.0 <= float(lon_val) <= 105.0


def _archive_write_allowed_for_chengdu_zuuu(
    *,
    slug: Optional[str] = None,
    title: Optional[str] = None,
    city: Optional[str] = None,
    station_id: Optional[str] = None,
    resolution_source: Optional[str] = None,
    lat: Optional[float] = None,
    lon: Optional[float] = None,
) -> bool:
    if not _archive_write_scope_is_chengdu_zuuu():
        return True
    if _is_chengdu_zuuu_market(
        slug=slug,
        title=title,
        city=city,
        station_id=station_id,
        resolution_source=resolution_source,
    ):
        return True
    return _coords_are_chengdu(lat, lon)


def _payload_write_allowed_for_chengdu_zuuu(
    payload: Optional[Mapping[str, Any]],
    *,
    slug: Optional[str] = None,
    title: Optional[str] = None,
    city: Optional[str] = None,
    station_id: Optional[str] = None,
    resolution_source: Optional[str] = None,
    lat: Optional[float] = None,
    lon: Optional[float] = None,
) -> bool:
    if not _archive_write_scope_is_chengdu_zuuu():
        return True
    if not isinstance(payload, Mapping):
        return _archive_write_allowed_for_chengdu_zuuu(
            slug=slug,
            title=title,
            city=city,
            station_id=station_id,
            resolution_source=resolution_source,
            lat=lat,
            lon=lon,
        )

    market_meta = payload.get("market") if isinstance(payload.get("market"), Mapping) else {}
    profile_meta = (
        payload.get("resolution_source_profile")
        if isinstance(payload.get("resolution_source_profile"), Mapping)
        else {}
    )

    def _first_present(*values: Any) -> Any:
        for value in values:
            if str(value or "").strip():
                return value
        return None

    rows = payload.get("rows")
    if not isinstance(rows, list):
        rows = payload.get("distribution")
    first_row = next((item for item in (rows or []) if isinstance(item, Mapping)), {})

    return _archive_write_allowed_for_chengdu_zuuu(
        slug=_first_present(slug, payload.get("slug"), market_meta.get("slug")),
        title=_first_present(title, payload.get("title"), market_meta.get("title")),
        city=_first_present(
            city,
            payload.get("city"),
            payload.get("city_key"),
            market_meta.get("city"),
            first_row.get("city"),
            first_row.get("city_key"),
        ),
        station_id=_first_present(
            station_id,
            payload.get("station_id"),
            market_meta.get("station_id"),
            profile_meta.get("station_id"),
            first_row.get("station_id"),
            first_row.get("source_station_id"),
        ),
        resolution_source=_first_present(
            resolution_source,
            payload.get("resolution_source"),
            market_meta.get("resolution_source"),
            profile_meta.get("resolution_source"),
            first_row.get("resolution_source"),
        ),
        lat=lat
        if lat is not None
        else to_float(_first_present(payload.get("lat"), market_meta.get("lat"), first_row.get("lat"))),
        lon=lon
        if lon is not None
        else to_float(_first_present(payload.get("lon"), market_meta.get("lon"), first_row.get("lon"))),
    )


def _model_cache_ttl_sec(model: str) -> int:
    if model == "nws_forecast":
        return _env_int("PM_CACHE_TTL_NWS_SEC") or 3600
    return _env_int("PM_CACHE_TTL_ENSEMBLE_SEC") or 21600


def _model_window_minutes() -> int:
    return _env_int("PM_MODEL_WINDOW_MINUTES") or 180


def _model_background_refresh_minutes() -> int:
    return _env_int("PM_MODEL_BACKGROUND_REFRESH_MINUTES") or 45


def _model_window_refresh_minutes() -> int:
    return _env_int("PM_MODEL_WINDOW_REFRESH_MINUTES") or 3


def _model_cache_max_age_sec() -> int:
    return _env_int("PM_MODEL_CACHE_MAX_AGE_SEC") or 172800


def _event_days_out(event_date: str, now: datetime) -> Optional[int]:
    if not event_date:
        return None
    try:
        ev_date = datetime.fromisoformat(event_date).date()
    except Exception:
        return None
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    return (ev_date - now.date()).days


def _model_refresh_minutes_for_event(event_date: str, now: datetime) -> Tuple[int, int]:
    default_min = _env_int("PM_MODEL_REFRESH_MINUTES_DEFAULT") or _model_background_refresh_minutes()
    d0d1_min = _env_int("PM_MODEL_REFRESH_MINUTES_D0D1") or 10
    d3_min = _env_int("PM_MODEL_REFRESH_MINUTES_D3PLUS") or 60
    days_out = _event_days_out(event_date, now)
    if days_out is None:
        return default_min, default_min
    if days_out <= 1:
        return d0d1_min, d0d1_min
    if days_out >= 3:
        return d3_min, d3_min
    return default_min, default_min


def _parse_cycle_hours(raw: Optional[str]) -> Optional[List[int]]:
    if not raw:
        return None
    try:
        offsets = [int(x.strip()) for x in raw.split(",") if x.strip()]
    except ValueError:
        return None
    return offsets or None


def _model_cycle_hours(model: str) -> Optional[List[int]]:
    if not model:
        return None
    env_key = f"PM_MODEL_CYCLE_HOURS_{model.upper()}"
    offsets = _parse_cycle_hours(os.environ.get(env_key))
    if offsets:
        return offsets
    offsets = _parse_cycle_hours(os.environ.get("PM_ENSEMBLE_CYCLE_HOURS"))
    if offsets:
        return offsets
    return MODEL_CYCLE_DEFAULTS.get(model)


def _estimate_model_run_at(model: str, base_time: datetime) -> Optional[datetime]:
    offsets = _model_cycle_hours(model)
    if not offsets:
        return None
    if base_time.tzinfo is None:
        base_time = base_time.replace(tzinfo=timezone.utc)
    delay_hours = _env_int("PM_ENSEMBLE_CYCLE_DELAY_HOURS") or 2
    anchor = _aligned_model_refresh_ts(base_time - timedelta(hours=delay_hours), offsets, 0)
    return anchor


def _is_within_model_window(model: str, now: datetime) -> bool:
    offsets = _model_cycle_hours(model)
    if not offsets:
        return True
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    delay_hours = _env_int("PM_ENSEMBLE_CYCLE_DELAY_HOURS") or 2
    window_minutes = _model_window_minutes()
    for back_days in range(0, 2):
        base = (now - timedelta(days=back_days)).replace(
            hour=0, minute=0, second=0, microsecond=0
        )
        for hour in offsets:
            start = base + timedelta(hours=hour + delay_hours)
            end = start + timedelta(minutes=window_minutes)
            if start <= now <= end:
                return True
    return False


def _should_fetch_model_now(
    model: str,
    loc_key: str,
    date: str,
    market_var: str,
    market_unit: str,
    now: datetime,
) -> Tuple[bool, str]:
    if model == "nws_forecast":
        return True, "nws"
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    meta = _load_latest_model_cache_meta(model, loc_key, date, market_var, market_unit)
    last_update = ""
    created_at_raw = ""
    if meta:
        last_update = meta.get("official_updated_at") or meta.get("created_at") or ""
        created_at_raw = meta.get("created_at") or ""
    if not last_update:
        return True, "no_cache"
    last_dt = _parse_iso_dt(last_update)
    if last_dt is None:
        return True, "no_cache"
    if last_dt.tzinfo is None:
        last_dt = last_dt.replace(tzinfo=timezone.utc)
    age_min = (now - last_dt).total_seconds() / 60.0
    window_min, background_min = _model_refresh_minutes_for_event(date, now)
    strict_cycle = _env_bool("PM_MODEL_STRICT_CYCLE", False)
    if strict_cycle:
        created_at_dt = _parse_iso_dt(created_at_raw)
        if created_at_dt is None:
            created_at_dt = last_dt
        if _is_within_model_window(model, now):
            if _model_cache_force_refresh(model, created_at_dt, now):
                return True, "cycle_window"
            return False, "cycle_hold"
        return False, "cycle_wait"
    if _is_within_model_window(model, now):
        if age_min >= window_min:
            return True, "window"
        return False, "window_hold"
    if age_min >= background_min:
        return True, "background"
    return False, "throttle"


def _aligned_model_refresh_ts(
    now: datetime,
    offsets: Optional[List[int]],
    delay_hours: int,
) -> Optional[datetime]:
    if not offsets:
        return None
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    for back_days in range(0, 3):
        base = (now - timedelta(days=back_days)).replace(
            hour=0, minute=0, second=0, microsecond=0
        )
        for hour in sorted(offsets, reverse=True):
            candidate = base + timedelta(hours=hour + delay_hours)
            if candidate <= now:
                return candidate
    return None


def _model_cache_force_refresh(
    model: str,
    created_at: Optional[datetime],
    now: datetime,
) -> bool:
    if created_at is None:
        return True
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    created_at = created_at if created_at.tzinfo else created_at.replace(tzinfo=timezone.utc)
    if model == "nws_forecast":
        return False
    offsets = _model_cycle_hours(model)
    if not offsets:
        return False
    delay_hours = _env_int("PM_ENSEMBLE_CYCLE_DELAY_HOURS") or 2
    anchor = _aligned_model_refresh_ts(now, offsets, delay_hours)
    if anchor is None:
        return False
    return created_at < anchor


def _sleep_open_meteo_spacing() -> None:
    if OPEN_METEO_GLOBAL_RATE_LIMIT:
        return
    low = max(0.0, OPEN_METEO_MODEL_SPACING_MIN)
    high = max(low, OPEN_METEO_MODEL_SPACING_MAX)
    if high <= 0:
        return
    time.sleep(random.uniform(low, high))


def _open_meteo_global_spacing_sec() -> float:
    low = max(0.0, OPEN_METEO_MODEL_SPACING_MIN)
    high = max(low, OPEN_METEO_MODEL_SPACING_MAX)
    if high <= 0:
        return 0.0
    return float(random.uniform(low, high))


def _open_meteo_wait_global_slot(scope: str = "open_meteo") -> float:
    if not OPEN_METEO_GLOBAL_RATE_LIMIT:
        return 0.0
    delay = _open_meteo_global_spacing_sec()
    if delay <= 0 or not DB_PATH.exists():
        return 0.0
    key = f"net_rate:{scope}"
    wait_sec = 0.0
    conn = None
    try:
        conn = open_db(connect_timeout_sec=0.2, busy_timeout_ms=200)
        cur = conn.cursor()
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS net_rate_limits (
                key TEXT PRIMARY KEY,
                next_allowed_at TEXT,
                updated_at TEXT
            )
            """
        )
        conn.commit()
        for _ in range(6):
            try:
                conn.execute("BEGIN IMMEDIATE")
                cur = conn.cursor()
                cur.execute(
                    "SELECT next_allowed_at FROM net_rate_limits WHERE key = ?",
                    (key,),
                )
                row = cur.fetchone()
                next_allowed = _parse_iso_dt(str(row[0] or "")) if row else None
                now = datetime.now(timezone.utc)
                if next_allowed is not None and next_allowed.tzinfo is None:
                    next_allowed = next_allowed.replace(tzinfo=timezone.utc)
                if next_allowed is not None and next_allowed > now:
                    wait_sec = (next_allowed - now).total_seconds()
                else:
                    wait_sec = 0.0
                reserved_at = now + timedelta(seconds=max(0.0, wait_sec))
                next_dt = reserved_at + timedelta(seconds=float(delay))
                cur.execute(
                    f"""
                    INSERT INTO net_rate_limits(key, next_allowed_at, updated_at)
                    VALUES (?, ?, ?)
                    ON CONFLICT(key) DO UPDATE SET
                      next_allowed_at = excluded.next_allowed_at,
                      updated_at = excluded.updated_at
                    """,
                    (key, next_dt.isoformat(), now.isoformat()),
                )
                conn.commit()
                break
            except sqlite3.OperationalError:
                try:
                    conn.rollback()
                except Exception:
                    pass
                time.sleep(0.05 + random.uniform(0.0, 0.2))
                continue
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass
    if wait_sec > 0:
        time.sleep(wait_sec)
    return float(wait_sec)


def _clob_book_global_spacing_sec() -> float:
    low = max(0.0, CLOB_BOOK_SPACING_MIN)
    high = max(low, CLOB_BOOK_SPACING_MAX)
    if high <= 0:
        return 0.0
    return float(random.uniform(low, high))


def _clob_book_wait_global_slot(
    scope: str = "clob_book",
    *,
    max_wait_sec: Optional[float] = None,
) -> float:
    if not _env_bool("PM_CLOB_BOOK_GLOBAL_RATE_LIMIT", CLOB_BOOK_GLOBAL_RATE_LIMIT):
        return 0.0
    started_mono = time.monotonic()

    def _wait_budget_remaining() -> Optional[float]:
        if max_wait_sec is None:
            return None
        try:
            max_wait_val = float(max_wait_sec)
        except Exception:
            return None
        if not math.isfinite(max_wait_val) or max_wait_val < 0:
            return None
        return max(0.0, float(max_wait_val) - (time.monotonic() - started_mono))

    delay = _clob_book_global_spacing_sec()
    if delay <= 0 or not DB_PATH.exists():
        return 0.0
    key = f"net_rate:{scope}"
    wait_sec = 0.0
    conn = None
    conn_ctx = None
    try:
        initial_remaining = _wait_budget_remaining()
        connect_timeout_sec = 0.2
        busy_timeout_ms = 200
        if initial_remaining is not None:
            if initial_remaining <= 0.02:
                return 0.0
            connect_timeout_sec = max(0.02, min(0.2, float(initial_remaining)))
            busy_timeout_ms = max(25, min(200, int(float(initial_remaining) * 1000)))
        conn = open_db(
            connect_timeout_sec=connect_timeout_sec,
            busy_timeout_ms=busy_timeout_ms,
        )
        cur = conn.cursor()
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS net_rate_limits (
                key TEXT PRIMARY KEY,
                next_allowed_at TEXT,
                updated_at TEXT
            )
            """
        )
        conn.commit()
        for _ in range(6):
            remaining_before_try = _wait_budget_remaining()
            if remaining_before_try is not None and remaining_before_try <= 0.02:
                break
            try:
                conn.execute("BEGIN IMMEDIATE")
                cur = conn.cursor()
                cur.execute(
                    "SELECT next_allowed_at FROM net_rate_limits WHERE key = ?",
                    (key,),
                )
                row = cur.fetchone()
                next_allowed = _parse_iso_dt(str(row[0] or "")) if row else None
                now = datetime.now(timezone.utc)
                if next_allowed is not None and next_allowed.tzinfo is None:
                    next_allowed = next_allowed.replace(tzinfo=timezone.utc)
                if next_allowed is not None and next_allowed > now:
                    wait_sec = (next_allowed - now).total_seconds()
                else:
                    wait_sec = 0.0
                reserved_at = now + timedelta(seconds=max(0.0, wait_sec))
                next_dt = reserved_at + timedelta(seconds=float(delay))
                cur.execute(
                    f"""
                    INSERT INTO net_rate_limits(key, next_allowed_at, updated_at)
                    VALUES (?, ?, ?)
                    ON CONFLICT(key) DO UPDATE SET
                      next_allowed_at = excluded.next_allowed_at,
                      updated_at = excluded.updated_at
                    """,
                    (key, next_dt.isoformat(), now.isoformat()),
                )
                conn.commit()
                break
            except sqlite3.OperationalError:
                try:
                    conn.rollback()
                except Exception:
                    pass
                retry_sleep = 0.05 + random.uniform(0.0, 0.2)
                remaining_after_error = _wait_budget_remaining()
                if remaining_after_error is not None:
                    retry_sleep = min(float(retry_sleep), max(0.0, float(remaining_after_error)))
                if retry_sleep > 0:
                    time.sleep(retry_sleep)
                continue
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass
    if max_wait_sec is not None:
        try:
            max_wait_val = float(max_wait_sec)
        except Exception:
            max_wait_val = None
        if max_wait_val is not None and math.isfinite(max_wait_val) and max_wait_val >= 0:
            wait_sec = min(float(wait_sec), float(max_wait_val))
    if wait_sec > 0:
        time.sleep(wait_sec)
    return float(wait_sec)


def _parse_iso_dt(value: Optional[str]) -> Optional[datetime]:
    if not value:
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


def _parse_http_date(value: Optional[str]) -> Optional[datetime]:
    if not value:
        return None
    try:
        dt = parsedate_to_datetime(value)
    except (TypeError, ValueError):
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def _resolve_model_official_update(
    model: str,
    provenance: Optional[Dict],
) -> Tuple[Optional[str], Optional[str]]:
    if not provenance:
        if model != "nws_forecast":
            estimate = _estimate_model_run_at(model, datetime.now(timezone.utc))
            if estimate:
                return estimate.isoformat(), "estimated"
        return None, None
    official_raw = str(provenance.get("official_updated_at") or "")
    official_dt = _parse_iso_dt(official_raw)
    if official_dt:
        if official_dt.tzinfo is None:
            official_dt = official_dt.replace(tzinfo=timezone.utc)
        return official_dt.isoformat(), "official"
    resp_dt = _parse_http_date(str(provenance.get("response_date") or ""))
    if resp_dt is None:
        resp_dt = _parse_iso_dt(
            str(provenance.get("completed_at") or provenance.get("requested_at") or "")
        )
    if resp_dt is None:
        resp_dt = datetime.now(timezone.utc)
    if model != "nws_forecast":
        estimate = _estimate_model_run_at(model, resp_dt)
        if estimate:
            return estimate.isoformat(), "estimated"
    return None, None


def _members_signature(members: Optional[np.ndarray]) -> Optional[str]:
    if members is None:
        return None
    try:
        arr = np.asarray(members, dtype=float)
    except Exception:
        return None
    if arr.size == 0:
        return None
    arr = np.ascontiguousarray(arr)
    digest = hashlib.sha256()
    digest.update(str(arr.shape).encode("utf-8"))
    digest.update(arr.tobytes())
    return digest.hexdigest()


def _load_latest_model_cache_meta(
    model: str,
    loc_key: str,
    date: str,
    market_var: str,
    market_unit: str,
) -> Optional[Dict[str, str]]:
    if not DB_PATH.exists():
        return None
    try:
        conn = open_db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        try:
            cur.execute(
                """
                SELECT official_updated_at, official_updated_source, members_signature, created_at
                FROM model_member_cache
                WHERE model = ? AND loc_key = ? AND event_date = ?
                  AND market_var = ? AND market_unit = ?
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (model, loc_key, date, market_var, market_unit or ""),
            )
            row = cur.fetchone()
        except sqlite3.OperationalError:
            cur.execute(
                """
                SELECT created_at
                FROM model_member_cache
                WHERE model = ? AND loc_key = ? AND event_date = ?
                  AND market_var = ? AND market_unit = ?
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (model, loc_key, date, market_var, market_unit or ""),
            )
            row = cur.fetchone()
            if row:
                return {
                    "official_updated_at": "",
                    "official_updated_source": "",
                    "members_signature": "",
                    "created_at": str(row["created_at"] or ""),
                }
    except Exception:
        row = None
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not row:
        return None
    return {
        "official_updated_at": str(row["official_updated_at"] or ""),
        "official_updated_source": str(row["official_updated_source"] or ""),
        "members_signature": str(row["members_signature"] or ""),
        "created_at": str(row["created_at"] or ""),
    }


def _open_meteo_cooldown_until(
    loc_key: str,
    event_date: str,
    market_var: str,
    market_unit: str,
) -> Optional[datetime]:
    if not DB_PATH.exists():
        return None
    try:
        conn = open_db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute(
            """
            SELECT cooldown_until
            FROM model_request_cooldown
            WHERE loc_key = ? AND event_date = ? AND market_var = ? AND market_unit = ?
            """,
            (loc_key, event_date, market_var, market_unit or ""),
        )
        row = cur.fetchone()
    except Exception:
        return None
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not row:
        return None
    return _parse_iso_dt(str(row["cooldown_until"] or ""))


def _set_open_meteo_cooldown(
    loc_key: str,
    event_date: str,
    market_var: str,
    market_unit: str,
    seconds: int,
    reason: str,
) -> None:
    if seconds <= 0 or not DB_PATH.exists():
        return
    until = datetime.now(timezone.utc) + timedelta(seconds=seconds)
    try:
        conn = open_db()
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO model_request_cooldown (
                loc_key, event_date, market_var, market_unit, reason, cooldown_until, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(loc_key, event_date, market_var, market_unit)
            DO UPDATE SET cooldown_until = excluded.cooldown_until,
                          reason = excluded.reason,
                          created_at = excluded.created_at
            """,
            (
                loc_key,
                event_date,
                market_var,
                market_unit or "",
                reason,
                until.isoformat(),
                utc_now_iso(),
            ),
        )
        conn.commit()
    except Exception:
        pass
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _parse_cache_ts(raw: Optional[str]) -> Optional[datetime]:
    if not raw:
        return None
    try:
        ts = datetime.fromisoformat(raw)
    except ValueError:
        return None
    if ts.tzinfo is None:
        ts = ts.replace(tzinfo=timezone.utc)
    return ts


def _load_model_member_cache(
    model: str,
    lat: float,
    lon: float,
    date: str,
    market_var: str,
    market_unit: Optional[str],
    max_age_sec: int,
    ignore_cycle_refresh: bool = False,
) -> Optional[Tuple[np.ndarray, float]]:
    if max_age_sec <= 0 or not DB_PATH.exists():
        return None
    loc_key = _model_cache_key(lat, lon)
    try:
        conn = open_db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute(
            """
            SELECT members_json, created_at
            FROM model_member_cache
            WHERE model = ? AND loc_key = ? AND event_date = ?
              AND market_var = ? AND market_unit = ?
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (model, loc_key, date, market_var, market_unit or ""),
        )
        row = cur.fetchone()
    except Exception:
        return None
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not row:
        return None
    created_at = _parse_cache_ts(row["created_at"])
    if created_at is None:
        return None
    now = datetime.now(timezone.utc)
    if not ignore_cycle_refresh and _model_cache_force_refresh(model, created_at, now):
        return None
    age_sec = (datetime.now(timezone.utc) - created_at).total_seconds()
    if age_sec > max_age_sec:
        return None
    try:
        members = json.loads(row["members_json"] or "[]")
    except json.JSONDecodeError:
        return None
    if not isinstance(members, list) or not members:
        return None
    return np.array(members, dtype=float), float(age_sec)


def _save_model_member_cache(
    model: str,
    lat: float,
    lon: float,
    date: str,
    market_var: str,
    market_unit: Optional[str],
    members: np.ndarray,
    official_updated_at: Optional[str] = None,
    official_updated_source: Optional[str] = None,
    members_signature: Optional[str] = None,
) -> None:
    if members is None or not DB_PATH.exists():
        return
    if not _archive_write_allowed_for_chengdu_zuuu(lat=lat, lon=lon):
        return
    try:
        arr = np.array(members, dtype=float)
    except Exception:
        return
    if arr.size == 0:
        return
    loc_key = _model_cache_key(lat, lon)
    payload = json.dumps(arr.tolist())
    signature = members_signature or _members_signature(arr) or ""
    try:
        conn = open_db()
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO model_member_cache (
                model, loc_key, event_date, market_var, market_unit,
                members_json, created_at, official_updated_at, official_updated_source,
                members_signature
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                model,
                loc_key,
                date,
                market_var,
                market_unit or "",
                payload,
                utc_now_iso(),
                official_updated_at or "",
                official_updated_source or "",
                signature,
            ),
        )
        conn.commit()
    except Exception:
        return
    finally:
        try:
            conn.close()
        except Exception:
            pass




def _is_errno24_error(exc: Exception) -> bool:
    msg = str(exc or "")
    if not msg:
        return False
    lower = msg.lower()
    return (
        ("errno 24" in lower)
        or ("too many open files" in lower)
        or ("exec_errno24" in lower)
        or ("emfile" in lower)
    )


def _payload_has_errno24(payload: Any) -> bool:
    if isinstance(payload, dict):
        blob = " ".join(
            str(payload.get(key, "") or "")
            for key in ("error", "error_detail", "stderr", "stdout", "detail")
        )
    else:
        blob = str(payload or "")
    return _is_errno24_error(blob)


def _normalize_errno24_payload(payload: Any) -> Dict[str, Any]:
    if isinstance(payload, dict):
        out = dict(payload)
    else:
        out = {"error": str(payload or "exec_failed")}
    if _payload_has_errno24(out):
        out["error"] = "exec_errno24"
        out.setdefault("error_detail", "too_many_open_files")
    return out


def _exec_failed_payload(exc: Exception) -> Dict[str, Any]:
    if _is_errno24_error(exc):
        return {"error": "exec_errno24", "error_detail": "too_many_open_files"}
    payload: Dict[str, Any] = {"error": f"exec_failed:{exc}"}
    stdout = getattr(exc, "output", None)
    stderr = getattr(exc, "stderr", None)
    if stdout is not None:
        payload["stdout"] = str(stdout).strip()
    if stderr is not None:
        payload["stderr"] = str(stderr).strip()
        err_detail = _extract_node_error_detail(str(stderr or ""), str(stdout or ""))
        if err_detail:
            payload["error_detail"] = err_detail
    if isinstance(exc, subprocess.TimeoutExpired):
        payload["timeout_expired"] = True
        payload["timeout_sec"] = float(exc.timeout) if exc.timeout is not None else None
        payload["cmd"] = [str(part) for part in (exc.cmd or [])]
        payload.setdefault("stdout", str(stdout or "").strip())
        payload.setdefault("stderr", str(stderr or "").strip())
        payload.setdefault("error_detail", "subprocess_timeout")
        if not payload.get("stdout") and not payload.get("stderr"):
            payload["subprocess_timeout_output_missing"] = True
            payload["subprocess_timeout_output_missing_reason"] = (
                "outer_timeout_before_child_json_or_stderr_flush"
            )
    return payload


try:
    _NODE_SUBPROCESS_MAX_CONCURRENT = int(float(os.environ.get("PM_NODE_SUBPROCESS_MAX_CONCURRENT", "1") or 1))
except Exception:
    _NODE_SUBPROCESS_MAX_CONCURRENT = 1
_NODE_SUBPROCESS_MAX_CONCURRENT = max(1, min(_NODE_SUBPROCESS_MAX_CONCURRENT, 16))
_NODE_SUBPROCESS_SEM = threading.BoundedSemaphore(_NODE_SUBPROCESS_MAX_CONCURRENT)
_NODE_SUBPROCESS_ACTIVE_LOCK = threading.RLock()
_NODE_SUBPROCESS_ACTIVE_PGIDS: Set[int] = set()


def _register_node_subprocess_pgid(pgid: Optional[int]) -> None:
    if pgid is None:
        return
    try:
        pgid_i = int(pgid)
    except Exception:
        return
    if pgid_i <= 0:
        return
    with _NODE_SUBPROCESS_ACTIVE_LOCK:
        _NODE_SUBPROCESS_ACTIVE_PGIDS.add(pgid_i)


def _unregister_node_subprocess_pgid(pgid: Optional[int]) -> None:
    if pgid is None:
        return
    try:
        pgid_i = int(pgid)
    except Exception:
        return
    with _NODE_SUBPROCESS_ACTIVE_LOCK:
        _NODE_SUBPROCESS_ACTIVE_PGIDS.discard(pgid_i)


def _terminate_node_process_group(pgid: Optional[int], sig: int) -> None:
    if pgid is None:
        return
    try:
        pgid_i = int(pgid)
    except Exception:
        return
    if pgid_i <= 0:
        return
    try:
        os.killpg(pgid_i, sig)
    except ProcessLookupError:
        pass
    except PermissionError as exc:
        if sig != signal.SIGKILL:
            print(
                f"[auto-trade] failed to signal node process group pgid={pgid_i} sig={sig}: {exc}",
                file=sys.stderr,
                flush=True,
            )
    except Exception as exc:
        print(
            f"[auto-trade] failed to signal node process group pgid={pgid_i} sig={sig}: {exc}",
            file=sys.stderr,
            flush=True,
        )


def _terminate_active_node_subprocesses(grace_sec: float = 0.35) -> None:
    with _NODE_SUBPROCESS_ACTIVE_LOCK:
        pgids = list(_NODE_SUBPROCESS_ACTIVE_PGIDS)
    if not pgids:
        return
    for pgid in pgids:
        _terminate_node_process_group(pgid, signal.SIGTERM)
    if grace_sec and grace_sec > 0:
        time.sleep(min(float(grace_sec), 2.0))
    for pgid in pgids:
        _terminate_node_process_group(pgid, signal.SIGKILL)
    with _NODE_SUBPROCESS_ACTIVE_LOCK:
        for pgid in pgids:
            _NODE_SUBPROCESS_ACTIVE_PGIDS.discard(pgid)


def _run_node_subprocess(
    cmd: List[str],
    *,
    env: Dict[str, str],
    timeout: Optional[float],
    retries_on_errno24: int = 1,
    retry_sleep_sec: float = 0.35,
) -> subprocess.CompletedProcess:
    last_exc: Optional[Exception] = None
    retries = max(0, int(retries_on_errno24))
    for attempt in range(retries + 1):
        proc: Optional[subprocess.Popen] = None
        pgid: Optional[int] = None
        try:
            _NODE_SUBPROCESS_SEM.acquire()
            try:
                proc = subprocess.Popen(
                    cmd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    env=env,
                    close_fds=True,
                    start_new_session=True,
                )
                try:
                    pgid = os.getpgid(proc.pid)
                except Exception:
                    pgid = None
                _register_node_subprocess_pgid(pgid)
                try:
                    stdout, stderr = proc.communicate(timeout=timeout)
                except subprocess.TimeoutExpired as exc:
                    _terminate_node_process_group(pgid, signal.SIGTERM)
                    try:
                        stdout, stderr = proc.communicate(timeout=1.0)
                    except subprocess.TimeoutExpired:
                        _terminate_node_process_group(pgid, signal.SIGKILL)
                        stdout, stderr = proc.communicate()
                    raise subprocess.TimeoutExpired(
                        cmd,
                        timeout,
                        output=stdout if stdout is not None else getattr(exc, "output", None),
                        stderr=stderr if stderr is not None else getattr(exc, "stderr", None),
                    )
                return subprocess.CompletedProcess(
                    cmd,
                    proc.returncode,
                    stdout=stdout,
                    stderr=stderr,
                )
            finally:
                _unregister_node_subprocess_pgid(pgid)
                _NODE_SUBPROCESS_SEM.release()
        except Exception as exc:
            last_exc = exc
            if attempt >= retries or not _is_errno24_error(exc):
                raise
            sleep_sec = max(0.05, float(retry_sleep_sec)) * float(attempt + 1)
            print(
                f"[auto-trade] node subprocess Errno24 retry {attempt + 1}/{retries}: {exc}",
                file=sys.stderr,
                flush=True,
            )
            time.sleep(sleep_sec)
    if last_exc is not None:
        raise last_exc
    raise RuntimeError("node_subprocess_failed")


def _normalize_place_order_price(price: Any) -> Tuple[Optional[float], bool]:
    try:
        value = float(price)
    except Exception:
        return None, False
    if not math.isfinite(value):
        return None, False
    # Polymarket prices are in [0, 1]. Many markets trade with 0.1c ticks (0.001),
    # so do not clamp to a 1c minimum.
    clamped = min(0.999, max(0.001, value))
    clamped = round(clamped, 6)
    return clamped, abs(clamped - value) > 1e-9


def _auto_order_record_price(price: Any) -> Optional[float]:
    price_val = to_float(price)
    if price_val is None or not math.isfinite(price_val):
        return None
    normalized, _ = _normalize_place_order_price(price_val)
    if normalized is not None and math.isfinite(normalized):
        return float(normalized)
    return float(price_val)


def _auto_trade_buy_fee_rate() -> float:
    fee_rate = _env_float("PM_AUTO_TRADE_BUY_FEE_RATE")
    if fee_rate is None or not math.isfinite(fee_rate) or fee_rate < 0:
        fee_rate = 0.05
    return max(0.0, min(float(fee_rate), 0.25))


def _estimate_buy_collateral_required_usdc(
    *,
    price: Any,
    size: Any,
    amount: Any = None,
    order_type: Any = None,
    fee_rate: Optional[float] = None,
) -> Optional[float]:
    price_val = to_float(price)
    size_val = to_float(size)
    amount_val = to_float(amount)
    order_type_u = str(order_type or "").strip().upper()
    if fee_rate is None or not math.isfinite(fee_rate) or fee_rate < 0:
        fee_rate = _auto_trade_buy_fee_rate()
    fee_rate = max(0.0, float(fee_rate))

    base_notional: Optional[float] = None
    if order_type_u in {"FAK", "FOK"} and amount_val is not None and math.isfinite(amount_val) and amount_val > 0:
        base_notional = float(amount_val)
    elif (
        price_val is not None
        and math.isfinite(price_val)
        and price_val > 0
        and size_val is not None
        and math.isfinite(size_val)
        and size_val > 0
    ):
        base_notional = float(price_val) * float(size_val)
    elif amount_val is not None and math.isfinite(amount_val) and amount_val > 0:
        base_notional = float(amount_val)
    if base_notional is None or not math.isfinite(base_notional) or base_notional <= 0:
        return None

    fee_est = float(base_notional) * float(fee_rate)
    if (
        price_val is not None
        and math.isfinite(price_val)
        and price_val > 0
        and size_val is not None
        and math.isfinite(size_val)
        and size_val > 0
    ):
        fee_price = min(max(float(price_val), 0.0), max(1.0 - float(price_val), 0.0))
        fee_est = max(fee_est, float(fee_rate) * float(fee_price) * float(size_val))
    return max(0.0, float(base_notional) + float(fee_est))


def _max_buy_size_for_collateral_usdc(
    *,
    available_usdc: Any,
    price: Any,
    reserve_usdc: Any = 0.0,
    fee_rate: Optional[float] = None,
) -> Optional[float]:
    available_val = to_float(available_usdc)
    price_val = to_float(price)
    reserve_val = to_float(reserve_usdc)
    if available_val is None or not math.isfinite(available_val):
        return None
    if price_val is None or not math.isfinite(price_val) or price_val <= 0:
        return None
    if reserve_val is None or not math.isfinite(reserve_val) or reserve_val < 0:
        reserve_val = 0.0
    if fee_rate is None or not math.isfinite(fee_rate) or fee_rate < 0:
        fee_rate = _auto_trade_buy_fee_rate()
    fee_rate = max(0.0, float(fee_rate))
    spendable = max(0.0, float(available_val) - float(reserve_val))
    fee_price = min(max(float(price_val), 0.0), max(1.0 - float(price_val), 0.0))
    per_share = float(price_val) + float(fee_rate) * float(fee_price)
    if per_share <= TIME_EDGE_Q_EPS:
        return None
    size = math.floor((spendable / per_share) * 10000.0) / 10000.0
    if size <= TIME_EDGE_Q_EPS:
        return None
    return float(size)


def _clob_order_service_enabled() -> bool:
    return _env_bool("PM_CLOB_ORDER_SERVICE_ENABLED", False)


def _clob_order_service_url() -> str:
    raw = str(os.environ.get("PM_CLOB_ORDER_SERVICE_URL") or "").strip()
    if not raw:
        host = str(os.environ.get("PM_CLOB_ORDER_SERVICE_HOST") or "127.0.0.1").strip() or "127.0.0.1"
        port = str(os.environ.get("PM_CLOB_ORDER_SERVICE_PORT") or "8765").strip() or "8765"
        raw = f"http://{host}:{port}"
    return raw.rstrip("/")


def _clob_order_service_request_timeout_sec(default_timeout_sec: float) -> float:
    configured = _env_float("PM_CLOB_ORDER_SERVICE_REQUEST_TIMEOUT_SEC")
    if configured is None or not math.isfinite(configured) or configured <= 0:
        configured = default_timeout_sec
    return max(0.5, min(float(configured), max(0.5, float(default_timeout_sec))))


def _clob_order_service_idempotency_key(payload: Mapping[str, Any]) -> str:
    audit_keys = {
        "execution_domain",
        "order_execution_domain",
        "order_execution_source",
        "order_execution_context_version",
        "order_execution_reason",
        "order_intent_action",
        "manual_confirm_source",
    }
    stable_payload = {
        str(key): value
        for key, value in dict(payload or {}).items()
        if str(key)
        not in {"idempotency_key", "request_id", "created_at", "submitted_at", *audit_keys}
        and value is not None
    }
    raw = json.dumps(stable_payload, sort_keys=True, separators=(",", ":"), default=str)
    return "clobsvc:" + hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _clob_order_service_direct_target_idempotency_key(payload: Mapping[str, Any]) -> str:
    if not isinstance(payload, Mapping) or not bool(payload.get("direct_target_order_context")):
        return ""
    if bool(payload.get("direct_target_exit_order")):
        return ""
    slug = str(payload.get("slug") or "").strip()
    event_date = _normalize_date_key(str(payload.get("event_date") or "").strip())
    outcome = str(payload.get("outcome") or payload.get("target_bucket") or "").strip()
    outcome_side = str(payload.get("outcome_side") or "").strip().upper()
    token_id = str(payload.get("token_id") or "").strip()
    trade_side = str(payload.get("side") or "").strip().upper()
    if not slug or not event_date or not outcome or outcome_side not in {"YES", "NO"} or not token_id:
        return ""
    intent_payload = {
        "intent": "direct_target_entry_v1",
        "slug": slug,
        "event_date": event_date,
        "outcome": outcome,
        "outcome_side": outcome_side,
        "token_id": token_id,
        "trade_side": trade_side or "BUY",
        "intent_action": str(payload.get("intent_action") or "entry").strip().lower() or "entry",
        "source": str(payload.get("strategy_source") or payload.get("posterior_target_source") or "posterior_target_direct").strip().lower(),
    }
    raw = json.dumps(intent_payload, sort_keys=True, separators=(",", ":"), default=str)
    return "clobsvc:direct-target:" + hashlib.sha256(raw.encode("utf-8")).hexdigest()


ORDER_EXECUTION_CONTEXT_VERSION = "order_execution_domain_v1"
ORDER_EXECUTION_DOMAIN_BAYES_WEATHER = "bayes_weather_auto_trade"
ORDER_EXECUTION_DOMAIN_MIRROR_FOLLOW = "mirror_follow"
ORDER_EXECUTION_DOMAIN_MANUAL_SMOKE_TEST = "manual_smoke_test"
ORDER_EXECUTION_DOMAIN_UNSPECIFIED = "unspecified"


def _order_execution_context_from_order_context(
    *,
    action: str,
    side_upper: str,
    direct_target_order: bool,
    direct_target_exit_order: bool,
    order_context: Optional[Mapping[str, Any]],
) -> Dict[str, Any]:
    ctx = dict(order_context or {}) if isinstance(order_context, Mapping) else {}
    domain = str(
        ctx.get("order_execution_domain")
        or ctx.get("execution_domain")
        or ""
    ).strip()
    if not domain and direct_target_order:
        domain = ORDER_EXECUTION_DOMAIN_BAYES_WEATHER
    if not domain:
        domain = ORDER_EXECUTION_DOMAIN_UNSPECIFIED

    intent_action = str(ctx.get("intent_action") or "").strip().lower()
    if not intent_action and str(action or "").strip() == "place-order":
        intent_action = "exit" if side_upper == "SELL" else "entry"
    if not intent_action:
        intent_action = str(action or "").strip().lower() or "unknown"

    source = str(
        ctx.get("order_execution_source")
        or ctx.get("entry_order_submit_source")
        or ctx.get("strategy_source")
        or ctx.get("posterior_target_source")
        or domain
    ).strip() or domain
    reason = str(ctx.get("order_execution_reason") or "").strip()
    if not reason:
        if domain == ORDER_EXECUTION_DOMAIN_BAYES_WEATHER:
            reason = "bayes_or_hard_source_decision_path"
        elif domain == ORDER_EXECUTION_DOMAIN_MIRROR_FOLLOW:
            reason = "source_wallet_mirror_strategy"
        elif domain == ORDER_EXECUTION_DOMAIN_MANUAL_SMOKE_TEST:
            reason = "manual_real_money_smoke_test"
        else:
            reason = "low_level_order_gateway_call"

    return {
        "order_execution_context_version": ORDER_EXECUTION_CONTEXT_VERSION,
        "order_execution_domain": domain,
        "execution_domain": domain,
        "order_execution_source": source,
        "order_execution_reason": reason,
        "order_intent_action": intent_action,
        "direct_target_exit_order": bool(direct_target_exit_order),
    }


def _bayes_weather_order_context(
    *,
    slug: Any,
    event_date: Any,
    outcome: Any,
    side: Any,
    intent_action: str,
    submit_source: str,
    candidate: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    details = dict(candidate or {}) if isinstance(candidate, Mapping) else {}
    raw_execution_contract = details.get("sequential_bayes_execution_contract")
    execution_contract = (
        raw_execution_contract if isinstance(raw_execution_contract, Mapping) else {}
    )
    target_bucket = (
        details.get("target_bucket")
        or details.get("posterior_target_bucket")
        or details.get("ssot_target_bucket")
        or outcome
    )
    ctx: Dict[str, Any] = {
        "execution_domain": ORDER_EXECUTION_DOMAIN_BAYES_WEATHER,
        "order_execution_domain": ORDER_EXECUTION_DOMAIN_BAYES_WEATHER,
        "order_execution_source": str(submit_source or "bayes_weather_auto_trade"),
        "order_execution_reason": "bayes_or_hard_source_decision_path",
        "intent_action": str(intent_action or "").strip() or "entry",
        "strategy_source": str(
            details.get("strategy_source")
            or details.get("strategy")
            or details.get("posterior_target_source")
            or "bayes_weather_auto_trade"
        ).strip()
        or "bayes_weather_auto_trade",
        "entry_order_submit_source": str(submit_source or "bayes_weather_auto_trade"),
        "slug": str(slug or ""),
        "event_date": str(event_date or ""),
        "outcome": str(outcome or ""),
        "outcome_side": str(side or "").strip().upper(),
        "target_bucket": str(target_bucket or ""),
        "posterior_target_bucket": details.get("posterior_target_bucket"),
        "ssot_target_bucket": details.get("ssot_target_bucket"),
        "posterior_target_source": details.get("posterior_target_source"),
        "posterior_target_fact_id": details.get("posterior_target_fact_id"),
        "posterior_target_fact_as_of": details.get("posterior_target_fact_as_of"),
        "posterior_composer_schema": details.get("posterior_composer_schema"),
        "posterior_activation_mode": details.get("posterior_activation_mode"),
        "sequential_bayes_execution_contract_id": details.get(
            "sequential_bayes_execution_contract_id"
        ),
        "signal_to_order_slo_deadline_at": details.get("signal_to_order_slo_deadline_at")
        or execution_contract.get("signal_to_order_slo_deadline_at"),
        "signal_to_order_hard_deadline_at": details.get(
            "signal_to_order_hard_deadline_at"
        ) or execution_contract.get("signal_to_order_hard_deadline_at"),
        "observation_to_order_slo_deadline_at": details.get(
            "observation_to_order_slo_deadline_at"
        ) or execution_contract.get("observation_to_order_slo_deadline_at"),
        "observation_to_order_hard_deadline_at": details.get(
            "observation_to_order_hard_deadline_at"
        ) or execution_contract.get("observation_to_order_hard_deadline_at"),
        "target_realization_v3_plan_id": details.get("target_realization_v3_plan_id"),
        "target_realization_maker_only": details.get("target_realization_maker_only"),
        "target_realization_price_source": details.get("target_realization_price_source"),
        "passive_limit_price": (
            details.get("limit_price")
            if details.get("limit_price") is not None
            else details.get("price")
        ),
        "best_bid": details.get("best_bid") or details.get("bid"),
        "best_ask": details.get("best_ask") or details.get("ask"),
        "post_only": details.get("post_only"),
        "order_type": details.get("order_type"),
    }
    if isinstance(raw_execution_contract, Mapping):
        ctx["sequential_bayes_execution_contract"] = dict(execution_contract)
        ctx["sequential_bayes_execution_validation"] = (
            validate_sequential_bayes_execution_context(details)
        )
    return {key: value for key, value in ctx.items() if value is not None and str(value).strip()}


def _clob_order_service_timeout_confirm_sec() -> float:
    configured = _env_float("PM_CLOB_ORDER_SERVICE_TIMEOUT_CONFIRM_SEC")
    if configured is None or not math.isfinite(configured) or configured < 0:
        configured = 8.0
    return max(0.0, min(float(configured), 12.0))


def _clob_order_service_direct_timeout_defer_confirm() -> bool:
    return _env_bool("PM_CLOB_ORDER_SERVICE_DIRECT_TIMEOUT_DEFER_CONFIRM", True)


def _clob_order_service_timeout_may_have_submitted(payload: Mapping[str, Any]) -> bool:
    if not isinstance(payload, Mapping):
        return False
    return bool(
        payload.get("clob_order_service")
        and payload.get("timeout_expired")
        and str(payload.get("error") or "").strip() == "clob_order_service_timeout"
    )


def _clob_order_service_submit_pending(payload: Mapping[str, Any]) -> bool:
    if not isinstance(payload, Mapping):
        return False
    return bool(
        payload.get("clob_order_service")
        and payload.get("pending")
        and payload.get("accepted")
        and str(payload.get("idempotency_key") or "").strip()
        and not str(payload.get("orderID") or payload.get("orderId") or "").strip()
    )


def _clob_order_service_timeout_confirm(
    *,
    service_url: str,
    idempotency_key: str,
    timeout_body: MutableMapping[str, Any],
) -> Tuple[bool, Dict[str, Any]]:
    confirm_sec = _clob_order_service_timeout_confirm_sec()
    key = str(idempotency_key or "").strip()
    if not key or confirm_sec <= 0:
        return False, dict(timeout_body)
    url = f"{service_url}/order-status"
    deadline = time.monotonic() + confirm_sec
    attempts = 0
    last_body: Dict[str, Any] = {}
    while time.monotonic() <= deadline:
        attempts += 1
        remaining = max(0.05, deadline - time.monotonic())
        try:
            response = requests.get(
                url,
                params={"idempotency_key": key},
                timeout=(0.25, min(1.0, remaining)),
            )
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {"response": body}
            except Exception:
                body = {"stdout": str(response.text or "").strip()}
            body["clob_order_service"] = True
            body["clob_order_service_url"] = service_url
            body["clob_order_service_status_http_status"] = int(response.status_code)
            body["clob_order_service_timeout_confirm_attempts"] = attempts
            last_body = dict(body)
            if response.status_code < 400 and body.get("ok") is not False and body.get("orderID"):
                body.setdefault("source", "clob_order_service")
                body["clob_order_service_timeout_recovered"] = True
                body["clob_order_service_original_error"] = timeout_body.get("error")
                body["clob_order_service_original_error_detail"] = timeout_body.get("error_detail")
                body["clob_order_service_timeout_confirm_sec"] = float(confirm_sec)
                return True, body
            if not bool(body.get("pending")):
                time.sleep(min(0.25, max(0.0, deadline - time.monotonic())))
                continue
        except requests.exceptions.RequestException as exc:
            last_body = {
                "error": "clob_order_service_status_request_failed",
                "error_detail": str(exc),
                "clob_order_service": True,
                "clob_order_service_url": service_url,
                "clob_order_service_timeout_confirm_attempts": attempts,
            }
        time.sleep(min(0.25, max(0.0, deadline - time.monotonic())))
    out = dict(timeout_body)
    out["clob_order_service_timeout_confirm_attempts"] = attempts
    out["clob_order_service_timeout_confirm_sec"] = float(confirm_sec)
    if last_body:
        out["clob_order_service_timeout_confirm_last"] = last_body
    return False, out


def _clob_order_service_async_ack_confirm_sec() -> float:
    configured = _env_float("PM_CLOB_ORDER_SERVICE_ASYNC_ACK_CONFIRM_SEC")
    if configured is None or not math.isfinite(configured) or configured < 0:
        configured = 2.4
    return max(0.0, min(float(configured), 3.0))


def _clob_order_service_async_ack_confirm(
    *,
    service_url: str,
    idempotency_key: str,
    pending_body: MutableMapping[str, Any],
    deadline_sec: float,
) -> Tuple[bool, bool, Dict[str, Any]]:
    key = str(idempotency_key or "").strip()
    if not key or deadline_sec <= 0:
        return False, False, dict(pending_body)
    url = f"{service_url}/order-status"
    deadline = time.monotonic() + float(deadline_sec)
    attempts = 0
    last_body: Dict[str, Any] = {}
    while time.monotonic() <= deadline:
        attempts += 1
        remaining = max(0.03, deadline - time.monotonic())
        try:
            response = requests.get(
                url,
                params={"idempotency_key": key},
                timeout=(0.15, min(0.35, remaining)),
            )
            try:
                body = response.json()
                if not isinstance(body, dict):
                    body = {"response": body}
            except Exception:
                body = {"stdout": str(response.text or "").strip()}
            body["clob_order_service"] = True
            body["clob_order_service_url"] = service_url
            body["clob_order_service_status_http_status"] = int(response.status_code)
            body["clob_order_service_async_ack_confirm_attempts"] = attempts
            last_body = dict(body)
            order_id = str(body.get("orderID") or body.get("orderId") or "").strip()
            if response.status_code < 400 and body.get("pending") is not True:
                body.setdefault("source", "clob_order_service")
                body["clob_order_service_async_ack_recovered"] = True
                body["clob_order_service_original_pending"] = True
                if order_id and body.get("ok") is not False:
                    return True, True, body
                if body.get("ok") is False or str(body.get("error") or "").strip():
                    return True, False, body
        except requests.exceptions.RequestException as exc:
            last_body = {
                "error": "clob_order_service_status_request_failed",
                "error_detail": str(exc),
                "clob_order_service": True,
                "clob_order_service_url": service_url,
                "clob_order_service_async_ack_confirm_attempts": attempts,
            }
        time.sleep(min(0.08, max(0.0, deadline - time.monotonic())))
    try:
        attempts += 1
        response = requests.get(
            url,
            params={"idempotency_key": key},
            timeout=(0.1, 0.25),
        )
        try:
            body = response.json()
            if not isinstance(body, dict):
                body = {"response": body}
        except Exception:
            body = {"stdout": str(response.text or "").strip()}
        body["clob_order_service"] = True
        body["clob_order_service_url"] = service_url
        body["clob_order_service_status_http_status"] = int(response.status_code)
        body["clob_order_service_async_ack_confirm_attempts"] = attempts
        last_body = dict(body)
        order_id = str(body.get("orderID") or body.get("orderId") or "").strip()
        if response.status_code < 400 and body.get("pending") is not True:
            body.setdefault("source", "clob_order_service")
            body["clob_order_service_async_ack_recovered"] = True
            body["clob_order_service_original_pending"] = True
            body["clob_order_service_async_ack_final_probe"] = True
            if order_id and body.get("ok") is not False:
                return True, True, body
            if body.get("ok") is False or str(body.get("error") or "").strip():
                return True, False, body
    except requests.exceptions.RequestException as exc:
        last_body = {
            "error": "clob_order_service_status_request_failed",
            "error_detail": str(exc),
            "clob_order_service": True,
            "clob_order_service_url": service_url,
            "clob_order_service_async_ack_confirm_attempts": attempts,
        }
    out = dict(pending_body)
    out["clob_order_service_async_ack_confirm_attempts"] = attempts
    out["clob_order_service_async_ack_confirm_sec"] = float(deadline_sec)
    if last_body:
        out["clob_order_service_async_ack_confirm_last"] = last_body
    return False, False, out


def _run_clob_order_service_place_order(
    payload: Mapping[str, Any],
    *,
    timeout_sec: float,
) -> Tuple[bool, Dict[str, Any]]:
    service_url = _clob_order_service_url()
    direct_target_service_order = bool(isinstance(payload, Mapping) and payload.get("direct_target_order_context"))
    if not service_url:
        return False, {
            "error": "clob_order_service_url_missing",
            "clob_order_service": True,
        }
    url = f"{service_url}/place-order"
    started = time.monotonic()
    request_timeout = _clob_order_service_request_timeout_sec(timeout_sec)
    try:
        response = requests.post(
            url,
            json=dict(payload),
            timeout=(0.25, request_timeout),
        )
    except requests.exceptions.ConnectTimeout as exc:
        return False, {
            "error": "clob_order_service_unavailable",
            "error_detail": f"connect_timeout:{exc}",
            "clob_order_service": True,
            "clob_order_service_url": service_url,
            "clob_order_service_ms": round((time.monotonic() - started) * 1000.0, 3),
        }
    except requests.exceptions.ConnectionError as exc:
        return False, {
            "error": "clob_order_service_unavailable",
            "error_detail": str(exc),
            "clob_order_service": True,
            "clob_order_service_url": service_url,
            "clob_order_service_ms": round((time.monotonic() - started) * 1000.0, 3),
        }
    except requests.exceptions.ReadTimeout as exc:
        timeout_body: Dict[str, Any] = {
            "error": "clob_order_service_timeout",
            "error_detail": f"read_timeout:{exc}",
            "timeout_expired": True,
            "timeout_sec": float(request_timeout),
            "clob_order_service": True,
            "clob_order_service_url": service_url,
            "reconcile_required": True,
            "clob_order_service_ms": round((time.monotonic() - started) * 1000.0, 3),
        }
        if (
            direct_target_service_order
            and str(dict(payload).get("idempotency_key") or "").strip()
            and _clob_order_service_direct_timeout_defer_confirm()
        ):
            timeout_body["clob_order_service_timeout_confirm_deferred"] = True
            timeout_body["order_submit_pending_confirmation"] = True
            timeout_body["order_submit_pending_reason"] = "clob_order_service_read_timeout_deferred"
            return False, timeout_body
        ok_confirm, confirm_body = _clob_order_service_timeout_confirm(
            service_url=service_url,
            idempotency_key=str(dict(payload).get("idempotency_key") or ""),
            timeout_body=timeout_body,
        )
        if ok_confirm:
            confirm_body["clob_order_service_ms"] = round((time.monotonic() - started) * 1000.0, 3)
            return True, confirm_body
        return False, confirm_body
    except requests.exceptions.RequestException as exc:
        return False, {
            "error": "clob_order_service_request_failed",
            "error_detail": str(exc),
            "clob_order_service": True,
            "clob_order_service_url": service_url,
            "clob_order_service_ms": round((time.monotonic() - started) * 1000.0, 3),
        }

    elapsed_ms = round((time.monotonic() - started) * 1000.0, 3)
    try:
        body = response.json()
        if not isinstance(body, dict):
            body = {"response": body}
    except Exception:
        body = {"stdout": str(response.text or "").strip()}
    body["clob_order_service"] = True
    body["clob_order_service_url"] = service_url
    body["clob_order_service_http_status"] = int(response.status_code)
    body["clob_order_service_ms"] = elapsed_ms
    if response.status_code == 404:
        body.setdefault("error", "clob_order_service_not_found")
        return False, body
    if response.status_code >= 400:
        body.setdefault("error", f"clob_order_service_http_{response.status_code}")
        return False, body
    if _clob_order_service_submit_pending(body):
        confirm_budget = min(
            _clob_order_service_async_ack_confirm_sec(),
            max(0.0, float(request_timeout) - (elapsed_ms / 1000.0) - 0.05),
        )
        final, ok_final, final_body = _clob_order_service_async_ack_confirm(
            service_url=service_url,
            idempotency_key=str(body.get("idempotency_key") or dict(payload).get("idempotency_key") or ""),
            pending_body=body,
            deadline_sec=confirm_budget,
        )
        if final:
            final_body["clob_order_service_ms"] = round((time.monotonic() - started) * 1000.0, 3)
            return bool(ok_final), final_body
        body = final_body
        body.setdefault("error", "clob_order_service_submit_pending")
        return False, body
    if body.get("ok") is False or not body.get("orderID"):
        body.setdefault("error", "clob_order_service_missing_order_id")
        return False, body
    body.setdefault("source", "clob_order_service")
    return True, body


def _resolve_exit_liquidity_price(
    preferred_price: Any,
    best_bid: Any,
    best_ask: Any,
    *,
    allow_ask_fallback: bool,
) -> Tuple[Optional[float], bool]:
    preferred_val = to_float(preferred_price)
    if (
        preferred_val is not None
        and math.isfinite(preferred_val)
        and preferred_val > TIME_EDGE_Q_EPS
    ):
        return float(preferred_val), False
    bid_val = to_float(best_bid)
    if bid_val is not None and math.isfinite(bid_val) and bid_val > TIME_EDGE_Q_EPS:
        return float(bid_val), False
    ask_val = to_float(best_ask)
    if (
        allow_ask_fallback
        and ask_val is not None
        and math.isfinite(ask_val)
        and ask_val > TIME_EDGE_Q_EPS
    ):
        return float(ask_val), True
    return None, False


def _run_node_order(
    action: str,
    token_id: str,
    side: str,
    price: Optional[float] = None,
    size: Optional[float] = None,
    order_type: Optional[str] = None,
    amount: Optional[float] = None,
    tick_size: Optional[float] = None,
    neg_risk: Optional[bool] = None,
    order_context: Optional[Mapping[str, Any]] = None,
    post_only: Optional[bool] = None,
) -> Tuple[bool, Dict[str, Any]]:
    ensure_system_proxy_settings()
    script_path = Path(AUTO_TRADE_SCRIPT)
    if not script_path.exists():
        return False, {"error": f"script_missing:{script_path}"}
    if not token_id:
        return False, {"error": "missing_token"}
    node_bin = _resolve_node_bin()
    if node_bin != "node" and not Path(node_bin).exists():
        return False, {"error": f"node_missing:{node_bin}"}
    side_upper = str(side or "").strip().upper()
    context_ref = dict(order_context or {}) if isinstance(order_context, Mapping) else {}
    target_realization_v3_maker = bool(
        action == "place-order"
        and (
            str(context_ref.get("target_realization_v3_plan_id") or "").strip()
            or context_ref.get("target_realization_maker_only") is True
        )
    )
    if target_realization_v3_maker:
        order_type = "GTC"
        post_only = True
    effective_post_only = bool(post_only)
    normalized_price = price
    buy_notional_cap_usdc: Optional[float] = None
    buy_size_cap_price: Optional[float] = None
    order_cap_meta: Dict[str, Any] = {}
    service_tick_size = to_float(tick_size)
    if service_tick_size is not None and (
        not math.isfinite(service_tick_size) or service_tick_size <= 0
    ):
        service_tick_size = None
    service_neg_risk: Optional[bool] = bool(neg_risk) if isinstance(neg_risk, bool) else None
    cmd = [node_bin, str(script_path), action, "--token-id", token_id, "--side", side]
    direct_target_order = bool(
        action == "place-order" and _env_bool("PM_AUTO_TRADE_DIRECT_JOB_CONTEXT", False)
    )
    direct_target_exit_order = False
    if action == "place-order":
        eff_type_for_timeout = (order_type or AUTO_TRADE_ORDER_TYPE).strip().upper()
        direct_target_exit_order = bool(
            direct_target_order and eff_type_for_timeout in {"FOK", "FAK"} and side_upper == "SELL"
        )
    order_execution_context = _order_execution_context_from_order_context(
        action=action,
        side_upper=side_upper,
        direct_target_order=direct_target_order,
        direct_target_exit_order=direct_target_exit_order,
        order_context=order_context,
    )
    if action == "place-order":
        effective_order_type = (order_type or AUTO_TRADE_ORDER_TYPE).strip().upper()
        if size is None and amount is None:
            return False, {"error": "missing_size_or_amount"}
        if normalized_price is None and effective_order_type in {"GTC", "GTD"}:
            return False, {"error": "missing_price"}
        if normalized_price is not None:
            normalized_price_val, was_clamped = _normalize_place_order_price(normalized_price)
            if normalized_price_val is None:
                return False, {"error": "invalid_price"}
            if was_clamped:
                print(
                    "[auto-trade] order price clamped "
                    f"{float(normalized_price):.6f} -> {normalized_price_val:.6f} "
                    f"(side={side}, token={token_id}, action={action})"
                )
            normalized_price = normalized_price_val
            cmd += ["--price", f"{normalized_price:.6f}"]
        if target_realization_v3_maker:
            expected_passive_price = to_float(context_ref.get("passive_limit_price"))
            if expected_passive_price is None:
                expected_passive_price = to_float(
                    context_ref.get("best_bid")
                    if side_upper == "BUY"
                    else context_ref.get("best_ask")
                )
            expected_passive_norm, _ = _normalize_place_order_price(expected_passive_price)
            if expected_passive_norm is None:
                return False, {"error": "target_realization_v3_passive_quote_missing"}
            if normalized_price is None or abs(
                float(normalized_price) - float(expected_passive_norm)
            ) > TIME_EDGE_Q_EPS:
                return False, {
                    "error": "target_realization_v3_passive_price_mismatch",
                    "expected_price": float(expected_passive_norm),
                    "actual_price": normalized_price,
                }
        if side_upper == "BUY":
            buy_notional_cap_usdc = _entry_order_notional_cap_usdc()
            if (
                buy_notional_cap_usdc is not None
                and math.isfinite(buy_notional_cap_usdc)
                and buy_notional_cap_usdc > TIME_EDGE_Q_EPS
            ):
                cap_changed = False
                market_amount_aligned = False
                amount_before = to_float(amount)
                size_before = to_float(size)
                price_for_size = to_float(normalized_price)
                if effective_order_type in {"FOK", "FAK"}:
                    market_amount_before = (
                        amount_before
                        if amount_before is not None and math.isfinite(amount_before)
                        else size_before
                    )
                    if (
                        market_amount_before is not None
                        and math.isfinite(market_amount_before)
                        and market_amount_before > TIME_EDGE_Q_EPS
                    ):
                        market_amount_after = min(
                            float(market_amount_before),
                            float(buy_notional_cap_usdc),
                        )
                        if market_amount_after + TIME_EDGE_Q_EPS < float(market_amount_before):
                            cap_changed = True
                        if (
                            size_before is None
                            or not math.isfinite(size_before)
                            or abs(float(size_before) - float(market_amount_after)) > TIME_EDGE_Q_EPS
                        ):
                            market_amount_aligned = True
                        if (
                            amount_before is None
                            or not math.isfinite(amount_before)
                            or abs(float(amount_before) - float(market_amount_after)) > TIME_EDGE_Q_EPS
                        ):
                            market_amount_aligned = True
                        size = float(market_amount_after)
                        amount = float(market_amount_after)
                else:
                    if (
                        amount_before is not None
                        and math.isfinite(amount_before)
                        and amount_before > buy_notional_cap_usdc + TIME_EDGE_Q_EPS
                    ):
                        amount = float(buy_notional_cap_usdc)
                        cap_changed = True
                    if (
                        size_before is not None
                        and math.isfinite(size_before)
                        and size_before > TIME_EDGE_Q_EPS
                        and price_for_size is not None
                        and math.isfinite(price_for_size)
                        and price_for_size > TIME_EDGE_Q_EPS
                    ):
                        buy_size_cap_price = float(price_for_size)
                        size_cap = float(buy_notional_cap_usdc) / float(price_for_size)
                        if size_before > size_cap + TIME_EDGE_Q_EPS:
                            size = max(0.0, float(size_cap))
                            cap_changed = True
                if cap_changed or market_amount_aligned:
                    order_cap_meta = {
                        "order_notional_cap_usdc": float(buy_notional_cap_usdc),
                        "order_cap_applied": bool(cap_changed),
                        "order_market_amount_aligned": bool(market_amount_aligned),
                        "order_amount_before_cap": amount_before,
                        "order_amount_after_cap": to_float(amount),
                        "order_size_before_cap": size_before,
                        "order_size_after_cap": to_float(size),
                        "order_size_cap_price": buy_size_cap_price,
                    }
                    print(
                        "[auto-trade] BUY order amount normalized "
                        f"cap={float(buy_notional_cap_usdc):.4f} "
                        f"amount={amount_before}->{to_float(amount)} "
                        f"size={size_before}->{to_float(size)} "
                        f"price={buy_size_cap_price if buy_size_cap_price is not None else '—'} "
                        f"token={token_id}"
                    )
        if size is not None:
            size_val = to_float(size)
            if size_val is None or not math.isfinite(size_val) or size_val <= 0:
                return False, {"error": "invalid_size"}
            size = float(size_val)
            cmd += ["--size", f"{size:.6f}"]
        if amount is not None:
            amount_val = to_float(amount)
            if amount_val is None or not math.isfinite(amount_val) or amount_val <= 0:
                return False, {"error": "invalid_amount"}
            amount = float(amount_val)
            cmd += ["--amount", f"{amount:.6f}"]
        cmd += ["--order-type", effective_order_type]
        if effective_post_only:
            cmd += ["--post-only", "true"]
        if direct_target_order:
            tick_size_val = to_float(tick_size)
            if tick_size_val is None or not math.isfinite(tick_size_val) or tick_size_val <= 0:
                tick_size_val = _env_float("PM_CLOB_DEFAULT_TICK_SIZE")
            if tick_size_val is None or not math.isfinite(tick_size_val) or tick_size_val <= 0:
                tick_size_val = 0.01
            neg_risk_val = bool(neg_risk) if isinstance(neg_risk, bool) else _env_bool(
                "PM_CLOB_DEFAULT_NEG_RISK",
                True,
            )
            service_tick_size = float(tick_size_val)
            service_neg_risk = bool(neg_risk_val)
            cmd += ["--tick-size", f"{float(tick_size_val):.6f}".rstrip("0").rstrip(".")]
            cmd += ["--neg-risk", "true" if neg_risk_val else "false"]
    if _auto_trade_dry_run_enabled():
        payload = {"dry_run": True, "status": "dry_run", "cmd": cmd}
        if action == "place-order":
            payload.update(order_execution_context)
            payload["post_only"] = bool(effective_post_only)
            payload["maker_only"] = bool(target_realization_v3_maker)
        if order_cap_meta:
            payload.update(order_cap_meta)
        return True, payload

    if action == "place-order" and not _clob_order_service_enabled():
        return False, {
            "error": "durable_clob_order_service_required",
            "reconcile_required": False,
        }

    env = _build_node_env()
    if action == "place-order":
        eff_type = (order_type or AUTO_TRADE_ORDER_TYPE).strip().upper()
        if eff_type in {"FOK", "FAK"}:
            env["PM_ALLOW_MARKET_ORDERS"] = "1"
    timeout_sec = float(AUTO_TRADE_TIMEOUT)
    fast_exit_direct = False
    cancel_order = action == "cancel-orders"
    if direct_target_order:
        timeout_sec = (
            _direct_target_exit_order_timeout_sec()
            if direct_target_exit_order
            else _direct_target_order_timeout_sec()
        )
        for key, value in _direct_target_order_env_overrides(
            timeout_sec=timeout_sec,
            exit_order=direct_target_exit_order,
        ).items():
            env[str(key)] = str(value)
        if str(env.get("PM_CLOB_FAST_ALLOW_PROXY_FALLBACK") or "").strip().lower() in {
            "1",
            "true",
            "yes",
            "on",
        }:
            env["PM_CLOB_FORCE_DIRECT"] = "0"
            if (
                str(env.get("PM_CLOB_FORCE_PROXY") or "").strip().lower()
                in {"1", "true", "yes", "on"}
                or _env_bool("PM_CLOB_FORCE_PROXY", False)
                or _env_bool("PM_AUTO_TRADE_DIRECT_FORCE_PROXY_ON_FALLBACK", True)
            ):
                env["PM_CLOB_FORCE_PROXY"] = "1"
                env["PM_CLOB_DIRECT_FIRST"] = "0"
                env["PM_SCAN_FORCE_DIRECT"] = "0"
            else:
                env["PM_CLOB_FORCE_PROXY"] = "0"
            proxy_url = env.get("HTTPS_PROXY") or env.get("HTTP_PROXY") or env.get("ALL_PROXY")
            if not proxy_url:
                fallback_proxy = _detect_local_http_proxy_url()
                if fallback_proxy:
                    env["HTTP_PROXY"] = fallback_proxy
                    env["HTTPS_PROXY"] = fallback_proxy
                    env["http_proxy"] = fallback_proxy
                    env["https_proxy"] = fallback_proxy
                    env["GLOBAL_AGENT_HTTP_PROXY"] = fallback_proxy
    if action == "place-order":
        eff_type = (order_type or AUTO_TRADE_ORDER_TYPE).strip().upper()
        if eff_type in {"FOK", "FAK"} and side_upper == "SELL":
            exit_timeout_sec = _env_float("PM_AUTO_TRADE_EXIT_NODE_TIMEOUT_SEC")
            if (
                exit_timeout_sec is None
                or not math.isfinite(exit_timeout_sec)
                or exit_timeout_sec <= 0
            ):
                exit_timeout_sec = 15.0
            timeout_sec = max(5.0, min(float(exit_timeout_sec), float(AUTO_TRADE_TIMEOUT)))
            fast_exit_direct = True
            if direct_target_order:
                timeout_sec = _direct_target_exit_order_timeout_sec()
    if side_upper == "SELL" and action == "cancel-orders":
        fast_exit_direct = True
    if cancel_order:
        timeout_sec = _cancel_order_timeout_sec()
    if direct_target_order:
        direct_proxy_fallback = str(env.get("PM_CLOB_FAST_ALLOW_PROXY_FALLBACK") or "").strip().lower() in {
            "1",
            "true",
            "yes",
            "on",
        }
        direct_min_timeout_ms = 800
        direct_configured_max_timeout_ms = _coerce_int(
            env.get("PM_CLOB_PLACE_ORDER_TIMEOUT_CAP_MS"),
            0,
        )
        if direct_configured_max_timeout_ms <= 0:
            direct_configured_max_timeout_ms = 3500
        direct_max_timeout_ms = (
            90000
            if direct_target_exit_order
            else (
                15000
                if direct_proxy_fallback
                else max(3500, min(int(direct_configured_max_timeout_ms), 15000))
            )
        )
        direct_proxy_forced = bool(
            direct_proxy_fallback
            and _env_bool("PM_AUTO_TRADE_DIRECT_FORCE_PROXY_ON_FALLBACK", True)
        )
        direct_hard_timeout_min_ms = (
            1500
            if direct_target_exit_order
            else (1500 if direct_proxy_forced else (6000 if direct_proxy_fallback else 1250))
        )
        direct_hard_timeout_padding_ms = (
            5000
            if direct_target_exit_order
            else (1000 if direct_proxy_forced else (12000 if direct_proxy_fallback else 1000))
        )
        _apply_clob_fast_direct_env_defaults(
            env,
            timeout_sec=timeout_sec,
            hard_timeout_ms_key="PM_CLOB_PLACE_ORDER_HARD_TIMEOUT_MS",
            min_timeout_ms=direct_min_timeout_ms,
            max_timeout_ms=direct_max_timeout_ms,
            hard_timeout_min_ms=direct_hard_timeout_min_ms,
            hard_timeout_padding_ms=direct_hard_timeout_padding_ms,
        )
        if not direct_target_exit_order:
            hard_timeout_candidates = [
                _coerce_int(env.get("PM_CLOB_PLACE_ORDER_HARD_TIMEOUT_MS"), 0),
                _coerce_int(env.get("PM_CLOB_COMMAND_HARD_TIMEOUT_MS"), 0),
            ]
            hard_timeout_candidates = [value for value in hard_timeout_candidates if value > 0]
            operation_timeout_ms = _coerce_int(
                env.get("PM_CLOB_PLACE_ORDER_OPERATION_TIMEOUT_MS"),
                0,
            )
            if hard_timeout_candidates and operation_timeout_ms > 0:
                operation_timeout_cap_ms = max(1000, min(hard_timeout_candidates) - 250)
                if operation_timeout_ms > operation_timeout_cap_ms:
                    env["PM_CLOB_PLACE_ORDER_OPERATION_TIMEOUT_MS"] = str(operation_timeout_cap_ms)
        timeout_sec = _cap_node_outer_timeout_to_hard_timeout(
            timeout_sec,
            env,
            "PM_CLOB_PLACE_ORDER_HARD_TIMEOUT_MS",
            "PM_CLOB_COMMAND_HARD_TIMEOUT_MS",
            padding_sec=2.5 if not direct_target_exit_order else 0.75,
        )
    elif cancel_order:
        env.setdefault("PM_CLOB_FAST_ALLOW_PROXY_FALLBACK", "1")
        env.setdefault("PM_CLOB_RETRY_MAX", "2")
        _apply_clob_fast_direct_env_defaults(
            env,
            timeout_sec=timeout_sec,
            hard_timeout_ms_key="PM_CLOB_CANCEL_ORDERS_HARD_TIMEOUT_MS",
            min_timeout_ms=3000,
            max_timeout_ms=10000,
            hard_timeout_min_ms=4000,
            hard_timeout_padding_ms=1000,
        )
        timeout_sec = _cap_node_outer_timeout_to_hard_timeout(
            timeout_sec,
            env,
            "PM_CLOB_CANCEL_ORDERS_HARD_TIMEOUT_MS",
            "PM_CLOB_COMMAND_HARD_TIMEOUT_MS",
        )
    elif fast_exit_direct:
        _apply_clob_fast_direct_env_defaults(env, timeout_sec=timeout_sec)
        timeout_sec = _cap_node_outer_timeout_to_hard_timeout(
            timeout_sec,
            env,
            "PM_CLOB_COMMAND_HARD_TIMEOUT_MS",
            "PM_CLOB_HARD_TIMEOUT_MS",
        )

    def _attach_order_submit_timing(
        payload_obj: Dict[str, Any],
        *,
        order_submit_started_at: str,
        order_submit_started_mono: float,
    ) -> Dict[str, Any]:
        if action != "place-order" or not isinstance(payload_obj, dict):
            return payload_obj
        elapsed_ms = max(0.0, (time.monotonic() - order_submit_started_mono) * 1000.0)
        payload_obj.setdefault("order_submit_started_at", order_submit_started_at)
        payload_obj["order_submit_completed_at"] = utc_now_iso_ms()
        payload_obj["order_submit_ms"] = round(float(elapsed_ms), 3)
        payload_obj["order_submit_outer_timeout_sec"] = float(timeout_sec)
        for ctx_key, ctx_value in order_execution_context.items():
            if ctx_value is not None and str(ctx_value).strip():
                payload_obj.setdefault(ctx_key, ctx_value)
        if str(payload_obj.get("idempotency_key") or "").strip():
            payload_obj.setdefault(
                "order_intent_id",
                str(payload_obj.get("idempotency_key") or "").strip(),
            )
        return payload_obj

    def _run_clob_order_service_once() -> Tuple[bool, Dict[str, Any]]:
        order_submit_started_at = utc_now_iso_ms() if action == "place-order" else ""
        order_submit_started_mono = time.monotonic()
        eff_type_for_service = (order_type or AUTO_TRADE_ORDER_TYPE).strip().upper()
        service_payload: Dict[str, Any] = {
            "token_id": str(token_id),
            "side": side_upper,
            "order_type": eff_type_for_service,
            "price": normalized_price,
            "size": size,
            "amount": amount,
            "allow_market": eff_type_for_service in {"FOK", "FAK"},
            "direct_target_order_context": bool(direct_target_order),
            "direct_target_exit_order": bool(direct_target_exit_order),
            "post_only": bool(effective_post_only),
            "maker_only": bool(target_realization_v3_maker),
        }
        service_payload.update(order_execution_context)
        if (
            direct_target_order
            and not direct_target_exit_order
            and _env_bool("PM_CLOB_ORDER_SERVICE_DIRECT_ENTRY_ASYNC_ACK", True)
        ):
            service_payload["async_ack"] = True
        if isinstance(order_context, Mapping):
            for ctx_key in (
                "slug",
                "event_date",
                "outcome",
                "outcome_side",
                "intent_action",
                "strategy_source",
                "posterior_target_source",
                "target_bucket",
                "posterior_target_bucket",
                "ssot_target_bucket",
                "posterior_target_fact_id",
                "posterior_target_fact_as_of",
                "entry_order_submit_source",
                "order_execution_domain",
                "execution_domain",
                "order_execution_source",
                "order_execution_reason",
                "order_execution_context_version",
                "order_intent_action",
                "manual_confirm_source",
                "order_intent_id",
                "sequential_bayes_execution_contract_id",
                "signal_to_order_slo_deadline_at",
                "signal_to_order_hard_deadline_at",
                "observation_to_order_slo_deadline_at",
                "observation_to_order_hard_deadline_at",
            ):
                ctx_value = order_context.get(ctx_key)
                if ctx_value is not None and str(ctx_value).strip():
                    service_payload[ctx_key] = ctx_value
        if service_tick_size is not None and math.isfinite(service_tick_size) and service_tick_size > 0:
            service_payload["tick_size"] = float(service_tick_size)
        if service_neg_risk is not None:
            service_payload["neg_risk"] = bool(service_neg_risk)
        service_payload["idempotency_key"] = (
            _clob_order_service_direct_target_idempotency_key(service_payload)
            or _clob_order_service_idempotency_key(service_payload)
        )
        service_payload["order_intent_id"] = str(
            service_payload.get("order_intent_id")
            or context_ref.get("order_intent_id")
            or service_payload["idempotency_key"]
        ).strip()
        ok_service, service_result = _run_clob_order_service_place_order(
            service_payload,
            timeout_sec=timeout_sec,
        )
        if isinstance(service_result, dict):
            service_result.setdefault("cmd", ["clob_order_service", "place-order"])
            service_result.setdefault("clob_order_service_request", {
                key: value
                for key, value in service_payload.items()
                if key not in {"idempotency_key"}
            })
            service_result.setdefault("idempotency_key", service_payload["idempotency_key"])
            service_result.setdefault("order_intent_id", service_payload["order_intent_id"])
        return ok_service, _attach_order_submit_timing(
            service_result,
            order_submit_started_at=order_submit_started_at,
            order_submit_started_mono=order_submit_started_mono,
        )

    def _run_once(cmd_args: List[str]) -> Tuple[bool, Dict[str, Any]]:
        order_submit_started_at = utc_now_iso_ms() if action == "place-order" else ""
        order_submit_started_mono = time.monotonic()

        try:
            res = _run_node_subprocess(
                cmd_args,
                env=env,
                timeout=timeout_sec,
                retries_on_errno24=1,
            )
        except Exception as exc:
            return False, _attach_order_submit_timing(
                _exec_failed_payload(exc),
                order_submit_started_at=order_submit_started_at,
                order_submit_started_mono=order_submit_started_mono,
            )
        if res.returncode != 0:
            err_detail = _extract_node_error_detail(res.stderr, res.stdout)
            payload = {
                "error": "exec_nonzero",
                "stderr": res.stderr.strip(),
                "stdout": res.stdout.strip(),
            }
            if err_detail:
                payload["error_detail"] = err_detail
            return False, _attach_order_submit_timing(
                payload,
                order_submit_started_at=order_submit_started_at,
                order_submit_started_mono=order_submit_started_mono,
            )
        payload = None
        for line in (res.stdout or "").splitlines():
            line = line.strip()
            if not line or not line.startswith("{") or not line.endswith("}"):
                continue
            try:
                payload = json.loads(line)
                break
            except json.JSONDecodeError:
                continue
        if payload is None:
            payload = {"stdout": res.stdout.strip()}
        return True, _attach_order_submit_timing(
            payload,
            order_submit_started_at=order_submit_started_at,
            order_submit_started_mono=order_submit_started_mono,
        )

    if action == "place-order":
        ok, payload = _run_clob_order_service_once()
        if order_cap_meta and isinstance(payload, dict):
            payload.update(order_cap_meta)
        if direct_target_order and isinstance(payload, dict):
            payload.setdefault("direct_target_order_context", True)
            payload.setdefault("direct_target_order_timeout_sec", float(timeout_sec))
        return ok, payload

    ok, payload = _run_once(cmd)
    if ok:
        if order_cap_meta:
            payload.update(order_cap_meta)
        return True, payload
    if isinstance(payload, dict):
        if order_cap_meta:
            payload.update(order_cap_meta)

    return False, payload


def _parse_clob_balance_size(raw_value: Any) -> Optional[float]:
    if raw_value is None:
        return None
    raw_text = str(raw_value).strip()
    if not raw_text:
        return None
    try:
        val = float(raw_text)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(val):
        return None
    if re.match(r"^-?\d+$", raw_text):
        decimals = _env_int("PM_CLOB_TOKEN_DECIMALS")
        if decimals is None or decimals < 0 or decimals > 18:
            decimals = 6
        scale = 10 ** decimals
        if scale > 0:
            return val / scale
    return val


def _resolve_conditional_available_size(payload: Any) -> Optional[float]:
    if not isinstance(payload, dict):
        return None
    balance = _parse_clob_balance_size(payload.get("balance"))
    allowance = _parse_clob_balance_size(payload.get("allowance"))
    balance_allowance = _parse_clob_balance_size(
        payload.get("balance_allowance") if payload.get("balance_allowance") is not None else payload.get("balanceAllowance")
    )
    values = []
    for value in (balance_allowance, balance, allowance):
        if value is None or not math.isfinite(value):
            continue
        values.append(max(0.0, float(value)))
    if not values:
        return None
    return min(values)


def _run_node_balance(
    token_id: str = "",
    refresh: bool = True,
    asset_type: str = "CONDITIONAL",
) -> Tuple[bool, Dict[str, Any]]:
    if ACCOUNT_REQUESTS_DISABLED or _env_bool("PM_AUTO_TRADE_BALANCE_DISABLED", False):
        return False, {"error": "balance_disabled"}
    ensure_system_proxy_settings()
    script_path = Path(AUTO_TRADE_SCRIPT)
    if not script_path.exists():
        return False, {"error": f"script_missing:{script_path}"}
    asset_type_u = str(asset_type or "CONDITIONAL").strip().upper()
    if asset_type_u not in {"CONDITIONAL", "COLLATERAL"}:
        asset_type_u = "CONDITIONAL"
    if asset_type_u == "CONDITIONAL" and not token_id:
        return False, {"error": "missing_token"}
    node_bin = _resolve_node_bin()
    if node_bin != "node" and not Path(node_bin).exists():
        return False, {"error": f"node_missing:{node_bin}"}
    cmd = [
        node_bin,
        str(script_path),
        "balance",
        "--asset-type",
        asset_type_u,
    ]
    if token_id:
        cmd += ["--token-id", token_id]
    if refresh:
        cmd += ["--refresh", "1"]
    if _auto_trade_dry_run_enabled():
        return True, {"dry_run": True, "cmd": cmd}
    try:
        env = _build_node_env()
        res = _run_node_subprocess(
            cmd,
            env=env,
            timeout=AUTO_TRADE_TIMEOUT,
            retries_on_errno24=1,
        )
    except Exception as exc:
        return False, _exec_failed_payload(exc)
    if res.returncode != 0:
        err_detail = _extract_node_error_detail(res.stderr, res.stdout)
        payload = {
            "error": "exec_nonzero",
            "stderr": res.stderr.strip(),
            "stdout": res.stdout.strip(),
        }
        if err_detail:
            payload["error_detail"] = err_detail
        return False, _normalize_errno24_payload(payload)
    payload = None
    for line in (res.stdout or "").splitlines():
        line = line.strip()
        if not line or not line.startswith("{") or not line.endswith("}"):
            continue
        try:
            payload = json.loads(line)
            break
        except json.JSONDecodeError:
            continue
    if payload is None:
        payload = {"stdout": res.stdout.strip()}
    if isinstance(payload, dict) and payload.get("ok") is False:
        return False, _normalize_errno24_payload(payload)
    return True, payload


def _resolve_collateral_available_usdc(payload: Any) -> Optional[float]:
    if not isinstance(payload, dict):
        return None

    components = _parse_collateral_balance_components(payload)
    values: List[float] = []
    for val in (
        components.get("balance_allowance"),
        components.get("balance"),
        components.get("allowance"),
    ):
        if val is None or not math.isfinite(val):
            continue
        values.append(max(0.0, float(val)))
    if not values:
        return None
    return min(values)


def _parse_collateral_balance_components(payload: Any) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return {
            "balance": None,
            "allowance": None,
            "balance_allowance": None,
            "allowances_map": {},
            "allowance_max": None,
        }

    def _parse_amount(raw_value: Any) -> Optional[float]:
        if raw_value is None:
            return None
        raw_text = str(raw_value).strip()
        if not raw_text:
            return None
        try:
            num = float(raw_text)
        except (TypeError, ValueError):
            return None
        if not math.isfinite(num):
            return None
        if re.fullmatch(r"-?\d+", raw_text):
            return num / 1_000_000.0
        return num

    def _extract_max_amount(raw_value: Any) -> Optional[float]:
        vals: List[float] = []
        if isinstance(raw_value, dict):
            for v in raw_value.values():
                parsed = _extract_max_amount(v)
                if parsed is not None and math.isfinite(parsed):
                    vals.append(parsed)
        elif isinstance(raw_value, (list, tuple, set)):
            for v in raw_value:
                parsed = _extract_max_amount(v)
                if parsed is not None and math.isfinite(parsed):
                    vals.append(parsed)
        else:
            parsed = _parse_amount(raw_value)
            if parsed is not None and math.isfinite(parsed):
                vals.append(parsed)
        if not vals:
            return None
        return max(max(vals), 0.0)

    balance = _extract_max_amount(
        payload.get("balance")
        if payload.get("balance") is not None
        else payload.get("available")
    )
    allowance = _extract_max_amount(payload.get("allowance"))
    allowances_map: Dict[str, float] = {}
    allowances_raw = payload.get("allowances")
    if isinstance(allowances_raw, dict):
        for key, val in allowances_raw.items():
            parsed = _extract_max_amount(val)
            if parsed is None or not math.isfinite(parsed):
                continue
            spender = str(key or "").strip().lower()
            if not spender:
                continue
            allowances_map[spender] = max(0.0, float(parsed))
    allowance_max = max(allowances_map.values()) if allowances_map else None
    if allowance is None:
        allowance = allowance_max
    balance_allowance = _extract_max_amount(
        payload.get("balance_allowance")
        if payload.get("balance_allowance") is not None
        else payload.get("balanceAllowance")
    )
    if (
        balance_allowance is None
        and balance is not None
        and allowance is not None
        and math.isfinite(balance)
        and math.isfinite(allowance)
    ):
        balance_allowance = min(max(0.0, float(balance)), max(0.0, float(allowance)))
    return {
        "balance": max(0.0, float(balance)) if balance is not None and math.isfinite(balance) else None,
        "allowance": max(0.0, float(allowance)) if allowance is not None and math.isfinite(allowance) else None,
        "balance_allowance": (
            max(0.0, float(balance_allowance))
            if balance_allowance is not None and math.isfinite(balance_allowance)
            else None
        ),
        "allowances_map": allowances_map,
        "allowance_max": (
            max(0.0, float(allowance_max))
            if allowance_max is not None and math.isfinite(allowance_max)
            else None
        ),
    }


def _classify_mirror_order_failure(
    *,
    payload_order: Optional[Dict[str, Any]],
    required_notional: Optional[float],
    collateral_balance_payload: Optional[Dict[str, Any]] = None,
    fallback_error: str = "",
) -> str:
    primary_parts: List[str] = []
    detail_parts: List[str] = []
    if isinstance(payload_order, dict):
        for key in ("error_detail", "error", "statusText"):
            val = payload_order.get(key)
            if val:
                primary_parts.append(str(val))
                detail_parts.append(str(val))
        for key in ("stderr", "stdout"):
            val = payload_order.get(key)
            if val:
                detail_parts.append(str(val))
    if fallback_error:
        primary_parts.append(str(fallback_error))
        detail_parts.append(str(fallback_error))
    primary_text = " ".join(primary_parts).strip()
    detail_text = " ".join(detail_parts).strip()
    lowered_primary = primary_text.lower()
    lowered = detail_text.lower()
    if "invalid amount" in lowered_primary and "min size" in lowered_primary:
        return "min_notional"
    owner_markers = (
        "owner mismatch",
        "owner_mismatch",
        "balance owner",
        "invalid signer",
        "signature mismatch",
    )
    if any(marker in lowered_primary for marker in owner_markers):
        return "owner_mismatch"
    if (
        ("orderbook" in lowered_primary and "does not exist" in lowered_primary)
        or "no orderbook" in lowered_primary
    ):
        return "orderbook_missing"
    insufficient_markers = (
        "not enough balance",
        "insufficient balance",
        "allowance",
        "insufficient funds",
    )
    if not any(marker in lowered for marker in insufficient_markers):
        if (
            ("orderbook" in lowered and "does not exist" in lowered)
            or "no orderbook" in lowered
        ):
            return "orderbook_missing"
        return primary_text or detail_text or "order_failed"
    comps = _parse_collateral_balance_components(collateral_balance_payload or {})
    balance = to_float(comps.get("balance"))
    allowance = to_float(comps.get("allowance"))
    balance_allowance = to_float(comps.get("balance_allowance"))
    req = to_float(required_notional)
    if req is not None and math.isfinite(req) and req > TIME_EDGE_Q_EPS:
        threshold = float(req) - TIME_EDGE_Q_EPS
        if balance is not None and math.isfinite(balance) and balance < threshold:
            return "balance_insufficient"
        if allowance is not None and math.isfinite(allowance) and allowance < threshold:
            return "allowance_insufficient"
        if balance_allowance is not None and math.isfinite(balance_allowance) and balance_allowance < threshold:
            if balance is not None and math.isfinite(balance) and balance >= threshold:
                return "allowance_insufficient"
            if allowance is not None and math.isfinite(allowance) and allowance >= threshold:
                return "balance_insufficient"
            return "allowance_insufficient"
        if (
            balance_allowance is not None
            and math.isfinite(balance_allowance)
            and balance_allowance >= threshold
        ):
            # API reports "not enough balance/allowance" while snapshot looks sufficient.
            # This is usually a short-lived reservation/available-balance mismatch, not
            # necessarily a signer/owner mismatch.
            return "balance_allowance_conflict"
    if "allowance" in lowered and "balance" not in lowered:
        return "allowance_insufficient"
    if "balance" in lowered and "allowance" not in lowered:
        return "balance_insufficient"
    if "allowance" in lowered:
        return "allowance_insufficient"
    return "balance_insufficient"


def _run_node_trades(
    env_override: Optional[Dict[str, str]] = None,
    timeout_override: Optional[float] = None,
) -> Tuple[bool, Dict[str, Any]]:
    ensure_system_proxy_settings()
    script_path = Path(AUTO_TRADE_SCRIPT)
    if not script_path.exists():
        return False, {"error": f"script_missing:{script_path}"}
    node_bin = _resolve_node_bin()
    if node_bin != "node" and not Path(node_bin).exists():
        return False, {"error": f"node_missing:{node_bin}"}
    cmd = [node_bin, str(script_path), "fetch-trades"]
    env = _build_node_env()
    if env_override:
        for key, value in env_override.items():
            env[str(key)] = str(value)
    _apply_clob_trade_env_defaults(env)
    timeout_val = timeout_override if timeout_override is not None else min(AUTO_TRADE_TIMEOUT, TRADE_SYNC_NODE_TIMEOUT)
    if timeout_val is None or not math.isfinite(timeout_val) or timeout_val <= 0:
        timeout_val = min(AUTO_TRADE_TIMEOUT, TRADE_SYNC_NODE_TIMEOUT)

    def _run_node_cmd(timeout: Optional[float]):
        return _run_node_subprocess(
            cmd,
            env=env,
            timeout=timeout,
            retries_on_errno24=1,
        )

    try:
        res = _run_node_cmd(timeout_val)
    except subprocess.TimeoutExpired as exc:
        retry_enabled = _env_bool("PM_TRADE_SYNC_NODE_TIMEOUT_RETRY", False)
        if not retry_enabled:
            return False, _exec_failed_payload(exc)
        fallback_timeout = max(timeout_val * 2, timeout_val + 60)
        fallback_timeout = min(fallback_timeout, timeout_val + 180)
        fallback_cap = _env_float("PM_TRADE_SYNC_NODE_TIMEOUT_FALLBACK_MAX")
        if (
            fallback_cap is not None
            and math.isfinite(fallback_cap)
            and fallback_cap > 0
        ):
            fallback_timeout = min(fallback_timeout, float(fallback_cap))
        print(
            f"[auto-trade] trade sync node timeout ({timeout_val}s); retrying with {fallback_timeout}s",
            file=sys.stderr,
            flush=True,
        )
        try:
            res = _run_node_cmd(fallback_timeout)
        except subprocess.TimeoutExpired as exc2:
            return False, _exec_failed_payload(exc2)
        except Exception as exc2:
            return False, _exec_failed_payload(exc2)
    except Exception as exc:
        return False, _exec_failed_payload(exc)
    if res.returncode != 0:
        err_detail = _extract_node_error_detail(res.stderr, res.stdout)
        payload = {
            "error": "exec_nonzero",
            "stderr": res.stderr.strip(),
            "stdout": res.stdout.strip(),
        }
        if err_detail:
            payload["error_detail"] = err_detail
        return False, _normalize_errno24_payload(payload)
    payload = None
    for line in (res.stdout or "").splitlines():
        line = line.strip()
        if not line or not line.startswith("{") or not line.endswith("}"):
            continue
        try:
            payload = json.loads(line)
            break
        except json.JSONDecodeError:
            continue
    if payload is None:
        payload = {"stdout": res.stdout.strip()}
    if isinstance(payload, dict) and payload.get("ok") is False:
        return False, _normalize_errno24_payload(payload)
    return True, payload


def _run_node_claim(max_per_loop: Optional[int] = None) -> Tuple[bool, Dict[str, Any]]:
    ensure_system_proxy_settings()
    script_path = Path(AUTO_TRADE_SCRIPT)
    if not script_path.exists():
        return False, {"error": f"script_missing:{script_path}"}
    node_bin = _resolve_node_bin()
    if node_bin != "node" and not Path(node_bin).exists():
        return False, {"error": f"node_missing:{node_bin}"}
    max_targets = int(max_per_loop or POLY_CLAIM_MAX_PER_LOOP or 2)
    if max_targets <= 0:
        max_targets = 1
    cmd = [node_bin, str(script_path), "claim", "--max", str(max_targets)]
    if _auto_trade_dry_run_enabled():
        cmd += ["--dry-run", "1"]
        return True, {"dry_run": True, "cmd": cmd}
    try:
        env = _build_node_env()
        res = _run_node_subprocess(
            cmd,
            env=env,
            timeout=max(AUTO_TRADE_TIMEOUT, 90),
            retries_on_errno24=1,
        )
    except Exception as exc:
        return False, _exec_failed_payload(exc)
    if res.returncode != 0:
        err_detail = _extract_node_error_detail(res.stderr, res.stdout)
        payload = {
            "error": "exec_nonzero",
            "stderr": res.stderr.strip(),
            "stdout": res.stdout.strip(),
        }
        if err_detail:
            payload["error_detail"] = err_detail
        return False, _normalize_errno24_payload(payload)
    payload = None
    for line in (res.stdout or "").splitlines():
        line = line.strip()
        if not line or not line.startswith("{") or not line.endswith("}"):
            continue
        try:
            payload = json.loads(line)
            break
        except json.JSONDecodeError:
            continue
    if payload is None:
        payload = {"stdout": res.stdout.strip()}
    if isinstance(payload, dict) and payload.get("ok") is False:
        return False, _normalize_errno24_payload(payload)
    return True, payload if isinstance(payload, dict) else {"result": payload}


def _run_node_get_order(order_id: str) -> Tuple[bool, Dict[str, Any]]:
    ensure_system_proxy_settings()
    if not order_id:
        return False, {"error": "missing_order_id"}
    script_path = Path(AUTO_TRADE_SCRIPT)
    if not script_path.exists():
        return False, {"error": f"script_missing:{script_path}"}
    node_bin = _resolve_node_bin()
    if node_bin != "node" and not Path(node_bin).exists():
        return False, {"error": f"node_missing:{node_bin}"}
    cmd = [node_bin, str(script_path), "get-order", "--order-id", str(order_id)]
    if _auto_trade_dry_run_enabled():
        return True, {"dry_run": True, "order": {"orderID": order_id}}
    try:
        env = _build_node_env()
        timeout_sec = _get_order_timeout_sec()
        clob_timeout_sec = max(2.0, float(timeout_sec) - 1.0)
        direct_get_order_context = False
        if _env_bool("PM_AUTO_TRADE_DIRECT_JOB_CONTEXT", False):
            direct_get_order_context = True
            direct_get_timeout = _env_float("PM_AUTO_TRADE_DIRECT_GET_ORDER_TIMEOUT_SEC")
            if (
                direct_get_timeout is None
                or not math.isfinite(direct_get_timeout)
                or direct_get_timeout <= 0
            ):
                direct_get_timeout = 4.0
            timeout_sec = max(2.0, min(float(direct_get_timeout), 8.0))
            clob_timeout_sec = max(1.5, float(timeout_sec) - 0.5)
        else:
            env.setdefault("PM_CLOB_FAST_ALLOW_PROXY_FALLBACK", "1")
            env.setdefault("PM_CLOB_RETRY_MAX", "2")
        _apply_clob_fast_direct_env_defaults(
            env,
            timeout_sec=clob_timeout_sec,
            hard_timeout_ms_key="PM_CLOB_GET_ORDER_HARD_TIMEOUT_MS",
            min_timeout_ms=1200 if direct_get_order_context else 3000,
            hard_timeout_min_ms=1500 if direct_get_order_context else 4000,
            hard_timeout_padding_ms=250 if direct_get_order_context else 1000,
        )
        res = _run_node_subprocess(
            cmd,
            env=env,
            timeout=timeout_sec,
            retries_on_errno24=1,
        )
    except Exception as exc:
        return False, _exec_failed_payload(exc)
    if res.returncode != 0:
        err_detail = _extract_node_error_detail(res.stderr, res.stdout)
        payload = {
            "error": "exec_nonzero",
            "stderr": res.stderr.strip(),
            "stdout": res.stdout.strip(),
        }
        if err_detail:
            payload["error_detail"] = err_detail
        return False, _normalize_errno24_payload(payload)
    payload = None
    for line in (res.stdout or "").splitlines():
        line = line.strip()
        if not line or not line.startswith("{") or not line.endswith("}"):
            continue
        try:
            payload = json.loads(line)
            break
        except json.JSONDecodeError:
            continue
    if payload is None:
        payload = {"stdout": res.stdout.strip()}
    if isinstance(payload, dict) and payload.get("ok") is False:
        return False, _normalize_errno24_payload(payload)
    return True, payload


def _run_node_open_orders() -> Tuple[bool, Dict[str, Any]]:
    if ACCOUNT_REQUESTS_DISABLED or not _env_bool("PM_AUTO_TRADE_SYNC_OPEN_ORDERS", True):
        return False, {"error": "open_orders_disabled"}
    ensure_system_proxy_settings()
    script_path = Path(AUTO_TRADE_SCRIPT)
    if not script_path.exists():
        return False, {"error": f"script_missing:{script_path}"}
    node_bin = _resolve_node_bin()
    if node_bin != "node" and not Path(node_bin).exists():
        return False, {"error": f"node_missing:{node_bin}"}
    cmd = [node_bin, str(script_path), "fetch-open-orders"]
    env = _build_node_env()
    _apply_clob_trade_env_defaults(env)
    if _auto_trade_dry_run_enabled():
        return True, {"dry_run": True, "open_orders": []}
    timeout_sec = _env_float("PM_AUTO_TRADE_OPEN_ORDERS_TIMEOUT_SEC")
    if timeout_sec is None or not math.isfinite(timeout_sec):
        timeout_sec = float(min(30, max(15, AUTO_TRADE_TIMEOUT)))
    if timeout_sec < 5:
        timeout_sec = 5.0
    env.setdefault(
        "PM_CLOB_FETCH_OPEN_ORDERS_HARD_TIMEOUT_MS",
        str(int(max(10000.0, float(timeout_sec) * 1000.0 + 5000.0))),
    )
    try:
        res = _run_node_subprocess(
            cmd,
            env=env,
            timeout=timeout_sec,
            retries_on_errno24=1,
        )
    except Exception as exc:
        return False, _exec_failed_payload(exc)
    if res.returncode != 0:
        err_detail = _extract_node_error_detail(res.stderr, res.stdout)
        payload = {
            "error": "exec_nonzero",
            "stderr": res.stderr.strip(),
            "stdout": res.stdout.strip(),
        }
        if err_detail:
            payload["error_detail"] = err_detail
        return False, _normalize_errno24_payload(payload)
    payload = None
    for line in (res.stdout or "").splitlines():
        line = line.strip()
        if not line or not line.startswith("{") or not line.endswith("}"):
            continue
        try:
            payload = json.loads(line)
            break
        except json.JSONDecodeError:
            continue
    if payload is None:
        payload = {"stdout": res.stdout.strip()}
    if isinstance(payload, dict) and payload.get("ok") is False:
        return False, _normalize_errno24_payload(payload)
    return True, payload


_MIRROR_ORDER_STATUS_POLL_LAST_AT: float = 0.0


def _mirror_poll_follow_order_statuses(
    *,
    max_rows: int = 40,
    max_age_sec: int = 6 * 3600,
    min_interval_sec: float = 5.0,
) -> Dict[str, Any]:
    """Poll recent mirror_follow_trades rows in `placed` and update to `filled` / `failed`.

    This prevents a common failure mode: an order is "placed" but matched 0 and ends up
    CANCELED, so the user sees nothing in Positions/History and the follow loop won't retry.
    """
    global _MIRROR_ORDER_STATUS_POLL_LAST_AT
    now = time.time()
    if min_interval_sec > 0 and (now - _MIRROR_ORDER_STATUS_POLL_LAST_AT) < float(min_interval_sec):
        return {"ran": False, "reason": "cooldown"}
    _MIRROR_ORDER_STATUS_POLL_LAST_AT = now

    max_rows = max(1, min(int(max_rows or 0), 300))
    max_age_sec = max(60, min(int(max_age_sec or 0), 7 * 86400))
    updated = 0
    checked = 0
    filled = 0
    failed = 0
    skipped_old = 0
    errors: List[str] = []
    last_checked_at = utc_now_iso()

    def _row_age_sec(created_at: str) -> Optional[int]:
        dt = _parse_iso_dt(created_at)
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return max(0, int(now - dt.timestamp()))

    with open_db() as conn:
        cur = conn.cursor()
        try:
            cur.execute(
                """
                SELECT id, mirror_order_id, mirror_status, mirror_error, raw_json, created_at
                FROM mirror_follow_trades
                WHERE LOWER(COALESCE(mirror_status, '')) = 'placed'
                  AND COALESCE(mirror_order_id, '') != ''
                ORDER BY created_at DESC
                LIMIT ?
                """,
                (int(max_rows),),
            )
            rows = cur.fetchall()
        except sqlite3.OperationalError as exc:
            return {"ran": False, "error": f"db_error:{exc}"}

        for row in rows:
            row_id = int(row[0] or 0)
            order_id = str(row[1] or "").strip()
            created_at = str(row[5] or "")
            if not row_id or not order_id:
                continue
            age = _row_age_sec(created_at)
            if age is not None and age > int(max_age_sec):
                skipped_old += 1
                continue

            # If fills already exist in SSOT, treat as filled and avoid extra CLOB calls.
            fill_qty = None
            try:
                cur.execute(
                    "SELECT SUM(COALESCE(size, 0)) FROM edge_trade_fills WHERE order_id = ?",
                    (order_id,),
                )
                r2 = cur.fetchone()
                fill_qty = to_float(r2[0]) if r2 else None
            except sqlite3.OperationalError:
                fill_qty = None
            if fill_qty is not None and math.isfinite(fill_qty) and fill_qty > TIME_EDGE_Q_EPS:
                new_status = "filled"
                new_error = ""
                raw_text = str(row[4] or "")
                try:
                    raw = json.loads(raw_text) if raw_text else {}
                except Exception:
                    raw = {}
                if not isinstance(raw, dict):
                    raw = {}
                raw["mirror_order_check"] = {
                    "checked_at": last_checked_at,
                    "source": "edge_trade_fills",
                    "fill_qty": round(float(fill_qty), 6),
                }
                try:
                    cur.execute(
                        "UPDATE mirror_follow_trades SET mirror_status = ?, mirror_error = ?, raw_json = ? WHERE id = ?",
                        (new_status, new_error, json.dumps(raw, ensure_ascii=False), row_id),
                    )
                    updated += 1
                    filled += 1
                except sqlite3.OperationalError:
                    pass
                continue

            checked += 1
            ok, payload = _run_node_get_order(order_id)
            order = payload.get("order") if isinstance(payload, dict) else None
            if not ok:
                err = str((payload or {}).get("error_detail") or (payload or {}).get("error") or "get_order_failed")
                errors.append(err[:160])
                continue
            if not isinstance(order, dict):
                # If we can't find the order anymore and we have no fills, treat as no-fill failure.
                status_norm = ""
                matched = None
            else:
                status_norm = str(order.get("status") or order.get("state") or order.get("orderStatus") or "").strip().lower()
                matched = to_float(
                    order.get("size_matched")
                    or order.get("sizeMatched")
                    or order.get("matched_amount")
                    or order.get("matchedAmount")
                    or order.get("filledSize")
                    or order.get("sizeFilled")
                )

            raw_text = str(row[4] or "")
            try:
                raw = json.loads(raw_text) if raw_text else {}
            except Exception:
                raw = {}
            if not isinstance(raw, dict):
                raw = {}
            raw["mirror_order_check"] = {
                "checked_at": last_checked_at,
                "status": str(status_norm or ""),
                "size_matched": float(matched) if matched is not None else None,
                "order_missing": bool(order is None or not isinstance(order, dict)),
            }

            if matched is not None and math.isfinite(matched) and matched > TIME_EDGE_Q_EPS:
                new_status = "filled"
                new_error = ""
            elif status_norm in {"canceled", "cancelled", "expired", "rejected", "failed"} or not order:
                new_status = "failed"
                new_error = "canceled_no_fill" if status_norm else "order_missing_no_fill"
            else:
                continue  # still open / unknown; leave as placed

            try:
                cur.execute(
                    "UPDATE mirror_follow_trades SET mirror_status = ?, mirror_error = ?, raw_json = ? WHERE id = ?",
                    (new_status, new_error, json.dumps(raw, ensure_ascii=False), row_id),
                )
                updated += 1
                if new_status == "filled":
                    filled += 1
                else:
                    failed += 1
            except sqlite3.OperationalError:
                continue
        conn.commit()

    return {
        "ran": True,
        "checked": int(checked),
        "updated": int(updated),
        "filled": int(filled),
        "failed": int(failed),
        "skipped_old": int(skipped_old),
        "errors": errors[:8],
    }


def _redact_sensitive_text(text: Optional[str]) -> str:
    if not text:
        return ""
    out = str(text)
    for key in (
        "POLY_API_KEY",
        "POLY_API_SECRET",
        "POLY_API_PASSPHRASE",
        "POLY_PASSPHRASE",
        "POLY_SIGNATURE",
        "PRIVATE_KEY",
    ):
        out = re.sub(
            rf'("{re.escape(key)}"\s*:\s*")([^"]+)(")',
            r"\g<1>***\g<3>",
            out,
        )
        out = re.sub(
            rf"({re.escape(key)}=)([^\s&]+)",
            r"\g<1>***",
            out,
        )
    return out


def _auto_trade_cached_open_orders_by_token(
    *,
    allow_fetch: bool,
    force_refresh: bool = False,
) -> Dict[str, List[Dict[str, Any]]]:
    global _AUTO_TRADE_OPEN_ORDERS_CACHE, _AUTO_TRADE_OPEN_ORDERS_LAST_FAIL_AT, _AUTO_TRADE_OPEN_ORDERS_LAST_FAIL_MSG
    now_ts = time.time()
    cache_sec = _env_float("PM_AUTO_TRADE_OPEN_ORDERS_CACHE_SEC")
    if cache_sec is None or not math.isfinite(cache_sec):
        cache_sec = 60.0
    if cache_sec < 0:
        cache_sec = 0.0
    fail_cooldown_sec = _env_float("PM_AUTO_TRADE_OPEN_ORDERS_FAIL_COOLDOWN_SEC")
    if fail_cooldown_sec is None or not math.isfinite(fail_cooldown_sec):
        fail_cooldown_sec = max(10.0, cache_sec)
    if fail_cooldown_sec < 0:
        fail_cooldown_sec = 0.0
    cached = _AUTO_TRADE_OPEN_ORDERS_CACHE.get("by_token")
    if ACCOUNT_REQUESTS_DISABLED:
        return dict(cached) if isinstance(cached, dict) else {}
    cached_ts = float(_AUTO_TRADE_OPEN_ORDERS_CACHE.get("ts") or 0.0)
    cache_age_sec = max(0.0, now_ts - cached_ts) if cached_ts > 0 else None
    if (
        (not force_refresh)
        and isinstance(cached, dict)
        and cached_ts > 0
        and cache_age_sec is not None
        and cache_age_sec <= cache_sec
    ):
        _AUTO_TRADE_OPEN_ORDERS_CACHE["last_source"] = "cache"
        _AUTO_TRADE_OPEN_ORDERS_CACHE["last_age_sec"] = float(cache_age_sec)
        _AUTO_TRADE_OPEN_ORDERS_CACHE["last_duration_sec"] = 0.0
        return dict(cached)
    if not allow_fetch:
        return dict(cached) if isinstance(cached, dict) else {}
    if _AUTO_TRADE_OPEN_ORDERS_LAST_FAIL_AT and (now_ts - _AUTO_TRADE_OPEN_ORDERS_LAST_FAIL_AT) < fail_cooldown_sec:
        return dict(cached) if isinstance(cached, dict) else {}

    request_started_at = time.time()
    ok, payload = _run_node_open_orders()
    if not ok:
        payload = _normalize_errno24_payload(payload)
        err = str(payload.get("error") or "exec_nonzero")
        err_detail = str(payload.get("error_detail") or "").strip()
        detail = err_detail
        if not detail:
            stderr = _redact_sensitive_text(str(payload.get("stderr") or ""))
            stdout = _redact_sensitive_text(str(payload.get("stdout") or ""))
            tail = (stderr or stdout).splitlines()[-1].strip() if (stderr or stdout) else ""
            detail = tail[:240]
        msg = f"{err}{(' ' + detail) if detail else ''}".strip()
        if msg and msg != _AUTO_TRADE_OPEN_ORDERS_LAST_FAIL_MSG and err != "exec_errno24":
            print(f"[auto-trade] open order sync failed: {msg}")
        _AUTO_TRADE_OPEN_ORDERS_LAST_FAIL_AT = now_ts
        _AUTO_TRADE_OPEN_ORDERS_LAST_FAIL_MSG = msg
        _AUTO_TRADE_OPEN_ORDERS_CACHE["last_source"] = "network_error"
        _AUTO_TRADE_OPEN_ORDERS_CACHE["last_age_sec"] = 0.0
        _AUTO_TRADE_OPEN_ORDERS_CACHE["last_duration_sec"] = max(0.0, time.time() - request_started_at)
        return dict(cached) if isinstance(cached, dict) else {}

    open_orders_raw = payload.get("open_orders") if isinstance(payload, dict) else None
    if open_orders_raw is None and isinstance(payload, dict):
        open_orders_raw = payload.get("data")
    open_orders = open_orders_raw if isinstance(open_orders_raw, list) else []
    by_token: Dict[str, List[Dict[str, Any]]] = {}
    for order in open_orders:
        if not isinstance(order, dict):
            continue
        token_id = (
            order.get("tokenID")
            or order.get("tokenId")
            or order.get("token_id")
            or order.get("asset_id")
            or order.get("assetId")
        )
        if not token_id:
            continue
        token_id = str(token_id)
        side = str(order.get("side") or order.get("orderSide") or "").upper()
        if side not in {"BUY", "SELL"}:
            continue
        order_id = order.get("orderID") or order.get("orderId") or order.get("id") or ""
        created_at = _parse_trade_time(order.get("createdAt") or order.get("created_at") or order.get("timestamp"))
        by_token.setdefault(token_id, []).append(
            {
                "order_id": str(order_id) if order_id is not None else "",
                "created_at": created_at,
                "side": side,
            }
        )
    finished_at = time.time()
    _AUTO_TRADE_OPEN_ORDERS_CACHE["ts"] = finished_at
    _AUTO_TRADE_OPEN_ORDERS_CACHE["by_token"] = dict(by_token)
    _AUTO_TRADE_OPEN_ORDERS_CACHE["last_source"] = "network"
    _AUTO_TRADE_OPEN_ORDERS_CACHE["last_age_sec"] = 0.0
    _AUTO_TRADE_OPEN_ORDERS_CACHE["last_duration_sec"] = max(0.0, finished_at - request_started_at)
    _AUTO_TRADE_OPEN_ORDERS_LAST_FAIL_AT = 0.0
    _AUTO_TRADE_OPEN_ORDERS_LAST_FAIL_MSG = ""
    return dict(by_token)


def _parse_json_from_text(text: Optional[str]) -> Optional[Dict[str, Any]]:
    if not text:
        return None
    for raw in str(text).splitlines():
        line = raw.strip()
        if not line or not line.startswith("{") or not line.endswith("}"):
            continue
        try:
            data = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(data, dict):
            return data
    return None


def _extract_node_error_detail(stderr: Optional[str], stdout: Optional[str]) -> str:
    for text in (stderr, stdout):
        data = _parse_json_from_text(text)
        if not data:
            continue
        err = data.get("error") or data.get("message") or data.get("detail")
        if err:
            return str(err)
    return ""

def _extract_min_order_size_hint(
    stderr: Optional[str],
    stdout: Optional[str],
    detail: Optional[str] = None,
) -> Optional[float]:
    pattern = re.compile(
        r"size\s*\(([-+]?\d*\.?\d+)\)\s*lower than the minimum:\s*([-+]?\d*\.?\d+)",
        re.IGNORECASE,
    )
    fallback_pattern = re.compile(
        r"minimum\s*[:=]\s*([-+]?\d*\.?\d+)",
        re.IGNORECASE,
    )
    texts = [detail, stderr, stdout]
    for raw in texts:
        if not raw:
            continue
        blob = str(raw)
        match = pattern.search(blob)
        if match:
            try:
                value = float(match.group(2))
            except (TypeError, ValueError):
                value = None
            if value is not None and math.isfinite(value) and value > 0:
                return value
        if "lower than the minimum" in blob.lower():
            fallback = fallback_pattern.search(blob)
            if fallback:
                try:
                    value = float(fallback.group(1))
                except (TypeError, ValueError):
                    value = None
                if value is not None and math.isfinite(value) and value > 0:
                    return value
    return None


def _escape_applescript(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", " ")


def _send_sms_message(message: str, recipient: str) -> bool:
    if not SMS_ENABLED or not recipient:
        return False
    safe = _escape_applescript(message.strip())
    if not safe:
        return False
    script = (
        'tell application "Messages"\n'
        f'  set targetBuddy to "{recipient}"\n'
        '  set targetService to missing value\n'
        '  try\n'
        '    set targetService to first service whose service type is SMS\n'
        '  end try\n'
        '  if targetService is missing value then\n'
        '    try\n'
        '      set targetService to first service whose service type is iMessage\n'
        '    end try\n'
        '  end if\n'
        '  if targetService is missing value then\n'
        '    error "no messaging service"\n'
        '  end if\n'
        '  send "'
        + safe
        + '" to buddy targetBuddy of targetService\n'
        'end tell'
    )
    try:
        res = subprocess.run(
            ["osascript", "-e", script],
            capture_output=True,
            text=True,
            check=False,
        )
    except OSError as exc:
        print(f"[sms] failed to invoke osascript: {exc}")
        return False
    if res.returncode != 0:
        err = (res.stderr or res.stdout or "").strip()
        print(f"[sms] send failed: {err}")
        return False
    return True


def _format_sms_message(
    kind: str,
    title: str,
    side: str,
    outcome: str,
    event_url: str,
    headroom: Optional[float],
    ask: Optional[float],
    q: Optional[float],
    lag: Optional[float],
    edge_min: Optional[float],
    edge_level: str,
    position_ratio: float,
    reasons: Optional[List[str]] = None,
) -> str:
    side_label = "买YES" if side == "YES" else "买NO"
    headroom_text = _format_pct(headroom)
    ask_text = _format_pct(ask)
    q_text = _format_pct(q)
    lag_text = _format_ratio(lag)
    edge_min_text = _format_pct(edge_min)
    ratio_text = f"{position_ratio * 100:.2f}%" if position_ratio > 0 else "—"
    level_text = edge_level or "—"
    link_text = f" 链接:{event_url}" if event_url else ""
    if kind == "exit":
        reason_text = ""
        if reasons:
            reason_text = " 原因:" + "/".join(reasons)
        return (
            f"【应退出】{title} {side_label} {outcome} "
            f"H={headroom_text} ask={ask_text} L={lag_text} "
            f"{level_text}/{ratio_text}{reason_text}{link_text}"
        )
    return (
        f"【可进场】{title} {side_label} {outcome} "
        f"H={headroom_text} ask={ask_text} q={q_text} L={lag_text} "
        f"signal_edge={edge_min_text} {level_text}/{ratio_text}{link_text}"
    )


def _format_trade_sms_message(
    kind: str,
    title: str,
    side: str,
    outcome: str,
    event_url: str,
    price: Optional[float],
    size: Optional[float],
    when: str,
    condition_text: str,
    pnl: Optional[float] = None,
) -> str:
    side_label = "买YES" if side == "YES" else "买NO"
    if kind == "sell":
        side_label = "卖YES" if side == "YES" else "卖NO"
    price_text = _format_pct(price)
    size_text = _format_ratio(size, 4) if size else "—"
    notional = None
    if price is not None and size is not None:
        notional = price * size
    amount_text = _format_usdc(notional)
    pnl_text = _format_usdc(pnl)
    link_text = f" 链接:{event_url}" if event_url else ""
    if kind == "sell":
        return (
            f"【卖出下单】{title} {side_label} {outcome} 时间={when} "
            f"金额={amount_text} 价格={price_text} 份额={size_text} "
            f"盈亏={pnl_text} 条件:{condition_text}{link_text}"
        )
    return (
        f"【买入】{title} {side_label} {outcome} 时间={when} "
        f"金额={amount_text} 价格={price_text} 份额={size_text} "
        f"条件:{condition_text}{link_text}"
    )


def _format_trade_fill_sms_message(
    trade_side: str,
    title: str,
    side: str,
    outcome: str,
    event_url: str,
    price: Optional[float],
    size: Optional[float],
    when: str,
    pnl: Optional[float] = None,
    strategy: str = "",
) -> str:
    action = "已成交" if trade_side == "BUY" else "已卖出"
    side_label = "买YES" if side == "YES" else "买NO"
    if trade_side == "SELL":
        side_label = "卖YES" if side == "YES" else "卖NO"
    strategy_name = str(strategy or "").strip().lower()
    price_text = _format_pct(price)
    size_text = _format_ratio(size, 4) if size else "—"
    notional = None
    if price is not None and size is not None:
        notional = price * size
    amount_text = _format_usdc(notional)
    pnl_text = _format_usdc(pnl)
    link_text = f" 链接:{event_url}" if event_url else ""
    if strategy_name == "mirror_follow":
        mirror_action = "跟买成交" if trade_side == "BUY" else "跟卖成交"
        if trade_side == "SELL":
            return (
                f"【影子跟单】{mirror_action} {title} {side_label} {outcome} 时间={when} "
                f"金额={amount_text} 价格={price_text} 份额={size_text} "
                f"盈亏={pnl_text}{link_text}"
            )
        return (
            f"【影子跟单】{mirror_action} {title} {side_label} {outcome} 时间={when} "
            f"金额={amount_text} 价格={price_text} 份额={size_text}{link_text}"
        )
    if trade_side == "SELL":
        return (
            f"【{action}】{title} {side_label} {outcome} 时间={when} "
            f"金额={amount_text} 价格={price_text} 份额={size_text} "
            f"盈亏={pnl_text}{link_text}"
        )
    return (
        f"【{action}】{title} {side_label} {outcome} 时间={when} "
        f"金额={amount_text} 价格={price_text} 份额={size_text}{link_text}"
    )


def _dump_reason_list(values: Optional[Iterable[Any]]) -> Optional[str]:
    if values is None:
        return None
    if isinstance(values, str):
        values_iter = [values]
    elif isinstance(values, (list, tuple, set)):
        values_iter = list(values)
    else:
        values_iter = [values]
    out: List[str] = []
    for item in values_iter:
        if item is None:
            continue
        text = str(item).strip()
        if not text or text in out:
            continue
        out.append(text)
    if not out:
        return None
    return json.dumps(out, ensure_ascii=False)


def _dump_reason_list_or_blank(values: Optional[Iterable[Any]]) -> str:
    dumped = _dump_reason_list(values)
    return dumped if dumped is not None else ""


def _parse_reason_list(raw: Any) -> List[str]:
    if raw is None:
        return []
    if isinstance(raw, list):
        items = raw
    elif isinstance(raw, (tuple, set)):
        items = list(raw)
    else:
        text = str(raw or "").strip()
        if not text:
            return []
        if text.startswith("["):
            try:
                parsed = json.loads(text)
            except Exception:
                parsed = None
            if isinstance(parsed, list):
                items = parsed
            else:
                items = [text]
        else:
            items = [text]
    out: List[str] = []
    for item in items:
        text = str(item or "").strip()
        if not text or text in out:
            continue
        out.append(text)
    return out


TARGET_REALIZATION_OLD_BUCKET_EXIT_CODES: Set[str] = {
    "target_realization_yes_target_invalidated",
    "target_realization_no_invalidated",
}


def _should_bypass_target_switch_exit_balance_check(exit_reason_codes: Any) -> bool:
    if not _env_bool("PM_AUTO_TRADE_TARGET_SWITCH_EXIT_BYPASS_BALANCE_CHECK", True):
        return False
    code_set = {
        str(code or "").strip().lower()
        for code in _parse_reason_list(exit_reason_codes)
        if str(code or "").strip()
    }
    return bool(code_set.intersection(TARGET_REALIZATION_OLD_BUCKET_EXIT_CODES))


def _runtime_truthy_flag(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        try:
            return bool(math.isfinite(float(value)) and float(value) != 0.0)
        except Exception:
            return False
    text = str(value or "").strip().lower()
    if not text:
        return False
    if text in {"1", "true", "yes", "on", "y"}:
        return True
    if text in {"0", "false", "no", "off", "n", "none", "null"}:
        return False
    return True


def _bucket_hard_zero_exit_meta(
    row_ref: Mapping[str, Any],
    side_label: str,
) -> Dict[str, Any]:
    if not isinstance(row_ref, Mapping):
        return {"hard_zero": False}
    if str(side_label or "").strip().upper() != "YES":
        return {"hard_zero": False}

    hard_zero_sources: List[str] = []
    for key in (
        "q_bayes_physical_likelihood_hard_zero",
        "q_posterior_observed_constraints_hard_zero",
        "posterior_settlement_candidate_bucket_hard_zero",
    ):
        if _runtime_truthy_flag(row_ref.get(key)):
            hard_zero_sources.append(key)

    hard_reasons: List[str] = []
    for key in (
        "q_bayes_physical_likelihood_hard_reasons",
        "q_posterior_observed_constraints_hard_zero_reasons",
        "posterior_settlement_candidate_bucket_hard_zero_reasons",
        "hard_reasons",
    ):
        for reason in _parse_reason_list(row_ref.get(key)):
            if reason not in hard_reasons:
                hard_reasons.append(reason)

    zero_posterior_field = ""
    zero_posterior_value: Optional[float] = None
    for key in (
        "q_bayes_posterior",
        "q_temperature_bucket_posterior",
        "posterior_settlement_candidate_bucket_prob",
        "current_target_posterior",
        "held_target_posterior",
        "switch_reference_posterior",
    ):
        val = to_float(row_ref.get(key))
        if val is None or not math.isfinite(val):
            continue
        if val <= TIME_EDGE_Q_EPS:
            zero_posterior_field = key
            zero_posterior_value = float(val)
            break

    observed_break = "observed_today_max_above_bucket" in {
        str(reason or "").strip() for reason in hard_reasons
    }
    hard_zero = bool(hard_zero_sources or (observed_break and zero_posterior_field))
    meta: Dict[str, Any] = {
        "hard_zero": hard_zero,
        "hard_zero_sources": hard_zero_sources,
        "hard_zero_reasons": hard_reasons,
        "observed_today_max_above_bucket": bool(observed_break),
    }
    if zero_posterior_field:
        meta["zero_posterior_field"] = zero_posterior_field
        meta["zero_posterior_value"] = zero_posterior_value
    return meta


def _target_realization_hard_zero_exit_context(row_ref: Mapping[str, Any]) -> Dict[str, Any]:
    if not isinstance(row_ref, Mapping):
        return {}
    context: Dict[str, Any] = {}
    scalar_keys = (
        "target_bucket",
        "ssot_target_bucket",
        "posterior_settlement_target_bucket",
        "second_target_bucket",
        "posterior_settlement_second_target_bucket",
        "held_target_bucket",
        "current_position_target_bucket",
        "target_posterior",
        "posterior_settlement_target_posterior",
        "second_target_posterior",
        "posterior_settlement_second_target_posterior",
        "posterior_settlement_candidate_bucket_prob",
        "q_temperature_bucket_posterior",
        "target_realization_path_p_reach_yes",
        "target_realization_reliability",
        "target_realization_reliability_source",
        "target_realization_plan_action",
        "target_realization_leg_role",
        "target_realization_capital_plan_version",
        "target_realization_capital_plan_source",
        "target_realization_ui_risk_explanation_text",
        "target_realization_trade_follow_allowed",
        "target_realization_trade_follow_reason",
        "target_realization_path_reliability_state",
        "target_realization_path_reliability_label",
        "target_realization_path_reliability_score",
        "target_realization_freshness_source_stale",
        "target_realization_observation_age_minutes",
        "target_realization_error_band_sigma_c",
        "target_realization_error_band_source",
        "target_realization_hard_source_observed_max_c",
        "target_realization_hard_source_state_label",
        "target_realization_hard_source_source",
        "decision_ssot",
        "decision_basis",
        "bayes_recomputed_async",
        "fact_recompute_async",
    )
    for key in scalar_keys:
        value = row_ref.get(key)
        if value is None or value == "":
            continue
        context[key] = value
    for key in (
        "target_realization_ui_risk_codes",
        "target_realization_error_band",
        "target_realization_hard_source_state",
        "target_realization_ui_risk_explanation",
    ):
        value = row_ref.get(key)
        if value is None or value == "":
            continue
        if isinstance(value, Mapping):
            context[key] = dict(value)
        elif isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
            context[key] = list(value)
        else:
            context[key] = value
    return context


def _target_realization_hard_zero_exit_meta(
    row_ref: Mapping[str, Any],
    side_label: str,
    exit_codes: Optional[Iterable[Any]] = None,
) -> Dict[str, Any]:
    meta = _bucket_hard_zero_exit_meta(row_ref, side_label)
    if not meta.get("hard_zero"):
        meta["target_realization_hard_zero_exit"] = False
        return meta
    code_set = {
        str(code or "").strip()
        for code in (exit_codes or [])
        if str(code or "").strip()
    }
    target_exit = (not code_set) or bool(code_set & TARGET_REALIZATION_OLD_BUCKET_EXIT_CODES)
    meta["target_realization_hard_zero_exit"] = bool(target_exit)
    if code_set:
        meta["exit_reason_codes"] = sorted(code_set)
    context = _target_realization_hard_zero_exit_context(row_ref)
    if context:
        meta["target_realization_hard_zero_exit_context"] = context
    return meta


def _should_defer_target_switch_exit_for_entry_priority(
    *,
    exit_only: bool,
    target_switch_expected_entry_keys: Set[Tuple[str, str]],
    outcome_label: str,
    side_label: str,
    row_ref: Mapping[str, Any],
    exit_codes: Sequence[Any],
) -> bool:
    if exit_only or not target_switch_expected_entry_keys:
        return False
    outcome_key = str(outcome_label or "").strip()
    side_key = str(side_label or "").strip().upper()
    if not outcome_key or side_key not in {"YES", "NO"}:
        return False
    if (outcome_key, side_key) in target_switch_expected_entry_keys:
        return False
    code_set = {
        str(code or "").strip()
        for code in (exit_codes or [])
        if str(code or "").strip()
    }
    if _target_realization_hard_zero_exit_meta(
        row_ref,
        side_key,
        code_set,
    ).get("target_realization_hard_zero_exit"):
        if isinstance(row_ref, dict):
            row_ref["target_switch_entry_priority_override"] = "hard_zero_old_bucket_exit"
        return False
    if code_set.intersection(TARGET_REALIZATION_OLD_BUCKET_EXIT_CODES):
        if isinstance(row_ref, dict):
            row_ref["target_switch_entry_priority_override"] = "old_bucket_exit_immediate"
        return False
    return bool(row_ref.get("target_adjustment_force_exit"))


def _marketable_exit_retry_price_floor_plan(
    *,
    prev_exit_retry_count: int,
    hard_zero_price_floor_rearm: bool,
) -> Dict[str, Any]:
    prev_count = max(int(prev_exit_retry_count or 0), 0)
    if hard_zero_price_floor_rearm:
        return {
            "last_status": "target_realization_hard_zero_dead_market",
            "last_error": "",
            "exit_retry_count": 0,
            "reason_codes": ["target_realization_hard_zero_dead_market"],
            "reasons": [
                "硬归零旧桶FAK退出无成交且已到最小报价；盘口已无可成交买盘，等待结算归零"
            ],
            "rearm": False,
        }
    return {
        "last_status": "exit_retry_price_floor",
        "last_error": "exit_retry_price_floor",
        "exit_retry_count": prev_count + 1,
        "reason_codes": ["exit_marketable_retry_skipped_price_floor"],
        "reasons": ["FAK退出无成交，但已无更低一档可重试"],
        "rearm": False,
    }


def _hard_zero_dead_market_exit_meta(
    row_ref: Mapping[str, Any],
    side_label: str,
    exit_codes: Optional[Iterable[Any]],
    *,
    best_bid: Any,
    best_ask: Any,
    bid_depth: Any = None,
) -> Dict[str, Any]:
    hard_zero_meta = _target_realization_hard_zero_exit_meta(
        row_ref,
        side_label,
        exit_codes,
    )
    if not hard_zero_meta.get("target_realization_hard_zero_exit"):
        return {"exit_dead_market": False}
    bid_val = to_float(best_bid)
    ask_val = to_float(best_ask)
    bid_depth_val = to_float(bid_depth)
    bid_missing_or_zero = (
        bid_val is None or not math.isfinite(bid_val) or bid_val <= TIME_EDGE_Q_EPS
    )
    bid_depth_zero = (
        bid_depth_val is not None
        and math.isfinite(bid_depth_val)
        and bid_depth_val <= TIME_EDGE_Q_EPS
    )
    dead_market = bool(bid_missing_or_zero or bid_depth_zero)
    reason = ""
    if bid_missing_or_zero:
        reason = "hard_zero_old_bucket_no_executable_yes_bid"
    elif bid_depth_zero:
        reason = "hard_zero_old_bucket_zero_bid_depth"
    meta: Dict[str, Any] = {
        "exit_dead_market": dead_market,
        "exit_dead_market_reason": reason,
        "exit_dead_market_best_bid": bid_val,
        "exit_dead_market_best_ask": ask_val,
        "exit_dead_market_bid_depth": bid_depth_val,
        "exit_dead_market_ask_only": bool(
            bid_missing_or_zero
            and ask_val is not None
            and math.isfinite(ask_val)
            and ask_val > TIME_EDGE_Q_EPS
        ),
        "exit_dead_market_settlement_wait": bool(dead_market),
        "target_realization_hard_zero_exit": True,
        "target_realization_hard_zero_exit_meta": hard_zero_meta,
    }
    return meta


def _resolve_entry_drawdown_block() -> Tuple[bool, Dict[str, Any]]:
    entry_drawdown_blocked = False
    entry_drawdown_detail: Dict[str, Any] = {}
    max_drawdown_pct = _env_float("PM_AUTO_TRADE_MAX_DRAWDOWN_PCT")
    if max_drawdown_pct is None or not math.isfinite(max_drawdown_pct) or max_drawdown_pct < 0:
        max_drawdown_pct = 0.10
    if max_drawdown_pct > 1.0:
        max_drawdown_pct = max_drawdown_pct / 100.0
    bankroll_base = _env_float("PM_BANKROLL_USDC")
    if (
        max_drawdown_pct is not None
        and math.isfinite(max_drawdown_pct)
        and max_drawdown_pct > 0
        and bankroll_base is not None
        and math.isfinite(bankroll_base)
        and bankroll_base > 0
    ):
        total_pnl = None
        try:
            pnl_conn = open_db()
            pnl_conn.row_factory = sqlite3.Row
            pnl_cur = pnl_conn.cursor()
            pnl_cur.execute(
                """
                SELECT SUM(COALESCE(realized_pnl, 0) + COALESCE(unrealized_pnl, 0))
                FROM edge_trades
                """
            )
            row_pnl = pnl_cur.fetchone()
            if row_pnl:
                total_pnl = to_float(row_pnl[0])
        except Exception:
            total_pnl = None
        finally:
            try:
                pnl_conn.close()
            except Exception:
                pass
        if total_pnl is not None and math.isfinite(total_pnl):
            drawdown_pct = max(0.0, -float(total_pnl) / float(bankroll_base))
            entry_drawdown_detail = {
                "drawdown_pct": drawdown_pct,
                "drawdown_max_pct": float(max_drawdown_pct),
                "bankroll_base": float(bankroll_base),
                "total_pnl": float(total_pnl),
            }
            if drawdown_pct >= max_drawdown_pct - TIME_EDGE_Q_EPS:
                entry_drawdown_blocked = True
    return entry_drawdown_blocked, entry_drawdown_detail


def _resolve_lcb_global_daily_loss_block(run_date: str) -> Tuple[bool, Dict[str, Any]]:
    blocked = False
    detail: Dict[str, Any] = {}
    run_date_key = str(run_date or "").strip().split("T", 1)[0]
    if not run_date_key:
        return blocked, detail
    loss_stop_usdc = _env_float("PM_LCB_GLOBAL_DAILY_LOSS_STOP_USDC")
    if (
        loss_stop_usdc is None
        or not math.isfinite(loss_stop_usdc)
        or float(loss_stop_usdc) <= 0
    ):
        return blocked, detail
    loss_stop_usdc = float(loss_stop_usdc)
    daily_realized_pnl: Optional[float] = None
    closed_count = 0
    pnl_conn: Optional[sqlite3.Connection] = None
    try:
        pnl_conn = open_db()
        pnl_conn.row_factory = sqlite3.Row
        pnl_cur = pnl_conn.cursor()
        day_start = f"{run_date_key} 00:00:00"
        pnl_cur.execute(
            """
            SELECT
              SUM(COALESCE(t.realized_pnl, 0.0)) AS pnl_sum,
              COUNT(*) AS trade_count
            FROM edge_trades t
            WHERE t.state = 'exit'
              AND t.realized_pnl IS NOT NULL
              AND datetime(substr(t.updated_at, 1, 19)) >= datetime(?)
              AND datetime(substr(t.updated_at, 1, 19)) < datetime(?, '+1 day')
              AND EXISTS (
                    SELECT 1
                    FROM auto_orders ao
                    WHERE ao.slug = t.slug
                      AND ao.event_date = t.event_date
                      AND ao.outcome = t.outcome
                      AND ao.side = t.side
                      AND lower(COALESCE(ao.action, '')) = 'entry'
                      AND lower(COALESCE(ao.strategy, '')) IN (
                        'path_probability_follow',
                        'lcb_global',
                        'hard_source_direct',
                        'target_realization_binary_settlement'
                      )
              )
            """,
            (day_start, day_start),
        )
        row = pnl_cur.fetchone()
        if row:
            daily_realized_pnl = to_float(row["pnl_sum"])
            try:
                closed_count = int(row["trade_count"] or 0)
            except Exception:
                closed_count = 0
    except Exception:
        daily_realized_pnl = None
        closed_count = 0
    finally:
        try:
            if pnl_conn is not None:
                pnl_conn.close()
        except Exception:
            pass
    if daily_realized_pnl is None or not math.isfinite(daily_realized_pnl):
        daily_realized_pnl = 0.0
    blocked = float(daily_realized_pnl) <= -float(loss_stop_usdc) + TIME_EDGE_Q_EPS
    detail = {
        "run_date": run_date_key,
        "daily_realized_pnl": float(daily_realized_pnl),
        "daily_loss_stop_usdc": float(loss_stop_usdc),
        "closed_count": int(closed_count),
    }
    return blocked, detail


def _merge_hard_source_direct_block_context(
    dest: Dict[str, Any],
    hard_block: Mapping[str, Any],
) -> None:
    if not isinstance(dest, dict) or not isinstance(hard_block, Mapping):
        return
    aliases = {
        "source": "hard_source_source_id",
        "observed_at": "hard_source_observed_at",
        "fetched_at": "hard_source_fetched_at",
        "ssot_written_at": "hard_source_ssot_written_at",
        "ssot_write_ms": "hard_source_ssot_write_ms",
        "job_enqueued_at": "hard_source_job_enqueued_at",
        "worker_started_at": "hard_source_worker_started_at",
        "fetch_to_ssot_ms": "hard_source_fetch_to_ssot_ms",
        "ssot_to_job_enqueue_ms": "hard_source_ssot_to_job_enqueue_ms",
        "fetch_to_job_enqueue_ms": "hard_source_fetch_to_job_enqueue_ms",
        "job_enqueue_to_worker_ms": "hard_source_job_enqueue_to_worker_ms",
    }
    for src_key, dst_key in aliases.items():
        val = hard_block.get(src_key)
        if val is not None:
            dest[dst_key] = val
    if hard_block.get("observed_at"):
        dest["hard_source_seen_at"] = hard_block.get("observed_at")
    for key in (
        "signal_id",
        "source_event_id",
        "awc_valid_time",
        "awc_hard_source_signal_at",
        "signal_eligible",
        "acceptance_state",
        "acceptance_reason",
        "hard_source_acceptance_state",
        "hard_source_runtime_contract",
        "hard_source_runtime_contract_version",
        "signal_to_order_timing",
        "signal_to_order_slo_ms",
        "signal_to_fact_ms",
        "signal_to_decision_ms",
        "signal_to_job_enqueue_ms",
        "awc_signal_to_order_submit_ms",
        "signal_to_order_slo_met",
        "signal_to_order_slo_violation_reason",
        "signal_to_order_terminal_state",
        "signal_to_order_terminal_reason",
        "signal_to_order_terminal_at",
        "signal_to_terminal_ms",
        "orderbook_checked_at",
        "orderbook_check_source",
        "orderbook_check_result",
        "orderbook_refreshed_at",
        "orderbook_refresh_started_at",
        "risk_checked_at",
        "risk_check_source",
        "risk_check_result",
        "idempotency_checked_at",
        "idempotency_key",
        "submit_requested_at",
        "exchange_ack_at",
        "order_ack_at",
        "order_ack_status",
        "exchange_post_started",
        "exchange_post_started_at",
        "order_submitted_at",
        "order_submission_time_quality",
        "signal_to_orderbook_ms",
        "signal_to_risk_ms",
        "signal_to_idempotency_ms",
        "signal_to_submit_request_ms",
        "signal_to_exchange_ack_ms",
        "orderbook_to_risk_check_ms",
        "risk_check_to_idempotency_ms",
        "risk_check_to_submit_ms",
        "idempotency_to_submit_request_ms",
        "submit_request_to_exchange_ack_ms",
        "signal_to_order_ledger_status",
        "signal_to_order_ledger_schema_status",
        "signal_to_order_ledger_prewrite",
        "signal_to_order_ledger_result",
    ):
        if key in hard_block and hard_block.get(key) is not None:
            dest[key] = hard_block.get(key)
    target_bucket = hard_block.get("target_bucket") or hard_block.get("ssot_target_bucket")
    if target_bucket and not dest.get("outcome"):
        dest["outcome"] = target_bucket
    if hard_block.get("side") and not dest.get("side"):
        dest["side"] = str(hard_block.get("side") or "").strip().upper()
    dest["hard_source_direct"] = True
    dest["hard_source_posterior_override"] = True


def notify_edge_signals(
    run_date: str,
    event_date: str,
    result: Dict,
) -> None:
    if not SMS_ENABLED or not SMS_RECIPIENT or not SMS_SIGNAL_ENABLED or SMS_FILL_ONLY:
        return
    slug = str(result.get("slug") or "")
    title = str(result.get("title") or "")
    event_url = str(result.get("event_url") or "")
    if not event_url and slug:
        event_url = f"https://polymarket.com/event/{slug}"
    if not slug or not event_date:
        return
    if not _payload_write_allowed_for_chengdu_zuuu(
        result,
        slug=slug,
        title=title,
        station_id=str(result.get("station_id") or ""),
        resolution_source=str(result.get("resolution_source") or ""),
        lat=to_float(result.get("lat")),
        lon=to_float(result.get("lon")),
    ):
        return
    rows = result.get("rows") or []
    if not rows:
        return
    hard_source_sla_result_context: Dict[str, Any] = {}
    result_hard_block = result.get("hard_source_direct")
    if isinstance(result_hard_block, Mapping):
        if result_hard_block.get("source"):
            hard_source_sla_result_context["hard_source_source_id"] = result_hard_block.get("source")
        if result_hard_block.get("observed_at"):
            hard_source_sla_result_context["hard_source_observed_at"] = result_hard_block.get("observed_at")
            hard_source_sla_result_context["hard_source_seen_at"] = result_hard_block.get("observed_at")
        if result_hard_block.get("fetched_at"):
            hard_source_sla_result_context["hard_source_fetched_at"] = result_hard_block.get("fetched_at")
        if result_hard_block.get("ssot_written_at"):
            hard_source_sla_result_context["hard_source_ssot_written_at"] = result_hard_block.get("ssot_written_at")
        if result_hard_block.get("ssot_write_ms") is not None:
            hard_source_sla_result_context["hard_source_ssot_write_ms"] = result_hard_block.get("ssot_write_ms")
        if result_hard_block.get("job_enqueued_at"):
            hard_source_sla_result_context["hard_source_job_enqueued_at"] = result_hard_block.get("job_enqueued_at")
        if result_hard_block.get("worker_started_at"):
            hard_source_sla_result_context["hard_source_worker_started_at"] = result_hard_block.get("worker_started_at")
        if result_hard_block.get("target_bucket"):
            hard_source_sla_result_context["outcome"] = result_hard_block.get("target_bucket")
        hard_source_sla_result_context["hard_source_direct"] = True
        hard_source_sla_result_context["hard_source_posterior_override"] = True
        _merge_hard_source_direct_block_context(
            hard_source_sla_result_context,
            result_hard_block,
        )
    result_hard_timing = result.get("hard_source_direct_timing")
    if isinstance(result_hard_timing, Mapping):
        timing_aliases = {
            "seen_at": "hard_source_seen_at",
            "fetched_at": "hard_source_fetched_at",
            "decision_started_at": "hard_source_decision_started_at",
            "ssot_written_at": "hard_source_ssot_written_at",
            "seen_to_ssot_ms": "hard_source_seen_to_ssot_ms",
            "fetch_to_ssot_ms": "hard_source_fetch_to_ssot_ms",
        }
        for src_key, dst_key in timing_aliases.items():
            if result_hard_timing.get(src_key) is not None:
                hard_source_sla_result_context[dst_key] = result_hard_timing.get(src_key)
        hard_source_sla_result_context["hard_source_direct"] = True
        hard_source_sla_result_context["hard_source_posterior_override"] = True
    for row_ref in rows:
        if not isinstance(row_ref, Mapping):
            continue
        if not (row_ref.get("hard_source_direct") or row_ref.get("hard_source_ssot_written_at")):
            continue
        _copy_hard_source_sla_fields(hard_source_sla_result_context, row_ref)
        if row_ref.get("outcome") and not hard_source_sla_result_context.get("outcome"):
            hard_source_sla_result_context["outcome"] = row_ref.get("outcome")
        break
    event_tz = str(
        result.get("tz")
        or result.get("timezone")
        or ((rows[0] or {}).get("tz") if isinstance(rows[0], Mapping) else "")
        or ""
    )

    positions_priority_fast_loop, positions_priority_allow_slow = _auto_trade_positions_priority_fast_loop_state()
    slow_request_used = False
    edge_realizable_v2_enabled = _env_bool("PM_EDGE_REALIZABLE_V2_ENABLED", False)
    entry_tradeability_gate_enabled = _entry_tradeability_gate_enabled_from_env()
    edge_realizable_v2_gate_exit = _env_bool("PM_EDGE_REALIZABLE_V2_GATE_EXIT", False)
    entry_edge_realizable_min_v2 = _env_float("PM_AUTO_TRADE_ENTRY_EDGE_REALIZABLE_V2_MIN")
    if entry_edge_realizable_min_v2 is None or not math.isfinite(entry_edge_realizable_min_v2):
        entry_edge_realizable_min_v2 = None
    entry_edge_realizable_p_realize_min = _env_float("PM_AUTO_TRADE_ENTRY_EDGE_REALIZABLE_P_REALIZE_MIN")
    if (
        entry_edge_realizable_p_realize_min is None
        or not math.isfinite(entry_edge_realizable_p_realize_min)
    ):
        entry_edge_realizable_p_realize_min = 0.0
    if entry_edge_realizable_p_realize_min < 0:
        entry_edge_realizable_p_realize_min = 0.0
    if entry_edge_realizable_p_realize_min > 1:
        entry_edge_realizable_p_realize_min = 1.0
    entry_edge_realizable_p_converge_min = _env_float("PM_AUTO_TRADE_ENTRY_EDGE_REALIZABLE_P_CONVERGE_MIN")
    if (
        entry_edge_realizable_p_converge_min is None
        or not math.isfinite(entry_edge_realizable_p_converge_min)
    ):
        entry_edge_realizable_p_converge_min = 0.0
    if entry_edge_realizable_p_converge_min < 0:
        entry_edge_realizable_p_converge_min = 0.0
    if entry_edge_realizable_p_converge_min > 1:
        entry_edge_realizable_p_converge_min = 1.0

    def _mark_slow_request_used() -> None:
        nonlocal slow_request_used
        if positions_priority_fast_loop and not slow_request_used:
            slow_request_used = True
            _auto_trade_positions_priority_mark_slow_request()

    entry_drawdown_blocked = False
    entry_drawdown_detail: Dict[str, Any] = {}
    try:
        entry_drawdown_blocked, entry_drawdown_detail = _resolve_entry_drawdown_block()
    except Exception as exc:
        entry_drawdown_blocked = False
        entry_drawdown_detail = {}
        print(f"[auto-trade] drawdown check failed {slug} {event_date}: {exc}")

    # Reprice "executable edge" at runtime using the same semantics as the order we would submit
    # (limit vs market/FAK pay-up). This keeps exec_edge_entry thresholds meaningful even when the
    # facts snapshot's exec_* fields were computed with a different executable_price assumption.
    exec_edge_ob_timeout_sec = _env_float("PM_AUTO_TRADE_EXEC_EDGE_ORDERBOOK_TIMEOUT_SEC")
    if exec_edge_ob_timeout_sec is None or not math.isfinite(exec_edge_ob_timeout_sec):
        exec_edge_ob_timeout_sec = 2.5
    if exec_edge_ob_timeout_sec <= 0:
        exec_edge_ob_timeout_sec = 2.5
    exec_edge_ob_retries = int(_env_float("PM_AUTO_TRADE_EXEC_EDGE_ORDERBOOK_RETRIES") or 1)
    exec_edge_ob_retries = max(0, min(exec_edge_ob_retries, 2))
    _exec_edge_book_cache: Dict[str, Dict[str, Any]] = {}

    def _get_exec_edge_book(token_id: str) -> Optional[Dict[str, Any]]:
        key = str(token_id or "").strip()
        if not key:
            return None
        cached = _exec_edge_book_cache.get(key)
        if isinstance(cached, dict):
            return cached
        try:
            book = fetch_orderbook(
                key,
                retries=int(exec_edge_ob_retries),
                backoff=0.15 if exec_edge_ob_retries > 0 else 0.0,
                timeout_sec=float(exec_edge_ob_timeout_sec),
            )
        except Exception:
            book = None
        if isinstance(book, dict):
            _exec_edge_book_cache[key] = book
            return book
        return None

    def _avg_price_for_amount(
        asks_levels: Any,
        amount_usdc: Optional[float],
        *,
        cap_price: Optional[float] = None,
    ) -> Tuple[Optional[float], float, float]:
        """Simulate BUY execution against ask stack given a notional 'amount' (Polymarket market orders).

        Returns (avg_price, filled_qty, spent_usdc). If nothing fills -> (None, 0.0, 0.0).
        """
        amt = to_float(amount_usdc)
        if amt is None or not math.isfinite(amt) or amt <= TIME_EDGE_Q_EPS:
            return None, 0.0, 0.0
        cap = to_float(cap_price)
        if cap is not None and (not math.isfinite(cap) or cap <= 0):
            cap = None
        levels = asks_levels if isinstance(asks_levels, list) else []
        parsed: List[Tuple[float, float]] = []
        for lvl in levels:
            if not isinstance(lvl, dict):
                continue
            p = to_float(lvl.get("price"))
            q = to_float(lvl.get("size"))
            if p is None or q is None or (not math.isfinite(p)) or (not math.isfinite(q)) or p <= 0 or q <= 0:
                continue
            if cap is not None and p > cap + 1e-9:
                continue
            parsed.append((float(p), float(q)))
        if not parsed:
            return None, 0.0, 0.0
        parsed.sort(key=lambda it: it[0])
        remaining = float(amt)
        spent = 0.0
        filled = 0.0
        for price, qty in parsed:
            if remaining <= TIME_EDGE_Q_EPS:
                break
            level_cost = price * qty
            take_cost = level_cost if level_cost <= remaining else remaining
            take_qty = take_cost / price
            spent += take_cost
            filled += take_qty
            remaining -= take_cost
        if filled <= TIME_EDGE_Q_EPS:
            return None, 0.0, 0.0
        return spent / filled, filled, spent

    # Keep executable-edge cost components aligned with facts composer defaults.
    exec_spread_weight_runtime = _env_float("PM_EXEC_EDGE_SPREAD_WEIGHT")
    if exec_spread_weight_runtime is None or not math.isfinite(exec_spread_weight_runtime):
        exec_spread_weight_runtime = 0.25
    if exec_spread_weight_runtime < 0:
        exec_spread_weight_runtime = 0.0
    if exec_spread_weight_runtime > 1:
        exec_spread_weight_runtime = exec_spread_weight_runtime / 100.0
    exec_depth_penalty_weight_runtime = _env_float("PM_EXEC_EDGE_DEPTH_PENALTY_WEIGHT")
    if exec_depth_penalty_weight_runtime is None or not math.isfinite(exec_depth_penalty_weight_runtime):
        exec_depth_penalty_weight_runtime = 1.0
    if exec_depth_penalty_weight_runtime < 0:
        exec_depth_penalty_weight_runtime = 0.0
    exec_cancel_cost_runtime = _env_float("PM_EXEC_EDGE_CANCEL_COST")
    if exec_cancel_cost_runtime is None or not math.isfinite(exec_cancel_cost_runtime):
        exec_cancel_cost_runtime = 0.002
    if exec_cancel_cost_runtime < 0:
        exec_cancel_cost_runtime = 0.0
    if exec_cancel_cost_runtime > 1:
        exec_cancel_cost_runtime = exec_cancel_cost_runtime / 100.0
    exec_retry_cost_runtime = _env_float("PM_EXEC_EDGE_RETRY_COST")
    if exec_retry_cost_runtime is None or not math.isfinite(exec_retry_cost_runtime):
        exec_retry_cost_runtime = 0.001
    if exec_retry_cost_runtime < 0:
        exec_retry_cost_runtime = 0.0
    if exec_retry_cost_runtime > 1:
        exec_retry_cost_runtime = exec_retry_cost_runtime / 100.0
    exec_base_cost_runtime = float(exec_cancel_cost_runtime) + float(exec_retry_cost_runtime)

    def _liquidity_penalty_runtime(spread_val: Optional[float], ask_val: Optional[float]) -> float:
        penalty = 0.0
        spr = to_float(spread_val)
        ask = to_float(ask_val)
        if spr is not None and math.isfinite(spr):
            spread_pct = float(spr) * 100.0
            penalty += max(0.0, (spread_pct - 8.0) / 10.0)
        if ask is not None and math.isfinite(ask):
            penalty += max(0.0, (float(ask) - 0.6) / 0.2)
        return penalty
    init_db()
    conn = open_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        "SELECT outcome, side, state, entry_at FROM edge_notifications WHERE slug = ? AND event_date = ?",
        (slug, event_date),
    )
    prev_states = {(r[0], r[1]): {"state": r[2], "entry_at": r[3]} for r in cur.fetchall()}

    def _update_state(outcome: str, side: str, state: str, entry_at: Optional[str] = None) -> None:
        cur.execute(
            """
            INSERT INTO edge_notifications (slug, event_date, outcome, side, state, entry_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(slug, event_date, outcome, side)
            DO UPDATE SET state = excluded.state,
                          entry_at = COALESCE(excluded.entry_at, edge_notifications.entry_at),
                          updated_at = excluded.updated_at
            """,
            (slug, event_date, outcome, side, state, entry_at, utc_now_iso()),
        )

    for row in rows:
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        for side in ("YES", "NO"):
            if side == "YES":
                exit_flag = bool(row.get("edge_min_exit_yes"))
                reasons = row.get("edge_min_exit_reasons_yes") or []
                headroom = row.get("headroom_yes")
                ask = row.get("best_ask")
                q_val = row.get("q_entry") or row.get("q_calibrated") or row.get("q_round")
                lag = row.get("lag_yes")
            else:
                exit_flag = bool(row.get("edge_min_exit_no"))
                reasons = row.get("edge_min_exit_reasons_no") or []
                headroom = row.get("headroom_no")
                ask = row.get("best_ask_no")
                q_val = row.get("q_entry_no") or row.get("q_calibrated_no") or row.get("q_round_no")
                lag = row.get("lag_no")
            try:
                q_val_f = float(q_val) if q_val is not None else None
            except (TypeError, ValueError):
                q_val_f = None
            try:
                ask_val = float(ask) if ask is not None else None
            except (TypeError, ValueError):
                ask_val = None
            signal_edge_val = (
                (q_val_f - ask_val)
                if q_val_f is not None
                and ask_val is not None
                and math.isfinite(q_val_f)
                and math.isfinite(ask_val)
                else None
            )
            use_edge_bias = (
                _env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_EDGE_CONFIDENCE", False)
                or _env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_EDGE_BIAS", False)
                or _env_bool("PM_AUTO_TRADE_ENTRY_APPLY_EDGE_BIAS", False)
            )
            bias_ok = True
            if use_edge_bias:
                _load_edge_bias_calibration(MINUTE_EDGE_ENTRY_BIAS_DAYS)
                pred_edge_points = (
                    (q_val_f - ask_val) * 100.0
                    if q_val_f is not None and ask_val is not None and math.isfinite(q_val_f) and math.isfinite(ask_val)
                    else None
                )
                bias_mean, ratio = _resolve_edge_bias(pred_edge_points)
                if _env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_EDGE_CONFIDENCE", False):
                    if ratio is None or not math.isfinite(ratio) or ratio < MINUTE_EDGE_ENTRY_CONFIDENCE_MIN:
                        bias_ok = False
                if _env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_EDGE_BIAS", False):
                    if bias_mean is None or not math.isfinite(bias_mean) or bias_mean < MINUTE_EDGE_ENTRY_BIAS_MIN:
                        bias_ok = False
            edge_min_eval = (
                signal_edge_val if signal_edge_val is not None and math.isfinite(signal_edge_val) else -999.0
            )
            band_ok = True
            if _env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_EDGE_BAND", False):
                if MINUTE_EDGE_ENTRY_EDGE_BANDS:
                    band_ok = any(
                        edge_min_eval >= band_min and edge_min_eval <= band_max
                        for band_min, band_max in MINUTE_EDGE_ENTRY_EDGE_BANDS
                    )
                else:
                    band_ok = False
            q_band_ok = True
            if _env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_Q_BAND", False):
                try:
                    q_val = float(q_val) if q_val is not None else None
                except (TypeError, ValueError):
                    q_val = None
                if MINUTE_EDGE_ENTRY_Q_BANDS and q_val is not None and math.isfinite(q_val):
                    q_band_ok = any(
                        q_val >= band_min and q_val <= band_max
                        for band_min, band_max in MINUTE_EDGE_ENTRY_Q_BANDS
                    )
                else:
                    q_band_ok = False
            state = "exit" if exit_flag else (
                "entry"
                if edge_min_eval > MINUTE_EDGE_ENTRY_EDGE_MIN and band_ok and q_band_ok and bias_ok
                else "none"
            )
            prev_entry = prev_states.get((outcome, side), {})
            prev_state = prev_entry.get("state")
            if state == "entry" and prev_state != "entry":
                _update_state(outcome, side, "entry", utc_now_iso())
            elif state == "exit" and prev_state == "entry":
                _update_state(outcome, side, "exit")
            elif state == "none" and prev_state != "none":
                _update_state(outcome, side, "none", "")
    now_iso = utc_now_iso_ms()
    reconcile_exit_no_position_blockers(cur, now_iso=now_iso)
    conn.commit()
    conn.close()


def execute_auto_trades(
    run_date: str,
    event_date: str,
    result: Dict,
    *,
    exit_only: bool = False,
    run_id: Optional[int] = None,
    positions_snapshot: Optional[Dict[str, Dict[str, Any]]] = None,
    positions_snapshot_error: str = "",
    settled_reconcile_context: Optional[Dict[str, Any]] = None,
    direct_job_context: bool = False,
) -> None:
    # NOTE: AUTO_TRADE_ENABLED is an env-driven switch and must be refreshed at runtime
    # (LaunchAgents/UI restarts/toggles can change env without reloading the module).
    global AUTO_TRADE_ENABLED, AUTO_TRADE_SYNC_TRADES
    AUTO_TRADE_ENABLED = os.environ.get("PM_AUTO_TRADE_ENABLED", "0").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    AUTO_TRADE_SYNC_TRADES = os.environ.get("PM_AUTO_TRADE_SYNC_TRADES", "1").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    if isinstance(result, dict):
        _apply_temperature_path_trade_follow_gate_to_targets(result)
    direct_target_job = bool(direct_job_context or _auto_trade_payload_is_direct_target_job(result))
    direct_primary_entry_fast_slice = bool(
        direct_target_job
        and not exit_only
        and result.get("direct_target_primary_entry_fast_slice")
        and _direct_target_primary_only_fast_path_enabled(result)
    )
    auto_trade_dry_run = _auto_trade_dry_run_enabled()
    if not AUTO_TRADE_ENABLED and not exit_only:
        # Allow dry-run entry evaluation for diagnostics even if auto-trade is disabled.
        if auto_trade_dry_run:
            AUTO_TRADE_ENABLED = True
        else:
            # Allow exits even when auto-trade is disabled (no new entries).
            exit_only = True
    _refresh_auto_trade_config()
    slug = str(result.get("slug") or "")
    title = str(result.get("title") or "")
    event_url = str(result.get("event_url") or "")
    if not event_url and slug:
        event_url = f"https://polymarket.com/event/{slug}"
    if not slug or not event_date:
        return
    event_date_key = event_date.split("T", 1)[0] if event_date else ""
    rows = result.get("rows") or []
    if not rows:
        return
    hard_source_sla_result_context: Dict[str, Any] = {}
    result_hard_block = result.get("hard_source_direct")
    if isinstance(result_hard_block, Mapping):
        if result_hard_block.get("source"):
            hard_source_sla_result_context["hard_source_source_id"] = result_hard_block.get("source")
        if result_hard_block.get("observed_at"):
            hard_source_sla_result_context["hard_source_observed_at"] = result_hard_block.get("observed_at")
            hard_source_sla_result_context["hard_source_seen_at"] = result_hard_block.get("observed_at")
        if result_hard_block.get("fetched_at"):
            hard_source_sla_result_context["hard_source_fetched_at"] = result_hard_block.get("fetched_at")
        if result_hard_block.get("ssot_written_at"):
            hard_source_sla_result_context["hard_source_ssot_written_at"] = result_hard_block.get("ssot_written_at")
        if result_hard_block.get("ssot_write_ms") is not None:
            hard_source_sla_result_context["hard_source_ssot_write_ms"] = result_hard_block.get("ssot_write_ms")
        if result_hard_block.get("job_enqueued_at"):
            hard_source_sla_result_context["hard_source_job_enqueued_at"] = result_hard_block.get("job_enqueued_at")
        if result_hard_block.get("worker_started_at"):
            hard_source_sla_result_context["hard_source_worker_started_at"] = result_hard_block.get("worker_started_at")
        if result_hard_block.get("target_bucket"):
            hard_source_sla_result_context["outcome"] = result_hard_block.get("target_bucket")
        hard_source_sla_result_context["hard_source_direct"] = True
        hard_source_sla_result_context["hard_source_posterior_override"] = True
        _merge_hard_source_direct_block_context(
            hard_source_sla_result_context,
            result_hard_block,
        )
    result_hard_timing = result.get("hard_source_direct_timing")
    if isinstance(result_hard_timing, Mapping):
        timing_aliases = {
            "seen_at": "hard_source_seen_at",
            "fetched_at": "hard_source_fetched_at",
            "decision_started_at": "hard_source_decision_started_at",
            "ssot_written_at": "hard_source_ssot_written_at",
            "seen_to_ssot_ms": "hard_source_seen_to_ssot_ms",
            "fetch_to_ssot_ms": "hard_source_fetch_to_ssot_ms",
        }
        for src_key, dst_key in timing_aliases.items():
            if result_hard_timing.get(src_key) is not None:
                hard_source_sla_result_context[dst_key] = result_hard_timing.get(src_key)
        hard_source_sla_result_context["hard_source_direct"] = True
        hard_source_sla_result_context["hard_source_posterior_override"] = True
    for row_ref in rows:
        if not isinstance(row_ref, Mapping):
            continue
        if not (row_ref.get("hard_source_direct") or row_ref.get("hard_source_ssot_written_at")):
            continue
        _copy_hard_source_sla_fields(hard_source_sla_result_context, row_ref)
        if row_ref.get("outcome") and not hard_source_sla_result_context.get("outcome"):
            hard_source_sla_result_context["outcome"] = row_ref.get("outcome")
        break
    event_tz = str(
        result.get("tz")
        or result.get("timezone")
        or ((rows[0] or {}).get("tz") if isinstance(rows[0], Mapping) else "")
        or ""
    )
    event_timing_enabled = bool(
        direct_target_job or exit_only or _env_bool("PM_AUTO_TRADE_EVENT_STAGE_TIMINGS", False)
    )
    event_timing_threshold_sec = _env_float("PM_AUTO_TRADE_EVENT_STAGE_TIMINGS_MIN_SEC")
    if (
        event_timing_threshold_sec is None
        or not math.isfinite(event_timing_threshold_sec)
        or event_timing_threshold_sec < 0
    ):
        event_timing_threshold_sec = 1.0
    event_started_monotonic = time.monotonic()
    event_stage_timings: Dict[str, float] = {}
    event_stage_meta: Dict[str, Any] = {}

    def _event_stage_start() -> float:
        return time.monotonic()

    def _event_stage_end(name: str, started: Optional[float]) -> None:
        if started is None:
            return
        try:
            elapsed = max(0.0, time.monotonic() - float(started))
        except Exception:
            return
        prev = to_float(event_stage_timings.get(name))
        if prev is not None and math.isfinite(prev):
            elapsed += float(prev)
        event_stage_timings[name] = round(float(elapsed), 3)

    @contextmanager
    def _event_stage_scope(name: str, *, enabled: bool = True) -> Iterable[None]:
        started = _event_stage_start() if enabled else None
        try:
            yield
        finally:
            if enabled:
                _event_stage_end(name, started)

    def _emit_event_stage_timings() -> None:
        if not event_timing_enabled:
            return
        total_sec = max(0.0, time.monotonic() - event_started_monotonic)
        if total_sec + TIME_EDGE_Q_EPS < float(event_timing_threshold_sec):
            return
        parts = [f"total={total_sec:.3f}s"]
        for stage_name in (
            "state_load",
            "orderbook_missing_cooldown",
            "target_switch_priority_prepare",
            "row_token_hydration",
            "rules_hydration",
            "payload_fallback_load",
            "latest_tick_fill",
            "trade_sync",
            "row_processing",
            "entry_candidates_build",
            "positions_fetch",
            "settled_reconcile",
            "preflight_queries",
            "open_orders_sync",
            "snapshot_consistency_load",
            "market_tick_refresh",
            "direct_target_fast_prepare",
            "direct_target_fast_submit",
            "direct_target_fast_finalize",
            "order_confirm",
            "exit_rows_focus",
            "exit_row_prepare",
            "exit_quote_refresh",
            "exit_open_order_probe",
            "exit_trigger_eval",
            "exit_submit",
            "exit_post_submit_confirm",
            "decision_finalize",
        ):
            stage_val = to_float(event_stage_timings.get(stage_name))
            if stage_val is None or not math.isfinite(stage_val):
                continue
            parts.append(f"{stage_name}={float(stage_val):.3f}s")
        positions_source_meta = str(event_stage_meta.get("positions_source") or "").strip()
        if positions_source_meta:
            parts.append(f"positions_src={positions_source_meta}")
        positions_count_meta = event_stage_meta.get("positions_count")
        if positions_count_meta is not None:
            try:
                parts.append(f"positions_count={int(positions_count_meta)}")
            except Exception:
                pass
        positions_cache_age_meta = to_float(event_stage_meta.get("positions_cache_age_sec"))
        if positions_cache_age_meta is not None and math.isfinite(positions_cache_age_meta):
            parts.append(f"positions_age={float(positions_cache_age_meta):.1f}s")
        open_orders_source_meta = str(event_stage_meta.get("open_orders_source") or "").strip()
        if open_orders_source_meta:
            parts.append(f"open_orders_src={open_orders_source_meta}")
        open_orders_cache_age_meta = to_float(event_stage_meta.get("open_orders_cache_age_sec"))
        if open_orders_cache_age_meta is not None and math.isfinite(open_orders_cache_age_meta):
            parts.append(f"open_orders_age={float(open_orders_cache_age_meta):.1f}s")
        trade_sync_token_count_meta = event_stage_meta.get("trade_sync_token_count")
        if trade_sync_token_count_meta is not None:
            try:
                parts.append(f"trade_sync_tokens={int(trade_sync_token_count_meta)}")
            except Exception:
                pass
        trade_sync_allowed_meta = event_stage_meta.get("trade_sync_allowed")
        if trade_sync_allowed_meta is not None:
            parts.append(f"trade_sync_allowed={1 if trade_sync_allowed_meta else 0}")
        trade_sync_due_meta = event_stage_meta.get("trade_sync_due")
        if trade_sync_due_meta is not None:
            parts.append(f"trade_sync_due={1 if trade_sync_due_meta else 0}")
        snap_rows_meta = event_stage_meta.get("snapshot_consistency_rows")
        if snap_rows_meta is not None:
            try:
                parts.append(f"snapshot_rows={int(snap_rows_meta)}")
            except Exception:
                pass
        exit_rows_before_meta = event_stage_meta.get("exit_rows_before_focus")
        exit_rows_after_meta = event_stage_meta.get("exit_rows_after_focus")
        if exit_rows_before_meta is not None and exit_rows_after_meta is not None:
            try:
                parts.append(f"exit_rows={int(exit_rows_before_meta)}->{int(exit_rows_after_meta)}")
            except Exception:
                pass
        exit_held_outcomes_meta = event_stage_meta.get("exit_held_outcomes")
        if exit_held_outcomes_meta is not None:
            try:
                parts.append(f"exit_held_outcomes={int(exit_held_outcomes_meta)}")
            except Exception:
                pass
        print(
            f"[auto-trade] event timings {slug} {event_date.split('T', 1)[0]} "
            f"exit_only={1 if exit_only else 0} {' '.join(parts)}"
        )
    entry_orderbook_missing_cooldown_sec = _env_int(
        "PM_AUTO_TRADE_ENTRY_ORDERBOOK_MISSING_COOLDOWN_SEC"
    )
    if (
        entry_orderbook_missing_cooldown_sec is None
        or entry_orderbook_missing_cooldown_sec < 0
    ):
        entry_orderbook_missing_cooldown_sec = 900
    entry_orderbook_missing_cooldown_min_hits = _env_int(
        "PM_AUTO_TRADE_ENTRY_ORDERBOOK_MISSING_COOLDOWN_MIN_HITS"
    )
    if (
        entry_orderbook_missing_cooldown_min_hits is None
        or entry_orderbook_missing_cooldown_min_hits <= 0
    ):
        entry_orderbook_missing_cooldown_min_hits = 2
    if direct_target_job and _env_bool(
        "PM_TARGET_REALIZATION_DIRECT_SKIP_ORDERBOOK_MISSING_COOLDOWN",
        True,
    ):
        entry_orderbook_missing_cooldown_sec = 0
    orderbook_missing_recent_threshold = max(
        1,
        int(entry_orderbook_missing_cooldown_min_hits),
    )
    recent_orderbook_missing_tokens: Set[str] = set()
    recent_orderbook_missing_counts: Dict[str, int] = {}
    orderbook_missing_cooldown_started = _event_stage_start()
    if entry_orderbook_missing_cooldown_sec > 0:
        window_sql = f"-{int(entry_orderbook_missing_cooldown_sec)} seconds"
        try:
            with open_db() as conn_recent_ob:
                cur_recent_ob = conn_recent_ob.cursor()
                cur_recent_ob.execute(
                    """
                    SELECT json_extract(d.details_json, '$.token_id') AS token_id,
                           COUNT(*) AS hit_count
                    FROM auto_trade_decisions d
                    JOIN json_each(d.reason_codes_json) rc
                    WHERE d.slug = ?
                      AND d.event_date = ?
                      AND d.action = 'entry'
                      AND rc.value = 'orderbook_missing'
                      AND datetime(substr(d.created_at, 1, 19)) >= datetime('now', ?)
                    GROUP BY json_extract(d.details_json, '$.token_id')
                    """,
                    (slug, event_date, window_sql),
                )
                for row_recent_ob in cur_recent_ob.fetchall() or []:
                    token_val = ""
                    hit_count = 0
                    if isinstance(row_recent_ob, sqlite3.Row):
                        token_val = str(row_recent_ob["token_id"] or "").strip()
                        try:
                            hit_count = int(row_recent_ob["hit_count"] or 0)
                        except Exception:
                            hit_count = 0
                    elif isinstance(row_recent_ob, tuple) and row_recent_ob:
                        token_val = str(row_recent_ob[0] or "").strip()
                        try:
                            hit_count = int(row_recent_ob[1] or 0)
                        except Exception:
                            hit_count = 0
                    if token_val:
                        recent_orderbook_missing_counts[token_val] = max(0, int(hit_count))
                        if int(hit_count) >= int(orderbook_missing_recent_threshold):
                            recent_orderbook_missing_tokens.add(token_val)
        except Exception:
            recent_orderbook_missing_tokens = set()
            recent_orderbook_missing_counts = {}
    _event_stage_end("orderbook_missing_cooldown", orderbook_missing_cooldown_started)

    def _orderbook_missing_recent_hits(token_id: str) -> int:
        token_key = str(token_id or "").strip()
        if not token_key:
            return 0
        return int(recent_orderbook_missing_counts.get(token_key) or 0)

    def _is_orderbook_missing_recent_token(token_id: str) -> bool:
        token_key = str(token_id or "").strip()
        if not token_key:
            return False
        if entry_orderbook_missing_cooldown_sec <= 0:
            return False
        return _orderbook_missing_recent_hits(token_key) >= int(orderbook_missing_recent_threshold)

    def _mark_orderbook_missing_recent_token(token_id: str, add_hits: int = 1) -> int:
        token_key = str(token_id or "").strip()
        if not token_key:
            return 0
        hit_inc = max(1, int(add_hits or 1))
        hit_count = int(recent_orderbook_missing_counts.get(token_key) or 0) + hit_inc
        recent_orderbook_missing_counts[token_key] = int(hit_count)
        if int(hit_count) >= int(orderbook_missing_recent_threshold):
            recent_orderbook_missing_tokens.add(token_key)
        return int(hit_count)

    if recent_orderbook_missing_tokens:
        hit_max = max(_orderbook_missing_recent_hits(tk) for tk in recent_orderbook_missing_tokens)
        print(
            "[auto-trade] orderbook-missing cooldown "
            f"slug={slug} tokens={len(recent_orderbook_missing_tokens)} "
            f"window={int(entry_orderbook_missing_cooldown_sec)}s "
            f"min_hits={int(entry_orderbook_missing_cooldown_min_hits)} "
            f"max_hits={int(hit_max)}"
        )

    positions_priority_fast_loop, positions_priority_allow_slow = _auto_trade_positions_priority_fast_loop_state()
    slow_request_used = False

    def _mark_slow_request_used() -> None:
        nonlocal slow_request_used
        if positions_priority_fast_loop and not slow_request_used:
            slow_request_used = True
            _auto_trade_positions_priority_mark_slow_request()

    def _fmt_price(value: Optional[float]) -> str:
        price_val = to_float(value)
        if price_val is None or not math.isfinite(price_val):
            return "—"
        return f"{float(price_val):.3f}"

    entry_drawdown_blocked, entry_drawdown_detail = _resolve_entry_drawdown_block()
    lcb_global_daily_loss_blocked = False
    lcb_global_daily_loss_detail: Dict[str, Any] = {}
    try:
        lcb_global_daily_loss_blocked, lcb_global_daily_loss_detail = _resolve_lcb_global_daily_loss_block(
            run_date
        )
    except Exception as exc:
        lcb_global_daily_loss_blocked = False
        lcb_global_daily_loss_detail = {}
        print(f"[auto-trade] lcb_global daily-loss check failed {slug} {event_date}: {exc}")

    # --- Executable-edge runtime repricing (SSOT for decision-time gates) ---
    # We reprice exec_edge_entry/edge_realizable_score using the *actual order semantics* we will submit:
    # - Passive limit: executable_price == submitted limit price (mid / discounted ask, etc.)
    # - Crossing limit (pay-up): executable_price simulated against current ask stack with cap=limit price
    # - Market (FAK/FOK): executable_price simulated against ask stack by notional amount (optional cap)
    #
    # This is intentionally kept local to this run (per execute_auto_trades call) with a small cache to
    # avoid excessive orderbook fetches across candidates.
    exec_edge_ob_timeout_sec = _env_float("PM_AUTO_TRADE_EXEC_EDGE_ORDERBOOK_TIMEOUT_SEC")
    if exec_edge_ob_timeout_sec is None or not math.isfinite(exec_edge_ob_timeout_sec):
        exec_edge_ob_timeout_sec = 2.5
    if exec_edge_ob_timeout_sec <= 0:
        exec_edge_ob_timeout_sec = 2.5
    exec_edge_ob_retries = int(_env_float("PM_AUTO_TRADE_EXEC_EDGE_ORDERBOOK_RETRIES") or 1)
    exec_edge_ob_retries = max(0, min(exec_edge_ob_retries, 2))
    _exec_edge_book_cache: Dict[str, Dict[str, Any]] = {}

    def _get_exec_edge_book(token_id: str) -> Optional[Dict[str, Any]]:
        key = str(token_id or "").strip()
        if not key:
            return None
        if direct_target_job and not _env_bool("PM_AUTO_TRADE_DIRECT_JOB_FETCH_EXEC_EDGE_BOOK", False):
            return None
        cached = _exec_edge_book_cache.get(key)
        if isinstance(cached, dict):
            return cached
        try:
            book = fetch_orderbook(
                key,
                retries=int(exec_edge_ob_retries),
                backoff=0.15 if exec_edge_ob_retries > 0 else 0.0,
                timeout_sec=float(exec_edge_ob_timeout_sec),
            )
        except Exception:
            book = None
        if isinstance(book, dict):
            _exec_edge_book_cache[key] = book
            return book
        return None

    def _avg_price_for_amount(
        asks_levels: Any,
        amount_usdc: Optional[float],
        *,
        cap_price: Optional[float] = None,
    ) -> Tuple[Optional[float], float, float]:
        """Simulate BUY execution against ask stack given a notional amount (market orders)."""
        amt = to_float(amount_usdc)
        if amt is None or not math.isfinite(amt) or amt <= TIME_EDGE_Q_EPS:
            return None, 0.0, 0.0
        cap = to_float(cap_price)
        if cap is not None and (not math.isfinite(cap) or cap <= 0):
            cap = None
        levels = asks_levels if isinstance(asks_levels, list) else []
        parsed: List[Tuple[float, float]] = []
        for lvl in levels:
            if not isinstance(lvl, dict):
                continue
            p = to_float(lvl.get("price"))
            q = to_float(lvl.get("size"))
            if (
                p is None
                or q is None
                or (not math.isfinite(p))
                or (not math.isfinite(q))
                or p <= 0
                or q <= 0
            ):
                continue
            if cap is not None and p > cap + 1e-9:
                continue
            parsed.append((float(p), float(q)))
        if not parsed:
            return None, 0.0, 0.0
        parsed.sort(key=lambda it: it[0])
        remaining = float(amt)
        spent = 0.0
        filled = 0.0
        for price, qty in parsed:
            if remaining <= TIME_EDGE_Q_EPS:
                break
            level_cost = price * qty
            take_cost = level_cost if level_cost <= remaining else remaining
            take_qty = take_cost / price
            spent += take_cost
            filled += take_qty
            remaining -= take_cost
        if filled <= TIME_EDGE_Q_EPS:
            return None, 0.0, 0.0
        return spent / filled, filled, spent

    def _avg_price_for_size(
        asks_levels: Any,
        size_shares: Optional[float],
        *,
        cap_price: Optional[float] = None,
    ) -> Tuple[Optional[float], float, float]:
        """Simulate BUY execution against ask stack for a target share size (crossing limit / VWAP)."""
        size = to_float(size_shares)
        if size is None or not math.isfinite(size) or size <= TIME_EDGE_Q_EPS:
            return None, 0.0, 0.0
        cap = to_float(cap_price)
        if cap is not None and (not math.isfinite(cap) or cap <= 0):
            cap = None
        levels = asks_levels if isinstance(asks_levels, list) else []
        parsed: List[Tuple[float, float]] = []
        for lvl in levels:
            if not isinstance(lvl, dict):
                continue
            p = to_float(lvl.get("price"))
            q = to_float(lvl.get("size"))
            if (
                p is None
                or q is None
                or (not math.isfinite(p))
                or (not math.isfinite(q))
                or p <= 0
                or q <= 0
            ):
                continue
            if cap is not None and p > cap + 1e-9:
                continue
            parsed.append((float(p), float(q)))
        if not parsed:
            return None, 0.0, 0.0
        parsed.sort(key=lambda it: it[0])
        remaining = float(size)
        spent = 0.0
        filled = 0.0
        for price, qty in parsed:
            if remaining <= TIME_EDGE_Q_EPS:
                break
            take_qty = qty if qty <= remaining else remaining
            spent += take_qty * price
            filled += take_qty
            remaining -= take_qty
        if filled <= TIME_EDGE_Q_EPS:
            return None, 0.0, 0.0
        return spent / filled, filled, spent

    # Keep executable-edge cost components aligned with facts composer defaults.
    exec_spread_weight_runtime = _env_float("PM_EXEC_EDGE_SPREAD_WEIGHT")
    if exec_spread_weight_runtime is None or not math.isfinite(exec_spread_weight_runtime):
        exec_spread_weight_runtime = 0.25
    if exec_spread_weight_runtime < 0:
        exec_spread_weight_runtime = 0.0
    if exec_spread_weight_runtime > 1:
        exec_spread_weight_runtime = exec_spread_weight_runtime / 100.0
    exec_depth_penalty_weight_runtime = _env_float("PM_EXEC_EDGE_DEPTH_PENALTY_WEIGHT")
    if exec_depth_penalty_weight_runtime is None or not math.isfinite(exec_depth_penalty_weight_runtime):
        exec_depth_penalty_weight_runtime = 1.0
    if exec_depth_penalty_weight_runtime < 0:
        exec_depth_penalty_weight_runtime = 0.0
    exec_cancel_cost_runtime = _env_float("PM_EXEC_EDGE_CANCEL_COST")
    if exec_cancel_cost_runtime is None or not math.isfinite(exec_cancel_cost_runtime):
        exec_cancel_cost_runtime = 0.002
    if exec_cancel_cost_runtime < 0:
        exec_cancel_cost_runtime = 0.0
    if exec_cancel_cost_runtime > 1:
        exec_cancel_cost_runtime = exec_cancel_cost_runtime / 100.0
    exec_retry_cost_runtime = _env_float("PM_EXEC_EDGE_RETRY_COST")
    if exec_retry_cost_runtime is None or not math.isfinite(exec_retry_cost_runtime):
        exec_retry_cost_runtime = 0.001
    if exec_retry_cost_runtime < 0:
        exec_retry_cost_runtime = 0.0
    if exec_retry_cost_runtime > 1:
        exec_retry_cost_runtime = exec_retry_cost_runtime / 100.0
    exec_base_cost_runtime = float(exec_cancel_cost_runtime) + float(exec_retry_cost_runtime)

    def _liquidity_penalty_runtime(spread_val: Optional[float], ask_val: Optional[float]) -> float:
        penalty = 0.0
        spr = to_float(spread_val)
        ask = to_float(ask_val)
        if spr is not None and math.isfinite(spr):
            spread_pct = float(spr) * 100.0
            penalty += max(0.0, (spread_pct - 8.0) / 10.0)
        if ask is not None and math.isfinite(ask):
            penalty += max(0.0, (float(ask) - 0.6) / 0.2)
        return penalty
    expected_entry_targets: List[Dict[str, Any]] = []
    raw_expected_targets = result.get("entry_expected_targets")
    if isinstance(raw_expected_targets, list):
        for item in raw_expected_targets:
            if not isinstance(item, dict):
                continue
            item_slug = str(item.get("slug") or item.get("event_slug") or "").strip()
            item_date = _normalize_date_key(str(item.get("event_date") or "").strip())
            if item_slug and slug and item_slug != slug:
                continue
            if item_date and event_date_key and item_date != event_date_key:
                continue
            out = str(item.get("outcome") or "").strip()
            side = str(item.get("side") or "").strip().upper()
            strategy = str(item.get("strategy") or "").strip().lower()
            if not out or side not in {"YES", "NO"}:
                continue
            if strategy == "yes_top":
                continue
            expected_item: Dict[str, Any] = {
                "outcome": out,
                "side": side,
                "strategy": strategy,
                "entry_ok": bool(item.get("entry_ok")),
                "entry_reasons": list(item.get("entry_reasons") or [])
                if isinstance(item.get("entry_reasons"), list)
                else [],
                "edge_score": to_float(item.get("edge_score")),
                "edge_min": to_float(item.get("edge_min")),
                "ask": to_float(item.get("ask")),
                "q_min_bound": to_float(item.get("q_min_bound")),
                "spread": to_float(item.get("spread")),
                "lag": to_float(item.get("lag")),
                "token_id": str(item.get("token_id") or "").strip(),
                "slug": item_slug,
                "event_date": item_date,
            }
            for extra_key, extra_val in item.items():
                if extra_key in expected_item:
                    continue
                if extra_key in {"hard_source_acceptance_state", "signal_to_order_timing"} and isinstance(extra_val, Mapping):
                    expected_item[extra_key] = dict(extra_val)
                    continue
                if isinstance(extra_val, (str, int, float, bool)) or extra_val is None:
                    expected_item[extra_key] = extra_val
            expected_entry_targets.append(expected_item)
    expected_entry_targets_by_key: Dict[Tuple[str, str], Dict[str, Any]] = {}
    expected_entry_targets_by_outcome: Dict[str, List[Dict[str, Any]]] = {}
    for item in expected_entry_targets:
        if not isinstance(item, dict):
            continue
        key = (str(item.get("outcome") or ""), str(item.get("side") or "").upper())
        if not key[0] or key[1] not in {"YES", "NO"}:
            continue
        expected_entry_targets_by_key[key] = item
        expected_entry_targets_by_outcome.setdefault(key[0], []).append(item)
    hard_source_sla_by_entry_key: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for key, item in expected_entry_targets_by_key.items():
        if not isinstance(item, dict):
            continue
        if not bool(
            item.get("hard_source_direct")
            or item.get("hard_source_posterior_override")
            or _is_posterior_target_direct_candidate(item)
        ):
            continue
        hard_source_sla_by_entry_key[key] = item
    hard_source_sla_context: Dict[str, Any] = (
        next(iter(hard_source_sla_by_entry_key.values()), {})
        if hard_source_sla_by_entry_key
        else {}
    )
    if hard_source_sla_context and hard_source_sla_result_context:
        _copy_hard_source_sla_fields(hard_source_sla_context, hard_source_sla_result_context)
    if not hard_source_sla_context and hard_source_sla_result_context:
        hard_source_sla_context = dict(hard_source_sla_result_context)
    if hard_source_sla_context:
        context_outcome = str(hard_source_sla_context.get("outcome") or "").strip()
        context_side = str(hard_source_sla_context.get("side") or "YES").strip().upper()
        if context_outcome and context_side in {"YES", "NO"}:
            hard_source_sla_by_entry_key.setdefault(
                (context_outcome, context_side),
                dict(hard_source_sla_context),
            )
    hard_source_sla_by_row_key: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for row_item in rows:
        if not isinstance(row_item, Mapping):
            continue
        out_key = str(row_item.get("outcome") or row_item.get("label") or "").strip()
        if not out_key:
            continue
        if not bool(
            row_item.get("hard_source_direct")
            or row_item.get("hard_source_posterior_override")
            or _is_posterior_target_direct_candidate(row_item)
            or str(row_item.get("hard_source_ssot_written_at") or "").strip()
        ):
            continue
        hard_source_sla_by_row_key[(out_key, "YES")] = dict(row_item)
    if hard_source_sla_result_context:
        result_context_outcome = str(
            hard_source_sla_result_context.get("outcome") or ""
        ).strip()
        result_context_side = str(
            hard_source_sla_result_context.get("side") or "YES"
        ).strip().upper()
        for context_key, context_item in list(hard_source_sla_by_entry_key.items()):
            if (
                result_context_outcome
                and context_key[0] == result_context_outcome
                and (not result_context_side or context_key[1] == result_context_side)
            ):
                _copy_hard_source_sla_fields(context_item, hard_source_sla_result_context)
        for context_key, context_item in list(hard_source_sla_by_row_key.items()):
            if (
                result_context_outcome
                and context_key[0] == result_context_outcome
                and (not result_context_side or context_key[1] == result_context_side)
            ):
                _copy_hard_source_sla_fields(context_item, hard_source_sla_result_context)
    expected_entry_strategy: Dict[Tuple[str, str], str] = {
        key: str(item.get("strategy") or "").lower()
        for key, item in expected_entry_targets_by_key.items()
    }
    target_switch_entry_priority_enabled = _env_bool(
        "PM_TARGET_REALIZATION_SWITCH_ENTRY_FIRST",
        True,
    )
    target_switch_non_target_entry_suppression_enabled = _env_bool(
        "PM_TARGET_REALIZATION_SWITCH_SUPPRESS_NON_TARGET_ENTRY",
        True,
    )
    target_switch_expected_entry_keys: Set[Tuple[str, str]] = set()
    target_switch_primary_entry_keys: Set[Tuple[str, str]] = set()
    target_switch_priority_started = _event_stage_start()
    if target_switch_entry_priority_enabled and (not exit_only or direct_target_job):
        for key, item in expected_entry_targets_by_key.items():
            if str(item.get("target_realization_leg_role") or "").strip() == "old_bucket_reverse":
                continue
            entry_reasons = item.get("entry_reasons")
            reason_set = {
                str(reason or "").strip().lower()
                for reason in (entry_reasons if isinstance(entry_reasons, list) else [])
                if str(reason or "").strip()
            }
            if not reason_set.intersection(
                {"target_realization_switch", "target_realization_order_intent"}
            ):
                continue
            target_switch_expected_entry_keys.add(key)
            leg_role = str(item.get("target_realization_leg_role") or "").strip()
            if (
                _is_posterior_target_direct_buy_new_target(
                    item,
                    outcome=key[0],
                    side=key[1],
                )
                or (
                    key[1] == "YES"
                    and leg_role
                    in {
                        "new_bucket_entry",
                        "target_yes",
                        "posterior_target_direct_target",
                    }
                )
            ):
                target_switch_primary_entry_keys.add(key)
    if not target_switch_primary_entry_keys and target_switch_expected_entry_keys:
        target_switch_primary_entry_keys = set(target_switch_expected_entry_keys)
    target_switch_order_submitted_entry_keys: Set[Tuple[str, str]] = set()
    target_switch_expected_outcomes = {
        str(key[0] or "").strip()
        for key in target_switch_expected_entry_keys
        if str(key[0] or "").strip()
    }
    target_switch_primary_outcomes = {
        str(key[0] or "").strip()
        for key in target_switch_primary_entry_keys
        if str(key[0] or "").strip()
    }
    if target_switch_expected_outcomes and rows:
        original_rows_len = len(rows)
        rows = sorted(
            rows,
            key=lambda row_ref: (
                0
                if str((row_ref or {}).get("outcome") or "").strip()
                in target_switch_primary_outcomes
                else 1
                if str((row_ref or {}).get("outcome") or "").strip()
                in target_switch_expected_outcomes
                else 2
            ),
        )
        event_stage_meta["target_switch_entry_priority_rows"] = int(original_rows_len)
        event_stage_meta["target_switch_entry_priority_outcomes"] = sorted(
            target_switch_expected_outcomes
        )
        event_stage_meta["target_switch_primary_entry_outcomes"] = sorted(
            target_switch_primary_outcomes
        )
    _event_stage_end("target_switch_priority_prepare", target_switch_priority_started)
    market_var = str(result.get("market_var") or infer_market_variable(title, slug) or "")
    # Display threshold is a UI/visual hint. Entry gating uses a separate knob so that
    # "可下单" (per-outcome) does not get silently blocked by an unrelated event-level display threshold.
    temp_event_min_edge_score = AUTO_TRADE_TEMPERATURE_EVENT_MIN_EDGE_SCORE_ENTRY
    if temp_event_min_edge_score is None or not math.isfinite(temp_event_min_edge_score):
        temp_event_min_edge_score = 0.0
    if temp_event_min_edge_score < 0:
        temp_event_min_edge_score = 0.0
    entry_blocked_by_temp_edge_score = False
    def _resolve_event_lat_lon_for_consensus() -> Tuple[Optional[float], Optional[float], str]:
        for source, lat_raw, lon_raw in (
            ("result.lat_lon", result.get("lat"), result.get("lon")),
            ("result.latitude_longitude", result.get("latitude"), result.get("longitude")),
        ):
            lat_val = to_float(lat_raw)
            lon_val = to_float(lon_raw)
            if (
                lat_val is not None
                and lon_val is not None
                and math.isfinite(lat_val)
                and math.isfinite(lon_val)
            ):
                return float(lat_val), float(lon_val), source
        for row_ref in rows:
            if not isinstance(row_ref, dict):
                continue
            lat_raw = row_ref.get("lat")
            if lat_raw is None:
                lat_raw = row_ref.get("latitude")
            lon_raw = row_ref.get("lon")
            if lon_raw is None:
                lon_raw = row_ref.get("longitude")
            lat_val = to_float(lat_raw)
            lon_val = to_float(lon_raw)
            if (
                lat_val is not None
                and lon_val is not None
                and math.isfinite(lat_val)
                and math.isfinite(lon_val)
            ):
                return float(lat_val), float(lon_val), "row.lat_lon"
        if not slug or not event_date_key:
            return None, None, ""
        try:
            with open_db_ro_fast(timeout_sec=0.35, busy_timeout_ms=300) as conn:
                cur = conn.cursor()
                cur.execute(
                    f"""
                    SELECT lat, lon
                    FROM event_runs
                    WHERE slug = ?
                      AND event_date = ?
                      AND lat IS NOT NULL
                      AND lon IS NOT NULL
                    ORDER BY COALESCE(created_at, '') DESC, id DESC
                    LIMIT 1
                    """,
                    (slug, event_date_key),
                )
                coord_row = cur.fetchone()
            if coord_row:
                lat_val = to_float(coord_row[0])
                lon_val = to_float(coord_row[1])
                if (
                    lat_val is not None
                    and lon_val is not None
                    and math.isfinite(lat_val)
                    and math.isfinite(lon_val)
                ):
                    return float(lat_val), float(lon_val), "event_runs"
        except Exception as exc:
            event_stage_meta["consensus_coord_lookup_error"] = str(exc)[:160]
        return None, None, ""

    market_closed = bool(result.get("market_closed"))
    market_closed_direct_target_entry_override = bool(
        market_closed
        and direct_target_job
        and _payload_has_executable_direct_entry_target(result)
    )
    if market_closed and not exit_only:
        has_open_position = False
        try:
            init_db()
            with open_db() as conn:
                cur = conn.cursor()
                cur.execute(
                    """
                    SELECT 1
                    FROM edge_trades
                    WHERE slug = ? AND event_date = ?
                      AND (
                        (position_size IS NOT NULL AND position_size > ?)
                        OR state IN ('entry', 'entry_pending')
                      )
                    LIMIT 1
                    """,
                    (slug, event_date_key, TIME_EDGE_Q_EPS),
                )
                has_open_position = cur.fetchone() is not None
        except Exception:
            has_open_position = False
        if market_closed_direct_target_entry_override:
            event_stage_meta["market_closed_direct_target_entry_override"] = True
        elif not has_open_position:
            try:
                targets, targets_source = _resolve_fallback_diag_targets(result, slug, event_date_key)
                if targets:
                    _record_auto_trade_fallback_decisions(
                        run_id=run_id,
                        run_date=run_date,
                        slug=slug,
                        event_date=event_date_key,
                        title=title,
                        targets=targets,
                        reason_code="market_closed",
                        reason_text="市场已关闭且无持仓，跳过入场",
                        details={
                            "source": "execute_auto_trades_preflight",
                            "targets_source": targets_source,
                            "market_closed": True,
                        },
                        decided_state="blocked",
                        entry_only_realizable_mode=_env_bool(
                            "PM_AUTO_TRADE_ENTRY_ONLY_REALIZABLE",
                            True,
                        ),
                    )
            except Exception:
                pass
            return
        else:
            exit_only = True
    run_dt = _parse_date(run_date) or datetime.now(timezone.utc).date()
    event_dt = _parse_date(event_date_key)
    days_to_event: Optional[int] = None
    if event_dt is not None:
        try:
            days_to_event = (event_dt - run_dt).days
        except Exception:
            days_to_event = None
    if days_to_event is not None and days_to_event < 0:
        days_to_event = 0
    def _hydrate_row_tokens_from_market_cache(rows_ref: List[Dict[str, Any]]) -> None:
        if not rows_ref or not slug or not event_date_key:
            return
        market_meta_fields = (
            "market_active",
            "market_closed",
            "market_archived",
            "market_accepting_orders",
            "market_enable_orderbook",
        )
        outcome_exact: Dict[str, List[Dict[str, Any]]] = {}
        outcome_norm: Dict[str, List[Dict[str, Any]]] = {}
        for row_ref in rows_ref:
            if not isinstance(row_ref, dict):
                continue
            outcome_label = str(row_ref.get("outcome") or "").strip()
            if not outcome_label:
                continue
            outcome_exact.setdefault(outcome_label, []).append(row_ref)
            outcome_norm_key = _normalize_outcome_key(outcome_label)
            if outcome_norm_key:
                outcome_norm.setdefault(outcome_norm_key, []).append(row_ref)

        if not outcome_exact:
            return

        missing_tokens_before = 0
        missing_market_meta_before = 0
        market_meta_tighten_candidates_before = 0
        for row_ref in rows_ref:
            if not isinstance(row_ref, dict):
                continue
            if not str(row_ref.get("yes_token") or "").strip() or not str(
                row_ref.get("no_token") or ""
            ).strip():
                missing_tokens_before += 1
            if any(_coerce_optional_bool(row_ref.get(field)) is None for field in market_meta_fields):
                missing_market_meta_before += 1
            row_already_blocked = (
                _coerce_optional_bool(row_ref.get("market_closed")) is True
                or _coerce_optional_bool(row_ref.get("market_archived")) is True
                or _coerce_optional_bool(row_ref.get("market_active")) is False
                or _coerce_optional_bool(row_ref.get("market_accepting_orders")) is False
                or _coerce_optional_bool(row_ref.get("market_enable_orderbook")) is False
            )
            if not row_already_blocked:
                market_meta_tighten_candidates_before += 1
        if (
            missing_tokens_before <= 0
            and missing_market_meta_before <= 0
            and market_meta_tighten_candidates_before <= 0
        ):
            return

        token_rows: List[sqlite3.Row] = []
        try:
            init_db()
            with open_db() as conn_token:
                conn_token.row_factory = sqlite3.Row
                cur_token = conn_token.cursor()
                cur_token.execute(
                    """
                    SELECT
                        outcome,
                        yes_token,
                        no_token,
                        market_active,
                        market_closed,
                        market_archived,
                        market_accepting_orders,
                        market_enable_orderbook
                    FROM market_tokens
                    WHERE slug = ? AND event_date = ?
                    """,
                    (slug, event_date_key),
                )
                token_rows = cur_token.fetchall() or []
        except Exception:
            token_rows = []

        if not token_rows:
            return

        for token_row in token_rows:
            outcome_label = str(token_row["outcome"] or "").strip()
            if not outcome_label:
                continue
            yes_token = str(token_row["yes_token"] or "").strip()
            no_token = str(token_row["no_token"] or "").strip()
            market_meta_values = {
                "market_active": _coerce_optional_bool(token_row["market_active"]),
                "market_closed": _coerce_optional_bool(token_row["market_closed"]),
                "market_archived": _coerce_optional_bool(token_row["market_archived"]),
                "market_accepting_orders": _coerce_optional_bool(token_row["market_accepting_orders"]),
                "market_enable_orderbook": _coerce_optional_bool(token_row["market_enable_orderbook"]),
            }
            matched_rows = outcome_exact.get(outcome_label) or []
            if not matched_rows:
                outcome_norm_key = _normalize_outcome_key(outcome_label)
                if outcome_norm_key:
                    matched_rows = outcome_norm.get(outcome_norm_key) or []
            if not matched_rows:
                continue
            for row_ref in matched_rows:
                if yes_token and not str(row_ref.get("yes_token") or "").strip():
                    row_ref["yes_token"] = yes_token
                if no_token and not str(row_ref.get("no_token") or "").strip():
                    row_ref["no_token"] = no_token
                for field_name, field_val in market_meta_values.items():
                    if field_val is None:
                        continue
                    current_val = _coerce_optional_bool(row_ref.get(field_name))
                    if current_val is None:
                        row_ref[field_name] = field_val
                        continue
                    # Runtime market_tokens are allowed to tighten stale fact rows.
                    # Never use an open/accepting cache value to loosen a blocked row.
                    if field_name in {"market_closed", "market_archived"} and field_val is True:
                        row_ref[field_name] = True
                    elif (
                        field_name
                        in {"market_active", "market_accepting_orders", "market_enable_orderbook"}
                        and field_val is False
                    ):
                        row_ref[field_name] = False

        missing_tokens_after = 0
        missing_market_meta_after = 0
        market_meta_tightened_after = 0
        for row_ref in rows_ref:
            if not isinstance(row_ref, dict):
                continue
            if not str(row_ref.get("yes_token") or "").strip() or not str(
                row_ref.get("no_token") or ""
            ).strip():
                missing_tokens_after += 1
            if any(_coerce_optional_bool(row_ref.get(field)) is None for field in market_meta_fields):
                missing_market_meta_after += 1
            if (
                _coerce_optional_bool(row_ref.get("market_closed")) is True
                or _coerce_optional_bool(row_ref.get("market_archived")) is True
                or _coerce_optional_bool(row_ref.get("market_active")) is False
                or _coerce_optional_bool(row_ref.get("market_accepting_orders")) is False
                or _coerce_optional_bool(row_ref.get("market_enable_orderbook")) is False
            ):
                market_meta_tightened_after += 1
        recovered_tokens = max(0, missing_tokens_before - missing_tokens_after)
        recovered_market_meta = max(0, missing_market_meta_before - missing_market_meta_after)
        if recovered_tokens > 0 or recovered_market_meta > 0 or market_meta_tightened_after > 0:
            print(
                "[auto-trade] token hydration "
                f"slug={slug} event_date={event_date_key} recovered_tokens={recovered_tokens} "
                f"missing_tokens_after={missing_tokens_after} "
                f"recovered_market_meta={recovered_market_meta} "
                f"missing_market_meta_after={missing_market_meta_after} "
                f"market_meta_tightened={market_meta_tightened_after}"
            )

    def _hydrate_row_rules_from_context(rows_ref: List[Dict[str, Any]]) -> None:
        if not rows_ref or not slug or not event_date_key:
            return

        rule_fields = (
            "resolution_source",
            "station_id",
            "rounding_rule",
            "market_var",
            "market_unit",
        )
        source_profile_fields = (
            "source_kind",
            "source_confidence",
            "source_fit_tier",
            "source_trust_tier",
            "source_usable_for_settlement",
            "source_station_id",
            "source_station_expected",
            "source_station_match",
            "source_station_match_reason",
            "source_aux_only",
            "publication_cadence",
            "source_na_reason",
        )

        def _is_empty(value: Any) -> bool:
            if value is None:
                return True
            if isinstance(value, str):
                return not value.strip()
            return False

        def _normalize_missing(value: Any) -> List[str]:
            if isinstance(value, list):
                return [str(v or "").strip() for v in value if str(v or "").strip()]
            text = str(value or "").strip()
            if not text:
                return []
            try:
                parsed = json.loads(text)
                if isinstance(parsed, list):
                    return [str(v or "").strip() for v in parsed if str(v or "").strip()]
            except Exception:
                pass
            return [part.strip() for part in re.split(r"[,;|]", text) if part.strip()]

        def _row_needs_rules(row_ref: Mapping[str, Any]) -> bool:
            if _coerce_optional_bool(row_ref.get("rules_contract_ok")) is not True:
                return True
            market_var_local = str(row_ref.get("market_var") or result.get("market_var") or "").strip()
            if _is_empty(row_ref.get("resolution_source")):
                return True
            if is_temperature_market_var(market_var_local):
                for field_name in ("station_id", "market_var", "market_unit"):
                    if _is_empty(row_ref.get(field_name)):
                        return True
                source_profile = weather_resolution_source_profile(
                    str(row_ref.get("resolution_source") or result.get("resolution_source") or "").strip(),
                    station_id=str(row_ref.get("station_id") or result.get("station_id") or "").strip() or None,
                    description=str(result.get("description") or ""),
                )
                if source_profile.get("source_usable_for_settlement") is not True:
                    return True
            return False

        needs_before = sum(
            1 for row_ref in rows_ref if isinstance(row_ref, dict) and _row_needs_rules(row_ref)
        )
        if needs_before <= 0:
            return

        values: Dict[str, Any] = {}
        rules_ok: Optional[bool] = None
        missing_reasons: List[str] = []
        source = ""

        def _fill_value(key: str, value: Any) -> None:
            if key not in rule_fields:
                return
            if _is_empty(value):
                return
            if _is_empty(values.get(key)):
                values[key] = value

        def _apply_profile(profile: Any, source_name: str) -> None:
            nonlocal rules_ok, missing_reasons, source
            if not isinstance(profile, Mapping):
                return
            for field_name in rule_fields:
                _fill_value(field_name, profile.get(field_name))
            profile_ok = _coerce_optional_bool(profile.get("ok"))
            if profile_ok is True:
                rules_ok = True
                missing_reasons = []
            elif profile_ok is False and rules_ok is None:
                rules_ok = False
            profile_missing = _normalize_missing(profile.get("missing_reasons"))
            if profile_missing and not missing_reasons and rules_ok is not True:
                missing_reasons = profile_missing
            if source_name and not source:
                source = source_name

        def _merge_result_rule_values() -> None:
            profile_obj = result.get("contract_profile")
            profile: Dict[str, Any] = dict(profile_obj) if isinstance(profile_obj, Mapping) else {}
            profile_changed = False
            for field_name, field_value in values.items():
                if _is_empty(field_value):
                    continue
                if _is_empty(result.get(field_name)):
                    result[field_name] = field_value
                if _is_empty(profile.get(field_name)):
                    profile[field_name] = field_value
                    profile_changed = True
            if rules_ok is not None:
                if _coerce_optional_bool(result.get("rules_contract_ok")) is None:
                    result["rules_contract_ok"] = bool(rules_ok)
                if _coerce_optional_bool(profile.get("ok")) is None:
                    profile["ok"] = bool(rules_ok)
                    profile_changed = True
            if missing_reasons:
                if not result.get("rules_missing_reasons"):
                    result["rules_missing_reasons"] = list(missing_reasons)
                if not profile.get("missing_reasons"):
                    profile["missing_reasons"] = list(missing_reasons)
                    profile_changed = True
            if source and _is_empty(result.get("rules_hydration_source")):
                result["rules_hydration_source"] = source
            if profile_changed and profile:
                result["contract_profile"] = profile

        def _persist_event_run_rules_merge_fill() -> None:
            if not _env_bool("PM_AUTO_TRADE_RULES_CACHE_MERGE_FILL", True):
                return
            usable_values = {
                field_name: field_value
                for field_name, field_value in values.items()
                if field_name in rule_fields and not _is_empty(field_value)
            }
            if not usable_values:
                return
            try:
                init_db()
                with open_db(
                    autocommit=True,
                    connect_timeout_sec=0.8,
                    busy_timeout_ms=800,
                ) as conn_rules_cache:
                    conn_rules_cache.row_factory = sqlite3.Row
                    latest_row = conn_rules_cache.execute(
                        """
                        SELECT id
                        FROM event_runs
                        WHERE slug = ? AND event_date = ?
                        ORDER BY COALESCE(created_at, '') DESC, id DESC
                        LIMIT 1
                        """,
                        (slug, event_date_key),
                    ).fetchone()
                    if not latest_row:
                        return
                    set_parts: List[str] = []
                    params: List[Any] = []
                    for field_name in rule_fields:
                        field_value = usable_values.get(field_name)
                        if _is_empty(field_value):
                            continue
                        set_parts.append(
                            f"{field_name} = CASE "
                            f"WHEN {field_name} IS NULL OR TRIM(CAST({field_name} AS TEXT)) = '' "
                            f"THEN ? ELSE {field_name} END"
                        )
                        params.append(field_value)
                    if not set_parts:
                        return
                    params.append(int(latest_row["id"]))
                    conn_rules_cache.execute(
                        f"UPDATE event_runs SET {', '.join(set_parts)} WHERE id = ?",
                        tuple(params),
                    )
            except Exception as exc:
                try:
                    event_stage_meta["rules_hydration_cache_error"] = str(exc)[:160]
                except Exception:
                    pass

        def _derive_rules_state_from_values() -> None:
            nonlocal rules_ok, missing_reasons
            market_var_local = str(values.get("market_var") or result.get("market_var") or "").strip()
            if rules_ok is True:
                if is_temperature_market_var(market_var_local):
                    source_for_profile = str(values.get("resolution_source") or result.get("resolution_source") or "").strip()
                    if source_for_profile:
                        source_profile = weather_resolution_source_profile(
                            source_for_profile,
                            station_id=str(values.get("station_id") or result.get("station_id") or "").strip() or None,
                            description=str(result.get("description") or ""),
                        )
                        if source_profile.get("source_usable_for_settlement") is not True:
                            rules_ok = False
                            missing_reasons = [
                                str(source_profile.get("source_na_reason") or "resolution_source_untrusted")
                            ]
                            return
                return
            derived_missing: List[str] = []
            if _is_empty(values.get("resolution_source")):
                derived_missing.append("resolution_source")
            if is_temperature_market_var(market_var_local):
                if _is_empty(values.get("station_id")):
                    derived_missing.append("station_id")
                if _is_empty(values.get("market_unit")):
                    derived_missing.append("market_unit")
                if _is_empty(market_var_local):
                    derived_missing.append("market_var")
                source_for_profile = str(values.get("resolution_source") or result.get("resolution_source") or "").strip()
                if source_for_profile:
                    source_profile = weather_resolution_source_profile(
                        source_for_profile,
                        station_id=str(values.get("station_id") or result.get("station_id") or "").strip() or None,
                        description=str(result.get("description") or ""),
                    )
                    if source_profile.get("source_usable_for_settlement") is not True:
                        reason = str(source_profile.get("source_na_reason") or "resolution_source_untrusted")
                        if reason not in derived_missing:
                            derived_missing.append(reason)
            if market_var_local and not derived_missing:
                field_missing_only = False
                if rules_ok is False and missing_reasons:
                    missing_set = {
                        str(item or "").strip().lower()
                        for item in missing_reasons
                        if str(item or "").strip()
                    }
                    field_missing_only = bool(missing_set) and missing_set.issubset(
                        {"resolution_source", "station_id", "market_unit", "market_var"}
                    )
                if rules_ok is None or field_missing_only:
                    rules_ok = True
                    missing_reasons = []
            elif derived_missing and not missing_reasons:
                missing_reasons = derived_missing

        _apply_profile(result.get("contract_profile"), "result.contract_profile")
        for field_name in rule_fields:
            _fill_value(field_name, result.get(field_name))
        result_rules_ok = _coerce_optional_bool(result.get("rules_contract_ok"))
        if result_rules_ok is True:
            rules_ok = True
            missing_reasons = []
        elif result_rules_ok is False and rules_ok is None:
            rules_ok = False
            if not source:
                source = "result"
        result_missing = _normalize_missing(result.get("rules_missing_reasons"))
        if result_missing and not missing_reasons and rules_ok is not True:
            missing_reasons = result_missing

        if rules_ok is not True or any(_is_empty(values.get(field_name)) for field_name in ("resolution_source", "market_var", "market_unit")):
            try:
                with open_db_ro_fast(timeout_sec=0.6, busy_timeout_ms=500) as conn_rules:
                    conn_rules.row_factory = sqlite3.Row
                    rule_row = conn_rules.execute(
                        """
                        SELECT
                            resolution_source,
                            station_id,
                            rounding_rule,
                            market_var,
                            market_unit,
                            payload_json
                        FROM event_runs
                        WHERE slug = ? AND event_date = ?
                          AND (
                            COALESCE(resolution_source, '') != ''
                            OR COALESCE(station_id, '') != ''
                            OR COALESCE(market_var, '') != ''
                            OR COALESCE(market_unit, '') != ''
                            OR COALESCE(payload_json, '') LIKE '%contract_profile%'
                          )
                        ORDER BY COALESCE(created_at, '') DESC, id DESC
                        LIMIT 1
                        """,
                        (slug, event_date_key),
                    ).fetchone()
                if rule_row:
                    for field_name in rule_fields:
                        _fill_value(field_name, rule_row[field_name])
                    payload = str(rule_row["payload_json"] or "").strip()
                    if payload:
                        try:
                            parsed_payload = json.loads(payload)
                        except Exception:
                            parsed_payload = None
                        if isinstance(parsed_payload, Mapping):
                            _apply_profile(parsed_payload.get("contract_profile"), "event_runs.payload")
                            payload_rules_ok = _coerce_optional_bool(parsed_payload.get("rules_contract_ok"))
                            if payload_rules_ok is True:
                                rules_ok = True
                                missing_reasons = []
                            elif payload_rules_ok is False and rules_ok is None:
                                rules_ok = False
                            payload_missing = _normalize_missing(parsed_payload.get("rules_missing_reasons"))
                            if payload_missing and not missing_reasons and rules_ok is not True:
                                missing_reasons = payload_missing
                    if not source:
                        source = "event_runs"
            except Exception as exc:
                try:
                    event_stage_meta["rules_hydration_event_runs_error"] = str(exc)[:160]
                except Exception:
                    pass

        _derive_rules_state_from_values()
        market_var_for_profile = str(values.get("market_var") or result.get("market_var") or "").strip()
        if (
            _env_bool("PM_AUTO_TRADE_RULES_LIVE_HYDRATE", True)
            and (
                rules_ok is not True
                or _is_empty(values.get("resolution_source"))
                or (is_temperature_market_var(market_var_for_profile) and _is_empty(values.get("station_id")))
            )
        ):
            try:
                hydrate_timeout = _env_float("PM_AUTO_TRADE_RULES_LIVE_HYDRATE_TIMEOUT", 4.0) or 4.0
                event_live = fetch_gamma_event_by_slug(
                    slug,
                    timeout=max(1.0, min(8.0, float(hydrate_timeout))),
                    retries=1,
                )
                if isinstance(event_live, Mapping):
                    outcome_labels = [
                        str(row_ref.get("outcome") or "").strip()
                        for row_ref in rows_ref
                        if isinstance(row_ref, dict) and str(row_ref.get("outcome") or "").strip()
                    ]
                    live_title = str(event_live.get("title") or title or slug)
                    live_description = str(event_live.get("description") or "")
                    live_market_var = market_var_for_profile or infer_market_variable(live_title, slug)
                    live_market_unit = str(values.get("market_unit") or result.get("market_unit") or "").strip()
                    if not live_market_unit:
                        live_market_unit = infer_market_unit(outcome_labels, live_market_var)
                    live_profile = build_weather_contract_profile(
                        title=live_title,
                        slug=slug,
                        description=live_description,
                        resolution_source=event_live.get("resolutionSource") or event_live.get("resolution_source"),
                        outcome_labels=outcome_labels,
                        event_date=event_date_key,
                        market_var=live_market_var,
                        market_unit=live_market_unit,
                    )
                    _apply_profile(live_profile, "gamma_event_detail")
            except Exception as exc:
                try:
                    event_stage_meta["rules_hydration_live_error"] = str(exc)[:160]
                except Exception:
                    pass

        _derive_rules_state_from_values()
        source_profile_final = weather_resolution_source_profile(
            str(values.get("resolution_source") or result.get("resolution_source") or "").strip(),
            station_id=str(values.get("station_id") or result.get("station_id") or "").strip() or None,
            description=str(result.get("description") or ""),
        )

        for row_ref in rows_ref:
            if not isinstance(row_ref, dict):
                continue
            for field_name, field_value in values.items():
                if _is_empty(row_ref.get(field_name)):
                    row_ref[field_name] = field_value
            for field_name in source_profile_fields:
                field_value = source_profile_final.get(field_name)
                if _is_empty(row_ref.get(field_name)) and not _is_empty(field_value):
                    row_ref[field_name] = field_value
            if rules_ok is not None and _coerce_optional_bool(row_ref.get("rules_contract_ok")) is None:
                row_ref["rules_contract_ok"] = bool(rules_ok)
            if not row_ref.get("rules_missing_reasons"):
                row_ref["rules_missing_reasons"] = list(missing_reasons)

        _merge_result_rule_values()
        needs_after = sum(
            1 for row_ref in rows_ref if isinstance(row_ref, dict) and _row_needs_rules(row_ref)
        )
        recovered = max(0, needs_before - needs_after)
        if recovered > 0:
            if not direct_target_job:
                _persist_event_run_rules_merge_fill()
            print(
                "[auto-trade] rules hydration "
                f"slug={slug} event_date={event_date_key} recovered={recovered} "
                f"missing_after={needs_after} source={source or 'derived'}"
            )

    skip_direct_token_hydration = bool(
        direct_target_job
        and _env_bool("PM_TARGET_REALIZATION_DIRECT_SKIP_TOKEN_HYDRATION", True)
    )
    token_hydration_started = _event_stage_start()
    if not skip_direct_token_hydration:
        _hydrate_row_tokens_from_market_cache(rows)
    _event_stage_end("row_token_hydration", token_hydration_started)
    skip_direct_rules_hydration = bool(
        direct_target_job
        and _env_bool("PM_TARGET_REALIZATION_DIRECT_SKIP_RULES_HYDRATION", True)
    )
    rules_hydration_started = _event_stage_start()
    if not skip_direct_rules_hydration:
        _hydrate_row_rules_from_context(rows)
    _event_stage_end("rules_hydration", rules_hydration_started)
    slug_lc = slug.strip().lower()
    title_lc = title.strip().lower()
    is_highest_temperature_event = (
        slug_lc.startswith("highest-temperature-in-")
        or "highest temperature in" in title_lc
    )
    follow_event_close_utc: Optional[datetime] = None
    follow_hours_to_settlement: Optional[float] = None
    follow_near_settlement = False
    entry_time_tiers = _parse_entry_time_thresholds(
        os.environ.get("PM_AUTO_TRADE_ENTRY_TIME_THRESHOLDS", "")
    )
    entry_edge_score_min_runtime, entry_signal_edge_min_runtime, entry_time_tier = (
        _resolve_entry_time_thresholds(
            days_to_event,
            float(AUTO_TRADE_MIN_EDGE_SCORE),
            float(MINUTE_EDGE_ENTRY_EDGE_MIN),
            entry_time_tiers,
        )
    )
    trade_token_map: Dict[str, Dict[str, str]] = {}
    trade_mark_map: Dict[Tuple[str, str, str, str], Optional[float]] = {}
    row_processing_started = _event_stage_start()
    for row in rows:
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        yes_token = str(row.get("yes_token") or "")
        no_token = str(row.get("no_token") or "")
        if yes_token:
            trade_token_map[yes_token] = {
                "slug": slug,
                "event_date": event_date_key,
                "outcome": outcome,
                "side": "YES",
            }
            yes_mark = to_float(row.get("best_bid")) or to_float(row.get("best_ask"))
            if yes_mark is not None:
                trade_mark_map[(slug, event_date_key, outcome, "YES")] = yes_mark
        if no_token:
            trade_token_map[no_token] = {
                "slug": slug,
                "event_date": event_date_key,
                "outcome": outcome,
                "side": "NO",
            }
            no_mark = to_float(row.get("best_bid_no")) or to_float(row.get("best_ask_no"))
            if no_mark is not None:
                trade_mark_map[(slug, event_date_key, outcome, "NO")] = no_mark
    trade_sync_started = _event_stage_start()
    if trade_token_map:
        global _AUTO_TRADE_LAST_SYNC_RUN_DATE, _AUTO_TRADE_LAST_SYNC_AT, _AUTO_TRADE_LAST_SYNC_KEY
        global _AUTO_TRADE_SYNC_TOKEN_MAP, _AUTO_TRADE_SYNC_MARK_MAP
        if run_date != _AUTO_TRADE_LAST_SYNC_RUN_DATE:
            _AUTO_TRADE_LAST_SYNC_RUN_DATE = run_date
            _AUTO_TRADE_LAST_SYNC_AT = 0.0
            _AUTO_TRADE_LAST_SYNC_KEY = ()
            _AUTO_TRADE_SYNC_TOKEN_MAP = {}
            _AUTO_TRADE_SYNC_MARK_MAP = {}
        _AUTO_TRADE_SYNC_TOKEN_MAP.update(trade_token_map)
        _AUTO_TRADE_SYNC_MARK_MAP.update(trade_mark_map)
        allow_trade_sync = AUTO_TRADE_SYNC_TRADES and not exit_only
        if positions_priority_fast_loop and not positions_priority_allow_slow:
            allow_trade_sync = False
        event_stage_meta["trade_sync_token_count"] = len(_AUTO_TRADE_SYNC_TOKEN_MAP)
        event_stage_meta["trade_sync_allowed"] = bool(allow_trade_sync)
        if allow_trade_sync:
            now_ts = time.time()
            cooldown = AUTO_TRADE_SYNC_COOLDOWN_SEC
            should_sync = cooldown <= 0 or (now_ts - _AUTO_TRADE_LAST_SYNC_AT) >= cooldown
            event_stage_meta["trade_sync_due"] = bool(should_sync)
            if should_sync:
                _mark_slow_request_used()
                if sync_trade_fills(_AUTO_TRADE_SYNC_TOKEN_MAP, _AUTO_TRADE_SYNC_MARK_MAP):
                    _AUTO_TRADE_LAST_SYNC_AT = now_ts
                    _AUTO_TRADE_LAST_SYNC_KEY = tuple(sorted(_AUTO_TRADE_SYNC_TOKEN_MAP.keys()))
    _event_stage_end("trade_sync", trade_sync_started)
    init_db()
    conn = open_db(autocommit=True)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    state_load_started = _event_stage_start()
    prev_states = _load_trade_state(slug, event_date_key)
    manual_ignores = _load_auto_trade_manual_ignores(slug, event_date_key, conn)
    entry_strategy_by_key: Dict[Tuple[str, str], str] = {}
    entry_q_ref_by_key: Dict[Tuple[str, str], float] = {}
    try:
        cur.execute(
            """
            SELECT order_id, outcome, side, strategy, q_calibrated, q_raw
            FROM auto_orders
            WHERE slug = ? AND event_date = ?
              AND action IN ('entry', 'entry_topup')
            ORDER BY created_at DESC, id DESC
            """,
            (slug, event_date_key),
        )
        for strategy_row in cur.fetchall():
            order_id_now = str(strategy_row[0] or "").strip()
            strategy_outcome = str(strategy_row[1] or "").strip()
            strategy_side = str(strategy_row[2] or "").strip().upper()
            if not strategy_outcome or strategy_side not in {"YES", "NO"}:
                continue
            key = (strategy_outcome, strategy_side)
            if key in entry_strategy_by_key:
                continue
            strategy_name = str(strategy_row[3] or "").strip().lower()
            if strategy_name:
                entry_strategy_by_key[key] = strategy_name
            q_ref = to_float(strategy_row[4])
            if q_ref is None or not math.isfinite(q_ref):
                q_ref = to_float(strategy_row[5])
            if (
                q_ref is not None
                and math.isfinite(q_ref)
                and 0.0 - TIME_EDGE_Q_EPS <= q_ref <= 1.0 + TIME_EDGE_Q_EPS
            ):
                entry_q_ref_by_key[key] = max(0.0, min(1.0, q_ref))
    except sqlite3.OperationalError:
        entry_strategy_by_key = {}
        entry_q_ref_by_key = {}
    _event_stage_end("state_load", state_load_started)
    # Buffer per-(outcome, side, action) so each run writes only the latest decision,
    # and the UI can explain "why no order" without recomputing gating.
    decision_buffer: Dict[Tuple[str, str, str], Dict[str, Any]] = {}
    persisted_decision_fingerprints: Set[str] = set()
    decision_context_by_key: Dict[Tuple[str, str, str], Dict[str, Any]] = {}

    def _detail_put_float(out: Dict[str, Any], key: str, val: Any) -> None:
        v = to_float(val)
        if v is None or not math.isfinite(v):
            return
        out[key] = float(v)

    def _detail_put_str(out: Dict[str, Any], key: str, val: Any) -> None:
        s = str(val or "").strip()
        if not s:
            return
        out[key] = s

    def _detail_put_bool(out: Dict[str, Any], key: str, val: Any) -> None:
        if val is None:
            return
        out[key] = bool(val)

    def _detail_put_mapping(out: Dict[str, Any], key: str, val: Any) -> None:
        if not isinstance(val, Mapping) or not val:
            return
        out[key] = {str(item_key): item_value for item_key, item_value in val.items()}

    def _physical_likelihood_audit_fields(meta: Mapping[str, Any]) -> Dict[str, Any]:
        row = meta.get("physical_likelihood_row") if isinstance(meta, Mapping) else None
        if not isinstance(row, Mapping):
            row = meta.get("physical_likelihood_observed_row") if isinstance(meta, Mapping) else None
        if not isinstance(row, Mapping):
            return {}
        out: Dict[str, Any] = {}
        if row.get("hard_zero") is not None:
            out["q_bayes_physical_likelihood_hard_zero"] = bool(row.get("hard_zero"))
        hard_reasons = row.get("hard_reasons")
        if isinstance(hard_reasons, list):
            reasons = [str(reason) for reason in hard_reasons if str(reason).strip()]
            if reasons:
                out["q_bayes_physical_likelihood_hard_reasons"] = reasons
        components = row.get("components")
        if isinstance(components, Mapping) and components:
            out["q_bayes_physical_likelihood_components"] = {
                str(key): value for key, value in components.items()
            }
        component_groups = row.get("component_groups")
        if isinstance(component_groups, Mapping) and component_groups:
            state_trace = _state_evidence_trace_from_component_groups(
                component_groups,
                source="metar_strong_likelihood.component_groups",
            )
            if state_trace:
                out["state_evidence_trace"] = state_trace
            out["q_bayes_physical_likelihood_component_groups"] = {
                str(key): value for key, value in component_groups.items()
            }
        return out

    def _first_detail_str(mapping: Mapping[str, Any], *keys: str) -> str:
        for key in keys:
            val = mapping.get(key)
            text = str(val or "").strip()
            if text:
                return text
        return ""

    def _normalize_decision_source_fit_fields(details: Dict[str, Any]) -> None:
        source_fit_tier = _first_detail_str(
            details,
            "source_fit_tier",
            "weather_strategy_source_fit_tier",
            "observed_nowcast_source_fit_tier",
            "source_trust_tier",
            "weather_strategy_source_trust_tier",
            "observed_nowcast_source_trust_tier",
        )
        if source_fit_tier:
            details["source_fit_tier"] = source_fit_tier
            details.setdefault("source_trust_tier", source_fit_tier)
            return
        source_fit_na_reason = _first_detail_str(
            details,
            "source_fit_na_reason",
            "source_na_reason",
            "weather_strategy_source_na_reason",
            "observed_nowcast_source_na_reason",
        )
        if not source_fit_na_reason and _first_detail_str(
            details,
            "strategy",
            "weather_strategy_family",
            "resolution_source",
            "station_id",
            "market_var",
        ):
            source_fit_na_reason = "source_fit_unavailable"
        if source_fit_na_reason:
            details["source_fit_na_reason"] = source_fit_na_reason

    def _detail_put_weather_strategy(out: Dict[str, Any], candidate: Mapping[str, Any]) -> None:
        for key in WEATHER_STRATEGY_FIELD_NAMES:
            val = candidate.get(key)
            if isinstance(val, bool):
                _detail_put_bool(out, key, val)
            elif to_float(val) is not None:
                _detail_put_float(out, key, val)
            else:
                _detail_put_str(out, key, val)

