    def _buffer_same_outcome_active_entry(
        outcome_label: str,
        side_label: str,
        block_meta: Mapping[str, Any],
        *,
        details: Optional[Dict[str, Any]] = None,
    ) -> None:
        merged_details = dict(details or {})
        merged_details["same_outcome_order_limit"] = dict(block_meta)
        _buffer_decision(
            outcome_label,
            side_label,
            "entry",
            decided_state="blocked",
            will_order=False,
            reason_codes=["same_outcome_open_order"],
            reasons=["同温度桶已有一笔活跃订单/仓位，本轮不再开新单"],
            details=merged_details,
        )

    def _target_switch_entry_priority_should_defer_exit(
        outcome_label: str,
        side_label: str,
        row_ref: Mapping[str, Any],
        exit_codes: Sequence[Any],
    ) -> bool:
        outcome_key = str(outcome_label or "").strip()
        side_key = str(side_label or "").strip().upper()
        submitted_primary_keys = (
            target_switch_order_submitted_entry_keys.intersection(target_switch_primary_entry_keys)
            if target_switch_primary_entry_keys
            else set(target_switch_order_submitted_entry_keys)
        )
        if submitted_primary_keys:
            return False
        if target_switch_order_submitted_entry_keys and not direct_target_job:
            return False
        if (
            direct_target_job
            and target_switch_primary_entry_keys
            and not exit_only
            and not _direct_target_payload_requests_exit_cleanup(result)
            and not _env_bool("PM_TARGET_REALIZATION_DIRECT_JOB_OLD_EXIT_BEFORE_ENTRY", False)
            and outcome_key
            and side_key in {"YES", "NO"}
            and (outcome_key, side_key) not in target_switch_primary_entry_keys
        ):
            if isinstance(row_ref, dict):
                row_ref["target_switch_entry_priority_override"] = "direct_target_primary_entry_first"
            return True
        return _should_defer_target_switch_exit_for_entry_priority(
            exit_only=exit_only,
            target_switch_expected_entry_keys=target_switch_expected_entry_keys,
            outcome_label=outcome_key,
            side_label=side_key,
            row_ref=row_ref,
            exit_codes=exit_codes,
        )

    def _defer_target_switch_exit_for_entry_priority(
        outcome_label: str,
        side_label: str,
        row_ref: Mapping[str, Any],
        prev_entry_ref: Mapping[str, Any],
        prev_state_ref: str,
        *,
        position_size_estimate: Optional[float],
        avg_cost_estimate: Optional[float],
        exit_price_estimate: Optional[float],
        exit_order_type_text: str,
        exit_reasons_ref: Sequence[Any],
        exit_reason_codes_ref: Sequence[Any],
        exit_reasons_text_ref: str,
        exit_reason_codes_text_ref: str,
        exit_triggered_at_update_ref: Optional[str],
        prev_exit_retry_count_ref: int,
    ) -> None:
        now_iso = utc_now_iso()
        position_size_val = to_float(position_size_estimate)
        if position_size_val is None or not math.isfinite(position_size_val):
            position_size_val = to_float(prev_entry_ref.get("position_size"))
        if position_size_val is None or not math.isfinite(position_size_val):
            position_size_val = 0.0
        defer_detail = {
            "strategy": str(prev_entry_ref.get("strategy") or "exit"),
            "position_size": float(position_size_val),
            "avg_price": avg_cost_estimate,
            "exit_price": exit_price_estimate,
            "exit_order_type": exit_order_type_text,
            "exit_reason_codes": list(exit_reason_codes_ref or []),
            "exit_reasons": list(exit_reasons_ref or []),
            "target_switch_entry_priority": True,
            "target_switch_expected_entry_keys": [
                {"outcome": key_outcome, "side": key_side}
                for key_outcome, key_side in sorted(target_switch_expected_entry_keys)
            ],
            "target_switch_primary_entry_keys": [
                {"outcome": key_outcome, "side": key_side}
                for key_outcome, key_side in sorted(target_switch_primary_entry_keys)
            ],
            "target_adjustment_action": row_ref.get("target_adjustment_action")
            or row_ref.get("action"),
            "target_bucket": row_ref.get("target_bucket"),
            "held_target_bucket": row_ref.get("held_target_bucket"),
            "current_top_bucket": row_ref.get("current_top_bucket"),
        }
        _buffer_decision(
            outcome_label,
            side_label,
            "exit",
            decided_state=prev_state_ref or "entry",
            will_order=False,
            reason_codes=["target_realization_exit_deferred_entry_priority"],
            reasons=["换桶入场优先：旧目标桶退出交给退出轮次处理"],
            details=defer_detail,
        )
        _update_trade_state(
            outcome_label,
            side_label,
            prev_state_ref or "entry",
            None,
            None,
            last_action="exit_skip",
            last_action_price=exit_price_estimate,
            last_action_size=float(position_size_val),
            last_action_order_type=exit_order_type_text,
            last_action_at=now_iso,
            last_status="target_switch_entry_priority",
            last_error="",
            exit_reasons=exit_reasons_text_ref,
            exit_reason_codes=exit_reason_codes_text_ref,
            exit_triggered_at=exit_triggered_at_update_ref,
            exit_skip_reason="target_switch_entry_priority",
            exit_skip_detail="entry_job_deferred_old_bucket_exit_until_target_entry_decision",
            exit_skip_at=now_iso,
            exit_retry_count=prev_exit_retry_count_ref,
            position_size=float(position_size_val),
            avg_price=avg_cost_estimate,
        )

