    def _parse_entry_edge_realizable_strategy_overrides(raw_text: str) -> Dict[str, Dict[str, Any]]:
        text = str(raw_text or "").strip()
        if not text:
            return {}
        try:
            payload = json.loads(text)
        except Exception:
            return {}
        if not isinstance(payload, dict):
            return {}

        def _clamp_nonneg(value: Any) -> Optional[float]:
            num = to_float(value)
            if num is None or not math.isfinite(num):
                return None
            return max(0.0, float(num))

        def _clamp_prob(value: Any) -> Optional[float]:
            num = _clamp_nonneg(value)
            if num is None:
                return None
            return min(1.0, float(num))

        def _boolish(value: Any) -> Optional[bool]:
            if isinstance(value, bool):
                return bool(value)
            if value is None:
                return None
            text_val = str(value).strip().lower()
            if text_val in {"1", "true", "yes", "on"}:
                return True
            if text_val in {"0", "false", "no", "off"}:
                return False
            return None

        out: Dict[str, Dict[str, Any]] = {}
        for raw_key, raw_entry in payload.items():
            key = str(raw_key or "").strip().lower()
            if not key:
                continue
            entry_obj = raw_entry if isinstance(raw_entry, dict) else {"p_realize_min": raw_entry}
            override: Dict[str, Any] = {}
            edge_min = _clamp_nonneg(
                entry_obj.get("edge_realizable_min", entry_obj.get("entry_edge_realizable_min"))
            )
            if edge_min is not None:
                override["edge_realizable_min"] = edge_min
            edge_v2_min = _clamp_nonneg(
                entry_obj.get(
                    "edge_realizable_v2_min",
                    entry_obj.get("entry_edge_realizable_v2_min"),
                )
            )
            if edge_v2_min is not None:
                override["edge_realizable_v2_min"] = edge_v2_min
            p_realize_min = _clamp_prob(
                entry_obj.get(
                    "p_realize_min",
                    entry_obj.get(
                        "edge_realizable_p_realize_min",
                        entry_obj.get("entry_edge_realizable_p_realize_min"),
                    ),
                )
            )
            if p_realize_min is not None:
                override["p_realize_min"] = p_realize_min
            p_converge_min = _clamp_prob(
                entry_obj.get(
                    "p_converge_min",
                    entry_obj.get(
                        "edge_realizable_p_converge_min",
                        entry_obj.get("entry_edge_realizable_p_converge_min"),
                    ),
                )
            )
            if p_converge_min is not None:
                override["p_converge_min"] = p_converge_min
            hq_signal_lcb_min = _clamp_nonneg(
                entry_obj.get(
                    "high_quality_signal_lcb_min",
                    entry_obj.get("edge_signal_lcb_min"),
                )
            )
            if hq_signal_lcb_min is not None:
                override["high_quality_signal_lcb_min"] = hq_signal_lcb_min
            hq_path_lcb_min = _clamp_prob(
                entry_obj.get(
                    "high_quality_path_lcb_min",
                    entry_obj.get("edge_path_p_reach_lcb_min"),
                )
            )
            if hq_path_lcb_min is not None:
                override["high_quality_path_lcb_min"] = hq_path_lcb_min
            hq_edge_lcb_min = _clamp_nonneg(
                entry_obj.get(
                    "high_quality_edge_lcb_min",
                    entry_obj.get(
                        "edge_tradeability_profit_min",
                        entry_obj.get("edge_tradeability_edge_lcb_min"),
                    ),
                )
            )
            if hq_edge_lcb_min is not None:
                override["high_quality_edge_lcb_min"] = hq_edge_lcb_min
            hq_bypass_p_realize = _boolish(
                entry_obj.get(
                    "high_quality_bypass_p_realize_min",
                    entry_obj.get("high_quality_allow_p_realize_bypass"),
                )
            )
            if hq_bypass_p_realize is not None:
                override["high_quality_bypass_p_realize_min"] = bool(hq_bypass_p_realize)
            hq_bypass_p_converge = _boolish(
                entry_obj.get(
                    "high_quality_bypass_p_converge_min",
                    entry_obj.get("high_quality_allow_p_converge_bypass"),
                )
            )
            if hq_bypass_p_converge is not None:
                override["high_quality_bypass_p_converge_min"] = bool(hq_bypass_p_converge)
            if override:
                out[key] = override
        return out

    entry_edge_realizable_strategy_overrides = _parse_entry_edge_realizable_strategy_overrides(
        os.environ.get("PM_AUTO_TRADE_ENTRY_EDGE_REALIZABLE_STRATEGY_OVERRIDES", "")
    )

    def _edge_realizable_gates_for_strategy(strategy_name: str) -> Dict[str, Any]:
        key = str(strategy_name or "").strip().lower() or "main"
        strategy_override = (
            entry_edge_realizable_strategy_overrides.get(key)
            or entry_edge_realizable_strategy_overrides.get("*")
            or {}
        )
        edge_min = to_float(strategy_override.get("edge_realizable_min"))
        if edge_min is None or not math.isfinite(edge_min) or edge_min < 0:
            edge_min = float(entry_edge_realizable_min)

        edge_v2_min = to_float(strategy_override.get("edge_realizable_v2_min"))
        if edge_v2_min is None or not math.isfinite(edge_v2_min) or edge_v2_min < 0:
            edge_v2_min = (
                float(entry_edge_realizable_min_v2)
                if entry_edge_realizable_min_v2 is not None and math.isfinite(entry_edge_realizable_min_v2)
                else None
            )

        p_realize_min = to_float(strategy_override.get("p_realize_min"))
        if p_realize_min is None or not math.isfinite(p_realize_min):
            p_realize_min = float(entry_edge_realizable_p_realize_min)
        p_realize_min = max(0.0, min(1.0, float(p_realize_min)))

        p_converge_min = to_float(strategy_override.get("p_converge_min"))
        if p_converge_min is None or not math.isfinite(p_converge_min):
            p_converge_min = float(entry_edge_realizable_p_converge_min)
        p_converge_min = max(0.0, min(1.0, float(p_converge_min)))

        hq_signal_lcb_min = to_float(strategy_override.get("high_quality_signal_lcb_min"))
        if hq_signal_lcb_min is not None and (not math.isfinite(hq_signal_lcb_min) or hq_signal_lcb_min < 0):
            hq_signal_lcb_min = None
        hq_path_lcb_min = to_float(strategy_override.get("high_quality_path_lcb_min"))
        if hq_path_lcb_min is not None and (not math.isfinite(hq_path_lcb_min) or hq_path_lcb_min < 0):
            hq_path_lcb_min = None
        if hq_path_lcb_min is not None:
            hq_path_lcb_min = min(1.0, float(hq_path_lcb_min))
        hq_edge_lcb_min = to_float(strategy_override.get("high_quality_edge_lcb_min"))
        if hq_edge_lcb_min is not None and (not math.isfinite(hq_edge_lcb_min) or hq_edge_lcb_min < 0):
            hq_edge_lcb_min = None

        hq_bypass_p_realize = bool(strategy_override.get("high_quality_bypass_p_realize_min"))
        hq_bypass_p_converge = bool(strategy_override.get("high_quality_bypass_p_converge_min"))

        return {
            "strategy": key,
            "override_applied": bool(strategy_override),
            "override_keys": ",".join(sorted(strategy_override.keys())) if strategy_override else "",
            "edge_realizable_min": float(edge_min),
            "edge_realizable_v2_min": (
                float(edge_v2_min) if edge_v2_min is not None and math.isfinite(edge_v2_min) else None
            ),
            "p_realize_min": float(p_realize_min),
            "p_converge_min": float(p_converge_min),
            "high_quality_signal_lcb_min": (
                float(hq_signal_lcb_min) if hq_signal_lcb_min is not None and math.isfinite(hq_signal_lcb_min) else None
            ),
            "high_quality_path_lcb_min": (
                float(hq_path_lcb_min) if hq_path_lcb_min is not None and math.isfinite(hq_path_lcb_min) else None
            ),
            "high_quality_edge_lcb_min": (
                float(hq_edge_lcb_min) if hq_edge_lcb_min is not None and math.isfinite(hq_edge_lcb_min) else None
            ),
            "high_quality_bypass_p_realize_min": bool(hq_bypass_p_realize),
            "high_quality_bypass_p_converge_min": bool(hq_bypass_p_converge),
        }

    strategy_realized_edge_gate_enabled = _env_bool(
        "PM_AUTO_TRADE_STRATEGY_REALIZED_EDGE_GATE_ENABLED",
        False,
    )
    strategy_realized_edge_min = _env_float("PM_AUTO_TRADE_STRATEGY_REALIZED_EDGE_MIN")
    if strategy_realized_edge_min is None or not math.isfinite(strategy_realized_edge_min):
        strategy_realized_edge_min = 0.0
    strategy_realized_edge_min_samples = _env_int(
        "PM_AUTO_TRADE_STRATEGY_REALIZED_EDGE_MIN_SAMPLES"
    )
    if strategy_realized_edge_min_samples is None or strategy_realized_edge_min_samples < 1:
        strategy_realized_edge_min_samples = 20
    strategy_realized_edge_block_missing = _env_bool(
        "PM_AUTO_TRADE_STRATEGY_REALIZED_EDGE_BLOCK_MISSING",
        False,
    )
    strategy_gate_report_path = _resolve_edge_strategy_gate_report_path()
    strategy_gate_report = _load_edge_strategy_gate_report(strategy_gate_report_path)
    strategy_gate_generated_at = (
        str(strategy_gate_report.get("generated_at") or "").strip() or None
    )
    strategy_gate_stats = _edge_strategy_gate_map(strategy_gate_report)

    def _parse_strategy_realized_edge_strategy_overrides(
        raw_text: str,
    ) -> Dict[str, Dict[str, Any]]:
        text = str(raw_text or "").strip()
        if not text:
            return {}
        try:
            payload = json.loads(text)
        except Exception:
            return {}
        if not isinstance(payload, dict):
            return {}

        def _boolish(value: Any) -> Optional[bool]:
            if isinstance(value, bool):
                return bool(value)
            if value is None:
                return None
            text_val = str(value).strip().lower()
            if text_val in {"1", "true", "yes", "on"}:
                return True
            if text_val in {"0", "false", "no", "off"}:
                return False
            return None

        out: Dict[str, Dict[str, Any]] = {}
        for raw_key, raw_entry in payload.items():
            key = str(raw_key or "").strip().lower()
            if not key:
                continue
            entry_obj = raw_entry if isinstance(raw_entry, dict) else {"realized_edge_min": raw_entry}
            override: Dict[str, Any] = {}

            gate_enabled_val = _boolish(
                entry_obj.get(
                    "gate_enabled",
                    entry_obj.get("strategy_realized_edge_gate_enabled"),
                )
            )
            if gate_enabled_val is not None:
                override["gate_enabled"] = bool(gate_enabled_val)

            realized_edge_min_val = to_float(
                entry_obj.get(
                    "realized_edge_min",
                    entry_obj.get("strategy_realized_edge_min"),
                )
            )
            if realized_edge_min_val is not None and math.isfinite(realized_edge_min_val):
                override["realized_edge_min"] = float(realized_edge_min_val)

            min_samples_raw = entry_obj.get(
                "min_samples",
                entry_obj.get("strategy_realized_edge_min_samples"),
            )
            try:
                min_samples_val = (
                    int(float(min_samples_raw))
                    if min_samples_raw is not None
                    else None
                )
            except Exception:
                min_samples_val = None
            if min_samples_val is not None and min_samples_val >= 1:
                override["min_samples"] = int(min_samples_val)

            block_missing_val = _boolish(
                entry_obj.get(
                    "block_missing",
                    entry_obj.get("strategy_realized_edge_block_missing"),
                )
            )
            if block_missing_val is not None:
                override["block_missing"] = bool(block_missing_val)

            if override:
                out[key] = override
        return out

    strategy_realized_edge_strategy_overrides = _parse_strategy_realized_edge_strategy_overrides(
        os.environ.get("PM_AUTO_TRADE_STRATEGY_REALIZED_EDGE_STRATEGY_OVERRIDES", "")
    )

    def _strategy_realized_edge_gates_for_strategy(strategy_name: str) -> Dict[str, Any]:
        key = str(strategy_name or "").strip().lower() or "main"
        strategy_override = (
            strategy_realized_edge_strategy_overrides.get(key)
            or strategy_realized_edge_strategy_overrides.get("*")
            or {}
        )
        gate_enabled = bool(strategy_realized_edge_gate_enabled)
        if key == "lcb_global" and "gate_enabled" not in strategy_override:
            gate_enabled = False
        if "gate_enabled" in strategy_override:
            gate_enabled = bool(strategy_override.get("gate_enabled"))

        realized_edge_min_val = to_float(strategy_override.get("realized_edge_min"))
        if realized_edge_min_val is None or not math.isfinite(realized_edge_min_val):
            realized_edge_min_val = float(strategy_realized_edge_min)

        min_samples_val = strategy_override.get("min_samples")
        try:
            min_samples_i = int(min_samples_val) if min_samples_val is not None else None
        except Exception:
            min_samples_i = None
        if min_samples_i is None or min_samples_i < 1:
            min_samples_i = int(strategy_realized_edge_min_samples)

        block_missing = bool(strategy_realized_edge_block_missing)
        if key == "lcb_global" and "block_missing" not in strategy_override:
            block_missing = False
        if "block_missing" in strategy_override:
            block_missing = bool(strategy_override.get("block_missing"))

        return {
            "strategy": key,
            "override_applied": bool(strategy_override),
            "override_keys": ",".join(sorted(strategy_override.keys())) if strategy_override else "",
            "gate_enabled": bool(gate_enabled),
            "realized_edge_min": float(realized_edge_min_val),
            "min_samples": int(min_samples_i),
            "block_missing": bool(block_missing),
        }

    def _strategy_gate_entry_for(strategy_name: str) -> Optional[Dict[str, Any]]:
        key = str(strategy_name or "").strip().lower()
        if not key:
            key = "main"
        entry = strategy_gate_stats.get(key)
        if isinstance(entry, dict):
            return entry
        if key == "lcb_global":
            fallback = strategy_gate_stats.get("main")
            if isinstance(fallback, dict):
                return fallback
        if key in {"yes_top", "adj_pair", "hard_bound_no", "follow_copy"}:
            fallback = strategy_gate_stats.get("main")
            if isinstance(fallback, dict):
                return fallback
        return None

    def _edge_realizable_report_lookup(
        bucket_key: Optional[str],
    ) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:
        if not edge_realizable_report_enabled or not bucket_key or not edge_realizable_report_buckets:
            return None, None
        entry = edge_realizable_report_buckets.get(bucket_key)
        if entry is not None:
            return entry, bucket_key
        if "|ot:" in bucket_key and not bucket_key.endswith("ot:ANY"):
            bucket_any = bucket_key.rsplit("|ot:", 1)[0] + "|ot:ANY"
            entry = edge_realizable_report_buckets.get(bucket_any)
            if entry is not None:
                return entry, bucket_any
        return None, None

    def _edge_realizable_report_adjust(
        edge_val: Optional[float],
        bucket_key: Optional[str],
    ) -> Tuple[Optional[float], Dict[str, Any]]:
        meta: Dict[str, Any] = {}
        if edge_val is None or not math.isfinite(edge_val):
            return edge_val, meta
        entry, used_key = _edge_realizable_report_lookup(bucket_key)
        if entry is None:
            return edge_val, meta
        count_val = to_float(entry.get("count"))
        try:
            count_i = int(count_val) if count_val is not None and math.isfinite(count_val) else None
        except Exception:
            count_i = None
        avg_real_edge = to_float(entry.get("avg_real_edge"))
        avg_pred_edge = to_float(entry.get("avg_pred_edge"))
        bias_val = to_float(entry.get("bias"))
        win_rate_val = to_float(entry.get("win_rate"))
        meta.update(
            {
                "edge_realizable_report_bucket": used_key,
                "edge_realizable_report_count": count_i,
                "edge_realizable_report_avg_real_edge": avg_real_edge,
                "edge_realizable_report_avg_pred_edge": avg_pred_edge,
                "edge_realizable_report_bias": bias_val,
                "edge_realizable_report_win_rate": win_rate_val,
                "edge_realizable_report_min_count": edge_realizable_report_min_count,
                "edge_realizable_report_min_real_edge": edge_realizable_report_min_real_edge,
            }
        )
        if edge_realizable_report_min_bias is not None:
            meta["edge_realizable_report_min_bias"] = edge_realizable_report_min_bias
        if count_i is None or edge_realizable_report_min_count <= 0 or count_i < edge_realizable_report_min_count:
            meta["edge_realizable_report_low_sample"] = True
            return edge_val, meta
        if (
            edge_realizable_report_apply_bias
            and bias_val is not None
            and math.isfinite(bias_val)
        ):
            bias_adj = float(bias_val)
            if edge_realizable_report_bias_clamp is not None and math.isfinite(edge_realizable_report_bias_clamp):
                bias_adj = max(
                    -float(edge_realizable_report_bias_clamp),
                    min(float(edge_realizable_report_bias_clamp), bias_adj),
                )
            edge_val = float(edge_val) + bias_adj
            meta["edge_realizable_report_bias_adj"] = bias_adj
        blocked = False
        if (
            edge_realizable_report_block_negative
            and avg_real_edge is not None
            and math.isfinite(avg_real_edge)
            and avg_real_edge < edge_realizable_report_min_real_edge - TIME_EDGE_Q_EPS
        ):
            blocked = True
        if (
            edge_realizable_report_min_bias is not None
            and bias_val is not None
            and math.isfinite(bias_val)
            and bias_val < edge_realizable_report_min_bias - TIME_EDGE_Q_EPS
        ):
            blocked = True
        if blocked:
            meta["edge_realizable_report_blocked"] = True
        return edge_val, meta

    def _edge_realizable_exec_audit_adjust(
        edge_val: Optional[float],
    ) -> Tuple[Optional[float], Dict[str, Any]]:
        meta: Dict[str, Any] = {}
        if edge_val is None or not math.isfinite(edge_val):
            return edge_val, meta
        if not edge_exec_audit_gate_enabled:
            return edge_val, meta
        failed_checks: List[str] = []
        sample_scale = 1.0
        pred_rows_below_min = False
        if edge_exec_audit_min_pred_rows > 0:
            if edge_exec_audit_pred_rows is None or edge_exec_audit_pred_rows <= 0:
                sample_scale = 0.0
            else:
                sample_scale = max(
                    0.0,
                    min(1.0, float(edge_exec_audit_pred_rows) / float(edge_exec_audit_min_pred_rows)),
                )
            pred_rows_below_min = bool(
                edge_exec_audit_pred_rows is None
                or edge_exec_audit_pred_rows < edge_exec_audit_min_pred_rows
            )
        if sample_scale < edge_exec_audit_scale_floor:
            sample_scale = float(edge_exec_audit_scale_floor)
        if edge_exec_audit_require_pass and edge_exec_audit_gate_pass is not True:
            soft_gate_fail = bool(
                edge_exec_audit_allow_soft_gate_fail
                and edge_exec_audit_failed_name_set
                and edge_exec_audit_failed_name_set.issubset(edge_exec_audit_soft_gate_fail_names)
            )
            if soft_gate_fail:
                meta["edge_realizable_exec_audit_soft_gate_fail"] = True
            else:
                failed_checks.append("audit_gate")
        if pred_rows_below_min:
            meta["edge_realizable_exec_audit_low_sample"] = True
            if edge_exec_audit_block_pred_rows_min:
                failed_checks.append("pred_rows_min")
        avg_real_edge_gate_ready = True
        if edge_exec_audit_avg_real_edge_min_samples > 0:
            avg_real_edge_gate_ready = bool(
                edge_exec_audit_pred_rows is not None
                and edge_exec_audit_pred_rows >= edge_exec_audit_avg_real_edge_min_samples
            )
        if (
            edge_exec_audit_min_avg_real_edge is not None
            and avg_real_edge_gate_ready
            and (
                edge_exec_audit_avg_real_edge is None
                or not math.isfinite(edge_exec_audit_avg_real_edge)
                or edge_exec_audit_avg_real_edge < edge_exec_audit_min_avg_real_edge - TIME_EDGE_Q_EPS
            )
        ):
            failed_checks.append("avg_real_edge_min")
        elif edge_exec_audit_min_avg_real_edge is not None and not avg_real_edge_gate_ready:
            meta["edge_realizable_exec_audit_avg_real_edge_warmup"] = True
        meta.update(
            {
                "edge_realizable_exec_audit_gate_pass": edge_exec_audit_gate_pass,
                "edge_realizable_exec_audit_pred_rows": edge_exec_audit_pred_rows,
                "edge_realizable_exec_audit_pred_rows_min": edge_exec_audit_min_pred_rows,
                "edge_realizable_exec_audit_avg_real_edge": edge_exec_audit_avg_real_edge,
                "edge_realizable_exec_audit_avg_real_edge_min": edge_exec_audit_min_avg_real_edge,
                "edge_realizable_exec_audit_avg_real_edge_min_samples": edge_exec_audit_avg_real_edge_min_samples,
                "edge_realizable_exec_audit_block_pred_rows_min": edge_exec_audit_block_pred_rows_min,
                "edge_realizable_exec_audit_scale": sample_scale,
                "edge_realizable_exec_audit_source_path": str(edge_exec_audit_path or ""),
                "edge_realizable_exec_audit_source_generated_at": edge_exec_audit_generated_at,
                "edge_realizable_exec_audit_gate_failed_names": ",".join(edge_exec_audit_failed_names),
            }
        )
        if failed_checks:
            meta["edge_realizable_exec_audit_blocked"] = True
            meta["edge_realizable_exec_audit_failed_checks"] = ",".join(failed_checks)
            return None, meta
        if edge_exec_audit_apply_sample_scale and sample_scale < 1.0 - TIME_EDGE_Q_EPS:
            edge_val = float(edge_val) * float(sample_scale)
        return edge_val, meta

    def _edge_tradeability_adjust(
        *,
        edge_val: Optional[float],
        candidate: Dict[str, Any],
        row_ref: Mapping[str, Any],
        outcome: str,
        side: str,
        spread_val: Optional[float],
        depth_ratio_val: Optional[float],
        days_to_event_val: Optional[float],
        bucket_key: Optional[str],
        edge_semantics: str = "auto",
    ) -> Tuple[Optional[float], Dict[str, Any]]:
        meta: Dict[str, Any] = {}
        if not edge_tradeability_enabled:
            return edge_val, meta
        edge_semantics_resolved = str(edge_semantics or "auto").strip().lower() or "auto"
        if edge_semantics_resolved == "auto":
            edge_semantics_resolved = "raw_exec"
        edge_input_val = edge_val
        if edge_input_val is None or not math.isfinite(edge_input_val):
            edge_input_val = to_float(candidate.get("edge_realizable_v2_raw"))
            if edge_input_val is not None and math.isfinite(edge_input_val):
                edge_semantics_resolved = "realized_v2"
        if edge_input_val is None or not math.isfinite(edge_input_val):
            edge_input_val = to_float(candidate.get("edge_realizable"))
            if edge_input_val is not None and math.isfinite(edge_input_val):
                edge_semantics_resolved = "raw_exec"
        if edge_input_val is None or not math.isfinite(edge_input_val):
            return edge_val, meta
        signal_meta = compute_signal_advantage(
            q_raw=to_float(candidate.get("q_raw")),
            q_calibrated=to_float(candidate.get("q_calibrated")),
            q_edge=to_float(candidate.get("q_edge")),
            trend_pct=to_float(candidate.get("trend_pct")),
            trend_consistency_up=to_float(candidate.get("trend_consistency_up")),
            model_spread=to_float(row_ref.get("q_round_model_spread")),
            signal_z=float(edge_tradeability_signal_z),
        )
        signal_alpha_val = to_float(signal_meta.get("signal_alpha"))
        signal_lcb_val = to_float(signal_meta.get("signal_lcb"))
        tail_blocked, tail_reason, tail_meta = _candidate_is_extreme_tail_ask_untradeable(
            candidate,
            side=side,
            row_ref=row_ref,
        )
        if tail_blocked:
            existing_reasons = str(meta.get("edge_tradeability_reasons") or "").strip()
            if existing_reasons:
                reason_parts = [x.strip() for x in existing_reasons.split(",") if x.strip()]
                if tail_reason and tail_reason not in reason_parts:
                    reason_parts.append(tail_reason)
                meta["edge_tradeability_reasons"] = ",".join(reason_parts)
            else:
                meta["edge_tradeability_reasons"] = tail_reason
            meta["edge_tradeability_pass"] = False
            meta["edge_tradeability_blocked"] = True
            meta["edge_tradeability_soft"] = False
            meta["edge_tradeability_untradeable_tail"] = True
            meta.update(tail_meta)
            return None, meta
        path_meta = estimate_path_probability(
            signal_alpha=signal_alpha_val,
            spread=spread_val,
            depth_ratio=depth_ratio_val,
            hours_to_settle=float(days_to_event_val) * 24.0
            if days_to_event_val is not None and math.isfinite(days_to_event_val)
            else None,
            calibration_bucket_key=bucket_key,
            signal_z=float(edge_tradeability_signal_z),
        )
        edge_floor_meta = estimate_tradeable_edge_floor(
            edge_raw=edge_input_val,
            p_reach=path_meta.get("p_reach"),
            p_reach_lcb=path_meta.get("p_reach_lcb"),
            p_reach_ucb=path_meta.get("p_reach_ucb"),
            spread=spread_val,
            fee_cost=to_float(candidate.get("exec_fee_cost")),
            hold_cost=to_float(candidate.get("edge_realizable_hold_cost")),
            slippage_buffer=edge_tradeability_slippage_buffer,
            edge_semantics=edge_semantics_resolved,
        )
        path_gate_enforced = bool(edge_floor_meta.get("path_gate_enforced", True))
        policy_key = "|".join(
            [
                str(slug or "").strip(),
                str(event_date_key or "").strip(),
                str(outcome or "").strip(),
                str(side or "").strip().upper(),
                str(candidate.get("strategy") or "").strip().lower() or "main",
            ]
        )
        policy_eval = dict(edge_tradeability_policy) if isinstance(edge_tradeability_policy, dict) else {}
        strategy_name_eval = str(candidate.get("strategy") or "").strip().lower() or "main"
        if _is_path_probability_follow_strategy(strategy_name_eval):
            signal_lcb_min_override = to_float(candidate.get("lcb_global_signal_lcb_min"))
            if signal_lcb_min_override is None:
                signal_lcb_min_override = to_float(lcb_global_signal_lcb_min)
            if signal_lcb_min_override is not None and math.isfinite(signal_lcb_min_override):
                policy_eval["signal_lcb_min"] = max(0.0, float(signal_lcb_min_override))
            path_lcb_min_override = to_float(candidate.get("lcb_global_path_lcb_min"))
            if path_lcb_min_override is None:
                path_lcb_min_override = to_float(lcb_global_path_lcb_min)
            if path_lcb_min_override is not None and math.isfinite(path_lcb_min_override):
                policy_eval["path_lcb_min"] = min(1.0, max(0.0, float(path_lcb_min_override)))
            edge_lcb_min_override = to_float(candidate.get("lcb_global_edge_lcb_min"))
            if edge_lcb_min_override is not None and math.isfinite(edge_lcb_min_override):
                policy_eval["edge_lcb_min"] = float(edge_lcb_min_override)
        if not policy_eval:
            policy_eval = edge_tradeability_policy
        policy_meta = evaluate_tradeability(
            policy=policy_eval,
            key=policy_key,
            signal_lcb=signal_lcb_val,
            path_lcb=path_meta.get("p_reach_lcb"),
            edge_lcb=edge_floor_meta.get("edge_lcb_tradeable"),
            v2_value=candidate.get("edge_realizable_v2"),
            exec_audit_gate_pass=(
                bool(candidate.get("edge_realizable_exec_audit_gate_pass"))
                if candidate.get("edge_realizable_exec_audit_gate_pass") is not None
                else None
            ),
            enforce_path_gate=path_gate_enforced,
        )
        meta.update(
            {
                "edge_tradeability_input_semantics": edge_semantics_resolved,
                "edge_signal_alpha": signal_meta.get("signal_alpha"),
                "edge_signal_lcb": signal_meta.get("signal_lcb"),
                "edge_signal_sigma": signal_meta.get("signal_sigma"),
                "edge_signal_confidence": signal_meta.get("signal_confidence"),
                "edge_tradeability_signal_z": float(edge_tradeability_signal_z),
                "edge_tradeability_signal_z_stage": edge_tradeability_signal_z_meta.get("stage"),
                "edge_tradeability_signal_z_source": edge_tradeability_signal_z_meta.get("source"),
                "edge_signal_components_q_edge": signal_meta.get("signal_components_q_edge"),
                "edge_signal_components_model_spread": signal_meta.get("signal_components_model_spread"),
                "edge_signal_components_consensus_adjustment": signal_meta.get("signal_components_consensus_adjustment"),
                "edge_path_p_reach": path_meta.get("p_reach"),
                "edge_path_p_reach_lcb": path_meta.get("p_reach_lcb"),
                "edge_path_p_reach_ucb": path_meta.get("p_reach_ucb"),
                "edge_path_sample_n": path_meta.get("path_sample_n"),
                "edge_path_bucket_key": path_meta.get("path_bucket_key"),
                "edge_path_bucket_key_used": path_meta.get("path_bucket_key_used"),
                "edge_path_fallback_rank": path_meta.get("path_fallback_rank"),
                "edge_path_source": path_meta.get("path_source"),
                "edge_path_calibration_path": path_meta.get("path_calibration_path"),
                "edge_path_calibration_generated_at": path_meta.get("path_calibration_generated_at"),
                "edge_tradeability_edge_expected": edge_floor_meta.get("edge_expected_tradeable"),
                "edge_tradeability_profit_value": edge_floor_meta.get("edge_lcb_tradeable"),
                "edge_tradeability_edge_ucb": edge_floor_meta.get("edge_ucb_tradeable"),
                "edge_tradeability_miss_cost": edge_floor_meta.get("edge_miss_cost"),
                "edge_tradeability_slippage_buffer": edge_floor_meta.get("edge_slippage_buffer"),
                "edge_tradeability_edge_floor_mode": edge_floor_meta.get("edge_floor_mode"),
                "edge_tradeability_mode": policy_meta.get("mode"),
                "edge_tradeability_policy_enforce": policy_meta.get("enforce"),
                "edge_tradeability_canary_sampled": policy_meta.get("canary_sampled"),
                "edge_tradeability_pass": policy_meta.get("pass"),
                "edge_tradeability_blocked": policy_meta.get("blocked"),
                "edge_tradeability_shadow_block": policy_meta.get("shadow_block"),
                "edge_tradeability_reasons": policy_meta.get("reasons_csv"),
                "edge_tradeability_signal_lcb_min": policy_meta.get("signal_lcb_min"),
                "edge_tradeability_path_lcb_min": policy_meta.get("path_lcb_min"),
                "edge_tradeability_profit_min": policy_meta.get("edge_lcb_min"),
                "edge_tradeability_path_gate_enforced": policy_meta.get("path_gate_enforced"),
            }
        )
        variance_gate = _bayes_variance_entry_gate(candidate)
        meta.update(variance_gate)
        if variance_gate.get("q_bayes_variance_gate_enabled") and not variance_gate.get(
            "q_bayes_variance_gate_pass"
        ):
            existing_reasons = str(meta.get("edge_tradeability_reasons") or "").strip()
            variance_reason = str(
                variance_gate.get("q_bayes_variance_skip_reason") or "q_bayes_variance_high"
            ).strip()
            if variance_reason:
                if existing_reasons:
                    reasons_now = [x.strip() for x in existing_reasons.split(",")]
                    if variance_reason not in reasons_now:
                        meta["edge_tradeability_reasons"] = (
                            f"{existing_reasons},{variance_reason}"
                        )
                else:
                    meta["edge_tradeability_reasons"] = variance_reason
            meta["edge_tradeability_pass"] = False
            meta["edge_tradeability_blocked"] = True
            return None, meta
        edge_lcb_val = to_float(edge_floor_meta.get("edge_lcb_tradeable"))
        # Keep v2 (expected edge) as the primary value for downstream v2 gates.
        # LCB is exposed via edge_tradeability_* fields and evaluated by policy/HQ gates.
        # Overwriting v2 with LCB here can unintentionally double-tighten entry gating.
        bayes_edge_val, bayes_meta = apply_bayes_tradeability_adjustment(
            edge_lcb=edge_lcb_val,
            db_path=str(DB_PATH),
            strategy=str(candidate.get("strategy") or "main"),
            outcome=outcome,
            side=side,
            slug=str(slug or ""),
            event_date=str(event_date_key or ""),
        )
        bayes_scale = to_float(bayes_meta.get("edge_tradeability_bayes_scale"))
        if bayes_scale is None or not math.isfinite(bayes_scale):
            bayes_scale = 1.0
        row_q = to_float(row_ref.get("q_entry") if side == "YES" else row_ref.get("q_entry_no"))
        bayes_q_source = ""
        bayes_q_raw = to_float(candidate.get("q_calibrated"))
        if bayes_q_raw is not None and math.isfinite(bayes_q_raw):
            bayes_q_source = "q_calibrated"
        else:
            bayes_q_raw = to_float(candidate.get("q_entry"))
            if bayes_q_raw is not None and math.isfinite(bayes_q_raw):
                bayes_q_source = "q_entry"
            else:
                bayes_q_raw = to_float(candidate.get("q_round"))
                if bayes_q_raw is not None and math.isfinite(bayes_q_raw):
                    bayes_q_source = "q_round"
                else:
                    bayes_q_raw = to_float(candidate.get("q_min_bound"))
                    if bayes_q_raw is not None and math.isfinite(bayes_q_raw):
                        bayes_q_source = "q_min_bound"
                    elif row_q is not None and math.isfinite(row_q):
                        bayes_q_raw = row_q
                        bayes_q_source = "q_entry_row"
        if (
            bayes_q_raw is not None
            and math.isfinite(bayes_q_raw)
            and 0.0 <= float(bayes_q_raw) <= 1.0
            and float(bayes_q_raw) * float(bayes_scale) <= 1.0
        ):
            bayes_q_val = float(bayes_q_raw) * float(bayes_scale)
            bayes_suffix = "_yes" if str(side or "").strip().upper() == "YES" else "_no"
            meta["edge_tradeability_bayes_q_source"] = str(bayes_q_source or "q_unknown")
            meta["edge_tradeability_bayes_q"] = bayes_q_val
            meta[f"edge_tradeability_bayes_q{bayes_suffix}"] = bayes_q_val
            meta["edge_tradeability_bayes_q_scale"] = float(bayes_scale)
            meta[f"edge_tradeability_bayes_q{bayes_suffix}_scale"] = float(bayes_scale)
            meta["edge_tradeability_bayes_q_evidence"] = int(
                bayes_meta.get("edge_tradeability_bayes_evidence", 0)
            )
            meta[f"edge_tradeability_bayes_q{bayes_suffix}_evidence"] = int(
                bayes_meta.get("edge_tradeability_bayes_evidence", 0)
            )
        if bayes_meta:
            meta.update(bayes_meta)
        if bayes_edge_val is not None and math.isfinite(bayes_edge_val):
            meta["edge_tradeability_profit_value_bayes"] = float(bayes_edge_val)
            meta["edge_tradeability_profit_value_bayes_scale"] = meta.get(
                "edge_tradeability_bayes_scale"
            )
        if bayes_meta.get("edge_tradeability_bayes_hard_block"):
            existing_reasons = str(meta.get("edge_tradeability_reasons") or "").strip()
            hard_block_reason = str(
                bayes_meta.get("edge_tradeability_bayes_hard_block_reason") or ""
            ).strip()
            if not hard_block_reason:
                hard_block_reason = "bayes_hard_block"
            if hard_block_reason:
                if existing_reasons:
                    if hard_block_reason not in [x.strip() for x in existing_reasons.split(",")]:
                        meta["edge_tradeability_reasons"] = (
                            f"{existing_reasons},{hard_block_reason}"
                        )
                else:
                    meta["edge_tradeability_reasons"] = hard_block_reason
            meta["edge_tradeability_pass"] = False
            meta["edge_tradeability_blocked"] = True
            return None, meta
        if bayes_edge_val is not None and math.isfinite(bayes_edge_val):
            edge_val = float(bayes_edge_val)
        if policy_meta.get("blocked"):
            return None, meta
        return edge_val, meta

