def _db_cache_key() -> str:
    try:
        return str(Path(DB_PATH).resolve())
    except Exception:
        return str(DB_PATH)


def _apply_db_connection_pragmas(
    conn: sqlite3.Connection,
    *,
    busy_timeout_ms: int,
    ensure_journal_mode: bool = False,
) -> None:
    cache_key = _db_cache_key()
    if ensure_journal_mode:
        with _DB_PRAGMA_INIT_LOCK:
            need_journal_mode = cache_key not in _DB_PRAGMA_READY_KEYS
            if need_journal_mode:
                try:
                    conn.execute(f"PRAGMA journal_mode={DB_JOURNAL_MODE}")
                    _DB_PRAGMA_READY_KEYS.add(cache_key)
                except sqlite3.Error:
                    pass
    try:
        conn.execute("PRAGMA synchronous=NORMAL")
        conn.execute(f"PRAGMA busy_timeout={int(max(0, busy_timeout_ms))}")
    except sqlite3.Error:
        pass


def _sqlite_sql_requires_write_gate(sql: Any) -> bool:
    text = str(sql or "").strip()
    if not text:
        return False
    while text.startswith("--"):
        _, _, rest = text.partition("\n")
        text = rest.strip()
    if not text:
        return False
    first = text.split(None, 1)[0].strip().upper()
    if first in {
        "INSERT",
        "UPDATE",
        "DELETE",
        "REPLACE",
        "CREATE",
        "ALTER",
        "DROP",
        "VACUUM",
        "REINDEX",
    }:
        return True
    if first == "PRAGMA":
        upper = text.upper()
        return "JOURNAL_MODE" in upper or "WAL_CHECKPOINT" in upper
    if first == "WITH":
        upper = text.upper()
        return any(token in upper for token in (" INSERT ", " UPDATE ", " DELETE ", " REPLACE "))
    return False


class _QueuedWriteCursor(sqlite3.Cursor):
    def execute(self, sql: str, parameters: Any = (), /) -> sqlite3.Cursor:
        if _sqlite_sql_requires_write_gate(sql):
            ensure_gate = getattr(self.connection, "_ensure_archive_db_write_gate", None)
            if callable(ensure_gate):
                ensure_gate()
        return super().execute(sql, parameters)

    def executemany(self, sql: str, seq_of_parameters: Any, /) -> sqlite3.Cursor:
        if _sqlite_sql_requires_write_gate(sql):
            ensure_gate = getattr(self.connection, "_ensure_archive_db_write_gate", None)
            if callable(ensure_gate):
                ensure_gate()
        return super().executemany(sql, seq_of_parameters)

    def executescript(self, sql_script: str, /) -> sqlite3.Cursor:
        if _sqlite_sql_requires_write_gate(sql_script):
            ensure_gate = getattr(self.connection, "_ensure_archive_db_write_gate", None)
            if callable(ensure_gate):
                ensure_gate()
        return super().executescript(sql_script)


class _AutoClosingConnection(sqlite3.Connection):
    """Close connections when callers use ``with open_db()``.

    ``sqlite3.Connection`` commits or rolls back on context exit but keeps the
    file descriptor open. Long-lived daemons in this project use ``with
    open_db()`` as a short-lived connection pattern, so make that pattern close
    the handle after preserving sqlite's native transaction semantics.
    """

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        suppress = super().__exit__(exc_type, exc, tb)
        try:
            self.close()
        except sqlite3.Error:
            pass
        return bool(suppress)

    def cursor(self, *args: Any, **kwargs: Any) -> sqlite3.Cursor:
        kwargs.setdefault("factory", _QueuedWriteCursor)
        return super().cursor(*args, **kwargs)

    def _ensure_archive_db_write_gate(self) -> None:
        if getattr(self, "_archive_db_write_gate_cm", None) is not None:
            return
        owner = str(getattr(self, "_archive_db_write_gate_owner", "scan_weather_market.open_db") or "")
        gate_cm = archive_db_write_gate(DB_PATH, owner=owner or "scan_weather_market.open_db")
        gate_cm.__enter__()
        try:
            setattr(self, "_archive_db_write_gate_cm", gate_cm)
        except Exception:
            gate_cm.__exit__(None, None, None)
            raise

    def _release_archive_db_write_gate(self) -> None:
        gate_cm = getattr(self, "_archive_db_write_gate_cm", None)
        if gate_cm is None:
            return
        try:
            setattr(self, "_archive_db_write_gate_cm", None)
        except Exception:
            pass
        try:
            gate_cm.__exit__(None, None, None)
        except Exception:
            pass

    def execute(self, sql: str, parameters: Any = (), /) -> sqlite3.Cursor:
        if _sqlite_sql_requires_write_gate(sql):
            self._ensure_archive_db_write_gate()
        return super().execute(sql, parameters)

    def executemany(self, sql: str, seq_of_parameters: Any, /) -> sqlite3.Cursor:
        if _sqlite_sql_requires_write_gate(sql):
            self._ensure_archive_db_write_gate()
        return super().executemany(sql, seq_of_parameters)

    def executescript(self, sql_script: str, /) -> sqlite3.Cursor:
        if _sqlite_sql_requires_write_gate(sql_script):
            self._ensure_archive_db_write_gate()
        return super().executescript(sql_script)

    def commit(self) -> None:
        try:
            return super().commit()
        finally:
            self._release_archive_db_write_gate()

    def rollback(self) -> None:
        try:
            return super().rollback()
        finally:
            self._release_archive_db_write_gate()

    def close(self) -> None:
        try:
            super().close()
        finally:
            self._release_archive_db_write_gate()


def _open_db_connection(
    *,
    connect_timeout_sec: float,
    busy_timeout_ms: int,
    autocommit: bool = False,
    ensure_journal_mode: bool = False,
) -> sqlite3.Connection:
    connect_kwargs: Dict[str, Any] = {
        "timeout": float(connect_timeout_sec),
        "factory": _AutoClosingConnection,
    }
    if autocommit:
        connect_kwargs["isolation_level"] = None
    conn = sqlite3.connect(DB_PATH, **connect_kwargs)
    setattr(conn, "_archive_db_write_gate_owner", "scan_weather_market.open_db")
    _apply_db_connection_pragmas(
        conn,
        busy_timeout_ms=int(busy_timeout_ms),
        ensure_journal_mode=bool(ensure_journal_mode),
    )
    return conn


def _open_auto_trade_job_bookkeeping_db() -> sqlite3.Connection:
    return _open_db_connection(
        connect_timeout_sec=float(_auto_trade_job_bookkeeping_connect_timeout_sec()),
        busy_timeout_ms=int(_auto_trade_job_bookkeeping_busy_timeout_ms()),
        ensure_journal_mode=True,
    )


def _auto_trade_runtime_lock_stale_sec() -> int:
    raw = os.environ.get("PM_AUTO_TRADE_RUNTIME_LOCK_STALE_SEC", "1800")
    try:
        val = int(float(str(raw or "1800").strip()))
    except Exception:
        val = 1800
    return max(300, min(val, 24 * 3600))


def _auto_trade_runtime_lock_acquire(run_date: str, *, note: str = "") -> bool:
    lock_dir = DATA_DIR / "auto_trade_runtime.lock"
    meta_path = lock_dir / "meta.json"
    stale_sec = _auto_trade_runtime_lock_stale_sec()
    if lock_dir.exists():
        stale = True
        lock_pid = ""
        started_at = ""
        try:
            meta = json.loads(meta_path.read_text(encoding="utf-8"))
            lock_pid = str(meta.get("pid") or "").strip()
            started_at = str(meta.get("started_at") or "").strip()
        except Exception:
            lock_pid = ""
            started_at = ""
        if lock_pid.isdigit():
            try:
                os.kill(int(lock_pid), 0)
                stale = False
            except OSError:
                stale = True
        if not stale and started_at:
            started_dt = _parse_iso_utc(started_at)
            if started_dt is not None:
                age_sec = (datetime.now(timezone.utc) - started_dt).total_seconds()
                if age_sec >= stale_sec:
                    stale = True
        if stale:
            shutil.rmtree(lock_dir, ignore_errors=True)
    if lock_dir.exists():
        return False
    try:
        lock_dir.mkdir(parents=True, exist_ok=False)
    except FileExistsError:
        return False
    meta = {
        "pid": os.getpid(),
        "run_date": str(run_date or ""),
        "started_at": utc_now_iso(),
        "note": str(note or ""),
    }
    try:
        meta_path.write_text(json.dumps(meta, ensure_ascii=True), encoding="utf-8")
    except Exception:
        pass
    return True


def _auto_trade_runtime_lock_release() -> None:
    lock_dir = DATA_DIR / "auto_trade_runtime.lock"
    shutil.rmtree(lock_dir, ignore_errors=True)


def _auto_trade_runtime_lock_is_active(*, cleanup_stale: bool = False) -> bool:
    lock_dir = DATA_DIR / "auto_trade_runtime.lock"
    meta_path = lock_dir / "meta.json"
    if not lock_dir.exists():
        return False
    lock_pid = ""
    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
        lock_pid = str(meta.get("pid") or "").strip()
    except Exception:
        lock_pid = ""
    if lock_pid.isdigit():
        try:
            os.kill(int(lock_pid), 0)
            return True
        except OSError:
            pass
    if cleanup_stale:
        shutil.rmtree(lock_dir, ignore_errors=True)
    return False


def _auto_trade_direct_runtime_lock_wait_sec() -> float:
    raw = _env_float("PM_AUTO_TRADE_DIRECT_RUNTIME_LOCK_WAIT_SEC")
    if raw is None or not math.isfinite(raw):
        raw = 0.0
    return max(0.0, min(float(raw), 1.0))


def _serialize_job_row(row: Optional[sqlite3.Row]) -> Dict[str, Any]:
    if not row:
        return {}
    out: Dict[str, Any] = {}
    for key in row.keys():
        out[str(key)] = row[key]
    return out


def _auto_trade_job_cleanup_history(conn: sqlite3.Connection, now_dt: datetime, now_iso: str) -> Dict[str, int]:
    """Compact terminal job history so stale blockers do not accumulate forever."""
    out = {"superseded": 0, "deleted": 0}
    cur = conn.cursor()
    try:
        out["superseded"] = mark_superseded_terminal_jobs_with_newer_active(
            cur,
            now_iso=now_iso,
        )
    except sqlite3.Error:
        out["superseded"] = 0
    keep_days = _auto_trade_job_history_days()
    cutoff_iso = (now_dt - timedelta(days=keep_days)).isoformat(timespec="seconds")
    try:
        out["deleted"] = delete_terminal_auto_trade_jobs_before(
            cur,
            cutoff_iso=cutoff_iso,
        )
    except sqlite3.Error:
        out["deleted"] = 0
    return out


def enqueue_auto_trade_job(
    run_date: str,
    *,
    source: str = "",
    priority: int = 0,
    payload: Optional[Dict[str, Any]] = None,
    max_retry: Optional[int] = None,
    force_enqueue: bool = False,
) -> Dict[str, Any]:
    init_db()
    run_date_key = _normalize_date_key(run_date)
    run_date_parsed = _parse_date(run_date_key)
    run_date_key = run_date_parsed.isoformat() if run_date_parsed is not None else ""
    et_today = today_date_str("America/New_York")
    if not run_date_key:
        run_date_key = et_today
    if run_date_key > et_today:
        run_date_key = et_today
    if not run_date_key:
        return {"ok": False, "error": "no_run_date"}
    source_text = str(source or "").strip() or "manual"
    priority_val = int(priority or 0)
    max_retry_val = _auto_trade_job_max_retry_default() if max_retry is None else int(max_retry)
    max_retry_val = max(0, min(max_retry_val, 20))
    now_iso = utc_now_iso()
    payload_json = ""
    if isinstance(payload, dict):
        try:
            payload_json = json.dumps(payload, ensure_ascii=True, separators=(",", ":"))
        except Exception:
            payload_json = ""
    with open_db() as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        locked_error: Optional[Exception] = None
        job_id = 0
        inserted: Optional[sqlite3.Row] = None
        for attempt in range(3):
            now_dt = datetime.now(timezone.utc)
            active_cutoff = (
                now_dt - timedelta(seconds=_auto_trade_job_stuck_sec())
            ).isoformat(timespec="seconds")
            try:
                _auto_trade_job_reap_stuck_rows(conn, now_dt, now_iso)
                _auto_trade_job_cleanup_history(conn, now_dt, now_iso)
                if not force_enqueue:
                    try:
                        cur.execute(
                            """
                            SELECT *
                            FROM auto_trade_jobs
                            WHERE run_date = ?
                              AND (
                                    state IN ('queued', 'retrying')
                                    OR (
                                        state = 'running'
                                        AND (
                                            (COALESCE(lease_until, '') <> '' AND lease_until > ?)
                                            OR (
                                                COALESCE(lease_until, '') = ''
                                                AND COALESCE(updated_at, started_at, created_at, '') <> ''
                                                AND COALESCE(updated_at, started_at, created_at) > ?
                                            )
                                        )
                                    )
                                  )
                            ORDER BY priority DESC, created_at DESC, id DESC
                            LIMIT 1
                            """,
                            (run_date_key, now_iso, active_cutoff),
                        )
                        active = cur.fetchone()
                    except sqlite3.Error:
                        active = None
                    if active:
                        return {
                            "ok": True,
                            "enqueued": False,
                            "reason": "already_active",
                            "job": _serialize_job_row(active),
                        }
                job_id = insert_auto_trade_job(
                    cur,
                    run_date=run_date_key,
                    source=source_text,
                    priority=priority_val,
                    payload_json=payload_json,
                    max_retry=max_retry_val,
                    next_retry_at=now_iso,
                    created_at=now_iso,
                    updated_at=now_iso,
                )
                conn.commit()
                try:
                    cur.execute("SELECT * FROM auto_trade_jobs WHERE id = ?", (job_id,))
                    inserted = cur.fetchone()
                except sqlite3.Error:
                    inserted = None
                break
            except sqlite3.OperationalError as exc:
                try:
                    conn.rollback()
                except sqlite3.Error:
                    pass
                if "locked" in str(exc).lower() and attempt < 2:
                    locked_error = exc
                    time.sleep(0.5 * (attempt + 1))
                    continue
                raise
        if job_id <= 0 and locked_error is not None:
            raise locked_error
    return {"ok": True, "enqueued": True, "job": _serialize_job_row(inserted)}


def _auto_trade_job_insert_run_row(run_date: str, started_at: str) -> Optional[int]:
    if not DB_PATH.exists():
        return None
    for attempt in range(3):
        try:
            with _open_auto_trade_job_bookkeeping_db() as conn:
                cur = conn.cursor()
                cur.execute(
                    """
                    INSERT INTO auto_trade_runs(run_date, started_at, ended_at, ok, error, processed, skipped, created_at)
                    VALUES (?, ?, NULL, NULL, '', 0, 0, ?)
                    """,
                    (run_date, started_at, started_at),
                )
                conn.commit()
                rid = int(cur.lastrowid or 0)
            return rid if rid > 0 else None
        except sqlite3.OperationalError as exc:
            if _sqlite_locked_error(exc) and attempt < 2:
                time.sleep(0.1 * float(attempt + 1))
                continue
            return None
        except Exception:
            return None
    return None


def _auto_trade_job_update_run_row(
    run_id: Optional[int],
    *,
    ended_at: str,
    ok: int,
    error: str,
    processed: int,
    skipped: int,
) -> None:
    if not run_id:
        return
    for attempt in range(3):
        try:
            with _open_auto_trade_job_bookkeeping_db() as conn:
                cur = conn.cursor()
                cur.execute(
                    """
                    UPDATE auto_trade_runs
                    SET ended_at = ?, ok = ?, error = ?, processed = ?, skipped = ?
                    WHERE id = ?
                    """,
                    (
                        ended_at,
                        int(ok),
                        str(error or ""),
                        int(processed or 0),
                        int(skipped or 0),
                        int(run_id),
                    ),
                )
                conn.commit()
            return
        except sqlite3.OperationalError as exc:
            if _sqlite_locked_error(exc) and attempt < 2:
                time.sleep(0.1 * float(attempt + 1))
                continue
            return
        except Exception:
            return


def _auto_trade_job_touch(
    job_id: int,
    *,
    run_id: Optional[int] = None,
    now_dt: Optional[datetime] = None,
) -> Optional[bool]:
    if int(job_id or 0) <= 0:
        return False
    now_dt = now_dt or datetime.now(timezone.utc)
    now_iso = now_dt.isoformat(timespec="seconds")
    lease_until = (now_dt + timedelta(seconds=_auto_trade_job_lease_sec())).isoformat(
        timespec="seconds"
    )
    locked_seen = False
    for attempt in range(5):
        try:
            with _open_auto_trade_job_bookkeeping_db() as conn:
                cur = conn.cursor()
                updated = touch_running_auto_trade_job(
                    cur,
                    job_id=job_id,
                    lease_until=lease_until,
                    now_iso=now_iso,
                    run_id=run_id,
                )
                conn.commit()
                return bool(updated)
        except sqlite3.OperationalError as exc:
            if _sqlite_locked_error(exc):
                locked_seen = True
                if attempt < 4:
                    time.sleep(0.2 * float(attempt + 1))
                    continue
                return None
            return False
        except Exception:
            return False
    if locked_seen:
        return None
    return False


def _auto_trade_job_write_final_state(
    job_id: int,
    *,
    state: str,
    ended_at: str,
    run_id: Optional[int],
    last_error: str = "",
    retry_count: Optional[int] = None,
    next_retry_at: str = "",
) -> Dict[str, Any]:
    if int(job_id or 0) <= 0:
        return {}
    state_now = str(state or "").strip().lower()
    if state_now not in {"success", "retrying", "failed", "superseded"}:
        raise ValueError(f"unsupported_job_state:{state_now}")
    for attempt in range(5):
        try:
            with _open_auto_trade_job_bookkeeping_db() as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                if state_now == "success":
                    write_auto_trade_job_final_state(
                        cur,
                        job_id=job_id,
                        state="success",
                        ended_at=ended_at,
                        run_id=run_id,
                        attempts=5,
                    )
                elif state_now == "retrying":
                    write_auto_trade_job_final_state(
                        cur,
                        job_id=job_id,
                        state="retrying",
                        ended_at=ended_at,
                        run_id=run_id,
                        retry_count=retry_count,
                        next_retry_at=str(next_retry_at or ""),
                        last_error=str(last_error or "auto_trade_failed"),
                        attempts=5,
                    )
                elif state_now == "failed":
                    write_auto_trade_job_final_state(
                        cur,
                        job_id=job_id,
                        state="failed",
                        ended_at=ended_at,
                        run_id=run_id,
                        retry_count=retry_count,
                        last_error=str(last_error or "auto_trade_failed"),
                        attempts=5,
                    )
                else:
                    write_auto_trade_job_final_state(
                        cur,
                        job_id=job_id,
                        state="superseded",
                        ended_at=ended_at,
                        run_id=run_id,
                        last_error=str(last_error or "superseded"),
                        attempts=5,
                    )
                conn.commit()
                _sqlite_execute_with_retry(
                    cur,
                    "SELECT * FROM auto_trade_jobs WHERE id = ?",
                    (int(job_id),),
                    attempts=5,
                )
                row = cur.fetchone()
                return _serialize_job_row(row)
        except sqlite3.OperationalError as exc:
            if _sqlite_locked_error(exc) and attempt < 4:
                time.sleep(0.25 * float(attempt + 1))
                continue
            return {}
        except Exception:
            return {}
    return {}


def _auto_trade_job_reap_stuck_rows(conn: sqlite3.Connection, now_dt: datetime, now_iso: str) -> int:
    stuck_sec = _auto_trade_job_stuck_sec()
    lease_cutoff = now_iso
    active_cutoff = (now_dt - timedelta(seconds=stuck_sec)).isoformat(timespec="seconds")
    cur = conn.cursor()
    cur.execute(
        """
        SELECT id, run_id, run_date, started_at, retry_count, max_retry
        FROM auto_trade_jobs
        WHERE state = 'running'
          AND (
                (COALESCE(lease_until, '') <> '' AND lease_until <= ?)
                OR (
                    COALESCE(lease_until, '') = ''
                    AND COALESCE(updated_at, started_at, created_at, '') <> ''
                    AND COALESCE(updated_at, started_at, created_at) <= ?
                )
              )
        """,
        (lease_cutoff, active_cutoff),
    )
    stale_jobs = cur.fetchall() or []
    stale_job_ids = {
        int(to_float((row["id"] if hasattr(row, "keys") else row[0])) or 0)
        for row in stale_jobs
        if row is not None
    }
    if not _auto_trade_runtime_lock_is_active(cleanup_stale=True):
        orphan_cutoff = (
            now_dt - timedelta(seconds=_auto_trade_job_orphan_grace_sec())
        ).isoformat(timespec="seconds")
        cur.execute(
            """
            SELECT id, run_id, run_date, started_at, retry_count, max_retry
            FROM auto_trade_jobs
            WHERE state = 'running'
              AND COALESCE(updated_at, started_at, created_at, '') <> ''
              AND COALESCE(updated_at, started_at, created_at) <= ?
            """,
            (orphan_cutoff,),
        )
        for orphan_row in cur.fetchall() or []:
            orphan_id = int(
                to_float(
                    orphan_row["id"] if hasattr(orphan_row, "keys") else orphan_row[0]
                )
                or 0
            )
            if orphan_id <= 0 or orphan_id in stale_job_ids:
                continue
            stale_jobs.append(orphan_row)
            stale_job_ids.add(orphan_id)
    stuck_jobs = 0
    base_backoff = _auto_trade_job_base_backoff_sec()

    def _row_get(row_obj: Any, key: str, idx: int, default: Any = None) -> Any:
        try:
            if hasattr(row_obj, "keys"):
                return row_obj[key]
        except Exception:
            pass
        try:
            return row_obj[idx]
        except Exception:
            return default

    for stale in stale_jobs:
        job_id = int(to_float(_row_get(stale, "id", 0)) or 0)
        if job_id <= 0:
            continue
        retry_count = int(to_float(_row_get(stale, "retry_count", 4)) or 0)
        max_retry = int(to_float(_row_get(stale, "max_retry", 5)) or _auto_trade_job_max_retry_default())
        max_retry = max(0, min(max_retry, 20))
        retry_count_next = retry_count + 1
        if retry_count_next <= max_retry:
            backoff = base_backoff * (2 ** max(0, retry_count_next - 1))
            backoff = min(backoff, 600.0)
            next_retry_iso = (now_dt + timedelta(seconds=backoff)).isoformat(timespec="seconds")
            updated_count = mark_running_auto_trade_job_retrying(
                cur,
                job_id=job_id,
                retry_count=retry_count_next,
                next_retry_at=next_retry_iso,
                now_iso=now_iso,
            )
        else:
            updated_count = mark_running_auto_trade_job_failed(
                cur,
                job_id=job_id,
                retry_count=retry_count_next,
                now_iso=now_iso,
            )
        stuck_jobs += int(updated_count or 0)
    # Close run rows linked to newly reaped stuck jobs.
    for stale in stale_jobs:
        try:
            run_id = int(to_float(_row_get(stale, "run_id", 1)) or 0)
        except Exception:
            run_id = 0
        if run_id > 0:
            cur.execute(
                """
                UPDATE auto_trade_runs
                SET ended_at = ?,
                    ok = COALESCE(ok, 0),
                    error = CASE
                        WHEN COALESCE(error, '') = '' THEN 'worker_stuck_timeout'
                        ELSE error
                    END,
                    processed = COALESCE(processed, 0),
                    skipped = COALESCE(skipped, 0)
                WHERE id = ?
                  AND COALESCE(ended_at, '') = ''
                """,
                (now_iso, run_id),
            )
            continue
        run_date = str(_row_get(stale, "run_date", 2, "") or "").strip()
        started_at = str(_row_get(stale, "started_at", 3, "") or "").strip()
        if not run_date or not started_at:
            continue
        cur.execute(
            """
            SELECT id
            FROM auto_trade_runs
            WHERE run_date = ?
              AND COALESCE(ended_at, '') = ''
              AND started_at >= ?
              AND started_at <= ?
            ORDER BY started_at ASC, id ASC
            LIMIT 1
            """,
            (run_date, started_at, now_iso),
        )
        row_run = cur.fetchone()
        if not row_run:
            continue
        run_pick = int((row_run[0] if isinstance(row_run, tuple) else row_run["id"]) or 0)
        if run_pick <= 0:
            continue
        cur.execute(
            """
            UPDATE auto_trade_runs
            SET ended_at = ?,
                ok = COALESCE(ok, 0),
                error = CASE
                    WHEN COALESCE(error, '') = '' THEN 'worker_stuck_timeout'
                    ELSE error
                END,
                processed = COALESCE(processed, 0),
                skipped = COALESCE(skipped, 0)
            WHERE id = ?
              AND COALESCE(ended_at, '') = ''
            """,
            (now_iso, run_pick),
        )
    # Backfill run-table closure for any orphaned/stale runs that never received ended_at
    # (e.g. worker crash before job finalization).
    cur.execute(
        """
        UPDATE auto_trade_runs
        SET ended_at = ?,
            ok = COALESCE(ok, 0),
            error = CASE
                WHEN COALESCE(error, '') = '' THEN 'worker_stuck_timeout'
                ELSE error
            END,
            processed = COALESCE(processed, 0),
            skipped = COALESCE(skipped, 0)
        WHERE (COALESCE(ended_at, '') = '')
          AND (COALESCE(started_at, '') <> '')
          AND started_at <= ?
          AND NOT EXISTS (
                SELECT 1
                FROM auto_trade_jobs j
                WHERE j.state = 'running'
                  AND j.run_id = auto_trade_runs.id
          )
        """,
        (now_iso, active_cutoff),
    )
    return stuck_jobs


def _auto_trade_job_claim_one(requested_job_id: Optional[int] = None) -> Optional[Dict[str, Any]]:
    init_db()
    requested_id = 0
    try:
        requested_id = int(requested_job_id or 0)
    except Exception:
        requested_id = 0
    exclude_direct_target_jobs = _env_bool("PM_AUTO_TRADE_JOB_CLAIM_EXCLUDE_DIRECT_TARGET", False)
    claim_only_target_realization_v3 = _env_bool(
        "PM_AUTO_TRADE_JOB_CLAIM_ONLY_TARGET_REALIZATION_V3",
        False,
    )
    direct_latest_first = (
        _env_bool("PM_AUTO_TRADE_DIRECT_JOB_CLAIM_LATEST_FIRST", False)
        and not exclude_direct_target_jobs
    )
    # The v3-dedicated worker owns only v3 execution latency.  Broad legacy
    # cleanup can scan historical jobs/runs while holding BEGIN IMMEDIATE and
    # must remain on the maintenance/general-worker lane.
    skip_claim_cleanup = _env_bool(
        "PM_AUTO_TRADE_JOB_SKIP_CLEANUP_ON_CLAIM",
        False,
    ) or claim_only_target_realization_v3
    claim_retry = _env_int("PM_AUTO_TRADE_JOB_CLAIM_RETRY")
    if claim_retry is None or int(claim_retry) < 1:
        claim_retry = 8
    claim_retry = max(1, min(int(claim_retry), 60))
    claim_backoff = _env_float("PM_AUTO_TRADE_JOB_CLAIM_BACKOFF_SEC")
    if claim_backoff is None or not math.isfinite(claim_backoff) or claim_backoff < 0:
        claim_backoff = 0.25
    claim_backoff_cap = _env_float("PM_AUTO_TRADE_JOB_CLAIM_BACKOFF_CAP_SEC")
    if claim_backoff_cap is None or not math.isfinite(claim_backoff_cap) or claim_backoff_cap < 0:
        claim_backoff_cap = 2.0
    for attempt in range(int(claim_retry)):
        now_dt = datetime.now(timezone.utc)
        now_iso = now_dt.isoformat(timespec="milliseconds")
        lease_until = (now_dt + timedelta(seconds=_auto_trade_job_lease_sec())).isoformat(
            timespec="milliseconds"
        )
        try:
            with open_db() as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                cur.execute("BEGIN IMMEDIATE")
                if not skip_claim_cleanup:
                    _auto_trade_job_reap_stuck_rows(conn, now_dt, now_iso)
                    _auto_trade_job_cleanup_history(conn, now_dt, now_iso)
                if requested_id > 0:
                    requested_v3_only_sql = (
                        "AND json_extract(payload_json, '$.target_realization_v3.plan_version') = "
                        "'strong_posterior_three_leg_strategy_v2'"
                        if claim_only_target_realization_v3
                        else ""
                    )
                    cur.execute(
                        f"""
                        SELECT id
                        FROM auto_trade_jobs
                        WHERE id = ?
                          AND state IN ('queued', 'retrying')
                          {requested_v3_only_sql}
                        LIMIT 1
                        """,
                        (requested_id,),
                    )
                else:
                    direct_exclusion_sql = (
                        f"AND NOT {_auto_trade_job_direct_sql_predicate()}"
                        if exclude_direct_target_jobs
                        else ""
                    )
                    v3_only_sql = (
                        "AND json_extract(payload_json, '$.target_realization_v3.plan_version') = "
                        "'strong_posterior_three_leg_strategy_v2'"
                        if claim_only_target_realization_v3
                        else ""
                    )
                    if direct_latest_first:
                        order_sql = f"""
                        ORDER BY
                          priority DESC,
                          CASE WHEN {_auto_trade_job_direct_sql_predicate()} THEN 0 ELSE 1 END ASC,
                          CASE WHEN {_auto_trade_job_direct_sql_predicate()} THEN created_at ELSE '' END DESC,
                          CASE WHEN {_auto_trade_job_direct_sql_predicate()} THEN id ELSE 0 END DESC,
                          created_at ASC,
                          id ASC
                        """
                    else:
                        order_sql = "ORDER BY priority DESC, created_at ASC, id ASC"
                    cur.execute(
                        f"""
                        SELECT id
                        FROM auto_trade_jobs
                        WHERE state IN ('queued', 'retrying')
                          AND (
                            COALESCE(next_retry_at, '') = ''
                            OR julianday(next_retry_at) <= julianday(?)
                          )
                          {direct_exclusion_sql}
                          {v3_only_sql}
                        {order_sql}
                        LIMIT 1
                        """,
                        (now_iso,),
                    )
                row = cur.fetchone()
                if not row:
                    conn.commit()
                    return None
                job_id = int(row["id"] or 0)
                claim_auto_trade_job_running(
                    cur,
                    job_id=job_id,
                    lease_until=lease_until,
                    now_iso=now_iso,
                )
                cur.execute("SELECT * FROM auto_trade_jobs WHERE id = ?", (job_id,))
                picked = cur.fetchone()
                conn.commit()
            return _serialize_job_row(picked) if picked else None
        except sqlite3.OperationalError as exc:
            if (not _sqlite_locked_error(exc)) or attempt >= (int(claim_retry) - 1):
                raise
            if claim_backoff > 0:
                sleep_for = float(claim_backoff) * float(attempt + 1)
                if claim_backoff_cap > 0:
                    sleep_for = min(sleep_for, float(claim_backoff_cap))
                if sleep_for > 0:
                    time.sleep(sleep_for)
            continue
    return None


def auto_trade_job_status(run_date: str = "", limit: int = 20) -> Dict[str, Any]:
    init_db()
    run_date_key = _normalize_date_key(run_date)
    now_iso = utc_now_iso()
    limit_val = max(1, min(int(limit or 20), 200))
    with open_db() as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        where_sql = ""
        params: List[Any] = []
        if run_date_key:
            where_sql = "WHERE run_date = ?"
            params.append(run_date_key)
        cur.execute(
            f"""
            SELECT state, COUNT(*) AS cnt
            FROM auto_trade_jobs
            {where_sql}
            GROUP BY state
            """,
            tuple(params),
        )
        counts = {str(r["state"] or ""): int(r["cnt"] or 0) for r in (cur.fetchall() or [])}
        cur.execute(
            f"""
            SELECT *
            FROM auto_trade_jobs
            {where_sql}
            ORDER BY created_at DESC, id DESC
            LIMIT ?
            """,
            tuple(params + [limit_val]),
        )
        rows = cur.fetchall() or []
    items = [_serialize_job_row(r) for r in rows]
    active = next((it for it in items if str(it.get("state") or "") in {"running", "retrying", "queued"}), None)
    return {
        "ok": True,
        "run_date": run_date_key,
        "generated_at": now_iso,
        "counts": counts,
        "active": active or {},
        "items": items,
    }


def run_auto_trade_job_worker_once(requested_job_id: Optional[int] = None) -> Dict[str, Any]:
    class _AutoTradeWorkerInterrupted(BaseException):
        pass

    # The dedicated Live worker runs against an already-migrated production DB.
    # Validate its narrow execution schema read-only and mark this process ready
    # before the generic claim helper reaches the very large full init_db path.
    # A new/incomplete DB fails this probe and keeps the existing full-init
    # fallback, so tests and bootstrap installs retain their migration behavior.
    if _env_bool("PM_AUTO_TRADE_WORKER_EXISTING_SCHEMA_FAST_PATH", False):
        _mark_existing_auto_trade_worker_schema_ready()

    requested_id = 0
    try:
        requested_id = int(requested_job_id or 0)
    except Exception:
        requested_id = 0
    exclude_direct_target_jobs = _env_bool("PM_AUTO_TRADE_JOB_CLAIM_EXCLUDE_DIRECT_TARGET", False)
    direct_claim_candidate = (
        (not exclude_direct_target_jobs)
        and (requested_id > 0 or _auto_trade_has_claimable_direct_target_job())
    )
    quick_claim_env: Dict[str, str] = {}
    if direct_claim_candidate:
        quick_claim_env = {
            "PM_AUTO_TRADE_JOB_CLAIM_RETRY": str(
                max(1, min(_env_int("PM_AUTO_TRADE_DIRECT_JOB_CLAIM_RETRY") or 2, 8))
            ),
            "PM_AUTO_TRADE_JOB_CLAIM_BACKOFF_SEC": f"{max(0.0, min(_env_float('PM_AUTO_TRADE_DIRECT_JOB_CLAIM_BACKOFF_SEC') or 0.025, 0.25)):.3f}",
            "PM_AUTO_TRADE_JOB_CLAIM_BACKOFF_CAP_SEC": f"{max(0.0, min(_env_float('PM_AUTO_TRADE_DIRECT_JOB_CLAIM_BACKOFF_CAP_SEC') or 0.050, 0.5)):.3f}",
            "PM_AUTO_TRADE_JOB_LEASE_SEC": str(
                max(30, min(_env_int("PM_AUTO_TRADE_DIRECT_JOB_LEASE_SEC") or 30, 120))
            ),
            "PM_AUTO_TRADE_JOB_STUCK_SEC": str(
                max(30, min(_env_int("PM_AUTO_TRADE_DIRECT_JOB_STUCK_SEC") or 30, 120))
            ),
            "PM_AUTO_TRADE_JOB_ORPHAN_GRACE_SEC": str(
                max(15, min(_env_int("PM_AUTO_TRADE_DIRECT_JOB_ORPHAN_GRACE_SEC") or 15, 60))
            ),
            "PM_AUTO_TRADE_JOB_BACKOFF_SEC": f"{max(1.0, min(_env_float('PM_AUTO_TRADE_DIRECT_JOB_BACKOFF_SEC') or 1.0, 5.0)):.3f}",
            "PM_DB_CONNECT_TIMEOUT_SEC": f"{max(0.05, min(_env_float('PM_AUTO_TRADE_DIRECT_JOB_DB_CONNECT_TIMEOUT_SEC') or 0.250, 1.0)):.3f}",
            "PM_DB_BUSY_TIMEOUT_MS": str(
                max(50, min(_env_int("PM_AUTO_TRADE_DIRECT_JOB_DB_BUSY_TIMEOUT_MS") or 250, 1000))
            ),
            "PM_AUTO_TRADE_DIRECT_RUNTIME_LOCK_WAIT_SEC": f"{max(0.0, min(_env_float('PM_AUTO_TRADE_DIRECT_RUNTIME_LOCK_WAIT_SEC') or 0.0, 1.0)):.3f}",
            "PM_AUTO_TRADE_JOB_BOOKKEEPING_CONNECT_TIMEOUT_SEC": f"{max(0.05, min(_env_float('PM_AUTO_TRADE_JOB_BOOKKEEPING_CONNECT_TIMEOUT_SEC') or 0.150, 0.300)):.3f}",
            "PM_AUTO_TRADE_JOB_BOOKKEEPING_BUSY_TIMEOUT_MS": str(
                max(100, min(_env_int("PM_AUTO_TRADE_JOB_BOOKKEEPING_BUSY_TIMEOUT_MS") or 200, 300))
            ),
            "PM_AUTO_TRADE_DIRECT_JOB_CLAIM_LATEST_FIRST": "1",
            "PM_AUTO_TRADE_JOB_SKIP_CLEANUP_ON_CLAIM": "1",
            "PM_AUTO_TRADE_DECISION_WRITE_RETRY_ATTEMPTS": str(
                max(1, min(_env_int("PM_AUTO_TRADE_DIRECT_DECISION_WRITE_RETRY_ATTEMPTS") or 1, 3))
            ),
            "PM_AUTO_TRADE_DECISION_WRITE_RETRY_SLEEP_SEC": f"{max(0.0, min(_env_float('PM_AUTO_TRADE_DIRECT_DECISION_WRITE_RETRY_SLEEP_SEC') or 0.0, 0.1)):.3f}",
        }
    quick_claim_prev = {key: os.environ.get(key) for key in quick_claim_env}
    try:
        if direct_claim_candidate:
            for key, value in quick_claim_env.items():
                os.environ[key] = value
        else:
            wait_sec = _env_float("PM_AUTO_TRADE_FACTS_LOCK_WAIT_SEC")
            if wait_sec is None:
                wait_sec = _facts_lock_wait_sec()
            if not _wait_for_facts_lock("auto-trade", wait_sec):
                return {"ok": True, "picked": False, "message": "facts_lock_active"}
            if not _wait_for_db_writer_lock("auto-trade", _env_float("PM_AUTO_TRADE_DB_LOCK_WAIT_SEC")):
                if not _env_bool("PM_AUTO_TRADE_DB_LOCK_BEST_EFFORT", True):
                    return {"ok": True, "picked": False, "message": "db_writer_lock_active"}
                print("[auto-trade] db_writer lock active, continue with best-effort claim")
        picked = _auto_trade_job_claim_one(requested_job_id=requested_id if requested_id > 0 else None)
    finally:
        for key, prev in quick_claim_prev.items():
            if prev is None:
                os.environ.pop(key, None)
            else:
                os.environ[key] = prev
    if not picked:
        return {"ok": True, "picked": False, "message": "no_job"}
    job_id = int(picked.get("id") or 0)
    run_date_raw = _normalize_date_key(str(picked.get("run_date") or ""))
    run_date_parsed = _parse_date(run_date_raw)
    run_date = run_date_parsed.isoformat() if run_date_parsed is not None else today_date_str("America/New_York")
    et_today = today_date_str("America/New_York")
    if run_date > et_today:
        run_date = et_today
    now_iso = utc_now_iso_ms()
    payload_raw = str(picked.get("payload_json") or "").strip()
    payload: Dict[str, Any] = {}
    if payload_raw:
        try:
            parsed = json.loads(payload_raw)
            if isinstance(parsed, dict):
                payload = parsed
        except Exception:
            payload = {}
    direct_target_job_payload = _auto_trade_payload_is_direct_target_job(payload)
    if (
        direct_target_job_payload
        and not bool(payload.get("exit_only"))
        and _env_bool("PM_AUTO_TRADE_DIRECT_JOB_PRIMARY_FAST_SLICE_EARLY", True)
        and _direct_target_primary_only_fast_path_enabled(payload)
    ):
        payload_sliced, slice_applied, deferred_targets = _direct_target_primary_entry_fast_slice_payload(
            payload
        )
        if slice_applied:
            payload = payload_sliced
            payload["direct_target_primary_entry_fast_slice_early"] = True
            payload["direct_target_deferred_target_count_early"] = int(deferred_targets)
            posterior_block = payload.get("posterior_target_direct")
            if isinstance(posterior_block, dict):
                posterior_block["primary_fast_slice_early"] = True
                posterior_block["deferred_target_count_early"] = int(deferred_targets)
            for event_item in payload.get("event_payloads") or []:
                if not isinstance(event_item, dict):
                    continue
                event_payload = event_item.get("payload")
                if not isinstance(event_payload, dict):
                    continue
                event_block = event_payload.get("posterior_target_direct")
                if isinstance(event_block, dict):
                    event_block["primary_fast_slice_early"] = True
                    event_block["deferred_target_count_early"] = int(deferred_targets)
            direct_target_job_payload = _auto_trade_payload_is_direct_target_job(payload)
    worker_started_at = now_iso
    hard_source_block = payload.get("hard_source_direct")
    hard_source_worker_context: Dict[str, Any] = {}
    if isinstance(hard_source_block, dict):
        hard_source_block["worker_started_at"] = worker_started_at
        hard_source_block["job_id"] = job_id
        hard_source_block["job_enqueue_to_worker_ms"] = _iso_latency_ms_between(
            hard_source_block.get("job_enqueued_at"),
            worker_started_at,
        )
        hard_source_block["ssot_to_worker_ms"] = _iso_latency_ms_between(
            hard_source_block.get("ssot_written_at"),
            worker_started_at,
        )
        if hard_source_block.get("awc_hard_source_signal_at"):
            hard_source_block["signal_to_worker_ms"] = _iso_latency_ms_between(
                hard_source_block.get("awc_hard_source_signal_at"),
                worker_started_at,
            )
            timing = (
                dict(hard_source_block.get("signal_to_order_timing"))
                if isinstance(hard_source_block.get("signal_to_order_timing"), Mapping)
                else {}
            )
            if timing:
                timing["worker_started_at"] = worker_started_at
                timing["signal_to_worker_ms"] = hard_source_block.get("signal_to_worker_ms")
                if not str(timing.get("terminal_state") or "").strip() or str(timing.get("terminal_state")) == "job_enqueued":
                    timing["terminal_state"] = "worker_started"
                    timing["terminal_reason"] = "awaiting_order_submit"
                hard_source_block["signal_to_order_timing"] = timing
        _merge_hard_source_direct_block_context(
            hard_source_worker_context,
            hard_source_block,
        )

    def _merge_worker_hard_source_context_into_target(target: Dict[str, Any]) -> None:
        if not isinstance(target, dict) or not hard_source_worker_context:
            return
        if not bool(target.get("hard_source_direct") or target.get("hard_source_posterior_override")):
            return
        context_outcome = str(hard_source_worker_context.get("outcome") or "").strip()
        context_side = str(hard_source_worker_context.get("side") or "YES").strip().upper()
        target_outcome = str(target.get("outcome") or target.get("target_bucket") or "").strip()
        target_side = str(target.get("side") or "YES").strip().upper()
        if context_outcome and target_outcome and context_outcome != target_outcome:
            return
        if context_side and target_side and context_side != target_side:
            return
        _copy_hard_source_sla_fields(target, hard_source_worker_context)
    posterior_target_block = payload.get("posterior_target_direct")
    if isinstance(posterior_target_block, dict):
        posterior_target_block["worker_started_at"] = worker_started_at
        posterior_target_block["job_id"] = job_id
        posterior_target_block["job_enqueue_to_worker_ms"] = _iso_latency_ms_between(
            posterior_target_block.get("job_enqueued_at"),
            worker_started_at,
        )
        posterior_target_block["fact_to_worker_ms"] = _iso_latency_ms_between(
            posterior_target_block.get("fact_as_of"),
            worker_started_at,
        )
    raw_targets = payload.get("entry_expected_targets")
    if isinstance(raw_targets, list):
        for target in raw_targets:
            if not isinstance(target, dict):
                continue
            _merge_worker_hard_source_context_into_target(target)
            if bool(target.get("hard_source_direct") or target.get("hard_source_posterior_override")):
                target["hard_source_worker_started_at"] = worker_started_at
                target["hard_source_job_id"] = job_id
                target["hard_source_job_enqueue_to_worker_ms"] = _iso_latency_ms_between(
                    target.get("hard_source_job_enqueued_at"),
                    worker_started_at,
                )
                target["hard_source_ssot_to_worker_ms"] = _iso_latency_ms_between(
                    target.get("hard_source_ssot_written_at"),
                    worker_started_at,
                )
                if target.get("awc_hard_source_signal_at"):
                    target["signal_to_worker_ms"] = _iso_latency_ms_between(
                        target.get("awc_hard_source_signal_at"),
                        worker_started_at,
                    )
                    timing = (
                        dict(target.get("signal_to_order_timing"))
                        if isinstance(target.get("signal_to_order_timing"), Mapping)
                        else {}
                    )
                    if timing:
                        timing["worker_started_at"] = worker_started_at
                        timing["signal_to_worker_ms"] = target.get("signal_to_worker_ms")
                        if not str(timing.get("terminal_state") or "").strip() or str(timing.get("terminal_state")) == "job_enqueued":
                            timing["terminal_state"] = "worker_started"
                            timing["terminal_reason"] = "awaiting_order_submit"
                        target["signal_to_order_timing"] = timing
            if bool(target.get("posterior_target_direct")):
                target["posterior_target_worker_started_at"] = worker_started_at
                target["posterior_target_job_id"] = job_id
                target["posterior_target_job_enqueue_to_worker_ms"] = _iso_latency_ms_between(
                    target.get("posterior_target_job_enqueued_at"),
                    worker_started_at,
                )
                target["posterior_target_fact_to_worker_ms"] = _iso_latency_ms_between(
                    target.get("posterior_target_fact_as_of"),
                    worker_started_at,
                )
    for event_item in payload.get("event_payloads") or []:
        if not isinstance(event_item, dict):
            continue
        event_payload = event_item.get("payload")
        if not isinstance(event_payload, dict):
            continue
        nested_block = event_payload.get("hard_source_direct")
        if isinstance(nested_block, dict):
            nested_block["worker_started_at"] = worker_started_at
            nested_block["job_id"] = job_id
            nested_block["job_enqueue_to_worker_ms"] = _iso_latency_ms_between(
                nested_block.get("job_enqueued_at"),
                worker_started_at,
            )
        nested_posterior_target = event_payload.get("posterior_target_direct")
        if isinstance(nested_posterior_target, dict):
            nested_posterior_target["worker_started_at"] = worker_started_at
            nested_posterior_target["job_id"] = job_id
            nested_posterior_target["job_enqueue_to_worker_ms"] = _iso_latency_ms_between(
                nested_posterior_target.get("job_enqueued_at"),
                worker_started_at,
            )
            nested_posterior_target["fact_to_worker_ms"] = _iso_latency_ms_between(
                nested_posterior_target.get("fact_as_of"),
                worker_started_at,
            )
        nested_targets = event_payload.get("entry_expected_targets")
        if not isinstance(nested_targets, list):
            continue
        for target in nested_targets:
            if not isinstance(target, dict):
                continue
            _merge_worker_hard_source_context_into_target(target)
            if bool(target.get("hard_source_direct") or target.get("hard_source_posterior_override")):
                target["hard_source_worker_started_at"] = worker_started_at
                target["hard_source_job_id"] = job_id
                target["hard_source_job_enqueue_to_worker_ms"] = _iso_latency_ms_between(
                    target.get("hard_source_job_enqueued_at"),
                    worker_started_at,
                )
                target["hard_source_ssot_to_worker_ms"] = _iso_latency_ms_between(
                    target.get("hard_source_ssot_written_at"),
                    worker_started_at,
                )
                if target.get("awc_hard_source_signal_at"):
                    target["signal_to_worker_ms"] = _iso_latency_ms_between(
                        target.get("awc_hard_source_signal_at"),
                        worker_started_at,
                    )
                    timing = (
                        dict(target.get("signal_to_order_timing"))
                        if isinstance(target.get("signal_to_order_timing"), Mapping)
                        else {}
                    )
                    if timing:
                        timing["worker_started_at"] = worker_started_at
                        timing["signal_to_worker_ms"] = target.get("signal_to_worker_ms")
                        if not str(timing.get("terminal_state") or "").strip() or str(timing.get("terminal_state")) == "job_enqueued":
                            timing["terminal_state"] = "worker_started"
                            timing["terminal_reason"] = "awaiting_order_submit"
                        target["signal_to_order_timing"] = timing
            if bool(target.get("posterior_target_direct")):
                target["posterior_target_worker_started_at"] = worker_started_at
                target["posterior_target_job_id"] = job_id
                target["posterior_target_job_enqueue_to_worker_ms"] = _iso_latency_ms_between(
                    target.get("posterior_target_job_enqueued_at"),
                    worker_started_at,
                )
                target["posterior_target_fact_to_worker_ms"] = _iso_latency_ms_between(
                    target.get("posterior_target_fact_as_of"),
                    worker_started_at,
                )
    exit_only = bool(payload.get("exit_only"))
    target_realization_v3_execution = payload.get("target_realization_v3")
    target_realization_v3_execution = (
        target_realization_v3_execution
        if isinstance(target_realization_v3_execution, Mapping)
        else {}
    )
    target_realization_v3_execution_phase = str(
        target_realization_v3_execution.get("execution_phase") or ""
    ).strip().upper()
    target_realization_v3_phase_recognized = target_realization_v3_execution_phase in {
        "",
        "BUY_NEW",
        "SELL_OLD",
        "REFRESH_BUY",
    }
    target_realization_v3_sell_phase = bool(
        target_realization_v3_execution_phase == "SELL_OLD"
    )
    target_realization_v3_refresh_phase = bool(
        target_realization_v3_execution_phase == "REFRESH_BUY"
    )
    skip_direct_run_row = bool(
        direct_target_job_payload
        and _env_bool("PM_AUTO_TRADE_DIRECT_JOB_SKIP_RUN_ROW", False)
    )
    run_id = None if skip_direct_run_row else _auto_trade_job_insert_run_row(run_date, now_iso)
    if run_id is not None and job_id > 0:
        linked = False
        for attempt in range(5):
            try:
                with _open_auto_trade_job_bookkeeping_db() as conn_link:
                    cur_link = conn_link.cursor()
                    link_running_auto_trade_job_run_id(
                        cur_link,
                        job_id=job_id,
                        run_id=run_id,
                        now_iso=now_iso,
                    )
                    conn_link.commit()
                    linked = True
                    break
            except sqlite3.OperationalError as exc:
                if "locked" in str(exc).lower() and attempt < 4:
                    time.sleep(0.25 * (attempt + 1))
                    continue
                break
            except Exception:
                break
        if not linked:
            print(f"[auto-trade] warn run_id_link_failed job_id={job_id} run_id={run_id}")
    result: Dict[str, Any]
    err_text = ""
    direct_disabled_fast_path = bool(
        direct_target_job_payload
        and not _env_bool("PM_AUTO_TRADE_ENABLED", False)
    )
    direct_active_entry_fast_result: Dict[str, Any] = {}
    direct_active_entry_fast_completed = False
    lock_acquired = False
    if not target_realization_v3_phase_recognized:
        result = {
            "ok": False,
            "status": "target_realization_v3_unknown_execution_phase",
            "run_date": run_date,
            "processed": 0,
            "skipped": 0,
            "places_orders": False,
        }
        err_text = "target_realization_v3_unknown_execution_phase"
    elif direct_disabled_fast_path:
        result = _record_direct_target_disabled_job_decisions(
            run_id=run_id,
            run_date=run_date,
            payload=payload,
        )
    elif direct_target_job_payload and not exit_only:
        direct_active_entry_fast_result = _record_direct_target_already_active_job_decisions(
            run_id=run_id,
            run_date=run_date,
            payload=payload,
            job_id=job_id,
            worker_started_at=worker_started_at,
        )
        if direct_active_entry_fast_result.get("ok"):
            result = direct_active_entry_fast_result
            direct_active_entry_fast_completed = True
        else:
            lock_acquired = _auto_trade_runtime_lock_acquire(run_date, note="auto_trade_job_worker")
            if not lock_acquired:
                wait_sec = _auto_trade_direct_runtime_lock_wait_sec()
                deadline = time.monotonic() + wait_sec
                while wait_sec > 0 and time.monotonic() < deadline:
                    time.sleep(min(0.05, max(0.0, deadline - time.monotonic())))
                    lock_acquired = _auto_trade_runtime_lock_acquire(
                        run_date,
                        note="auto_trade_job_worker_direct_target_retry",
                    )
                    if lock_acquired:
                        break
    else:
        lock_acquired = _auto_trade_runtime_lock_acquire(run_date, note="auto_trade_job_worker")
        if not lock_acquired and direct_target_job_payload:
            wait_sec = _auto_trade_direct_runtime_lock_wait_sec()
            deadline = time.monotonic() + wait_sec
            while wait_sec > 0 and time.monotonic() < deadline:
                time.sleep(min(0.05, max(0.0, deadline - time.monotonic())))
                lock_acquired = _auto_trade_runtime_lock_acquire(
                    run_date,
                    note="auto_trade_job_worker_direct_target_retry",
                )
                if lock_acquired:
                    break
    if (
        target_realization_v3_phase_recognized
        and (not direct_disabled_fast_path)
        and (not direct_active_entry_fast_completed)
        and not lock_acquired
    ):
        result = {
            "ok": False,
            "error": "runtime_lock_busy",
            "run_date": run_date,
            "processed": 0,
            "skipped": 0,
            "direct_target_runtime_lock_fast_retry": bool(direct_target_job_payload),
            "direct_target_active_entry_fast_confirm": dict(direct_active_entry_fast_result),
        }
        err_text = "runtime_lock_busy"
    elif (
        target_realization_v3_phase_recognized
        and (not direct_disabled_fast_path)
        and (not direct_active_entry_fast_completed)
    ):
        heartbeat_stop = threading.Event()
        heartbeat_interval = _env_float("PM_AUTO_TRADE_JOB_HEARTBEAT_SEC")
        if heartbeat_interval is None or not math.isfinite(heartbeat_interval) or heartbeat_interval <= 0:
            heartbeat_interval = 45.0
        heartbeat_interval = max(5.0, min(float(heartbeat_interval), 300.0))
        heartbeat_thread: Optional[threading.Thread] = None
        signal_handlers_installed = False
        previous_signal_handlers: Dict[int, Any] = {}

        def _heartbeat() -> None:
            if job_id > 0:
                touched = _auto_trade_job_touch(job_id, run_id=run_id)
                if touched is None:
                    print(f"[auto-trade] job heartbeat delayed: bookkeeping_locked job_id={job_id}")
                    return
                if not touched:
                    raise RuntimeError(f"touch_failed job_id={job_id}")

        def _heartbeat_loop() -> None:
            while not heartbeat_stop.wait(heartbeat_interval):
                try:
                    _heartbeat()
                except Exception as exc:
                    print(f"[auto-trade] job heartbeat loop failed: {exc}")

        def _signal_name(signum: int) -> str:
            try:
                return str(signal.Signals(int(signum)).name or "").strip().lower()
            except Exception:
                return f"signal_{int(signum)}"

        def _install_worker_signal_handlers() -> None:
            nonlocal signal_handlers_installed
            if threading.current_thread() is not threading.main_thread():
                return

            def _handle(signum: int, _frame: Any) -> None:
                raise _AutoTradeWorkerInterrupted(_signal_name(signum))

            for sig_obj in (signal.SIGTERM, signal.SIGINT):
                sig_num = int(sig_obj)
                previous_signal_handlers[sig_num] = signal.getsignal(sig_obj)
                signal.signal(sig_obj, _handle)
            signal_handlers_installed = True

        try:
            _install_worker_signal_handlers()
            try:
                _heartbeat()
            except Exception as exc:
                print(f"[auto-trade] job heartbeat bootstrap failed: {exc}")
            heartbeat_thread = threading.Thread(
                target=_heartbeat_loop,
                name="auto_trade_job_heartbeat",
                daemon=True,
            )
            heartbeat_thread.start()
            _refresh_auto_trade_config()
            if target_realization_v3_refresh_phase:
                transition_signal_at = str(
                    target_realization_v3_execution.get("transition_signal_at")
                    or target_realization_v3_execution.get("sell_fill_confirmed_at")
                    or ""
                )
                refresh_result = _target_realization_v3_refresh_after_sell_fill(
                    payload,
                    transition_signal_at=transition_signal_at,
                )
                result = {
                    **dict(refresh_result),
                    "run_date": run_date,
                    "processed": 1 if refresh_result.get("ok") else 0,
                    "skipped": 0 if refresh_result.get("ok") else 1,
                    "target_realization_v3_refresh_phase": True,
                }
                if refresh_result.get("ok") is not True:
                    result["ok"] = False
                    result["error"] = str(
                        refresh_result.get("error")
                        or "target_realization_v3_fill_refresh_failed"
                    )
            elif target_realization_v3_sell_phase:
                sell_result = _direct_target_old_exit_cleanup_after_success(
                    payload,
                    run_id=run_id,
                    run_date=run_date,
                    job_id=job_id,
                    worker_started_at=worker_started_at,
                )
                result = {
                    **dict(sell_result),
                    "run_date": run_date,
                    "processed": int(sell_result.get("submitted") or 0),
                    "skipped": int(sell_result.get("skipped") or 0),
                    "target_realization_v3_sell_phase": True,
                    "buy_new_deferred": True,
                    "buy_new_requires_latest_ssot_refresh": True,
                    "sell_fill_confirmed_at": (
                        utc_now_iso_ms() if sell_result.get("all_filled") is True else ""
                    ),
                }
                if sell_result.get("all_filled") is True:
                    transition_signal_at = str(result.get("sell_fill_confirmed_at") or "")
                    refresh_result = _target_realization_v3_refresh_after_sell_fill(
                        payload,
                        transition_signal_at=transition_signal_at,
                    )
                    result["target_realization_v3_fill_refresh"] = dict(refresh_result)
                    result["buy_new_job_id"] = refresh_result.get("job_id")
                    result["buy_new_job_enqueued"] = bool(refresh_result.get("job_enqueued"))
                    result["fill_to_buy_job_enqueue_ms"] = refresh_result.get("elapsed_ms")
                    if refresh_result.get("ok") is not True:
                        persisted = _target_realization_v3_persist_refresh_phase(
                            job_id,
                            payload,
                            transition_signal_at=transition_signal_at,
                        )
                        result["refresh_retry_phase_persisted"] = persisted
                        result["ok"] = False
                        result["error"] = str(
                            refresh_result.get("error")
                            or "target_realization_v3_fill_refresh_failed"
                        )
                else:
                    result["ok"] = False
                    result["error"] = "target_realization_v3_sell_old_not_fully_filled"
            else:
                result = run_auto_trades_for_date(
                    run_date,
                    exit_only=exit_only,
                    run_id=run_id,
                    job_heartbeat=_heartbeat,
                    job_payload=payload,
                )
            if isinstance(result, dict) and skip_direct_run_row:
                result.setdefault("direct_job_skip_run_row", True)
            if not result.get("ok"):
                err_text = str(result.get("error") or "auto_trade_failed")
        except _AutoTradeWorkerInterrupted as exc:
            worker_signal_name = str(exc or "").strip().lower() or "signal"
            result = {
                "ok": False,
                "error": f"worker_terminated_{worker_signal_name}",
                "run_date": run_date,
                "processed": 0,
                "skipped": 0,
            }
            err_text = str(result["error"])
        except Exception as exc:
            result = {"ok": False, "error": str(exc), "run_date": run_date, "processed": 0, "skipped": 0}
            err_text = str(exc)
        finally:
            heartbeat_stop.set()
            if heartbeat_thread is not None:
                try:
                    heartbeat_thread.join(timeout=1.0)
                except Exception:
                    pass
            _auto_trade_runtime_lock_release()
            if signal_handlers_installed:
                for sig_num, prev_handler in previous_signal_handlers.items():
                    try:
                        signal.signal(sig_num, prev_handler)
                    except Exception:
                        pass

    if (
        isinstance(result, dict)
        and bool(result.get("ok"))
        and direct_target_job_payload
        and not exit_only
        and not target_realization_v3_sell_phase
        and not target_realization_v3_refresh_phase
    ):
        direct_old_exit_cleanup_result = _direct_target_old_exit_cleanup_after_success(
            payload,
            run_id=run_id,
            run_date=run_date,
            job_id=job_id,
            worker_started_at=worker_started_at,
        )
        if direct_old_exit_cleanup_result.get("status") != "not_applicable":
            result["direct_target_old_exit_cleanup"] = direct_old_exit_cleanup_result

    ended_iso = utc_now_iso()
    ok_flag = bool(result.get("ok"))
    signal_terminal_results: List[Dict[str, Any]] = []
    if not ok_flag:
        terminal_reason = str(err_text or result.get("error") or "auto_trade_failed").strip()
        terminal_state = _classify_signal_to_order_terminal_state(
            terminal_reason,
            terminal_reason,
            will_order=True,
        )
        signal_terminal_results = _upsert_signal_to_order_terminal_for_payload(
            payload,
            terminal_state=terminal_state,
            terminal_reason=terminal_reason or terminal_state,
            terminal_at=ended_iso,
        )
        if signal_terminal_results:
            result["signal_to_order_terminal_results"] = signal_terminal_results[:8]
    processed = int(result.get("processed") or 0)
    skipped = int(result.get("skipped") or 0)
    if run_id is not None:
        _auto_trade_job_update_run_row(
            run_id,
            ended_at=ended_iso,
            ok=1 if ok_flag else 0,
            error=err_text,
            processed=processed,
            skipped=skipped,
        )

    if ok_flag:
        job_row = _auto_trade_job_write_final_state(
            job_id,
            state="success",
            ended_at=ended_iso,
            run_id=run_id,
        )
        if not job_row:
            job_row = dict(picked)
            job_row["state"] = "success"
            job_row["run_id"] = run_id
            job_row["ended_at"] = ended_iso
            job_row["updated_at"] = ended_iso
            job_row["last_error"] = ""
        response = {
            "ok": True,
            "picked": True,
            "job": job_row,
            "result": result,
        }
        chained_buy_job_id = int(result.get("buy_new_job_id") or 0) if isinstance(result, Mapping) else 0
        if (
            target_realization_v3_sell_phase
            and chained_buy_job_id > 0
            and chained_buy_job_id != job_id
            and _env_bool("PM_TARGET_REALIZATION_V3_CHAIN_BUY_WORKER_INLINE", True)
        ):
            chained_started = time.monotonic()
            chained = run_auto_trade_job_worker_once(requested_job_id=chained_buy_job_id)
            response["target_realization_v3_chained_buy_worker"] = chained
            response["fill_refresh_to_chained_worker_complete_ms"] = round(
                max(0.0, time.monotonic() - chained_started) * 1000.0,
                3,
            )
        return response
    direct_runtime_lock_busy = bool(direct_target_job_payload and err_text == "runtime_lock_busy")
    retry_count = int(picked.get("retry_count") or 0) + (0 if direct_runtime_lock_busy else 1)
    max_retry = int(picked.get("max_retry") or _auto_trade_job_max_retry_default())
    max_retry = max(0, min(max_retry, 20))
    if retry_count <= max_retry:
        backoff_base = _auto_trade_job_base_backoff_sec()
        backoff = backoff_base * (2 ** max(0, retry_count - 1))
        backoff = min(backoff, 600.0)
        next_retry_dt = datetime.now(timezone.utc) + timedelta(seconds=backoff)
        next_retry_iso = next_retry_dt.isoformat(timespec="seconds")
        job_row = _auto_trade_job_write_final_state(
            job_id,
            state="retrying",
            ended_at=ended_iso,
            run_id=run_id,
            last_error=err_text or "auto_trade_failed",
            retry_count=retry_count,
            next_retry_at=next_retry_iso,
        )
        if not job_row:
            job_row = dict(picked)
            job_row["state"] = "retrying"
            job_row["retry_count"] = retry_count
            job_row["next_retry_at"] = next_retry_iso
            job_row["run_id"] = run_id
            job_row["ended_at"] = ended_iso
            job_row["updated_at"] = ended_iso
            job_row["last_error"] = err_text or "auto_trade_failed"
        return {
            "ok": False,
            "picked": True,
            "retrying": True,
            "job": job_row,
            "result": result,
            "error": err_text or "auto_trade_failed",
            "signal_to_order_terminal_results": signal_terminal_results[:8],
        }
    job_row = _auto_trade_job_write_final_state(
        job_id,
        state="failed",
        ended_at=ended_iso,
        run_id=run_id,
        last_error=err_text or "auto_trade_failed",
        retry_count=retry_count,
    )
    if not job_row:
        job_row = dict(picked)
        job_row["state"] = "failed"
        job_row["retry_count"] = retry_count
        job_row["run_id"] = run_id
        job_row["ended_at"] = ended_iso
        job_row["updated_at"] = ended_iso
        job_row["last_error"] = err_text or "auto_trade_failed"
    return {
        "ok": False,
        "picked": True,
        "retrying": False,
        "job": job_row,
        "result": result,
        "error": err_text or "auto_trade_failed",
        "signal_to_order_terminal_results": signal_terminal_results[:8],
    }


def reconcile_edge_trades_positions_from_fills(conn: sqlite3.Connection) -> int:
    """
    SSOT: reconcile edge_trades.position_size from edge_trade_fills net buys/sells.

    This prevents stale position_size from causing repeated exit attempts that fail with "no_balance"
    after a position has already been sold (or was never actually held).
    """
    cur = conn.cursor()
    now_iso = utc_now_iso()
    now_dt = datetime.now(timezone.utc)
    lookback_days_raw = os.environ.get("PM_TRADE_SYNC_RECONCILE_LOOKBACK_DAYS", "21").strip()
    try:
        lookback_days = int(float(lookback_days_raw))
    except Exception:
        lookback_days = 21
    lookback_days = max(1, min(lookback_days, 180))
    cutoff_dt = now_dt - timedelta(days=lookback_days)
    cutoff_iso = cutoff_dt.isoformat(timespec="seconds")

    try:
        cur.execute(
            """
            SELECT slug, event_date, outcome, outcome_side,
                   SUM(CASE WHEN trade_side = 'BUY' THEN size ELSE -size END) AS net_size,
                   MAX(trade_time) AS last_trade_time
            FROM edge_trade_fills
            WHERE trade_time >= ?
            GROUP BY slug, event_date, outcome, outcome_side
            """,
            (cutoff_iso,),
        )
        rows = cur.fetchall()
    except sqlite3.OperationalError:
        return 0

    updated = 0
    for slug, event_date, outcome, side, net_size, last_trade_time in rows:
        slug = str(slug or "")
        event_date = str(event_date or "")
        outcome = str(outcome or "")
        side = str(side or "")
        if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
            continue
        try:
            net = float(net_size) if net_size is not None else 0.0
        except (TypeError, ValueError):
            net = 0.0
        if not math.isfinite(net):
            net = 0.0
        if net < 0:
            net = 0.0

        try:
            cur.execute(
                """
                SELECT position_size, last_error, last_action
                FROM edge_trades
                WHERE slug = ? AND event_date = ? AND outcome = ? AND side = ?
                LIMIT 1
                """,
                (slug, event_date, outcome, side),
            )
            row = cur.fetchone()
        except sqlite3.OperationalError:
            row = None
        if not row:
            continue

        prev_pos = to_float(row[0])
        prev_pos = prev_pos if prev_pos is not None and math.isfinite(prev_pos) else 0.0
        if abs(prev_pos - net) > 1e-6:
            updated += update_position_size_from_fill(
                cur,
                slug=slug,
                event_date=event_date,
                outcome=outcome,
                side=side,
                position_size=net,
                last_fill_at=str(last_trade_time or ""),
                now_iso=now_iso,
            )

        if net <= TIME_EDGE_Q_EPS:
            last_error = str(row[1] or "").strip().lower()
            last_action = str(row[2] or "").strip().lower()
            if last_action == "exit_skip" and last_error in {"no_balance", "balance_parse_failed", "balance_unavailable"}:
                updated += clear_balance_skip_after_no_position(
                    cur,
                    slug=slug,
                    event_date=event_date,
                    outcome=outcome,
                    side=side,
                    max_position_size=TIME_EDGE_Q_EPS,
                    now_iso=now_iso,
                )

    # Clear stale no-position errors that otherwise keep health in blocker state.
    # Scope:
    # - exit state with no position (any date), or
    # - past events with no position (entry/entry_pending leftovers).
    try:
        today_local = today_date_str("America/New_York")
    except Exception:
        today_local = today_date_str("utc")
    try:
        updated += reconcile_no_position_errors(
            cur,
            now_iso=now_iso,
            max_position_size=TIME_EDGE_Q_EPS,
            today=today_local,
        )
    except sqlite3.OperationalError:
        pass
    try:
        updated += reconcile_past_no_position_entries(
            cur,
            now_iso=now_iso,
            max_position_size=TIME_EDGE_Q_EPS,
            today=today_local,
        )
    except sqlite3.OperationalError:
        pass
    return updated


def _normalize_wallet_address(value: Any) -> str:
    text = str(value or "").strip().lower()
    if re.fullmatch(r"0x[a-f0-9]{40}", text):
        return text
    return ""


def _resolve_signer_address_from_env() -> str:
    """Best-effort derive the signer EOA address from PRIVATE_KEY."""
    private_key = str(os.environ.get("PRIVATE_KEY") or "").strip()
    if not private_key:
        return ""
    if EthAccount is not None:
        try:
            addr = str(EthAccount.from_key(private_key).address or "").strip()
            return _normalize_wallet_address(addr)
        except Exception:
            pass
    node_bin = shutil.which("node") or "/opt/homebrew/bin/node" or "/usr/local/bin/node"
    try:
        res = subprocess.run(
            [
                node_bin,
                "-e",
                "const { Wallet } = require('ethers'); console.log(new Wallet(process.env.PRIVATE_KEY).address)",
            ],
            env={"PRIVATE_KEY": private_key},
            capture_output=True,
            text=True,
            timeout=3,
            check=False,
        )
        return _normalize_wallet_address((res.stdout or "").strip())
    except Exception:
        return ""


def _mirror_trade_id(trade: Dict[str, Any]) -> str:
    if not isinstance(trade, dict):
        return ""
    explicit_id = trade.get("tradeID") or trade.get("tradeId") or trade.get("id")
    if explicit_id:
        return str(explicit_id)
    tx_hash = str(trade.get("transactionHash") or trade.get("transaction_hash") or "").strip().lower()
    token = str(
        trade.get("asset")
        or trade.get("tokenID")
        or trade.get("tokenId")
        or trade.get("token_id")
        or ""
    ).strip()
    side = str(trade.get("side") or "").strip().upper()
    ts = trade.get("timestamp")
    price = trade.get("price")
    size = trade.get("size") or trade.get("quantity")
    payload = f"{tx_hash}|{token}|{side}|{ts}|{price}|{size}"
    return hashlib.sha1(payload.encode("utf-8")).hexdigest()


def _mirror_trade_timestamp(trade: Dict[str, Any]) -> int:
    if not isinstance(trade, dict):
        return 0
    ts_raw = trade.get("timestamp")
    if ts_raw is not None:
        try:
            ts_num = float(ts_raw)
            if math.isfinite(ts_num) and ts_num > 0:
                if ts_num > 1e12:
                    ts_num = ts_num / 1000.0
                return int(ts_num)
        except (TypeError, ValueError):
            pass
    for key in ("createdAt", "created_at", "time"):
        ts_text = str(trade.get(key) or "").strip()
        if not ts_text:
            continue
        try:
            dt = datetime.fromisoformat(ts_text.replace("Z", "+00:00"))
            return int(dt.timestamp())
        except Exception:
            continue
    return 0


def _mirror_source_trade_merge_key(trade: Dict[str, Any]) -> str:
    if not isinstance(trade, dict):
        return ""
    tx_hash = str(trade.get("transactionHash") or trade.get("transaction_hash") or "").strip().lower()
    token = str(
        trade.get("asset")
        or trade.get("tokenID")
        or trade.get("tokenId")
        or trade.get("token_id")
        or ""
    ).strip()
    side = str(trade.get("side") or "").strip().upper()
    if tx_hash and token and side:
        return f"tx:{tx_hash}|{token}|{side}"
    explicit_id = trade.get("tradeID") or trade.get("tradeId") or trade.get("id")
    if explicit_id:
        return f"id:{str(explicit_id).strip().lower()}"
    fallback_id = _mirror_trade_id(trade)
    if fallback_id:
        return f"hash:{fallback_id}"
    return ""


def _normalize_mirror_source_trade_rows(
    rows: List[Dict[str, Any]],
    *,
    source: str,
) -> List[Dict[str, Any]]:
    grouped: Dict[str, Dict[str, Any]] = {}
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        if source == "activity":
            row_type = str(row.get("type") or "").strip().upper()
            if row_type and row_type != "TRADE":
                continue
        side = str(row.get("side") or "").strip().upper()
        if side not in {"BUY", "SELL"}:
            continue
        token = str(
            row.get("asset")
            or row.get("tokenID")
            or row.get("tokenId")
            or row.get("token_id")
            or ""
        ).strip()
        if not token:
            continue
        ts = _mirror_trade_timestamp(row)
        if ts <= 0:
            continue
        price = to_float(row.get("price"))
        size = to_float(row.get("size") or row.get("quantity"))
        if (
            price is None
            or size is None
            or not math.isfinite(price)
            or not math.isfinite(size)
            or price <= 0
            or size <= 0
        ):
            continue
        merge_key = _mirror_source_trade_merge_key(row)
        if not merge_key:
            continue
        stable_id = hashlib.sha1(merge_key.encode("utf-8")).hexdigest()
        group = grouped.get(merge_key)
        if group is None:
            tx_hash = str(row.get("transactionHash") or row.get("transaction_hash") or "").strip().lower()
            grouped[merge_key] = {
                "merge_key": merge_key,
                "tradeID": stable_id,
                "transactionHash": tx_hash,
                "asset": token,
                "side": side,
                "timestamp": int(ts),
                "notional_sum": float(price) * float(size),
                "size_sum": float(size),
                "row_count": 1,
                "source": source,
            }
            continue
        group["notional_sum"] = float(group.get("notional_sum") or 0.0) + float(price) * float(size)
        group["size_sum"] = float(group.get("size_sum") or 0.0) + float(size)
        group["row_count"] = int(group.get("row_count") or 0) + 1
        if ts >= int(group.get("timestamp") or 0):
            group["timestamp"] = int(ts)
    out: List[Dict[str, Any]] = []
    for payload in grouped.values():
        size_sum = to_float(payload.get("size_sum"))
        notional_sum = to_float(payload.get("notional_sum"))
        if (
            size_sum is None
            or notional_sum is None
            or not math.isfinite(size_sum)
            or not math.isfinite(notional_sum)
            or size_sum <= 0
            or notional_sum <= 0
        ):
            continue
        price = notional_sum / size_sum
        out.append(
            {
                "tradeID": str(payload.get("tradeID") or ""),
                "transactionHash": str(payload.get("transactionHash") or ""),
                "asset": str(payload.get("asset") or ""),
                "side": str(payload.get("side") or ""),
                "timestamp": int(payload.get("timestamp") or 0),
                "price": float(price),
                "size": float(size_sum),
                "_merge_key": str(payload.get("merge_key") or ""),
                "_source": str(payload.get("source") or source),
                "_row_count": int(payload.get("row_count") or 1),
            }
        )
    out.sort(key=lambda item: int(item.get("timestamp") or 0), reverse=True)
    return out


def _normalize_mirror_source_activity_ops(
    rows: List[Dict[str, Any]],
    *,
    source: str,
) -> List[Dict[str, Any]]:
    """
    Normalize non-trade "activity" rows (e.g. CONVERSION / MERGE / REDEEM) into a stable,
    de-duplicable feed for diagnostics / UI display.

    These are *not* CLOB trades and should not trigger mirror-follow order placement.
    """
    out: List[Dict[str, Any]] = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        row_type = str(row.get("type") or "").strip().upper()
        if row_type not in {"CONVERSION", "MERGE", "REDEEM"}:
            continue
        # Activity rows typically carry a tx hash but do not have an asset/side/price like trades.
        tx_hash = str(row.get("transactionHash") or row.get("transaction_hash") or "").strip().lower()
        if not tx_hash:
            continue
        ts = _mirror_trade_timestamp(row)
        if ts <= 0:
            continue
        slug = str(row.get("slug") or "").strip()
        event_slug = str(row.get("eventSlug") or row.get("event_slug") or "").strip()
        title = str(row.get("title") or "").strip()
        condition_id = str(row.get("conditionId") or row.get("condition_id") or "").strip()
        size = to_float(row.get("size") or row.get("quantity"))
        usdc_size = to_float(row.get("usdcSize") or row.get("usdc_size"))
        merge_key = f"{row_type}|{tx_hash}"
        stable_id = hashlib.sha1(merge_key.encode("utf-8")).hexdigest()
        out.append(
            {
                "op_id": stable_id,
                "op_type": row_type,
                "transactionHash": tx_hash,
                "timestamp": int(ts),
                "slug": slug,
                "eventSlug": event_slug,
                "title": title,
                "conditionId": condition_id,
                "size": float(size) if size is not None and math.isfinite(size) else None,
                "usdcSize": float(usdc_size) if usdc_size is not None and math.isfinite(usdc_size) else None,
                "_merge_key": merge_key,
                "_source": str(source or "activity"),
            }
        )
    out.sort(key=lambda item: int(item.get("timestamp") or 0), reverse=True)
    return out


def _merge_mirror_source_trade_feeds(
    *,
    canonical_rows: List[Dict[str, Any]],
    extra_rows: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    merged: Dict[str, Dict[str, Any]] = {}
    for row in canonical_rows or []:
        if not isinstance(row, dict):
            continue
        key = str(row.get("_merge_key") or _mirror_source_trade_merge_key(row))
        if not key:
            continue
        merged[key] = dict(row)
    for row in extra_rows or []:
        if not isinstance(row, dict):
            continue
        key = str(row.get("_merge_key") or _mirror_source_trade_merge_key(row))
        if not key or key in merged:
            continue
        merged[key] = dict(row)
    out = list(merged.values())
    out.sort(key=lambda item: int(item.get("timestamp") or 0), reverse=True)
    return out


def _load_mirror_source_online_state() -> Dict[str, Any]:
    if not MIRROR_SOURCE_ONLINE_STATE_PATH.exists():
        return {}
    try:
        raw = json.loads(MIRROR_SOURCE_ONLINE_STATE_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return raw if isinstance(raw, dict) else {}


def _save_mirror_source_online_state(payload: Dict[str, Any]) -> None:
    if not isinstance(payload, dict):
        return
    try:
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        MIRROR_SOURCE_ONLINE_STATE_PATH.write_text(
            json.dumps(payload, ensure_ascii=True),
            encoding="utf-8",
        )
    except Exception:
        return


def _format_mirror_source_online_sms(
    source_address: str,
    latest_trade_ts: int,
    *,
    trade_count: int,
    online_window_sec: int,
) -> str:
    addr = str(source_address or "").strip().lower()
    if len(addr) >= 12:
        addr_text = f"{addr[:8]}...{addr[-4:]}"
    else:
        addr_text = addr or "unknown"
    if latest_trade_ts > 0:
        latest_at = datetime.fromtimestamp(latest_trade_ts, tz=timezone.utc).isoformat(
            timespec="seconds"
        )
    else:
        latest_at = "unknown"
    return (
        f"【影子跟单】对标账户上线 {addr_text} "
        f"最新成交(UTC)={latest_at} "
        f"近窗口={int(max(60, online_window_sec))}s "
        f"抓取条数={int(max(0, trade_count))}"
    )


def _format_mirror_order_sms(
    *,
    source_side: str,
    slug: str,
    event_date: str,
    outcome: str,
    outcome_side: str,
    source_price: Optional[float],
    source_size: Optional[float],
    mirror_price: Optional[float],
    mirror_size: Optional[float],
    mirror_order_id: str,
    when: str,
) -> str:
    source_side_norm = str(source_side or "").strip().upper()
    action_text = "跟买下单" if source_side_norm == "BUY" else "跟卖下单"
    side_label = "YES" if str(outcome_side or "").strip().upper() == "YES" else "NO"
    market_label = str(outcome or "").strip() or "—"
    date_label = str(event_date or "").strip() or "—"
    source_price_text = _format_pct(source_price)
    source_size_text = _format_ratio(source_size, 4) if source_size else "—"
    mirror_price_text = _format_pct(mirror_price)
    mirror_size_text = _format_ratio(mirror_size, 4) if mirror_size else "—"
    mirror_notional = (
        float(mirror_price) * float(mirror_size)
        if mirror_price is not None and mirror_size is not None
        else None
    )
    amount_text = _format_usdc(mirror_notional)
    order_text = str(mirror_order_id or "").strip()
    if len(order_text) > 14:
        order_text = f"{order_text[:8]}...{order_text[-4:]}"
    if not order_text:
        order_text = "—"
    event_url = f"https://polymarket.com/event/{slug}" if slug else ""
    link_text = f" 链接:{event_url}" if event_url else ""
    return (
        f"【影子跟单】{action_text} {date_label} {side_label} {market_label} "
        f"金额={amount_text} 跟价/量={mirror_price_text}/{mirror_size_text} "
        f"源价/量={source_price_text}/{source_size_text} 时间={when} 订单={order_text}{link_text}"
    )


def _mirror_source_online_transition(
    *,
    source_address: str,
    trades: List[Dict[str, Any]],
    result_ref: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "source_online": False,
        "source_latest_trade_ts": 0,
        "source_latest_trade_at": "",
        "source_online_sms_sent": False,
        "source_online_sms_enabled": False,
    }
    source_norm = _normalize_wallet_address(source_address)
    if not source_norm:
        return out
    now_ts = int(time.time())
    online_window_runtime = _env_int("PM_MIRROR_SOURCE_ONLINE_WINDOW_SEC")
    if online_window_runtime is None or online_window_runtime < 60:
        online_window_runtime = MIRROR_SOURCE_ONLINE_WINDOW_SEC
    online_window_runtime = max(60, int(online_window_runtime))
    sms_cooldown_runtime = _env_int("PM_MIRROR_SOURCE_ONLINE_SMS_COOLDOWN_SEC")
    if sms_cooldown_runtime is None or sms_cooldown_runtime < 0:
        sms_cooldown_runtime = MIRROR_SOURCE_ONLINE_SMS_COOLDOWN_SEC
    sms_cooldown_runtime = max(0, int(sms_cooldown_runtime))
    sms_enabled_runtime = _env_bool(
        "PM_MIRROR_SOURCE_ONLINE_SMS_ENABLED",
        MIRROR_SOURCE_ONLINE_SMS_ENABLED,
    )
    latest_trade_ts = 0
    for trade in trades or []:
        ts = _mirror_trade_timestamp(trade if isinstance(trade, dict) else {})
        if ts > latest_trade_ts:
            latest_trade_ts = ts
    latest_trade_at = (
        datetime.fromtimestamp(latest_trade_ts, tz=timezone.utc).isoformat(timespec="seconds")
        if latest_trade_ts > 0
        else ""
    )
    source_online = latest_trade_ts > 0 and (now_ts - latest_trade_ts) <= online_window_runtime
    state = _load_mirror_source_online_state()
    prev_source = _normalize_wallet_address(state.get("source_address"))
    prev_online = bool(state.get("online")) if prev_source == source_norm else False
    last_alert_at = _parse_iso_dt(str(state.get("last_alert_at") or ""))
    if last_alert_at is not None and last_alert_at.tzinfo is None:
        last_alert_at = last_alert_at.replace(tzinfo=timezone.utc)
    last_alert_age = None
    if last_alert_at is not None:
        last_alert_age = max(
            0.0,
            (datetime.now(timezone.utc) - last_alert_at).total_seconds(),
        )
    can_send_online_sms = (
        bool(sms_enabled_runtime)
        and SMS_ENABLED
        and bool(SMS_RECIPIENT)
        and source_online
        and not prev_online
        and (
            sms_cooldown_runtime <= 0
            or last_alert_age is None
            or float(last_alert_age) >= float(sms_cooldown_runtime)
        )
    )
    if can_send_online_sms:
        sms_text = _format_mirror_source_online_sms(
            source_norm,
            latest_trade_ts,
            trade_count=len(trades or []),
            online_window_sec=online_window_runtime,
        )
        if _send_sms_message(sms_text, SMS_RECIPIENT):
            out["source_online_sms_sent"] = True
    now_iso = utc_now_iso()
    next_state: Dict[str, Any] = {
        "source_address": source_norm,
        "online": bool(source_online),
        "online_window_sec": int(online_window_runtime),
        "updated_at": now_iso,
        "last_seen_trade_ts": int(max(latest_trade_ts, int(to_float(state.get("last_seen_trade_ts")) or 0))),
        "last_seen_trade_at": (
            datetime.fromtimestamp(
                max(latest_trade_ts, int(to_float(state.get("last_seen_trade_ts")) or 0)),
                tz=timezone.utc,
            ).isoformat(timespec="seconds")
            if max(latest_trade_ts, int(to_float(state.get("last_seen_trade_ts")) or 0)) > 0
            else ""
        ),
        "last_online_at": str(state.get("last_online_at") or ""),
        "last_offline_at": str(state.get("last_offline_at") or ""),
        "last_alert_at": str(state.get("last_alert_at") or ""),
        "last_alert_trade_ts": int(to_float(state.get("last_alert_trade_ts")) or 0),
        "last_alert_trade_at": str(state.get("last_alert_trade_at") or ""),
        "last_alert_sent": bool(state.get("last_alert_sent")),
    }
    if source_online:
        next_state["last_online_at"] = now_iso
    else:
        next_state["last_offline_at"] = now_iso
    if out.get("source_online_sms_sent"):
        next_state["last_alert_at"] = now_iso
        next_state["last_alert_trade_ts"] = int(max(latest_trade_ts, 0))
        next_state["last_alert_trade_at"] = latest_trade_at
        next_state["last_alert_sent"] = True
    elif can_send_online_sms:
        next_state["last_alert_sent"] = False
    _save_mirror_source_online_state(next_state)
    out["source_online"] = bool(source_online)
    out["source_latest_trade_ts"] = int(max(latest_trade_ts, 0))
    out["source_latest_trade_at"] = latest_trade_at
    out["source_online_sms_enabled"] = bool(sms_enabled_runtime and SMS_ENABLED and bool(SMS_RECIPIENT))
    out["source_online_window_sec"] = int(online_window_runtime)
    out["source_online_sms_cooldown_sec"] = int(sms_cooldown_runtime)
    out["source_online_prev"] = bool(prev_online)
    if isinstance(result_ref, dict):
        result_ref.update(out)
    return out


def _load_mirror_token_map(conn: sqlite3.Connection) -> Dict[str, Dict[str, str]]:
    out: Dict[str, Dict[str, str]] = {}
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT slug, event_date, outcome, yes_token, no_token
            FROM market_tokens
            """
        )
    except sqlite3.OperationalError:
        return out
    for row in cur.fetchall():
        slug = str(row[0] or "")
        event_date = str(row[1] or "")
        outcome = str(row[2] or "")
        if not slug or not event_date or not outcome:
            continue
        yes_token = str(row[3] or "").strip()
        no_token = str(row[4] or "").strip()
        if yes_token:
            out[yes_token] = {
                "slug": slug,
                "event_date": event_date,
                "outcome": outcome,
                "outcome_side": "YES",
            }
        if no_token:
            out[no_token] = {
                "slug": slug,
                "event_date": event_date,
                "outcome": outcome,
                "outcome_side": "NO",
            }
    return out


def _build_mirror_event_outcome_token_index(
    token_map: Dict[str, Dict[str, str]],
) -> Dict[Tuple[str, str, str, str], str]:
    out: Dict[Tuple[str, str, str, str], str] = {}
    for token_id, mapping in (token_map or {}).items():
        if not isinstance(mapping, dict):
            continue
        slug = str(mapping.get("slug") or "")
        event_date = str(mapping.get("event_date") or "")
        outcome = str(mapping.get("outcome") or "")
        side = str(mapping.get("outcome_side") or "").upper()
        if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
            continue
        out[(slug, event_date, outcome, side)] = str(token_id or "")
    return out


def _load_latest_event_side_ticks(
    conn: sqlite3.Connection,
    *,
    slug: str,
    event_date: str,
    side: str,
    as_of_iso: str = "",
) -> List[Dict[str, Any]]:
    if not slug or not event_date:
        return []
    side_norm = str(side or "").upper()
    if side_norm not in {"YES", "NO"}:
        return []
    cur = conn.cursor()
    try:
        cur.execute(
            """
            WITH latest AS (
                SELECT
                    outcome,
                    best_bid,
                    best_ask,
                    spread,
                    bid_depth_topN,
                    ask_depth_topN,
                    created_at,
                    ROW_NUMBER() OVER (
                        PARTITION BY outcome
                        ORDER BY created_at DESC, id DESC
                    ) AS rn
                FROM event_market_ticks
                WHERE slug = ?
                  AND event_date = ?
                  AND UPPER(COALESCE(side, '')) = ?
                  AND (? = '' OR COALESCE(created_at, '') <= ?)
            )
            SELECT outcome, best_bid, best_ask, spread, bid_depth_topN, ask_depth_topN, created_at
            FROM latest
            WHERE rn = 1
            """,
            (slug, event_date, side_norm, str(as_of_iso or ""), str(as_of_iso or "")),
        )
    except sqlite3.OperationalError:
        return []
    out: List[Dict[str, Any]] = []
    for row in cur.fetchall():
        out.append(
            {
                "outcome": str(row[0] or ""),
                "best_bid": to_float(row[1]),
                "best_ask": to_float(row[2]),
                "spread": to_float(row[3]),
                "bid_depth_topN": to_float(row[4]),
                "ask_depth_topN": to_float(row[5]),
                "created_at": str(row[6] or ""),
            }
        )
    return out


def _select_mirror_no_bucket_for_buy(
    *,
    conn: sqlite3.Connection,
    ticks_cache: Dict[Tuple[str, str, str], List[Dict[str, Any]]],
    event_outcome_token_index: Dict[Tuple[str, str, str, str], str],
    slug: str,
    event_date: str,
    source_outcome: str,
    source_token_id: str,
    as_of_iso: str,
    min_ask: float,
    min_depth: float,
    max_source_ask_gap: float,
) -> Optional[Dict[str, Any]]:
    cache_key = (str(slug or ""), str(event_date or ""), str(as_of_iso or ""))
    if cache_key not in ticks_cache:
        ticks_cache[cache_key] = _load_latest_event_side_ticks(
            conn,
            slug=slug,
            event_date=event_date,
            side="NO",
            as_of_iso=as_of_iso,
        )
    rows = ticks_cache.get(cache_key) or []
    candidates = [
        row
        for row in rows
        if (
            row.get("best_ask") is not None
            and math.isfinite(float(row.get("best_ask")))
            and float(row.get("best_ask")) > 0
        )
    ]
    if not candidates:
        return None
    source_row = next((row for row in candidates if str(row.get("outcome") or "") == source_outcome), None)
    source_ask = to_float(source_row.get("best_ask")) if source_row else None
    high_cert = [row for row in candidates if float(row.get("best_ask") or 0) >= float(min_ask)]
    if not high_cert:
        return None
    selected = sorted(
        high_cert,
        key=lambda row: (
            float(row.get("best_ask") or 0.0),
            -float(row.get("ask_depth_topN") or 0.0),
            str(row.get("outcome") or ""),
        ),
    )[0]
    selected_ask = to_float(selected.get("best_ask"))
    selected_depth = to_float(selected.get("ask_depth_topN")) or 0.0
    if selected_ask is None or selected_ask <= 0:
        return None
    if min_depth > 0 and selected_depth < float(min_depth):
        return None
    if (
        source_ask is not None
        and source_ask > 0
        and max_source_ask_gap >= 0
        and (float(selected_ask) - float(source_ask)) > float(max_source_ask_gap)
    ):
        return None
    selected_outcome = str(selected.get("outcome") or "")
    selected_token_id = str(
        event_outcome_token_index.get((slug, event_date, selected_outcome, "NO")) or ""
    ).strip()
    if not selected_token_id:
        return None
    ask_rank_all = (
        1
        + next(
            idx
            for idx, row in enumerate(
                sorted(
                    candidates,
                    key=lambda item: (
                        float(item.get("best_ask") or 0.0),
                        -float(item.get("ask_depth_topN") or 0.0),
                        str(item.get("outcome") or ""),
                    ),
                )
            )
            if str(row.get("outcome") or "") == selected_outcome
        )
    )
    ask_rank_high_cert = (
        1
        + next(
            idx
            for idx, row in enumerate(
                sorted(
                    high_cert,
                    key=lambda item: (
                        float(item.get("best_ask") or 0.0),
                        -float(item.get("ask_depth_topN") or 0.0),
                        str(item.get("outcome") or ""),
                    ),
                )
            )
            if str(row.get("outcome") or "") == selected_outcome
        )
    )
    return {
        "selected_token_id": selected_token_id,
        "selected_outcome": selected_outcome,
        "source_token_id": source_token_id,
        "source_outcome": source_outcome,
        "source_ask": source_ask,
        "selected_ask": float(selected_ask),
        "selected_depth": float(selected_depth),
        "selected_created_at": str(selected.get("created_at") or ""),
        "high_cert_count": int(len(high_cert)),
        "ask_rank_all": int(ask_rank_all),
        "ask_rank_high_cert": int(ask_rank_high_cert),
    }


def _select_mirror_no_bucket_for_sell(
    *,
    event_outcome_token_index: Dict[Tuple[str, str, str, str], str],
    mirror_position_map: Dict[Tuple[str, str, str, str], float],
    slug: str,
    event_date: str,
    source_outcome: str,
) -> Optional[Dict[str, Any]]:
    holdings: List[Tuple[str, float]] = []
    for (h_slug, h_event_date, h_outcome, h_side), pos in (mirror_position_map or {}).items():
        if h_slug != slug or h_event_date != event_date or str(h_side or "").upper() != "NO":
            continue
        pos_val = to_float(pos)
        if pos_val is None or not math.isfinite(pos_val) or pos_val <= TIME_EDGE_Q_EPS:
            continue
        holdings.append((str(h_outcome or ""), float(pos_val)))
    if not holdings:
        return None
    source_holding = next((item for item in holdings if item[0] == source_outcome), None)
    if source_holding is not None:
        selected_outcome, selected_pos = source_holding
    else:
        selected_outcome, selected_pos = sorted(
            holdings,
            key=lambda item: (-float(item[1]), str(item[0])),
        )[0]
    selected_token_id = str(
        event_outcome_token_index.get((slug, event_date, selected_outcome, "NO")) or ""
    ).strip()
    if not selected_token_id:
        return None
    return {
        "selected_token_id": selected_token_id,
        "selected_outcome": selected_outcome,
        "selected_position_size": float(selected_pos),
        "source_outcome": source_outcome,
    }


def _mirror_outcome_anchor(label: str) -> Optional[Dict[str, Any]]:
    text = str(label or "").strip()
    if not text:
        return None
    try:
        spec = parse_outcome_label(text)
    except Exception:
        return None
    if spec.kind == "range" and spec.k2 is not None:
        value = (float(spec.k) + float(spec.k2)) * 0.5
    else:
        value = float(spec.k)
    if not math.isfinite(value):
        return None
    return {
        "value": float(value),
        "unit": str(spec.unit or ""),
        "kind": str(spec.kind or ""),
        "kind_rank": {"eq": 0, "range": 1, "le": 2, "ge": 2}.get(str(spec.kind or ""), 3),
    }


def _select_mirror_yes_bucket_for_buy(
    *,
    conn: sqlite3.Connection,
    ticks_cache: Dict[Tuple[str, str, str], List[Dict[str, Any]]],
    event_outcome_token_index: Dict[Tuple[str, str, str, str], str],
    slug: str,
    event_date: str,
    source_outcome: str,
    source_token_id: str,
    as_of_iso: str,
    primary_offset: float,
    fallback_offset: float,
    max_ask: float,
    min_depth: float,
) -> Optional[Dict[str, Any]]:
    source_anchor = _mirror_outcome_anchor(source_outcome)
    if not source_anchor:
        return None
    cache_key = (str(slug or ""), str(event_date or ""), str(as_of_iso or ""))
    if cache_key not in ticks_cache:
        ticks_cache[cache_key] = _load_latest_event_side_ticks(
            conn,
            slug=slug,
            event_date=event_date,
            side="YES",
            as_of_iso=as_of_iso,
        )
    rows = ticks_cache.get(cache_key) or []
    candidates_raw = [
        row
        for row in rows
        if (
            row.get("best_ask") is not None
            and math.isfinite(float(row.get("best_ask")))
            and float(row.get("best_ask")) > 0
        )
    ]
    if not candidates_raw:
        return None
    source_ask: Optional[float] = None
    parsed_candidates: List[Dict[str, Any]] = []
    for row in candidates_raw:
        outcome = str(row.get("outcome") or "")
        ask = to_float(row.get("best_ask"))
        if ask is None or ask <= 0:
            continue
        if outcome == source_outcome:
            source_ask = float(ask)
        anchor = _mirror_outcome_anchor(outcome)
        if not anchor:
            continue
        source_unit = str(source_anchor.get("unit") or "")
        if source_unit and str(anchor.get("unit") or "") and str(anchor.get("unit") or "") != source_unit:
            continue
        parsed_candidates.append(
            {
                "outcome": outcome,
                "ask": float(ask),
                "depth": float(to_float(row.get("ask_depth_topN")) or 0.0),
                "created_at": str(row.get("created_at") or ""),
                "value": float(anchor.get("value") or 0.0),
                "kind_rank": int(anchor.get("kind_rank") or 3),
            }
        )
    if not parsed_candidates:
        return None
    offsets: List[float] = []
    for val in (primary_offset, fallback_offset):
        if val is None or not math.isfinite(val):
            continue
        fval = float(val)
        if not offsets or abs(fval - offsets[-1]) > 1e-9:
            offsets.append(fval)
    if not offsets:
        return None
    source_value = float(source_anchor.get("value") or 0.0)
    attempts: List[Dict[str, Any]] = []
    for offset in offsets:
        target_value = float(source_value) + float(offset)
        direction = 0
        if offset > 1e-9:
            direction = 1
        elif offset < -1e-9:
            direction = -1
        directional_pool = parsed_candidates
        if direction > 0:
            directional_pool = [row for row in parsed_candidates if float(row.get("value") or 0.0) >= source_value - 1e-9]
        elif direction < 0:
            directional_pool = [row for row in parsed_candidates if float(row.get("value") or 0.0) <= source_value + 1e-9]
        pool = directional_pool or parsed_candidates
        ranked = sorted(
            pool,
            key=lambda row: (
                abs(float(row.get("value") or 0.0) - float(target_value)),
                int(row.get("kind_rank") or 3),
                float(row.get("ask") or 0.0),
                -float(row.get("depth") or 0.0),
                str(row.get("outcome") or ""),
            ),
        )
        if not ranked:
            continue
        selected = ranked[0]
        selected_ask = float(selected.get("ask") or 0.0)
        selected_depth = float(selected.get("depth") or 0.0)
        price_ok = bool(max_ask <= 0 or selected_ask <= float(max_ask))
        depth_ok = bool(min_depth <= 0 or selected_depth >= float(min_depth))
        attempts.append(
            {
                "offset": float(offset),
                "target_value": float(target_value),
                "selected_outcome": str(selected.get("outcome") or ""),
                "selected_ask": float(selected_ask),
                "selected_depth": float(selected_depth),
                "price_ok": bool(price_ok),
                "depth_ok": bool(depth_ok),
            }
        )
        if not price_ok or not depth_ok:
            continue
        selected_outcome = str(selected.get("outcome") or "")
        selected_token_id = str(
            event_outcome_token_index.get((slug, event_date, selected_outcome, "YES")) or ""
        ).strip()
        if not selected_token_id:
            continue
        return {
            "selected_token_id": selected_token_id,
            "selected_outcome": selected_outcome,
            "source_token_id": source_token_id,
            "source_outcome": source_outcome,
            "source_value": float(source_value),
            "source_ask": source_ask,
            "selected_ask": float(selected_ask),
            "selected_depth": float(selected_depth),
            "selected_created_at": str(selected.get("created_at") or ""),
            "selected_offset": float(offset),
            "max_ask_gate": float(max_ask),
            "min_depth_gate": float(min_depth),
            "attempts": attempts,
        }
    return None


