def _resolve_mirror_daily_budget_tz() -> str:
    tz_name = str(
        os.environ.get("PM_MIRROR_DAILY_BUDGET_TZ") or MIRROR_DAILY_BUDGET_TZ or "America/New_York"
    ).strip()
    if not tz_name:
        tz_name = "America/New_York"
    lower = tz_name.lower()
    if lower in {"et", "eastern", "us/eastern"}:
        tz_name = "America/New_York"
    if ZoneInfo is None:
        return tz_name
    try:
        ZoneInfo(tz_name)
        return tz_name
    except Exception:
        return "America/New_York"


def _day_bounds_utc_for_tz(day_iso: str, tz_name: str) -> Tuple[Optional[str], Optional[str]]:
    try:
        day = date.fromisoformat(str(day_iso or ""))
    except ValueError:
        return None, None
    if ZoneInfo is None:
        start_utc = datetime(day.year, day.month, day.day, tzinfo=timezone.utc)
        end_utc = start_utc + timedelta(days=1)
        return start_utc.isoformat(timespec="seconds"), end_utc.isoformat(timespec="seconds")
    try:
        tz = ZoneInfo(tz_name)
    except Exception:
        tz = ZoneInfo("America/New_York")
    start_local = datetime(day.year, day.month, day.day, tzinfo=tz)
    end_local = start_local + timedelta(days=1)
    return (
        start_local.astimezone(timezone.utc).isoformat(timespec="seconds"),
        end_local.astimezone(timezone.utc).isoformat(timespec="seconds"),
    )


def _resolve_mirror_notional(
    source_price: Optional[float],
    source_size: Optional[float],
    *,
    copy_ratio: float,
    notional_mode: str,
    daily_budget_remaining: Optional[float] = None,
) -> Optional[float]:
    source_notional: Optional[float] = None
    if (
        source_price is not None
        and source_size is not None
        and math.isfinite(source_price)
        and math.isfinite(source_size)
        and source_price > 0
        and source_size > 0
    ):
        source_notional = float(source_price) * float(source_size)
    notional = None
    if notional_mode == "daily_remaining_ratio":
        # Per-trade follow notional: source_notional * copy_ratio.
        # Daily budget ratio is a hard cap (applied below via daily_budget_remaining).
        if source_notional is not None:
            ratio = copy_ratio if math.isfinite(copy_ratio) and copy_ratio > 0 else 1.0
            notional = source_notional * ratio
        elif MIRROR_ORDER_USDC is not None and math.isfinite(MIRROR_ORDER_USDC) and MIRROR_ORDER_USDC > 0:
            notional = float(MIRROR_ORDER_USDC)
        else:
            fallback = _env_float("PM_ORDER_USDC")
            if fallback is not None and math.isfinite(fallback) and fallback > 0:
                notional = float(fallback)
    else:
        if MIRROR_ORDER_USDC is not None and math.isfinite(MIRROR_ORDER_USDC) and MIRROR_ORDER_USDC > 0:
            notional = float(MIRROR_ORDER_USDC)
        elif source_notional is not None:
            ratio = copy_ratio if math.isfinite(copy_ratio) and copy_ratio > 0 else 1.0
            notional = source_notional * ratio
        else:
            fallback = _env_float("PM_ORDER_USDC")
            if fallback is not None and math.isfinite(fallback) and fallback > 0:
                notional = float(fallback)
    if notional is None or not math.isfinite(notional) or notional <= 0:
        return None
    min_required = 0.0
    if MIRROR_MIN_ORDER_USDC > 0:
        min_required = float(MIRROR_MIN_ORDER_USDC)
    if MIRROR_EXCHANGE_MIN_ORDER_USDC > 0:
        min_required = max(min_required, float(MIRROR_EXCHANGE_MIN_ORDER_USDC))
    if min_required > 0:
        notional = max(notional, float(min_required))
    if MIRROR_MAX_ORDER_USDC > 0:
        notional = min(notional, MIRROR_MAX_ORDER_USDC)
    if (
        daily_budget_remaining is not None
        and math.isfinite(daily_budget_remaining)
        and daily_budget_remaining > 0
        and notional > daily_budget_remaining
    ):
        notional = float(daily_budget_remaining)
        # If we're budget-capped below the exchange minimum, treat it as exhausted.
        if MIRROR_EXCHANGE_MIN_ORDER_USDC > 0 and notional + TIME_EDGE_Q_EPS < float(MIRROR_EXCHANGE_MIN_ORDER_USDC):
            return None
    return notional if notional > 0 else None


def _mirror_retry_error_markers(raw: str) -> List[str]:
    parts = [str(part or "").strip().lower() for part in str(raw or "").split(",")]
    return [part for part in parts if part]


def _mirror_retry_count_from_raw(raw_json_text: Optional[str]) -> int:
    if not raw_json_text:
        return 0
    try:
        payload = json.loads(raw_json_text)
    except Exception:
        return 0
    if not isinstance(payload, dict):
        return 0
    value = payload.get("mirror_retry_count")
    try:
        count = int(value)
    except (TypeError, ValueError):
        return 0
    return max(0, count)


def _mirror_error_retryable(error_text: str, markers: List[str]) -> bool:
    lowered = str(error_text or "").strip().lower()
    if not lowered:
        return False
    # Venue-specific rejection that can be fixed by enforcing a higher minimum notional.
    if "invalid amount" in lowered and "min size" in lowered:
        return True
    # Mirror-follow specific transient: order accepted/placed but matched 0 and ended canceled.
    # We want to retry these even if the retry marker list is strict.
    if any(marker in lowered for marker in ("buy_not_filled", "canceled_no_fill", "not_filled", "no_fill")):
        return True
    if not markers:
        return True
    return any(marker in lowered for marker in markers)


class _MirrorSourceRtdsBuffer:
    """Thread-safe buffer of source trades received via RTDS websocket.

    The goal is low-latency ingestion during bursty periods; we keep this buffer
    small and drain it from the mirror-follow loop (SSOT remains mirror_follow_trades).
    """

    def __init__(self, max_rows: int = 2000) -> None:
        self._lock = threading.Lock()
        self._rows: List[Dict[str, Any]] = []
        self._max_rows = int(max_rows) if max_rows > 0 else 2000
        self._last_recv_at = 0.0

    def push(self, row: Dict[str, Any]) -> None:
        if not isinstance(row, dict):
            return
        with self._lock:
            self._rows.append(row)
            self._last_recv_at = time.time()
            # Drop oldest to cap memory during bursts.
            if len(self._rows) > self._max_rows:
                self._rows = self._rows[-self._max_rows :]

    def drain(self, max_items: int = 5000) -> List[Dict[str, Any]]:
        n = int(max_items) if max_items and max_items > 0 else 5000
        with self._lock:
            if not self._rows:
                return []
            out = self._rows[:n]
            self._rows = self._rows[n:]
        return out

    def last_recv_age_sec(self) -> Optional[float]:
        with self._lock:
            t = float(self._last_recv_at or 0.0)
        if t <= 0:
            return None
        return max(0.0, time.time() - t)


class _MirrorSourceRtdsWorker:
    """RTDS activity->trades websocket subscriber for near-realtime source trade detection.

    We subscribe only to a small set of event slugs (derived from recent source activity),
    then filter incoming activity trade events by proxyWallet/wallet matching the source.
    """

    def __init__(self, *, source_address: str) -> None:
        self.source_address = _normalize_wallet_address(source_address)
        self._stop = threading.Event()
        self._thread: Optional[threading.Thread] = None
        self._buffer = _MirrorSourceRtdsBuffer()
        self._connected = False
        self._connected_at = 0.0
        self._last_error = ""
        self._subscribed_slugs: Set[str] = set()

    def start(self) -> None:
        if self._thread and self._thread.is_alive():
            return
        self._stop.clear()
        self._thread = threading.Thread(
            target=self._thread_main,
            name="mirror_source_rtds",
            daemon=True,
        )
        self._thread.start()

    def stop(self) -> None:
        self._stop.set()

    def drain_rows(self, max_items: int = 5000) -> List[Dict[str, Any]]:
        return self._buffer.drain(max_items=max_items)

    def health(self) -> Dict[str, Any]:
        connected_age = None
        try:
            if self._connected and self._connected_at and self._connected_at > 0:
                connected_age = max(0.0, time.time() - float(self._connected_at))
        except Exception:
            connected_age = None
        return {
            "enabled": True,
            "connected": bool(self._connected),
            "connected_age_sec": connected_age,
            "last_error": str(self._last_error or ""),
            "last_recv_age_sec": self._buffer.last_recv_age_sec(),
            "subscribed_slugs": int(len(self._subscribed_slugs)),
        }

    def _compute_target_slugs(self) -> List[str]:
        if not self.source_address:
            return []
        lookback = _env_int("PM_MIRROR_RTD_TARGET_LOOKBACK_SEC")
        if lookback is None or lookback < 0:
            lookback = MIRROR_RTD_TARGET_LOOKBACK_SEC
        lookback = max(0, min(int(lookback), 7 * 86400))
        max_slugs = _env_int("PM_MIRROR_RTD_TARGET_MAX_SLUGS")
        if max_slugs is None or max_slugs < 1:
            max_slugs = MIRROR_RTD_TARGET_MAX_SLUGS
        max_slugs = max(1, min(int(max_slugs), 200))
        now_ts = int(time.time())
        floor_ts = max(0, now_ts - int(lookback))
        slugs: List[str] = []
        try:
            # Use a short read-only connection: RTDS refresh should not contend with writers.
            uri = f"file:{DB_PATH}?mode=ro"
            conn = sqlite3.connect(uri, uri=True, timeout=0.2)
            try:
                try:
                    conn.execute("PRAGMA busy_timeout=200")
                except sqlite3.Error:
                    pass
                cur = conn.cursor()
                cur.execute(
                    """
                    SELECT slug, MAX(source_ts) AS max_ts
                    FROM mirror_follow_trades
                    WHERE source_address = ?
                      AND source_ts IS NOT NULL
                      AND source_ts >= ?
                      AND slug IS NOT NULL
                      AND TRIM(slug) <> ''
                    GROUP BY slug
                    ORDER BY max_ts DESC
                    LIMIT ?
                    """,
                    (self.source_address, int(floor_ts), int(max_slugs)),
                )
                for row in cur.fetchall() or []:
                    slug = str(row[0] or "").strip()
                    if slug:
                        slugs.append(slug)
                # If there were no recent slugs in the lookback window, fall back to the
                # latest known slugs (so we can still receive the next trade instantly).
                if not slugs:
                    cur.execute(
                        """
                        SELECT slug, MAX(source_ts) AS max_ts
                        FROM mirror_follow_trades
                        WHERE source_address = ?
                          AND source_ts IS NOT NULL
                          AND slug IS NOT NULL
                          AND TRIM(slug) <> ''
                        GROUP BY slug
                        ORDER BY max_ts DESC
                        LIMIT ?
                        """,
                        (self.source_address, int(max_slugs)),
                    )
                    for row in cur.fetchall() or []:
                        slug = str(row[0] or "").strip()
                        if slug:
                            slugs.append(slug)
            finally:
                try:
                    conn.close()
                except Exception:
                    pass
        except Exception:
            return []
        return slugs

    async def _send_subscribe(self, ws: Any, slugs: Iterable[str]) -> None:
        subs = []
        for slug in slugs:
            s = str(slug or "").strip()
            if not s:
                continue
            subs.append(
                {
                    "topic": "activity",
                    "type": "trades",
                    "filters": json.dumps({"event_slug": s}, ensure_ascii=True),
                }
            )
        if not subs:
            return
        msg = {"action": "subscribe", "subscriptions": subs}
        await ws.send(json.dumps(msg, ensure_ascii=True))

    async def _send_unsubscribe(self, ws: Any, slugs: Iterable[str]) -> None:
        subs = []
        for slug in slugs:
            s = str(slug or "").strip()
            if not s:
                continue
            subs.append(
                {
                    "topic": "activity",
                    "type": "trades",
                    "filters": json.dumps({"event_slug": s}, ensure_ascii=True),
                }
            )
        if not subs:
            return
        msg = {"action": "unsubscribe", "subscriptions": subs}
        await ws.send(json.dumps(msg, ensure_ascii=True))

    def _row_matches_source(self, trade: Dict[str, Any]) -> bool:
        if not self.source_address:
            return False
        addr = self.source_address
        for key in ("proxyWallet", "wallet", "user", "userAddress", "trader", "owner"):
            val = trade.get(key)
            if not val:
                continue
            if str(val).strip().lower() == addr:
                return True
        return False

    def _ingest_trade(self, trade: Dict[str, Any]) -> None:
        # Keep only the fields our mirror-follow pipeline understands.
        row = {
            "type": str(trade.get("type") or "TRADE"),
            "asset": str(trade.get("asset") or trade.get("tokenId") or trade.get("tokenID") or "").strip(),
            "side": str(trade.get("side") or "").strip().upper(),
            "timestamp": trade.get("timestamp"),
            "price": trade.get("price"),
            "size": trade.get("size") or trade.get("quantity"),
            "transactionHash": str(trade.get("transactionHash") or trade.get("transaction_hash") or "").strip(),
            "proxyWallet": str(trade.get("proxyWallet") or "").strip().lower(),
            "_rtds_received_at": utc_now_iso(),
            "_source": "rtds_activity",
        }
        if not row.get("asset") or row.get("side") not in {"BUY", "SELL"}:
            return
        self._buffer.push(row)

    async def _run_once(self) -> None:
        url = str(os.environ.get("PM_MIRROR_RTD_URL") or MIRROR_RTD_URL).strip() or MIRROR_RTD_URL
        ping_sec = _env_float("PM_MIRROR_RTD_PING_SEC")
        if ping_sec is None or not math.isfinite(ping_sec) or ping_sec <= 0:
            ping_sec = MIRROR_RTD_PING_SEC
        ping_sec = max(1.0, min(float(ping_sec), 60.0))
        refresh_sec = _env_float("PM_MIRROR_RTD_SUB_REFRESH_SEC")
        if refresh_sec is None or not math.isfinite(refresh_sec) or refresh_sec <= 0:
            refresh_sec = MIRROR_RTD_SUB_REFRESH_SEC
        refresh_sec = max(1.0, min(float(refresh_sec), 120.0))

        # Proxy support: if HTTPS_PROXY is set, websockets can use it directly.
        proxy_url = str(os.environ.get("HTTPS_PROXY") or os.environ.get("https_proxy") or "").strip()
        proxy = proxy_url if proxy_url else None
        # In "force proxy" mode, always use proxy; otherwise try direct first then proxy fallback.
        force_proxy = _env_bool("PM_MIRROR_RTD_FORCE_PROXY", _env_bool("PM_CLOB_FORCE_PROXY", False))
        ssl_ctx = None
        try:
            # Use certifi CA bundle because system Python SSL roots may be incomplete under proxies.
            ssl_ctx = ssl.create_default_context(cafile=certifi.where())
        except Exception:
            ssl_ctx = None

        async def _connect(proxy_arg: Optional[str]) -> Any:
            return await websockets.connect(
                url,
                proxy=proxy_arg,
                ssl=ssl_ctx,
                open_timeout=8,
                ping_interval=None,  # RTDS expects text PING messages, not ws ping frames.
                ping_timeout=None,
                close_timeout=2,
                max_size=8 * 1024 * 1024,
                max_queue=512,
            )

        ws = None
        if force_proxy and proxy:
            ws = await _connect(proxy)
        else:
            try:
                ws = await _connect(None)
            except Exception:
                if proxy:
                    ws = await _connect(proxy)
                else:
                    raise

        assert ws is not None
        self._connected = True
        self._connected_at = time.time()
        last_ping = 0.0
        last_refresh = 0.0
        subscribed: Set[str] = set()
        self._subscribed_slugs = set()
        try:
            while not self._stop.is_set():
                now = time.time()
                if now - last_ping >= float(ping_sec):
                    try:
                        await ws.send("PING")
                    except Exception:
                        raise
                    last_ping = now

                if now - last_refresh >= float(refresh_sec):
                    desired = set(self._compute_target_slugs())
                    add = sorted(desired - subscribed)
                    remove = sorted(subscribed - desired)
                    if remove:
                        try:
                            await self._send_unsubscribe(ws, remove)
                        except Exception:
                            # Unsubscribe failures aren't fatal; we can resync on reconnect.
                            pass
                        for s in remove:
                            subscribed.discard(s)
                    if add:
                        await self._send_subscribe(ws, add)
                        for s in add:
                            subscribed.add(s)
                    self._subscribed_slugs = set(subscribed)
                    last_refresh = now

                # Sleep/recv with a short timeout so we can ping/refresh.
                timeout = 0.5
                try:
                    raw = await asyncio.wait_for(ws.recv(), timeout=timeout)
                except asyncio.TimeoutError:
                    continue
                except Exception:
                    raise
                if raw is None:
                    continue
                text = raw.decode("utf-8", errors="ignore") if isinstance(raw, (bytes, bytearray)) else str(raw)
                if text.strip().upper() in {"PONG", "PING"}:
                    continue
                try:
                    msg = json.loads(text)
                except Exception:
                    continue
                if not isinstance(msg, dict):
                    continue
                topic = str(msg.get("topic") or "").strip().lower()
                msg_type = str(msg.get("type") or "").strip().lower()
                if topic != "activity" or msg_type != "trades":
                    continue
                trade = msg.get("data")
                if not isinstance(trade, dict):
                    continue
                if not self._row_matches_source(trade):
                    continue
                self._ingest_trade(trade)
        finally:
            self._connected = False
            self._connected_at = 0.0
            try:
                await ws.close()
            except Exception:
                pass

    async def _run_forever(self) -> None:
        backoff = 1.0
        while not self._stop.is_set():
            self._connected = False
            try:
                await self._run_once()
                backoff = 1.0
                self._last_error = ""
            except Exception as exc:
                self._last_error = str(exc)
                # Exponential backoff capped to avoid tight reconnect loops.
                await asyncio.sleep(min(max(backoff, 0.5), 30.0))
                backoff = min(backoff * 1.7, 30.0)

    def _thread_main(self) -> None:
        try:
            asyncio.run(self._run_forever())
        except Exception as exc:
            self._connected = False
            self._last_error = f"thread_failed:{exc}"


_MIRROR_SOURCE_RTDS: Optional[_MirrorSourceRtdsWorker] = None
_MIRROR_SOURCE_RTDS_LAST_DISCOVERY_AT: float = 0.0


def _ensure_mirror_source_rtds_started(source_address: str) -> Optional[_MirrorSourceRtdsWorker]:
    global _MIRROR_SOURCE_RTDS
    if not _env_bool("PM_MIRROR_RTD_ENABLED", MIRROR_RTD_ENABLED):
        return None
    src = _normalize_wallet_address(source_address)
    if not src:
        return None
    if _MIRROR_SOURCE_RTDS is None or _MIRROR_SOURCE_RTDS.source_address != src:
        _MIRROR_SOURCE_RTDS = _MirrorSourceRtdsWorker(source_address=src)
        _MIRROR_SOURCE_RTDS.start()
        return _MIRROR_SOURCE_RTDS
    _MIRROR_SOURCE_RTDS.start()
    return _MIRROR_SOURCE_RTDS


def _drain_mirror_source_rtds_rows(source_address: str, max_items: int = 5000) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    worker = _ensure_mirror_source_rtds_started(source_address)
    if worker is None:
        return [], {"enabled": False}
    rows = worker.drain_rows(max_items=max_items)
    return rows, worker.health()


def run_mirror_follow_trades(
    run_date: str,
    *,
    retry_cooldown_override_sec: Optional[int] = None,
) -> Dict[str, Any]:
    mirror_enabled = _env_bool("PM_MIRROR_TRADING_ENABLED", MIRROR_TRADING_ENABLED)
    source_addr_runtime = str(os.environ.get("PM_MIRROR_SOURCE_ADDRESS") or MIRROR_SOURCE_ADDRESS).strip().lower()
    result: Dict[str, Any] = {
        "enabled": bool(mirror_enabled),
        "ran": False,
        "source_address": source_addr_runtime,
        "fetched": 0,
        "processed": 0,
        "placed": 0,
        "failed": 0,
        "skipped": 0,
        "retried": 0,
        "errors": [],
    }
    mirror_order_sms_enabled_runtime = _env_bool(
        "PM_MIRROR_ORDER_SMS_ENABLED",
        MIRROR_ORDER_SMS_ENABLED,
    )
    mirror_order_sms_enabled_runtime = bool(
        mirror_order_sms_enabled_runtime
        and SMS_ENABLED
        and SMS_TRADE_NOTIFY_ENABLED
        and bool(SMS_RECIPIENT)
    )
    result["mirror_order_sms_enabled"] = bool(mirror_order_sms_enabled_runtime)
    daily_budget_tz_runtime = _resolve_mirror_daily_budget_tz()
    daily_budget_date_runtime = today_date_str(daily_budget_tz_runtime)
    daily_budget_start_utc, daily_budget_end_utc = _day_bounds_utc_for_tz(
        daily_budget_date_runtime,
        daily_budget_tz_runtime,
    )
    copy_ratio_runtime = _env_float("PM_MIRROR_COPY_RATIO")
    if copy_ratio_runtime is None or not math.isfinite(copy_ratio_runtime) or copy_ratio_runtime <= 0:
        copy_ratio_runtime = MIRROR_COPY_RATIO
    if copy_ratio_runtime is None or not math.isfinite(copy_ratio_runtime) or copy_ratio_runtime <= 0:
        copy_ratio_runtime = 1.0
    # Optional per-outcome-side overrides (keeps "pure mirror" semantics by side).
    # Use <=0 / non-finite to mean "disabled" and fall back to PM_MIRROR_COPY_RATIO.
    copy_ratio_yes_runtime = _env_float("PM_MIRROR_COPY_RATIO_YES")
    if copy_ratio_yes_runtime is None or not math.isfinite(copy_ratio_yes_runtime) or copy_ratio_yes_runtime <= 0:
        copy_ratio_yes_runtime = None
    copy_ratio_no_runtime = _env_float("PM_MIRROR_COPY_RATIO_NO")
    if copy_ratio_no_runtime is None or not math.isfinite(copy_ratio_no_runtime) or copy_ratio_no_runtime <= 0:
        copy_ratio_no_runtime = None
    exchange_min_order_usdc_runtime = _env_float("PM_MIRROR_EXCHANGE_MIN_ORDER_USDC")
    if (
        exchange_min_order_usdc_runtime is None
        or not math.isfinite(exchange_min_order_usdc_runtime)
        or exchange_min_order_usdc_runtime < 0
    ):
        exchange_min_order_usdc_runtime = MIRROR_EXCHANGE_MIN_ORDER_USDC
    exchange_min_order_usdc_runtime = max(0.0, float(exchange_min_order_usdc_runtime))
    min_order_usdc_runtime = _env_float("PM_MIRROR_MIN_ORDER_USDC")
    if min_order_usdc_runtime is None or not math.isfinite(min_order_usdc_runtime) or min_order_usdc_runtime < 0:
        min_order_usdc_runtime = MIRROR_MIN_ORDER_USDC
    min_order_usdc_runtime = max(0.0, float(min_order_usdc_runtime))
    effective_min_order_usdc_runtime = max(float(min_order_usdc_runtime), float(exchange_min_order_usdc_runtime))
    notional_mode_runtime = str(
        os.environ.get("PM_MIRROR_NOTIONAL_MODE") or MIRROR_NOTIONAL_MODE or "source_copy"
    ).strip().lower()
    if notional_mode_runtime not in {"source_copy", "daily_remaining_ratio", "source_size_ratio"}:
        notional_mode_runtime = "source_copy"
    daily_budget_ratio_runtime = _env_float("PM_MIRROR_DAILY_BUDGET_RATIO")
    if (
        daily_budget_ratio_runtime is None
        or not math.isfinite(daily_budget_ratio_runtime)
        or daily_budget_ratio_runtime <= 0
    ):
        daily_budget_ratio_runtime = MIRROR_DAILY_BUDGET_RATIO
    if (
        daily_budget_ratio_runtime is None
        or not math.isfinite(daily_budget_ratio_runtime)
        or daily_budget_ratio_runtime <= 0
    ):
        daily_budget_ratio_runtime = 0.5
    if daily_budget_ratio_runtime > 1:
        daily_budget_ratio_runtime = 1.0
    daily_budget_usdc_runtime = _env_float("PM_MIRROR_DAILY_BUDGET_USDC")
    if (
        daily_budget_usdc_runtime is None
        or not math.isfinite(daily_budget_usdc_runtime)
        or daily_budget_usdc_runtime <= 0
    ):
        daily_budget_usdc_runtime = MIRROR_DAILY_BUDGET_USDC
    if (
        daily_budget_usdc_runtime is not None
        and (not math.isfinite(daily_budget_usdc_runtime) or daily_budget_usdc_runtime <= 0)
    ):
        daily_budget_usdc_runtime = None
    daily_budget_proportional_runtime = _env_bool(
        "PM_MIRROR_DAILY_BUDGET_PROPORTIONAL",
        MIRROR_DAILY_BUDGET_PROPORTIONAL,
    )
    retry_failed_runtime = _env_bool("PM_MIRROR_RETRY_FAILED", MIRROR_RETRY_FAILED_ENABLED)
    retry_max_runtime = _env_int("PM_MIRROR_RETRY_MAX")
    if retry_max_runtime is None or retry_max_runtime < 0:
        retry_max_runtime = MIRROR_RETRY_MAX
    retry_cooldown_runtime = _env_int("PM_MIRROR_RETRY_COOLDOWN_SEC")
    if retry_cooldown_runtime is None or retry_cooldown_runtime < 0:
        retry_cooldown_runtime = MIRROR_RETRY_COOLDOWN_SEC
    if retry_cooldown_override_sec is not None:
        if math.isfinite(float(retry_cooldown_override_sec)):
            retry_cooldown_runtime = max(int(retry_cooldown_override_sec), 0)
    retry_lookback_runtime = _env_int("PM_MIRROR_RETRY_LOOKBACK_SEC")
    if retry_lookback_runtime is None or retry_lookback_runtime < 0:
        retry_lookback_runtime = MIRROR_RETRY_LOOKBACK_SEC
    mirror_price_mode_runtime = str(
        os.environ.get("PM_MIRROR_PRICE_MODE") or MIRROR_PRICE_MODE or "book"
    ).strip().lower()
    if mirror_price_mode_runtime not in {"book", "source"}:
        mirror_price_mode_runtime = MIRROR_PRICE_MODE
    if mirror_price_mode_runtime not in {"book", "source"}:
        mirror_price_mode_runtime = "book"
    skip_book_when_source_price_runtime = _env_bool(
        "PM_MIRROR_SKIP_BOOK_WHEN_SOURCE_PRICE",
        MIRROR_SKIP_BOOK_WHEN_SOURCE_PRICE,
    )
    buy_cap_to_source_runtime = _env_bool(
        "PM_MIRROR_BUY_CAP_TO_SOURCE",
        MIRROR_BUY_CAP_TO_SOURCE,
    )
    buy_cap_source_only_same_outcome_runtime = _env_bool(
        "PM_MIRROR_BUY_CAP_SOURCE_ONLY_SAME_OUTCOME",
        MIRROR_BUY_CAP_SOURCE_ONLY_SAME_OUTCOME,
    )
    buy_chase_enabled_runtime = _env_bool(
        "PM_MIRROR_BUY_CHASE_ENABLED",
        MIRROR_BUY_CHASE_ENABLED,
    )
    buy_guarantee_fill_enabled_runtime = _env_bool(
        "PM_MIRROR_BUY_GUARANTEE_FILL_ENABLED",
        MIRROR_BUY_GUARANTEE_FILL_ENABLED,
    )
    buy_guarantee_max_pay_up_runtime = _env_float("PM_MIRROR_BUY_GUARANTEE_MAX_PAY_UP")
    if buy_guarantee_max_pay_up_runtime is None or not math.isfinite(buy_guarantee_max_pay_up_runtime):
        buy_guarantee_max_pay_up_runtime = MIRROR_BUY_GUARANTEE_MAX_PAY_UP
