TEMPERATURE_MOMENTUM_WINDOWS: Tuple[Tuple[str, float], ...] = (
    ("24h", 24.0),
    ("12h", 12.0),
    ("6h", 6.0),
    ("3h", 3.0),
    ("2h", 2.0),
    ("1h", 1.0),
    ("45m", 45.0 / 60.0),
    ("30m", 30.0 / 60.0),
    ("15m", 15.0 / 60.0),
    ("10m", 10.0 / 60.0),
    ("5m", 5.0 / 60.0),
    ("3m", 3.0 / 60.0),
    ("2m", 2.0 / 60.0),
    ("1m", 1.0 / 60.0),
)
TEMPERATURE_MOMENTUM_WEIGHTS: Dict[str, float] = {
    "1m": 0.12,
    "2m": 0.11,
    "3m": 0.10,
    "5m": 0.09,
    "10m": 0.08,
    "15m": 0.08,
    "30m": 0.07,
    "45m": 0.06,
    "1h": 0.08,
    "2h": 0.06,
    "3h": 0.05,
    "6h": 0.04,
    "12h": 0.03,
    "24h": 0.03,
}
TEMPERATURE_MOMENTUM_EFFECTIVE_WINDOWS: Tuple[str, ...] = ("1h", "45m", "30m")
TEMPERATURE_MOMENTUM_DIAGNOSTIC_ONLY_WINDOWS: Tuple[str, ...] = ("15m", "10m", "5m", "3m", "2m", "1m")
TEMPERATURE_MOMENTUM_EFFECTIVE_WEIGHTS: Dict[str, float] = {
    "1h": 0.48,
    "45m": 0.12,
    "30m": 0.12,
}
TEMPERATURE_MOMENTUM_RECENT_WINDOWS: Tuple[str, ...] = ("30m", "45m", "1h")
TEMPERATURE_MOMENTUM_POSTERIOR_CONFIRM_WINDOWS: Tuple[str, ...] = ("30m", "45m", "1h")
TEMPERATURE_RISE_RATE_PRIMARY_WINDOWS: Tuple[str, ...] = ("1h", "45m", "30m")
TEMPERATURE_RISE_RATE_STABLE_PRIORITY: Tuple[str, ...] = (
    "1h",
    "45m",
    "30m",
    "2h",
    "3h",
    "6h",
    "12h",
    "24h",
)


def _copy_temperature_momentum_to_source_namespace(features: Dict[str, Any], prefix: str) -> None:
    prefix_text = str(prefix or "").strip().rstrip("_")
    if not prefix_text:
        return
    momentum_keys = [
        key
        for key in list(features.keys())
        if str(key).startswith("temperature_momentum_")
        or str(key).startswith("temperature_rise_rate_")
        or str(key).startswith("temperature_trajectory_stable_rate_")
    ]
    for key in momentum_keys:
        value = features.get(key)
        if value not in (None, ""):
            features[f"{prefix_text}_{key}"] = value


def _promote_hard_observation_path_features(features: Dict[str, Any]) -> None:
    if not _env_bool("PM_HARD_OBSERVATION_PATH_PROMOTION_ENABLED", True):
        return
    awc_available = str(features.get("zuuu_metar_raw_awc_available") or "").strip().lower() in {"1", "true", "yes", "on"} or (
        str(features.get("source") or "").strip() == "zuuu_metar_raw_awc"
    )
    awc_date_mismatch = str(features.get("zuuu_metar_raw_awc_date_mismatch") or "").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    if not awc_available or awc_date_mismatch:
        return

    latest_temp = to_float(features.get("zuuu_metar_raw_awc_latest_temp_c"))
    if latest_temp is None:
        latest_temp = to_float(features.get("metar_temperature_c"))
    if latest_temp is not None and math.isfinite(float(latest_temp)):
        previous_temp = to_float(features.get("observed_temp_c"))
        previous_source = str(features.get("observed_temp_source") or "")
        if previous_temp is not None and previous_source and previous_source != "zuuu_metar_raw_awc":
            features["observed_temp_preserved_c"] = float(previous_temp)
            features["observed_temp_preserved_source"] = previous_source
        features["observed_temp"] = float(latest_temp)
        features["observed_temp_c"] = float(latest_temp)
        features["observed_temp_source"] = "zuuu_metar_raw_awc"
        features["metar_temperature_c"] = float(latest_temp)

    today_max = to_float(features.get("zuuu_metar_raw_awc_today_max_c"))
    if today_max is not None and math.isfinite(float(today_max)):
        previous_max = to_float(features.get("observed_today_max_c"))
        previous_source = str(features.get("observed_today_max_source") or "")
        if previous_max is not None and previous_source and previous_source != "zuuu_metar_raw_awc":
            features["observed_today_max_preserved_c"] = float(previous_max)
            features["observed_today_max_preserved_source"] = previous_source
        features["observed_today_max_c"] = float(today_max)
        features["observed_today_max_source"] = "zuuu_metar_raw_awc"
        features["observed_today_max_trusted"] = True

    for key in list(features.keys()):
        text = str(key)
        prefix = "zuuu_metar_raw_awc_temperature_"
        if text.startswith(prefix):
            generic_key = "temperature_" + text[len(prefix):]
            value = features.get(text)
            if value not in (None, ""):
                previous = features.get(generic_key)
                if previous not in (None, "") and previous != value:
                    features[f"{generic_key}_preserved_before_hard_source"] = previous
                features[generic_key] = value

    stable_rate = to_float(features.get("zuuu_metar_raw_awc_temperature_trajectory_stable_rate_c_per_hour"))
    stable_source = str(features.get("zuuu_metar_raw_awc_temperature_trajectory_stable_rate_source") or "")
    stable_window = str(features.get("zuuu_metar_raw_awc_temperature_trajectory_stable_rate_window") or "")
    stable_window_key = stable_window.strip()
    if (
        stable_rate is not None
        and math.isfinite(float(stable_rate))
        and stable_window_key in TEMPERATURE_RISE_RATE_PRIMARY_WINDOWS
    ):
        features["temperature_rise_rate_c_per_hour"] = float(stable_rate)
        features["temperature_rise_rate_source"] = stable_source or "zuuu_metar_raw_awc:stable_window"
        features["temperature_rise_rate_window"] = stable_window_key
    elif stable_rate is not None and math.isfinite(float(stable_rate)):
        features["temperature_rise_rate_short_window_suppressed_c_per_hour"] = float(stable_rate)
        features["temperature_rise_rate_short_window_suppressed_window"] = stable_window_key
        features["temperature_rise_rate_na_reason"] = "primary_stable_window_missing"

    if any(str(key).startswith("zuuu_metar_raw_awc_temperature_momentum_") for key in features):
        features["temperature_momentum_source"] = "zuuu_metar_raw_awc"
        features["observation_path_primary_source"] = "zuuu_metar_raw_awc"
        features["observation_path_primary_reason"] = "hard_metar_observation_promoted_over_soft_intraday_sources"


def _temperature_momentum_posterior_gate(
    rates: Mapping[str, float],
    *,
    state: str,
    effective: Optional[float],
) -> Dict[str, Any]:
    one_hour_threshold = _env_float("PM_TEMPERATURE_MOMENTUM_ONE_HOUR_POSTERIOR_GATE_MIN_C_PER_HOUR")
    if one_hour_threshold is None or not math.isfinite(float(one_hour_threshold)):
        one_hour_threshold = 0.75
    one_hour_core = to_float(rates.get("1h"))
    confirmed_positive = [
        label
        for label in TEMPERATURE_MOMENTUM_POSTERIOR_CONFIRM_WINDOWS
        if to_float(rates.get(label)) is not None and float(rates[label]) >= 0.25
    ]
    one_hour_context_positive = [
        label
        for label in ("2h", "3h", "6h")
        if to_float(rates.get(label)) is not None and float(rates[label]) >= 0.35
    ]
    positive_short = [
        label
        for label in ("10m", "15m")
        if to_float(rates.get(label)) is not None and float(rates[label]) >= 0.35
    ]
    stable_confirmed_allowed = bool(
        effective is not None
        and float(effective) >= 0.20
        and len(confirmed_positive) >= 3
        and str(state or "") not in {"cooling", "not_realized", "flat"}
    )
    one_hour_core_allowed = bool(
        effective is not None
        and float(effective) >= 0.25
        and one_hour_core is not None
        and float(one_hour_core) >= float(one_hour_threshold)
        and bool(one_hour_context_positive)
        and str(state or "") in {"sustained_warming", "emerging_warming", "weak_warming"}
    )
    allowed = bool(
        (
            effective is not None
            and float(effective) >= 0.25
            and len(confirmed_positive) >= 2
            and str(state or "") in {"sustained_warming", "emerging_warming", "weak_warming"}
        )
        or stable_confirmed_allowed
        or one_hour_core_allowed
    )
    if allowed:
        gate_state = "confirmed"
        if stable_confirmed_allowed:
            reason = "stable_multi_window_confirmed"
        elif one_hour_core_allowed:
            reason = "one_hour_context_confirmed"
        else:
            reason = "multi_window_confirmed"
    elif (
        confirmed_positive == ["1h"]
        and one_hour_core is not None
        and float(one_hour_core) >= float(one_hour_threshold)
    ):
        gate_state = "one_hour_watch"
        reason = "one_hour_requires_30m_45m_confirmation"
    elif positive_short and len(confirmed_positive) < 2:
        gate_state = "short_window_watch"
        reason = "short_window_warming_requires_30m_1h_confirmation"
    elif str(state or "") in {"cooling", "not_realized", "flat"}:
        gate_state = "not_warming"
        reason = f"momentum_state_{state}"
    else:
        gate_state = "unconfirmed"
        reason = "multi_window_confirmation_missing"
    return {
        "allowed": allowed,
        "state": gate_state,
        "reason": reason,
        "confirmed_windows": ",".join(confirmed_positive + one_hour_context_positive),
        "confirmed_positive_window_count": len(confirmed_positive + one_hour_context_positive),
        "positive_short_windows": ",".join(positive_short),
        "positive_context_windows": ",".join(one_hour_context_positive),
    }


def _temperature_momentum_from_pairs(
    temp_time_pairs: Sequence[Tuple[datetime, float]],
    *,
    source: str,
    horizons: Sequence[Any] = TEMPERATURE_MOMENTUM_WINDOWS,
) -> Dict[str, Any]:
    pairs: List[Tuple[datetime, float]] = []
    for raw_time, raw_temp in temp_time_pairs:
        if not isinstance(raw_time, datetime):
            continue
        temp = to_float(raw_temp)
        if temp is None or not math.isfinite(temp):
            continue
        t = raw_time.astimezone(timezone.utc) if raw_time.tzinfo else raw_time.replace(tzinfo=timezone.utc)
        pairs.append((t, float(temp)))
    pairs.sort(key=lambda item: item[0])
    if len(pairs) < 2:
        return {}
    latest_time, latest_temp = pairs[-1]
    out: Dict[str, Any] = {
        "temperature_momentum_source": source,
        "temperature_momentum_latest_observation_at": _iso_from_datetime(latest_time),
        "temperature_momentum_sample_count": len(pairs),
    }
    rates: Dict[str, float] = {}
    for raw_horizon in horizons:
        if isinstance(raw_horizon, (tuple, list)) and len(raw_horizon) >= 2:
            label = str(raw_horizon[0])
            horizon_hours = to_float(raw_horizon[1])
        else:
            horizon_hours = to_float(raw_horizon)
            label = f"{int(float(horizon_hours))}h" if horizon_hours is not None and float(horizon_hours).is_integer() else str(raw_horizon)
        if horizon_hours is None:
            continue
        if horizon_hours <= 0:
            continue
        target = latest_time - timedelta(hours=float(horizon_hours))
        candidates: List[Tuple[float, datetime, float]] = []
        for prior_time, prior_temp in pairs[:-1]:
            elapsed_h = (latest_time - prior_time).total_seconds() / 3600.0
            if elapsed_h <= 0:
                continue
            if horizon_hours < 1.0:
                tolerance_h = max(5.0 / 60.0, float(horizon_hours) * 0.20)
                min_elapsed_h = max(1.0 / 60.0, float(horizon_hours) - tolerance_h)
                max_elapsed_h = float(horizon_hours) + tolerance_h
            else:
                min_elapsed_h = max(30.0 / 3600.0, float(horizon_hours) * 0.65)
                max_elapsed_h = max(float(horizon_hours) + 0.75, float(horizon_hours) * 1.5)
            if elapsed_h >= min_elapsed_h and elapsed_h <= max_elapsed_h:
                candidates.append((abs(elapsed_h - float(horizon_hours)), prior_time, prior_temp))
        if not candidates:
            continue
        _, prior_time, prior_temp = min(candidates, key=lambda item: item[0])
        actual_h = max(1e-6, (latest_time - prior_time).total_seconds() / 3600.0)
        delta_c = float(latest_temp) - float(prior_temp)
        rate = float(delta_c) / float(actual_h)
        rates[str(label)] = rate
        out[f"temperature_momentum_{label}_c_per_hour"] = rate
        out[f"temperature_momentum_{label}_delta_c"] = float(delta_c)
        out[f"temperature_momentum_{label}_actual_hours"] = float(actual_h)
        out[f"temperature_momentum_{label}_requested_hours"] = float(horizon_hours)
        out[f"temperature_momentum_{label}_window_quality"] = (
            "exact_or_near_requested_window"
            if abs(float(actual_h) - float(horizon_hours)) <= max(5.0 / 60.0, float(horizon_hours) * 0.20)
            else "nearest_available_observation_window"
        )
    if not rates:
        return out
    available_horizons = ",".join(label for label, _hours in TEMPERATURE_MOMENTUM_WINDOWS if label in rates)
    stable_rates = {
        label: rates[label]
        for label in TEMPERATURE_MOMENTUM_EFFECTIVE_WINDOWS
        if label in rates
    }
    diagnostic_only = [label for label in TEMPERATURE_MOMENTUM_DIAGNOSTIC_ONLY_WINDOWS if label in rates]
    if diagnostic_only:
        out["temperature_momentum_diagnostic_only_windows"] = ",".join(diagnostic_only)
        out["temperature_momentum_diagnostic_only_reason"] = "sub_30m_windows_not_used_for_live_momentum"
    for label in TEMPERATURE_RISE_RATE_PRIMARY_WINDOWS:
        if label in rates:
            out["temperature_trajectory_stable_rate_c_per_hour"] = float(rates[label])
            out["temperature_trajectory_stable_rate_window"] = label
            out["temperature_trajectory_stable_rate_source"] = f"{source}:{label}"
            break
    if not stable_rates:
        out["temperature_momentum_realization_state"] = "short_window_only"
        out["temperature_momentum_sustained_warming"] = False
        out["temperature_momentum_available_horizons"] = available_horizons
        out["temperature_momentum_effective_na_reason"] = "stable_window_missing"
        out["temperature_momentum_posterior_gate_allowed"] = False
        out["temperature_momentum_posterior_gate_state"] = "diagnostic_only"
        out["temperature_momentum_posterior_gate_reason"] = (
            "sub_30m_windows_not_used_for_live_momentum" if diagnostic_only else "stable_window_missing"
        )
        out["temperature_momentum_posterior_confirmed_windows"] = ""
        out["temperature_momentum_posterior_confirmed_window_count"] = 0
        return out
    denom = sum(TEMPERATURE_MOMENTUM_EFFECTIVE_WEIGHTS.get(label, 0.0) for label in stable_rates) or float(len(stable_rates))
    effective = (
        sum(float(rate) * TEMPERATURE_MOMENTUM_EFFECTIVE_WEIGHTS.get(label, 1.0) for label, rate in stable_rates.items())
        / max(1e-6, denom)
    )
    recent = [stable_rates[label] for label in TEMPERATURE_MOMENTUM_RECENT_WINDOWS if label in stable_rates]
    short = sum(recent) / float(len(recent)) if recent else stable_rates.get("1h")
    positive_count = sum(1 for val in stable_rates.values() if val >= 0.25)
    nonpositive_count = sum(1 for val in stable_rates.values() if val <= 0.0)
    confirmed_positive_count = sum(
        1
        for label in TEMPERATURE_MOMENTUM_POSTERIOR_CONFIRM_WINDOWS
        if label in stable_rates and stable_rates[label] >= 0.25
    )
    if short is not None and short <= -0.20 and effective <= 0.0:
        state = "cooling"
    elif short is not None and short <= 0.0 and effective <= 0.10:
        state = "not_realized"
    elif (
        short is not None
        and short >= 0.35
        and positive_count >= 2
        and confirmed_positive_count >= 2
        and effective >= 0.25
    ):
        state = "sustained_warming"
    elif short is not None and short >= 0.35 and effective >= 0.10:
        state = "emerging_warming"
    elif effective >= 0.15 and nonpositive_count == 0:
        state = "weak_warming"
    elif abs(effective) < 0.15:
        state = "flat"
    else:
        state = "mixed"
    gate = _temperature_momentum_posterior_gate(rates, state=state, effective=float(effective))
    out["temperature_momentum_effective_c_per_hour"] = float(effective)
    out["temperature_momentum_effective_windows"] = ",".join(label for label in TEMPERATURE_MOMENTUM_EFFECTIVE_WINDOWS if label in stable_rates)
    out["temperature_momentum_realization_state"] = state
    out["temperature_momentum_sustained_warming"] = bool(state == "sustained_warming")
    out["temperature_momentum_posterior_gate_allowed"] = bool(gate["allowed"])
    out["temperature_momentum_posterior_gate_state"] = str(gate["state"])
    out["temperature_momentum_posterior_gate_reason"] = str(gate["reason"])
    out["temperature_momentum_posterior_confirmed_windows"] = str(gate["confirmed_windows"])
    out["temperature_momentum_posterior_confirmed_window_count"] = int(gate["confirmed_positive_window_count"])
    out["temperature_momentum_positive_short_windows"] = str(gate["positive_short_windows"])
    if gate["allowed"]:
        out["temperature_momentum_posterior_effective_c_per_hour"] = float(effective)
    out["temperature_momentum_available_horizons"] = available_horizons
    return out


def _apply_temperature_trajectory_rates(
    features: Dict[str, Any],
    temp_time_pairs: Sequence[Tuple[datetime, float]],
    *,
    source: str,
) -> None:
    pairs: List[Tuple[datetime, float]] = []
    for raw_time, raw_temp in temp_time_pairs:
        if not isinstance(raw_time, datetime):
            continue
        temp = to_float(raw_temp)
        if temp is None or not math.isfinite(temp):
            continue
        t = raw_time.astimezone(timezone.utc) if raw_time.tzinfo else raw_time.replace(tzinfo=timezone.utc)
        pairs.append((t, float(temp)))
    pairs.sort(key=lambda item: item[0])
    if len(pairs) < 2:
        return
    t0, v0 = pairs[-2]
    t1, v1 = pairs[-1]
    hours_delta = max(1e-6, (t1 - t0).total_seconds() / 3600.0)
    raw_pair_rate = float((v1 - v0) / hours_delta)
    features["temperature_rise_rate_raw_pair_c_per_hour"] = raw_pair_rate
    features["temperature_rise_rate_raw_pair_actual_hours"] = float(hours_delta)
    features["temperature_rise_rate_raw_pair_source"] = f"{source}:last_two_points"
    momentum = _temperature_momentum_from_pairs(pairs, source=source)
    features.update(momentum)
    stable_rate = to_float(momentum.get("temperature_trajectory_stable_rate_c_per_hour"))
    if stable_rate is not None and math.isfinite(float(stable_rate)):
        features["temperature_rise_rate_c_per_hour"] = float(stable_rate)
        features["temperature_rise_rate_source"] = str(
            momentum.get("temperature_trajectory_stable_rate_source") or f"{source}:stable_window"
        )
        features["temperature_rise_rate_window"] = str(
            momentum.get("temperature_trajectory_stable_rate_window") or ""
        )
        return
    if hours_delta >= 0.5:
        features["temperature_rise_rate_c_per_hour"] = raw_pair_rate
        features["temperature_rise_rate_source"] = f"{source}:last_pair_stable_elapsed"
        features["temperature_rise_rate_window"] = "last_pair"
        return
    features["temperature_rise_rate_na_reason"] = "stable_window_missing"


def _metar_cross_check_timeout() -> Tuple[float, float]:
    raw = _env_float("PM_METAR_CROSS_CHECK_TIMEOUT_SEC")
    if raw is None or not math.isfinite(float(raw)) or float(raw) <= 0:
        raw = min(3.0, float(BAYES_LIKELIHOOD_AUX_TIMEOUT_SEC))
    total = max(0.75, min(8.0, float(raw)))
    return max(0.4, min(1.5, total * 0.5)), total


def _metar_cross_check_retry_count() -> int:
    raw = _env_int("PM_METAR_CROSS_CHECK_RETRIES")
    if raw is None or raw < 1:
        raw = 1
    return max(1, min(int(raw), 2))


def _metar_cross_check_features_from_observations(
    *,
    prefix: str,
    provider: str,
    station: str,
    observations: Sequence[Mapping[str, Any]],
    source_url: str,
    fetched_at: datetime,
    target_event_date: Optional[str],
    tz: Optional[str],
    realtime: bool,
    requires_token: bool = False,
    error: str = "",
) -> Dict[str, Any]:
    features: Dict[str, Any] = {
        f"{prefix}_provider": provider,
        f"{prefix}_station_id": station,
        f"{prefix}_source_url": source_url,
        f"{prefix}_fetched_at": fetched_at.isoformat(),
        f"{prefix}_realtime_enabled": bool(realtime),
        f"{prefix}_usable_for_final_settlement": False,
        f"{prefix}_requires_token": bool(requires_token),
    }
    if error:
        features[f"{prefix}_available"] = False
        features[f"{prefix}_error"] = error
        return features
    rows: List[Dict[str, Any]] = []
    for obs in observations:
        if not isinstance(obs, Mapping):
            continue
        obs_time = obs.get("observation_time")
        obs_dt = obs_time if isinstance(obs_time, datetime) else _parse_metar_time(obs_time)
        raw = str(obs.get("raw") or obs.get("rawOb") or obs.get("raw_text") or obs.get("raw_text_report") or "")
        temp_c = to_float(
            obs.get("temperature_c")
            if obs.get("temperature_c") is not None
            else obs.get("temp_c")
        )
        if temp_c is None and isinstance(obs.get("temperature"), Mapping):
            temp_c = to_float((obs.get("temperature") or {}).get("value"))
        if temp_c is None:
            temp_c = to_float(obs.get("tmpc") if obs.get("tmpc") is not None else obs.get("temp"))
        dew_c = to_float(
            obs.get("dewpoint_c")
            if obs.get("dewpoint_c") is not None
            else obs.get("dwpc")
        )
        if dew_c is None and isinstance(obs.get("dewpoint"), Mapping):
            dew_c = to_float((obs.get("dewpoint") or {}).get("value"))
        if obs_dt is None and raw:
            parsed = _parse_awc_raw_metar_line(raw, fetched_at)
            obs_dt = parsed.get("observation_time") if isinstance(parsed.get("observation_time"), datetime) else None
            if temp_c is None:
                temp_c = to_float(parsed.get("temperature_c"))
            if dew_c is None:
                dew_c = to_float(parsed.get("dewpoint_c"))
        if obs_dt is None or temp_c is None or not math.isfinite(float(temp_c)):
            continue
        rows.append(
            {
                "observation_time": obs_dt.astimezone(timezone.utc) if obs_dt.tzinfo else obs_dt.replace(tzinfo=timezone.utc),
                "temperature_c": float(temp_c),
                "dewpoint_c": float(dew_c) if dew_c is not None and math.isfinite(float(dew_c)) else None,
                "raw": raw,
            }
        )
    rows.sort(key=lambda item: item["observation_time"])
    features[f"{prefix}_rows"] = len(rows)
    features[f"{prefix}_available"] = bool(rows)
    if not rows:
        features[f"{prefix}_error"] = "observations_missing"
        return features
    latest = rows[-1]
    features[f"{prefix}_latest_at"] = _iso_from_datetime(latest["observation_time"])
    features[f"{prefix}_latest_temp_c"] = float(latest["temperature_c"])
    if latest.get("dewpoint_c") is not None:
        features[f"{prefix}_latest_dewpoint_c"] = float(latest["dewpoint_c"])
    if latest.get("raw"):
        features[f"{prefix}_latest_raw"] = str(latest.get("raw") or "")
    local_zone = None
    if tz and ZoneInfo is not None:
        try:
            local_zone = ZoneInfo(str(tz))
        except Exception:
            local_zone = None
    target_key = _normalize_date_key(str(target_event_date or ""))
    if target_key:
        features[f"{prefix}_target_event_date"] = target_key
    latest_local = (
        latest["observation_time"].astimezone(local_zone)
        if local_zone is not None
        else latest["observation_time"].astimezone(timezone.utc)
    )
    features[f"{prefix}_observation_local_date"] = latest_local.date().isoformat()
    if target_key and latest_local.date().isoformat() != target_key:
        features[f"{prefix}_date_mismatch"] = True
        features[f"{prefix}_date_mismatch_reason"] = "latest_metar_local_date_not_target_event_date"
    same_day_pairs: List[Tuple[datetime, float]] = []
    for row in rows:
        row_local = (
            row["observation_time"].astimezone(local_zone)
            if local_zone is not None
            else row["observation_time"].astimezone(timezone.utc)
        )
        if target_key and row_local.date().isoformat() != target_key:
            continue
        if not target_key and row_local.date() != latest_local.date():
            continue
        same_day_pairs.append((row["observation_time"], float(row["temperature_c"])))
    if same_day_pairs:
        max_time, max_temp = max(same_day_pairs, key=lambda item: (item[1], item[0]))
        features[f"{prefix}_today_max_c"] = float(max_temp)
        features[f"{prefix}_today_max_at"] = _iso_from_datetime(max_time)
        features[f"{prefix}_today_sample_count"] = len(same_day_pairs)
    return features


def _fetch_iem_noaaport_metar_cross_check_features(
    station: str,
    *,
    target_event_date: Optional[str],
    tz: Optional[str],
    hours: int,
) -> Dict[str, Any]:
    target_key = _normalize_date_key(str(target_event_date or ""))
    now_utc = datetime.now(timezone.utc)
    if target_key:
        try:
            start_date = datetime.fromisoformat(target_key).date()
        except Exception:
            start_date = now_utc.date()
    else:
        start_date = now_utc.date()
    end_date = start_date + timedelta(days=1)
    params = {
        "station": station,
        "data": ["tmpc", "dwpc", "metar"],
        "year1": start_date.year,
        "month1": start_date.month,
        "day1": start_date.day,
        "year2": end_date.year,
        "month2": end_date.month,
        "day2": end_date.day,
        "tz": "Etc/UTC",
        "format": "onlycomma",
        "latlon": "no",
        "elev": "no",
        "missing": "empty",
        "trace": "null",
        "direct": "no",
        "report_type": ["1", "2"],
    }
    fetched_at = datetime.now(timezone.utc)
    try:
        resp = requests_get(
            IEM_ASOS_ARCHIVE_URL,
            params=params,
            timeout=_metar_cross_check_timeout(),
            retries=_metar_cross_check_retry_count(),
            backoff=0.25,
            bypass_proxy=True,
        )
        resp.raise_for_status()
    except Exception as exc:
        return _metar_cross_check_features_from_observations(
            prefix="zuuu_metar_iem_noaaport",
            provider="IEM ASOS/METAR NOAAPort archive",
            station=station,
            observations=[],
            source_url=IEM_ASOS_ARCHIVE_URL,
            fetched_at=fetched_at,
            target_event_date=target_event_date,
            tz=tz,
            realtime=True,
            error=f"request_error:{exc.__class__.__name__}",
        )
    fetched_at = datetime.now(timezone.utc)
    rows: List[Dict[str, Any]] = []
    try:
        reader = csv.DictReader((getattr(resp, "text", "") or "").splitlines())
        for row in reader:
            valid = _parse_metar_time(row.get("valid"))
            temp_c = to_float(row.get("tmpc"))
            dew_c = to_float(row.get("dwpc"))
            raw = str(row.get("metar") or "")
            if valid is None and raw:
                parsed = _parse_awc_raw_metar_line(raw, fetched_at)
                valid = parsed.get("observation_time") if isinstance(parsed.get("observation_time"), datetime) else None
                if temp_c is None:
                    temp_c = to_float(parsed.get("temperature_c"))
                if dew_c is None:
                    dew_c = to_float(parsed.get("dewpoint_c"))
            if valid is None or temp_c is None:
                continue
            rows.append({"observation_time": valid, "temperature_c": float(temp_c), "dewpoint_c": dew_c, "raw": raw})
    except Exception as exc:
        return _metar_cross_check_features_from_observations(
            prefix="zuuu_metar_iem_noaaport",
            provider="IEM ASOS/METAR NOAAPort archive",
            station=station,
            observations=[],
            source_url=getattr(resp, "url", "") or IEM_ASOS_ARCHIVE_URL,
            fetched_at=fetched_at,
            target_event_date=target_event_date,
            tz=tz,
            realtime=True,
            error=f"parse_error:{exc.__class__.__name__}",
        )
    return _metar_cross_check_features_from_observations(
        prefix="zuuu_metar_iem_noaaport",
        provider="IEM ASOS/METAR NOAAPort archive",
        station=station,
        observations=rows,
        source_url=getattr(resp, "url", "") or IEM_ASOS_ARCHIVE_URL,
        fetched_at=fetched_at,
        target_event_date=target_event_date,
        tz=tz,
        realtime=True,
    )


def _fetch_avwx_metar_cross_check_features(station: str, *, target_event_date: Optional[str], tz: Optional[str]) -> Dict[str, Any]:
    token = str(os.environ.get("PM_AVWX_API_TOKEN") or os.environ.get("AVWX_TOKEN") or "").strip()
    url = AVWX_METAR_URL_TEMPLATE.format(station=quote(station, safe=""))
    fetched_at = datetime.now(timezone.utc)
    if not token:
        return _metar_cross_check_features_from_observations(
            prefix="zuuu_metar_avwx",
            provider="AVWX REST",
            station=station,
            observations=[],
            source_url=url,
            fetched_at=fetched_at,
            target_event_date=target_event_date,
            tz=tz,
            realtime=True,
            requires_token=True,
            error="token_missing",
        )
    try:
        resp = requests_get(
            url,
            headers={"Authorization": f"Bearer {token}", "Accept": "application/json"},
            params={"format": "json"},
            timeout=_metar_cross_check_timeout(),
            retries=_metar_cross_check_retry_count(),
            backoff=0.25,
            bypass_proxy=True,
        )
        resp.raise_for_status()
        data = resp.json()
    except Exception as exc:
        return _metar_cross_check_features_from_observations(
            prefix="zuuu_metar_avwx",
            provider="AVWX REST",
            station=station,
            observations=[],
            source_url=url,
            fetched_at=fetched_at,
            target_event_date=target_event_date,
            tz=tz,
            realtime=True,
            requires_token=True,
            error=f"request_error:{exc.__class__.__name__}",
        )
    obs = {
        "observation_time": ((data.get("time") or {}).get("dt") if isinstance(data.get("time"), Mapping) else data.get("time")),
        "temperature_c": ((data.get("temperature") or {}).get("value") if isinstance(data.get("temperature"), Mapping) else data.get("temperature")),
        "dewpoint_c": ((data.get("dewpoint") or {}).get("value") if isinstance(data.get("dewpoint"), Mapping) else data.get("dewpoint")),
        "raw": data.get("raw"),
    }
    return _metar_cross_check_features_from_observations(
        prefix="zuuu_metar_avwx",
        provider="AVWX REST",
        station=station,
        observations=[obs],
        source_url=getattr(resp, "url", "") or url,
        fetched_at=datetime.now(timezone.utc),
        target_event_date=target_event_date,
        tz=tz,
        realtime=True,
        requires_token=True,
    )


def _fetch_checkwx_metar_cross_check_features(station: str, *, target_event_date: Optional[str], tz: Optional[str]) -> Dict[str, Any]:
    token = str(os.environ.get("PM_CHECKWX_API_KEY") or os.environ.get("CHECKWX_API_KEY") or "").strip()
    url = CHECKWX_METAR_DECODED_URL_TEMPLATE.format(station=quote(station, safe=""))
    fetched_at = datetime.now(timezone.utc)
    if not token:
        return _metar_cross_check_features_from_observations(
            prefix="zuuu_metar_checkwx",
            provider="CheckWX",
            station=station,
            observations=[],
            source_url=url,
            fetched_at=fetched_at,
            target_event_date=target_event_date,
            tz=tz,
            realtime=True,
            requires_token=True,
            error="token_missing",
        )
    try:
        resp = requests_get(
            url,
            headers={"X-API-Key": token, "Accept": "application/json"},
            timeout=_metar_cross_check_timeout(),
            retries=_metar_cross_check_retry_count(),
            backoff=0.25,
            bypass_proxy=True,
        )
        resp.raise_for_status()
        data = resp.json()
    except Exception as exc:
        return _metar_cross_check_features_from_observations(
            prefix="zuuu_metar_checkwx",
            provider="CheckWX",
            station=station,
            observations=[],
            source_url=url,
            fetched_at=fetched_at,
            target_event_date=target_event_date,
            tz=tz,
            realtime=True,
            requires_token=True,
            error=f"request_error:{exc.__class__.__name__}",
        )
    rows = data.get("data") if isinstance(data, Mapping) else []
    if isinstance(rows, Mapping):
        rows = [rows]
    obs_rows: List[Dict[str, Any]] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, Mapping):
            continue
        temperature = row.get("temperature") if isinstance(row.get("temperature"), Mapping) else {}
        dewpoint = row.get("dewpoint") if isinstance(row.get("dewpoint"), Mapping) else {}
        obs_rows.append(
            {
                "observation_time": row.get("observed") or row.get("timestamp"),
                "temperature_c": temperature.get("celsius") if isinstance(temperature, Mapping) else None,
                "dewpoint_c": dewpoint.get("celsius") if isinstance(dewpoint, Mapping) else None,
                "raw": row.get("raw_text") or row.get("raw"),
            }
        )
    return _metar_cross_check_features_from_observations(
        prefix="zuuu_metar_checkwx",
        provider="CheckWX",
        station=station,
        observations=obs_rows,
        source_url=getattr(resp, "url", "") or url,
        fetched_at=datetime.now(timezone.utc),
        target_event_date=target_event_date,
        tz=tz,
        realtime=True,
        requires_token=True,
    )


def _build_metar_cross_check_summary(features: Mapping[str, Any]) -> Dict[str, Any]:
    prefixes = ("zuuu_metar_iem_noaaport", "zuuu_metar_avwx", "zuuu_metar_checkwx")
    awc_latest = to_float(features.get("zuuu_metar_raw_awc_latest_temp_c"))
    awc_max = to_float(features.get("zuuu_metar_raw_awc_today_max_c"))
    sources: List[Dict[str, Any]] = []
    aligned = 0
    available = 0
    max_delta_abs = 0.0
    for prefix in prefixes:
        is_available = bool(features.get(f"{prefix}_available"))
        latest = to_float(features.get(f"{prefix}_latest_temp_c"))
        today_max = to_float(features.get(f"{prefix}_today_max_c"))
        compare_val = today_max if today_max is not None else latest
        ref_val = awc_max if today_max is not None else awc_latest
        delta = None
        if compare_val is not None and ref_val is not None:
            delta = float(compare_val) - float(ref_val)
            max_delta_abs = max(max_delta_abs, abs(delta))
        status = "available"
        if not is_available:
            status = str(features.get(f"{prefix}_error") or "missing")
        elif delta is not None and abs(delta) <= 0.6:
            status = "aligned"
            aligned += 1
        elif delta is not None:
            status = "temperature_mismatch"
        available += 1 if is_available else 0
        sources.append(
            {
                "key": prefix,
                "provider": features.get(f"{prefix}_provider"),
                "available": bool(is_available),
                "status": status,
                "latest_at": features.get(f"{prefix}_latest_at"),
                "latest_temp_c": latest,
                "today_max_c": today_max,
                "delta_vs_awc_c": delta,
                "requires_token": bool(features.get(f"{prefix}_requires_token")),
                "error": features.get(f"{prefix}_error"),
                "source_url": features.get(f"{prefix}_source_url"),
            }
        )
    return {
        "available_count": int(available),
        "aligned_count": int(aligned),
        "source_count": len(prefixes),
        "status": (
            "aligned"
            if available and aligned == available
            else ("mismatch" if max_delta_abs > 0.6 else ("partial" if available else "missing"))
        ),
        "max_abs_delta_vs_awc_c": float(max_delta_abs),
        "sources": sources,
        "primary_source": "zuuu_metar_raw_awc",
    }


def fetch_zuuu_metar_cross_check_features(
    station_id: Optional[str],
    *,
    target_event_date: Optional[str],
    tz: Optional[str],
    hours: int = 48,
) -> Dict[str, Any]:
    station = _normalize_station_code(station_id)
    if station != "ZUUU" or not _env_bool("PM_METAR_CROSS_CHECK_ENABLED", True):
        return {}
    features: Dict[str, Any] = {}
    if _env_bool("PM_METAR_CROSS_CHECK_IEM_ENABLED", True):
        features.update(
            _fetch_iem_noaaport_metar_cross_check_features(
                station,
                target_event_date=target_event_date,
                tz=tz,
                hours=hours,
            )
        )
    if _env_bool("PM_METAR_CROSS_CHECK_AVWX_ENABLED", True):
        features.update(_fetch_avwx_metar_cross_check_features(station, target_event_date=target_event_date, tz=tz))
    if _env_bool("PM_METAR_CROSS_CHECK_CHECKWX_ENABLED", True):
        features.update(_fetch_checkwx_metar_cross_check_features(station, target_event_date=target_event_date, tz=tz))
    if features:
        features["metar_cross_check_summary"] = _build_metar_cross_check_summary(features)
        features["metar_cross_check_sources"] = features["metar_cross_check_summary"].get("sources")
    return features


def fetch_zuuu_metar_raw_awc_features(
    station_id: Optional[str],
    *,
    hours: int = 48,
    tz: Optional[str] = None,
    target_event_date: Optional[str] = None,
    market_unit: Optional[str] = "C",
    observed_nowcast_value: Optional[float] = None,
    observed_nowcast_source: Optional[str] = None,
    wu_history_metrics: Optional[Mapping[str, Any]] = None,
    provenance: Optional[Dict[str, Any]] = None,
    include_cross_checks: bool = True,
) -> Dict[str, Any]:
    station = _normalize_station_code(station_id)
    if station != "ZUUU":
        return {}
    metar_cross_check_features: Dict[str, Any] = {}
    metar_cross_check_error = ""
    if include_cross_checks:
        try:
            metar_cross_check_features = fetch_zuuu_metar_cross_check_features(
                station,
                target_event_date=target_event_date,
                tz=tz,
                hours=hours,
            )
        except Exception as exc:
            metar_cross_check_error = f"{exc.__class__.__name__}"
    params = {
        "ids": station,
        "format": "raw",
        "taf": "false",
        "hours": max(1, int(hours)),
    }
    request_timeout = _awc_metar_request_timeout()
    request_retries = _awc_metar_request_retries()
    force_proxy = _aviationweather_force_proxy()
    request_started_at = datetime.now(timezone.utc)
    request_start_ts = time.time()
    response = requests_get(
        AVIATIONWEATHER_METAR_URL,
        params=params,
        bypass_proxy=not force_proxy,
        force_proxy=force_proxy,
        retries=request_retries,
        backoff=0.25,
        timeout=request_timeout,
        verify=False if _should_allow_insecure_ssl() else None,
    )
    request_completed_at = datetime.now(timezone.utc)
    request_duration_ms = int((time.time() - request_start_ts) * 1000)
    if provenance is not None:
        provenance["response_url"] = response.url
        provenance["status_code"] = response.status_code
        provenance["response_date"] = response.headers.get("Date") or ""
        provenance["request_started_at"] = request_started_at.isoformat()
        provenance["request_completed_at"] = request_completed_at.isoformat()
        provenance["request_duration_ms"] = request_duration_ms
        provenance["request_timeout"] = list(request_timeout)
        provenance["request_retries"] = int(request_retries)
        provenance["force_proxy"] = bool(force_proxy)
    response.raise_for_status()
    response_date = _parse_metar_time(response.headers.get("Date")) or datetime.now(timezone.utc)
    parsed_rows: List[Dict[str, Any]] = []
    for line in (getattr(response, "text", "") or "").splitlines():
        row = _parse_awc_raw_metar_line(line, response_date)
        if row and row.get("station_id") == station:
            parsed_rows.append(row)
    parsed_rows.sort(key=lambda row: row.get("observation_time") or datetime.min.replace(tzinfo=timezone.utc))
    if not parsed_rows:
        return {}
    latest = parsed_rows[-1]
    latest_time = latest.get("observation_time")
    latest_time_dt = latest_time if isinstance(latest_time, datetime) else None
    latest_temp_c = to_float(latest.get("temperature_c"))
    latest_dewpoint_c = to_float(latest.get("dewpoint_c"))
    latest_pressure_hpa = to_float(latest.get("pressure_hpa"))
    previous_wind_row: Optional[Mapping[str, Any]] = None
    previous_dewpoint_row: Optional[Mapping[str, Any]] = None
    previous_pressure_row: Optional[Mapping[str, Any]] = None
    for row in reversed(parsed_rows[:-1]):
        if any(row.get(key) not in (None, "") for key in ("wind_speed_mps", "wind_dir_deg", "wind_dir_text")):
            previous_wind_row = row
            break
    for row in reversed(parsed_rows[:-1]):
        if to_float(row.get("dewpoint_c")) is not None:
            previous_dewpoint_row = row
            break
    for row in reversed(parsed_rows[:-1]):
        if to_float(row.get("pressure_hpa")) is not None:
            previous_pressure_row = row
            break
    features: Dict[str, Any] = {
        "source": "zuuu_metar_raw_awc",
        "wu_settlement_page": "Wunderground settlement display page",
        "wu_settlement_page_role": "polymarket_settlement_display_page_not_sensor_origin",
        "twc_provider": "Weather.com/TWC",
        "twc_provider_role": "weather_api_provider_wrapper_not_sensor_origin",
        "zuuu_metar_observed": "ZUUU airport METAR observed",
        "zuuu_metar_observed_source": "NOAA AviationWeather Raw METAR",
        "zuuu_metar_observed_role": "hard_realtime_observed_lower_bound",
        "zuuu_metar_archive_iem": "historical_archive_not_realtime",
        "zuuu_metar_archive_iem_role": "historical_metar_archive_verification",
        "zuuu_metar_archive_iem_realtime_enabled": False,
        "zuuu_metar_raw_awc_available": True,
        "zuuu_metar_raw_awc_station_id": station,
        "zuuu_metar_raw_awc_url": response.url,
        "zuuu_metar_raw_awc_response_date": response.headers.get("Date") or "",
        "zuuu_metar_raw_awc_request_started_at": request_started_at.isoformat(),
        "zuuu_metar_raw_awc_fetched_at": request_completed_at.isoformat(),
        "zuuu_metar_raw_awc_fetch_duration_ms": request_duration_ms,
        "zuuu_metar_raw_awc_cross_checks_included": bool(include_cross_checks),
        "zuuu_metar_raw_awc_target_poll_seconds": 1.0,
        "zuuu_metar_raw_awc_rows": len(parsed_rows),
        "zuuu_metar_raw_awc_latest_raw": str(latest.get("raw") or ""),
        "zuuu_metar_raw_awc_latest_at": _iso_from_datetime(latest_time_dt),
    }
    if latest_temp_c is not None and math.isfinite(latest_temp_c):
        features["zuuu_metar_raw_awc_latest_temp_c"] = float(latest_temp_c)
    if latest_dewpoint_c is not None and math.isfinite(latest_dewpoint_c):
        features["zuuu_metar_raw_awc_latest_dewpoint_c"] = float(latest_dewpoint_c)
    if latest_pressure_hpa is not None and math.isfinite(latest_pressure_hpa):
        features["zuuu_metar_raw_awc_latest_pressure_hpa"] = float(latest_pressure_hpa)
        features["awc_pressure_hpa"] = float(latest_pressure_hpa)
    latest_wind_map = {
        "wind_dir_deg": "wind_dir_deg",
        "wind_speed_mps": "wind_speed_mps",
        "wind_variable_from_deg": "wind_variable_from_deg",
        "wind_variable_to_deg": "wind_variable_to_deg",
        "wind_gust_mps": "wind_gust_mps",
        "wind_variable": "wind_variable",
        "wind_dir_text": "wind_dir_text",
        "wind_token": "wind_token",
        "wind_variable_token": "wind_variable_token",
    }
    for row_key, out_key in latest_wind_map.items():
        value = latest.get(row_key)
        if value in (None, ""):
            continue
        features[f"zuuu_metar_raw_awc_latest_{out_key}"] = value
        features[f"awc_{out_key}"] = value
    if any(str(key).startswith("awc_wind_") for key in features):
        features["awc_wind_source"] = "zuuu_metar_raw_awc_latest_raw"
        features["awc_wind_observed_at"] = _iso_from_datetime(latest_time_dt)
    if previous_wind_row is not None:
        previous_time = previous_wind_row.get("observation_time")
        previous_time_dt = previous_time if isinstance(previous_time, datetime) else None
        for row_key, out_key in latest_wind_map.items():
            value = previous_wind_row.get(row_key)
            if value in (None, ""):
                continue
            features[f"zuuu_metar_raw_awc_previous_{out_key}"] = value
            features[f"awc_previous_{out_key}"] = value
        features["awc_previous_wind_observed_at"] = _iso_from_datetime(previous_time_dt)
    if previous_dewpoint_row is not None:
        previous_dew = to_float(previous_dewpoint_row.get("dewpoint_c"))
        previous_time = previous_dewpoint_row.get("observation_time")
        previous_time_dt = previous_time if isinstance(previous_time, datetime) else None
        if previous_dew is not None and math.isfinite(previous_dew):
            features["zuuu_metar_raw_awc_previous_dewpoint_c"] = float(previous_dew)
            features["awc_previous_dewpoint_c"] = float(previous_dew)
            features["awc_previous_dewpoint_observed_at"] = _iso_from_datetime(previous_time_dt)
            if latest_dewpoint_c is not None and math.isfinite(latest_dewpoint_c):
                features["zuuu_metar_raw_awc_dewpoint_trend_c"] = float(latest_dewpoint_c) - float(previous_dew)
                features["dewpoint_trend_c"] = float(latest_dewpoint_c) - float(previous_dew)
    if previous_pressure_row is not None:
        previous_pressure = to_float(previous_pressure_row.get("pressure_hpa"))
        previous_time = previous_pressure_row.get("observation_time")
        previous_time_dt = previous_time if isinstance(previous_time, datetime) else None
        if previous_pressure is not None and math.isfinite(previous_pressure):
            features["zuuu_metar_raw_awc_previous_pressure_hpa"] = float(previous_pressure)
            features["awc_previous_pressure_hpa"] = float(previous_pressure)
            features["awc_previous_pressure_observed_at"] = _iso_from_datetime(previous_time_dt)
            if latest_pressure_hpa is not None and math.isfinite(latest_pressure_hpa):
                features["zuuu_metar_raw_awc_pressure_trend_hpa"] = float(latest_pressure_hpa) - float(previous_pressure)
                features["awc_pressure_trend_hpa"] = float(latest_pressure_hpa) - float(previous_pressure)
                features["pressure_trend_hpa_recent"] = float(latest_pressure_hpa) - float(previous_pressure)
    if latest_time_dt is not None:
        age_minutes = (datetime.now(timezone.utc) - latest_time_dt.astimezone(timezone.utc)).total_seconds() / 60.0
        if math.isfinite(age_minutes):
            features["zuuu_metar_raw_awc_age_minutes"] = max(0.0, float(age_minutes))
    local_zone = None
    if tz and ZoneInfo is not None:
        try:
            local_zone = ZoneInfo(str(tz))
        except Exception:
            local_zone = None
    latest_local_date = ""
    if latest_time_dt is not None:
        latest_local = latest_time_dt.astimezone(local_zone) if local_zone is not None else latest_time_dt.astimezone(timezone.utc)
        latest_local_date = latest_local.date().isoformat()
        features["zuuu_metar_raw_awc_observation_local_date"] = latest_local_date
    target_key = _normalize_date_key(str(target_event_date or ""))
    if target_key:
        features["zuuu_metar_raw_awc_target_event_date"] = target_key
    event_date_matches = bool(not target_key or (latest_local_date and latest_local_date == target_key))
    features["zuuu_metar_raw_awc_date_mismatch"] = bool(target_key and not event_date_matches)
    features["zuuu_metar_raw_awc_date_mismatch_reason"] = (
        "latest_raw_metar_local_date_not_target_event_date"
        if target_key and not event_date_matches
        else ""
    )
    latest_precip_rate = _metar_precip_rate_mm_per_h(latest)
    latest_no_precip = _metar_confirms_no_precip(latest)
    latest_cavok = bool(re.search(r"\bCAVOK\b", str(latest.get("raw") or ""), flags=re.I))
    if event_date_matches:
        if latest_precip_rate is not None:
            features["is_raining_observed"] = True
            features["metar_rain_observed"] = True
            features["observed_precip_rate_mm_per_h"] = float(latest_precip_rate)
            features["precipitation_rate_mm_per_h"] = float(latest_precip_rate)
            features["radar_qpe_proxy_source"] = "zuuu_metar_raw_awc_present_weather"
        elif latest_no_precip:
            features["is_raining_observed"] = False
            features["metar_no_precip_observed"] = True
            features["awc_metar_no_precip_observed"] = True
            features["metar_cavok_observed"] = bool(latest_cavok)
            features["observed_precip_rate_mm_per_h"] = 0.0
            features["precipitation_rate_mm_per_h"] = 0.0
            features["radar_qpe_proxy_source"] = (
                "zuuu_metar_raw_awc_cavok_no_precip"
                if latest_cavok
                else "zuuu_metar_raw_awc_no_precip"
            )
    same_day_temps: List[float] = []
    same_day_temp_pairs: List[Tuple[datetime, float]] = []
    same_day_temp_rows: List[Tuple[datetime, float, Mapping[str, Any]]] = []
    same_day_latest_time: Optional[datetime] = None
    for row in parsed_rows:
        row_time = row.get("observation_time")
        row_time_dt = row_time if isinstance(row_time, datetime) else None
        if row_time_dt is None:
            continue
        row_local = row_time_dt.astimezone(local_zone) if local_zone is not None else row_time_dt.astimezone(timezone.utc)
        if target_key:
            if row_local.date().isoformat() != target_key:
                continue
        elif latest_time_dt is not None:
            latest_local_dt = latest_time_dt.astimezone(local_zone) if local_zone is not None else latest_time_dt.astimezone(timezone.utc)
            if row_local.date() != latest_local_dt.date():
                continue
        temp_val = to_float(row.get("temperature_c"))
        if temp_val is not None and math.isfinite(temp_val):
            same_day_temps.append(float(temp_val))
            same_day_temp_pairs.append((row_time_dt.astimezone(timezone.utc), float(temp_val)))
            same_day_temp_rows.append((row_time_dt.astimezone(timezone.utc), float(temp_val), row))
            if same_day_latest_time is None or row_time_dt > same_day_latest_time:
                same_day_latest_time = row_time_dt
    awc_today_max_c: Optional[float] = None
    if same_day_temps:
        awc_today_max_c = float(max(same_day_temps))
        features["zuuu_metar_raw_awc_today_max_c"] = awc_today_max_c
        features["zuuu_metar_raw_awc_today_sample_count"] = len(same_day_temps)
        max_time, _max_temp, max_row = max(same_day_temp_rows, key=lambda item: (item[1], item[0]))
        features["zuuu_metar_raw_awc_today_max_raw"] = str(max_row.get("raw") or "")
        features["zuuu_metar_raw_awc_today_max_at"] = _iso_from_datetime(max_time)
        points: List[Dict[str, Any]] = []
        for point_time, point_temp, point_row in same_day_temp_rows[-48:]:
            point = {
                "at": _iso_from_datetime(point_time),
                "temp_c": float(point_temp),
                "raw": str(point_row.get("raw") or ""),
            }
            dew_val = to_float(point_row.get("dewpoint_c"))
            if dew_val is not None and math.isfinite(float(dew_val)):
                point["dewpoint_c"] = float(dew_val)
            pressure_val = to_float(point_row.get("pressure_hpa"))
            if pressure_val is not None and math.isfinite(float(pressure_val)):
                point["pressure_hpa"] = float(pressure_val)
            weather_text = _metar_weather_text(point_row).strip()
            if weather_text:
                point["present_weather"] = weather_text
            points.append(point)
        features["zuuu_metar_raw_awc_today_temperature_points"] = points
    if event_date_matches and latest_temp_c is not None and math.isfinite(latest_temp_c):
        features["observed_temp"] = float(latest_temp_c)
        features["observed_temp_c"] = float(latest_temp_c)
        features["observed_temp_source"] = "zuuu_metar_raw_awc"
        features["metar_temperature_c"] = float(latest_temp_c)
        if latest_dewpoint_c is not None and math.isfinite(latest_dewpoint_c):
            features["dewpoint_c"] = float(latest_dewpoint_c)
        if latest_pressure_hpa is not None and math.isfinite(latest_pressure_hpa):
            features["pressure_hpa"] = float(latest_pressure_hpa)
    if event_date_matches and awc_today_max_c is not None:
        features["observed_today_max_c"] = float(awc_today_max_c)
        features["observed_today_max_source"] = "zuuu_metar_raw_awc"
        features["observed_today_max_trusted"] = True
    if event_date_matches:
        features.update(
            _temperature_momentum_from_pairs(
                same_day_temp_pairs,
                source="zuuu_metar_raw_awc",
            )
        )
        _copy_temperature_momentum_to_source_namespace(features, "zuuu_metar_raw_awc")

    obs_val = to_float(observed_nowcast_value)
    obs_source = str(observed_nowcast_source or "").strip()
    if obs_val is not None and math.isfinite(obs_val) and obs_source:
        wu_value_c = _convert_temp_value(float(obs_val), normalize_unit(market_unit) or "C", "C")
        compare_basis = "current_temperature"
        awc_compare_c = latest_temp_c
        if "max_since7am" in obs_source or "history" in obs_source or "daily" in obs_source:
            compare_basis = "intraday_max"
            awc_compare_c = awc_today_max_c if awc_today_max_c is not None else latest_temp_c
        if awc_compare_c is not None and math.isfinite(float(awc_compare_c)):
            delta = float(wu_value_c) - float(awc_compare_c)
            features["zuuu_metar_raw_awc_vs_wu_nowcast_source"] = obs_source
            features["zuuu_metar_raw_awc_vs_wu_nowcast_basis"] = compare_basis
            features["zuuu_metar_raw_awc_vs_wu_nowcast_delta_c"] = float(delta)
            features["zuuu_metar_raw_awc_vs_wu_nowcast_abs_delta_c"] = abs(float(delta))
            features["zuuu_metar_raw_awc_vs_wu_nowcast_status"] = _awc_wu_compare_status(
                abs_delta_c=abs(float(delta)),
                lag_minutes=None,
            )
    if isinstance(wu_history_metrics, Mapping):
        wu_hist_val = to_float(wu_history_metrics.get("value"))
        if wu_hist_val is not None and math.isfinite(wu_hist_val) and awc_today_max_c is not None:
            wu_hist_c = _convert_temp_value(float(wu_hist_val), normalize_unit(market_unit) or "C", "C")
            delta = float(wu_hist_c) - float(awc_today_max_c)
            features["zuuu_metar_raw_awc_vs_wu_history_delta_c"] = float(delta)
            features["zuuu_metar_raw_awc_vs_wu_history_abs_delta_c"] = abs(float(delta))
            features["zuuu_metar_raw_awc_vs_wu_history_status"] = _awc_wu_compare_status(
                abs_delta_c=abs(float(delta)),
                lag_minutes=None,
            )
        wu_hist_time_raw = wu_history_metrics.get("time_gmt")
        wu_hist_time: Optional[datetime] = None
        if isinstance(wu_hist_time_raw, (int, float)):
            wu_hist_time = datetime.fromtimestamp(float(wu_hist_time_raw), tz=timezone.utc)
        elif isinstance(wu_hist_time_raw, str):
            wu_hist_time = _parse_metar_time(wu_hist_time_raw)
        if wu_hist_time is not None and same_day_latest_time is not None:
            lag = (wu_hist_time.astimezone(timezone.utc) - same_day_latest_time.astimezone(timezone.utc)).total_seconds() / 60.0
            features["zuuu_metar_raw_awc_vs_wu_history_time_lag_minutes"] = float(lag)
            status = _awc_wu_compare_status(
                abs_delta_c=to_float(features.get("zuuu_metar_raw_awc_vs_wu_history_abs_delta_c")),
                lag_minutes=float(lag),
            )
            features["zuuu_metar_raw_awc_vs_wu_history_status"] = status
    if metar_cross_check_features:
        features.update(metar_cross_check_features)
    if metar_cross_check_error:
        features["metar_cross_check_error"] = metar_cross_check_error
    alert = _build_zuuu_awc_wu_delay_deformation_alert(features)
    features["weather_source_delay_deformation_alert"] = alert
    features["weather_source_alert_status"] = alert.get("status")
    features["weather_source_alert_level"] = alert.get("level")
    features["weather_source_alert_codes"] = ",".join(str(code) for code in alert.get("codes") or [])
    if provenance is not None:
        provenance["station_id"] = station
        provenance["rows"] = len(parsed_rows)
        provenance["feature_keys"] = sorted(features.keys())
    return features


def _taf_signed_temp_c(token: str) -> Optional[float]:
    text = str(token or "").strip().upper()
    if not text:
        return None
    sign = -1.0 if text.startswith("M") else 1.0
    digits = text[1:] if text.startswith("M") else text
    if not digits.isdigit():
        return None
    return sign * float(int(digits))


def _infer_taf_day_hour_time(token: str, reference_dt: datetime) -> Optional[datetime]:
    match = re.match(r"^(\d{2})(\d{2})Z$", str(token or "").strip().upper())
    if not match:
        return None
    day = int(match.group(1))
    hour = int(match.group(2))
    add_day = 0
    if hour == 24:
        hour = 0
        add_day = 1
    if hour < 0 or hour > 23:
        return None
    ref = reference_dt.astimezone(timezone.utc) if reference_dt.tzinfo else reference_dt.replace(tzinfo=timezone.utc)
    candidates: List[datetime] = []
    for delta in (-1, 0, 1):
        year, month = _month_shift(ref.year, ref.month, delta)
        if day > calendar.monthrange(year, month)[1]:
            continue
        try:
            candidates.append(datetime(year, month, day, hour, 0, tzinfo=timezone.utc) + timedelta(days=add_day))
        except ValueError:
            continue
    if not candidates:
        return None
    return min(candidates, key=lambda dt: abs((dt - ref).total_seconds()))


def _parse_zuuu_taf_raw(
    raw_text: str,
    *,
    response_dt: datetime,
    target_event_date: Optional[str],
    tz: Optional[str],
) -> Dict[str, Any]:
    text = " ".join(str(raw_text or "").strip().split())
    if not text:
        return {}
    tokens = text.split()
    if len(tokens) < 3:
        return {}
    start_idx = 1 if tokens[0].upper() == "TAF" else 0
    while start_idx < len(tokens) and tokens[start_idx].upper() in {"AMD", "COR", "CORR", "RTD"}:
        start_idx += 1
    station = tokens[start_idx].strip().upper() if start_idx < len(tokens) else ""
    if station != "ZUUU":
        return {}
    issue_time: Optional[datetime] = None
    if start_idx + 1 < len(tokens) and re.match(r"^\d{6}Z$", tokens[start_idx + 1].upper()):
        issue_time = _infer_metar_raw_time(tokens[start_idx + 1], response_dt)
    reference_dt = issue_time or response_dt
    valid_start: Optional[datetime] = None
    valid_end: Optional[datetime] = None
    valid_match = re.search(r"\b(\d{2})(\d{2})/(\d{2})(\d{2})\b", text)
    if valid_match:
        valid_start = _infer_taf_day_hour_time(valid_match.group(1) + valid_match.group(2) + "Z", reference_dt)
        valid_end = _infer_taf_day_hour_time(valid_match.group(3) + valid_match.group(4) + "Z", reference_dt)
        if valid_start is not None and valid_end is not None and valid_end <= valid_start:
            valid_end = valid_end + timedelta(days=1)
    local_zone = None
    if tz and ZoneInfo is not None:
        try:
            local_zone = ZoneInfo(str(tz))
        except Exception:
            local_zone = None
    target_key = _normalize_date_key(str(target_event_date or ""))

    def local_date(dt: Optional[datetime]) -> str:
        if dt is None:
            return ""
        local_dt = dt.astimezone(local_zone) if local_zone is not None else dt.astimezone(timezone.utc)
        return local_dt.date().isoformat()

    tx_candidates: List[Dict[str, Any]] = []
    for match in re.finditer(r"\bTX(M?\d{2})/(\d{4})Z\b", text, flags=re.I):
        temp_c = _taf_signed_temp_c(match.group(1))
        at_utc = _infer_taf_day_hour_time(match.group(2) + "Z", reference_dt)
        if temp_c is None or at_utc is None:
            continue
        tx_candidates.append(
            {
                "temperature_c": float(temp_c),
                "forecast_at": at_utc,
                "local_date": local_date(at_utc),
                "token": match.group(0),
            }
        )
    tn_candidates: List[Dict[str, Any]] = []
    for match in re.finditer(r"\bTN(M?\d{2})/(\d{4})Z\b", text, flags=re.I):
        temp_c = _taf_signed_temp_c(match.group(1))
        at_utc = _infer_taf_day_hour_time(match.group(2) + "Z", reference_dt)
        if temp_c is None or at_utc is None:
            continue
        tn_candidates.append(
            {
                "temperature_c": float(temp_c),
                "forecast_at": at_utc,
                "local_date": local_date(at_utc),
                "token": match.group(0),
            }
        )
    if target_key:
        target_tx = [item for item in tx_candidates if item.get("local_date") == target_key]
        target_tn = [item for item in tn_candidates if item.get("local_date") == target_key]
    else:
        target_tx = list(tx_candidates)
        target_tn = list(tn_candidates)
    if not target_tx:
        return {
            "station_id": station,
            "raw": text,
            "issue_time": issue_time,
            "valid_start": valid_start,
            "valid_end": valid_end,
            "target_event_date": target_key,
            "tx_candidates": tx_candidates,
            "tn_candidates": tn_candidates,
            "error": "target_tx_missing",
        }
    peak = max(target_tx, key=lambda item: float(item.get("temperature_c") or -999.0))
    low_candidates = target_tn or tn_candidates
    low = min(low_candidates, key=lambda item: float(item.get("temperature_c") or 999.0)) if low_candidates else None
    return {
        "station_id": station,
        "raw": text,
        "issue_time": issue_time,
        "valid_start": valid_start,
        "valid_end": valid_end,
        "target_event_date": target_key,
        "peak": peak,
        "minimum": low,
        "tx_candidates": tx_candidates,
        "tn_candidates": tn_candidates,
    }


def _taf_forecast_request_timeout() -> Tuple[float, float]:
    raw = _env_float("PM_TAF_FORECAST_TIMEOUT_SEC")
    if raw is None or not math.isfinite(float(raw)) or float(raw) <= 0:
        raw = min(3.0, float(BAYES_LIKELIHOOD_AUX_TIMEOUT_SEC))
    total = max(1.0, min(8.0, float(raw)))
    connect = max(0.5, min(2.0, total * 0.5))
    read = max(0.75, total)
    return (float(connect), float(read))


def _taf_forecast_request_retries() -> int:
    raw = _env_int("PM_TAF_FORECAST_RETRIES")
    if raw is None or raw < 1:
        raw = 1
    return max(1, min(int(raw), 2))


def _awc_metar_request_timeout() -> Tuple[float, float]:
    raw = _env_float("PM_BAYES_LIKELIHOOD_AWC_METAR_TIMEOUT_SEC")
    if raw is None or not math.isfinite(float(raw)) or float(raw) <= 0:
        raw = min(2.0, float(BAYES_LIKELIHOOD_AUX_TIMEOUT_SEC))
    total = max(1.0, min(8.0, float(raw)))
    connect = max(0.5, min(1.5, total * 0.5))
    read = max(0.75, total)
    return (float(connect), float(read))


def _awc_metar_request_retries() -> int:
    raw = _env_int("PM_BAYES_LIKELIHOOD_AWC_METAR_RETRIES")
    if raw is None or raw < 1:
        raw = 1
    return max(1, min(int(raw), 2))


def _aviationweather_force_proxy() -> bool:
    return _env_bool("PM_AVIATIONWEATHER_FORCE_PROXY", True)


def fetch_zuuu_taf_forecast_peak_metrics(
    station_id: Optional[str],
    event_date: str,
    market_var: Optional[str],
    market_unit: Optional[str],
    *,
    tz: Optional[str] = None,
    provenance: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    station = _normalize_station_code(station_id)
    if station != "ZUUU":
        return {"ok": False, "error": "station_not_zuuu"}
    kind = _market_var_extreme_kind(market_var)
    if kind != "max":
        return {"ok": False, "error": "market_var_unsupported"}
    target_key = _normalize_date_key(str(event_date or ""))
    if not target_key:
        return {"ok": False, "error": "missing_event_date"}
    params = {
        "ids": station,
        "format": "raw",
        "metar": "false",
    }
    request_timeout = _taf_forecast_request_timeout()
    request_retries = _taf_forecast_request_retries()
    force_proxy = _aviationweather_force_proxy()
    response = requests_get(
        AVIATIONWEATHER_TAF_URL,
        params=params,
        bypass_proxy=not force_proxy,
        force_proxy=force_proxy,
        retries=request_retries,
        backoff=0.25,
        timeout=request_timeout,
        verify=False if _should_allow_insecure_ssl() else None,
    )
    if provenance is not None:
        provenance["response_url"] = response.url
        provenance["status_code"] = response.status_code
        provenance["response_date"] = response.headers.get("Date") or ""
        provenance["request_timeout"] = list(request_timeout)
        provenance["request_retries"] = int(request_retries)
        provenance["force_proxy"] = bool(force_proxy)
    response.raise_for_status()
    response_dt = _parse_metar_time(response.headers.get("Date")) or datetime.now(timezone.utc)
    parsed = _parse_zuuu_taf_raw(
        getattr(response, "text", "") or "",
        response_dt=response_dt,
        target_event_date=target_key,
        tz=tz,
    )
    if provenance is not None:
        provenance["parsed_keys"] = sorted(parsed.keys()) if isinstance(parsed, Mapping) else []
    if not parsed or parsed.get("error"):
        return {
            "ok": False,
            "error": str((parsed or {}).get("error") or "taf_parse_failed"),
            "source": "zuuu_taf_awc_tx_peak",
            "source_url": response.url,
            "raw_text": getattr(response, "text", "") or "",
        }
    peak = parsed.get("peak") if isinstance(parsed.get("peak"), Mapping) else {}
    peak_c = to_float(peak.get("temperature_c") if isinstance(peak, Mapping) else None)
    peak_at = peak.get("forecast_at") if isinstance(peak, Mapping) else None
    if peak_c is None:
        return {
            "ok": False,
            "error": "taf_peak_value_missing",
            "source": "zuuu_taf_awc_tx_peak",
            "source_url": response.url,
            "raw_text": getattr(response, "text", "") or "",
        }
    unit = normalize_unit(market_unit) or "C"
    value = _convert_temp_value(float(peak_c), "C", unit)
    minimum = parsed.get("minimum") if isinstance(parsed.get("minimum"), Mapping) else {}
    min_c = to_float(minimum.get("temperature_c") if isinstance(minimum, Mapping) else None)
    issue_time = parsed.get("issue_time") if isinstance(parsed.get("issue_time"), datetime) else None
    out: Dict[str, Any] = {
        "ok": True,
        "value": float(value),
        "value_c": float(peak_c),
        "unit": unit,
        "source": "zuuu_taf_awc_tx_peak",
        "source_url": response.url,
        "station_id": station,
        "raw_text": str(parsed.get("raw") or ""),
        "peak_token": str(peak.get("token") or "") if isinstance(peak, Mapping) else "",
        "peak_at": _iso_from_datetime(peak_at if isinstance(peak_at, datetime) else None),
        "issued_at": _iso_from_datetime(issue_time),
        "valid_start_at": _iso_from_datetime(parsed.get("valid_start") if isinstance(parsed.get("valid_start"), datetime) else None),
        "valid_end_at": _iso_from_datetime(parsed.get("valid_end") if isinstance(parsed.get("valid_end"), datetime) else None),
        "target_event_date": target_key,
        "source_fit_tier": "airport_taf_short_range_forecast",
        "source_trust_tier": "strong_soft_forecast",
        "source_usable_for_settlement": False,
        "soft": True,
        "strong_soft": True,
        "not_observed_nowcast": True,
        "usable_for_bayes": False,
        "confidence": 1.0,
    }
    if min_c is not None:
        out["minimum_c"] = float(min_c)
        out["minimum_token"] = str(minimum.get("token") or "") if isinstance(minimum, Mapping) else ""
        out["minimum_local_date"] = str(minimum.get("local_date") or "") if isinstance(minimum, Mapping) else ""
        min_at = minimum.get("forecast_at") if isinstance(minimum, Mapping) else None
        out["minimum_at"] = _iso_from_datetime(min_at if isinstance(min_at, datetime) else None)
    if issue_time is not None:
        age_minutes = (datetime.now(timezone.utc) - issue_time.astimezone(timezone.utc)).total_seconds() / 60.0
        if math.isfinite(age_minutes):
            out["age_minutes"] = max(0.0, float(age_minutes))
    taf_bayes_requested = _env_bool("PM_TAF_FORECAST_PEAK_BAYES_USABLE", False)
    taf_bayes_calibrated = _env_bool("PM_BAYES_TAF_PEAK_WALK_FORWARD_CALIBRATED", False) or _env_bool(
        "PM_TAF_FORECAST_PEAK_WALK_FORWARD_CALIBRATED",
        False,
    )
    taf_main_posterior_enabled = _env_bool("PM_BAYES_TAF_PEAK_MAIN_POSTERIOR_ENABLED", False) or _env_bool(
        "PM_TAF_FORECAST_PEAK_MAIN_POSTERIOR_ENABLED",
        False,
    )
    out["usable_for_bayes_requested"] = bool(taf_bayes_requested)
    out["created_at_walk_forward_calibrated"] = bool(taf_bayes_calibrated)
    out["main_posterior_enabled"] = bool(taf_main_posterior_enabled)
    out["usable_for_bayes"] = bool(taf_bayes_requested and taf_bayes_calibrated and taf_main_posterior_enabled)
    out["bayes_channel_status"] = (
        "enabled_by_calibrated_explicit_env"
        if taf_bayes_requested and taf_bayes_calibrated and taf_main_posterior_enabled
        else "reference_only_forecast_not_main_posterior"
        if taf_bayes_requested and taf_bayes_calibrated
        else "blocked_pending_created_at_walk_forward_calibration"
        if taf_bayes_requested
        else "pending_awc_wu_quality_gate_and_created_at_walk_forward_calibration"
    )
    if provenance is not None:
        provenance["feature_keys"] = sorted(out.keys())
    return out


def fetch_metar_likelihood_features(
    station_id: Optional[str],
    *,
    hours: int = 4,
    tz: Optional[str] = None,
    target_event_date: Optional[str] = None,
    provenance: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    station = _normalize_station_code(station_id)
    if not station:
        return {}
    params = {
        "ids": station,
        "format": "json",
        "taf": "false",
        "hours": max(1, int(hours)),
    }
    request_timeout = _awc_metar_request_timeout()
    request_retries = _awc_metar_request_retries()
    force_proxy = _aviationweather_force_proxy()
    r = requests_get(
        AVIATIONWEATHER_METAR_URL,
        params=params,
        bypass_proxy=not force_proxy,
        force_proxy=force_proxy,
        retries=request_retries,
        backoff=0.25,
        timeout=request_timeout,
        verify=False if _should_allow_insecure_ssl() else None,
    )
    if provenance is not None:
        provenance["response_url"] = r.url
        provenance["status_code"] = r.status_code
        provenance["response_date"] = r.headers.get("Date") or ""
        provenance["request_timeout"] = list(request_timeout)
        provenance["request_retries"] = int(request_retries)
        provenance["force_proxy"] = bool(force_proxy)
    r.raise_for_status()
    payload = r.json()
    rows = payload if isinstance(payload, list) else payload.get("data") if isinstance(payload, dict) else []
    if not isinstance(rows, list):
        rows = []
    metars = [row for row in rows if isinstance(row, Mapping)]
    if not metars:
        return {}
    metars.sort(key=_metar_row_time)
    latest = metars[-1]
    latest_time = _metar_row_time(latest)
    age_minutes: Optional[float] = None
    if latest_time != datetime.min.replace(tzinfo=timezone.utc):
        now_utc = datetime.now(timezone.utc)
        age_minutes = (now_utc - latest_time.astimezone(timezone.utc)).total_seconds() / 60.0
    max_age = _env_float("PM_BAYES_LIKELIHOOD_METAR_MAX_AGE_MIN")
    if max_age is None or not math.isfinite(max_age) or max_age <= 0:
        max_age = 90.0
    features: Dict[str, Any] = {
        "source": "metar_aviationweather",
        "station_id": station,
        "unit": "C",
        "temperature_unit": "C",
    }
    if age_minutes is not None and math.isfinite(age_minutes):
        features["metar_age_minutes"] = max(0.0, float(age_minutes))
        if age_minutes > float(max_age):
            features["metar_stale"] = True
            features["metar_stale_reason"] = "metar_age_exceeds_max"
    local_zone = None
    if tz and ZoneInfo is not None:
        try:
            local_zone = ZoneInfo(str(tz))
        except Exception:
            local_zone = None
    latest_local_time: Optional[datetime] = None
    latest_local_date = ""
    if latest_time != datetime.min.replace(tzinfo=timezone.utc):
        latest_local_time = latest_time.astimezone(local_zone) if local_zone is not None else latest_time.astimezone(timezone.utc)
        latest_local_date = latest_local_time.date().isoformat()
    target_event_key = _normalize_date_key(str(target_event_date or ""))
    event_date_matches = True
    if target_event_key:
        event_date_matches = bool(latest_local_date and latest_local_date == target_event_key)
        features["metar_target_event_date"] = target_event_key
        if latest_local_date:
            features["metar_observation_local_date"] = latest_local_date
        if not event_date_matches:
            features["metar_observation_date_mismatch"] = True
            features["metar_observation_date_mismatch_reason"] = "latest_metar_local_date_not_target_event_date"
    temp_c = to_float(latest.get("temp") or latest.get("temp_c") or latest.get("temperature"))
    dew_c = to_float(latest.get("dewp") or latest.get("dewpoint") or latest.get("dewpoint_c"))
    if event_date_matches:
        if temp_c is not None and math.isfinite(temp_c):
            features["observed_temp"] = float(temp_c)
            features["metar_temperature_c"] = float(temp_c)
        if dew_c is not None and math.isfinite(dew_c):
            features["dewpoint_c"] = float(dew_c)
        wind_speed_kt = to_float(latest.get("wspd") or latest.get("wind_speed_kt") or latest.get("windSpeed"))
        if wind_speed_kt is not None and math.isfinite(wind_speed_kt):
            features["wind_speed_mps"] = float(wind_speed_kt) * 0.514444
        wind_gust_kt = to_float(latest.get("wgst") or latest.get("wind_gust_kt") or latest.get("windGust"))
        if wind_gust_kt is not None and math.isfinite(wind_gust_kt):
            features["wind_gust_mps"] = float(wind_gust_kt) * 0.514444
        wind_dir = to_float(latest.get("wdir") or latest.get("wind_dir_degrees") or latest.get("windDirection"))
        if wind_dir is not None and math.isfinite(wind_dir) and wind_dir >= 0:
            features["wind_direction_deg"] = float(wind_dir) % 360.0
        cloud_pct = _metar_effective_cloud_cover_pct(latest)
        if cloud_pct is not None:
            features["cloud_cover_pct"] = float(cloud_pct)
            features["metar_effective_cloud_cover_pct"] = float(cloud_pct)
        metar_precip_rate = _metar_precip_rate_mm_per_h(latest)
        if metar_precip_rate is not None:
            features["is_raining_observed"] = True
            features["metar_rain_observed"] = True
            features["observed_precip_rate_mm_per_h"] = float(metar_precip_rate)
            features["precipitation_rate_mm_per_h"] = float(metar_precip_rate)
            features["radar_qpe_proxy_source"] = "metar_present_weather"
        elif _metar_confirms_no_precip(latest):
            latest_raw = str(latest.get("rawOb") or latest.get("raw_text") or latest.get("raw") or "")
            latest_cavok = bool(re.search(r"\bCAVOK\b", latest_raw, flags=re.I))
            features["is_raining_observed"] = False
            features["metar_no_precip_observed"] = True
            features["awc_metar_no_precip_observed"] = True
            features["metar_cavok_observed"] = bool(latest_cavok)
            features["observed_precip_rate_mm_per_h"] = 0.0
            features["precipitation_rate_mm_per_h"] = 0.0
            features["radar_qpe_proxy_source"] = (
                "metar_present_weather_cavok_no_precip"
                if latest_cavok
                else "metar_present_weather_no_precip"
            )
        pressures = [
            (row, _metar_pressure_hpa(row))
            for row in metars
        ]
        pressures = [(row, val) for row, val in pressures if val is not None and math.isfinite(val)]
        if pressures:
            features["pressure_hpa"] = float(pressures[-1][1])
        if len(pressures) >= 2:
            features["pressure_trend_hpa_3h"] = float(pressures[-1][1] - pressures[0][1])
    if event_date_matches and latest_local_time is not None:
        local_time = latest_local_time
        features["observation_hour_local"] = float(
            local_time.hour + local_time.minute / 60.0 + local_time.second / 3600.0
        )
        features["observation_month"] = int(local_time.month)
        same_day_temps: List[float] = []
        for row in metars:
            row_time = _metar_row_time(row)
            if row_time == datetime.min.replace(tzinfo=timezone.utc):
                continue
            row_local = row_time.astimezone(local_zone) if local_zone is not None else row_time.astimezone(timezone.utc)
            if row_local.date() != local_time.date():
                continue
            row_temp = to_float(row.get("temp") or row.get("temp_c") or row.get("temperature"))
            if row_temp is not None and math.isfinite(row_temp):
                same_day_temps.append(float(row_temp))
        if same_day_temps:
            features["observed_today_max_c"] = float(max(same_day_temps))
            features["observed_today_max_source"] = "metar_recent_observations"
            features["observed_today_max_trusted"] = True
        temp_time_pairs: List[Tuple[datetime, float]] = []
        for row in metars:
            row_time = _metar_row_time(row)
            if row_time == datetime.min.replace(tzinfo=timezone.utc):
                continue
            row_local = row_time.astimezone(local_zone) if local_zone is not None else row_time.astimezone(timezone.utc)
            if row_local.date() != local_time.date():
                continue
            row_temp = to_float(row.get("temp") or row.get("temp_c") or row.get("temperature"))
            if row_temp is not None and math.isfinite(row_temp):
                temp_time_pairs.append((row_time.astimezone(timezone.utc), float(row_temp)))
        temp_time_pairs.sort(key=lambda item: item[0])
        if len(temp_time_pairs) >= 2:
            _apply_temperature_trajectory_rates(
                features,
                temp_time_pairs,
                source="metar_recent_observations",
            )
    if provenance is not None:
        provenance["station_id"] = station
        provenance["rows"] = len(metars)
        provenance["feature_keys"] = sorted(features.keys())
    return features


def _nws_quantitative_value(raw: Any) -> Optional[float]:
    if isinstance(raw, Mapping):
        return to_float(raw.get("value"))
    return to_float(raw)


def _nws_pressure_hpa(raw: Any) -> Optional[float]:
    val = _nws_quantitative_value(raw)
    if val is None or not math.isfinite(val):
        return None
    # NWS API pressure values are commonly Pa; hPa values are already around 1000.
    return float(val) / 100.0 if abs(float(val)) > 2000.0 else float(val)


def _nws_present_weather_rain_rate_mm_per_h(values: Any) -> Optional[float]:
    if not isinstance(values, list):
        return None
    best = 0.0
    seen = False
    for item in values:
        if not isinstance(item, Mapping):
            continue
        text = " ".join(
            str(item.get(key) or "")
            for key in ("intensity", "modifier", "weather", "rawString", "phenomenon")
        ).lower()
        if not any(token in text for token in ("rain", "drizzle", "shower", "thunderstorm")):
            continue
        seen = True
        if "heavy" in text:
            best = max(best, 8.0)
        elif "light" in text or "drizzle" in text:
            best = max(best, 1.0)
        elif "shower" in text or "thunderstorm" in text:
            best = max(best, 4.0)
        else:
            best = max(best, 2.5)
    return best if seen else None


def _nws_cloud_cover_pct(values: Any) -> Optional[float]:
    if not isinstance(values, list):
        return None
    cover_map = {
        "CLR": 0.0,
        "SKC": 0.0,
        "FEW": 12.5,
        "SCT": 37.5,
        "BKN": 75.0,
        "OVC": 100.0,
    }
    clear_fraction = 1.0
    seen = False
    for item in values:
        if not isinstance(item, Mapping):
            continue
        amount = str(item.get("amount") or item.get("coverage") or "").strip().upper()
        if not amount:
            continue
        cover_pct = cover_map.get(amount)
        if cover_pct is None:
            continue
        seen = True
        base = _nws_quantitative_value(item.get("base"))
        low_boost = 1.25 if base is not None and math.isfinite(base) and base < 1000.0 else 1.0
        clear_fraction *= max(0.0, 1.0 - min(1.0, cover_pct / 100.0 * low_boost))
    return max(0.0, min(100.0, (1.0 - clear_fraction) * 100.0)) if seen else None


def fetch_nws_latest_observation_likelihood_features(
    station_id: Optional[str],
    *,
    tz: Optional[str] = None,
    target_event_date: Optional[str] = None,
    provenance: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Fetch official NWS latest station observations as realtime physical evidence."""

    station = _normalize_station_code(station_id)
    if not station:
        return {}
    headers = {"User-Agent": NWS_USER_AGENT, "Accept": "application/geo+json"}
    url = NWS_STATION_OBSERVATIONS_LATEST_URL.format(station_id=station)
    resp = requests_get(
        url,
        headers=headers,
        bypass_proxy=True,
        retries=2,
        backoff=0.8,
        timeout=int(max(1, BAYES_LIKELIHOOD_AUX_TIMEOUT_SEC)),
    )
    if provenance is not None:
        provenance["response_url"] = resp.url
        provenance["status_code"] = resp.status_code
        provenance["response_date"] = resp.headers.get("Date") or ""
    if resp.status_code != 200:
        return {}
    data = resp.json()
    props = data.get("properties") if isinstance(data, Mapping) else {}
    if not isinstance(props, Mapping):
        props = {}
    features: Dict[str, Any] = {
        "source": "nws_latest_station_observation",
        "station_id": station,
        "unit": "C",
        "temperature_unit": "C",
    }
    timestamp = str(props.get("timestamp") or "").strip()
    obs_dt = _parse_metar_time(timestamp)
    local_zone = None
    if tz and ZoneInfo is not None:
        try:
            local_zone = ZoneInfo(str(tz))
        except Exception:
            local_zone = None
    local_date = ""
    local_time: Optional[datetime] = None
    if obs_dt is not None:
        local_time = obs_dt.astimezone(local_zone) if local_zone is not None else obs_dt.astimezone(timezone.utc)
        local_date = local_time.date().isoformat()
        features["nws_observation_time"] = obs_dt.astimezone(timezone.utc).isoformat()
        features["nws_observation_local_date"] = local_date
    target_event_key = _normalize_date_key(str(target_event_date or ""))
    event_date_matches = True
    if target_event_key:
        event_date_matches = bool(local_date and local_date == target_event_key)
        features["nws_target_event_date"] = target_event_key
        if not event_date_matches:
            features["nws_observation_date_mismatch"] = True
            features["nws_observation_date_mismatch_reason"] = "latest_nws_observation_local_date_not_target_event_date"
    if event_date_matches:
        temp_c = _nws_quantitative_value(props.get("temperature"))
        dew_c = _nws_quantitative_value(props.get("dewpoint"))
        wind_speed_mps = _nws_quantitative_value(props.get("windSpeed"))
        wind_gust_mps = _nws_quantitative_value(props.get("windGust"))
        wind_dir = _nws_quantitative_value(props.get("windDirection"))
        pressure_hpa = _nws_pressure_hpa(props.get("barometricPressure"))
        precip_1h = _nws_quantitative_value(props.get("precipitationLastHour"))
        precip_3h = _nws_quantitative_value(props.get("precipitationLast3Hours"))
        precip_6h = _nws_quantitative_value(props.get("precipitationLast6Hours"))
        present_rate = _nws_present_weather_rain_rate_mm_per_h(props.get("presentWeather"))
        precip_candidates = [
            val for val in (precip_1h, present_rate)
            if val is not None and math.isfinite(float(val))
        ]
        if precip_candidates:
            rate = float(max(precip_candidates))
            features["observed_precip_rate_mm_per_h"] = rate
            features["precipitation_rate_mm_per_h"] = rate
            features["qpe_precip_rate_mm_per_h"] = rate
            features["radar_qpe_proxy_source"] = "nws_latest_station_observation"
            if rate > 0:
                features["is_raining_observed"] = True
        if precip_1h is not None and math.isfinite(float(precip_1h)):
            features["qpe_precip_mm"] = float(precip_1h)
        wetness_vals = [val for val in (precip_1h, precip_3h, precip_6h) if val is not None and math.isfinite(float(val))]
        if wetness_vals:
            features["surface_wetness_proxy"] = max(0.0, min(1.0, max(float(v) for v in wetness_vals) / 5.0))
        cloud_pct = _nws_cloud_cover_pct(props.get("cloudLayers"))
        if temp_c is not None and math.isfinite(temp_c):
            features["observed_temp"] = float(temp_c)
            features["nws_temperature_c"] = float(temp_c)
            features["observed_today_max_c"] = float(temp_c)
            features["observed_today_max_source"] = "nws_latest_station_observation"
            features["observed_today_max_trusted"] = True
        if dew_c is not None and math.isfinite(dew_c):
            features["dewpoint_c"] = float(dew_c)
        if wind_speed_mps is not None and math.isfinite(wind_speed_mps):
            features["wind_speed_mps"] = float(wind_speed_mps)
        if wind_gust_mps is not None and math.isfinite(wind_gust_mps):
            features["wind_gust_mps"] = float(wind_gust_mps)
        if wind_dir is not None and math.isfinite(wind_dir):
            features["wind_direction_deg"] = float(wind_dir) % 360.0
        if pressure_hpa is not None:
            features["pressure_hpa"] = float(pressure_hpa)
        if cloud_pct is not None:
            features["cloud_cover_pct"] = float(cloud_pct)
            features["nws_effective_cloud_cover_pct"] = float(cloud_pct)
    if event_date_matches and local_time is not None:
        features["observation_hour_local"] = float(
            local_time.hour + local_time.minute / 60.0 + local_time.second / 3600.0
        )
        features["observation_month"] = int(local_time.month)
    if provenance is not None:
        provenance["station_id"] = station
        provenance["feature_keys"] = sorted(features.keys())
        if SAVE_MODEL_RAW:
            provenance["raw_response"] = data
    return features


def extract_members_daily_var(js: Dict, var: str, model: Optional[str] = None) -> np.ndarray:
    daily = js.get("daily") or {}
    if model:
        suffix_map = {
            "gfs_seamless": ["ncep_gefs_seamless"],
            "icon_seamless": ["icon_seamless_eps"],
            "ecmwf_ifs025": ["ecmwf_ifs025_ensemble"],
        }
        suffixes = suffix_map.get(model, [])
        members = []
        for suffix in suffixes:
            prefix = f"{var}_member"
            for key, vals in daily.items():
                if not isinstance(key, str) or not key.startswith(prefix):
                    continue
                if not key.endswith(f"_{suffix}"):
                    continue
                if not isinstance(vals, list) or not vals:
                    continue
                members.append(float(vals[0]))
        if members:
            return np.array(members, dtype=float)
        for suffix in suffixes:
            base_key = f"{var}_{suffix}"
            vals = daily.get(base_key)
            if isinstance(vals, list) and vals:
                return np.array([float(vals[0])], dtype=float)
    if var not in daily:
        raise ValueError(f"Missing daily[{var}] in ensemble response")
    v = daily[var]
    if isinstance(v, list) and v and isinstance(v[0], list):
        arr = np.array(v, dtype=float)
        days = len(daily.get("time") or [])
        if days == 0:
            days = 1
        if arr.shape[0] == days and arr.shape[1] != days:
            arr = arr.T
        if arr.shape[1] != 1:
            raise ValueError(f"Expected single-day slice; got shape={arr.shape}")
        return arr[:, 0]
    if isinstance(v, list) and v and not isinstance(v[0], list):
        return np.array(v, dtype=float)
    raise ValueError("Unexpected ensemble daily format")


def _parse_iso_date(ts: str) -> Optional[datetime]:
    try:
        return datetime.fromisoformat(ts.replace("Z", "+00:00"))
    except ValueError:
        return None


def _parse_wind_speed_mph(text: str) -> Optional[float]:
    if not text:
        return None
    nums = re.findall(r"-?\d+(?:\.\d+)?", text)
    if not nums:
        return None
    vals = [float(n) for n in nums]
    return max(vals)


def _convert_temp_f(value: float, market_unit: Optional[str]) -> float:
    if market_unit == "C":
        return (value - 32.0) * 5.0 / 9.0
    return value


def _convert_wind_mph(value: float, market_unit: Optional[str]) -> float:
    if market_unit == "kmh":
        return value * 1.609344
    if market_unit == "ms":
        return value * 0.44704
    return value


def fetch_nws_hourly(
    lat: float,
    lon: float,
    provenance: Optional[Dict] = None,
) -> Optional[List[Dict]]:
    headers = {"User-Agent": NWS_USER_AGENT, "Accept": "application/geo+json"}
    points_url = NWS_POINTS_URL.format(lat=lat, lon=lon)
    r = requests_get(
        points_url,
        headers=headers,
        bypass_proxy=True,
        retries=3,
    )
    if provenance is not None:
        provenance["points_url"] = points_url
        provenance["points_status"] = r.status_code
    if r.status_code != 200:
        return None
    props = r.json().get("properties") or {}
    hourly_url = props.get("forecastHourly")
    if not hourly_url:
        return None
    if provenance is not None:
        provenance["forecast_url"] = hourly_url
    r2 = requests_get(hourly_url, headers=headers, bypass_proxy=True, retries=3)
    if provenance is not None:
        provenance["forecast_status"] = r2.status_code
    if r2.status_code != 200:
        return None
    data = r2.json()
    if provenance is not None and SAVE_MODEL_RAW:
        provenance["raw_response"] = data
    if provenance is not None:
        props = data.get("properties", {}) if isinstance(data, dict) else {}
        official = ""
        if isinstance(props, dict):
            official = str(
                props.get("generatedAt")
                or props.get("updateTime")
                or props.get("updated")
                or ""
            )
        provenance["official_updated_at"] = official
        provenance["response_date"] = r2.headers.get("Date") or ""
    periods = data.get("properties", {}).get("periods")
    if isinstance(periods, list):
        return periods
    return None


def fetch_nws_daily_var(
    lat: float,
    lon: float,
    date: str,
    market_var: str,
    market_unit: Optional[str],
    provenance: Optional[Dict] = None,
) -> Optional[np.ndarray]:
    periods = fetch_nws_hourly(lat, lon, provenance=provenance)
    if not periods:
        return None
    if provenance is not None:
        provenance["periods_count"] = len(periods)
    temps: List[float] = []
    hums: List[float] = []
    winds: List[float] = []
    for p in periods:
        start = _parse_iso_date(str(p.get("startTime") or ""))
        if not start or start.date().isoformat() != date:
            continue
        temp = p.get("temperature")
        if isinstance(temp, (int, float)):
            temps.append(float(temp))
        rh = (p.get("relativeHumidity") or {}).get("value")
        if isinstance(rh, (int, float)):
            hums.append(float(rh))
        wind = _parse_wind_speed_mph(str(p.get("windSpeed") or ""))
        if wind is not None:
            winds.append(float(wind))
    if market_var == "temperature_2m_max" and temps:
        val = _convert_temp_f(max(temps), market_unit)
        return np.array([val], dtype=float)
    if market_var == "temperature_2m_min" and temps:
        val = _convert_temp_f(min(temps), market_unit)
        return np.array([val], dtype=float)
    if market_var == "relative_humidity_2m_mean" and hums:
        return np.array([float(np.mean(hums))], dtype=float)
    if market_var == "windspeed_10m_max" and winds:
        val = _convert_wind_mph(max(winds), market_unit)
        return np.array([val], dtype=float)
    return None


def is_us_coordinate(lat: float, lon: float) -> bool:
    boxes = [
        (24.0, 50.0, -125.0, -66.0),  # CONUS
        (51.0, 72.0, -170.0, -130.0),  # Alaska
        (18.0, 23.5, -161.0, -154.0),  # Hawaii
        (17.0, 19.8, -68.5, -65.0),  # Puerto Rico
        (17.0, 18.6, -65.2, -64.1),  # USVI (approx)
    ]
    for lat_min, lat_max, lon_min, lon_max in boxes:
        if lat_min <= lat <= lat_max and lon_min <= lon <= lon_max:
            return True
    return False


def is_us_station_id(station_id: Optional[str]) -> bool:
    if not station_id:
        return False
    code = station_id.strip().upper()
    return code.startswith("K") or code.startswith("P")


CANADA_TZS = {
    "America/Toronto",
    "America/Vancouver",
    "America/Edmonton",
    "America/Winnipeg",
    "America/Halifax",
    "America/St_Johns",
    "America/Regina",
    "America/Whitehorse",
    "America/Dawson",
    "America/Dawson_Creek",
    "America/Inuvik",
    "America/Yellowknife",
    "America/Atikokan",
    "America/Glace_Bay",
    "America/Goose_Bay",
    "America/Moncton",
    "America/Nipigon",
    "America/Pangnirtung",
    "America/Rainy_River",
    "America/Resolute",
    "America/Swift_Current",
    "America/Thunder_Bay",
}


def is_nws_allowed(
    lat: float,
    lon: float,
    tz: Optional[str],
    station_id: Optional[str] = None,
) -> bool:
    if not is_us_coordinate(lat, lon):
        return False
    if station_id and not is_us_station_id(station_id):
        return False
    if tz and tz in CANADA_TZS:
        return False
    return True


def _mrms_response_bytes(resp: Any) -> bytes:
    raw = getattr(resp, "content", None)
    if isinstance(raw, bytes):
        return raw
    text = getattr(resp, "text", "")
    if isinstance(text, str):
        return text.encode("utf-8")
    return bytes(str(text or ""), "utf-8")


def _mrms_latest_s3_object(
    product_prefix: str,
    date_keys: Sequence[str],
    *,
    provenance: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    import xml.etree.ElementTree as ET

    best: Dict[str, Any] = {}
    attempts: List[Dict[str, Any]] = []
    for date_key in date_keys:
        clean_date = re.sub(r"[^0-9]", "", str(date_key or ""))[:8]
        if len(clean_date) != 8:
            continue
        prefix = f"{str(product_prefix or '').rstrip('/')}/{clean_date}/"
        try:
            resp = requests_get(
                MRMS_S3_LIST_URL,
                params={"list-type": "2", "prefix": prefix, "max-keys": "1000"},
                headers=DEFAULT_REQUEST_HEADERS,
                bypass_proxy=True,
                retries=1,
                backoff=0.5,
                timeout=int(max(1, BAYES_LIKELIHOOD_AUX_TIMEOUT_SEC)),
            )
        except Exception as exc:
            attempts.append({"prefix": prefix, "error": exc.__class__.__name__})
            continue
        attempts.append({"prefix": prefix, "status_code": getattr(resp, "status_code", None)})
        if getattr(resp, "status_code", None) != 200:
            continue
        try:
            root = ET.fromstring(_mrms_response_bytes(resp))
        except Exception as exc:
            attempts[-1]["parse_error"] = exc.__class__.__name__
            continue
        for contents in root.findall(".//{*}Contents"):
            key_node = contents.find("{*}Key")
            if key_node is None or not key_node.text:
                continue
            key = str(key_node.text).strip()
            if not key.endswith(".grib2.gz"):
                continue
            size_node = contents.find("{*}Size")
            modified_node = contents.find("{*}LastModified")
            item = {
                "key": key,
                "size": int(to_float(size_node.text) or 0) if size_node is not None else 0,
                "last_modified": str(modified_node.text or "") if modified_node is not None else "",
            }
            if not best or key > str(best.get("key") or ""):
                best = item
    if provenance is not None:
        provenance["mrms_s3_attempts"] = attempts
    return best


def _mrms_key_time_iso(key: str) -> str:
    match = re.search(r"_(\d{8})-(\d{6})\.grib2\.gz$", str(key or ""))
    if not match:
        return ""
    try:
        dt = datetime.strptime(match.group(1) + match.group(2), "%Y%m%d%H%M%S").replace(tzinfo=timezone.utc)
        return dt.isoformat()
    except Exception:
        return ""


def _mrms_get_section(sections: Mapping[int, bytes], number: int) -> bytes:
    section = sections.get(number)
    if not section:
        raise ValueError(f"mrms_grib2_section_{number}_missing")
    return section


def _mrms_int4(section: bytes, offset: int, *, signed: bool = False) -> int:
    return int.from_bytes(section[offset : offset + 4], "big", signed=signed)


def _mrms_parse_png_payload(png: bytes) -> Dict[str, Any]:
    if not isinstance(png, (bytes, bytearray)) or not bytes(png).startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("mrms_png_signature_missing")
    pos = 8
    ihdr: Optional[bytes] = None
    idat_parts: List[bytes] = []
    payload = bytes(png)
    while pos + 12 <= len(payload):
        length = int.from_bytes(payload[pos : pos + 4], "big")
        chunk_type = payload[pos + 4 : pos + 8]
        chunk = payload[pos + 8 : pos + 8 + length]
        if len(chunk) != length:
            raise ValueError("mrms_png_chunk_truncated")
        if chunk_type == b"IHDR":
            ihdr = chunk
        elif chunk_type == b"IDAT":
            idat_parts.append(chunk)
        elif chunk_type == b"IEND":
            break
        pos += 12 + length
    if ihdr is None or not idat_parts:
        raise ValueError("mrms_png_required_chunk_missing")
    width = int.from_bytes(ihdr[0:4], "big")
    height = int.from_bytes(ihdr[4:8], "big")
    bit_depth = ihdr[8]
    color_type = ihdr[9]
    compression = ihdr[10]
    filter_method = ihdr[11]
    interlace = ihdr[12]
    if bit_depth != 16 or color_type != 0:
        raise ValueError(f"mrms_png_unsupported_format:{bit_depth}:{color_type}")
    if compression != 0 or filter_method != 0 or interlace != 0:
        raise ValueError("mrms_png_unsupported_compression_filter_or_interlace")
    raw = zlib.decompress(b"".join(idat_parts))
    row_bytes = width * 2
    expected = height * (1 + row_bytes)
    if len(raw) != expected:
        raise ValueError("mrms_png_unexpected_scanline_size")
    return {
        "width": width,
        "height": height,
        "bit_depth": bit_depth,
        "color_type": color_type,
        "row_bytes": row_bytes,
        "raw_scanlines": raw,
    }


def _mrms_paeth_predictor(a: int, b: int, c: int) -> int:
    p = a + b - c
    pa = abs(p - a)
    pb = abs(p - b)
    pc = abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    if pb <= pc:
        return b
    return c


def _mrms_png_unfiltered_row(png_meta: Mapping[str, Any], row_index: int) -> bytes:
    width = int(png_meta.get("width") or 0)
    height = int(png_meta.get("height") or 0)
    row_bytes = int(png_meta.get("row_bytes") or 0)
    raw = png_meta.get("raw_scanlines")
    if not isinstance(raw, (bytes, bytearray)) or width <= 0 or height <= 0 or row_bytes <= 0:
        raise ValueError("mrms_png_meta_invalid")
    if row_index < 0 or row_index >= height:
        raise ValueError("mrms_png_row_out_of_bounds")
    previous = bytearray(row_bytes)
    bytes_per_pixel = 2
    for row in range(row_index + 1):
        offset = row * (1 + row_bytes)
        filter_type = raw[offset]
        current = bytearray(raw[offset + 1 : offset + 1 + row_bytes])
        if filter_type == 1:
            for idx in range(row_bytes):
                left = current[idx - bytes_per_pixel] if idx >= bytes_per_pixel else 0
                current[idx] = (current[idx] + left) & 0xFF
        elif filter_type == 2:
            for idx in range(row_bytes):
                current[idx] = (current[idx] + previous[idx]) & 0xFF
        elif filter_type == 3:
            for idx in range(row_bytes):
                left = current[idx - bytes_per_pixel] if idx >= bytes_per_pixel else 0
                up = previous[idx]
                current[idx] = (current[idx] + ((left + up) // 2)) & 0xFF
        elif filter_type == 4:
            for idx in range(row_bytes):
                left = current[idx - bytes_per_pixel] if idx >= bytes_per_pixel else 0
                up = previous[idx]
                up_left = previous[idx - bytes_per_pixel] if idx >= bytes_per_pixel else 0
                current[idx] = (current[idx] + _mrms_paeth_predictor(left, up, up_left)) & 0xFF
        elif filter_type != 0:
            raise ValueError(f"mrms_png_unsupported_filter:{filter_type}")
        previous = current
    return bytes(previous)


def _mrms_parse_grib2_png_precip(payload_gz: bytes) -> Dict[str, Any]:
    try:
        payload = gzip.decompress(payload_gz)
    except Exception as exc:
        raise ValueError(f"mrms_gzip_decode_error:{exc.__class__.__name__}") from exc
    start = payload.find(b"GRIB")
    if start < 0 or len(payload) < start + 16:
        raise ValueError("mrms_grib2_header_missing")
    if payload[start + 7] != 2:
        raise ValueError("mrms_grib2_edition_not_2")
    total_len = int.from_bytes(payload[start + 8 : start + 16], "big")
    if total_len <= 16 or start + total_len > len(payload):
        raise ValueError("mrms_grib2_total_length_invalid")
    sections: Dict[int, bytes] = {}
    pos = start + 16
    while pos < start + total_len - 4:
        if pos + 5 > len(payload):
            raise ValueError("mrms_grib2_section_header_truncated")
        section_len = int.from_bytes(payload[pos : pos + 4], "big")
        section_num = payload[pos + 4]
        if section_len < 5 or pos + section_len > len(payload):
            raise ValueError("mrms_grib2_section_length_invalid")
        sections[int(section_num)] = payload[pos : pos + section_len]
        pos += section_len
    if payload[pos : pos + 4] != b"7777":
        raise ValueError("mrms_grib2_end_marker_missing")
    section3 = _mrms_get_section(sections, 3)
    section5 = _mrms_get_section(sections, 5)
    section6 = _mrms_get_section(sections, 6)
    section7 = _mrms_get_section(sections, 7)
    grid_template = int.from_bytes(section3[12:14], "big")
    data_template = int.from_bytes(section5[9:11], "big")
    bitmap_indicator = section6[5] if len(section6) > 5 else None
    if grid_template != 0:
        raise ValueError(f"mrms_grib2_unsupported_grid_template:{grid_template}")
    if data_template != 41:
        raise ValueError(f"mrms_grib2_unsupported_data_template:{data_template}")
    if bitmap_indicator not in (255, None):
        raise ValueError(f"mrms_grib2_unsupported_bitmap:{bitmap_indicator}")
    nx = _mrms_int4(section3, 30)
    ny = _mrms_int4(section3, 34)
    lat1 = _mrms_int4(section3, 46, signed=True) / 1_000_000.0
    lon1 = _mrms_int4(section3, 50, signed=True) / 1_000_000.0
    lat2 = _mrms_int4(section3, 55, signed=True) / 1_000_000.0
    lon2 = _mrms_int4(section3, 59, signed=True) / 1_000_000.0
    di = _mrms_int4(section3, 63) / 1_000_000.0
    dj = _mrms_int4(section3, 67) / 1_000_000.0
    scan_mode = int(section3[71])
    ref_value = struct.unpack(">f", section5[11:15])[0]
    binary_scale = int.from_bytes(section5[15:17], "big", signed=True)
    decimal_scale = int.from_bytes(section5[17:19], "big", signed=True)
    bits_per_value = int(section5[19])
    if bits_per_value != 16:
        raise ValueError(f"mrms_grib2_unsupported_bits_per_value:{bits_per_value}")
    png_meta = _mrms_parse_png_payload(section7[5:])
    width = int(png_meta.get("width") or 0)
    height = int(png_meta.get("height") or 0)
    if width != nx or height != ny:
        raise ValueError("mrms_grib2_png_grid_size_mismatch")
    return {
        "nx": nx,
        "ny": ny,
        "lat1": lat1,
        "lon1": lon1,
        "lat2": lat2,
        "lon2": lon2,
        "di": di,
        "dj": dj,
        "scan_mode": scan_mode,
        "ref_value": ref_value,
        "binary_scale": binary_scale,
        "decimal_scale": decimal_scale,
        "png_meta": png_meta,
    }


def _mrms_lon_to_grid(lon: float, lon1: float, lon2: float) -> float:
    lon_grid = float(lon) % 360.0
    if lon2 < lon1 and lon_grid < lon1:
        lon_grid += 360.0
    return lon_grid


def _mrms_sample_precip_from_parsed(parsed: Mapping[str, Any], lat: float, lon: float) -> Dict[str, Any]:
    nx = int(parsed.get("nx") or 0)
    ny = int(parsed.get("ny") or 0)
    lat1 = float(parsed.get("lat1"))
    lon1 = float(parsed.get("lon1"))
    lat2 = float(parsed.get("lat2"))
    lon2 = float(parsed.get("lon2"))
    di = float(parsed.get("di"))
    dj = float(parsed.get("dj"))
    if nx <= 0 or ny <= 0 or di <= 0 or dj <= 0:
        raise ValueError("mrms_grid_meta_invalid")
    lon_grid = _mrms_lon_to_grid(float(lon), lon1, lon2)
    x_float = (lon_grid - lon1) / di if lon2 >= lon1 else (lon1 - lon_grid) / di
    y_float = (float(lat) - lat1) / dj if lat2 >= lat1 else (lat1 - float(lat)) / dj
    x = int(round(x_float))
    y = int(round(y_float))
    if x < 0 or x >= nx or y < 0 or y >= ny:
        raise ValueError("mrms_point_outside_conus_grid")
    row = _mrms_png_unfiltered_row(parsed.get("png_meta") or {}, y)
    raw_code = int.from_bytes(row[x * 2 : x * 2 + 2], "big")
    value = (
        float(parsed.get("ref_value"))
        + float(raw_code) * (2.0 ** int(parsed.get("binary_scale") or 0))
    ) / (10.0 ** int(parsed.get("decimal_scale") or 0))
    rate = max(0.0, float(value))
    out = {
        "radar_precip_rate_mm_per_h": rate,
        "qpe_precip_rate_mm_per_h": rate,
        "precipitation_rate_mm_per_h": rate,
        "radar_precip_observed": bool(rate >= 0.05),
        "is_raining_observed": bool(rate >= 0.05),
        "surface_wetness_proxy": max(0.0, min(1.0, rate / 8.0)),
        "radar_qpe_grid_x": x,
        "radar_qpe_grid_y": y,
        "radar_qpe_raw_code": raw_code,
        "radar_qpe_raw_value_mm_per_h": float(value),
        "radar_qpe_grid_lat": lat1 + ((lat2 - lat1) / max(1, ny - 1)) * y,
        "radar_qpe_grid_lon": lon1 + ((lon2 - lon1) / max(1, nx - 1)) * x,
        "radar_qpe_grid_resolution_deg": max(di, dj),
    }
    if value < 0:
        out["radar_qpe_negative_raw_capped"] = True
    return out


def _mrms_parsed_precip_grib_for_key(key: str, *, provenance: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    clean_key = str(key or "").strip()
    if not clean_key:
        raise ValueError("mrms_key_missing")
    with MRMS_GRIB_DECODE_CACHE_LOCK:
        cached = MRMS_GRIB_DECODE_CACHE.get(clean_key)
        if isinstance(cached, dict):
            if provenance is not None:
                provenance["mrms_decode_cache_hit"] = True
            return cached
    url = MRMS_S3_LIST_URL + quote(clean_key, safe="/")
    resp = requests_get(
        url,
        headers=DEFAULT_REQUEST_HEADERS,
        bypass_proxy=True,
        retries=3,
        backoff=0.8,
        timeout=int(max(30, BAYES_LIKELIHOOD_AUX_TIMEOUT_SEC)),
    )
    if provenance is not None:
        provenance["mrms_grib_url"] = getattr(resp, "url", url)
        provenance["mrms_grib_status_code"] = getattr(resp, "status_code", None)
    if getattr(resp, "status_code", None) != 200:
        raise ValueError(f"mrms_grib_http_status:{getattr(resp, 'status_code', None)}")
    parsed = _mrms_parse_grib2_png_precip(_mrms_response_bytes(resp))
    with MRMS_GRIB_DECODE_CACHE_LOCK:
        MRMS_GRIB_DECODE_CACHE.clear()
        MRMS_GRIB_DECODE_CACHE[clean_key] = parsed
    return parsed


def fetch_mrms_qpe_metadata_features(
    lat: float,
    lon: float,
    *,
    tz: Optional[str] = None,
    target_event_date: Optional[str] = None,
    now_dt: Optional[datetime] = None,
    provenance: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Discover the latest official NOAA MRMS precip-rate file without decoding GRIB2."""

    if not is_us_coordinate(lat, lon):
        return {}
    now_utc = now_dt.astimezone(timezone.utc) if isinstance(now_dt, datetime) else datetime.now(timezone.utc)
    local_zone = None
    if tz and ZoneInfo is not None:
        try:
            local_zone = ZoneInfo(str(tz))
        except Exception:
            local_zone = None
    local_today = (now_utc.astimezone(local_zone) if local_zone is not None else now_utc).date().isoformat()
    target_key = _normalize_date_key(str(target_event_date or ""))
    features: Dict[str, Any] = {
        "source": "noaa_mrms_qpe_metadata",
        "radar_qpe_source": "NOAA_MRMS",
        "radar_qpe_product": "PrecipRate_00.00",
    }
    if target_key and target_key != local_today:
        features["radar_qpe_available"] = False
        features["radar_qpe_value_na_reason"] = "mrms_latest_not_target_event_date"
        if provenance is not None:
            provenance["feature_keys"] = sorted(features.keys())
        return features
    date_keys = [
        now_utc.strftime("%Y%m%d"),
        (now_utc - timedelta(days=1)).strftime("%Y%m%d"),
    ]
    latest = _mrms_latest_s3_object(
        MRMS_PRECIP_RATE_PREFIX,
        date_keys,
        provenance=provenance,
    )
    if not latest:
        features["radar_qpe_available"] = False
        features["radar_qpe_value_na_reason"] = "mrms_latest_file_not_found"
    else:
        key = str(latest.get("key") or "")
        features["radar_qpe_available"] = True
        features["radar_qpe_latest_key"] = key
        features["radar_qpe_latest_at"] = _mrms_key_time_iso(key)
        features["radar_qpe_source_url"] = MRMS_S3_LIST_URL + quote(key, safe="/")
        features["radar_qpe_latest_size_bytes"] = latest.get("size")
        features["radar_qpe_latest_modified_at"] = latest.get("last_modified")
        features["radar_qpe_value_na_reason"] = "mrms_grib2_decoder_unavailable"
        if _env_bool("PM_BAYES_LIKELIHOOD_FETCH_MRMS_PRECIP_ENABLED", True):
            try:
                parsed = _mrms_parsed_precip_grib_for_key(key, provenance=provenance)
                decoded = _mrms_sample_precip_from_parsed(parsed, lat, lon)
                features.update(decoded)
                features["radar_qpe_value_source"] = "noaa_mrms_precip_rate_grib2_png"
                features.pop("radar_qpe_value_na_reason", None)
            except Exception as exc:
                features["radar_qpe_value_na_reason"] = f"mrms_decode_error:{exc.__class__.__name__}"
                if provenance is not None:
                    provenance["mrms_decode_error"] = str(exc)[:200]
    if provenance is not None:
        provenance["feature_keys"] = sorted(features.keys())
    return features


def fetch_meteostat_daily_var(
    lat: float,
    lon: float,
    date: str,
    market_var: str,
    market_unit: Optional[str],
) -> Optional[float]:
    api_key = os.environ.get("METEOSTAT_API_KEY")
    if not api_key:
        return None
    headers = {
        "X-RapidAPI-Key": api_key,
        "X-RapidAPI-Host": os.environ.get("METEOSTAT_API_HOST", "meteostat.p.rapidapi.com"),
    }
    params = {"lat": lat, "lon": lon, "start": date, "end": date}
    r = requests_get(
        METEOSTAT_DAILY_URL, headers=headers, params=params, bypass_proxy=True, retries=3
    )
    if r.status_code != 200:
        return None
    data = r.json().get("data") or []
    if not data:
        return None
    row = data[0] or {}
    val = None
    if market_var == "temperature_2m_max":
        val = row.get("tmax")
        if val is not None:
            val = (val * 9.0 / 5.0 + 32.0) if market_unit == "F" else float(val)
    elif market_var == "temperature_2m_min":
        val = row.get("tmin")
        if val is not None:
            val = (val * 9.0 / 5.0 + 32.0) if market_unit == "F" else float(val)
    elif market_var in {"precipitation_sum", "snowfall_sum"}:
        key = "prcp" if market_var == "precipitation_sum" else "snow"
        val = row.get(key)
        if val is not None:
            if market_unit == "in":
                val = float(val) / 25.4
            elif market_unit == "cm":
                val = float(val) / 10.0
            else:
                val = float(val)
    elif market_var == "windspeed_10m_max":
        val = row.get("wspd")
        if val is not None:
            val = float(val)
            if market_unit == "mph":
                val = val / 1.609344
            elif market_unit == "ms":
                val = val / 3.6
    elif market_var == "pressure_msl_mean":
        val = row.get("pres")
        if val is not None:
            val = float(val)
            if market_unit == "inhg":
                val = val * 0.0295299830714
    elif market_var.startswith("relative_humidity"):
        val = row.get("rhum")
        if val is not None:
            val = float(val)
    return float(val) if val is not None else None


def _seed_from_parts(parts: List[str]) -> int:
    import hashlib

    seed_str = "|".join(parts)
    digest = hashlib.sha256(seed_str.encode("utf-8")).hexdigest()
    return int(digest[:16], 16)


