def _weather_feature_has_value(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, bool):
        return bool(value)
    if isinstance(value, (int, float)):
        return math.isfinite(float(value))
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, Mapping):
        return bool(value)
    if isinstance(value, np.ndarray):
        return bool(value.size)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return len(value) > 0
    return True


def _weather_likelihood_feature_group_availability(features: Mapping[str, Any]) -> Dict[str, Dict[str, Any]]:
    out: Dict[str, Dict[str, Any]] = {}
    for group_key in EVIDENCE_GROUPS:
        keys, default_reason = WEATHER_LIKELIHOOD_FEATURE_GROUP_KEYS.get(
            group_key,
            ((), "feature_group_missing"),
        )
        if group_key == "precipitation_evaporative_cooling":
            precip_profile = precipitation_evidence_profile(features)
            present_keys = []
            if precip_profile.get("available_strong"):
                source_field = str(precip_profile.get("source_field") or "")
                if source_field:
                    present_keys.append(source_field)
            reason = "" if present_keys else str(precip_profile.get("na_reason") or features.get("radar_qpe_value_na_reason") or default_reason)
            out[group_key] = {
                "available": bool(present_keys),
                "present_keys": present_keys[:12],
                "na_reason": reason,
                "source_profile": dict(precip_profile),
                "evidence_state": str(precip_profile.get("evidence_state") or "missing"),
            }
            continue
        present_keys: List[str] = []
        for key in keys:
            value = features.get(key)
            if key == "peak_estimator" and isinstance(value, Mapping) and not value.get("enabled"):
                continue
            if _weather_feature_has_value(value):
                present_keys.append(key)
        reason = ""
        if not present_keys:
            reason = str(features.get(f"{group_key}_na_reason") or default_reason)
            if group_key == "precipitation_evaporative_cooling":
                reason = str(features.get("radar_qpe_value_na_reason") or reason)
        out[group_key] = {
            "available": bool(present_keys),
            "present_keys": present_keys[:12],
            "na_reason": reason,
        }
    return out


def _weather_likelihood_feature_quality(features: Mapping[str, Any]) -> str:
    if not isinstance(features, Mapping) or not features:
        return "missing"
    groups = _weather_likelihood_feature_group_availability(features)
    primary_groups = [group for group in EVIDENCE_GROUPS if group != "residual_correction"]
    available_primary = sum(1 for group in primary_groups if groups.get(group, {}).get("available"))
    precip_ok = bool(groups.get("precipitation_evaporative_cooling", {}).get("available"))
    if available_primary >= 5 and precip_ok:
        return "complete"
    if available_primary >= 3:
        return "partial"
    return "minimal"


def _compact_weather_likelihood_value(value: Any, *, max_list_values: int, depth: int = 0) -> Any:
    if depth > 4:
        return None
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        fval = float(value)
        if not math.isfinite(fval):
            return None
        return int(value) if isinstance(value, int) and not isinstance(value, bool) else fval
    if isinstance(value, str):
        text = value.strip()
        return text[:500]
    if isinstance(value, np.ndarray):
        value = value.tolist()
    if isinstance(value, Mapping):
        out: Dict[str, Any] = {}
        for raw_key, raw_val in value.items():
            key = str(raw_key)
            lowered = key.lower()
            if lowered in {"raw_response", "raw_payload", "response_json", "payload_json"}:
                continue
            compact = _compact_weather_likelihood_value(
                raw_val,
                max_list_values=max_list_values,
                depth=depth + 1,
            )
            if compact is not None or raw_val is None:
                out[key] = compact
        return out
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        out_list: List[Any] = []
        for item in list(value)[:max_list_values]:
            compact = _compact_weather_likelihood_value(
                item,
                max_list_values=max_list_values,
                depth=depth + 1,
            )
            if compact is not None or item is None:
                out_list.append(compact)
        return out_list
    return str(value)[:500]


def _compact_weather_likelihood_features(
    features: Mapping[str, Any],
    *,
    max_list_values: int = 512,
) -> Dict[str, Any]:
    if not isinstance(features, Mapping) or not features:
        return {}
    out: Dict[str, Any] = {}
    for raw_key, raw_value in features.items():
        key = str(raw_key)
        lowered = key.lower()
        if lowered in {"raw_response", "raw_payload", "response_json", "payload_json"}:
            continue
        compact = _compact_weather_likelihood_value(
            raw_value,
            max_list_values=max(1, int(max_list_values)),
        )
        if compact is not None or raw_value is None:
            out[key] = compact
        if (
            isinstance(raw_value, Sequence)
            and not isinstance(raw_value, (str, bytes, bytearray))
            and len(raw_value) > max_list_values
        ):
            out[f"{key}_truncated_count"] = int(len(raw_value) - max_list_values)
    return out


def default_expand_sigma(market_var: str, market_unit: Optional[str]) -> float:
    unit = normalize_unit(market_unit) or ""
    if market_var.startswith("temperature_2m"):
        return 2.7 if unit == "F" else 1.5
    if market_var.startswith("relative_humidity"):
        return 5.0
    if market_var == "windspeed_10m_max":
        if unit == "mph":
            return 4.5
        if unit == "kmh":
            return 7.2
        return 2.0  # m/s
    if market_var == "pressure_msl_mean":
        return 0.06 if unit == "inhg" else 2.0
    if market_var == "visibility_mean":
        if unit == "mi":
            return 1.2
        if unit == "m":
            return 2000.0
        if unit == "km":
            return 2.0
        return 2.0  # km
    if market_var in ("precipitation_sum", "snowfall_sum"):
        if unit == "cm":
            return 0.2
        if unit == "in":
            return 0.08
        if unit == "mm":
            return 2.0
        return 2.0  # mm
    return 1.0


def expand_members(
    values: np.ndarray,
    target_size: int,
    sigma: float,
    seed: int,
) -> np.ndarray:
    if values.size >= target_size or target_size <= 0 or sigma <= 0:
        return values
    rng = np.random.default_rng(seed)
    base = rng.choice(values, size=target_size, replace=True)
    jitter = rng.normal(0.0, sigma, size=target_size)
    return base + jitter


def filter_members_by_bounds(values: np.ndarray, market_var: Optional[str]) -> np.ndarray:
    if not market_var:
        return values
    if market_var.startswith("relative_humidity"):
        return values[(values >= 0.0) & (values <= 100.0)]
    if market_var in {
        "precipitation_sum",
        "snowfall_sum",
        "windspeed_10m_max",
        "visibility_mean",
        "pressure_msl_mean",
    }:
        return values[values >= 0.0]
    return values


def clamp_members(values: np.ndarray, market_var: Optional[str]) -> np.ndarray:
    if not market_var:
        return values
    if market_var.startswith("relative_humidity"):
        return np.clip(values, 0.0, 100.0)
    if market_var in {
        "precipitation_sum",
        "snowfall_sum",
        "windspeed_10m_max",
        "visibility_mean",
        "pressure_msl_mean",
    }:
        return np.maximum(values, 0.0)
    return values


def _build_weather_likelihood_features(
    *,
    model_members: Mapping[str, Any],
    market_var: Optional[str],
    market_unit: Optional[str],
    observed_nowcast_value: Optional[float] = None,
    observed_nowcast_share: float = 0.0,
    observed_nowcast_source: Optional[str] = None,
    auxiliary_features: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Build the standard read-only feature payload consumed by Bayes likelihood."""

    if str(market_var or "") != "temperature_2m_max":
        return {}
    values: List[float] = []
    for raw in (model_members or {}).values():
        try:
            arr = np.asarray(raw, dtype=float)
        except Exception:
            continue
        for val in arr.flatten():
            try:
                fval = float(val)
            except Exception:
                continue
            if math.isfinite(fval):
                values.append(fval)
    if not values:
        return {}
    features: Dict[str, Any] = {
        "unit": normalize_unit(market_unit) or "",
        "market_unit": normalize_unit(market_unit) or "",
        "market_var": str(market_var or ""),
        "forecast_peak_temp": float(np.median(np.asarray(values, dtype=float))),
        "model_peak_temps": values,
        "temperature_distribution": values,
        "source": "scan_model_members",
    }
    obs = to_float(observed_nowcast_value)
    if (
        obs is not None
        and math.isfinite(obs)
        and observed_nowcast_share is not None
        and float(observed_nowcast_share) > 0
    ):
        obs_source = str(observed_nowcast_source or "observed_nowcast").strip() or "observed_nowcast"
        unit = normalize_unit(market_unit) or ""
        features["observed_temp"] = float(obs)
        features["observed_temp_source"] = obs_source
        features["observed_nowcast_share"] = max(0.0, min(1.0, float(observed_nowcast_share)))
        if unit == "C":
            features["observed_temp_c"] = float(obs)
            if str(market_var or "") == "temperature_2m_max" and (
                "history" in obs_source
                or "daily" in obs_source
                or "max_since7am" in obs_source
            ):
                features["observed_today_max_c"] = float(obs)
                features["observed_today_max_source"] = obs_source
                features["observed_today_max_trusted"] = True
        elif unit == "F" and str(market_var or "") == "temperature_2m_max" and (
            "history" in obs_source
            or "daily" in obs_source
            or "max_since7am" in obs_source
        ):
            features["observed_today_max_c"] = (float(obs) - 32.0) * 5.0 / 9.0
            features["observed_today_max_source"] = obs_source
            features["observed_today_max_trusted"] = True
    if isinstance(auxiliary_features, Mapping):
        aux_source = str(auxiliary_features.get("source") or "").strip()
        aux_is_zuuu_awc = bool(auxiliary_features.get("zuuu_metar_raw_awc_available")) or aux_source == "zuuu_metar_raw_awc"
        aux_is_wu_twc_observed = (
            bool(auxiliary_features.get("wu_twc_observed_intraday_available"))
            or aux_source == "wu_twc_observed_intraday"
        )
        observed_lock_keys = {
            "observed_temp",
            "observed_temp_c",
            "current_temp",
            "current_temp_c",
            "temperature_now",
            "temperature_now_c",
            "observed_today_max_c",
            "observed_today_max_source",
            "observed_today_max_trusted",
        }
        for key, value in auxiliary_features.items():
            if key in {"source", "unit", "market_unit", "market_var"}:
                continue
            if (
                observed_nowcast_source
                and key
                in observed_lock_keys
                and _weather_feature_has_value(features.get(str(key)))
                and not aux_is_zuuu_awc
                and not aux_is_wu_twc_observed
            ):
                continue
            features[str(key)] = value
        if aux_source:
            features["auxiliary_source"] = aux_source
        _promote_hard_observation_path_features(features)
    for group_key, (keys, reason) in WEATHER_LIKELIHOOD_FEATURE_GROUP_KEYS.items():
        if not any(_weather_feature_has_value(features.get(key)) for key in keys):
            if group_key == "precipitation_evaporative_cooling":
                reason = str(features.get("radar_qpe_value_na_reason") or reason)
            features[f"{group_key}_na_reason"] = reason
    if _env_bool("PM_BAYES_PEAK_ESTIMATOR_ENABLED", True):
        peak_meta = estimate_peak_temperature_from_features(features)
        features["peak_estimator"] = peak_meta
        features["peak_estimator_enabled"] = bool(peak_meta.get("enabled")) if isinstance(peak_meta, Mapping) else False
        features["peak_estimator_source"] = str(peak_meta.get("source") or "") if isinstance(peak_meta, Mapping) else ""
        if isinstance(peak_meta, Mapping) and peak_meta.get("enabled"):
            for meta_key, feature_key in (
                ("mu_c", "peak_estimator_mu_c"),
                ("sigma_c", "peak_estimator_sigma_c"),
                ("kalman_gain", "peak_estimator_kalman_gain"),
                ("extrapolation_c", "peak_estimator_extrapolation_c"),
                ("combined_discount", "peak_estimator_combined_discount"),
                ("peak_window_start_hour_local", "peak_window_start_hour_local"),
                ("peak_window_end_hour_local", "peak_window_end_hour_local"),
                ("hours_to_peak_window", "hours_to_peak_window"),
                ("lock_threshold_hour_local", "lock_threshold_hour_local"),
                (
                    "temperature_momentum_context_effective_c_per_hour",
                    "temperature_momentum_context_effective_c_per_hour",
                ),
            ):
                meta_val = to_float(peak_meta.get(meta_key))
                if meta_val is not None and math.isfinite(meta_val):
                    features[feature_key] = float(meta_val)
            for meta_key, feature_key in (
                ("temperature_momentum_context_warming_watch", "temperature_momentum_context_warming_watch"),
                ("temperature_momentum_realization_state", "temperature_momentum_realization_state"),
            ):
                meta_val = peak_meta.get(meta_key)
                if meta_val not in (None, ""):
                    features[feature_key] = meta_val
    return features


def round_half_up(x: float) -> int:
    return int(math.floor(x + 0.5)) if x >= 0 else int(math.ceil(x - 0.5))


def trunc_toward_zero(x: float) -> int:
    return int(math.trunc(x))


def map_to_int(values: np.ndarray, mode: str) -> np.ndarray:
    if mode == "round":
        return np.array([round_half_up(x) for x in values], dtype=int)
    if mode == "trunc":
        return np.array([trunc_toward_zero(x) for x in values], dtype=int)
    if mode == "floor":
        return np.floor(values).astype(int)
    if mode == "ceil":
        return np.ceil(values).astype(int)
    raise ValueError("mode must be round|floor|ceil")


def _canonical_bucket_rounding_rule(rule: Optional[str]) -> str:
    raw = str(rule or "").strip().lower()
    if raw in {"whole_degrees", "floor", "floor_degrees"}:
        return "whole_degrees"
    if raw in {"rounded_degrees", "round", "nearest", "nearest_whole"}:
        return "rounded_degrees"
    if raw in {"ceil", "ceiling", "ceiling_degrees"}:
        return "ceiling_degrees"
    return raw


def model_member_bucket_rule_meta(
    settlement_rounding_rule: Optional[str],
    *,
    market_var: Optional[str] = None,
    market_unit: Optional[str] = None,
    resolution_source: Optional[str] = None,
) -> Dict[str, Any]:
    configured = str(os.environ.get("PM_MODEL_MEMBER_BUCKET_RULE") or "source_aligned").strip().lower()
    settlement_rule = _canonical_bucket_rounding_rule(settlement_rounding_rule)
    unit = normalize_unit(market_unit or "")
    is_temperature = str(market_var or "").startswith("temperature") and unit in {"C", "F", None, ""}
    if configured in {"", "source_aligned", "settlement_source", "auto"}:
        if is_temperature and settlement_rule == "whole_degrees":
            rule = "rounded_degrees"
            reason = "source_aligned_whole_degree_display_uses_nearest_integer_for_model_members"
        else:
            rule = settlement_rule or "rounded_degrees"
            reason = "source_aligned_to_settlement_rule"
    elif configured in {"settlement", "contract", "hard_source"}:
        rule = settlement_rule or "whole_degrees"
        reason = "forced_contract_settlement_rule"
    else:
        rule = _canonical_bucket_rounding_rule(configured)
        if rule not in {"whole_degrees", "rounded_degrees", "ceiling_degrees"}:
            rule = "rounded_degrees"
            reason = "invalid_config_fallback_to_rounded_degrees"
        else:
            reason = "explicit_config"
    return {
        "rounding_rule": rule,
        "settlement_rounding_rule": settlement_rule or str(settlement_rounding_rule or ""),
        "configured": configured or "source_aligned",
        "reason": reason,
        "market_var": str(market_var or ""),
        "market_unit": str(market_unit or ""),
        "resolution_source": str(resolution_source or ""),
        "role": "model_member_bucket_probability_not_hard_settlement",
    }


@dataclass
class OutcomeSpec:
    label: str
    kind: str  # "eq" | "le" | "ge" | "range"
    k: float
    k2: Optional[float]
    unit: Optional[str]
    precision: int


def normalize_unit(unit: Optional[str]) -> Optional[str]:
    if not unit:
        return None
    u = unit.strip().lower()
    u = u.replace("°", "")
    if u in {"c", "celsius"}:
        return "C"
    if u in {"f", "fahrenheit"}:
        return "F"
    if u in {"%", "percent", "percentage"}:
        return "%"
    if u in {"mph"}:
        return "mph"
    if u in {"km/h", "kmh", "kph"}:
        return "kmh"
    if u in {"m/s", "ms"}:
        return "ms"
    if u in {"in", "inch", "inches"}:
        return "in"
    if u in {"mm"}:
        return "mm"
    if u in {"cm"}:
        return "cm"
    if u in {"hpa", "mb", "mbar"}:
        return "hpa"
    if u in {"inhg", "in hg"}:
        return "inhg"
    if u in {"m"}:
        return "m"
    if u in {"km"}:
        return "km"
    if u in {"mi", "mile", "miles"}:
        return "mi"
    return unit.strip()


def decimal_places(num_str: str) -> int:
    if "." in num_str:
        return len(num_str.split(".")[1])
    return 0


def parse_outcome_label(label: str) -> OutcomeSpec:
    raw = label.strip()
    normalized = raw.replace("–", "-")
    num = r"(-?\d+(?:\.\d+)?)"
    unit = r"([A-Za-z°/%]+)?"

    m = re.match(rf"^{num}\s*-\s*{num}\s*{unit}$", normalized)
    if m:
        u = normalize_unit(m.group(3))
        p1 = decimal_places(m.group(1))
        p2 = decimal_places(m.group(2))
        return OutcomeSpec(raw, "range", float(m.group(1)), float(m.group(2)), u, max(p1, p2))

    m = re.match(rf"^{num}\s+to\s+{num}\s*{unit}$", normalized, flags=re.I)
    if m:
        u = normalize_unit(m.group(3))
        p1 = decimal_places(m.group(1))
        p2 = decimal_places(m.group(2))
        return OutcomeSpec(raw, "range", float(m.group(1)), float(m.group(2)), u, max(p1, p2))

    m = re.match(rf"^{num}\s*{unit}\s+or\s+below$", normalized, flags=re.I)
    if m:
        u = normalize_unit(m.group(2))
        return OutcomeSpec(raw, "le", float(m.group(1)), None, u, decimal_places(m.group(1)))

    m = re.match(rf"^{num}\s*{unit}\s+or\s+(higher|above|more)$", normalized, flags=re.I)
    if m:
        u = normalize_unit(m.group(2))
        return OutcomeSpec(raw, "ge", float(m.group(1)), None, u, decimal_places(m.group(1)))

    m = re.match(rf"^{num}\s*{unit}$", normalized)
    if m:
        u = normalize_unit(m.group(2))
        return OutcomeSpec(raw, "eq", float(m.group(1)), None, u, decimal_places(m.group(1)))

    raise ValueError(f"Unsupported outcome label format: {label}")


def prob_for_outcome(values: np.ndarray, spec: OutcomeSpec) -> float:
    if spec.kind == "eq":
        tol = 0.5 * (10 ** (-spec.precision)) if spec.precision >= 0 else 0.5
        return float(np.mean(np.abs(values - spec.k) <= tol))
    if spec.kind == "le":
        return float(np.mean(values <= spec.k))
    if spec.kind == "ge":
        return float(np.mean(values >= spec.k))
    if spec.kind == "range" and spec.k2 is not None:
        return float(np.mean((values >= spec.k) & (values <= spec.k2)))
    raise ValueError("bad spec.kind")


def _parse_date(value: Optional[str]) -> Optional[datetime.date]:
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value)).date()
    except Exception:
        return None


def _parse_entry_time_thresholds(raw: Optional[str]) -> List[Dict[str, float]]:
    if not raw:
        return []
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        return []
    if not isinstance(payload, list):
        return []
    tiers: List[Dict[str, float]] = []
    for item in payload:
        if not isinstance(item, dict):
            continue
        max_days = item.get("max_days")
        try:
            max_days_val = int(max_days) if max_days is not None else None
        except (TypeError, ValueError):
            max_days_val = None
        if max_days_val is None:
            continue
        edge_min = to_float(item.get("edge_score_min"))
        signal_min = to_float(item.get("entry_signal_edge_min"))
        if edge_min is None and signal_min is None:
            continue
        tiers.append(
            {
                "max_days": max_days_val,
                "edge_score_min": edge_min,
                "entry_signal_edge_min": signal_min,
            }
        )
    tiers.sort(key=lambda t: int(t.get("max_days") or 0))
    return tiers


def _resolve_entry_time_thresholds(
    days_to_event: Optional[int],
    base_edge_score_min: float,
    base_signal_edge_min: float,
    tiers: List[Dict[str, float]],
) -> Tuple[float, float, Optional[Dict[str, float]]]:
    if days_to_event is None or not tiers:
        return base_edge_score_min, base_signal_edge_min, None
    selected: Optional[Dict[str, float]] = None
    for tier in tiers:
        max_days = int(tier.get("max_days") or 0)
        if days_to_event <= max_days:
            selected = tier
            break
    if selected is None:
        selected = tiers[-1]
    edge_min = base_edge_score_min
    signal_min = base_signal_edge_min
    val = to_float(selected.get("edge_score_min")) if selected else None
    if val is not None and math.isfinite(val):
        edge_min = float(val)
    val = to_float(selected.get("entry_signal_edge_min")) if selected else None
    if val is not None and math.isfinite(val):
        signal_min = float(val)
    return edge_min, signal_min, selected


def _bucket_is_integer(label: str) -> Optional[bool]:
    if not label:
        return None
    try:
        spec = parse_outcome_label(label)
    except Exception:
        return None
    values = []
    for val in (spec.k, spec.k2):
        if val is None:
            continue
        try:
            fval = float(val)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(fval):
            continue
        values.append(fval)
    if not values:
        return None
    for val in values:
        if abs(val - round(val)) > 1e-6:
            return False
    return True


def _detect_region(lat: Optional[float], lon: Optional[float]) -> str:
    """
    根据经纬度判断地区

    返回值：
    - "usa": 美国本土
    - "europe": 欧洲
    - "asia": 亚洲
    - "other": 其他地区
    """
    if lat is None or lon is None:
        return "other"

    try:
        lat_f = float(lat)
        lon_f = float(lon)
    except (TypeError, ValueError):
        return "other"

    # 美国本土：纬度25-50，经度-125到-65
    if 25 <= lat_f <= 50 and -125 <= lon_f <= -65:
        return "usa"

    # 欧洲：纬度35-70，经度-10到40
    if 35 <= lat_f <= 70 and -10 <= lon_f <= 40:
        return "europe"

    # 亚洲东部：纬度-10到55，经度60到150
    if -10 <= lat_f <= 55 and 60 <= lon_f <= 150:
        return "asia"

    return "other"


def scenario_stage(
    run_date: Optional[str],
    event_date: Optional[str],
    rounding_rule: Optional[str],
    market_unit: Optional[str],
    bucket_labels: Optional[list] = None,
    lat: Optional[float] = None,
    lon: Optional[float] = None,
) -> str:
    """
    确定场景阶段（地区+时间组合）

    返回格式：
    - "{region}_{time_stage}": 例如 "usa_late", "europe_mid"
    - "{time_stage}": 如果无法确定地区，fallback到纯时间场景
    """
    # 1. 检测地区
    region = _detect_region(lat, lon)

    # 2. 计算距离事件的天数
    run_dt = _parse_date(run_date)
    event_dt = _parse_date(event_date)
    days_to_event = None
    if run_dt and event_dt:
        days_to_event = (event_dt - run_dt).days

    # 3. 判断是否整数温度市场
    integer_bucket = False
    if bucket_labels:
        seen = False
        all_integer = True
        for label in bucket_labels:
            parsed = _bucket_is_integer(label or "")
            if parsed is None:
                continue
            seen = True
            if not parsed:
                all_integer = False
                break
        integer_bucket = bool(seen and all_integer)

    # 4. 确定时间阶段
    if days_to_event is not None and days_to_event <= 1:
        time_stage = "late"
    elif (
        days_to_event is not None
        and 2 <= days_to_event <= 4
        and ((rounding_rule or "") == "whole_degrees" or integer_bucket)
    ):
        time_stage = "integer"
    elif days_to_event is not None and days_to_event <= 4:
        time_stage = "mid"
    else:
        time_stage = "early"

    # 5. 组合地区+时间
    if region and region != "other":
        combined = f"{region}_{time_stage}"
        # 检查是否存在该组合的权重配置
        if combined in SCENARIO_WEIGHTS:
            return combined
        # 如果没有该组合，尝试使用地区的默认配置
        region_default = f"{region}_mid"
        if region_default in SCENARIO_WEIGHTS:
            return region_default

    # 6. Fallback到纯时间场景（向后兼容）
    return time_stage


def scenario_weights(
    models: List[str],
    run_date: Optional[str],
    event_date: Optional[str],
    rounding_rule: Optional[str],
    market_unit: Optional[str],
    bucket_labels: Optional[list] = None,
    lat: Optional[float] = None,
    lon: Optional[float] = None,
) -> Dict[str, float]:
    if not models:
        return {}
    stage = scenario_stage(run_date, event_date, rounding_rule, market_unit, bucket_labels, lat, lon)
    base = SCENARIO_WEIGHTS.get(stage, {})
    weights = {m: float(base.get(m, 0.0)) for m in models}
    total = sum(weights.values())
    if total <= 0:
        w = 1.0 / len(models)
        return {m: w for m in models}
    return {m: (weights[m] / total) for m in models}


def compute_q_band(values: np.ndarray, spec: OutcomeSpec, rounding_rule: Optional[str]) -> Dict[str, Any]:
    rule = _canonical_bucket_rounding_rule(rounding_rule)
    if rule in {"whole_degrees", "rounded_degrees", "ceiling_degrees"} and spec.unit in {"C", "F"}:
        q_floor = prob_for_outcome(map_to_int(values, "floor"), spec)
        q_nearest = prob_for_outcome(map_to_int(values, "round"), spec)
        q_ceil = prob_for_outcome(map_to_int(values, "ceil"), spec)
        if rule == "whole_degrees":
            q_round = q_floor
        elif rule == "ceiling_degrees":
            q_round = q_ceil
        else:
            q_round = q_nearest
        q_min = min(q_floor, q_nearest, q_ceil)
        q_max = max(q_floor, q_nearest, q_ceil)
        return {
            "q_round": q_round,
            "q_floor": q_floor,
            "q_ceil": q_ceil,
            "q_min": q_min,
            "q_max": q_max,
            "q_nearest": q_nearest,
            "bucket_rounding_rule": rule,
        }
    q_raw = prob_for_outcome(values, spec)
    return {
        "q_round": q_raw,
        "q_floor": q_raw,
        "q_ceil": q_raw,
        "q_min": q_raw,
        "q_max": q_raw,
        "q_nearest": q_raw,
        "bucket_rounding_rule": rule,
    }


def atomic_temperature_outcome_spec(spec: OutcomeSpec) -> OutcomeSpec:
    if spec.kind in {"le", "ge"} and spec.unit in {"C", "F"}:
        return OutcomeSpec(spec.label, "eq", float(spec.k), None, spec.unit, spec.precision)
    return spec


def observed_nowcast_bucket_weight(
    observed_value: Optional[float],
    spec: OutcomeSpec,
    rounding_rule: Optional[str],
    market_var: Optional[str],
    *,
    base_prob: Optional[float] = None,
) -> Optional[float]:
    obs = to_float(observed_value)
    if obs is None or not math.isfinite(float(obs)):
        return None
    if str(market_var or "") == "temperature_2m_max":
        threshold = math.floor(float(obs)) if rounding_rule == "whole_degrees" and spec.unit in {"C", "F"} else float(obs)
        if spec.kind == "eq":
            possible = float(spec.k) >= threshold
        elif spec.kind == "le":
            possible = float(spec.k) >= threshold
        elif spec.kind == "ge":
            possible = True
        elif spec.kind == "range" and spec.k2 is not None:
            possible = max(float(spec.k), float(spec.k2)) >= threshold
        else:
            possible = True
        return 1.0 if possible else 0.0
    if str(market_var or "") == "temperature_2m_min":
        threshold = math.floor(float(obs)) if rounding_rule == "whole_degrees" and spec.unit in {"C", "F"} else float(obs)
        if spec.kind == "eq":
            possible = float(spec.k) <= threshold
        elif spec.kind == "ge":
            possible = float(spec.k) <= threshold
        elif spec.kind == "le":
            possible = True
        elif spec.kind == "range" and spec.k2 is not None:
            possible = min(float(spec.k), float(spec.k2)) <= threshold
        else:
            possible = True
        return 1.0 if possible else 0.0
    obs_band = compute_q_band(np.array([float(obs)], dtype=float), spec, rounding_rule)
    return float(obs_band.get("q_round") or 0.0)


def suggest_limit_price(
    best_bid: Optional[float],
    best_ask: Optional[float],
    q_min: float,
    limit_discount: float,
) -> Optional[Tuple[float, float]]:
    if best_ask is None:
        return None
    cap = min(q_min, best_ask) * limit_discount
    if best_bid is None:
        return (max(0.0, cap * 0.5), cap)
    low = best_bid + 0.001
    high = cap
    if high <= low:
        return None
    return (low, high)


def tradeable_flags(
    best_ask: Optional[float], spread: Optional[float], max_ask: float, max_spread: float
) -> List[str]:
    flags = []
    if best_ask is None:
        flags.append("no_ask")
    elif best_ask >= max_ask:
        flags.append("ask")
    if spread is None:
        flags.append("no_spread")
    elif spread >= max_spread:
        flags.append("spr")
    return flags


def apply_rounding(actual: float, rounding_rule: Optional[str], unit: Optional[str]) -> float:
    if rounding_rule == "whole_degrees" and unit in {"C", "F"}:
        return float(math.floor(actual))
    return actual


def infer_market_variable(title: Optional[str], slug: str) -> Optional[str]:
    text = " ".join([title or "", slug]).lower()
    if "global land-ocean temperature index" in text or "gistemp" in text:
        return "global_temp_anomaly"
    if "temperature" in text:
        if "lowest" in text or "low" in text:
            return "temperature_2m_min"
        return "temperature_2m_max"
    if any(k in text for k in ["rain", "precipitation", "rainfall"]):
        return "precipitation_sum"
    if "snow" in text:
        return "snowfall_sum"
    if any(k in text for k in ["wind", "gust"]):
        return "windspeed_10m_max"
    if "humidity" in text:
        if "lowest" in text or "low" in text:
            return "relative_humidity_2m_min"
        if "highest" in text or "high" in text:
            return "relative_humidity_2m_max"
        return "relative_humidity_2m_mean"
    if any(k in text for k in ["pressure", "barometric"]):
        return "pressure_msl_mean"
    if "visibility" in text:
        return "visibility_mean"
    return None


def is_temperature_market_var(var: Optional[str]) -> bool:
    if not var:
        return False
    if var.startswith("temperature"):
        return True
    if var == "global_temp_anomaly":
        return True
    return False


def is_event_closed_flag(event: Optional[Dict[str, Any]]) -> bool:
    if not event:
        return False
    if event.get("closed") is True:
        return True
    if event.get("active") is False:
        return True
    status = str(event.get("status") or "").lower()
    if status in ("closed", "resolved", "settled"):
        return True
    return False


def is_effectively_closed_distribution(rows: List[Dict[str, Any]]) -> bool:
    asks: List[float] = []
    for row in rows:
        ask = to_float(row.get("best_ask"))
        if ask is None:
            continue
        asks.append(float(ask))
    if len(asks) < 2:
        return False
    asks.sort(reverse=True)
    return asks[0] >= 0.98 and asks[1] <= 0.02


def infer_market_unit(outcomes: List[str], var: str) -> Optional[str]:
    for label in outcomes:
        try:
            spec = parse_outcome_label(label)
        except ValueError:
            continue
        if spec.unit:
            return spec.unit
    if var.startswith("temperature"):
        return "C"
    if var == "global_temp_anomaly":
        return "C"
    if var.startswith("windspeed"):
        return "kmh"
    if var in {"precipitation_sum", "snowfall_sum"}:
        return "mm"
    if var.startswith("relative_humidity"):
        return "%"
    if var.startswith("pressure"):
        return "hpa"
    if var.startswith("visibility"):
        return "km"
    return None


def infer_unit_params(market_unit: Optional[str], var: str) -> Dict[str, str]:
    params: Dict[str, str] = {}
    if var.startswith("temperature"):
        if market_unit == "F":
            params["temperature_unit"] = "fahrenheit"
    if var.startswith("windspeed"):
        if market_unit == "mph":
            params["windspeed_unit"] = "mph"
        elif market_unit == "ms":
            params["windspeed_unit"] = "ms"
        elif market_unit == "kmh":
            params["windspeed_unit"] = "kmh"
    if var in {"precipitation_sum", "snowfall_sum"}:
        if market_unit == "in":
            params["precipitation_unit"] = "inch"
        elif market_unit == "mm":
            params["precipitation_unit"] = "mm"
    return params


def _open_meteo_source_unit_from_params(
    var: Optional[str],
    unit_params: Optional[Mapping[str, str]],
) -> str:
    params = unit_params if isinstance(unit_params, Mapping) else {}
    name = str(var or "")
    if name.startswith("temperature"):
        return "F" if str(params.get("temperature_unit") or "").lower() == "fahrenheit" else "C"
    if name.startswith("windspeed"):
        raw = str(params.get("windspeed_unit") or "").lower()
        if raw == "mph":
            return "mph"
        if raw == "ms":
            return "m/s"
        if raw == "kmh" or not raw:
            return "km/h"
    if name in {"precipitation_sum", "snowfall_sum"}:
        raw = str(params.get("precipitation_unit") or "").lower()
        return "in" if raw == "inch" else "mm"
    if name.startswith("pressure"):
        return "hPa"
    if name.startswith("visibility"):
        return "m"
    return normalize_unit(None) or ""


def _dual_temperature_unit_params(unit_params: Optional[Mapping[str, str]]) -> Optional[Dict[str, str]]:
    params = dict(unit_params or {})
    current = str(params.get("temperature_unit") or "celsius").lower()
    dual = dict(params)
    if current == "fahrenheit":
        dual["temperature_unit"] = "celsius"
    else:
        dual["temperature_unit"] = "fahrenheit"
    return dual


def _finite_member_stats(values: Any) -> Dict[str, Any]:
    try:
        arr = np.asarray(values, dtype=float)
    except Exception:
        return {"count": 0}
    finite = arr[np.isfinite(arr)]
    if finite.size <= 0:
        return {"count": 0}
    sample = [float(x) for x in finite.flatten()[:8]]
    return {
        "count": int(finite.size),
        "min": float(np.min(finite)),
        "max": float(np.max(finite)),
        "mean": float(np.mean(finite)),
        "median": float(np.median(finite)),
        "sample": sample,
    }


def convert_values(values: np.ndarray, market_unit: Optional[str], var: str) -> np.ndarray:
    if market_unit == "cm" and var in {"precipitation_sum", "snowfall_sum"}:
        return values / 10.0
    if market_unit == "inhg" and var.startswith("pressure"):
        return values * 0.0295299830714
    if market_unit == "km" and var.startswith("visibility"):
        return values / 1000.0
    if market_unit == "mi" and var.startswith("visibility"):
        return values / 1609.344
    return values


def outcome_labels_from_tokens(tokens: List[Dict[str, Optional[str]]]) -> List[str]:
    return [t["label"] for t in tokens]


def _normalize_station_code(value: Optional[str]) -> Optional[str]:
    text = str(value or "").strip().upper()
    if not text:
        return None
    text = re.sub(r"[^A-Z0-9]", "", text)
    if not re.match(r"^[A-Z0-9]{3,6}$", text):
        return None
    return text


def parse_station_from_resolution_source(url: Optional[str]) -> Optional[str]:
    source = str(url or "").strip()
    if not source:
        return None
    parsed = urlparse(source)
    host = parsed.netloc.lower()
    path = parsed.path or ""
    query_pairs = dict(parse_qsl(parsed.query or "", keep_blank_values=True))
    is_us_weather_gov = host == "weather.gov" or host.endswith(".weather.gov")
    is_noaa = host == "noaa.gov" or host.endswith(".noaa.gov")
    for key in (
        "station",
        "stationid",
        "station_id",
        "stationId",
        "site",
        "stid",
        "icao",
        "id",
    ):
        if key in query_pairs:
            station = _normalize_station_code(query_pairs.get(key))
            if station:
                return station
    if "wunderground.com" in host and re.search(r"/history/daily/.+", path):
        try:
            source_path = source.split("wunderground.com", 1)[1]
        except IndexError:
            source_path = path
        parts = [p for p in source_path.split("/") if p]
        if parts:
            last = parts[-1]
            last = re.sub(r"[^A-Za-z0-9]+$", "", last)
            station = _normalize_station_code(last)
            if station:
                return station
    if "wunderground.com" in host and re.search(r"/(?:weather|hourly|dashboard/pws)/.+", path):
        try:
            source_path = source.split("wunderground.com", 1)[1]
        except IndexError:
            source_path = path
        parts = [p for p in source_path.split("/") if p]
        if parts:
            last = re.sub(r"[^A-Za-z0-9]+$", "", parts[-1])
            station = _normalize_station_code(last)
            if station:
                return station
    if is_us_weather_gov or is_noaa:
        candidates = re.findall(r"\b[A-Z0-9]{3,6}\b", source.upper())
        ignored = {
            "HTTPS",
            "HTTP",
            "NOAA",
            "NWS",
            "WRH",
            "TIME",
            "SERIES",
            "TIMESERIES",
            "WEATHER",
            "GOV",
            "WWW",
        }
        for candidate in candidates:
            if candidate in ignored:
                continue
            station = _normalize_station_code(candidate)
            if station:
                return station
    return None


def weather_resolution_source_profile(
    resolution_source: Optional[str],
    *,
    station_id: Optional[str] = None,
    description: Optional[str] = None,
) -> Dict[str, Any]:
    source = str(resolution_source or "").strip()
    parsed = urlparse(source) if source else None
    host = (parsed.netloc.lower() if parsed else "")
    path = (parsed.path or "").lower() if parsed else ""
    desc = str(description or "").lower()
    expected_station = _normalize_station_code(station_id)
    source_station = parse_station_from_resolution_source(source)
    station = expected_station or source_station
    station_match: Optional[bool] = None
    if expected_station and not source_station:
        station_match = False
    station_match_reason = ""
    is_hko = host == "weather.gov.hk" or host.endswith(".weather.gov.hk")
    is_us_weather_gov = host == "weather.gov" or host.endswith(".weather.gov")
    is_noaa = host == "noaa.gov" or host.endswith(".noaa.gov")
    kind = "unknown"
    cadence = ""
    confidence = 0.0
    source_fit_tier = "unknown"
    usable_for_settlement = False
    aux_only = False
    na_reason = ""
    if is_hko and "/cis/climat" in path:
        kind = "hong_kong_observatory_daily_extract"
        cadence = "daily_extract_finalized"
        confidence = 0.95
        source_fit_tier = "settlement_source"
        usable_for_settlement = True
        station = HKO_OBSERVATORY_ID
    elif "wunderground.com" in host and "/history/daily/" in path:
        kind = "wunderground_history"
        cadence = "daily_history_finalized"
        confidence = 0.95
        source_fit_tier = "settlement_source"
        usable_for_settlement = True
    elif "wunderground.com" in host:
        # WU non-history pages often show private stations or nearby averages.
        kind = "wunderground_aux"
        cadence = "auxiliary_private_station_or_nearby_average"
        confidence = 0.25
        source_fit_tier = "auxiliary_only"
        aux_only = True
        na_reason = "wu_non_history_source"
    elif is_us_weather_gov and "/wrh/timeseries" in path:
        kind = "weather_gov_timeseries"
        cadence = "observation_timeseries"
        confidence = 0.95
        source_fit_tier = "settlement_source"
        usable_for_settlement = True
    elif host == "forecast.weather.gov" or (is_us_weather_gov and "timeseries" not in path):
        kind = "weather_gov_forecast"
        cadence = "forecast_or_station_page"
        confidence = 0.45
        source_fit_tier = "auxiliary_only"
        usable_for_settlement = False
        aux_only = True
        na_reason = "weather_gov_not_timeseries"
    elif is_noaa:
        kind = "noaa"
        cadence = "noaa_observation_or_document"
        confidence = 0.85
        source_fit_tier = "rule_source_candidate"
        usable_for_settlement = bool(station)
    if expected_station and source_station and expected_station != source_station:
        station_match = False
        usable_for_settlement = False
        source_fit_tier = "station_mismatch"
        confidence = min(float(confidence), 0.20)
        na_reason = "resolution_station_mismatch"
        station_match_reason = "expected_station_does_not_match_resolution_source"
    elif expected_station and source_station and expected_station == source_station:
        station_match = True
        station_match_reason = "expected_station_matches_resolution_source"
    elif expected_station and not source_station and source:
        usable_for_settlement = False
        if not na_reason:
            na_reason = "resolution_source_station_missing"
        station_match_reason = "resolution_source_station_missing"
    elif source_station:
        station_match_reason = "resolution_source_station_parsed"
    if source and not station:
        usable_for_settlement = False
        if not na_reason:
            na_reason = "station_id_missing"
    if not source:
        na_reason = "resolution_source_missing"
    if "final" in desc and not cadence:
        cadence = "finalized_data_only"
    return {
        "source_kind": kind,
        "station_id": station or "",
        "source_confidence": float(confidence),
        "source_fit_tier": source_fit_tier,
        "source_trust_tier": source_fit_tier,
        "source_usable_for_settlement": bool(usable_for_settlement),
        "source_station_id": source_station or "",
        "source_station_expected": expected_station or "",
        "source_station_match": station_match,
        "source_station_match_reason": station_match_reason,
        "source_aux_only": bool(aux_only),
        "publication_cadence": cadence,
        "source_na_reason": na_reason,
    }


def extract_resolution_source_from_text(text: Optional[str]) -> Optional[str]:
    if not text:
        return None
    urls = re.findall(r"https?://[^\s<>'\"]+", str(text), flags=re.I)
    preferred: List[str] = []
    fallback: List[str] = []
    for raw_url in urls:
        url = raw_url.strip().strip("'\"")
        url = url.rstrip(").,;]")
        low = url.lower()
        if "wunderground.com/history/daily/" in low:
            preferred.append(url)
        elif "weather.gov/wrh/timeseries" in low or "forecast.weather.gov" in low:
            preferred.append(url)
        elif "weather.gov" in low or "noaa.gov" in low:
            fallback.append(url)
    if preferred:
        return preferred[0]
    if fallback:
        return fallback[0]
    return None


def parse_rounding_rule(description: Optional[str]) -> Optional[str]:
    if not description:
        return None
    text = description.lower()
    if (
        "whole degrees" in text
        or "whole degree" in text
        or "whole-degree" in text
        or "integer degrees" in text
        or "integer degree" in text
    ):
        return "whole_degrees"
    return None


def build_weather_contract_profile(
    *,
    title: Optional[str],
    slug: str,
    description: Optional[str],
    resolution_source: Optional[str],
    outcome_labels: Optional[List[str]],
    event_date: Optional[str],
    market_var: Optional[str],
    market_unit: Optional[str],
) -> Dict[str, Any]:
    source = str(resolution_source or "").strip() or extract_resolution_source_from_text(description)
    desc = str(description or "")
    desc_low = desc.lower()
    source_profile = weather_resolution_source_profile(source, description=description)
    station_id = source_profile.get("station_id") or parse_station_from_resolution_source(source)
    source_kind = str(source_profile.get("source_kind") or "")
    high_low = ""
    if str(market_var or "") == "temperature_2m_max":
        high_low = "highest"
    elif str(market_var or "") == "temperature_2m_min":
        high_low = "lowest"
    labels = list(outcome_labels or [])
    rounding_rule = parse_rounding_rule(desc)
    finalized_rule = "finalized_data_only" if "final" in desc_low else ""
    revision_rule = ""
    if any(token in desc_low for token in ("subsequent", "revision", "revisions", "changes after")):
        revision_rule = "post_finalization_revisions_excluded"
    profile = {
        "slug": slug,
        "title": title or "",
        "event_date": event_date or "",
        "resolution_source": source or "",
        "source_kind": source_kind,
        "station_id": station_id or "",
        "source_confidence": source_profile.get("source_confidence"),
        "source_fit_tier": source_profile.get("source_fit_tier"),
        "source_trust_tier": source_profile.get("source_trust_tier"),
        "source_usable_for_settlement": bool(source_profile.get("source_usable_for_settlement")),
        "source_station_id": source_profile.get("source_station_id") or "",
        "source_station_expected": source_profile.get("source_station_expected") or "",
        "source_station_match": source_profile.get("source_station_match"),
        "source_station_match_reason": source_profile.get("source_station_match_reason") or "",
        "source_aux_only": bool(source_profile.get("source_aux_only")),
        "publication_cadence": source_profile.get("publication_cadence") or "",
        "source_na_reason": source_profile.get("source_na_reason") or "",
        "market_var": market_var or "",
        "market_unit": market_unit or "",
        "high_low": high_low,
        "rounding_rule": rounding_rule or "",
        "finalized_rule": finalized_rule,
        "revision_rule": revision_rule,
        "outcome_count": len(labels),
    }
    missing: List[str] = []
    if not profile["resolution_source"]:
        missing.append("resolution_source")
    if is_temperature_market_var(market_var) and profile["resolution_source"] and not profile["source_usable_for_settlement"]:
        missing.append("resolution_source_untrusted")
    if is_temperature_market_var(market_var) and not profile["station_id"]:
        missing.append("station_id")
    if is_temperature_market_var(market_var) and not profile["market_unit"]:
        missing.append("market_unit")
    if is_temperature_market_var(market_var) and not profile["high_low"]:
        missing.append("high_low")
    if is_temperature_market_var(market_var) and not labels:
        missing.append("outcomes")
    profile["missing_reasons"] = missing
    profile["ok"] = not missing
    profile["rules_tradeable"] = bool(profile["ok"] and profile["source_usable_for_settlement"])
    return profile


def weather_rules_incomplete(
    event: Mapping[str, Any],
    *,
    slug: Optional[str] = None,
    title: Optional[str] = None,
) -> bool:
    if not isinstance(event, Mapping):
        return True
    desc = str(event.get("description") or "")
    source = str(event.get("resolutionSource") or event.get("resolution_source") or "").strip()
    if not source:
        source = extract_resolution_source_from_text(desc) or ""
    market_var = infer_market_variable(title or event.get("title"), slug or str(event.get("slug") or ""))
    if not desc or not source:
        return True
    if is_temperature_market_var(market_var):
        source_profile = weather_resolution_source_profile(source, description=desc)
        if not source_profile.get("station_id"):
            return True
        if source_profile.get("source_usable_for_settlement") is not True:
            return True
    return False


def _nowcast_observed_share(
    run_date: Optional[str],
    event_date: Optional[str],
    tz: Optional[str],
    market_var: Optional[str],
    *,
    now_dt: Optional[datetime] = None,
    station_id: Optional[str] = None,
    resolution_source: Optional[str] = None,
    lat: Optional[float] = None,
    lon: Optional[float] = None,
) -> float:
    if not _env_bool("PM_OBS_NOWCAST_ENABLED", True):
        return 0.0
    if str(market_var or "") not in {"temperature_2m_max", "temperature_2m_min"}:
        return 0.0
    run_key = _normalize_date_key(str(run_date or ""))
    event_key = _normalize_date_key(str(event_date or ""))
    zone_name = str(tz or "").strip() or "UTC"
    zone = timezone.utc
    if ZoneInfo is not None:
        try:
            zone = ZoneInfo(zone_name)
        except Exception:
            zone = timezone.utc
    now_local = (now_dt or datetime.now(timezone.utc)).astimezone(zone)
    local_key = now_local.date().isoformat()
    if not event_key:
        return 0.0
    if event_key != local_key and run_key != event_key:
        return 0.0
    start_hour = _env_float("PM_OBS_NOWCAST_START_HOUR")
    full_hour = _env_float("PM_OBS_NOWCAST_FULL_HOUR")
    min_share = _env_float("PM_OBS_NOWCAST_MIN_SHARE")
    max_share = _env_float("PM_OBS_NOWCAST_MAX_SHARE")
    if start_hour is None or not math.isfinite(start_hour):
        start_hour = 10.0
    if full_hour is None or not math.isfinite(full_hour):
        full_hour = _expected_temperature_peak_hour_local(
            event_date,
            tz,
            station_id=station_id,
            resolution_source=resolution_source,
            lat=lat,
            lon=lon,
        )[0]
    if min_share is None or not math.isfinite(min_share):
        min_share = 0.15
    if max_share is None or not math.isfinite(max_share):
        max_share = 0.65
    min_share = max(0.0, min(1.0, float(min_share)))
    max_share = max(min_share, min(1.0, float(max_share)))
    hour = now_local.hour + now_local.minute / 60.0
    if hour < float(start_hour):
        return 0.0
    if float(full_hour) <= float(start_hour):
        return max_share
    progress = max(0.0, min(1.0, (hour - float(start_hour)) / (float(full_hour) - float(start_hour))))
    return min_share + (max_share - min_share) * progress


def _chengdu_seasonal_peak_hour_local(month: int) -> float:
    # Chengdu summer maximum temperature usually occurs later in the afternoon;
    # winter/shoulder seasons are earlier. This is only a window prior, not a
    # settlement fact, and is superseded by explicit features/env config.
    table = {
        1: 14.5,
        2: 15.0,
        3: 15.0,
        4: 15.5,
        5: 15.75,
        6: 16.0,
        7: 16.0,
        8: 16.0,
        9: 15.75,
        10: 15.25,
        11: 15.0,
        12: 14.5,
    }
    return float(table.get(int(month), 16.0))


_FORECAST_PEAK_TIME_KEYS: Tuple[str, ...] = (
    "wu_forecast_peak_at",
    "weather_com_forecast_peak_at",
    "twc_forecast_peak_at",
    "taf_forecast_peak_at",
    "wu_forecast_peak_valid_local",
    "weather_com_forecast_peak_valid_local",
    "twc_forecast_peak_valid_local",
)


def _parse_forecast_peak_datetime(value: Any, *, key: str, default_zone: timezone) -> Optional[datetime]:
    text = str(value or "").strip()
    if not text:
        return None
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        dt = datetime.fromisoformat(text)
    except Exception:
        try:
            dt = parsedate_to_datetime(text)
        except Exception:
            return None
    if dt.tzinfo is None:
        fallback_zone = default_zone if key.endswith("_local") or "valid_local" in key else timezone.utc
        dt = dt.replace(tzinfo=fallback_zone)
    return dt


def _forecast_peak_hour_from_features(
    features: Optional[Mapping[str, Any]],
    *,
    event_date: Optional[str],
    tz: Optional[str],
) -> Tuple[Optional[float], Dict[str, Any]]:
    if not isinstance(features, Mapping):
        return None, {"expected_peak_hour_source": "forecast_peak_time_missing"}
    event_key = _normalize_date_key(str(event_date or features.get("metar_target_event_date") or ""))
    zone = _entry_post_peak_zone(tz)
    for key in _FORECAST_PEAK_TIME_KEYS:
        dt = _parse_forecast_peak_datetime(features.get(key), key=key, default_zone=zone)
        if dt is None:
            continue
        local_dt = dt.astimezone(zone)
        if event_key and local_dt.date().isoformat() != event_key:
            continue
        hour = local_dt.hour + local_dt.minute / 60.0 + local_dt.second / 3600.0
        clamped_hour = max(0.0, min(23.99, float(hour)))
        return clamped_hour, {
            "expected_peak_hour_local": clamped_hour,
            "expected_peak_hour_source": key,
            "expected_peak_at_local": local_dt.isoformat(),
            "expected_peak_hour_role": "forecast_peak_window_not_settlement_fact",
            "expected_peak_hour_basis": "forecast_peak_timestamp",
        }
    return None, {"expected_peak_hour_source": "forecast_peak_time_missing"}


def _expected_temperature_peak_hour_local(
    event_date: Optional[str],
    tz: Optional[str],
    *,
    station_id: Optional[str] = None,
    resolution_source: Optional[str] = None,
    lat: Optional[float] = None,
    lon: Optional[float] = None,
    forecast_features: Optional[Mapping[str, Any]] = None,
) -> Tuple[float, Dict[str, Any]]:
    env_hour = _env_float("PM_TEMPERATURE_PEAK_HOUR_LOCAL")
    if env_hour is not None and math.isfinite(env_hour):
        hour = max(0.0, min(23.99, float(env_hour)))
        return hour, {
            "expected_peak_hour_local": hour,
            "expected_peak_hour_source": "env_PM_TEMPERATURE_PEAK_HOUR_LOCAL",
            "expected_peak_hour_role": "refresh_window_prior_not_settlement_fact",
        }
    forecast_hour, forecast_meta = _forecast_peak_hour_from_features(
        forecast_features,
        event_date=event_date,
        tz=tz,
    )
    if forecast_hour is not None:
        return float(forecast_hour), forecast_meta
    event_key = _normalize_date_key(str(event_date or ""))
    month = None
    parsed = _parse_date(event_key) if event_key else None
    if parsed is not None:
        month = int(parsed.month)
    station = _normalize_station_code(station_id or parse_station_from_resolution_source(resolution_source))
    source_low = str(resolution_source or "").lower()
    lat_val = to_float(lat)
    lon_val = to_float(lon)
    is_chengdu = bool(
        station == "ZUUU"
        or "chengdu" in source_low
        or (
            lat_val is not None
            and lon_val is not None
            and 29.0 <= float(lat_val) <= 32.0
            and 102.0 <= float(lon_val) <= 106.0
        )
    )
    if is_chengdu and month is not None:
        hour = _chengdu_seasonal_peak_hour_local(month)
        return hour, {
            "expected_peak_hour_local": hour,
            "expected_peak_hour_source": "chengdu_monthly_seasonal_peak_hour_prior_v1",
            "expected_peak_hour_role": "refresh_window_prior_not_settlement_fact",
            "expected_peak_hour_station_id": station or "",
            "expected_peak_hour_month": int(month),
            "expected_peak_hour_basis": "historical_seasonal_monthly_window",
        }
    # Generic fallback keeps the old late-afternoon temperature-max assumption
    # but labels it as a fallback so UI/logs do not imply station climatology.
    fallback = 16.0
    return fallback, {
        "expected_peak_hour_local": fallback,
        "expected_peak_hour_source": "generic_temperature_max_fallback",
        "expected_peak_hour_role": "refresh_window_prior_not_settlement_fact",
        "expected_peak_hour_station_id": station or "",
        "expected_peak_hour_month": int(month) if month is not None else None,
        "expected_peak_hour_basis": "fallback_missing_station_seasonal_history",
    }


def _effective_weather_likelihood_tz(
    tz: Optional[str],
    resolution_source: Optional[str] = None,
) -> str:
    zone_name = str(tz or "").strip() or "UTC"
    source_low = str(resolution_source or "").strip().lower()
    if zone_name.upper() in {"", "UTC", "ETC/UTC", "Z"} and (
        "/cn/" in source_low or "china" in source_low
    ):
        return "Asia/Shanghai"
    return zone_name


def _temperature_peak_likelihood_refresh_interval_sec(
    event_date: Optional[str],
    tz: Optional[str],
    market_var: Optional[str],
    *,
    now_dt: Optional[datetime] = None,
    lon: Optional[float] = None,
    lat: Optional[float] = None,
    station_id: Optional[str] = None,
    resolution_source: Optional[str] = None,
) -> Optional[float]:
    if not _env_bool("PM_BAYES_LIKELIHOOD_DYNAMIC_REFRESH_ENABLED", True):
        return None
    if str(market_var or "") != "temperature_2m_max":
        return None
    event_key = _normalize_date_key(str(event_date or ""))
    if not event_key:
        return None
    try:
        event_day = date.fromisoformat(event_key)
    except Exception:
        return None
    zone_name = _effective_weather_likelihood_tz(tz, resolution_source)
    zone = timezone.utc
    if ZoneInfo is not None:
        try:
            zone = ZoneInfo(zone_name)
        except Exception:
            zone = timezone.utc
    elif zone_name == "Asia/Shanghai":
        zone = timezone(timedelta(hours=8))
    elif zone_name.upper() in {"", "UTC", "ETC/UTC", "Z"}:
        lon_val = to_float(lon)
        if lon_val is not None and math.isfinite(lon_val):
            offset_hours = int(max(-12, min(14, round(float(lon_val) / 15.0))))
            zone = timezone(timedelta(hours=offset_hours))
    now_utc = now_dt or datetime.now(timezone.utc)
    if now_utc.tzinfo is None:
        now_utc = now_utc.replace(tzinfo=timezone.utc)
    now_local = now_utc.astimezone(zone)
    local_day = now_local.date()
    if local_day < event_day:
        return None

    start_hour = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_START_HOUR")
    peak_hour = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_PEAK_HOUR")
    end_hour = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_END_HOUR")
    pre_peak_min = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_PRE_PEAK_MIN")
    peak_min = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_PEAK_MIN")
    post_peak_min = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_POST_PEAK_MIN")
    pre_peak_sec = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_PRE_PEAK_SEC")
    peak_sec = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_PEAK_SEC")
    post_peak_sec = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_POST_PEAK_SEC")
    if start_hour is None or not math.isfinite(start_hour):
        start_hour = _env_float("PM_OBS_NOWCAST_START_HOUR") or 10.0
    if peak_hour is None or not math.isfinite(peak_hour):
        peak_hour = _env_float("PM_OBS_NOWCAST_FULL_HOUR")
    if peak_hour is None or not math.isfinite(peak_hour):
        peak_hour = _expected_temperature_peak_hour_local(
            event_date,
            zone_name,
            station_id=station_id,
            resolution_source=resolution_source,
            lat=lat,
            lon=lon,
        )[0]
    if end_hour is None or not math.isfinite(end_hour):
        end_hour = float(peak_hour) + 1.5
    if pre_peak_sec is not None and math.isfinite(pre_peak_sec) and pre_peak_sec > 0:
        pre_peak_min = float(pre_peak_sec) / 60.0
    if peak_sec is not None and math.isfinite(peak_sec) and peak_sec > 0:
        peak_min = float(peak_sec) / 60.0
    if post_peak_sec is not None and math.isfinite(post_peak_sec) and post_peak_sec > 0:
        post_peak_min = float(post_peak_sec) / 60.0
    if pre_peak_min is None or not math.isfinite(pre_peak_min) or pre_peak_min <= 0:
        pre_peak_min = 5.0
    if peak_min is None or not math.isfinite(peak_min) or peak_min <= 0:
        peak_min = 0.5
    if post_peak_min is None or not math.isfinite(post_peak_min) or post_peak_min <= 0:
        post_peak_min = 1.0
    def _post_observation_refresh_interval_sec(
        sec_key: str,
        min_key: str,
        *,
        default_min: float,
    ) -> float:
        interval_sec = _env_float(sec_key)
        interval_min = _env_float(min_key)
        if interval_sec is not None and math.isfinite(interval_sec) and interval_sec > 0:
            return max(60.0, float(interval_sec))
        if interval_min is None or not math.isfinite(interval_min) or interval_min <= 0:
            interval_min = float(default_min)
        return max(60.0, float(interval_min) * 60.0)

    if local_day > event_day:
        return _post_observation_refresh_interval_sec(
            "PM_BAYES_LIKELIHOOD_REFRESH_POST_EVENT_SEC",
            "PM_BAYES_LIKELIHOOD_REFRESH_POST_EVENT_MIN",
            default_min=10.0,
        )
    if float(end_hour) <= float(peak_hour):
        end_hour = float(peak_hour) + 0.5
    if float(peak_hour) <= float(start_hour):
        peak_hour = float(start_hour) + 0.5

    local_hour = now_local.hour + now_local.minute / 60.0 + now_local.second / 3600.0
    if local_hour < float(start_hour):
        return None
    if local_hour > float(end_hour):
        return _post_observation_refresh_interval_sec(
            "PM_BAYES_LIKELIHOOD_REFRESH_AFTER_WINDOW_SEC",
            "PM_BAYES_LIKELIHOOD_REFRESH_AFTER_WINDOW_MIN",
            default_min=5.0,
        )
    if local_hour <= float(peak_hour):
        progress = (local_hour - float(start_hour)) / max(1e-9, float(peak_hour) - float(start_hour))
        interval_min = float(pre_peak_min) + (float(peak_min) - float(pre_peak_min)) * max(0.0, min(1.0, progress))
    else:
        progress = (local_hour - float(peak_hour)) / max(1e-9, float(end_hour) - float(peak_hour))
        interval_min = float(peak_min) + (float(post_peak_min) - float(peak_min)) * max(0.0, min(1.0, progress))
    hours_to_peak = float(peak_hour) - float(local_hour)
    if hours_to_peak > 4.0:
        interval_min = min(float(interval_min), 15.0)
    elif hours_to_peak > 2.0:
        interval_min = min(float(interval_min), 10.0)
    elif hours_to_peak > 0.0:
        interval_min = min(float(interval_min), 5.0)
    else:
        interval_min = min(float(interval_min), 2.0)
    if abs(hours_to_peak) <= 0.5:
        interval_min = min(float(interval_min), 0.5)
        core_peak_sec = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_CORE_PEAK_SEC")
        if core_peak_sec is None or not math.isfinite(core_peak_sec) or core_peak_sec <= 0:
            core_peak_sec = 1.0
        interval_min = min(float(interval_min), max(1.0, float(core_peak_sec)) / 60.0)
    floor_min = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_MIN_FLOOR_MIN")
    floor_sec = _env_float("PM_BAYES_LIKELIHOOD_REFRESH_MIN_FLOOR_SEC")
    if floor_sec is not None and math.isfinite(floor_sec) and floor_sec > 0:
        floor_min = float(floor_sec) / 60.0
    if floor_min is None or not math.isfinite(floor_min) or floor_min <= 0:
        floor_min = 15.0 / 60.0
    floor_min = min(float(floor_min), float(interval_min))
    interval_min = max(float(floor_min), float(interval_min))
    return float(interval_min) * 60.0


def _market_var_extreme_kind(market_var: Optional[str]) -> str:
    if str(market_var or "") == "temperature_2m_max":
        return "max"
    if str(market_var or "") == "temperature_2m_min":
        return "min"
    return ""


def _iso_from_epoch(value: Any) -> str:
    try:
        ts = float(value)
    except (TypeError, ValueError):
        return ""
    if not math.isfinite(ts):
        return ""
    try:
        return datetime.fromtimestamp(ts, timezone.utc).isoformat(timespec="seconds")
    except Exception:
        return ""


def _datetime_from_epoch(value: Any) -> Optional[datetime]:
    try:
        ts = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(ts):
        return None
    try:
        return datetime.fromtimestamp(ts, timezone.utc)
    except Exception:
        return None


def _record_station_observation(
    *,
    event_date: str,
    station_id: Optional[str],
    resolution_source: Optional[str],
    source_kind: str,
    value: float,
    unit: Optional[str],
    market_var: Optional[str],
    source_fit_tier: Optional[str],
    source_confidence: Optional[float],
    observed_at: Optional[str] = None,
    published_at: Optional[str] = None,
    raw: Optional[Mapping[str, Any]] = None,
) -> None:
    if not _env_bool("PM_STATION_OBSERVATIONS_WRITE", True):
        return
    if not _archive_write_allowed_for_chengdu_zuuu(
        station_id=station_id,
        resolution_source=resolution_source,
    ):
        return
    try:
        numeric_value = float(value)
    except (TypeError, ValueError):
        return
    if not math.isfinite(numeric_value):
        return
    try:
        init_db()
        created_at = utc_now_iso()
        run_date = today_date_str("America/New_York")
        raw_json = (
            json.dumps(dict(raw), ensure_ascii=True, sort_keys=True)
            if isinstance(raw, Mapping)
            else None
        )
        with open_db(
            autocommit=True,
            connect_timeout_sec=0.8,
            busy_timeout_ms=800,
        ) as conn_obs:
            conn_obs.execute(
                """
                INSERT INTO station_observations (
                    run_date, event_date, station_id, resolution_source,
                    source_kind, observed_at, published_at, value, unit,
                    market_var, trust_tier, source_confidence, raw_json, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    run_date,
                    event_date,
                    str(station_id or "").strip().upper(),
                    str(resolution_source or "").strip(),
                    str(source_kind or "").strip(),
                    str(observed_at or "").strip(),
                    str(published_at or "").strip(),
                    numeric_value,
                    str(unit or "").strip(),
                    str(market_var or "").strip(),
                    str(source_fit_tier or "").strip(),
                    source_confidence,
                    raw_json,
                    created_at,
                ),
            )
    except Exception:
        return


def _wunderground_weather_url_from_history_source(resolution_source: Optional[str]) -> str:
    source = str(resolution_source or "").strip()
    if not source:
        return ""
    source = source.split("/date/", 1)[0].rstrip("/")
    if "/history/daily/" in source:
        return source.replace("/history/daily/", "/weather/")
    if "/weather/" in source or "/hourly/" in source or "/dashboard/pws/" in source:
        return source
    return ""


def _wu_twc_force_proxy() -> bool:
    return _env_bool("PM_WU_TWC_FORCE_PROXY", True)


def _wu_twc_obs_request_timeout() -> Tuple[float, float]:
    raw = _env_float("PM_WU_TWC_OBS_TIMEOUT_SEC")
    if raw is None or not math.isfinite(float(raw)) or float(raw) <= 0:
        raw = 5.0
    total = max(1.0, min(12.0, float(raw)))
    connect = max(0.5, min(2.0, total * 0.5))
    read = max(0.75, total)
    return (float(connect), float(read))


def _wu_twc_obs_request_retries() -> int:
    raw = _env_int("PM_WU_TWC_OBS_RETRIES")
    if raw is None or raw < 1:
        raw = 1
    return max(1, min(int(raw), 2))


def _wunderground_app_root_state(html_text: str) -> Dict[str, Any]:
    match = re.search(
        r'<script\s+id=["\']app-root-state["\']\s+type=["\']application/json["\']>(.*?)</script>',
        html_text or "",
        flags=re.S | re.I,
    )
    if not match:
        return {}
    try:
        parsed = json.loads(html.unescape(match.group(1)))
    except Exception:
        return {}
    return dict(parsed) if isinstance(parsed, Mapping) else {}


def _local_hour_from_wu_valid_time(value: Any) -> Optional[float]:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        dt = datetime.fromisoformat(text)
        return float(dt.hour) + float(dt.minute) / 60.0
    except Exception:
        match = re.search(r"T(\d{1,2}):(\d{2})", text)
        if not match:
            return None
        return float(match.group(1)) + float(match.group(2)) / 60.0


def _wu_units_from_url(url: str) -> str:
    low = str(url or "").lower()
    if "units=m" in low:
        return "C"
    if "units=e" in low:
        return "F"
    return "F"


def _extract_wunderground_current_observation_metrics_from_html(
    html_text: str,
    *,
    station_id: Optional[str],
    event_date: str,
    kind: str,
    market_unit: Optional[str],
) -> Dict[str, Any]:
    state = _wunderground_app_root_state(html_text)
    if not state:
        return {"ok": False, "error": "app_root_state_missing"}
    station_key = str(station_id or "").strip().upper()
    candidates: List[Tuple[int, str, Mapping[str, Any]]] = []
    for item in state.values():
        if not isinstance(item, Mapping):
            continue
        url = str(item.get("u") or "")
        if "/v3/wx/observations/current" not in url:
            continue
        body = item.get("b")
        if not isinstance(body, Mapping):
            continue
        score = 1
        if station_key and f"icaocode={station_key.lower()}" in url.lower():
            score = 3
        elif "geocode=" in url.lower():
            score = 2
        candidates.append((score, url, body))
    if not candidates:
        return {"ok": False, "error": "current_observation_missing"}
    candidates.sort(key=lambda item: item[0], reverse=True)
    event_key = _normalize_date_key(str(event_date or ""))
    skipped_date = False
    for score, url, body in candidates:
        valid_local = str(body.get("validTimeLocal") or "").strip()
        if event_key and valid_local and valid_local[:10] != event_key:
            skipped_date = True
            continue
        source_unit = _wu_units_from_url(url)
        local_hour = _local_hour_from_wu_valid_time(valid_local)
        source_detail = "current_temperature"
        raw_value = None
        if kind == "max":
            max_since_7 = to_float(body.get("temperatureMaxSince7Am"))
            if max_since_7 is not None and (local_hour is None or local_hour >= 7.0):
                raw_value = float(max_since_7)
                source_detail = "max_since7am"
        elif kind == "min":
            min_24h = to_float(body.get("temperatureMin24Hour"))
            if min_24h is not None:
                raw_value = float(min_24h)
                source_detail = "min_24h"
        if raw_value is None:
            current = to_float(body.get("temperature"))
            if current is None:
                continue
            raw_value = float(current)
            source_detail = "current_temperature"
        converted = _convert_temp_value(float(raw_value), source_unit, market_unit)
        time_gmt = to_float(body.get("validTimeUtc"))
        prefix = "wunderground_current_station" if score >= 3 else "wunderground_current_geocode"
        out: Dict[str, Any] = {
            "ok": True,
            "value": float(converted),
            "source": f"{prefix}_{source_detail}",
            "source_url": url,
            "raw_value": float(raw_value),
            "raw_unit": source_unit,
            "valid_time_local": valid_local,
        }
        if time_gmt is not None:
            out["time_gmt"] = float(time_gmt)
        return out
    return {
        "ok": False,
        "error": "current_observation_event_date_mismatch" if skipped_date else "current_observation_value_missing",
    }


def fetch_wunderground_current_observation_metrics(
    resolution_source: Optional[str],
    station_id: Optional[str],
    event_date: str,
    kind: str,
    market_unit: Optional[str],
) -> Dict[str, Any]:
    url = _wunderground_weather_url_from_history_source(resolution_source)
    if not url:
        return {"ok": False, "error": "weather_url_unavailable"}
    try:
        force_proxy = _wu_twc_force_proxy()
        resp = requests_get(
            url,
            headers=DEFAULT_REQUEST_HEADERS,
            timeout=_wu_twc_obs_request_timeout(),
            bypass_proxy=not force_proxy,
            force_proxy=force_proxy,
            retries=_wu_twc_obs_request_retries(),
        )
    except Exception as exc:
        return {"ok": False, "error": f"request_error:{exc.__class__.__name__}", "source_url": url}
    if getattr(resp, "status_code", None) != 200:
        return {"ok": False, "error": f"http_{getattr(resp, 'status_code', 0)}", "source_url": url}
    result = _extract_wunderground_current_observation_metrics_from_html(
        getattr(resp, "text", "") or "",
        station_id=station_id,
        event_date=event_date,
        kind=kind,
        market_unit=market_unit,
    )
    result.setdefault("source_url", url)
    return result


def fetch_wunderground_current_and_max_observation_metrics(
    resolution_source: Optional[str],
    station_id: Optional[str],
    event_date: str,
    market_unit: Optional[str],
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    url = _wunderground_weather_url_from_history_source(resolution_source)
    if not url:
        err = {"ok": False, "error": "weather_url_unavailable"}
        return dict(err), dict(err)
    try:
        force_proxy = _wu_twc_force_proxy()
        resp = requests_get(
            url,
            headers=DEFAULT_REQUEST_HEADERS,
            timeout=_wu_twc_obs_request_timeout(),
            bypass_proxy=not force_proxy,
            force_proxy=force_proxy,
            retries=_wu_twc_obs_request_retries(),
        )
    except Exception as exc:
        err = {"ok": False, "error": f"request_error:{exc.__class__.__name__}", "source_url": url}
        return dict(err), dict(err)
    if getattr(resp, "status_code", None) != 200:
        err = {"ok": False, "error": f"http_{getattr(resp, 'status_code', 0)}", "source_url": url}
        return dict(err), dict(err)
    html_text = getattr(resp, "text", "") or ""
    current = _extract_wunderground_current_observation_metrics_from_html(
        html_text,
        station_id=station_id,
        event_date=event_date,
        kind="current",
        market_unit=market_unit,
    )
    current.setdefault("source_url", url)
    max_since = _extract_wunderground_current_observation_metrics_from_html(
        html_text,
        station_id=station_id,
        event_date=event_date,
        kind="max",
        market_unit=market_unit,
    )
    max_since.setdefault("source_url", url)
    return current, max_since


def fetch_observed_nowcast_value(
    resolution_source: Optional[str],
    station_id: Optional[str],
    event_date: str,
    market_var: Optional[str],
    market_unit: Optional[str],
) -> Tuple[Optional[float], str]:
    source = str(resolution_source or "").strip()
    if not source or not event_date:
        return None, "missing_source"
    kind = _market_var_extreme_kind(market_var)
    if not kind:
        return None, "market_var_unsupported"
    source_profile = weather_resolution_source_profile(source, station_id=station_id)
    source_kind = str(source_profile.get("source_kind") or "")
    source_confidence = to_float(source_profile.get("source_confidence"))
    source_fit_tier = str(source_profile.get("source_fit_tier") or source_profile.get("source_trust_tier") or "")
    if source_profile.get("source_usable_for_settlement") is not True:
        reason = str(source_profile.get("source_na_reason") or "resolution_source_untrusted")
        return None, f"source_not_tradeable:{reason}"
    if source_kind == "wunderground_history":
        try:
            metrics = fetch_wunderground_history_metrics(source, event_date, kind, market_unit)
            val = metrics.get("value") if isinstance(metrics, Mapping) else None
            if val is not None and math.isfinite(float(val)):
                observed_at = _iso_from_epoch(metrics.get("time_gmt")) if isinstance(metrics, Mapping) else ""
                _record_station_observation(
                    event_date=event_date,
                    station_id=station_id or str(source_profile.get("station_id") or ""),
                    resolution_source=source,
                    source_kind=source_kind,
                    value=float(val),
                    unit=market_unit,
                    market_var=market_var,
                    source_fit_tier=source_fit_tier,
                    source_confidence=source_confidence,
                    observed_at=observed_at,
                    published_at=observed_at,
                    raw={"source": "wunderground_history_metrics"},
                )
                return float(val), "wunderground_history"
        except Exception as exc:
            return None, f"wunderground_history_error:{exc.__class__.__name__}"
        try:
            metrics = fetch_wunderground_current_observation_metrics(
                source,
                station_id or str(source_profile.get("station_id") or ""),
                event_date,
                kind,
                market_unit,
            )
            val = metrics.get("value") if isinstance(metrics, Mapping) else None
            if val is not None and math.isfinite(float(val)):
                observed_at = _iso_from_epoch(metrics.get("time_gmt")) if isinstance(metrics, Mapping) else ""
                source_label = str(metrics.get("source") or "wunderground_current_observation")
                confidence = 0.85 if "station" in source_label else 0.65
                _record_station_observation(
                    event_date=event_date,
                    station_id=station_id or str(source_profile.get("station_id") or ""),
                    resolution_source=source,
                    source_kind=source_label,
                    value=float(val),
                    unit=market_unit,
                    market_var=market_var,
                    source_fit_tier="settlement_source_nowcast",
                    source_confidence=confidence,
                    observed_at=observed_at,
                    published_at=observed_at,
                    raw={
                        "source": source_label,
                        "valid_time_local": metrics.get("valid_time_local"),
                        "raw_value": metrics.get("raw_value"),
                        "raw_unit": metrics.get("raw_unit"),
                    },
                )
                return float(val), source_label
        except Exception as exc:
            return None, f"wunderground_current_error:{exc.__class__.__name__}"
        try:
            local_tz = _effective_weather_likelihood_tz("", source)
            local_today = datetime.now(timezone.utc)
            if ZoneInfo is not None:
                try:
                    local_today = local_today.astimezone(ZoneInfo(local_tz))
                except Exception:
                    local_today = local_today.astimezone(timezone.utc)
            event_day = _parse_date(event_date)
            allow_d0_daily = _env_bool("PM_WU_ALLOW_DAILY_PAGE_D0_NOWCAST_FALLBACK", False)
            is_d0_or_future = bool(event_day is not None and event_day >= local_today.date())
            if allow_d0_daily or not is_d0_or_future:
                val = fetch_wunderground_daily_temp(source, event_date, kind, market_unit)
                if val is not None and math.isfinite(float(val)):
                    _record_station_observation(
                        event_date=event_date,
                        station_id=station_id or str(source_profile.get("station_id") or ""),
                        resolution_source=source,
                        source_kind=source_kind,
                        value=float(val),
                        unit=market_unit,
                        market_var=market_var,
                        source_fit_tier=source_fit_tier,
                        source_confidence=source_confidence,
                        raw={"source": "wunderground_daily"},
                    )
                    return float(val), "wunderground_daily"
        except Exception as exc:
            return None, f"wunderground_daily_error:{exc.__class__.__name__}"
        if not _env_bool("PM_WU_ALLOW_PWS_NOWCAST_AUX", False):
            return None, "wunderground_history_missing"
        try:
            val = fetch_wunderground_pws_daily_temp(source, station_id, event_date, kind, market_unit)
            if val is not None and math.isfinite(float(val)):
                _record_station_observation(
                    event_date=event_date,
                    station_id=station_id or str(source_profile.get("station_id") or ""),
                    resolution_source=source,
                    source_kind="wunderground_pws_aux",
                    value=float(val),
                    unit=market_unit,
                    market_var=market_var,
                    source_fit_tier="auxiliary_only",
                    source_confidence=0.35,
                    raw={"source": "wunderground_pws_aux"},
                )
                return float(val), "wunderground_pws_aux"
        except Exception as exc:
            return None, f"wunderground_pws_error:{exc.__class__.__name__}"
        return None, "wunderground_missing"
    if source_kind == "weather_gov_timeseries":
        return None, "weather_gov_timeseries_fetch_not_implemented"
    return None, "source_not_supported"


def _parse_wu_valid_local_datetime(value: Any, tz_name: Optional[str]) -> Optional[datetime]:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if dt.tzinfo is not None:
        return dt.astimezone(timezone.utc)
    zone = timezone.utc
    if tz_name and ZoneInfo is not None:
        try:
            zone = ZoneInfo(str(tz_name))
        except Exception:
            zone = timezone.utc
    return dt.replace(tzinfo=zone).astimezone(timezone.utc)


def _wunderground_history_temp_pairs_c(
    resolution_source: Optional[str],
    event_date: str,
    tz_name: Optional[str],
) -> Tuple[List[Tuple[datetime, float]], Dict[str, Any]]:
    payload, meta = _fetch_wunderground_history_api_payload(resolution_source, event_date, units="m")
    if not payload:
        payload, meta = _fetch_wunderground_history_payload_with_meta(resolution_source, event_date)
    pairs: List[Tuple[datetime, float]] = []
    observations = payload.get("observations") if isinstance(payload, Mapping) else None
    if not isinstance(observations, list):
        return pairs, dict(meta)
    zone = timezone.utc
    if tz_name and ZoneInfo is not None:
        try:
            zone = ZoneInfo(str(tz_name))
        except Exception:
            zone = timezone.utc
    event_key = _normalize_date_key(str(event_date or ""))
    best_raw: Optional[Tuple[float, float, str, datetime]] = None
    for obs in observations:
        if not isinstance(obs, dict):
            continue
        extracted = _extract_observation_temp(obs, default_unit=str(meta.get("default_unit") or "F"))
        if not extracted:
            continue
        ts = _observation_timestamp(obs)
        dt = _datetime_from_epoch(ts)
        if dt is None:
            continue
        local_dt = dt.astimezone(zone)
        if event_key and local_dt.date().isoformat() != event_key:
            continue
        value, unit = extracted
        temp_c = _convert_temp_value(float(value), unit, "C")
        if math.isfinite(float(temp_c)):
            pairs.append((dt.astimezone(timezone.utc), float(temp_c)))
            if best_raw is None or float(temp_c) > float(best_raw[0]):
                best_raw = (float(temp_c), float(value), str(unit or ""), dt.astimezone(timezone.utc))
    pairs.sort(key=lambda item: item[0])
    if best_raw is not None:
        meta["peak_raw_converted_c"] = float(best_raw[0])
        meta["peak_raw_value"] = float(best_raw[1])
        meta["peak_raw_unit"] = str(best_raw[2] or "")
        meta["peak_raw_at"] = _iso_from_datetime(best_raw[3])
    return pairs, dict(meta)


def _wunderground_history_peak_raw_observation(
    resolution_source: Optional[str],
    event_date: str,
    tz_name: Optional[str],
    *,
    units: str,
) -> Dict[str, Any]:
    payload, meta = _fetch_wunderground_history_api_payload(resolution_source, event_date, units=units)
    observations = payload.get("observations") if isinstance(payload, Mapping) else None
    if not isinstance(observations, list):
        out = dict(meta)
        out.setdefault("ok", False)
        out.setdefault("error", "observations_missing")
        return out
    zone = timezone.utc
    if tz_name and ZoneInfo is not None:
        try:
            zone = ZoneInfo(str(tz_name))
        except Exception:
            zone = timezone.utc
    event_key = _normalize_date_key(str(event_date or ""))
    best: Optional[Tuple[float, str, datetime]] = None
    default_unit = str(meta.get("default_unit") or ("C" if str(units).lower() == "m" else "F"))
    for obs in observations:
        if not isinstance(obs, dict):
            continue
        extracted = _extract_observation_temp(obs, default_unit=default_unit)
        if not extracted:
            continue
        ts = _observation_timestamp(obs)
        dt = _datetime_from_epoch(ts)
        if dt is None:
            continue
        if event_key and dt.astimezone(zone).date().isoformat() != event_key:
            continue
        value, unit = extracted
        if best is None or float(value) > float(best[0]):
            best = (float(value), str(unit or default_unit), dt.astimezone(timezone.utc))
    out = dict(meta)
    out["observation_count"] = len(observations)
    if best is None:
        out["ok"] = False
        out["error"] = "temperature_missing"
        return out
    out["ok"] = True
    out["raw_value"] = float(best[0])
    out["raw_unit"] = str(best[1] or "")
    out["observed_at"] = _iso_from_datetime(best[2])
    return out


def _weather_com_current_endpoint_raw_observation(source_url: Any, *, units: str) -> Dict[str, Any]:
    url = str(source_url or "").strip()
    units_norm = "m" if str(units or "").strip().lower() == "m" else "e"
    if not url:
        return {"ok": False, "error": "source_url_missing", "units": units_norm}
    if re.search(r"([?&])units=[^&]+", url):
        url = re.sub(r"([?&])units=[^&]+", rf"\1units={units_norm}", url)
    else:
        sep = "&" if "?" in url else "?"
        url = f"{url}{sep}units={units_norm}"
    try:
        force_proxy = _wu_twc_force_proxy()
        resp = requests_get(
            url,
            headers=DEFAULT_REQUEST_HEADERS,
            timeout=_wu_twc_obs_request_timeout(),
            bypass_proxy=not force_proxy,
            force_proxy=force_proxy,
            retries=_wu_twc_obs_request_retries(),
        )
    except Exception as exc:
        return {"ok": False, "error": f"request_error:{exc.__class__.__name__}", "units": units_norm}
    if getattr(resp, "status_code", None) != 200:
        return {"ok": False, "error": f"http_{getattr(resp, 'status_code', 0)}", "units": units_norm}
    try:
        body = resp.json()
    except Exception as exc:
        return {"ok": False, "error": f"json_error:{exc.__class__.__name__}", "units": units_norm}
    if not isinstance(body, Mapping):
        return {"ok": False, "error": "payload_not_mapping", "units": units_norm}
    unit = "C" if units_norm == "m" else "F"
    out: Dict[str, Any] = {
        "ok": True,
        "units": units_norm,
        "raw_unit": unit,
        "valid_time_local": body.get("validTimeLocal"),
    }
    raw_current = to_float(body.get("temperature"))
    raw_max = to_float(body.get("temperatureMaxSince7Am"))
    if raw_current is not None:
        out["current_raw_value"] = float(raw_current)
    if raw_max is not None:
        out["max_since7am_raw_value"] = float(raw_max)
    time_gmt = to_float(body.get("validTimeUtc"))
    if time_gmt is not None:
        out["time_gmt"] = float(time_gmt)
        dt = _datetime_from_epoch(time_gmt)
        if dt is not None:
            out["observed_at"] = _iso_from_datetime(dt)
    return out


def fetch_wu_twc_observed_intraday_features(
    resolution_source: Optional[str],
    station_id: Optional[str],
    event_date: str,
    market_var: Optional[str],
    market_unit: Optional[str],
    *,
    tz: Optional[str] = None,
    reference_observed_at: Optional[Any] = None,
    rounding_rule: Optional[str] = "whole_degrees",
    provenance: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    if str(market_var or "") != "temperature_2m_max":
        return {}
    source_profile = weather_resolution_source_profile(resolution_source, station_id=station_id)
    source_kind = str(source_profile.get("source_kind") or "")
    if source_kind not in {"wunderground_history", "wunderground_aux"}:
        return {}
    station = _normalize_station_code(station_id or source_profile.get("station_id"))
    if station and station != "ZUUU":
        return {}
    event_key = _normalize_date_key(str(event_date or ""))
    if not event_key:
        return {}
    tz_name = _effective_weather_likelihood_tz(tz, resolution_source)
    request_started_at = datetime.now(timezone.utc)
    request_start_ts = time.time()
    current_metrics: Dict[str, Any] = {}
    max_since_metrics: Dict[str, Any] = {}
    try:
        current_metrics, max_since_metrics = fetch_wunderground_current_and_max_observation_metrics(
            resolution_source,
            station or str(source_profile.get("station_id") or ""),
            event_key,
            "C",
        )
    except Exception as exc:
        current_metrics = {"ok": False, "error": f"current_error:{exc.__class__.__name__}"}
        max_since_metrics = {"ok": False, "error": f"max_since7_error:{exc.__class__.__name__}"}

    history_pairs: List[Tuple[datetime, float]] = []
    history_meta: Dict[str, Any] = {}
    try:
        history_pairs, history_meta = _wunderground_history_temp_pairs_c(
            resolution_source,
            event_key,
            tz_name,
        )
    except Exception as exc:
        history_meta = {"ok": False, "error": f"history_pairs_error:{exc.__class__.__name__}"}
    try:
        history_imperial_raw = _wunderground_history_peak_raw_observation(
            resolution_source,
            event_key,
            tz_name,
            units="e",
        )
    except Exception as exc:
        history_imperial_raw = {"ok": False, "error": f"history_raw_e_error:{exc.__class__.__name__}"}
    current_metric_raw: Dict[str, Any] = {}
    current_imperial_raw: Dict[str, Any] = {}
    current_endpoint_url = current_metrics.get("source_url") if isinstance(current_metrics, Mapping) else ""
    if current_endpoint_url:
        try:
            current_metric_raw = _weather_com_current_endpoint_raw_observation(current_endpoint_url, units="m")
        except Exception as exc:
            current_metric_raw = {"ok": False, "error": f"current_raw_m_error:{exc.__class__.__name__}"}
        try:
            current_imperial_raw = _weather_com_current_endpoint_raw_observation(current_endpoint_url, units="e")
        except Exception as exc:
            current_imperial_raw = {"ok": False, "error": f"current_raw_e_error:{exc.__class__.__name__}"}
    request_completed_at = datetime.now(timezone.utc)
    request_duration_ms = int((time.time() - request_start_ts) * 1000)

    current_temp_c = to_float(current_metrics.get("value")) if isinstance(current_metrics, Mapping) else None
    current_at = _datetime_from_epoch(current_metrics.get("time_gmt")) if isinstance(current_metrics, Mapping) else None
    if current_at is None and isinstance(current_metrics, Mapping):
        current_at = _parse_wu_valid_local_datetime(current_metrics.get("valid_time_local"), tz_name)
    if current_at is not None:
        local_zone = timezone.utc
        if tz_name and ZoneInfo is not None:
            try:
                local_zone = ZoneInfo(str(tz_name))
            except Exception:
                local_zone = timezone.utc
        current_local_key = current_at.astimezone(local_zone).date().isoformat()
        if current_local_key != event_key:
            current_temp_c = None
            current_at = None

    max_candidates: List[Tuple[float, Optional[datetime], str]] = []

    def _append_current_endpoint_raw_max_candidate(raw_obj: Mapping[str, Any], source_name: str) -> None:
        if not isinstance(raw_obj, Mapping) or not raw_obj.get("ok"):
            return
        raw_max = to_float(raw_obj.get("max_since7am_raw_value"))
        if raw_max is None or not math.isfinite(float(raw_max)):
            return
        raw_at = _parse_metar_time(raw_obj.get("observed_at"))
        if raw_at is None:
            raw_at = _datetime_from_epoch(raw_obj.get("time_gmt"))
        local_hour = _local_hour_from_wu_valid_time(raw_obj.get("valid_time_local"))
        if local_hour is None and raw_at is not None:
            local_zone = timezone.utc
            if tz_name and ZoneInfo is not None:
                try:
                    local_zone = ZoneInfo(str(tz_name))
                except Exception:
                    local_zone = timezone.utc
            local_dt = raw_at.astimezone(local_zone)
            local_hour = float(local_dt.hour + local_dt.minute / 60.0 + local_dt.second / 3600.0)
        if local_hour is not None and local_hour < 7.0:
            return
        raw_unit = str(raw_obj.get("raw_unit") or "").strip().upper().replace("°", "")
        if raw_unit == "F":
            max_c = (float(raw_max) - 32.0) * 5.0 / 9.0
        elif raw_unit in {"", "C"}:
            max_c = float(raw_max)
        else:
            return
        if raw_at is not None:
            local_zone = timezone.utc
            if tz_name and ZoneInfo is not None:
                try:
                    local_zone = ZoneInfo(str(tz_name))
                except Exception:
                    local_zone = timezone.utc
            if raw_at.astimezone(local_zone).date().isoformat() != event_key:
                return
        max_candidates.append((float(max_c), raw_at, source_name))

    if history_pairs:
        hist_time, hist_temp = max(history_pairs, key=lambda item: item[1])
        max_candidates.append((float(hist_temp), hist_time, "wu_twc_observed_intraday_history"))
    max_since_c = to_float(max_since_metrics.get("value")) if isinstance(max_since_metrics, Mapping) else None
    max_since_at = _datetime_from_epoch(max_since_metrics.get("time_gmt")) if isinstance(max_since_metrics, Mapping) else None
    if max_since_at is None and isinstance(max_since_metrics, Mapping):
        max_since_at = _parse_wu_valid_local_datetime(max_since_metrics.get("valid_time_local"), tz_name)
    if max_since_c is not None and math.isfinite(float(max_since_c)):
        max_candidates.append((float(max_since_c), max_since_at, "wu_twc_observed_intraday_max_since7am"))
    if current_temp_c is not None and math.isfinite(float(current_temp_c)):
        max_candidates.append((float(current_temp_c), current_at, "wu_twc_observed_intraday_current"))
    _append_current_endpoint_raw_max_candidate(
        current_metric_raw,
        "wu_twc_observed_intraday_current_metric_max_since7am",
    )
    _append_current_endpoint_raw_max_candidate(
        current_imperial_raw,
        "wu_twc_observed_intraday_current_imperial_max_since7am",
    )

    reference_dt = _parse_metar_time(reference_observed_at)
    latest_wu_dt = current_at
    if latest_wu_dt is None and history_pairs:
        latest_wu_dt = history_pairs[-1][0]
    latest_max_dt = max(
        [dt for _, dt, _ in max_candidates if isinstance(dt, datetime)],
        default=None,
    )
    now_utc = datetime.now(timezone.utc)
    age_minutes: Optional[float] = None
    if latest_wu_dt is not None:
        age_minutes = max(0.0, (now_utc - latest_wu_dt.astimezone(timezone.utc)).total_seconds() / 60.0)
    max_age = _env_float("PM_WU_TWC_OBSERVED_MAX_AGE_MIN")
    if max_age is None or not math.isfinite(float(max_age)) or float(max_age) <= 0:
        max_age = 90.0
    stale = bool(age_minutes is not None and age_minutes > float(max_age))
    primary_current = bool(
        current_temp_c is not None
        and current_at is not None
        and (reference_dt is None or current_at.astimezone(timezone.utc) >= reference_dt.astimezone(timezone.utc))
    )
    primary_max = bool(
        max_candidates
        and (
            reference_dt is None
            or (
                latest_max_dt is not None
                and latest_max_dt.astimezone(timezone.utc) >= reference_dt.astimezone(timezone.utc)
            )
        )
    )
    features: Dict[str, Any] = {
        "source": "wu_twc_observed_intraday",
        "wu_twc_observed_intraday": "Wunderground/Weather.com observed intraday",
        "wu_twc_observed_intraday_available": bool(current_temp_c is not None or max_candidates),
        "wu_twc_observed_intraday_station_id": station or str(source_profile.get("station_id") or ""),
        "wu_twc_observed_intraday_source_url": _wunderground_weather_url_from_history_source(resolution_source),
        "wu_twc_observed_intraday_resolution_source": str(resolution_source or ""),
        "wu_twc_observed_intraday_role": "settlement_ecosystem_observed_nowcast",
        "wu_twc_observed_intraday_provider": "Weather.com/TWC",
        "wu_twc_observed_intraday_event_date": event_key,
        "wu_twc_observed_intraday_request_started_at": request_started_at.isoformat(),
        "wu_twc_observed_intraday_fetched_at": request_completed_at.isoformat(),
        "wu_twc_observed_intraday_fetch_duration_ms": request_duration_ms,
        "wu_twc_observed_intraday_target_poll_seconds": 1.0,
        "wu_twc_observed_intraday_current_source": current_metrics.get("source") if isinstance(current_metrics, Mapping) else "",
        "wu_twc_observed_intraday_current_error": current_metrics.get("error") if isinstance(current_metrics, Mapping) else "",
        "wu_twc_observed_intraday_max_error": max_since_metrics.get("error") if isinstance(max_since_metrics, Mapping) else "",
        "wu_twc_observed_intraday_history_method": history_meta.get("method"),
        "wu_twc_observed_intraday_history_error": history_meta.get("error"),
        "wu_twc_observed_intraday_history_sample_count": len(history_pairs),
        "wu_twc_observed_intraday_history_units": history_meta.get("units"),
        "wu_twc_observed_intraday_history_raw_unit": history_meta.get("peak_raw_unit"),
        "wu_twc_observed_intraday_history_raw_value": history_meta.get("peak_raw_value"),
        "wu_twc_observed_intraday_history_raw_at": history_meta.get("peak_raw_at"),
        "wu_twc_observed_intraday_history_raw_imperial_unit": history_imperial_raw.get("raw_unit"),
        "wu_twc_observed_intraday_history_raw_imperial_value": history_imperial_raw.get("raw_value"),
        "wu_twc_observed_intraday_history_raw_imperial_at": history_imperial_raw.get("observed_at"),
        "wu_twc_observed_intraday_primary_current": primary_current,
        "wu_twc_observed_intraday_primary_max": primary_max,
        "wu_twc_observed_intraday_stale": stale,
        "wu_twc_observed_intraday_max_age_minutes": float(max_age),
    }
    if isinstance(current_metrics, Mapping):
        raw_value = to_float(current_metrics.get("raw_value"))
        if raw_value is not None:
            features["wu_twc_observed_intraday_current_raw_value"] = float(raw_value)
        if current_metrics.get("raw_unit"):
            features["wu_twc_observed_intraday_current_raw_unit"] = str(current_metrics.get("raw_unit") or "")
    if isinstance(max_since_metrics, Mapping):
        raw_value = to_float(max_since_metrics.get("raw_value"))
        if raw_value is not None:
            features["wu_twc_observed_intraday_max_since7am_raw_value"] = float(raw_value)
        if max_since_metrics.get("raw_unit"):
            features["wu_twc_observed_intraday_max_since7am_raw_unit"] = str(max_since_metrics.get("raw_unit") or "")
    for prefix, raw_obj in (
        ("wu_twc_observed_intraday_current_metric", current_metric_raw),
        ("wu_twc_observed_intraday_current_imperial", current_imperial_raw),
    ):
        if not isinstance(raw_obj, Mapping):
            continue
        if raw_obj.get("raw_unit"):
            features[f"{prefix}_raw_unit"] = str(raw_obj.get("raw_unit") or "")
        raw_current = to_float(raw_obj.get("current_raw_value"))
        raw_max = to_float(raw_obj.get("max_since7am_raw_value"))
        if raw_current is not None:
            features[f"{prefix}_raw_value"] = float(raw_current)
        if raw_max is not None:
            features[f"{prefix}_max_since7am_raw_value"] = float(raw_max)
        if raw_obj.get("observed_at"):
            features[f"{prefix}_raw_at"] = str(raw_obj.get("observed_at") or "")
    if age_minutes is not None:
        features["wu_twc_observed_intraday_age_minutes"] = float(age_minutes)
    if reference_dt is not None:
        features["wu_twc_observed_intraday_reference_observed_at"] = _iso_from_datetime(reference_dt)
    if current_temp_c is not None and math.isfinite(float(current_temp_c)):
        features["wu_twc_observed_intraday_current_temp_c"] = float(current_temp_c)
    if current_at is not None:
        features["wu_twc_observed_intraday_current_at"] = _iso_from_datetime(current_at)
        local_zone = timezone.utc
        if tz_name and ZoneInfo is not None:
            try:
                local_zone = ZoneInfo(str(tz_name))
            except Exception:
                local_zone = timezone.utc
        local_dt = current_at.astimezone(local_zone)
        features["wu_twc_observed_intraday_current_local"] = local_dt.isoformat()
        features["observation_hour_local"] = float(local_dt.hour + local_dt.minute / 60.0 + local_dt.second / 3600.0)
        features["observation_month"] = int(local_dt.month)
    if max_candidates:
        best_max, best_max_at, best_max_source = max(max_candidates, key=lambda item: item[0])
        features["wu_twc_observed_intraday_today_max_c"] = float(best_max)
        features["wu_twc_observed_intraday_today_max_source"] = best_max_source
        if best_max_at is not None:
            features["wu_twc_observed_intraday_today_max_at"] = _iso_from_datetime(best_max_at)
    temp_pairs = list(history_pairs)
    if current_at is not None and current_temp_c is not None and math.isfinite(float(current_temp_c)):
        temp_pairs.append((current_at.astimezone(timezone.utc), float(current_temp_c)))
    temp_pairs.sort(key=lambda item: item[0])
    deduped_pairs: List[Tuple[datetime, float]] = []
    seen_times: set[str] = set()
    for dt, val in temp_pairs:
        key = _iso_from_datetime(dt)
        if key in seen_times:
            continue
        seen_times.add(key)
        deduped_pairs.append((dt, val))
    if len(deduped_pairs) >= 2:
        _apply_temperature_trajectory_rates(
            features,
            deduped_pairs,
            source="wu_twc_observed_intraday",
        )
        _copy_temperature_momentum_to_source_namespace(features, "wu_twc_observed_intraday")
    if primary_current and current_temp_c is not None and math.isfinite(float(current_temp_c)):
        features["observed_temp"] = float(current_temp_c)
        features["observed_temp_c"] = float(current_temp_c)
        features["observed_temp_source"] = "wu_twc_observed_intraday_current"
    if primary_max and max_candidates:
        best_max, _best_max_at, best_max_source = max(max_candidates, key=lambda item: item[0])
        existing_observed_max = to_float(features.get("observed_today_max_c"))
        if existing_observed_max is None or float(best_max) >= float(existing_observed_max) - 1e-9:
            features["observed_today_max_c"] = float(best_max)
            features["observed_today_max_source"] = best_max_source
            features["observed_today_max_trusted"] = True
        else:
            features["observed_today_max_preserved_c"] = float(existing_observed_max)
            features["observed_today_max_preserved_source"] = str(features.get("observed_today_max_source") or "")
            features["observed_today_max_lower_candidate_c"] = float(best_max)
            features["observed_today_max_lower_candidate_source"] = best_max_source
    precision_profile = temperature_settlement_profile_from_wu_twc_features(
        features,
        rounding_rule=rounding_rule or "whole_degrees",
        settlement_unit=market_unit or "C",
    )
    if precision_profile:
        features["wu_twc_observed_intraday_settlement_precision"] = precision_profile
        features["wu_twc_observed_intraday_boundary_ambiguous"] = bool(
            precision_profile.get("boundary_ambiguous")
        )
        if precision_profile.get("ambiguous_reason"):
            features["wu_twc_observed_intraday_boundary_ambiguous_reason"] = str(
                precision_profile.get("ambiguous_reason") or ""
            )
    try:
        pws_rapid_features = fetch_twc_pws_rapid_history_aux_features(
            resolution_source,
            station or str(source_profile.get("station_id") or ""),
            event_key,
            tz=tz_name,
        )
        if pws_rapid_features:
            features.update(pws_rapid_features)
    except Exception as exc:
        features["twc_pws_rapid_history_aux_available"] = False
        features["twc_pws_rapid_history_aux_error"] = f"{exc.__class__.__name__}"
    if provenance is not None:
        provenance["feature_keys"] = sorted(features.keys())
        provenance["history_meta"] = history_meta
        provenance["request_started_at"] = request_started_at.isoformat()
        provenance["request_completed_at"] = request_completed_at.isoformat()
        provenance["request_duration_ms"] = request_duration_ms
        provenance["current_metrics_source"] = current_metrics.get("source") if isinstance(current_metrics, Mapping) else ""
        provenance["max_metrics_source"] = max_since_metrics.get("source") if isinstance(max_since_metrics, Mapping) else ""
    return features


def find_first_key(obj, keys: List[str]) -> Optional[Tuple[float, Optional[str]]]:
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k in keys:
                if isinstance(v, (int, float)):
                    return float(v), None
                if isinstance(v, dict):
                    val = v.get("value")
                    unit = v.get("unit") or v.get("units")
                    if isinstance(val, (int, float)):
                        return float(val), unit
            res = find_first_key(v, keys)
            if res is not None:
                return res
    elif isinstance(obj, list):
        for item in obj:
            res = find_first_key(item, keys)
            if res is not None:
                return res
    return None


def _parse_wunderground_json(html: str) -> Optional[Dict]:
    m = re.search(
        r'<script id="__NEXT_DATA__" type="application/json"[^>]*>(.*)</script>',
        html,
        flags=re.DOTALL,
    )
    if m:
        try:
            return json.loads(m.group(1))
        except Exception:
            pass
    scripts = re.findall(r"<script[^>]*>(.*?)</script>", html, flags=re.DOTALL)
    candidates = [s for s in scripts if s.strip().startswith("{") and s.strip().endswith("}")]
    candidates.sort(key=len, reverse=True)
    for sc in candidates:
        try:
            return json.loads(sc)
        except Exception:
            continue
    return None


def _extract_wunderground_hourly_api_url(html: str) -> Optional[str]:
    if not html:
        return None
    urls = re.findall(
        r"https://api\.weather\.com/v3/wx/forecast/hourly/15day\?[^\"'\\\s<>]+",
        html,
    )
    if not urls:
        return None
    return urls[0].replace("&amp;", "&")


def _extract_wunderground_inline_hourly_rows(
    html: str,
    *,
    hourly_api_url: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Read the hourly curve embedded in the public WU page response.

    WU renders a Weather.com hourly payload directly into its page.  The API
    URL embedded beside it can return a server-side 403 even when that page
    payload is present.  This parser is deliberately a fallback: it preserves
    the page's displayed forecast rather than treating a transport block as a
    missing forecast.
    """

    if not html:
        return []
    source_units = "F"
    if hourly_api_url:
        try:
            query = dict(parse_qsl(urlparse(hourly_api_url).query, keep_blank_values=True))
            source_units = "F" if str(query.get("units") or "e").lower() == "e" else "C"
        except Exception:
            pass
    candidates: List[Tuple[int, List[Any], List[Any]]] = []
    pattern = re.compile(
        r'"temperature":(?P<temperature>\[[^\]]*\]).{0,15000}?"validTimeLocal":(?P<valid_time>\[[^\]]*\])',
        flags=re.DOTALL,
    )
    for match in pattern.finditer(html):
        try:
            temperatures = json.loads(match.group("temperature"))
            valid_times = json.loads(match.group("valid_time"))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(temperatures, list) or not isinstance(valid_times, list) or len(temperatures) != len(valid_times):
            continue
        if not temperatures:
            continue
        candidates.append((len(temperatures), temperatures, valid_times))
    if not candidates:
        return []
    _size, temperatures, valid_times = max(candidates, key=lambda item: item[0])
    rows: List[Dict[str, Any]] = []
    for temperature, valid_time in zip(temperatures, valid_times):
        if not isinstance(temperature, (int, float)) or not isinstance(valid_time, str) or not valid_time:
            continue
        value = float(temperature)
        rows.append(
            {
                "valid_time_local": valid_time,
                "valid_time_utc": None,
                "temperature": value,
                "unit": source_units,
                "source_temperature": value,
                "source_unit": source_units,
                "derived_from": "wunderground_hourly_page_inline_payload",
                "native_decimal": isinstance(temperature, float) and not value.is_integer(),
            }
        )
    return rows


def _wunderground_forecast_hourly_source(resolution_source: Optional[str]) -> str:
    source = str(resolution_source or "").strip()
    if not source:
        return ""
    parsed = urlparse(source)
    host = parsed.netloc.lower()
    if "wunderground.com" not in host:
        return source
    path = parsed.path or ""
    path = re.sub(r"/date/\d{4}-\d{2}-\d{2}/?$", "", path, flags=re.I)
    if re.search(r"/hourly/", path, flags=re.I):
        hourly_path = path
    elif re.search(r"/history/daily/", path, flags=re.I):
        hourly_path = re.sub(r"/history/daily/", "/hourly/", path, count=1, flags=re.I)
    elif re.search(r"/weather/", path, flags=re.I):
        hourly_path = re.sub(r"/weather/", "/hourly/", path, count=1, flags=re.I)
    else:
        hourly_path = path
    return urlunparse(parsed._replace(path=hourly_path, query="", fragment=""))


def _with_query_param(url: str, key: str, value: str) -> str:
    parsed = urlparse(url)
    pairs = parse_qsl(parsed.query or "", keep_blank_values=True)
    replaced = False
    updated: List[Tuple[str, str]] = []
    for k, v in pairs:
        if k == key:
            updated.append((k, value))
            replaced = True
        else:
            updated.append((k, v))
    if not replaced:
        updated.append((key, value))
    return urlunparse(parsed._replace(query=urlencode(updated)))


def fetch_wunderground_hourly_temperatures(
    resolution_source: Optional[str],
    *,
    market_unit: Optional[str] = "C",
    require_native_decimal: bool = False,
) -> List[Dict[str, Any]]:
    source = str(resolution_source or "").strip()
    if not source or "wunderground.com" not in source:
        return []
    try:
        r = requests_get(
            source,
            headers=DEFAULT_REQUEST_HEADERS,
            timeout=30,
            bypass_proxy=True,
            retries=3,
        )
    except Exception:
        return []
    if getattr(r, "status_code", None) != 200:
        return []
    api_url = _extract_wunderground_hourly_api_url(getattr(r, "text", "") or "")
    if not api_url:
        return []
    inline_rows = _extract_wunderground_inline_hourly_rows(getattr(r, "text", "") or "", hourly_api_url=api_url)
    unit = str(market_unit or "").upper()
    unit_preferences = ["e", "m"] if unit == "F" else ["m", "e"]
    best_rows: List[Dict[str, Any]] = []
    for source_units in unit_preferences:
        unit_api_url = _with_query_param(api_url, "units", source_units)
        try:
            api_resp = requests_get(
                unit_api_url,
                headers=DEFAULT_REQUEST_HEADERS,
                timeout=30,
                bypass_proxy=True,
                retries=3,
            )
            if getattr(api_resp, "status_code", None) == 403:
                api_resp = requests_get(
                    unit_api_url,
                    headers=DEFAULT_REQUEST_HEADERS,
                    timeout=30,
                    bypass_proxy=False,
                    retries=1,
                )
            payload = api_resp.json()
        except Exception:
            continue
        temps = payload.get("temperature") if isinstance(payload, dict) else None
        valid_local = payload.get("validTimeLocal") if isinstance(payload, dict) else None
        valid_utc = payload.get("validTimeUtc") if isinstance(payload, dict) else None
        if not isinstance(temps, list):
            continue
        source_unit = "F" if source_units == "e" else "C"
        rows: List[Dict[str, Any]] = []
        for i, raw in enumerate(temps):
            if not isinstance(raw, (int, float)):
                continue
            value = float(raw)
            rows.append(
                {
                    "valid_time_local": (
                        valid_local[i]
                        if isinstance(valid_local, list) and i < len(valid_local)
                        else ""
                    ),
                    "valid_time_utc": (
                        valid_utc[i]
                        if isinstance(valid_utc, list) and i < len(valid_utc)
                        else None
                    ),
                    "temperature": value,
                    "unit": source_unit,
                    "source_temperature": value,
                    "source_unit": source_unit,
                    "derived_from": "",
                    "native_decimal": isinstance(raw, float) and not float(raw).is_integer(),
                }
            )
        if rows and not best_rows:
            best_rows = rows
        if any(row.get("native_decimal") for row in rows):
            return rows
    if require_native_decimal:
        return []
    return best_rows or inline_rows


def _forecast_peak_plateau_from_hourly_rows(
    rows: Sequence[Mapping[str, Any]],
    event_date: str,
    *,
    market_unit: Optional[str],
    source: str,
) -> Dict[str, Any]:
    event_key = _normalize_date_key(str(event_date or ""))
    unit = normalize_unit(market_unit) or "C"
    threshold = _env_float("PM_WU_TWC_PEAK_PLATEAU_THRESHOLD_C")
    if threshold is None or not math.isfinite(float(threshold)) or float(threshold) < 0:
        threshold = 0.3
    threshold = max(0.0, min(2.0, float(threshold)))

    candidates: List[Dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        valid_local = str(
            row.get("valid_time_local")
            or row.get("validTimeLocal")
            or row.get("forecast_valid_local")
            or row.get("time")
            or ""
        ).strip()
        if event_key and not valid_local.startswith(event_key):
            continue
        temp = to_float(row.get("temperature") if row.get("temperature") is not None else row.get("value"))
        if temp is None or not math.isfinite(float(temp)):
            continue
        row_unit = normalize_unit(row.get("unit") or row.get("source_unit") or unit) or unit
        temp_c = _convert_temp_value(float(temp), row_unit, "C")
        if not math.isfinite(float(temp_c)):
            continue
        hour_local: Optional[float] = None
        if valid_local:
            try:
                dt = datetime.fromisoformat(valid_local.replace("Z", "+00:00"))
                hour_local = float(dt.hour) + float(dt.minute) / 60.0 + float(dt.second) / 3600.0
            except Exception:
                hour_match = re.search(r"T(\d{1,2})(?::?(\d{2}))?", valid_local)
                if hour_match:
                    hour_local = float(hour_match.group(1)) + float(hour_match.group(2) or 0) / 60.0
        if hour_local is None:
            hour_local = to_float(row.get("hour_local") or row.get("hour"))
        if hour_local is None or not math.isfinite(float(hour_local)):
            continue
        hour_local = max(0.0, min(23.99, float(hour_local)))
        candidates.append(
            {
                "hour_local": hour_local,
                "temperature_c": float(temp_c),
                "valid_time_local": valid_local,
                "source_temperature": float(temp),
                "source_unit": row_unit,
            }
        )

    if not candidates:
        return {
            "available": False,
            "source": source,
            "basis": "hourly_near_peak_plateau",
            "event_date": event_key,
            "threshold_c": float(threshold),
            "na_reason": "event_date_hourly_temperatures_missing",
        }

    max_temp_c = max(float(item["temperature_c"]) for item in candidates)
    plateau = [
        item for item in candidates
        if float(item["temperature_c"]) >= max_temp_c - float(threshold) - 1e-9
    ]
    if not plateau:
        plateau = [max(candidates, key=lambda item: (float(item["temperature_c"]), float(item["hour_local"])))]

    by_hour: Dict[float, Dict[str, Any]] = {}
    for item in plateau:
        hour = float(item["hour_local"])
        hour_key = round(hour, 4)
        existing = by_hour.get(hour_key)
        if existing is None or float(item["temperature_c"]) > float(existing["temperature_c"]):
            by_hour[hour_key] = item
    plateau = sorted(by_hour.values(), key=lambda item: float(item["hour_local"]))

    raw_weights: List[float] = []
    denom = max(0.01, float(threshold))
    for item in plateau:
        delta = max(0.0, max_temp_c - float(item["temperature_c"]))
        raw_weights.append(max(0.25, 1.0 - delta / denom))
    weight_total = sum(raw_weights) or 1.0
    distribution: List[Dict[str, Any]] = []
    for item, weight in zip(plateau, raw_weights):
        distribution.append(
            {
                "hour_local": float(item["hour_local"]),
                "prob": float(weight) / float(weight_total),
                "temperature_c": float(item["temperature_c"]),
                "valid_time_local": str(item.get("valid_time_local") or ""),
            }
        )

    center_hour = sum(float(item["hour_local"]) * float(item["prob"]) for item in distribution)
    start_hour = min(float(item["hour_local"]) for item in distribution)
    end_hour = max(float(item["hour_local"]) for item in distribution)
    center_row = min(distribution, key=lambda item: abs(float(item["hour_local"]) - float(center_hour)))
    return {
        "available": True,
        "source": source,
        "basis": "hourly_near_peak_plateau",
        "event_date": event_key,
        "threshold_c": float(threshold),
        "max_temp_c": float(max_temp_c),
        "candidate_count": len(candidates),
        "plateau_count": len(distribution),
        "expected_peak_hour_local": float(center_hour),
        "expected_peak_at_local": str(center_row.get("valid_time_local") or ""),
        "expected_peak_window_start_hour_local": float(start_hour),
        "expected_peak_window_end_hour_local": float(end_hour),
        "expected_peak_hour_distribution": distribution,
        "plateau_rows": distribution,
    }


def _copy_forecast_peak_plateau_features(
    features: Dict[str, Any],
    *,
    prefix: str,
    metrics: Mapping[str, Any],
    canonical: bool = False,
    canonical_replace: bool = False,
) -> None:
    if not isinstance(features, dict) or not isinstance(metrics, Mapping):
        return
    raw_distribution = metrics.get("expected_peak_hour_distribution") or metrics.get("peak_hour_distribution")
    distribution: List[Dict[str, Any]] = []
    if isinstance(raw_distribution, list):
        for row in raw_distribution:
            if not isinstance(row, Mapping):
                continue
            hour = to_float(row.get("hour_local") or row.get("hour") or row.get("peak_hour"))
            prob = to_float(row.get("prob") or row.get("probability") or row.get("weight"))
            if hour is None or prob is None or not math.isfinite(float(hour)) or not math.isfinite(float(prob)):
                continue
            if float(prob) <= 0:
                continue
            item: Dict[str, Any] = {
                "hour_local": max(0.0, min(23.99, float(hour))),
                "prob": max(0.0, float(prob)),
            }
            temp_c = to_float(row.get("temperature_c") or row.get("temp_c"))
            if temp_c is not None and math.isfinite(float(temp_c)):
                item["temperature_c"] = float(temp_c)
            valid_local = str(row.get("valid_time_local") or row.get("expected_peak_at_local") or "").strip()
            if valid_local:
                item["valid_time_local"] = valid_local
            distribution.append(item)
    total = sum(float(row.get("prob") or 0.0) for row in distribution)
    if total > 0:
        distribution = [
            {
                **row,
                "prob": float(row.get("prob") or 0.0) / float(total),
            }
            for row in distribution
        ]
        distribution.sort(key=lambda row: float(row.get("hour_local") or 0.0))
        start = to_float(metrics.get("expected_peak_window_start_hour_local"))
        end = to_float(metrics.get("expected_peak_window_end_hour_local"))
        center = to_float(metrics.get("expected_peak_hour_local"))
        if start is None:
            start = min(float(row["hour_local"]) for row in distribution)
        if end is None:
            end = max(float(row["hour_local"]) for row in distribution)
        if center is None:
            center = sum(float(row["hour_local"]) * float(row["prob"]) for row in distribution)
        source = str(metrics.get("source") or prefix).strip() or prefix
        features[f"{prefix}_peak_hour_distribution"] = distribution
        features[f"{prefix}_peak_hour_distribution_source"] = source
        features[f"{prefix}_peak_hour_distribution_basis"] = "hourly_near_peak_plateau"
        features[f"{prefix}_peak_window_start_hour_local"] = float(start)
        features[f"{prefix}_peak_window_end_hour_local"] = float(end)
        features[f"{prefix}_expected_peak_hour_local"] = float(center)
        if metrics.get("expected_peak_at_local"):
            features[f"{prefix}_expected_peak_at_local"] = str(metrics.get("expected_peak_at_local") or "")
        for key in ("peak_plateau_threshold_c", "peak_plateau_max_temp_c", "peak_plateau_count"):
            value = metrics.get(key)
            if value not in (None, ""):
                features[f"{prefix}_{key}"] = value
        plateau = metrics.get("peak_plateau")
        if isinstance(plateau, Mapping):
            features[f"{prefix}_peak_plateau"] = dict(plateau)
        if canonical and (canonical_replace or not features.get("expected_peak_hour_distribution")):
            features["expected_peak_hour_distribution"] = distribution
            features["peak_hour_distribution"] = distribution
            features["expected_peak_hour_local"] = float(center)
            features["expected_peak_at_local"] = str(metrics.get("expected_peak_at_local") or "")
            features["expected_peak_window_start_hour_local"] = float(start)
            features["expected_peak_window_end_hour_local"] = float(end)
            features["expected_peak_hour_source"] = f"{source}:hourly_near_peak_plateau"
            features["expected_peak_window_source"] = f"{source}:hourly_near_peak_plateau"
        return
    reason = str(
        metrics.get("expected_peak_hour_distribution_na_reason")
        or metrics.get("peak_hour_distribution_na_reason")
        or (metrics.get("peak_plateau") or {}).get("na_reason")
        or ""
    ).strip()
    if reason:
        features[f"{prefix}_peak_hour_distribution_na_reason"] = reason


def _find_daily_temp_value(data: Dict, date: str, kind: str) -> Optional[float]:
    target_key = "temperatureMax" if kind == "max" else "temperatureMin"

    def walk(obj):
        if isinstance(obj, dict):
            vtl = obj.get("validTimeLocal")
            if isinstance(vtl, list) and target_key in obj:
                for i, t in enumerate(vtl):
                    if isinstance(t, str) and t.startswith(date):
                        arr = obj.get(target_key)
                        if isinstance(arr, list) and i < len(arr):
                            val = arr[i]
                            if isinstance(val, (int, float)):
                                return float(val)
            for v in obj.values():
                res = walk(v)
                if res is not None:
                    return res
        elif isinstance(obj, list):
            for it in obj:
                res = walk(it)
                if res is not None:
                    return res
        return None

    return walk(data)


def fetch_wunderground_daily_temp(
    resolution_source: Optional[str],
    date: str,
    kind: str,
    market_unit: Optional[str],
    *,
    timeout: Union[int, float, Tuple[float, float]] = 30,
    retries: int = 3,
) -> Optional[float]:
    if not resolution_source:
        return None
    source_profile = weather_resolution_source_profile(resolution_source)
    if source_profile.get("source_kind") != "wunderground_history":
        return None
    base_url = resolution_source.rstrip("/")
    if re.search(r"/history/daily/cn/chengdu/ZUUU$", base_url, flags=re.I):
        base_url = re.sub(r"/ZUUU$", "", base_url, flags=re.I)
    url = base_url + f"/date/{date}"
    r = requests_get(url, timeout=timeout, bypass_proxy=True, retries=retries)
    if r.status_code != 200:
        return None
    data = _parse_wunderground_json(r.text)
    if not data:
        return None
    val = _find_daily_temp_value(data, date, kind)
    if val is None:
        keys = [
            "maxTemperature",
            "temperatureMax",
            "temperatureHigh",
            "maxTemp",
            "maxTempC",
            "highTemp",
        ]
        if kind == "min":
            keys = [
                "minTemperature",
                "temperatureMin",
                "temperatureLow",
                "minTemp",
                "minTempC",
                "lowTemp",
            ]
        found = find_first_key(data, keys)
        if not found:
            # WU /weather pages are auxiliary only; keep this disabled unless explicitly
            # enabled for diagnostics outside trading/settlement.
            if _env_bool("PM_WU_ALLOW_WEATHER_PAGE_AUX_FALLBACK", False) and "/history/daily/" in resolution_source:
                alt_url = resolution_source.replace("/history/daily/", "/weather/").rstrip("/") + f"/date/{date}"
                r2 = requests_get(alt_url, timeout=timeout, bypass_proxy=True, retries=retries)
                if r2.status_code == 200:
                    data2 = _parse_wunderground_json(r2.text)
                    if data2:
                        val2 = _find_daily_temp_value(data2, date, kind)
                        if isinstance(val2, (int, float)):
                            if market_unit == "C":
                                return (float(val2) - 32.0) * 5.0 / 9.0
                            return float(val2)
                        found2 = find_first_key(data2, keys)
                        if found2:
                            val2, unit2 = found2
                            if unit2 and str(unit2).upper().startswith("F") and market_unit == "C":
                                return (val2 - 32.0) * 5.0 / 9.0
                            return float(val2)
            return None
        val, unit = found
        if unit and str(unit).upper().startswith("F") and market_unit == "C":
            return (val - 32.0) * 5.0 / 9.0
        return float(val)
    if market_unit == "C":
        return (val - 32.0) * 5.0 / 9.0
    return float(val)


def _wu_forecast_request_timeout() -> Tuple[float, float]:
    raw = _env_float("PM_WU_FORECAST_TIMEOUT_SEC")
    if raw is None or not math.isfinite(float(raw)) or float(raw) <= 0:
        raw = min(4.0, float(BAYES_LIKELIHOOD_AUX_TIMEOUT_SEC))
    total = max(1.0, min(8.0, float(raw)))
    connect = max(0.5, min(2.0, total * 0.5))
    read = max(0.75, total)
    return (float(connect), float(read))


def _wu_forecast_request_retries() -> int:
    raw = _env_int("PM_WU_FORECAST_RETRIES")
    if raw is None or raw < 1:
        raw = 1
    return max(1, min(int(raw), 2))


def fetch_wunderground_forecast_peak_metrics(
    resolution_source: Optional[str],
    event_date: str,
    market_var: Optional[str],
    market_unit: Optional[str],
) -> Dict[str, Any]:
    source = str(resolution_source or "").strip()
    kind = _market_var_extreme_kind(market_var)
    if not source or not event_date:
        return {"ok": False, "error": "missing_source_or_date"}
    if kind != "max":
        return {"ok": False, "error": "market_var_unsupported"}
    source_profile = weather_resolution_source_profile(source)
    if source_profile.get("source_kind") != "wunderground_history":
        return {"ok": False, "error": "resolution_source_not_wunderground_history"}
    local_tz = _effective_weather_likelihood_tz("", source)
    local_today_dt = datetime.now(timezone.utc)
    if ZoneInfo is not None:
        try:
            local_today_dt = local_today_dt.astimezone(ZoneInfo(local_tz))
        except Exception:
            local_today_dt = local_today_dt.astimezone(timezone.utc)
    event_day = _parse_date(event_date)
    if (
        event_day is not None
        and event_day < local_today_dt.date()
            and not _env_bool("PM_WU_FORECAST_ALLOW_PAST_DATES", False)
    ):
        return {"ok": False, "error": "event_date_not_forecast"}
    request_timeout = _wu_forecast_request_timeout()
    request_retries = _wu_forecast_request_retries()
    forecast_source = _wunderground_forecast_hourly_source(source)
    unit = normalize_unit(market_unit) or "C"
    peak_at = ""
    hourly_peak_c: Optional[float] = None
    event_key = str(event_date or "")[:10]
    hourly_rows = fetch_wunderground_hourly_temperatures(
        forecast_source,
        market_unit=unit,
        require_native_decimal=False,
    )
    plateau = _forecast_peak_plateau_from_hourly_rows(
        hourly_rows,
        event_key,
        market_unit=unit,
        source="wunderground_hourly_forecast_plateau",
    )
    hourly_candidates: List[Tuple[float, str]] = []
    for row in hourly_rows:
        if not isinstance(row, Mapping):
            continue
        valid_local = str(row.get("valid_time_local") or "")
        if event_key and not valid_local.startswith(event_key):
            continue
        temp = to_float(row.get("temperature"))
        if temp is None or not math.isfinite(float(temp)):
            continue
        temp_c = _convert_temp_value(float(temp), normalize_unit(row.get("unit") or unit) or unit, "C")
        hourly_candidates.append((float(temp_c), valid_local))
    if hourly_candidates:
        hourly_peak_c, peak_at = max(hourly_candidates, key=lambda item: (item[0], item[1]))
    if plateau.get("available") and plateau.get("expected_peak_at_local"):
        peak_at = str(plateau.get("expected_peak_at_local") or peak_at)
    value = fetch_wunderground_daily_temp(
        source,
        event_date,
        kind,
        market_unit,
        timeout=request_timeout,
        retries=request_retries,
    )
    if value is None or not math.isfinite(float(value)):
        if hourly_peak_c is None:
            return {"ok": False, "error": "forecast_peak_missing"}
        value = _convert_temp_value(float(hourly_peak_c), "C", unit)
    value_c, value_f = _forecast_temp_units(float(value), unit)
    plateau_valid = bool(plateau.get("available"))
    max_gap = _env_float("PM_WU_TWC_PEAK_PLATEAU_MAX_DAILY_GAP_C")
    if max_gap is None or not math.isfinite(float(max_gap)) or float(max_gap) <= 0:
        max_gap = 1.0
    plateau_max_c = to_float(plateau.get("max_temp_c"))
    if plateau_valid and plateau_max_c is not None and abs(float(value_c) - float(plateau_max_c)) > float(max_gap):
        plateau = dict(plateau)
        plateau["available"] = False
        plateau["na_reason"] = "hourly_plateau_max_far_from_daily_peak"
        plateau["daily_peak_c"] = float(value_c)
        plateau["daily_peak_gap_c"] = abs(float(value_c) - float(plateau_max_c))
        plateau_valid = False
        peak_at = ""
    return {
        "ok": True,
        "value": float(value),
        "value_c": value_c,
        "value_f": value_f,
        "unit": unit,
        "source": "wunderground_forecast_daily_peak",
        "wu_settlement_page": "Wunderground settlement display page",
        "wu_settlement_page_url": source,
        "wu_settlement_page_role": "polymarket_settlement_display_page",
        "twc_provider": "Weather.com/TWC",
        "twc_provider_role": "weather_api_provider_wrapper_not_sensor_origin",
        "source_fit_tier": "settlement_source_forecast",
        "source_trust_tier": "soft_forecast",
        "source_usable_for_settlement": False,
        "event_date": event_key,
        "peak_at": peak_at,
        "peak_time_source": "wunderground_hourly_forecast_plateau" if plateau_valid else "",
        "peak_plateau": plateau,
        "expected_peak_hour_distribution": plateau.get("expected_peak_hour_distribution") if plateau_valid else [],
        "expected_peak_hour_local": plateau.get("expected_peak_hour_local") if plateau_valid else None,
        "expected_peak_at_local": plateau.get("expected_peak_at_local") if plateau_valid else "",
        "expected_peak_window_start_hour_local": plateau.get("expected_peak_window_start_hour_local") if plateau_valid else None,
        "expected_peak_window_end_hour_local": plateau.get("expected_peak_window_end_hour_local") if plateau_valid else None,
        "expected_peak_hour_distribution_na_reason": "" if plateau_valid else str(plateau.get("na_reason") or "hourly_peak_plateau_unavailable"),
        "peak_plateau_threshold_c": plateau.get("threshold_c"),
        "peak_plateau_max_temp_c": plateau.get("max_temp_c"),
        "peak_plateau_count": plateau.get("plateau_count"),
        "forecast_source_url": forecast_source,
        "hourly_forecast_source_url": forecast_source,
        "hourly_curve": [
            {"valid_time_local": valid_local, "temperature_c": float(temp_c)}
            for temp_c, valid_local in sorted(hourly_candidates, key=lambda item: item[1])
        ],
        "station_id": str(source_profile.get("station_id") or "").strip().upper(),
        "resolution_source": source,
        "request_timeout": list(request_timeout),
        "request_retries": int(request_retries),
    }


def _weather_com_forecast_request_timeout() -> Tuple[float, float]:
    raw = _env_float("PM_WEATHER_COM_FORECAST_TIMEOUT_SEC")
    if raw is None or not math.isfinite(float(raw)) or float(raw) <= 0:
        raw = min(4.0, float(BAYES_LIKELIHOOD_AUX_TIMEOUT_SEC))
    total = max(1.0, min(8.0, float(raw)))
    connect = max(0.5, min(2.0, total * 0.5))
    read = max(0.75, total)
    return (float(connect), float(read))


def _weather_com_forecast_request_retries() -> int:
    raw = _env_int("PM_WEATHER_COM_FORECAST_RETRIES")
    if raw is None or raw < 1:
        raw = 1
    return max(1, min(int(raw), 2))


def _weather_com_api_key() -> str:
    return str(
        os.environ.get("PM_WEATHER_COM_API_KEY")
        or os.environ.get("PM_WU_HISTORY_API_KEY")
        or "6532d6454b8aa370768e63d6ba5a832e"
    ).strip()


def _redact_weather_com_api_key(url: str) -> str:
    if not url:
        return ""
    return re.sub(r"([?&]apiKey=)[^&]+", r"\1***", str(url))


def _weather_com_daily_index(payload: Mapping[str, Any], event_date: str) -> Optional[int]:
    target = _normalize_date_key(str(event_date or ""))
    if not target:
        return None
    for key in ("validTimeLocal", "fcstValidLocal", "validTimeUtc"):
        values = payload.get(key)
        if not isinstance(values, list):
            continue
        for idx, raw in enumerate(values):
            raw_text = str(raw or "").strip()
            if raw_text[:10] == target:
                return idx
    return None


def _weather_com_daily_value(payload: Mapping[str, Any], idx: int, kind: str) -> Optional[float]:
    keys = (
        ("calendarDayTemperatureMax", "temperatureMax", "temperatureHigh", "maxTemperature")
        if kind == "max"
        else ("calendarDayTemperatureMin", "temperatureMin", "temperatureLow", "minTemperature")
    )
    for key in keys:
        values = payload.get(key)
        if not isinstance(values, list) or idx >= len(values):
            continue
        value = values[idx]
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            return float(value)
    return None


def fetch_weather_com_forecast_peak_metrics(
    lat: Optional[float],
    lon: Optional[float],
    event_date: str,
    market_var: Optional[str],
    market_unit: Optional[str],
    *,
    station_id: Optional[str] = None,
    resolution_source: Optional[str] = None,
    include_capture_evidence: bool = False,
) -> Dict[str, Any]:
    kind = _market_var_extreme_kind(market_var)
    if kind != "max":
        return {"ok": False, "error": "market_var_unsupported"}
    event_key = _normalize_date_key(str(event_date or ""))
    if not event_key:
        return {"ok": False, "error": "missing_event_date"}
    lat_val = to_float(lat)
    lon_val = to_float(lon)
    if lat_val is None or lon_val is None:
        return {"ok": False, "error": "missing_geocode"}
    api_key = _weather_com_api_key()
    if not api_key:
        return {"ok": False, "error": "weather_com_api_key_missing"}
    unit = normalize_unit(market_unit) or "C"
    api_units = "e" if unit == "F" else "m"
    request_timeout = _weather_com_forecast_request_timeout()
    request_retries = _weather_com_forecast_request_retries()
    params = {
        "geocode": f"{float(lat_val):.6f},{float(lon_val):.6f}",
        "format": "json",
        "units": api_units,
        "language": "en-US",
        "apiKey": api_key,
    }
    requested_at = utc_now_iso() if include_capture_evidence else ""
    response_started_at = ""
    response_completed_at = ""
    raw_provider_response_utf8 = ""
    try:
        response = requests_get(
            WEATHER_COM_DAILY_FORECAST_URL,
            params=params,
            timeout=request_timeout,
            bypass_proxy=False,
            retries=request_retries,
            backoff=0.5,
            stream=include_capture_evidence,
        )
    except Exception as exc:
        return {"ok": False, "error": f"request_error:{exc.__class__.__name__}"}
    if include_capture_evidence:
        # stream=True returns after provider response headers.  Record this
        # receipt before consuming the body; a request-start timestamp is not
        # acceptable Tier-A arrival evidence.
        response_started_at = utc_now_iso()
        raw_provider_response_utf8 = str(getattr(response, "text", "") or "")
        response_completed_at = utc_now_iso()
        close_streaming_requests_response(response)
    safe_url = _redact_weather_com_api_key(getattr(response, "url", "") or WEATHER_COM_DAILY_FORECAST_URL)
    if response.status_code != 200:
        return {
            "ok": False,
            "error": f"http_{response.status_code}",
            "source_url": safe_url,
            "request_timeout": list(request_timeout),
            "request_retries": int(request_retries),
        }
    try:
        payload = response.json()
    except Exception as exc:
        return {
            "ok": False,
            "error": f"json_error:{exc.__class__.__name__}",
            "source_url": safe_url,
        }
    if not isinstance(payload, Mapping):
        return {"ok": False, "error": "payload_not_object", "source_url": safe_url}
    idx = _weather_com_daily_index(payload, event_key)
    if idx is None:
        return {"ok": False, "error": "event_date_not_in_weather_com_forecast", "source_url": safe_url}
    value = _weather_com_daily_value(payload, idx, kind)
    if value is None:
        return {"ok": False, "error": "forecast_peak_missing", "source_url": safe_url}
    value_c, value_f = _forecast_temp_units(float(value), unit)
    valid_local = None
    valid_values = payload.get("validTimeLocal")
    if isinstance(valid_values, list) and idx < len(valid_values):
        valid_local = str(valid_values[idx] or "")
    result = {
        "ok": True,
        "value": float(value),
        "value_c": value_c,
        "value_f": value_f,
        "unit": unit,
        "source": "weather_com_forecast_daily_peak",
        "source_url": safe_url,
        "twc_provider": "Weather.com/TWC",
        "twc_provider_role": "weather_api_provider_wrapper_not_sensor_origin",
        "source_fit_tier": "weather_com_daily_forecast",
        "source_trust_tier": "soft_forecast_display_only",
        "source_usable_for_settlement": False,
        "soft": True,
        "not_observed_nowcast": True,
        "posterior_included": False,
        "posterior_status": "display_only_not_in_main_posterior",
        "posterior_label": "独立抓取，仅数值对比",
        "not_in_posterior_reason": "display_only_pending_created_at_walk_forward_and_provider_dedupe",
        "event_date": event_key,
        "forecast_valid_local": valid_local,
        "station_id": _normalize_station_code(station_id),
        "resolution_source": str(resolution_source or ""),
        "geocode": params["geocode"],
        "request_timeout": list(request_timeout),
        "request_retries": int(request_retries),
    }
    if include_capture_evidence:
        # This evidence is deliberately opt-in.  The production caller keeps
        # its existing compact metrics payload; the research forward collector
        # alone owns immutable raw-response retention and its observed clock.
        result.update(
            {
                "requested_at": requested_at,
                "response_started_at": response_started_at,
                "response_completed_at": response_completed_at,
                "capture_time_provenance": "observed_transport",
                "response_headers_observed": True,
                "raw_provider_response_utf8": raw_provider_response_utf8,
            }
        )
    return result


def fetch_weather_com_hourly_peak_metrics(
    lat: Optional[float],
    lon: Optional[float],
    event_date: str,
    market_var: Optional[str],
    market_unit: Optional[str],
    *,
    station_id: Optional[str] = None,
    resolution_source: Optional[str] = None,
    include_capture_evidence: bool = False,
) -> Dict[str, Any]:
    kind = _market_var_extreme_kind(market_var)
    if kind != "max":
        return {"ok": False, "error": "market_var_unsupported"}
    event_key = _normalize_date_key(str(event_date or ""))
    if not event_key:
        return {"ok": False, "error": "missing_event_date"}
    lat_val = to_float(lat)
    lon_val = to_float(lon)
    if lat_val is None or lon_val is None:
        return {"ok": False, "error": "missing_geocode"}
    api_key = _weather_com_api_key()
    if not api_key:
        return {"ok": False, "error": "weather_com_api_key_missing"}
    unit = normalize_unit(market_unit) or "C"
    api_units = "e" if unit == "F" else "m"
    request_timeout = _weather_com_forecast_request_timeout()
    request_retries = _weather_com_forecast_request_retries()
    params = {
        "geocode": f"{float(lat_val):.6f},{float(lon_val):.6f}",
        "format": "json",
        "units": api_units,
        "language": "en-US",
        "apiKey": api_key,
    }
    requested_at = utc_now_iso() if include_capture_evidence else ""
    response_started_at = ""
    response_completed_at = ""
    raw_provider_response_utf8 = ""
    try:
        response = requests_get(
            WEATHER_COM_HOURLY_FORECAST_URL,
            params=params,
            timeout=request_timeout,
            bypass_proxy=False,
            retries=request_retries,
            backoff=0.5,
            stream=include_capture_evidence,
        )
    except Exception as exc:
        return {"ok": False, "error": f"request_error:{exc.__class__.__name__}"}
    if include_capture_evidence:
        # See the daily path above: response headers, then body, then close.
        response_started_at = utc_now_iso()
        raw_provider_response_utf8 = str(getattr(response, "text", "") or "")
        response_completed_at = utc_now_iso()
        close_streaming_requests_response(response)
    safe_url = _redact_weather_com_api_key(getattr(response, "url", "") or WEATHER_COM_HOURLY_FORECAST_URL)
    if response.status_code != 200:
        return {
            "ok": False,
            "error": f"http_{response.status_code}",
            "source_url": safe_url,
            "request_timeout": list(request_timeout),
            "request_retries": int(request_retries),
        }
    try:
        payload = response.json()
    except Exception as exc:
        return {"ok": False, "error": f"json_error:{exc.__class__.__name__}", "source_url": safe_url}
    if not isinstance(payload, Mapping):
        return {"ok": False, "error": "payload_not_object", "source_url": safe_url}
    temps = payload.get("temperature")
    valid_local = payload.get("validTimeLocal")
    if not isinstance(temps, list) or not isinstance(valid_local, list):
        return {"ok": False, "error": "hourly_temperature_or_time_missing", "source_url": safe_url}
    candidates: List[Tuple[float, str, float]] = []
    for idx, raw in enumerate(temps):
        time_text = str(valid_local[idx] if idx < len(valid_local) else "" or "")
        if event_key and not time_text.startswith(event_key):
            continue
        temp = to_float(raw)
        if temp is None or not math.isfinite(float(temp)):
            continue
        temp_c = _convert_temp_value(float(temp), unit, "C")
        candidates.append((float(temp_c), time_text, float(temp)))
    if not candidates:
        return {"ok": False, "error": "event_date_not_in_weather_com_hourly_forecast", "source_url": safe_url}
    peak_c, peak_at, peak_value = max(candidates, key=lambda item: (item[0], item[1]))
    hourly_rows = [
        {
            "valid_time_local": time_text,
            "temperature": raw_value,
            "unit": unit,
        }
        for _temp_c, time_text, raw_value in candidates
    ]
    plateau = _forecast_peak_plateau_from_hourly_rows(
        hourly_rows,
        event_key,
        market_unit=unit,
        source="weather_com_forecast_hourly_peak_plateau",
    )
    if plateau.get("available") and plateau.get("expected_peak_at_local"):
        peak_at = str(plateau.get("expected_peak_at_local") or peak_at)
    value_c, value_f = _forecast_temp_units(float(peak_value), unit)
    result = {
        "ok": True,
        "value": float(peak_value),
        "value_c": value_c,
        "value_f": value_f,
        "unit": unit,
        "source": "weather_com_forecast_hourly_peak",
        "source_url": safe_url,
        "twc_provider": "Weather.com/TWC",
        "twc_provider_role": "weather_api_provider_wrapper_not_sensor_origin",
        "source_fit_tier": "weather_com_hourly_forecast",
        "source_trust_tier": "soft_forecast_display_only",
        "source_usable_for_settlement": False,
        "soft": True,
        "not_observed_nowcast": True,
        "posterior_included": False,
        "posterior_status": "display_only_not_in_main_posterior",
        "posterior_label": "逐小时预报，仅用于峰值时间窗口",
        "not_in_posterior_reason": "display_only_peak_window_not_main_posterior",
        "event_date": event_key,
        "peak_at": peak_at,
        "peak_plateau": plateau,
        "expected_peak_hour_distribution": plateau.get("expected_peak_hour_distribution") if plateau.get("available") else [],
        "expected_peak_hour_local": plateau.get("expected_peak_hour_local"),
        "expected_peak_at_local": plateau.get("expected_peak_at_local"),
        "expected_peak_window_start_hour_local": plateau.get("expected_peak_window_start_hour_local"),
        "expected_peak_window_end_hour_local": plateau.get("expected_peak_window_end_hour_local"),
        "peak_plateau_threshold_c": plateau.get("threshold_c"),
        "peak_plateau_max_temp_c": plateau.get("max_temp_c"),
        "peak_plateau_count": plateau.get("plateau_count"),
        "hourly_curve": [
            {"valid_time_local": time_text, "temperature_c": float(temp_c)}
            for temp_c, time_text, _raw_value in sorted(candidates, key=lambda item: item[1])
        ],
        "station_id": _normalize_station_code(station_id),
        "resolution_source": str(resolution_source or ""),
        "geocode": params["geocode"],
        "request_timeout": list(request_timeout),
        "request_retries": int(request_retries),
    }
    if include_capture_evidence:
        result.update(
            {
                "requested_at": requested_at,
                "response_started_at": response_started_at,
                "response_completed_at": response_completed_at,
                "capture_time_provenance": "observed_transport",
                "response_headers_observed": True,
                "raw_provider_response_utf8": raw_provider_response_utf8,
            }
        )
    return result


def _latest_cached_soft_forecast_peak(
    *,
    slug: Optional[str],
    event_date: Optional[str],
    channel: str,
    market_unit: Optional[str],
    limit: int = 12,
) -> Dict[str, Any]:
    if not _env_bool("PM_SOFT_FORECAST_CACHE_FALLBACK_ENABLED", True):
        return {}
    slug_key = str(slug or "").strip()
    event_key = _normalize_date_key(str(event_date or ""))
    if not slug_key or not event_key or channel not in {"wu", "taf", "weather_com"}:
        return {}
    max_age = _env_float("PM_SOFT_FORECAST_CACHE_FALLBACK_MAX_AGE_MIN")
    if max_age is None or not math.isfinite(float(max_age)) or float(max_age) <= 0:
        max_age = 240.0
    if not DB_PATH.exists():
        return {}
    try:
        conn = sqlite3.connect(f"file:{DB_PATH}?mode=ro", uri=True)
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            """
            SELECT id, created_at, payload_json
            FROM event_runs
            WHERE slug = ?
              AND event_date = ?
              AND payload_json IS NOT NULL
              AND payload_json != ''
            ORDER BY created_at DESC, id DESC
            LIMIT ?
            """,
            (slug_key, event_key, max(1, int(limit))),
        ).fetchall()
        conn.close()
    except Exception:
        return {}
    now = datetime.now(timezone.utc)
    if channel == "wu":
        key = "wu_forecast_peak"
        row_key = "wu_forecast_peak_c"
    elif channel == "weather_com":
        key = "weather_com_forecast_peak"
        row_key = "weather_com_forecast_peak_c"
    else:
        key = "taf_forecast_peak"
        row_key = "taf_forecast_peak_c"
    for row in rows:
        created_at = str(row["created_at"] or "")
        created_dt = _parse_iso_dt(created_at)
        age_minutes: Optional[float] = None
        if created_dt is not None:
            if created_dt.tzinfo is None:
                created_dt = created_dt.replace(tzinfo=timezone.utc)
            age_minutes = (now - created_dt.astimezone(timezone.utc)).total_seconds() / 60.0
            if age_minutes < 0 or age_minutes > float(max_age):
                continue
        try:
            payload = json.loads(row["payload_json"] or "{}")
        except Exception:
            continue
        peak_obj = payload.get(key) if isinstance(payload.get(key), Mapping) else {}
        peak_c = to_float(peak_obj.get("value_c") if isinstance(peak_obj, Mapping) else None)
        if peak_c is None:
            for item in payload.get("rows") or []:
                if not isinstance(item, Mapping):
                    continue
                peak_c = to_float(item.get(row_key))
                if peak_c is not None:
                    break
        if peak_c is None or not math.isfinite(float(peak_c)):
            continue
        unit = normalize_unit(market_unit) or "C"
        value = _convert_temp_value(float(peak_c), "C", unit)
        source = str((peak_obj or {}).get("source") or "")
        if not source:
            source = "wunderground_forecast_daily_peak" if channel == "wu" else "zuuu_taf_awc_tx_peak"
        cached_source = f"{source}_cached_previous_event_run"
        out: Dict[str, Any] = {
            "ok": True,
            "value": float(value),
            "value_c": float(peak_c),
            "unit": unit,
            "source": cached_source,
            "source_fit_tier": str((peak_obj or {}).get("source_fit_tier") or "cached_soft_forecast"),
            "source_trust_tier": str((peak_obj or {}).get("source_trust_tier") or "soft_forecast"),
            "source_usable_for_settlement": False,
            "cache_fallback": True,
            "cache_fallback_channel": channel,
            "cache_fallback_event_run_id": int(row["id"]),
            "cache_fallback_created_at": created_at,
            "cache_fallback_age_minutes": age_minutes,
        }
        if channel == "wu":
            out.update(
                {
                    "wu_settlement_page": "Wunderground settlement display page",
                    "twc_provider": "Weather.com/TWC",
                    "station_id": "ZUUU" if "zuuu" in str(payload).lower() else "",
                    "peak_at": (peak_obj or {}).get("peak_at"),
                    "peak_time_source": (peak_obj or {}).get("peak_time_source"),
                }
            )
        elif channel == "weather_com":
            out.update(
                {
                    "twc_provider": "Weather.com/TWC",
                    "soft": True,
                    "not_observed_nowcast": True,
                    "posterior_included": False,
                    "posterior_status": "display_only_not_in_main_posterior",
                    "posterior_label": "独立抓取，仅数值对比",
                    "not_in_posterior_reason": "cached_display_only_pending_created_at_walk_forward_and_provider_dedupe",
                    "source_url": str((peak_obj or {}).get("source_url") or ""),
                }
            )
        else:
            out.update(
                {
                    "soft": True,
                    "strong_soft": True,
                    "not_observed_nowcast": True,
                    "usable_for_bayes_requested": bool(_env_bool("PM_TAF_FORECAST_PEAK_BAYES_USABLE", False)),
                    "created_at_walk_forward_calibrated": bool(
                        _env_bool("PM_BAYES_TAF_PEAK_WALK_FORWARD_CALIBRATED", False)
                        or _env_bool("PM_TAF_FORECAST_PEAK_WALK_FORWARD_CALIBRATED", False)
                    ),
                    "usable_for_bayes": bool(
                        _env_bool("PM_TAF_FORECAST_PEAK_BAYES_USABLE", False)
                        and (
                            _env_bool("PM_BAYES_TAF_PEAK_WALK_FORWARD_CALIBRATED", False)
                            or _env_bool("PM_TAF_FORECAST_PEAK_WALK_FORWARD_CALIBRATED", False)
                        )
                    ),
                    "bayes_channel_status": (
                        "enabled_by_calibrated_explicit_env_cached_previous_event_run"
                        if (
                            _env_bool("PM_TAF_FORECAST_PEAK_BAYES_USABLE", False)
                            and (
                                _env_bool("PM_BAYES_TAF_PEAK_WALK_FORWARD_CALIBRATED", False)
                                or _env_bool("PM_TAF_FORECAST_PEAK_WALK_FORWARD_CALIBRATED", False)
                            )
                        )
                        else "cached_previous_event_run_blocked_pending_created_at_walk_forward"
                        if _env_bool("PM_TAF_FORECAST_PEAK_BAYES_USABLE", False)
                        else "cached_previous_event_run_pending_created_at_walk_forward"
                    ),
                    "confidence": to_float((peak_obj or {}).get("confidence")) or 1.0,
                    "raw_text": str((peak_obj or {}).get("raw_text") or ""),
                    "peak_at": (peak_obj or {}).get("peak_at"),
                    "issued_at": (peak_obj or {}).get("issued_at"),
                    "valid_start_at": (peak_obj or {}).get("valid_start_at"),
                    "valid_end_at": (peak_obj or {}).get("valid_end_at"),
                }
            )
        return out
    return {}


def _extract_pws_id(text: str) -> Optional[str]:
    if not text:
        return None
    m = re.search(r"/dashboard/pws/([A-Za-z0-9]+)", text)
    if m:
        return m.group(1)
    m = re.search(r"/weather/[^/]+/[^/]+/([A-Za-z0-9]+)", text)
    if m:
        return m.group(1)
    m = re.search(r"/weather/[^/]+/([A-Za-z0-9]+)", text)
    if m:
        return m.group(1)
    return None


def _fetch_pws_api_key_and_station(url: str) -> Tuple[Optional[str], Optional[str]]:
    try:
        html = requests_get(url, timeout=20, bypass_proxy=False, retries=3).text
    except Exception:
        return None, None
    api_key = None
    station_id = None
    m = re.search(r"apiKey=([A-Za-z0-9]+)", html)
    if m:
        api_key = m.group(1)
    m = re.search(r"stationId=([A-Za-z0-9]+)", html)
    if m:
        station_id = m.group(1)
    return api_key, station_id


def fetch_wunderground_pws_daily_temp(
    resolution_source: Optional[str],
    station_id: Optional[str],
    date: str,
    kind: str,
    market_unit: Optional[str],
) -> Optional[float]:
    source = resolution_source or ""
    pws_id = _extract_pws_id(source)
    pws_url = source if pws_id else ""
    if not pws_id and station_id:
        src = PWS_STATION_URLS.get(station_id.upper())
        if src:
            pws_id = _extract_pws_id(src)
            pws_url = src
    if not pws_id:
        return None
    if not pws_url:
        pws_url = f"https://www.wunderground.com/dashboard/pws/{pws_id}"
    api_key, station = _fetch_pws_api_key_and_station(pws_url)
    if not api_key:
        return None
    station = station or pws_id
    date_key = date.replace("-", "")
    api_url = (
        "https://api.weather.com/v2/pws/history/all"
        f"?stationId={station}"
        "&format=json&units=e"
        f"&date={date_key}"
        "&numericPrecision=decimal"
        f"&apiKey={api_key}"
    )
    try:
        payload = requests_get(api_url, timeout=20, bypass_proxy=False, retries=3).json()
    except Exception:
        return None
    observations = payload.get("observations")
    if not isinstance(observations, list):
        return None
    values: List[float] = []
    for obs in observations:
        if not isinstance(obs, dict):
            continue
        imperial = obs.get("imperial")
        if isinstance(imperial, dict):
            key = "tempHigh" if kind == "max" else "tempLow"
            val = imperial.get(key)
            if isinstance(val, (int, float)):
                values.append(float(val))
        metric = obs.get("metric")
        if isinstance(metric, dict):
            key = "tempHigh" if kind == "max" else "tempLow"
            val = metric.get(key)
            if isinstance(val, (int, float)):
                values.append(float(val))
    if not values:
        return None
    value_f = max(values) if kind == "max" else min(values)
    if market_unit and market_unit.upper() == "C":
        return (value_f - 32.0) * 5.0 / 9.0
    return value_f


def fetch_twc_pws_rapid_history_aux_features(
    resolution_source: Optional[str],
    station_id: Optional[str],
    event_date: str,
    *,
    tz: Optional[str],
) -> Dict[str, Any]:
    if not _env_bool("PM_TWC_PWS_RAPID_HISTORY_ENABLED", True):
        return {}
    source = str(os.environ.get("PM_TWC_PWS_RAPID_HISTORY_URL") or resolution_source or "").strip()
    pws_id = str(os.environ.get("PM_TWC_PWS_RAPID_HISTORY_STATION_ID") or "").strip()
    if not pws_id:
        pws_id = _extract_pws_id(source) or ""
    pws_url = source if _extract_pws_id(source) else ""
    if not pws_id and station_id:
        fallback_url = PWS_STATION_URLS.get(str(station_id or "").strip().upper())
        if fallback_url:
            pws_id = _extract_pws_id(fallback_url) or ""
            pws_url = fallback_url
    fetched_at = datetime.now(timezone.utc)
    out: Dict[str, Any] = {
        "twc_pws_rapid_history_aux_provider": "Weather.com/TWC PWS",
        "twc_pws_rapid_history_aux_role": "auxiliary_intraday_warning_not_final_settlement",
        "twc_pws_rapid_history_aux_usable_for_final_settlement": False,
        "twc_pws_rapid_history_aux_fetched_at": fetched_at.isoformat(),
    }
    if not pws_id:
        out["twc_pws_rapid_history_aux_available"] = False
        out["twc_pws_rapid_history_aux_error"] = "pws_station_id_missing"
        return out
    api_key = str(
        os.environ.get("PM_TWC_PWS_API_KEY")
        or os.environ.get("PM_WEATHER_COM_API_KEY")
        or os.environ.get("PM_WU_HISTORY_API_KEY")
        or ""
    ).strip()
    station = pws_id
    if not api_key and pws_url:
        api_key, station_from_page = _fetch_pws_api_key_and_station(pws_url)
        station = station_from_page or station
    if not api_key:
        out["twc_pws_rapid_history_aux_station_id"] = station
        out["twc_pws_rapid_history_aux_available"] = False
        out["twc_pws_rapid_history_aux_error"] = "api_key_missing"
        return out
    params = {
        "stationId": station,
        "format": "json",
        "units": "m",
        "numericPrecision": "decimal",
        "apiKey": api_key,
    }
    try:
        resp = requests_get(
            WEATHER_COM_PWS_RAPID_HISTORY_URL,
            params=params,
            timeout=_wu_twc_obs_request_timeout(),
            bypass_proxy=False,
            retries=_wu_twc_obs_request_retries(),
        )
        resp.raise_for_status()
        payload = resp.json()
    except Exception as exc:
        out["twc_pws_rapid_history_aux_station_id"] = station
        out["twc_pws_rapid_history_aux_available"] = False
        out["twc_pws_rapid_history_aux_error"] = f"request_error:{exc.__class__.__name__}"
        return out
    observations = payload.get("observations") if isinstance(payload, Mapping) else None
    if not isinstance(observations, list):
        out["twc_pws_rapid_history_aux_station_id"] = station
        out["twc_pws_rapid_history_aux_available"] = False
        out["twc_pws_rapid_history_aux_error"] = "observations_missing"
        return out
    zone = timezone.utc
    if tz and ZoneInfo is not None:
        try:
            zone = ZoneInfo(str(tz))
        except Exception:
            zone = timezone.utc
    event_key = _normalize_date_key(str(event_date or ""))
    temp_pairs: List[Tuple[datetime, float]] = []
    for obs in observations:
        if not isinstance(obs, Mapping):
            continue
        metric = obs.get("metric") if isinstance(obs.get("metric"), Mapping) else {}
        temp_c = to_float(metric.get("temp") if isinstance(metric, Mapping) else None)
        if temp_c is None:
            temp_c = to_float(obs.get("temp"))
        obs_time = (
            _parse_metar_time(obs.get("obsTimeUtc"))
            or _parse_metar_time(obs.get("validTimeUtc"))
            or _datetime_from_epoch(obs.get("epoch"))
        )
        if temp_c is None or obs_time is None or not math.isfinite(float(temp_c)):
            continue
        obs_utc = obs_time.astimezone(timezone.utc) if obs_time.tzinfo else obs_time.replace(tzinfo=timezone.utc)
        if event_key and obs_utc.astimezone(zone).date().isoformat() != event_key:
            continue
        temp_pairs.append((obs_utc, float(temp_c)))
    temp_pairs.sort(key=lambda item: item[0])
    out["twc_pws_rapid_history_aux_station_id"] = station
    out["twc_pws_rapid_history_aux_source_url"] = getattr(resp, "url", "") or WEATHER_COM_PWS_RAPID_HISTORY_URL
    out["twc_pws_rapid_history_aux_available"] = bool(temp_pairs)
    out["twc_pws_rapid_history_aux_sample_count"] = len(temp_pairs)
    if not temp_pairs:
        out["twc_pws_rapid_history_aux_error"] = "event_date_temperature_missing"
        return out
    latest_time, latest_temp = temp_pairs[-1]
    max_time, max_temp = max(temp_pairs, key=lambda item: (item[1], item[0]))
    out["twc_pws_rapid_history_aux_latest_at"] = _iso_from_datetime(latest_time)
    out["twc_pws_rapid_history_aux_latest_temp_c"] = float(latest_temp)
    out["twc_pws_rapid_history_aux_today_max_at"] = _iso_from_datetime(max_time)
    out["twc_pws_rapid_history_aux_today_max_c"] = float(max_temp)
    if len(temp_pairs) >= 2:
        local_features: Dict[str, Any] = {}
        _apply_temperature_trajectory_rates(
            local_features,
            temp_pairs,
            source="twc_pws_rapid_history_aux",
        )
        for key, value in local_features.items():
            if key.startswith("temperature_"):
                out[f"twc_pws_rapid_history_aux_{key}"] = value
    return out


def _extract_observation_temp(obs: Dict, default_unit: str = "F") -> Optional[Tuple[float, str]]:
    metric = obs.get("metric")
    if isinstance(metric, dict):
        val = metric.get("temp")
        if isinstance(val, (int, float)):
            return float(val), "C"
    imperial = obs.get("imperial")
    if isinstance(imperial, dict):
        val = imperial.get("temp")
        if isinstance(val, (int, float)):
            return float(val), "F"
    for key in ("tempi", "temp"):
        val = obs.get(key)
        if isinstance(val, (int, float)):
            return float(val), str(default_unit or "F").upper()
    return None


def _convert_temp_value(value: float, unit: str, market_unit: Optional[str]) -> float:
    if market_unit and market_unit.upper() == "C":
        if unit.upper() == "F":
            return (value - 32.0) * 5.0 / 9.0
        return value
    if unit.upper() == "C":
        return value * 9.0 / 5.0 + 32.0
    return value


def _temperature_native_precision(value: Any, native_precision: Optional[str] = None) -> str:
    text = str(native_precision or "").strip().lower()
    if text:
        return text
    val = to_float(value)
    if val is None:
        return "unknown"
    return "integer_display" if abs(float(val) - round(float(val))) <= 1e-9 else "numeric"


def temperature_settlement_precision_profile(
    *,
    native_value: Any,
    native_unit: Any,
    settlement_unit: Any = "C",
    settlement_policy: Any = "whole_degrees",
    native_precision: Optional[str] = None,
    source: str = "",
    display_value: Any = None,
    display_unit: Any = None,
) -> Dict[str, Any]:
    """Describe whether a native temperature can deterministically pick a settlement bucket."""

    val = to_float(native_value)
    unit = normalize_unit(str(native_unit or "")) or str(native_unit or "").strip().upper().replace("°", "")
    settlement_unit_norm = normalize_unit(str(settlement_unit or "")) or str(settlement_unit or "C").strip().upper().replace("°", "")
    policy = str(settlement_policy or "whole_degrees").strip().lower()
    precision = _temperature_native_precision(val, native_precision)
    out: Dict[str, Any] = {
        "source": str(source or ""),
        "native_value": float(val) if val is not None else None,
        "native_unit": unit,
        "native_precision": precision,
        "display_value": display_value,
        "display_unit": normalize_unit(str(display_unit or "")) or str(display_unit or "").strip().upper().replace("°", ""),
        "settlement_unit": settlement_unit_norm,
        "settlement_policy": policy,
        "boundary_ambiguous": False,
        "boundary_status": "ok",
        "ambiguous_reason": "",
    }
    if val is None or unit not in {"C", "F"} or settlement_unit_norm not in {"C", "F"}:
        out["boundary_status"] = "missing_or_unsupported_unit"
        return out

    converted_c = _convert_temp_value(float(val), unit, "C")
    out["converted_value_c"] = float(converted_c)
    if unit == settlement_unit_norm:
        out["settlement_value"] = float(val)
    else:
        out["settlement_value"] = float(_convert_temp_value(float(val), unit, settlement_unit_norm))

    if unit == "F" and settlement_unit_norm == "C" and precision == "integer_display":
        lo_c = _convert_temp_value(float(val) - 0.5, "F", "C")
        hi_c = _convert_temp_value(float(val) + 0.5, "F", "C")
        out["native_rounding_interval"] = [float(val) - 0.5, float(val) + 0.5]
        out["settlement_interval_c"] = [float(lo_c), float(hi_c)]
        if "whole" in policy or "floor" in policy:
            lo_bucket = math.floor(float(lo_c))
            hi_bucket = math.floor(float(hi_c) - 1e-12)
            if abs(float(hi_c) - round(float(hi_c))) > 1e-9:
                hi_bucket = math.floor(float(hi_c))
            out["settlement_interval_floor_buckets"] = [int(lo_bucket), int(hi_bucket)]
            if lo_bucket != hi_bucket:
                out["boundary_ambiguous"] = True
                out["boundary_status"] = "boundary_ambiguous"
                out["ambiguous_reason"] = "native_f_integer_display_crosses_c_floor_bucket"
        elif "round" in policy:
            lo_bucket = int(round(float(lo_c)))
            hi_bucket = int(round(float(hi_c)))
            out["settlement_interval_rounded_buckets"] = [lo_bucket, hi_bucket]
            if lo_bucket != hi_bucket:
                out["boundary_ambiguous"] = True
                out["boundary_status"] = "boundary_ambiguous"
                out["ambiguous_reason"] = "native_f_integer_display_crosses_c_rounded_bucket"
    return out


def temperature_settlement_profile_from_wu_twc_features(
    features: Mapping[str, Any],
    *,
    rounding_rule: Optional[str] = "whole_degrees",
    settlement_unit: Optional[str] = "C",
) -> Dict[str, Any]:
    if not isinstance(features, Mapping):
        return {}
    source = str(features.get("wu_twc_observed_intraday_today_max_source") or "").strip()
    candidates: List[Tuple[str, Any, Any]] = []
    if source == "wu_twc_observed_intraday_history":
        candidates.append(
            (
                source,
                features.get("wu_twc_observed_intraday_history_raw_value"),
                features.get("wu_twc_observed_intraday_history_raw_unit"),
            )
        )
    elif source == "wu_twc_observed_intraday_current_metric_max_since7am":
        candidates.append(
            (
                source,
                features.get("wu_twc_observed_intraday_current_metric_max_since7am_raw_value"),
                features.get("wu_twc_observed_intraday_current_metric_raw_unit"),
            )
        )
    elif source == "wu_twc_observed_intraday_current_imperial_max_since7am":
        candidates.append(
            (
                source,
                features.get("wu_twc_observed_intraday_current_imperial_max_since7am_raw_value"),
                features.get("wu_twc_observed_intraday_current_imperial_raw_unit"),
            )
        )
    elif source == "wu_twc_observed_intraday_max_since7am":
        candidates.append(
            (
                source,
                features.get("wu_twc_observed_intraday_max_since7am_raw_value"),
                features.get("wu_twc_observed_intraday_max_since7am_raw_unit"),
            )
        )
    elif source == "wu_twc_observed_intraday_current":
        candidates.append(
            (
                source,
                features.get("wu_twc_observed_intraday_current_raw_value"),
                features.get("wu_twc_observed_intraday_current_raw_unit"),
            )
        )

    candidates.append(
        (
            "wu_twc_observed_intraday_history_metric_fallback",
            features.get("wu_twc_observed_intraday_history_raw_value"),
            features.get("wu_twc_observed_intraday_history_raw_unit"),
        )
    )
    candidates.append(
        (
            "wu_twc_observed_intraday_history_imperial_fallback",
            features.get("wu_twc_observed_intraday_history_raw_imperial_value"),
            features.get("wu_twc_observed_intraday_history_raw_imperial_unit"),
        )
    )
    for source_name, native_value, native_unit in candidates:
        if to_float(native_value) is None or not str(native_unit or "").strip():
            continue
        return temperature_settlement_precision_profile(
            native_value=native_value,
            native_unit=native_unit,
            settlement_unit=settlement_unit or "C",
            settlement_policy=rounding_rule or "whole_degrees",
            source=source_name,
            display_value=features.get("wu_twc_observed_intraday_today_max_c"),
            display_unit=settlement_unit or "C",
        )
    return {
        "source": source,
        "boundary_status": "native_temperature_missing",
        "boundary_ambiguous": False,
        "ambiguous_reason": "",
        "settlement_unit": normalize_unit(str(settlement_unit or "C")) or "C",
        "settlement_policy": str(rounding_rule or "whole_degrees"),
    }


def _observation_timestamp(obs: Dict) -> Optional[float]:
    for key in ("valid_time_gmt", "validTimeGMT", "utc_time", "timestamp"):
        val = obs.get(key)
        if isinstance(val, (int, float)):
            return float(val)
    local = obs.get("valid_time_local")
    if isinstance(local, str):
        try:
            return datetime.fromisoformat(local).timestamp()
        except Exception:
            pass
    return None


def _find_extreme_observation(
    observations: List[Dict],
    kind: str,
    market_unit: Optional[str],
    default_unit: str = "F",
) -> Tuple[Optional[float], Optional[Dict]]:
    best_temp: Optional[float] = None
    best_obs: Optional[Dict] = None
    for obs in observations:
        extracted = _extract_observation_temp(obs, default_unit=default_unit)
        if not extracted:
            continue
        value, unit = extracted
        converted = _convert_temp_value(value, unit, market_unit)
        if best_temp is None:
            best_temp = converted
            best_obs = obs
            continue
        if kind == "max" and converted > best_temp:
            best_temp = converted
            best_obs = obs
        if kind == "min" and converted < best_temp:
            best_temp = converted
            best_obs = obs
    return best_temp, best_obs


def _max_min_from_observations(
    observations: List[Dict],
    kind: str,
    market_unit: Optional[str],
    default_unit: str = "F",
) -> Optional[float]:
    val, _ = _find_extreme_observation(observations, kind, market_unit, default_unit=default_unit)
    return val


def _default_playwright_executable_path() -> Optional[str]:
    raw = str(os.environ.get("PM_PLAYWRIGHT_CHROMIUM_EXECUTABLE") or "").strip()
    if raw:
        return raw
    chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
    if os.path.exists(chrome):
        return chrome
    return None


def _fetch_wunderground_history_payload_with_meta(
    resolution_source: Optional[str],
    date: str,
) -> Tuple[Optional[Dict], Dict[str, Any]]:
    meta: Dict[str, Any] = {"ok": False, "method": "playwright_wunderground_history"}
    if not resolution_source:
        meta["error"] = "resolution_source_missing"
        return None, meta
    source_profile = weather_resolution_source_profile(resolution_source)
    if source_profile.get("source_kind") != "wunderground_history":
        meta["error"] = "resolution_source_not_wunderground_history"
        return None, meta
    if os.environ.get("PM_DISABLE_PLAYWRIGHT", "").strip().lower() in {"1", "true", "yes", "on"}:
        meta["error"] = "playwright_disabled"
        return None, meta
    try:
        from playwright.sync_api import sync_playwright
    except Exception as exc:
        meta["error"] = f"playwright_import_error:{exc.__class__.__name__}"
        return None, meta
    base_url = resolution_source.rstrip("/")
    if re.search(r"/history/daily/cn/chengdu/ZUUU$", base_url, flags=re.I):
        base_url = re.sub(r"/ZUUU$", "", base_url, flags=re.I)
    url = base_url + f"/date/{date}"
    meta["source_url"] = url
    target_prefix = "https://api.weather.com/v1/location/"
    target_path = "/observations/historical.json"
    payload = None
    matched_url = ""

    def on_response(resp):
        nonlocal payload, matched_url
        u = resp.url
        if not u.startswith(target_prefix) or target_path not in u:
            return
        try:
            payload = resp.json()
            matched_url = u
        except Exception:
            return

    browser = None
    try:
        with sync_playwright() as p:
            executable_path = _default_playwright_executable_path()
            launch_kwargs: Dict[str, Any] = {"headless": True}
            if executable_path:
                launch_kwargs["executable_path"] = executable_path
                meta["executable_path"] = executable_path
            browser = p.chromium.launch(**launch_kwargs)
            context = browser.new_context(ignore_https_errors=True)
            page = context.new_page()
            page.on("response", on_response)
            goto_timeout = int(os.environ.get("PM_WU_PLAYWRIGHT_GOTO_TIMEOUT_MS") or "45000")
            wait_ms = int(os.environ.get("PM_WU_PLAYWRIGHT_WAIT_MS") or "8000")
            meta["goto_timeout_ms"] = goto_timeout
            meta["wait_ms"] = wait_ms
            page.goto(url, wait_until="domcontentloaded", timeout=max(1000, goto_timeout))
            page.wait_for_timeout(max(0, wait_ms))
            browser.close()
            browser = None
    except Exception as exc:
        try:
            if browser is not None:
                browser.close()
        except Exception:
            pass
        meta["error"] = f"playwright_error:{exc.__class__.__name__}"
        return None, meta
    if not isinstance(payload, dict):
        meta["error"] = "historical_payload_missing"
        return None, meta
    meta["ok"] = True
    if matched_url:
        meta["matched_url"] = matched_url
    return payload, meta


def _fetch_wunderground_history_payload(
    resolution_source: Optional[str],
    date: str,
) -> Optional[Dict]:
    payload, _meta = _fetch_wunderground_history_payload_with_meta(resolution_source, date)
    return payload


def _wunderground_history_location_id(
    resolution_source: Optional[str],
    source_profile: Optional[Mapping[str, Any]] = None,
) -> Optional[str]:
    station = ""
    if isinstance(source_profile, Mapping):
        station = str(source_profile.get("station_id") or "").strip().upper()
    if not station and resolution_source:
        match = re.search(r"/history/daily/[^/]+/[^/]+/([A-Za-z0-9]+)(?:/|$)", resolution_source)
        if match:
            station = match.group(1).strip().upper()
    if not station:
        return None
    country = "CN"
    if resolution_source:
        match = re.search(r"/history/daily/([a-z]{2})/", resolution_source, flags=re.I)
        if match:
            country = match.group(1).strip().upper()
    return f"{station}:9:{country}"


def _fetch_wunderground_history_api_payload(
    resolution_source: Optional[str],
    date: str,
    *,
    units: str = "e",
) -> Tuple[Optional[Dict], Dict[str, Any]]:
    units_norm = "m" if str(units or "").strip().lower() == "m" else "e"
    source_profile = weather_resolution_source_profile(resolution_source)
    meta: Dict[str, Any] = {
        "ok": False,
        "method": "weather_com_history_api",
        "units": units_norm,
        "default_unit": "C" if units_norm == "m" else "F",
    }
    if source_profile.get("source_kind") != "wunderground_history":
        meta["error"] = "resolution_source_not_wunderground_history"
        return None, meta
    location_id = _wunderground_history_location_id(resolution_source, source_profile)
    if not location_id:
        meta["error"] = "location_id_missing"
        return None, meta
    api_key = str(
        os.environ.get("PM_WU_HISTORY_API_KEY")
        or os.environ.get("PM_WEATHER_COM_API_KEY")
        or "6532d6454b8aa370768e63d6ba5a832e"
    ).strip()
    if not api_key:
        meta["error"] = "api_key_missing"
        return None, meta
    date_key = str(date or "").replace("-", "")[:8]
    if len(date_key) != 8:
        meta["error"] = "date_invalid"
        return None, meta
    url = (
        "https://api.weather.com/v1/location/"
        f"{quote(location_id, safe='')}/observations/historical.json"
        f"?apiKey={api_key}&units={units_norm}&startDate={date_key}&endDate={date_key}"
    )
    meta["source_url"] = url
    meta["location_id"] = location_id
    try:
        resp = requests_get(
            url,
            timeout=int(os.environ.get("PM_WU_HISTORY_API_TIMEOUT_SEC") or "20"),
            bypass_proxy=False,
            retries=2,
        )
    except Exception as exc:
        meta["error"] = f"request_error:{exc.__class__.__name__}"
        return None, meta
    meta["status_code"] = int(getattr(resp, "status_code", 0) or 0)
    if resp.status_code != 200:
        meta["error"] = f"http_{resp.status_code}"
        return None, meta
    try:
        payload = resp.json()
    except Exception as exc:
        meta["error"] = f"json_error:{exc.__class__.__name__}"
        return None, meta
    if not isinstance(payload, dict):
        meta["error"] = "payload_not_mapping"
        return None, meta
    meta["ok"] = True
    return payload, meta


def fetch_wunderground_history_temp_with_playwright(
    resolution_source: Optional[str],
    date: str,
    kind: str,
    market_unit: Optional[str],
) -> Optional[float]:
    payload = _fetch_wunderground_history_payload(resolution_source, date)
    if not payload:
        return None
    observations = payload.get("observations")
    if not isinstance(observations, list):
        return None
    return _max_min_from_observations(observations, kind, market_unit)


def fetch_wunderground_history_metrics(
    resolution_source: Optional[str],
    date: str,
    kind: str,
    market_unit: Optional[str],
) -> Dict[str, Optional[float]]:
    api_units = "m" if str(market_unit or "").strip().upper() == "C" else "e"
    payload, meta = _fetch_wunderground_history_api_payload(resolution_source, date, units=api_units)
    if not payload:
        payload, meta = _fetch_wunderground_history_payload_with_meta(resolution_source, date)
    if not payload:
        return dict(meta)
    observations = payload.get("observations")
    if not isinstance(observations, list):
        out = dict(meta)
        out["ok"] = False
        out["error"] = "observations_missing"
        return out
    val, best_obs = _find_extreme_observation(
        observations,
        kind,
        market_unit,
        default_unit=str(meta.get("default_unit") or "F"),
    )
    result: Dict[str, Any] = dict(meta)
    result["observation_count"] = len(observations)
    if val is not None:
        result["value"] = val
    if best_obs:
        ts = _observation_timestamp(best_obs)
        if ts is not None:
            result["time_gmt"] = ts
    return result


def fetch_wunderground_max_temp(
    resolution_source: Optional[str],
    date: str,
    market_unit: Optional[str] = None,
) -> Optional[float]:
    val = fetch_wunderground_history_temp_with_playwright(
        resolution_source, date, "max", market_unit
    )
    if val is not None:
        return val
    return fetch_wunderground_daily_temp(resolution_source, date, "max", market_unit)


def fetch_wunderground_min_temp(
    resolution_source: Optional[str],
    date: str,
    market_unit: Optional[str] = None,
) -> Optional[float]:
    val = fetch_wunderground_history_temp_with_playwright(
        resolution_source, date, "min", market_unit
    )
    if val is not None:
        return val
    return fetch_wunderground_daily_temp(resolution_source, date, "min", market_unit)


def fetch_settlement_actual(
    resolution_source: Optional[str],
    event_date: str,
    market_var: str,
    market_unit: Optional[str],
    station_id: Optional[str] = None,
    lat: Optional[float] = None,
    lon: Optional[float] = None,
    tz: Optional[str] = None,
) -> Optional[float]:
    if not event_date:
        return None
    try:
        if resolution_source and "wunderground.com" in resolution_source:
            allow_pws_settlement_aux = _env_bool("PM_WU_ALLOW_PWS_SETTLEMENT_AUX", False)
            if market_var == "temperature_2m_max":
                metrics = fetch_wunderground_history_metrics(
                    resolution_source,
                    event_date,
                    "max",
                    market_unit,
                )
                val = to_float(metrics.get("value") if isinstance(metrics, Mapping) else None)
                if val is None and _env_bool("PM_WU_ALLOW_DAILY_TEMP_SETTLEMENT_FALLBACK", False):
                    val = fetch_wunderground_max_temp(resolution_source, event_date, market_unit)
                if val is not None:
                    return val
                if allow_pws_settlement_aux:
                    val = fetch_wunderground_pws_daily_temp(
                        resolution_source, station_id, event_date, "max", market_unit
                    )
                    if val is not None:
                        return val
            if market_var == "temperature_2m_min":
                metrics = fetch_wunderground_history_metrics(
                    resolution_source,
                    event_date,
                    "min",
                    market_unit,
                )
                val = to_float(metrics.get("value") if isinstance(metrics, Mapping) else None)
                if val is None and _env_bool("PM_WU_ALLOW_DAILY_TEMP_SETTLEMENT_FALLBACK", False):
                    val = fetch_wunderground_min_temp(resolution_source, event_date, market_unit)
                if val is not None:
                    return val
                if allow_pws_settlement_aux:
                    val = fetch_wunderground_pws_daily_temp(
                        resolution_source, station_id, event_date, "min", market_unit
                    )
                    if val is not None:
                        return val
            if market_var in {"temperature_2m_max", "temperature_2m_min"}:
                return None
    except Exception:
        if resolution_source and "wunderground.com" in resolution_source and market_var in {
            "temperature_2m_max",
            "temperature_2m_min",
        }:
            return None

    coords = None
    if station_id:
        coords = fetch_meteostat_station_coords(station_id)
        if coords is None:
            coords = fetch_ourairports_station_coords(station_id)
        if coords is None:
            coords = fetch_override_station_coords(station_id)
    if coords:
        lat, lon = coords
    if lat is None or lon is None:
        return None

    val = fetch_meteostat_daily_var(lat, lon, event_date, market_var, market_unit)
    if val is not None:
        return val

    unit_params = infer_unit_params(market_unit, market_var)
    zone = tz or "UTC"
    val = fetch_archive_daily_var(lat, lon, event_date, zone, market_var, unit_params)
    if val is not None:
        return val
    return None


def _value_is_present(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    return True


def _merge_latest_event_run_metadata(
    rows: Sequence[sqlite3.Row],
    *,
    slug: str,
    event_date: str,
    title: str,
    event_hint: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    merged: Dict[str, Any] = {}
    for row in rows:
        for key in row.keys():
            if key == "id":
                continue
            if _value_is_present(merged.get(key)):
                continue
            value = row[key]
            if _value_is_present(value):
                merged[key] = value
    hint = event_hint if isinstance(event_hint, Mapping) else {}
    merged.setdefault("slug", slug)
    merged.setdefault("event_date", event_date)
    if not _value_is_present(merged.get("run_date")):
        merged["run_date"] = event_date
    if not _value_is_present(merged.get("title")):
        merged["title"] = title or hint.get("title") or slug
    if not _value_is_present(merged.get("event_url")):
        merged["event_url"] = f"https://polymarket.com/event/{slug}"
    if not _value_is_present(merged.get("resolution_source")):
        resolution_source = hint.get("resolutionSource") or extract_resolution_source_from_text(hint.get("description"))
        if resolution_source:
            merged["resolution_source"] = resolution_source
    if not _value_is_present(merged.get("event_end_utc")) and hint.get("endDate"):
        merged["event_end_utc"] = hint.get("endDate")
    if not _value_is_present(merged.get("station_id")):
        station_id = parse_station_from_resolution_source(str(merged.get("resolution_source") or ""))
        if station_id:
            merged["station_id"] = station_id
    if not _value_is_present(merged.get("market_var")):
        market_var = infer_market_variable(str(merged.get("title") or title or ""), slug)
        if market_var:
            merged["market_var"] = market_var
    if not _value_is_present(merged.get("market_unit")) and _value_is_present(merged.get("market_var")):
        merged["market_unit"] = infer_market_unit([], str(merged.get("market_var") or ""))
    if not _value_is_present(merged.get("tz")):
        merged["tz"] = "UTC"
    return merged


def refresh_settlement_actual_for_pending_event(
    run_date: str,
    event_date: str,
    slug: str,
    title: str,
    event_hint: Optional[Mapping[str, Any]] = None,
) -> Tuple[bool, str, Optional[float]]:
    if not slug or not event_date:
        return False, "missing_slug_or_event_date", None
    if not _archive_write_allowed_for_chengdu_zuuu(
        slug=slug,
        title=title,
        resolution_source=(
            str((event_hint or {}).get("resolutionSource") or "")
            if isinstance(event_hint, Mapping)
            else None
        ),
        station_id=(
            parse_station_from_resolution_source(
                str((event_hint or {}).get("resolutionSource") or "")
            )
            if isinstance(event_hint, Mapping)
            else None
        ),
    ):
        return False, "write_scope_not_chengdu_zuuu", None
    init_db()
    conn = open_db()
    conn.row_factory = sqlite3.Row
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT *
            FROM event_runs
            WHERE slug = ? AND event_date = ?
            ORDER BY id DESC
            LIMIT 50
            """,
            (slug, _normalize_event_date(event_date)),
        )
        rows = list(cur.fetchall() or [])
        if not rows:
            return False, "event_run_missing", None
        for row in rows:
            existing_actual = to_float(row["settlement_actual"] if "settlement_actual" in row.keys() else None)
            if existing_actual is not None and math.isfinite(float(existing_actual)):
                return True, "already_settled", float(existing_actual)
        meta = _merge_latest_event_run_metadata(
            rows,
            slug=slug,
            event_date=_normalize_event_date(event_date),
            title=title,
            event_hint=event_hint,
        )
        resolution_source = str(meta.get("resolution_source") or "").strip()
        market_var = str(meta.get("market_var") or "").strip()
        if not market_var:
            return False, "market_var_missing", None
        market_unit = str(meta.get("market_unit") or "").strip() or None
        station_id = str(meta.get("station_id") or "").strip() or None
        lat = to_float(meta.get("lat"))
        lon = to_float(meta.get("lon"))
        tz = str(meta.get("tz") or "UTC").strip() or "UTC"
        actual = fetch_settlement_actual(
            resolution_source,
            _normalize_event_date(event_date),
            market_var,
            market_unit,
            station_id=station_id,
            lat=lat,
            lon=lon,
            tz=tz,
        )
        if actual is None or not math.isfinite(float(actual)):
            return False, "settlement_actual_missing", None
        created_at = utc_now_iso()
        base_row = dict(meta)
        base_row["run_date"] = run_date
        base_row["event_date"] = _normalize_event_date(event_date)
        base_row["slug"] = slug
        base_row["title"] = str(base_row.get("title") or title or slug)
        base_row["settlement_actual"] = float(actual)
        base_row["market_closed"] = 1
        payload_json = str(base_row.get("payload_json") or "{}")
        _insert_event_run_with_payload(conn, base_row, payload_json, created_at)
        conn.commit()
        return True, "settlement_actual_refreshed", float(actual)
    except sqlite3.OperationalError as exc:
        try:
            conn.rollback()
        except Exception:
            pass
        if _sqlite_is_locked_error(exc):
            return False, "db_locked", None
        return False, f"db_error:{exc}", None
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _station_forecast_is_recent(
    conn: sqlite3.Connection,
    station_id: str,
    event_date: str,
    max_age_sec: int,
    source: Optional[str] = None,
) -> bool:
    if max_age_sec <= 0:
        return False
    cur = conn.cursor()
    if source:
        cur.execute(
            """
            SELECT created_at
            FROM station_forecasts
            WHERE station_id = ? AND event_date = ? AND source = ?
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (station_id, event_date, source),
        )
    else:
        cur.execute(
            """
            SELECT created_at
            FROM station_forecasts
            WHERE station_id = ? AND event_date = ?
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (station_id, event_date),
        )
    row = cur.fetchone()
    if not row:
        return False
    created_at = _parse_iso_dt(str(row[0] or ""))
    if created_at is None:
        return False
    if created_at.tzinfo is None:
        created_at = created_at.replace(tzinfo=timezone.utc)
    age_sec = (datetime.now(timezone.utc) - created_at).total_seconds()
    return age_sec <= max_age_sec


def fetch_station_forecast_max(
    event_date: str,
    market_var: str,
    market_unit: Optional[str],
    station_id: Optional[str] = None,
    lat: Optional[float] = None,
    lon: Optional[float] = None,
    tz: Optional[str] = None,
) -> Optional[Dict[str, Any]]:
    date_key = _normalize_event_date(event_date)
    if not date_key or not market_var:
        return None
    coords = None
    if station_id:
        coords = fetch_meteostat_station_coords(station_id)
        if coords is None:
            coords = fetch_ourairports_station_coords(station_id)
        if coords is None:
            coords = fetch_override_station_coords(station_id)
    if coords:
        lat, lon = coords
    if lat is None or lon is None:
        return None
    tz = tz or "UTC"
    if is_nws_allowed(lat, lon, tz, station_id=station_id):
        provenance: Dict[str, Any] = {}
        try:
            arr = fetch_nws_daily_var(lat, lon, date_key, market_var, market_unit, provenance=provenance)
        except Exception:
            arr = None
        if arr is not None and arr.size > 0:
            val = float(arr[0])
            updated_at, _source = _resolve_model_official_update("nws_forecast", provenance)
            forecast_time = updated_at or utc_now_iso()
            source_url = provenance.get("forecast_url") or NWS_POINTS_URL.format(lat=lat, lon=lon)
            return {
                "value": val,
                "forecast_time": forecast_time,
                "forecast_date": date_key,
                "source": source_url,
            }
    open_meteo_loc_key = _model_cache_key(lat, lon)
    open_meteo_cooldown = _open_meteo_cooldown_until(
        open_meteo_loc_key, date_key, market_var, market_unit or ""
    )
    if open_meteo_cooldown is not None and open_meteo_cooldown > datetime.now(timezone.utc):
        return None
    unit_params = infer_unit_params(market_unit, market_var)
    provenance = {}
    try:
        val = fetch_open_meteo_forecast_daily_var(
            lat, lon, date_key, tz, market_var, unit_params, provenance=provenance
        )
        _sleep_open_meteo_spacing()
    except Exception as exc:
        if _is_open_meteo_rate_limited(exc):
            _set_open_meteo_cooldown(
                open_meteo_loc_key,
                date_key,
                market_var,
                market_unit or "",
                OPEN_METEO_CITY_COOLDOWN_SEC,
                "open_meteo_429",
            )
        return None
    if val is None or not math.isfinite(float(val)):
        return None
    resp_dt = _parse_http_date(str(provenance.get("response_date") or ""))
    forecast_time = resp_dt.isoformat() if resp_dt else utc_now_iso()
    source_url = provenance.get("response_url") or OPEN_METEO_FORECAST_URL
    return {
        "value": float(val),
        "forecast_time": forecast_time,
        "forecast_date": date_key,
        "source": source_url,
    }


def save_station_forecast(
    conn: sqlite3.Connection,
    run_date: str,
    event_date: str,
    station_id: str,
    resolution_source: Optional[str],
    forecast_value: float,
    market_unit: Optional[str],
    forecast_time: Optional[str],
    forecast_date: Optional[str],
    source: Optional[str],
    created_at: str,
) -> None:
    if not _archive_write_allowed_for_chengdu_zuuu(
        station_id=station_id,
        resolution_source=resolution_source,
    ):
        return
    forecast_c, forecast_f = _forecast_temp_units(forecast_value, market_unit)
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO station_forecasts (
            run_date, event_date, station_id, resolution_source,
            forecast_max_f, forecast_max_c, forecast_time, forecast_date,
            source, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            run_date,
            event_date,
            station_id,
            resolution_source,
            forecast_f,
            forecast_c,
            forecast_time,
            forecast_date,
            source,
            created_at,
        ),
    )


def ensure_column(conn: sqlite3.Connection, table: str, column: str, coltype: str) -> None:
    cur = conn.cursor()
    cur.execute(f"PRAGMA table_info({table})")
    cols = {r[1] for r in cur.fetchall()}
    if column not in cols:
        cur.execute(f"ALTER TABLE {table} ADD COLUMN {column} {coltype}")
        conn.commit()


def open_db(
    *,
    autocommit: bool = False,
    ensure_journal_mode: bool = False,
    connect_timeout_sec: Optional[float] = None,
    busy_timeout_ms: Optional[int] = None,
) -> sqlite3.Connection:
    connect_timeout_val = connect_timeout_sec
    if connect_timeout_val is None:
        connect_timeout_val = _env_float("PM_DB_CONNECT_TIMEOUT_SEC")
    if connect_timeout_val is None or not math.isfinite(connect_timeout_val) or connect_timeout_val < 0:
        connect_timeout_val = float(DB_CONNECT_TIMEOUT_SEC)
    busy_timeout_val = busy_timeout_ms
    if busy_timeout_val is None:
        busy_timeout_val = _env_int("PM_DB_BUSY_TIMEOUT_MS")
    if busy_timeout_val is None or busy_timeout_val < 0:
        busy_timeout_val = int(DB_BUSY_TIMEOUT_MS)
    return _open_db_connection(
        connect_timeout_sec=float(connect_timeout_val),
        busy_timeout_ms=int(busy_timeout_val),
        autocommit=bool(autocommit),
        ensure_journal_mode=bool(ensure_journal_mode),
    )


@contextmanager
def open_db_ro_fast(timeout_sec: float = 0.2, busy_timeout_ms: int = 200) -> Iterable[sqlite3.Connection]:
    """Short-lived read-only DB connection for hot read paths.

    Avoid journal_mode changes here so readers do not queue behind writers.
    """
    try:
        conn = sqlite3.connect(
            f"file:{DB_PATH}?mode=ro",
            uri=True,
            timeout=float(timeout_sec),
        )
    except sqlite3.Error:
        conn = sqlite3.connect(DB_PATH, timeout=float(timeout_sec))
    try:
        try:
            conn.execute("PRAGMA query_only=ON")
            conn.execute(f"PRAGMA busy_timeout={int(busy_timeout_ms)}")
        except sqlite3.Error:
            pass
        yield conn
    finally:
        try:
            conn.close()
        except sqlite3.Error:
            pass


_AUTO_TRADE_WORKER_REQUIRED_SCHEMA: Dict[str, Set[str]] = {
    "auto_trade_jobs": {
        "id",
        "state",
        "priority",
        "payload_json",
        "lease_until",
        "next_retry_at",
        "created_at",
        "updated_at",
        "order_intent_id",
    },
    "auto_trade_decisions": {
        "id",
        "action",
        "decided_state",
        "will_order",
        "reason_codes_json",
        "details_json",
        "decision_id",
        "order_intent_id",
    },
    "auto_orders": {
        "id",
        "order_id",
        "order_status",
        "order_checked_at",
        "decision_id",
        "order_intent_id",
    },
    "edge_trades": {
        "id",
        "state",
        "position_size",
        "avg_price",
        "last_order_id",
        "exit_skip_reason",
        "exit_skip_detail",
        "exit_skip_at",
    },
    "edge_trade_fills": {"id", "order_id", "trade_side", "created_at"},
    "event_market_ticks": {"id", "slug", "event_date", "outcome", "created_at"},
    "market_tokens": {"slug", "event_date", "outcome", "yes_token", "no_token"},
    "target_realization_execution_locks": {
        "slug",
        "event_date",
        "outcome",
        "side",
        "lock_type",
        "state",
        "updated_at",
    },
}


def _mark_existing_auto_trade_worker_schema_ready() -> bool:
    """Use a read-only schema probe to avoid full migrations on every hot worker tick."""

    cache_key = _db_cache_key()
    with _DB_SCHEMA_INIT_LOCK:
        if cache_key in _DB_SCHEMA_READY_KEYS:
            return True
    if not DB_PATH.exists():
        return False
    try:
        with open_db_ro_fast(timeout_sec=0.5, busy_timeout_ms=500) as conn:
            for table, required_columns in _AUTO_TRADE_WORKER_REQUIRED_SCHEMA.items():
                rows = conn.execute(f'PRAGMA table_info("{table}")').fetchall()
                present = {str(row[1] or "") for row in rows}
                if not required_columns.issubset(present):
                    return False
    except sqlite3.Error:
        return False
    with _DB_SCHEMA_INIT_LOCK:
        _DB_SCHEMA_READY_KEYS.add(cache_key)
    return True


def _sqlite_is_locked_error(exc: Any) -> bool:
    text = str(exc or "").strip().lower()
    return (
        "database is locked" in text
        or "database table is locked" in text
        or "database schema is locked" in text
        or "busy" in text
    )


def _sqlite_execute_with_retry(
    target: Any,
    sql: str,
    params: Tuple[Any, ...] = (),
    *,
    attempts: Optional[int] = None,
    sleep_base_sec: Optional[float] = None,
    sleep_cap_sec: Optional[float] = None,
    retry_count: Optional[int] = None,
    retry_sleep_sec: Optional[float] = None,
) -> Any:
    execute_fn = target.execute if hasattr(target, "execute") else target
    if not callable(execute_fn):
        raise TypeError("target must be a sqlite cursor or execute callable")

    max_attempts_raw = attempts if attempts is not None else retry_count
    if max_attempts_raw is None or max_attempts_raw < 1:
        max_attempts_raw = _env_int("PM_DB_LOCK_RETRY_COUNT")
    if max_attempts_raw is None or max_attempts_raw < 1:
        max_attempts_raw = 3
    max_attempts = max(1, min(int(max_attempts_raw), 12))

    base_sleep = sleep_base_sec
    if base_sleep is None or not math.isfinite(base_sleep) or base_sleep < 0:
        base_sleep = retry_sleep_sec
    if base_sleep is None or not math.isfinite(base_sleep) or base_sleep < 0:
        base_sleep = _env_float("PM_DB_LOCK_RETRY_SLEEP_SEC")
    if base_sleep is None or not math.isfinite(base_sleep) or base_sleep < 0:
        base_sleep = 0.35
    base_sleep = max(0.0, min(float(base_sleep), 5.0))

    cap_sleep = sleep_cap_sec
    if cap_sleep is None or not math.isfinite(cap_sleep) or cap_sleep < 0:
        cap_sleep = max(float(base_sleep), 2.0)
    cap_sleep = max(0.0, min(float(cap_sleep), 10.0))

    last_exc: Optional[Exception] = None
    for attempt in range(int(max_attempts)):
        try:
            return execute_fn(sql, params)
        except sqlite3.OperationalError as exc:
            last_exc = exc
            if (not _sqlite_is_locked_error(exc)) or (attempt + 1 >= int(max_attempts)):
                raise
            if base_sleep > 0:
                sleep_for = float(base_sleep) * float(attempt + 1)
                if cap_sleep > 0:
                    sleep_for = min(sleep_for, float(cap_sleep))
                time.sleep(sleep_for)
    if last_exc is not None:
        raise last_exc
    return execute_fn(sql, params)


def _sqlite_execute_with_retry_compat(
    target: Any,
    sql: str,
    params: Tuple[Any, ...] = (),
    *,
    attempts: Optional[int] = None,
    sleep_base_sec: Optional[float] = None,
    sleep_cap_sec: Optional[float] = None,
    retry_count: Optional[int] = None,
    retry_sleep_sec: Optional[float] = None,
) -> Any:
    try:
        return _sqlite_execute_with_retry(
            target,
            sql,
            params,
            attempts=attempts,
            sleep_base_sec=sleep_base_sec,
            sleep_cap_sec=sleep_cap_sec,
            retry_count=retry_count,
            retry_sleep_sec=retry_sleep_sec,
        )
    except TypeError as exc:
        text = str(exc or "")
        if "unexpected keyword argument" not in text:
            raise
        effective_attempts = attempts if attempts is not None else retry_count
        if effective_attempts is None or not math.isfinite(float(effective_attempts)) or int(effective_attempts) < 1:
            effective_attempts = 3
        effective_sleep = sleep_base_sec
        if effective_sleep is None or not math.isfinite(float(effective_sleep)) or float(effective_sleep) < 0:
            effective_sleep = retry_sleep_sec
        if effective_sleep is None or not math.isfinite(float(effective_sleep)) or float(effective_sleep) < 0:
            effective_sleep = 0.35
        return _sqlite_execute_with_retry(
            target,
            sql,
            params,
            retry_count=int(effective_attempts),
            retry_sleep_sec=float(effective_sleep),
        )


