def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def utc_now_iso_ms() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds")


def _normalize_date_key(value: str) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if "T" in text:
        return text.split("T", 1)[0]
    if " " in text:
        return text.split(" ", 1)[0]
    return text


def to_jsonable_result(result: Dict) -> Dict:
    out = dict(result)
    out["members"] = [float(x) for x in result["members"]]
    model_members = result.get("model_members")
    if isinstance(model_members, dict):
        out["model_members"] = {
            k: [float(x) for x in v] for k, v in model_members.items()
        }
    model_members_raw = result.get("model_members_decimal_raw")
    if isinstance(model_members_raw, dict):
        out["model_members_decimal_raw"] = {
            k: [float(x) for x in v] for k, v in model_members_raw.items()
        }
    model_source_raw = result.get("model_source_raw_members")
    if isinstance(model_source_raw, dict):
        out["model_source_raw_members"] = {
            k: [float(x) for x in v] for k, v in model_source_raw.items()
        }
    model_source_dual_raw = result.get("model_source_dual_raw_members")
    if isinstance(model_source_dual_raw, dict):
        out["model_source_dual_raw_members"] = {
            k: [float(x) for x in v] for k, v in model_source_dual_raw.items()
        }
    out["rows"] = [dict(r) for r in result["rows"]]
    return out


def _to_finite_float(value: Any) -> Optional[float]:
    parsed = to_float(value)
    if parsed is None or not math.isfinite(parsed):
        return None
    return parsed


